@pytest.fixture(autouse=True)
def synthetic_launch_authority_adapter(monkeypatch: pytest.MonkeyPatch):
    """Keep synthetic launch-spec tests outside the production trust domain."""

    module = _preflight()
    production_lookup = module._lookup_validated_launch_authority

    def lookup(value: object) -> object:
        authority = getattr(value, "_validated_launch_authority", None)
        if type(authority) is module._ValidatedLaunchPreflightAuthority:
            module._launch_validate_authority_projection(value, authority)
            return authority
        return production_lookup(value)

    monkeypatch.setattr(module, "_lookup_validated_launch_authority", lookup)
    yield production_lookup


