def _canonical(value: object) -> bytes:
    return json.dumps(
        value,
        ensure_ascii=False,
        allow_nan=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")


def _identity(inode: int):
    return _command_plan().FilesystemObjectIdentity(
        device=7,
        inode=inode,
        file_type=1,
        reparse_tag=0,
        link_count=1,
    )


def _identity_record(identity: object) -> dict[str, int]:
    return {
        "device": identity.device,
        "file_type": identity.file_type,
        "inode": identity.inode,
        "link_count": identity.link_count,
        "reparse_tag": identity.reparse_tag,
    }


def _event_pair(
    raw_path: str,
    kind: str,
    *,
    event_id: str = "file-change-1",
    final_text: str = "synthetic preflight complete",
) -> tuple[list[dict[str, object]], bytes]:
    changes = [{"path": raw_path, "kind": kind}]
    events = [
        {"type": "thread.started", "thread_id": "synthetic-thread"},
        {"type": "turn.started"},
        {
            "type": "item.started",
            "item": {
                "id": event_id,
                "type": "file_change",
                "changes": changes,
                "status": "in_progress",
            },
        },
        {
            "type": "item.completed",
            "item": {
                "id": event_id,
                "type": "file_change",
                "changes": changes,
                "status": "completed",
            },
        },
        {
            "type": "item.completed",
            "item": {
                "id": "final-message",
                "type": "agent_message",
                "text": final_text,
            },
        },
        {"type": "turn.completed", "usage": {}},
    ]
    return events, b"".join(_canonical(event) + b"\n" for event in events)


def _file_change_events(
    events: list[dict[str, object]],
) -> tuple[dict[str, object], dict[str, object]]:
    selected = tuple(
        event
        for event in events
        if isinstance(event.get("item"), dict)
        and event["item"].get("type") == "file_change"
    )
    assert len(selected) == 2
    return selected


def _capture(path: Path, content: bytes, *, inode: int):
    return _preflight().CapturedLaunchInput(
        path=str(path),
        content=content,
        utf8_bytes=len(content),
        sha256=sha256(content).hexdigest(),
        identity=_identity(inode),
    )


_SHELL_PREFLIGHT_PAYLOAD = r"Test-Path -LiteralPath '.\case.json'"
_NORMALIZED_SHELL_ITEM_ID = "<shell-tool-item-id>"


def _shell_rendered_command(shell_path: str) -> str:
    quoted_payload = _SHELL_PREFLIGHT_PAYLOAD.replace("'", "''")
    return (
        f'"{shell_path}" -NoLogo -NoProfile -NonInteractive -Command '
        f"'{quoted_payload}'"
    )


def _ordered_json(value: object) -> bytes:
    return json.dumps(
        value,
        ensure_ascii=False,
        allow_nan=False,
        sort_keys=False,
        separators=(",", ":"),
    ).encode("utf-8")


def _shell_client_jsonl(
    *,
    shell_path: str,
    item_id: str,
    thread_id: str,
    aggregated_output: str = "True\n",
) -> bytes:
    command = _shell_rendered_command(shell_path)
    events = (
        {"type": "thread.started", "thread_id": thread_id},
        {"type": "turn.started"},
        {
            "type": "item.started",
            "item": {
                "id": item_id,
                "type": "command_execution",
                "command": command,
                "aggregated_output": "",
                "exit_code": None,
                "status": "in_progress",
            },
        },
        {
            "type": "item.completed",
            "item": {
                "id": item_id,
                "type": "command_execution",
                "command": command,
                "aggregated_output": aggregated_output,
                "exit_code": 0,
                "status": "completed",
            },
        },
        {
            "type": "item.completed",
            "item": {
                "id": f"message-{thread_id}",
                "type": "agent_message",
                "text": "campaign6-loopback-complete",
            },
        },
        {"type": "turn.completed", "usage": {}},
    )
    return b"".join(_ordered_json(event) + b"\n" for event in events)


def _expected_normalized_shell_events(content: bytes, item_id: str) -> bytes:
    selected: list[bytes] = []
    raw_id = _ordered_json(item_id)
    normalized_id = _ordered_json(_NORMALIZED_SHELL_ITEM_ID)
    for line in content.removesuffix(b"\n").split(b"\n"):
        event = json.loads(line)
        item = event.get("item")
        if isinstance(item, dict) and item.get("type") == "command_execution":
            id_member = b'"id":' + raw_id
            assert line.count(id_member) == 1
            selected.append(
                line.replace(
                    id_member,
                    b'"id":' + normalized_id,
                    1,
                )
                + b"\n"
            )
    assert len(selected) == 2
    return b"".join(selected)


def _write_validator_wheel(
    path: Path,
    members: tuple[tuple[str | zipfile.ZipInfo, bytes], ...],
) -> None:
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", UserWarning)
        with zipfile.ZipFile(
            path,
            mode="w",
            compression=zipfile.ZIP_DEFLATED,
        ) as archive:
            for name, content in members:
                archive.writestr(name, content)
    raw_backslash_names = tuple(
        name
        for name, _content in members
        if isinstance(name, str) and "\\" in name
    )
    if raw_backslash_names:
        payload = path.read_bytes()
        for raw_name in raw_backslash_names:
            normalized = raw_name.replace("\\", "/").encode("utf-8")
            rejected = raw_name.encode("utf-8")
            assert len(normalized) == len(rejected)
            assert payload.count(normalized) == 2
            payload = payload.replace(normalized, rejected)
        path.write_bytes(payload)


