def _corrupt_validator_member_data(wheel: Path, member: str) -> None:
    payload = bytearray(wheel.read_bytes())
    with zipfile.ZipFile(wheel, mode="r") as archive:
        info = archive.getinfo(member)
        filename_length, extra_length = struct.unpack_from(
            "<HH",
            payload,
            info.header_offset + 26,
        )
        data_offset = info.header_offset + 30 + filename_length + extra_length
        assert info.compress_size > 2
        corrupt_at = data_offset + info.compress_size // 2
    payload[corrupt_at] ^= 0x01
    wheel.write_bytes(payload)


def _patch_validator_declared_size(
    wheel: Path,
    member: str,
    *,
    delta: int,
) -> None:
    payload = bytearray(wheel.read_bytes())
    with zipfile.ZipFile(wheel, mode="r") as archive:
        info = archive.getinfo(member)
        local_offset = info.header_offset
        raw_name = member.encode("utf-8")
        replacement_size = info.file_size + delta
    assert replacement_size >= 0
    struct.pack_into("<L", payload, local_offset + 22, replacement_size)
    eocd_offset = payload.rfind(b"PK\x05\x06")
    assert eocd_offset >= 0
    central_offset = struct.unpack_from("<L", payload, eocd_offset + 16)[0]
    position = central_offset
    patched = False
    while position < eocd_offset:
        assert payload[position : position + 4] == b"PK\x01\x02"
        filename_length, extra_length, comment_length = struct.unpack_from(
            "<HHH",
            payload,
            position + 28,
        )
        name_start = position + 46
        name_end = name_start + filename_length
        if payload[name_start:name_end] == raw_name:
            struct.pack_into("<L", payload, position + 24, replacement_size)
            patched = True
            break
        position = name_end + extra_length + comment_length
    assert patched is True
    wheel.write_bytes(payload)


def _patch_validator_general_purpose_flag(
    wheel: Path,
    member: str,
    *,
    flag: int,
) -> None:
    payload = bytearray(wheel.read_bytes())
    with zipfile.ZipFile(wheel, mode="r") as archive:
        info = archive.getinfo(member)
        local_offset = info.header_offset
        raw_name = member.encode("utf-8")
    local_flags = struct.unpack_from("<H", payload, local_offset + 6)[0]
    struct.pack_into("<H", payload, local_offset + 6, local_flags | flag)
    eocd_offset = payload.rfind(b"PK\x05\x06")
    assert eocd_offset >= 0
    central_offset = struct.unpack_from("<L", payload, eocd_offset + 16)[0]
    position = central_offset
    patched = False
    while position < eocd_offset:
        assert payload[position : position + 4] == b"PK\x01\x02"
        filename_length, extra_length, comment_length = struct.unpack_from(
            "<HHH",
            payload,
            position + 28,
        )
        name_start = position + 46
        name_end = name_start + filename_length
        if payload[name_start:name_end] == raw_name:
            central_flags = struct.unpack_from("<H", payload, position + 8)[0]
            struct.pack_into("<H", payload, position + 8, central_flags | flag)
            patched = True
            break
        position = name_end + extra_length + comment_length
    assert patched is True
    wheel.write_bytes(payload)


