def _invalid_validator_members(
    mutation: str,
) -> tuple[tuple[str | zipfile.ZipInfo, bytes], ...]:
    members: list[tuple[str | zipfile.ZipInfo, bytes]] = list(
        VALIDATOR_WHEEL_MEMBERS
    )
    if mutation == "duplicate":
        members.append(("yaml/__init__.py", b"duplicate\n"))
    elif mutation == "absolute":
        members.append(("/yaml/absolute.py", b"invalid\n"))
    elif mutation == "drive-qualified":
        members.append(("C:/yaml/drive.py", b"invalid\n"))
    elif mutation == "dot-segment":
        members.append(("yaml/../escape.py", b"invalid\n"))
    elif mutation == "backslash":
        members.append(("yaml\\escape.py", b"invalid\n"))
    elif mutation == "outside-runtime":
        members.append(("outside/member.py", b"invalid\n"))
    elif mutation == "case-collision":
        members.extend(
            (
                ("yaml/Collision.py", b"one\n"),
                ("yaml/collision.py", b"two\n"),
            )
        )
    elif mutation == "component-case-collision":
        members.extend(
            (
                ("yaml/Foo/one.py", b"one\n"),
                ("yaml/foo/two.py", b"two\n"),
            )
        )
    elif mutation == "file-as-parent":
        members.extend(
            (
                ("yaml/package", b"plain file\n"),
                ("yaml/package/module.py", b"nested\n"),
            )
        )
    elif mutation == "alternate-parent-spelling":
        members.extend(
            (
                ("yaml/Package/one.py", b"one\n"),
                ("yaml/package/two.py", b"two\n"),
            )
        )
    elif mutation == "reserved-device":
        members.append(("yaml/CON.py", b"invalid\n"))
    elif mutation == "trailing-dot":
        members.append(("yaml/trailing./member.py", b"invalid\n"))
    elif mutation == "alternate-data-stream":
        members.append(("yaml/member.py:payload", b"invalid\n"))
    elif mutation == "control-character":
        members.append(("yaml/control-\x01.py", b"invalid\n"))
    elif mutation == "oversized-component":
        members.append((f"yaml/{'a' * 256}.py", b"invalid\n"))
    elif mutation == "explicit-directory":
        members.append(("yaml/explicit/", b""))
    elif mutation == "symlink":
        link = zipfile.ZipInfo("yaml/link.py")
        link.create_system = 3
        link.external_attr = (stat.S_IFLNK | 0o777) << 16
        members.append((link, b"target.py"))
    elif mutation == "non-file":
        special = zipfile.ZipInfo("yaml/device")
        special.create_system = 3
        special.external_attr = (stat.S_IFCHR | 0o600) << 16
        members.append((special, b"invalid\n"))
    else:
        raise AssertionError(f"unknown validator mutation: {mutation}")
    return tuple(members)


def _record_hash(payload: bytes) -> str:
    encoded = base64.urlsafe_b64encode(sha256(payload).digest()).decode("ascii")
    return f"sha256={encoded.rstrip('=')}"


def _guarded_record_rows(dist_info: Path) -> list[list[str]]:
    return list(
        csv.reader(
            io.StringIO(
                (dist_info / "RECORD").read_text(encoding="utf-8"),
                newline="",
            ),
            strict=True,
        )
    )


def _write_guarded_record_rows(
    dist_info: Path,
    rows: Sequence[Sequence[str]],
) -> None:
    stream = io.StringIO(newline="")
    writer = csv.writer(stream, lineterminator="\n")
    writer.writerows(rows)
    (dist_info / "RECORD").write_text(
        stream.getvalue(),
        encoding="utf-8",
        newline="",
    )


def _write_guarded_distribution(
    root: Path,
    *,
    name: str,
    version: str,
    package_files: dict[str, bytes],
    requires: tuple[str, ...] = (),
    inert_pth: bool = False,
) -> Path:
    normalized_dir = name.replace("-", "_")
    dist_info = root / f"{normalized_dir}-{version}.dist-info"
    dist_info.mkdir(parents=True)
    metadata = (
        "Metadata-Version: 2.4\n"
        f"Name: {name}\n"
        f"Version: {version}\n"
        + "".join(f"Requires-Dist: {requirement}\n" for requirement in requires)
    ).encode("utf-8")
    files = dict(package_files)
    files[f"{dist_info.name}/METADATA"] = metadata
    files[f"{dist_info.name}/WHEEL"] = b"Wheel-Version: 1.0\nRoot-Is-Purelib: false\n"
    if inert_pth:
        files["distutils-precedence.pth"] = b"import _distutils_hack\n"
    for relative, payload in files.items():
        path = root.joinpath(*relative.split("/"))
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(payload)
    record_relative = f"{dist_info.name}/RECORD"
    stream = io.StringIO(newline="")
    writer = csv.writer(stream, lineterminator="\n")
    for relative in sorted(files, key=lambda value: (value.casefold(), value)):
        payload = files[relative]
        writer.writerow((relative, _record_hash(payload), str(len(payload))))
    writer.writerow((record_relative, "", ""))
    (dist_info / "RECORD").write_text(
        stream.getvalue(),
        encoding="utf-8",
        newline="",
    )
    return dist_info


def _actual_capture(path: Path):
    payload, identity = _preflight()._validator_capture_plain_file(
        path,
        max_bytes=64 * 1024 * 1024,
    )
    return _preflight().CapturedLaunchInput(
        path=str(path),
        content=payload,
        utf8_bytes=len(payload),
        sha256=sha256(payload).hexdigest(),
        identity=identity,
    )


