def test_guarded_python_runtime_never_imports_selected_package_code(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    paths = _guarded_runtime_fixture(tmp_path, monkeypatch)
    original_import = builtins.__import__
    forbidden_names = {
        "_yaml",
        "attrs",
        "build",
        "jsonschema",
        "pip",
        "pytest",
        "rpds",
        "setuptools",
        "yaml",
    }

    def guarded_import(name: str, *args: object, **kwargs: object) -> object:
        if name.split(".", 1)[0] in forbidden_names:
            raise AssertionError(f"package code import attempted: {name}")
        return original_import(name, *args, **kwargs)

    monkeypatch.setattr(builtins, "__import__", guarded_import)

    runtime = _freeze_guarded(paths)

    assert _preflight().validate_frozen_guarded_python_runtime(runtime) == runtime


@pytest.mark.parametrize(
    "mutation",
    (
        "missing-core",
        "lying-record",
        "hardlink-core",
        "duplicate-distribution",
        "overlapping-roots",
        "frozen-extra",
        "pth-mutation",
        "bootstrap-mutation",
        "project-mutation",
    ),
)
def test_guarded_python_runtime_rejects_missing_extra_mutated_and_linked_members(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    mutation: str,
) -> None:
    paths = _guarded_runtime_fixture(tmp_path, monkeypatch)
    runtime = None
    if mutation == "missing-core":
        Path(paths["python_home"]).joinpath("python3.dll").unlink()
    elif mutation == "lying-record":
        Path(paths["user_site"]).joinpath("yaml", "__init__.py").write_bytes(
            b"mutated without RECORD update\n"
        )
    elif mutation == "hardlink-core":
        os.link(
            Path(paths["python_path"]),
            Path(paths["python_home"]) / "python-hardlink.exe",
        )
    elif mutation == "duplicate-distribution":
        source = paths["dist_infos"]["pyyaml"]
        shutil.copytree(source, Path(paths["base_site"]) / source.name)
    elif mutation == "overlapping-roots":
        roots = (paths["user_site"], paths["user_site"])
        paths["distribution_roots"] = roots
        paths["host_facts"]["distribution_roots"] = roots
    elif mutation in (
        "frozen-extra",
        "pth-mutation",
        "bootstrap-mutation",
        "project-mutation",
    ):
        runtime = _freeze_guarded(paths)
        if mutation == "frozen-extra":
            Path(runtime.root).joinpath("unexpected.txt").write_bytes(b"extra\n")
        elif mutation == "pth-mutation":
            Path(runtime.root).joinpath("python314._pth").write_bytes(
                b".\nLib\nimport site\n"
            )
        elif mutation == "bootstrap-mutation":
            Path(runtime.bootstrap.path).write_bytes(b"mutated bootstrap\n")
        else:
            Path(runtime.project_metadata.path).write_bytes(b"mutated project\n")
    else:
        raise AssertionError(mutation)

    def forbidden(*_args: object, **_kwargs: object) -> object:
        raise AssertionError("guarded runtime attempted a process or network action")

    monkeypatch.setattr(subprocess, "Popen", forbidden)
    monkeypatch.setattr(subprocess, "run", forbidden)
    monkeypatch.setattr(socket, "socket", forbidden)
    with pytest.raises(RuntimeError):
        if runtime is None:
            _freeze_guarded(paths)
        else:
            _preflight().validate_frozen_guarded_python_runtime(runtime)
    assert Path(paths["runtime_root"]).exists() is (runtime is not None)


