@pytest.mark.parametrize(
    "mutation",
    ("distribution-version", "entry-ownership", "omitted-inert"),
)
def test_guarded_python_runtime_rejects_recanonicalized_distribution_mutation(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    mutation: str,
) -> None:
    paths = _guarded_runtime_fixture(tmp_path, monkeypatch)
    preflight = _preflight()
    runtime = _freeze_guarded(paths)
    distributions = list(runtime.distributions)

    def rebuild(distribution: object, **overrides: object):
        values = {
            field.name: getattr(distribution, field.name)
            for field in fields(preflight.FrozenDistribution)
            if field.name != "manifest_sha256"
        }
        values.update(overrides)
        return preflight._guarded_make_distribution(**values)

    if mutation == "distribution-version":
        index = next(
            index
            for index, item in enumerate(distributions)
            if item.normalized_name == "pyyaml"
        )
        distributions[index] = rebuild(
            distributions[index],
            distribution_version="0.0.0",
        )
    elif mutation == "entry-ownership":
        source_index = next(
            index
            for index, item in enumerate(distributions)
            if item.normalized_name == "pyyaml"
        )
        target_index = next(
            index
            for index, item in enumerate(distributions)
            if item.normalized_name == "attrs"
        )
        moved = next(
            entry
            for entry in distributions[source_index].entries
            if entry.relative_path == "_yaml/_yaml.pyd"
        )
        distributions[source_index] = rebuild(
            distributions[source_index],
            entries=tuple(
                entry
                for entry in distributions[source_index].entries
                if entry != moved
            ),
        )
        distributions[target_index] = rebuild(
            distributions[target_index],
            entries=tuple(
                sorted(
                    (*distributions[target_index].entries, moved),
                    key=lambda entry: (
                        entry.relative_path.casefold(),
                        entry.relative_path,
                    ),
                )
            ),
        )
    elif mutation == "omitted-inert":
        index = next(
            index
            for index, item in enumerate(distributions)
            if item.normalized_name == "setuptools"
        )
        distributions[index] = rebuild(
            distributions[index],
            omitted_inert_paths=("rogue.pth",),
        )
    else:
        raise AssertionError(mutation)

    candidate = _recanonicalize_guarded_runtime(
        runtime,
        distributions=tuple(distributions),
    )

    with pytest.raises(RuntimeError):
        preflight.validate_frozen_guarded_python_runtime(candidate)


