def _bootstrap_literal(name: str) -> object:
    tree = ast.parse(BOOTSTRAP_PATH.read_text(encoding="utf-8"))
    assignment = next(
        node
        for node in tree.body
        if isinstance(node, ast.Assign)
        and any(isinstance(target, ast.Name) and target.id == name for target in node.targets)
    )
    return ast.literal_eval(assignment.value)


def test_guard_bootstrap_rejects_site_pth_cwd_pythonpath_and_unknown_origin() -> None:
    assert BOOTSTRAP_PATH.is_file()
    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    imports = {
        alias.name.split(".", 1)[0]
        for node in ast.walk(tree)
        if isinstance(node, ast.Import)
        for alias in node.names
    } | {
        node.module.split(".", 1)[0]
        for node in ast.walk(tree)
        if isinstance(node, ast.ImportFrom) and node.module is not None
    }
    calls = {
        node.func.id
        for node in ast.walk(tree)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
    }

    assert imports <= {"hashlib", "json", "os", "sys"}
    assert not imports & {"importlib", "pkgutil", "runpy", "site"}
    assert not calls & {"compile", "eval", "exec", "open"}
    assert _bootstrap_literal("FORBIDDEN_ENVIRONMENT_NAMES") == (
        "PYTHONHOME",
        "PYTHONPATH",
        "PYTHONUSERBASE",
    )
    assert "validate_guarded_import_roots" in source
    assert "unknown import origin" in source
    assert "import site" not in source
    assert ".pth" in source


