def _load_broker_native_core_draft() -> dict[str, object]:
    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    namespace: dict[str, object] = {
        "__file__": str(BOOTSTRAP_PATH),
        "__name__": "_complete_suite_release_python_bootstrap_private_test",
    }
    exec(compile(source, str(BOOTSTRAP_PATH), "exec"), namespace)
    return namespace


def _broker_native_core_ms_crt_reference_render_argument(argument: str) -> str:
    needs_quotes = not argument or any(
        character in " \t\"" for character in argument
    )
    if not needs_quotes:
        return argument

    rendered = ['"']
    pending_backslashes = 0
    for character in argument:
        if character == "\\":
            pending_backslashes += 1
            continue
        if character == '"':
            rendered.append("\\" * (pending_backslashes * 2 + 1))
            rendered.append('"')
        else:
            rendered.append("\\" * pending_backslashes)
            rendered.append(character)
        pending_backslashes = 0
    rendered.append("\\" * (pending_backslashes * 2))
    rendered.append('"')
    return "".join(rendered)


def _broker_native_core_ms_crt_reference_render(
    executable: str,
    arguments: tuple[str, ...],
) -> tuple[str, int, str]:
    command_line = " ".join(
        _broker_native_core_ms_crt_reference_render_argument(item)
        for item in (executable, *arguments)
    )
    encoded = (command_line + "\x00").encode("utf-16-le", errors="strict")
    return command_line, len(encoded) // 2, sha256(encoded).hexdigest()


def test_broker_native_core_native_vector_matches_independent_ms_crt_oracle() -> None:
    # The reference renderer is cross-checked by the independent literal-vector
    # fixtures below; this required selector executes the complete comparison.
    namespace = _load_broker_native_core_draft()
    serializer = namespace["_c6_broker_native_core_draft_native_vector"]
    executable = "C:\\Program Files\\Kokoro\\runner.exe"
    arguments = (
        "",
        "plain",
        "with space",
        "with\ttab",
        'literal"quote',
        'slash\\"before-quote',
        "quoted trailing\\",
        "雪😀",
    )
    command_line, utf16_units, digest = (
        _broker_native_core_ms_crt_reference_render(
            executable,
            arguments,
        )
    )

    result = serializer(executable, arguments)

    assert result.contract == "complete-suite-windows-native-vector-v1"
    assert result.command_line == command_line
    assert result.utf16_units == utf16_units
    assert result.utf16le_sha256 == digest
    assert command_line not in repr(result)
    assert command_line not in str(result)
    with pytest.raises(AttributeError):
        result.command_line = "mutated"


@pytest.mark.parametrize(
    ("arguments", "expected_command_line"),
    (
        (("",), 'C:\\runner.exe ""'),
        (("space value",), 'C:\\runner.exe "space value"'),
        (("tab\tvalue",), 'C:\\runner.exe "tab\tvalue"'),
        (('quote"value',), 'C:\\runner.exe "quote\\"value"'),
        (('one\\"quote',), r'C:\runner.exe "one\\\"quote"'),
        (('many\\\\"quote',), r'C:\runner.exe "many\\\\\"quote"'),
        (("tail space\\",), r'C:\runner.exe "tail space\\"'),
        (("tail space\\\\",), r'C:\runner.exe "tail space\\\\"'),
        (("雪😀",), r"C:\runner.exe 雪😀"),
    ),
)
def test_broker_native_core_native_vector_matches_literal_expected_command_lines(
    arguments: tuple[str, ...],
    expected_command_line: str,
) -> None:
    serializer = _load_broker_native_core_draft()[
        "_c6_broker_native_core_draft_native_vector"
    ]
    expected_bytes = (expected_command_line + "\x00").encode(
        "utf-16-le",
        errors="strict",
    )

    result = serializer("C:\\runner.exe", arguments)

    assert result.command_line == expected_command_line
    assert result.utf16_units == len(expected_bytes) // 2
    assert result.utf16le_sha256 == sha256(expected_bytes).hexdigest()


def test_broker_native_core_native_vector_quote_expansion_boundary_is_utf16_exact() -> None:
    serializer = _load_broker_native_core_draft()[
        "_c6_broker_native_core_draft_native_vector"
    ]
    expected_prefix = 'C:\\x.exe " '
    expected_suffix = '\\\\"'
    fixed_units = len(
        (expected_prefix + expected_suffix + "\x00").encode("utf-16-le")
    ) // 2
    body_units = 30_000 - fixed_units
    exact_argument = " " + "a" * body_units + "\\"
    over_argument = " " + "a" * (body_units + 1) + "\\"
    expected_command_line = expected_prefix + "a" * body_units + expected_suffix
    expected_bytes = (expected_command_line + "\x00").encode("utf-16-le")
    assert len(expected_bytes) // 2 == 30_000
    assert len((expected_prefix + "a" * (body_units + 1) + expected_suffix + "\x00").encode("utf-16-le")) // 2 == 30_001

    result = serializer("C:\\x.exe", (exact_argument,))

    assert result.command_line == expected_command_line
    assert result.utf16_units == 30_000
    assert result.utf16le_sha256 == sha256(expected_bytes).hexdigest()
    with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
        serializer("C:\\x.exe", (over_argument,))


def test_broker_native_core_native_vector_accepts_30000_rejects_30001() -> None:
    serializer = _load_broker_native_core_draft()[
        "_c6_broker_native_core_draft_native_vector"
    ]
    executable = "C:\\x.exe"
    fixed_units = len((executable + " " + "\x00").encode("utf-16-le")) // 2
    exact_argument = "a" * (30_000 - fixed_units)
    over_argument = exact_argument + "a"
    assert _broker_native_core_ms_crt_reference_render(
        executable,
        (exact_argument,),
    )[1] == 30_000
    assert _broker_native_core_ms_crt_reference_render(
        executable,
        (over_argument,),
    )[1] == 30_001

    assert serializer(executable, (exact_argument,)).utf16_units == 30_000
    with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
        serializer(executable, (over_argument,))


def test_broker_native_core_rejects_native_vector_budget_bypass() -> None:
    serializer = _load_broker_native_core_draft()[
        "_c6_broker_native_core_draft_native_vector"
    ]
    executable = "C:\\x.exe"
    exact_argument = "😀" * 14_995
    over_argument = exact_argument + "a"
    assert len(executable + " " + over_argument + "\x00") < 30_000
    assert _broker_native_core_ms_crt_reference_render(
        executable,
        (exact_argument,),
    )[1] == 30_000
    assert _broker_native_core_ms_crt_reference_render(
        executable,
        (over_argument,),
    )[1] == 30_001

    assert serializer(executable, (exact_argument,)).utf16_units == 30_000
    with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
        serializer(executable, (over_argument,))


class _BrokerNativeCoreStringSubclass(str):
    pass


class _BrokerNativeCoreTupleSubclass(tuple):
    pass


@pytest.mark.parametrize(
    ("executable", "arguments"),
    (
        ("", ()),
        (123, ()),
        (_BrokerNativeCoreStringSubclass("C:\\runner.exe"), ()),
        ("relative.exe", ()),
        ("C:\\Tools\\..\\runner.exe", ()),
        ("C:\\runner.exe\x00", ()),
        ("C:\\runner\ud800.exe", ()),
        ("C:\\runner\udfff.exe", ()),
        ("C:\\runner.exe", ["not-a-tuple"]),
        ("C:\\runner.exe", _BrokerNativeCoreTupleSubclass(("safe",))),
        ("C:\\runner.exe", (123,)),
        (
            "C:\\runner.exe",
            (_BrokerNativeCoreStringSubclass("safe"),),
        ),
        ("C:\\runner.exe", ("nul\x00",)),
        ("C:\\runner.exe", ("high\ud800",)),
        ("C:\\runner.exe", ("low\udfff",)),
    ),
)
def test_broker_native_core_rejects_invalid_utf16_before_any_preparation(
    executable: object,
    arguments: object,
) -> None:
    namespace = _load_broker_native_core_draft()

    class _ForbiddenDigest:
        @staticmethod
        def sha256(_value: object) -> object:
            raise AssertionError("invalid UTF-16 reached digest preparation")

    namespace["hashlib"] = _ForbiddenDigest
    serializer = namespace["_c6_broker_native_core_draft_native_vector"]
    with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
        serializer(executable, arguments)


def test_broker_native_core_environment_block_is_ordinal_double_nul_and_descriptor_bound() -> None:
    serializer = _load_broker_native_core_draft()[
        "_c6_broker_native_core_draft_environment_block"
    ]
    supplied = (("zeta", "last"), ("Alpha", "雪😀"), ("beta", "secret-value"))
    result = serializer(supplied)
    expected_pairs = (("Alpha", "雪😀"), ("beta", "secret-value"), ("zeta", "last"))
    expected_block = "Alpha=雪😀\x00beta=secret-value\x00zeta=last\x00\x00"
    expected_bytes = expected_block.encode("utf-16-le", errors="strict")

    assert result.ordered_pairs == expected_pairs
    assert result.block_text == expected_block
    assert result.utf16_units == len(expected_bytes) // 2
    assert result.utf16le_byte_count == len(expected_bytes)
    assert result.utf16le_sha256 == sha256(expected_bytes).hexdigest()
    assert "secret-value" not in repr(result)
    assert expected_block not in repr(result)
    assert "secret-value" not in str(result)
    assert expected_block not in str(result)
    with pytest.raises(AttributeError):
        result.block_text = "mutated"

    empty = serializer(())
    assert empty.ordered_pairs == ()
    assert empty.block_text == "\x00\x00"
    assert empty.utf16le_byte_count == 4
    assert empty.utf16le_sha256 == sha256(b"\x00\x00\x00\x00").hexdigest()

    mutations = (
        [],
        _BrokerNativeCoreTupleSubclass((("A", "1"),)),
        (["A", "1"],),
        (_BrokerNativeCoreTupleSubclass(("A", "1")),),
        (("A",),),
        ((1, "value"),),
        ((_BrokerNativeCoreStringSubclass("A"), "value"),),
        (("A", 1),),
        (("A", _BrokerNativeCoreStringSubclass("value")),),
        (("", "value"),),
        (("A=B", "value"),),
        (("A\x00", "value"),),
        (("A\r", "value"),),
        (("A\n", "value"),),
        (("A\ud800", "value"),),
        (("A", "value\x00"),),
        (("A", "value\r"),),
        (("A", "value\n"),),
        (("A", "value\udfff"),),
        (("Name", "one"), ("name", "two")),
    )
    for mutation in mutations:
        with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
            serializer(mutation)


def test_broker_native_core_environment_names_use_utf16_ordinal_and_simple_case_key() -> None:
    serializer = _load_broker_native_core_draft()[
        "_c6_broker_native_core_draft_environment_block"
    ]
    supplied = (
        ("\ue000", "BMP private-use 雪"),
        ("ß", "eszett 😀"),
        ("TAB\tNAME", "tab"),
        ("\U00010000", "supplementary"),
        ("ss", "double-s"),
        ("SPACE NAME", "space"),
        ("CONTROL\x1fNAME", "control"),
    )
    expected_pairs = (
        ("CONTROL\x1fNAME", "control"),
        ("SPACE NAME", "space"),
        ("TAB\tNAME", "tab"),
        ("ss", "double-s"),
        ("ß", "eszett 😀"),
        ("\U00010000", "supplementary"),
        ("\ue000", "BMP private-use 雪"),
    )

    result = serializer(supplied)

    assert result.ordered_pairs == expected_pairs
    expected_block = "".join(
        f"{name}={value}\x00" for name, value in expected_pairs
    ) + "\x00"
    expected_bytes = expected_block.encode("utf-16-le", errors="strict")
    assert result.block_text == expected_block
    assert result.utf16_units == len(expected_bytes) // 2
    assert result.utf16le_sha256 == sha256(expected_bytes).hexdigest()
    with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
        serializer((("σ", "lower"), ("Σ", "upper")))
    with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
        serializer((("ı", "dotless-lower"), ("I", "upper")))


def test_broker_native_core_accepts_only_registered_context_subject_attribute_sets() -> None:
    projector = _load_broker_native_core_draft()[
        "_c6_broker_native_core_draft_project_policy"
    ]

    class _StringSubclass(str):
        pass

    leaf_attributes = (
        "HANDLE_LIST",
        "JOB_LIST",
        "CHILD_PROCESS_POLICY=PROCESS_CREATION_CHILD_PROCESS_RESTRICTED",
    )
    client_attributes = ("HANDLE_LIST", "JOB_LIST")
    rows = (
        (
            "guarded-target-or-native-leaf",
            "guarded-python-target",
            leaf_attributes,
            "none",
        ),
        (
            "guarded-target-or-native-leaf",
            "native-leaf",
            leaf_attributes,
            "none",
        ),
        (
            "codex-client-root",
            "loopback-codex-client-root",
            client_attributes,
            "unchanged-client-declared-descendants-only",
        ),
        (
            "codex-client-root",
            "approved-codex-client-root",
            client_attributes,
            "unchanged-client-declared-descendants-only",
        ),
    )
    for constructor_class, subject_kind, attributes, direct_child_authority in rows:
        result = projector(constructor_class, subject_kind, attributes)
        assert result.implementation_id == "broker-native-core-v1"
        assert result.constructor_class == constructor_class
        assert result.subject_kind == subject_kind
        assert result.attributes == attributes
        assert result.direct_child_authority == direct_child_authority
        assert "broker-native-core-v1" in repr(result)
        with pytest.raises(AttributeError):
            result.subject_kind = "mutated"

    rejected = (
        ("guarded-target-or-native-leaf", "unknown", leaf_attributes),
        (
            _StringSubclass("guarded-target-or-native-leaf"),
            "native-leaf",
            leaf_attributes,
        ),
        (
            "guarded-target-or-native-leaf",
            _StringSubclass("native-leaf"),
            leaf_attributes,
        ),
        ("codex-client-root", "native-leaf", client_attributes),
        ("root-broker", "guarded-python-target", leaf_attributes),
        ("standalone-native-leaf", "native-leaf", leaf_attributes),
        ("host-native-core-v1", "native-leaf", leaf_attributes),
        ("guarded-target-or-native-leaf", "native-leaf", list(leaf_attributes)),
        (
            "guarded-target-or-native-leaf",
            "native-leaf",
            _BrokerNativeCoreTupleSubclass(leaf_attributes),
        ),
        ("guarded-target-or-native-leaf", "native-leaf", leaf_attributes[::-1]),
        ("guarded-target-or-native-leaf", "native-leaf", leaf_attributes[:-1]),
        ("guarded-target-or-native-leaf", "native-leaf", (*leaf_attributes, "EXTRA")),
        (
            "guarded-target-or-native-leaf",
            "native-leaf",
            (_StringSubclass("HANDLE_LIST"), *leaf_attributes[1:]),
        ),
        ("codex-client-root", "approved-codex-client-root", client_attributes[::-1]),
    )
    for constructor_class, subject_kind, attributes in rejected:
        with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
            projector(constructor_class, subject_kind, attributes)


