def test_broker_native_core_constructor_attribute_registry_matches_literal_payload() -> None:
    namespace = _load_broker_native_core_draft()
    registry = namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_ATTRIBUTE_REGISTRY"
    ]
    field_names = _BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_ATTRIBUTE_FIELD_NAMES
    rows = _BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_ATTRIBUTE_ROWS
    canonical_bytes = (
        _BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_ATTRIBUTE_CANONICAL_BYTES
    )
    expected_sha256 = _BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_ATTRIBUTE_SHA256
    independent_payload = tuple(
        {field_name: row[index] for index, field_name in enumerate(field_names)}
        for row in rows
    )
    independent_bytes = json.dumps(
        independent_payload,
        ensure_ascii=True,
        allow_nan=False,
        separators=(",", ":"),
    ).encode("ascii", errors="strict") + b"\n"

    assert tuple(registry) == (
        field_names,
        rows,
        canonical_bytes,
        expected_sha256,
    )
    assert registry.field_names == field_names
    assert registry.rows == rows
    assert registry.canonical_bytes == canonical_bytes == independent_bytes
    assert registry.constructor_attribute_set_sha256 == expected_sha256
    assert len(canonical_bytes) == 994
    assert canonical_bytes.decode("ascii", errors="strict").encode("ascii") == canonical_bytes
    assert canonical_bytes.endswith(b"\n")
    assert canonical_bytes.count(b"\n") == 1
    assert b"\r" not in canonical_bytes
    assert b"\x00" not in canonical_bytes
    assert not canonical_bytes.startswith(b"\xef\xbb\xbf")
    assert expected_sha256.encode("ascii") not in canonical_bytes
    assert sha256(canonical_bytes).hexdigest() == expected_sha256
    assert len(expected_sha256) == 64
    assert all(character in "0123456789abcdef" for character in expected_sha256)
    one_byte_mutation = b"X" + canonical_bytes[1:]
    assert sha256(one_byte_mutation).hexdigest() != expected_sha256
    assert len(field_names) == 5
    assert len(rows) == 3
    assert tuple(len(row[1]) for row in rows) == (1, 2, 2)
    assert tuple(len(row[2]) for row in rows) == (1, 2, 1)
    assert tuple(len(row[3]) for row in rows) == (2, 3, 2)


def test_broker_native_core_constructor_attribute_registry_is_exactly_immutable_and_repr_safe() -> None:
    namespace = _load_broker_native_core_draft()
