def test_broker_native_core_job_topology_registry_matches_literal_payload() -> None:
    namespace = _load_broker_native_core_draft()
    registry = namespace["_C6_BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_REGISTRY"]
    field_names = _BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_FIELD_NAMES
    rows = _BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_ROWS
    canonical_bytes = _BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_CANONICAL_BYTES
    expected_sha256 = _BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_SHA256
    independent_payload = tuple(
        {field_name: row[index] for index, field_name in enumerate(field_names)}
        for row in rows
    )
    independent_bytes = json.dumps(
        independent_payload,
        ensure_ascii=True,
        allow_nan=False,
        separators=(",", ":"),
    ).encode("ascii", errors="strict") + b"\n"

    assert tuple(registry) == (
        field_names,
        rows,
        canonical_bytes,
        expected_sha256,
    )
    assert registry.field_names == field_names
    assert registry.rows == rows
    assert registry.canonical_bytes == canonical_bytes == independent_bytes
    assert registry.job_topology_sha256 == expected_sha256
    assert len(canonical_bytes) == 1780
    assert canonical_bytes.decode("ascii", errors="strict").encode("ascii") == canonical_bytes
    assert canonical_bytes.endswith(b"\n")
    assert canonical_bytes.count(b"\n") == 1
    assert b"\r" not in canonical_bytes
    assert b"\x00" not in canonical_bytes
    assert not canonical_bytes.startswith(b"\xef\xbb\xbf")
    assert expected_sha256.encode("ascii") not in canonical_bytes
    assert sha256(canonical_bytes).hexdigest() == expected_sha256
    assert len(expected_sha256) == 64
    assert all(character in "0123456789abcdef" for character in expected_sha256)
    assert sha256(b"X" + canonical_bytes[1:]).hexdigest() != expected_sha256
    assert len(field_names) == 7
    assert len(rows) == 7


def test_broker_native_core_job_topology_registry_is_exactly_immutable_and_repr_safe() -> None:
    namespace = _load_broker_native_core_draft()
    registry_type = namespace["_C6BrokerNativeCoreDraftJobTopologyRegistry"]
    registry = namespace["_C6_BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_REGISTRY"]

    def assert_exact_tuple_tree(value: object) -> None:
        assert type(value) in {str, tuple}
        if type(value) is tuple:
            for item in value:
                assert_exact_tuple_tree(item)

    assert type(registry) is registry_type
    assert_exact_tuple_tree(registry.field_names)
    assert_exact_tuple_tree(registry.rows)
    assert type(registry.canonical_bytes) is bytes
    assert type(registry.job_topology_sha256) is str
    summary = repr(registry)
    assert str(registry) == summary
    assert "field_count=7" in summary
    assert "row_count=7" in summary
    assert _BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_SHA256 in summary
    assert "root-broker" not in summary
    assert "codex-client-descendant" not in summary
    assert repr(registry.rows) not in summary
    assert repr(registry.canonical_bytes) not in summary
    assert len(summary) < 200
    with pytest.raises(AttributeError):
        registry.rows = ()
    with pytest.raises(TypeError):
        registry.rows[0][1] = ()


def test_broker_native_core_job_topology_registry_cross_binds_policy_and_constructor_rows() -> None:
    namespace = _load_broker_native_core_draft()
    topology_registry = namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_REGISTRY"
    ]
    constructor_registry = namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_ATTRIBUTE_REGISTRY"
    ]
    topology_by_id = {row[0]: row for row in topology_registry.rows}
    constructor_by_class = {row[0]: row for row in constructor_registry.rows}
    broker_topology_subject_rows = (
        ("initial-guarded-target", "guarded-python-target"),
        ("nested-guarded-target", "guarded-python-target"),
        ("broker-native-leaf", "native-leaf"),
        ("codex-client-root", "loopback-codex-client-root"),
        ("codex-client-root", "approved-codex-client-root"),
    )
    host_topology_ids = ("root-broker", "standalone-native-leaf")
    deduplicated_broker_subjects = tuple(
        dict.fromkeys(subject for _topology_id, subject in broker_topology_subject_rows)
    )
    policy_subjects = tuple(
        subject_kind
        for _constructor_class, subject_kind, _attributes, _authority in namespace[
            "_C6_BROKER_NATIVE_CORE_DRAFT_POLICY_ROWS"
        ]
    )

    assert deduplicated_broker_subjects == policy_subjects
    assert all(
        topology_id in topology_by_id
        for topology_id, _subject in broker_topology_subject_rows
    )
    assert not set(host_topology_ids) & {
        topology_id for topology_id, _subject in broker_topology_subject_rows
    }

    constructor_created_rows = (
        ("root-broker", "root-broker"),
        ("standalone-native-leaf", "guarded-target-or-native-leaf"),
        ("initial-guarded-target", "guarded-target-or-native-leaf"),
        ("nested-guarded-target", "guarded-target-or-native-leaf"),
        ("broker-native-leaf", "guarded-target-or-native-leaf"),
        ("codex-client-root", "codex-client-root"),
    )
    assert tuple(topology_by_id) == tuple(
        row[0] for row in _BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_ROWS
    )
    assert tuple(topology_id for topology_id, _class in constructor_created_rows) == tuple(
        topology_by_id
    )[:-1]
    for topology_id, constructor_class in constructor_created_rows:
        topology_row = topology_by_id[topology_id]
        constructor_row = constructor_by_class[constructor_class]
        assert topology_row[2]
        assert "JOB_LIST" in constructor_row[3]
        assert topology_row[1] + topology_row[2] == topology_row[3]
        assert topology_row[4] == topology_row[2][-1]

    assert tuple(
        row[0] for row in topology_registry.rows if not row[2]
    ) == ("codex-client-descendant",)
    assert all(row[1] + row[2] == row[3] for row in topology_registry.rows)
    assert tuple(row[5] for row in topology_registry.rows) == (
        "host:P0:J0",
        "host:P0:L0",
        "root:P1:J1",
        "root:P1:J1",
        "root:P1:J1",
        "root:P1:J1",
        "root:P1:J1",
    )
    assert tuple(row[6] for row in topology_registry.rows[:-1]) == tuple(
        f"{'host' if index < 2 else 'root'}:{row[4]}"
        for index, row in enumerate(topology_registry.rows[:-1])
    )
    assert topology_registry.rows[-1] == (
        "codex-client-descendant",
        ("parent-effective-chain",),
        (),
        ("parent-effective-chain",),
        "inherited-Cn",
        "root:P1:J1",
        "root:Cn",
    )


def test_broker_native_core_job_topology_registry_constructor_surface_is_closed() -> None:
    namespace = _load_broker_native_core_draft()
    registry_type = namespace["_C6BrokerNativeCoreDraftJobTopologyRegistry"]
    field_names = _BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_FIELD_NAMES
    rows = _BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_ROWS

    assert tuple(inspect.signature(registry_type.__new__).parameters) == (
        "cls",
        "field_names",
        "rows",
    )
    assert tuple(inspect.signature(registry_type).parameters) == (
        "field_names",
        "rows",
    )
    reconstructed = registry_type(field_names, rows)
    assert tuple(reconstructed) == tuple(
        namespace["_C6_BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_REGISTRY"]
    )
    for arguments in ((), (field_names,), (field_names, rows, b"caller-bytes")):
        with pytest.raises(TypeError):
            registry_type(*arguments)
    for keyword in (
        "canonical_bytes",
        "job_topology_sha256",
        "topology_id",
        "job_id",
        "constructor",
        "policy",
        "authority",
        "factory",
        "selector",
    ):
        with pytest.raises(TypeError):
            registry_type(field_names, rows, **{keyword: object()})

    class _RegistrySubclass(registry_type):
        pass

    with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
        _RegistrySubclass(field_names, rows)

    callable_topology_surface = {
        name
        for name, value in namespace.items()
        if name.startswith("_c6_broker_native_core_draft_")
        and callable(value)
        and any(
            token in name
            for token in (
                "job_constructor",
                "job_factory",
                "job_topology",
                "topology_registry",
            )
        )
    }
    assert callable_topology_surface == set()
    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    registry_name = "_C6_BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_REGISTRY"
    assert not any(
        isinstance(node, ast.Name)
        and isinstance(node.ctx, ast.Load)
        and node.id == registry_name
        for node in ast.walk(tree)
    )
    assert not BOOTSTRAP_PATH.with_name("complete_suite_control_plane.ps1").exists()
    for marker in (
        "C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN",
        "C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END",
    ):
        assert marker not in source


@pytest.mark.parametrize(
    "mutation",
    (
        "field-missing",
        "field-extra",
        "field-duplicate",
        "field-reordered",
        "row-missing",
        "row-extra",
        "row-duplicate",
        "row-reordered",
        "row-field-missing",
        "row-field-extra",
        "nested-missing",
        "nested-extra",
        "nested-duplicate",
        "nested-reordered",
        "topology-token-changed",
        "implicit-token-changed",
        "explicit-token-changed",
        "effective-token-changed",
        "immediate-scope-changed",
        "completion-owner-changed",
        "termination-owner-changed",
        "immediate-scope-null",
        "completion-owner-null",
        "termination-owner-null",
        "scalar-wrong-type",
        "nested-wrong-type",
        "nested-token-wrong-type",
    ),
)
def test_broker_native_core_job_topology_registry_rejects_every_closed_schema_mutation(
    mutation: str,
) -> None:
    namespace = _load_broker_native_core_draft()
    registry_type = namespace["_C6BrokerNativeCoreDraftJobTopologyRegistry"]
    field_names = _BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_FIELD_NAMES
    rows = _BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_ROWS

    if mutation == "field-missing":
        field_names = field_names[:-1]
    elif mutation == "field-extra":
        field_names = (*field_names, "extra")
    elif mutation == "field-duplicate":
        field_names = (field_names[0], field_names[0], *field_names[2:])
    elif mutation == "field-reordered":
        field_names = field_names[1:] + field_names[:1]
    elif mutation == "row-missing":
        rows = rows[:-1]
    elif mutation == "row-extra":
        rows = (*rows, rows[0])
    elif mutation == "row-duplicate":
        rows = (rows[0], rows[0], *rows[2:])
    elif mutation == "row-reordered":
        rows = rows[1:] + rows[:1]
    elif mutation == "row-field-missing":
        rows = (rows[0][:-1], *rows[1:])
    elif mutation == "row-field-extra":
        rows = ((*rows[0], "extra"), *rows[1:])
    elif mutation == "nested-missing":
        rows = ((*rows[0][:2], (), *rows[0][3:]), *rows[1:])
    elif mutation == "nested-extra":
        rows = ((*rows[0][:2], ("J0", "JX"), *rows[0][3:]), *rows[1:])
    elif mutation == "nested-duplicate":
        rows = (
            rows[0],
            rows[1],
            (*rows[2][:2], ("J1", "J1", "T0"), *rows[2][3:]),
            *rows[3:],
        )
    elif mutation == "nested-reordered":
        rows = (
            rows[0],
            rows[1],
            (*rows[2][:2], ("T0", "J1"), *rows[2][3:]),
            *rows[3:],
        )
    elif mutation == "topology-token-changed":
        rows = (("root_broker", *rows[0][1:]), *rows[1:])
    elif mutation == "implicit-token-changed":
        rows = (rows[0], rows[1], (rows[2][0], ("JX",), *rows[2][2:]), *rows[3:])
    elif mutation == "explicit-token-changed":
        rows = ((*rows[0][:2], ("JX",), *rows[0][3:]), *rows[1:])
    elif mutation == "effective-token-changed":
        rows = ((*rows[0][:3], ("JX",), *rows[0][4:]), *rows[1:])
    elif mutation == "immediate-scope-changed":
        rows = ((*rows[0][:4], "JX", *rows[0][5:]), *rows[1:])
    elif mutation == "completion-owner-changed":
        rows = ((*rows[0][:5], "host:P9:J0", rows[0][6]), *rows[1:])
    elif mutation == "termination-owner-changed":
        rows = ((*rows[0][:6], "host:JX"), *rows[1:])
    elif mutation == "immediate-scope-null":
        rows = ((*rows[0][:4], None, *rows[0][5:]), *rows[1:])
    elif mutation == "completion-owner-null":
        rows = ((*rows[0][:5], None, rows[0][6]), *rows[1:])
    elif mutation == "termination-owner-null":
        rows = ((*rows[0][:6], None), *rows[1:])
    elif mutation == "scalar-wrong-type":
        rows = ((b"root-broker", *rows[0][1:]), *rows[1:])
    elif mutation == "nested-wrong-type":
        rows = ((rows[0][0], list(rows[0][1]), *rows[0][2:]), *rows[1:])
    else:
        rows = ((*rows[0][:2], (None,), *rows[0][3:]), *rows[1:])

    with pytest.raises(RuntimeError) as rejection:
        registry_type(field_names, rows)
    assert rejection.type is RuntimeError
    assert rejection.value.args == ("GUARDED_BOOTSTRAP_INVALID",)


def test_broker_native_core_job_topology_registry_rejects_nonexact_types_before_protocols_and_cross_globals() -> None:
    namespace = _load_broker_native_core_draft()
    registry_type = namespace["_C6BrokerNativeCoreDraftJobTopologyRegistry"]
    field_names = _BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_FIELD_NAMES
    rows = _BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_ROWS
    calls: list[str] = []

    class _TupleSubclass(tuple):
        pass

    class _StringSubclass(str):
        def __eq__(self, _other: object) -> bool:
            calls.append("string-eq")
            raise AssertionError("string subclass equality dispatched")

    class _BytesSubclass(bytes):
        pass

    class _Hostile:
        def __iter__(self) -> object:
            calls.append("iter")
            raise AssertionError("hostile iteration dispatched")

        def __len__(self) -> int:
            calls.append("len")
            raise AssertionError("hostile length dispatched")

        def __getitem__(self, _key: object) -> object:
            calls.append("getitem")
            raise AssertionError("hostile indexing dispatched")

        def __eq__(self, _other: object) -> bool:
            calls.append("eq")
            raise AssertionError("hostile equality dispatched")

        def __str__(self) -> str:
            calls.append("str")
            raise AssertionError("hostile string conversion dispatched")

        def __bytes__(self) -> bytes:
            calls.append("bytes")
            raise AssertionError("hostile bytes conversion dispatched")

        def __bool__(self) -> bool:
            calls.append("bool")
            raise AssertionError("hostile truth dispatched")

        def __getattribute__(self, name: str) -> object:
            if name.startswith("__"):
                return object.__getattribute__(self, name)
            calls.append(f"attribute:{name}")
            raise AssertionError("hostile attribute access dispatched")

    hostile = _Hostile()
    rejected = (
        (list(field_names), rows),
        ({"topology_id": "root-broker"}, rows),
        (b"field-names", rows),
        (1, rows),
        (_TupleSubclass(field_names), rows),
        ((_StringSubclass(field_names[0]), *field_names[1:]), rows),
        (field_names, list(rows)),
        (field_names, {"rows": rows}),
        (field_names, _BytesSubclass(b"rows")),
        (field_names, _TupleSubclass(rows)),
        (field_names, (_TupleSubclass(rows[0]), *rows[1:])),
        (field_names, ((_StringSubclass(rows[0][0]), *rows[0][1:]), *rows[1:])),
        (field_names, ((rows[0][0], _TupleSubclass(rows[0][1]), *rows[0][2:]), *rows[1:])),
        (field_names, ((*rows[0][:2], _TupleSubclass(rows[0][2]), *rows[0][3:]), *rows[1:])),
        (field_names, ((*rows[0][:3], _TupleSubclass(rows[0][3]), *rows[0][4:]), *rows[1:])),
        (field_names, ((*rows[0][:4], _StringSubclass(rows[0][4]), *rows[0][5:]), *rows[1:])),
        (field_names, ((*rows[0][:5], _StringSubclass(rows[0][5]), rows[0][6]), *rows[1:])),
        (field_names, ((*rows[0][:6], _StringSubclass(rows[0][6])), *rows[1:])),
        (field_names, ((*rows[0][:2], (_StringSubclass(rows[0][2][0]),), *rows[0][3:]), *rows[1:])),
        ((hostile, *field_names[1:]), rows),
        (field_names, ((hostile, *rows[0][1:]), *rows[1:])),
        (field_names, ((rows[0][0], (hostile,), *rows[0][2:]), *rows[1:])),
        (field_names, ((*rows[0][:2], (hostile,), *rows[0][3:]), *rows[1:])),
        (field_names, ((*rows[0][:3], (hostile,), *rows[0][4:]), *rows[1:])),
        (field_names, ((*rows[0][:4], hostile, *rows[0][5:]), *rows[1:])),
        (field_names, ((*rows[0][:5], hostile, rows[0][6]), *rows[1:])),
        (field_names, ((*rows[0][:6], hostile), *rows[1:])),
    )

    class _ForbiddenModule:
        def __getattribute__(self, name: str) -> object:
            if name.startswith("__"):
                return object.__getattribute__(self, name)
            calls.append(f"module:{name}")
            raise AssertionError("JSON/hash reached before exact type rejection")

    original_json = namespace["json"]
    original_hashlib = namespace["hashlib"]
    namespace["json"] = _ForbiddenModule()
    namespace["hashlib"] = _ForbiddenModule()
    try:
        for rejected_field_names, rejected_rows in rejected:
            with pytest.raises(RuntimeError) as rejection:
                registry_type(rejected_field_names, rejected_rows)
            assert rejection.type is RuntimeError
            assert rejection.value.args == ("GUARDED_BOOTSTRAP_INVALID",)
    finally:
        namespace["json"] = original_json
        namespace["hashlib"] = original_hashlib

    cross_globals = (
        "_C6BrokerNativeCoreDraftConstructorAttributeRegistry",
        "_C6_BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_ATTRIBUTE_REGISTRY",
        "_C6_BROKER_NATIVE_CORE_DRAFT_POLICY_ROWS",
        "_C6_BROKER_NATIVE_CORE_DRAFT_LEAF_ATTRIBUTES",
        "_C6_BROKER_NATIVE_CORE_DRAFT_CLIENT_ATTRIBUTES",
    )
    originals = {name: namespace[name] for name in cross_globals}
    try:
        for name in cross_globals:
            namespace[name] = hostile
        reconstructed = registry_type(field_names, rows)
    finally:
        namespace.update(originals)
    assert tuple(reconstructed) == (
        field_names,
        rows,
        _BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_CANONICAL_BYTES,
        _BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_SHA256,
    )
    assert calls == []


