@pytest.mark.parametrize(
    ("explicit_job_list_ids", "canonical_bytes", "expected_length", "expected_sha256"),
    _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_PROJECTION_FIXTURES,
)
def test_broker_native_core_job_list_projection_matches_fixed_literal_fixtures(
    explicit_job_list_ids: tuple[str, ...],
    canonical_bytes: bytes,
    expected_length: int,
    expected_sha256: str,
) -> None:
    namespace = _load_broker_native_core_draft()
    projection_type = namespace["_C6BrokerNativeCoreDraftJobListProjection"]
    projection = projection_type(explicit_job_list_ids)

    assert tuple(projection) == (
        explicit_job_list_ids,
        canonical_bytes,
        expected_sha256,
    )
    assert projection.explicit_job_list_ids == explicit_job_list_ids
    assert projection.canonical_bytes == canonical_bytes
    assert projection.job_list_sha256 == expected_sha256
    assert len(canonical_bytes) == expected_length
    assert expected_length == (
        3 if not explicit_job_list_ids else 35 * len(explicit_job_list_ids) + 2
    )
    assert canonical_bytes.decode("ascii", errors="strict").encode("ascii") == (
        canonical_bytes
    )
    assert json.loads(canonical_bytes) == list(explicit_job_list_ids)
    assert canonical_bytes.endswith(b"\n")
    assert canonical_bytes.count(b"\n") == 1
    assert b"\r" not in canonical_bytes
    assert b"\x00" not in canonical_bytes
    assert not canonical_bytes.startswith(b"\xef\xbb\xbf")
    assert expected_sha256.encode("ascii") not in canonical_bytes
    assert sha256(canonical_bytes).hexdigest() == expected_sha256
    assert len(expected_sha256) == 64
    assert all(character in "0123456789abcdef" for character in expected_sha256)


def test_broker_native_core_job_list_projection_preserves_order_in_bytes_and_digest() -> None:
    namespace = _load_broker_native_core_draft()
    projection_type = namespace["_C6BrokerNativeCoreDraftJobListProjection"]
    forward = projection_type(
        (
            _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_2,
            _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_3,
        )
    )
    reverse = projection_type(
        (
            _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_3,
            _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_2,
        )
    )
    reverse_literal = (
        b'["00000000000000000000000000000003",'
        b'"00000000000000000000000000000002"]\n'
    )

    assert forward.canonical_bytes == (
        b'["00000000000000000000000000000002",'
        b'"00000000000000000000000000000003"]\n'
    )
    assert reverse.canonical_bytes == reverse_literal
    assert reverse.job_list_sha256 == sha256(reverse_literal).hexdigest()
    assert reverse.job_list_sha256 != forward.job_list_sha256
    assert reverse != forward


def test_broker_native_core_job_list_projection_is_exactly_immutable_and_repr_safe() -> None:
    namespace = _load_broker_native_core_draft()
    projection_type = namespace["_C6BrokerNativeCoreDraftJobListProjection"]
    projection = projection_type(
        (
            _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_2,
            _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_3,
            _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_4,
            _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_7,
        )
    )

    assert type(projection) is projection_type
    assert type(projection.explicit_job_list_ids) is tuple
    assert all(type(job_id) is str for job_id in projection.explicit_job_list_ids)
    assert type(projection.canonical_bytes) is bytes
    assert type(projection.job_list_sha256) is str
    summary = repr(projection)
    assert str(projection) == summary
    assert "job_count=4" in summary
    assert projection.job_list_sha256 in summary
    assert not any(job_id in summary for job_id in projection.explicit_job_list_ids)
    assert repr(projection.explicit_job_list_ids) not in summary
    assert repr(projection.canonical_bytes) not in summary
    assert len(summary) < 180
    with pytest.raises(AttributeError):
        projection.explicit_job_list_ids = ()
    with pytest.raises(TypeError):
        projection[0] = ()


