def test_broker_native_core_job_list_projection_rejects_nonexact_types_before_protocols_and_modules() -> None:
    namespace = _load_broker_native_core_draft()
    projection_type = namespace["_C6BrokerNativeCoreDraftJobListProjection"]
    calls: list[str] = []

    class _TupleSubclass(tuple):
        def __iter__(self) -> object:
            calls.append("tuple-iter")
            raise AssertionError("tuple subclass iteration dispatched")

        def __len__(self) -> int:
            calls.append("tuple-len")
            raise AssertionError("tuple subclass length dispatched")

    class _StringSubclass(str):
        def __iter__(self) -> object:
            calls.append("string-iter")
            raise AssertionError("string subclass iteration dispatched")

        def __len__(self) -> int:
            calls.append("string-len")
            raise AssertionError("string subclass length dispatched")

        def __eq__(self, _other: object) -> bool:
            calls.append("string-eq")
            raise AssertionError("string subclass equality dispatched")

        def __hash__(self) -> int:
            calls.append("string-hash")
            raise AssertionError("string subclass hash dispatched")

    class _BytesSubclass(bytes):
        pass

    class _Hostile:
        def __iter__(self) -> object:
            calls.append("iter")
            raise AssertionError("hostile iteration dispatched")

        def __len__(self) -> int:
            calls.append("len")
            raise AssertionError("hostile length dispatched")

        def __getitem__(self, _key: object) -> object:
            calls.append("getitem")
            raise AssertionError("hostile indexing dispatched")

        def __eq__(self, _other: object) -> bool:
            calls.append("eq")
            raise AssertionError("hostile equality dispatched")

        def __hash__(self) -> int:
            calls.append("hash")
            raise AssertionError("hostile hashing dispatched")

        def __str__(self) -> str:
            calls.append("str")
            raise AssertionError("hostile string conversion dispatched")

        def __bytes__(self) -> bytes:
            calls.append("bytes")
            raise AssertionError("hostile bytes conversion dispatched")

        def __bool__(self) -> bool:
            calls.append("bool")
            raise AssertionError("hostile truth dispatched")

    hostile = _Hostile()
    rejected = (
        [],
        {"job": _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_1},
        b"job-list",
        _BytesSubclass(b"job-list"),
        1,
        hostile,
        _TupleSubclass((_BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_1,)),
        (_StringSubclass(_BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_1),),
        (_BytesSubclass(b"0" * 32),),
        (hostile,),
        ("0" * 31,),
        ("0" * 33,),
        ("A" * 32,),
        ("g" * 32,),
        ("\x00" + "0" * 31,),
        (
            _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_1,
            _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_1,
        ),
    )

    class _ForbiddenModule:
        def __getattribute__(self, name: str) -> object:
            if name.startswith("__"):
                return object.__getattribute__(self, name)
            calls.append(f"module:{name}")
            raise AssertionError("JSON/hash reached before exact rejection")

    original_json = namespace["json"]
    original_hashlib = namespace["hashlib"]
    namespace["json"] = _ForbiddenModule()
    namespace["hashlib"] = _ForbiddenModule()
    try:
        for invalid_ids in rejected:
            with pytest.raises(RuntimeError) as rejection:
                projection_type(invalid_ids)
            assert rejection.type is RuntimeError
            assert rejection.value.args == ("GUARDED_BOOTSTRAP_INVALID",)
    finally:
        namespace["json"] = original_json
        namespace["hashlib"] = original_hashlib
    assert calls == []


def test_broker_native_core_job_list_projection_constructor_surface_is_closed_and_dormant() -> None:
    namespace = _load_broker_native_core_draft()
    projection_type = namespace["_C6BrokerNativeCoreDraftJobListProjection"]
    valid_ids = (_BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_1,)

    assert tuple(inspect.signature(projection_type.__new__).parameters) == (
        "cls",
        "explicit_job_list_ids",
    )
    assert tuple(inspect.signature(projection_type).parameters) == (
        "explicit_job_list_ids",
    )
    assert projection_type(explicit_job_list_ids=valid_ids) == projection_type(
        valid_ids
    )
    for arguments in ((), (valid_ids, b"caller-bytes")):
        with pytest.raises(TypeError):
            projection_type(*arguments)
    for keyword in (
        "canonical_bytes",
        "job_list_sha256",
        "job_count",
        "topology_id",
        "job_kind",
        "handle",
        "fresh_id",
        "factory",
        "selector",
        "authorization",
        "authority",
    ):
        with pytest.raises(TypeError):
            projection_type(valid_ids, **{keyword: object()})

    class _ProjectionSubclass(projection_type):
        pass

    with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
        _ProjectionSubclass(valid_ids)

    projection = projection_type(valid_ids)
    for forbidden_attribute in (
        "job_count",
        "topology_id",
        "job_kind",
        "handle",
        "fresh_id",
        "authorized",
        "authorization",
        "authority",
    ):
        assert not hasattr(projection, forbidden_attribute)

    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    class_name = "_C6BrokerNativeCoreDraftJobListProjection"
    class_nodes = tuple(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )
    assert len(class_nodes) == 1
    class_node = class_nodes[0]
    class_text = ast.unparse(class_node).lower()
    assert not any(
        token in class_text
        for token in (
            "authorization",
            "authority",
            "factory",
            "fresh",
            "handle",
            "os.",
            "random",
            "secrets",
            "selector",
            "topology",
            "uuid",
        )
    )
    parents = {
        child: node
        for node in ast.walk(tree)
        for child in ast.iter_child_nodes(node)
    }
    class_loads = tuple(
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Name)
        and isinstance(node.ctx, ast.Load)
        and node.id == class_name
    )
    assert len(class_loads) == 1
    class_guard = parents[class_loads[0]]
    assert isinstance(class_guard, ast.Compare)
    assert isinstance(class_guard.left, ast.Name)
    assert class_guard.left.id == "cls"
    assert len(class_guard.ops) == 1
    assert isinstance(class_guard.ops[0], ast.IsNot)
    assert class_guard.comparators == [class_loads[0]]
    assert not any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == class_name
        for node in ast.walk(tree)
    )
    callable_authority_surface = {
        name
        for name, value in namespace.items()
        if name.startswith("_c6_broker_native_core_draft_")
        and "job_list" in name
        and callable(value)
    }
    assert callable_authority_surface == set()
    assert not BOOTSTRAP_PATH.with_name("complete_suite_control_plane.ps1").exists()
    for marker in (
        "C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN",
        "C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END",
    ):
        assert marker not in source


def test_broker_native_core_job_list_projection_cross_binds_all_topology_rows_only_in_tests() -> None:
    namespace = _load_broker_native_core_draft()
    projection_type = namespace["_C6BrokerNativeCoreDraftJobListProjection"]
    topology_registry = namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_REGISTRY"
    ]
    constructor_registry = namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_ATTRIBUTE_REGISTRY"
    ]
    expected_rows = (
        ("root-broker", ("J0",), (_BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_1,)),
        (
            "standalone-native-leaf",
            ("L0",),
            (_BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_8,),
        ),
        (
            "initial-guarded-target",
            ("J1", "T0"),
            (
                _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_2,
                _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_3,
            ),
        ),
        (
            "nested-guarded-target",
            ("J1", "T0..Tk", "Tnew"),
            (
                _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_2,
                _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_3,
                _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_4,
                _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_5,
            ),
        ),
        (
            "broker-native-leaf",
            ("J1", "T0..Tk", "Ln"),
            (
                _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_2,
                _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_3,
                _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_4,
                _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_6,
            ),
        ),
        (
            "codex-client-root",
            ("J1", "T0..Tk", "Cn"),
            (
                _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_2,
                _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_3,
                _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_4,
                _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_7,
            ),
        ),
        ("codex-client-descendant", (), ()),
    )

    assert tuple((row[0], row[2]) for row in topology_registry.rows) == tuple(
        (topology_id, explicit_kinds)
        for topology_id, explicit_kinds, _explicit_ids in expected_rows
    )
    fixture_by_ids = {
        fixture[0]: (fixture[1], fixture[3])
        for fixture in _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_PROJECTION_FIXTURES
    }
    for _topology_id, _explicit_kinds, explicit_ids in expected_rows:
        projection = projection_type(explicit_ids)
        assert (projection.canonical_bytes, projection.job_list_sha256) == (
            fixture_by_ids[explicit_ids]
        )

    assert all(
        _BROKER_NATIVE_CORE_DRAFT_JOB_LIST_ID_1 not in explicit_ids
        for _topology_id, _explicit_kinds, explicit_ids in expected_rows[2:6]
    )
    assert expected_rows[-1][1:] == ((), ())
    constructor_by_class = {row[0]: row for row in constructor_registry.rows}
    constructor_created_rows = (
        ("root-broker", "root-broker"),
        ("standalone-native-leaf", "guarded-target-or-native-leaf"),
        ("initial-guarded-target", "guarded-target-or-native-leaf"),
        ("nested-guarded-target", "guarded-target-or-native-leaf"),
        ("broker-native-leaf", "guarded-target-or-native-leaf"),
        ("codex-client-root", "codex-client-root"),
    )
    assert tuple(topology_id for topology_id, _class in constructor_created_rows) == (
        tuple(row[0] for row in topology_registry.rows[:-1])
    )
    assert all(
        "JOB_LIST" in constructor_by_class[constructor_class][3]
        for _topology_id, constructor_class in constructor_created_rows
    )


