def test_broker_native_core_internal_channel_address_surface_is_closed_and_dormant() -> None:
    namespace = _load_broker_native_core_draft()
    class_name = "_C6BrokerNativeCoreDraftInternalChannelAddress"
    address_type = namespace[class_name]
    token = _BROKER_NATIVE_CORE_DRAFT_INTERNAL_CHANNEL_TOKEN

    assert tuple(inspect.signature(address_type.__new__).parameters) == (
        "cls",
        "token",
        "fixed_role",
    )
    assert tuple(inspect.signature(address_type).parameters) == (
        "token",
        "fixed_role",
    )
    assert address_type(token=token, fixed_role="go") == address_type(token, "go")
    for arguments in ((), (token,), (token, "go", "caller-output")):
        with pytest.raises(TypeError):
            address_type(*arguments)
    for keyword in (
        "pipe_name",
        "parent_action",
        "server_open_mode",
        "child_access",
        "digest",
        "ordinal",
        "applicability",
        "role_applicability",
        "token_generator",
        "token_reservation",
        "handle",
        "handle_manifest",
        "frame",
        "authorization",
        "authority",
        "factory",
        "selector",
        "registry",
    ):
        with pytest.raises(TypeError):
            address_type(token, "go", **{keyword: object()})

    class _AddressSubclass(address_type):
        pass

    with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
        _AddressSubclass(token, "go")

    address = address_type(token, "go")
    for forbidden_attribute in (
        "digest",
        "ordinal",
        "applicability",
        "role_applicability",
        "token_generator",
        "token_reservation",
        "handle",
        "handle_manifest",
        "frame",
        "authorization",
        "authority",
        "factory",
        "selector",
        "registry",
    ):
        assert not hasattr(address, forbidden_attribute)

    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    class_nodes = tuple(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )
    assert len(class_nodes) == 1
    parents = {
        child: node
        for node in ast.walk(tree)
        for child in ast.iter_child_nodes(node)
    }
    class_loads = tuple(
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Name)
        and isinstance(node.ctx, ast.Load)
        and node.id == class_name
    )
    assert len(class_loads) == 1
    class_guard = parents[class_loads[0]]
    assert isinstance(class_guard, ast.Compare)
    assert isinstance(class_guard.left, ast.Name)
    assert class_guard.left.id == "cls"
    assert len(class_guard.ops) == 1
    assert isinstance(class_guard.ops[0], ast.IsNot)
    assert class_guard.comparators == [class_loads[0]]
    assert not any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == class_name
        for node in ast.walk(tree)
    )
    assert {
        name
        for name, value in namespace.items()
        if name.startswith("_c6_broker_native_core_draft_")
        and "channel" in name
        and callable(value)
    } == set()
    assert not any(
        name != class_name and "INTERNAL_CHANNEL_ADDRESS" in name.upper()
        for name in namespace
    )
    assert not BOOTSTRAP_PATH.with_name("complete_suite_control_plane.ps1").exists()
    for marker in (
        "C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN",
        "C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END",
    ):
        assert marker not in source


