def test_broker_native_core_internal_channel_endpoint_construction_facts_cross_bind_addresses_and_applicability_without_claiming_direction_authority() -> None:
    namespace = _load_broker_native_core_draft()
    facts = namespace[
        "_C6BrokerNativeCoreDraftInternalChannelEndpointConstructionFactsRegistry"
    ]()
    applicability = namespace[
        "_C6BrokerNativeCoreDraftInternalChannelApplicabilityRegistry"
    ]()
    address_type = namespace["_C6BrokerNativeCoreDraftInternalChannelAddress"]
    token = _BROKER_NATIVE_CORE_DRAFT_INTERNAL_CHANNEL_TOKEN
    row = facts.rows[0]
    by_field = dict(zip(facts.field_names, row, strict=True))
    all_roles = (
        "descriptor",
        "ack-status",
        "go",
        "broker-request",
        "broker-response",
        "stdin",
        "stdout",
        "stderr",
    )
    stdio_roles = ("stdin", "stdout", "stderr")

    assert applicability.rows[0][3] == all_roles
    assert tuple(row[3] for row in applicability.rows[1:]) == (
        stdio_roles,
        stdio_roles,
        stdio_roles,
    )
    assert by_field["implementation_id"] == applicability.rows[0][0]
    assert by_field["implementation_id"] == namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_IMPLEMENTATION_ID"
    ]
    for applicability_row in applicability.rows:
        for fixed_role in applicability_row[3]:
            address = address_type(token, fixed_role)
            server_open_tokens = (
                address.server_open_mode,
                *by_field["common_server_open_flag_tokens"],
            )
            child_open_facts = (
                address.child_access,
                by_field["child_share_mode"],
                by_field["child_creation_disposition"],
                by_field["child_inheritable"],
                by_field["child_synchronous"],
            )
            assert server_open_tokens == (
                address.server_open_mode,
                "FILE_FLAG_FIRST_PIPE_INSTANCE",
                "FILE_FLAG_OVERLAPPED",
            )
            assert server_open_tokens[0] in {
                "PIPE_ACCESS_OUTBOUND",
                "PIPE_ACCESS_INBOUND",
            }
            assert child_open_facts == (
                address.child_access,
                0,
                "OPEN_EXISTING",
                True,
                True,
            )
            assert child_open_facts[0] in {"GENERIC_READ", "GENERIC_WRITE"}

    assert tuple(row[3] for row in applicability.rows) == (
        all_roles,
        stdio_roles,
        stdio_roles,
        stdio_roles,
    )


def test_broker_native_core_internal_channel_endpoint_construction_facts_pin_connect_and_successful_path_order() -> None:
    registry = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftInternalChannelEndpointConstructionFactsRegistry"
    ]()
    row = registry.rows[0]
    phases = registry.successful_path_per_channel_phases
    by_field = dict(zip(registry.field_names, row, strict=True))

    assert phases == (
        "server-created",
        "server-associated-with-private-iocp",
        "overlapped-connect-issued-with-FALSE/ERROR_IO_PENDING",
        "child-endpoint-opened",
        "one-successful-connect-completion-consumed",
        "per-channel-child-endpoint-only-placed-in-HANDLE_LIST",
        "CreateProcessW-succeeded",
        "parent-duplicate-of-child-endpoint-closed-immediately",
    )
    assert (
        phases.index("server-associated-with-private-iocp")
        < phases.index(
            "overlapped-connect-issued-with-FALSE/ERROR_IO_PENDING"
        )
        < phases.index("child-endpoint-opened")
        < phases.index("one-successful-connect-completion-consumed")
        < phases.index(
            "per-channel-child-endpoint-only-placed-in-HANDLE_LIST"
        )
        < phases.index("CreateProcessW-succeeded")
        < phases.index(
            "parent-duplicate-of-child-endpoint-closed-immediately"
        )
    )
    assert by_field["connect_overlapped"] is True
    assert by_field[
        "successful_connect_completions_required_before_process_creation"
    ] == 1
    assert by_field[
        "connect_overlapped_retained_until_completion_consumed"
    ] is True
    assert by_field[
        "connect_buffer_retained_until_completion_consumed"
    ] is True
    assert by_field["per_channel_handle_list_endpoint"] == (
        "child-endpoint-only"
    )
    assert "server" not in by_field["per_channel_handle_list_endpoint"]
    assert "child-endpoint-only" in phases[5]
    assert phases[-1].endswith("closed-immediately")


def test_broker_native_core_internal_channel_endpoint_construction_facts_registry_is_zero_arg_immutable_and_bounded() -> None:
    registry_type = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftInternalChannelEndpointConstructionFactsRegistry"
    ]
    registry = registry_type()
    expected_summary = (
        "_C6BrokerNativeCoreDraftInternalChannelEndpointConstructionFactsRegistry("
        "field_count=18, row_count=1, phase_count=8)"
    )

    assert tuple(inspect.signature(registry_type.__new__).parameters) == ("cls",)
    assert tuple(inspect.signature(registry_type).parameters) == ()
    assert repr(registry) == expected_summary
    assert str(registry) == expected_summary
    assert len(expected_summary) == 116
    for arguments in ((None,), (("descriptor",),), (object(), object())):
        with pytest.raises(TypeError):
            registry_type(*arguments)
    for keyword in (
        "role",
        "address",
        "handle",
        "ordinal",
        "key",
        "result",
        "callback",
        "server_inheritable",
        "selector",
        "factory",
        "digest",
    ):
        with pytest.raises(TypeError):
            registry_type(**{keyword: object()})
    with pytest.raises(AttributeError):
        registry.rows = ()
    with pytest.raises(TypeError):
        registry[0] = ()

    class _RegistrySubclass(registry_type):
        pass

    with pytest.raises(RuntimeError) as rejection:
        _RegistrySubclass()
    assert rejection.type is RuntimeError
    assert rejection.value.args == ("GUARDED_BOOTSTRAP_INVALID",)


def test_broker_native_core_internal_channel_endpoint_construction_facts_registry_is_module_dependency_free() -> None:
    namespace = _load_broker_native_core_draft()
    registry_type = namespace[
        "_C6BrokerNativeCoreDraftInternalChannelEndpointConstructionFactsRegistry"
    ]
    calls: list[str] = []

    class _ForbiddenModule:
        def __getattribute__(self, name: str) -> object:
            if name.startswith("__"):
                return object.__getattribute__(self, name)
            calls.append(name)
            raise AssertionError("endpoint construction facts used a module")

    originals = {
        module_name: namespace[module_name]
        for module_name in ("json", "hashlib", "os", "sys")
    }
    namespace.update(
        {module_name: _ForbiddenModule() for module_name in originals}
    )
    try:
        registry = registry_type()
    finally:
        namespace.update(originals)

    assert tuple(registry) == (
        _BROKER_NATIVE_CORE_DRAFT_INTERNAL_CHANNEL_ENDPOINT_CONSTRUCTION_FIELD_NAMES,
        _BROKER_NATIVE_CORE_DRAFT_INTERNAL_CHANNEL_ENDPOINT_CONSTRUCTION_ROWS,
        _BROKER_NATIVE_CORE_DRAFT_INTERNAL_CHANNEL_ENDPOINT_CONSTRUCTION_PHASES,
    )
    assert calls == []


