def test_broker_native_core_iocp_operation_issue_facts_pin_issue_order_return_transitions_and_retirement() -> None:
    registry = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftIocpOperationIssueFactsRegistry"
    ]()
    phases = registry.issue_phases
    return_fields, return_rows = registry.issue_return_table
    lifetime_fields, lifetime_rows = registry.allocation_lifetime_table
    returns_by_match = {
        row[1]: dict(zip(return_fields, row, strict=True))
        for row in return_rows
    }
    lifetimes_by_match = {
        row[0]: dict(zip(lifetime_fields, row, strict=True))
        for row in lifetime_rows
    }

    assert phases == (
        "zero-dedicated-OVERLAPPED",
        "allocate-immutable-operation-buffer-and-cursor",
        "insert-ISSUING-ledger-entry",
        "invoke-overlapped-ReadFile-or-WriteFile",
    )
    assert phases.index("zero-dedicated-OVERLAPPED") < phases.index(
        "allocate-immutable-operation-buffer-and-cursor"
    ) < phases.index("insert-ISSUING-ledger-entry") < phases.index(
        "invoke-overlapped-ReadFile-or-WriteFile"
    )
    assert tuple(returns_by_match) == (
        "TRUE",
        "FALSE/ERROR_IO_PENDING",
        "FALSE/ERROR_BROKEN_PIPE-and-role-permitted-read-terminal",
        "any-other-FALSE/GetLastError()",
    )
    assert returns_by_match["TRUE"] == {
        "api_scope": "ReadFile-or-WriteFile",
        "return_match": "TRUE",
        "ledger_state_before": "ISSUING",
        "ledger_state_after": "LIVE_AWAIT_PACKET",
        "recorded_outcome": "none",
        "packet_expected": True,
        "immediate_byte_count_policy": "ignore",
    }
    assert returns_by_match["FALSE/ERROR_IO_PENDING"][
        "ledger_state_after"
    ] == "LIVE_AWAIT_PACKET"
    assert returns_by_match["FALSE/ERROR_IO_PENDING"][
        "packet_expected"
    ] is True
    broken_pipe = returns_by_match[
        "FALSE/ERROR_BROKEN_PIPE-and-role-permitted-read-terminal"
    ]
    assert broken_pipe["api_scope"] == "ReadFile"
    assert broken_pipe["ledger_state_after"] is None
    assert broken_pipe["recorded_outcome"] == "immediate-EOF"
    assert broken_pipe["packet_expected"] is False
    other_error = returns_by_match["any-other-FALSE/GetLastError()"]
    assert other_error["ledger_state_after"] is None
    assert other_error["recorded_outcome"] == "immediate-terminal-error"
    assert other_error["packet_expected"] is False
    assert not any(
        "ERROR_PIPE_CONNECTED" in row[1] for row in return_rows
    )
    assert tuple(lifetimes_by_match) == (
        "TRUE",
        "FALSE/ERROR_IO_PENDING",
    )
    for lifetime in lifetimes_by_match.values():
        assert lifetime["overlapped_action"] == "retain"
        assert lifetime["buffer_and_cursor_action"] == "retain"
        assert lifetime["retention_boundary"] == (
            "exact-one-queued-packet-consumed"
        )
        assert lifetime["pre_retirement_prohibition"] == (
            "no-reuse-move-or-free"
        )
    assert registry.invariants == (
        _BROKER_NATIVE_CORE_DRAFT_IOCP_OPERATION_ISSUE_INVARIANTS
    )


def test_broker_native_core_iocp_operation_issue_facts_cross_bind_internal_channel_roles_and_connect_retention() -> None:
    namespace = _load_broker_native_core_draft()
    registry = namespace[
        "_C6BrokerNativeCoreDraftIocpOperationIssueFactsRegistry"
    ]()
    applicability = namespace[
        "_C6BrokerNativeCoreDraftInternalChannelApplicabilityRegistry"
    ]()
    address_type = namespace[
        "_C6BrokerNativeCoreDraftInternalChannelAddress"
    ]
    endpoint_facts = namespace[
        "_C6BrokerNativeCoreDraftInternalChannelEndpointConstructionFactsRegistry"
    ]()
    endpoint_by_field = dict(
        zip(endpoint_facts.field_names, endpoint_facts.rows[0], strict=True)
    )
    identity_fields, identity_rows = registry.identity_table
    identity = dict(zip(identity_fields, identity_rows[0], strict=True))
    lifetime_fields, lifetime_rows = registry.allocation_lifetime_table
    lifetimes = {
        row[0]: dict(zip(lifetime_fields, row, strict=True))
        for row in lifetime_rows
    }
    action_to_issue_api = {"reads": "ReadFile", "writes": "WriteFile"}
    token = _BROKER_NATIVE_CORE_DRAFT_INTERNAL_CHANNEL_TOKEN
    observed_issue_apis: set[str] = set()

    assert identity["implementation_id"] == namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_IMPLEMENTATION_ID"
    ] == "broker-native-core-v1"
    assert identity["issue_api_literals"] == ("ReadFile", "WriteFile")
    for applicability_row in applicability.rows:
        assert applicability_row[0] == identity["implementation_id"]
        for fixed_role in applicability_row[3]:
            address = address_type(token, fixed_role)
            issue_api = action_to_issue_api[address.parent_action]
            observed_issue_apis.add(issue_api)
            assert issue_api in identity["issue_api_literals"]
    assert observed_issue_apis == {"ReadFile", "WriteFile"}

    pending = "FALSE/ERROR_IO_PENDING"
    assert endpoint_by_field["accepted_initial_connect_result_literal"] == (
        pending
    )
    assert endpoint_by_field[
        "connect_overlapped_retained_until_completion_consumed"
    ] is True
    assert endpoint_by_field[
        "connect_buffer_retained_until_completion_consumed"
    ] is True
    assert lifetimes[pending]["overlapped_action"] == "retain"
    assert lifetimes[pending]["buffer_and_cursor_action"] == "retain"
    assert all(
        lifetime["retention_boundary"]
        == "exact-one-queued-packet-consumed"
        for lifetime in lifetimes.values()
    )
    assert any(
        "overlapped-connect" in phase
        for phase in endpoint_facts.successful_path_per_channel_phases
    )
    assert "connect" not in repr(tuple(registry)).casefold()


