def test_broker_native_core_iocp_dispatch_result_facts_constructor_call_and_selector_oracles_reject_every_extra_surface() -> None:
    class_name = (
        "_C6BrokerNativeCoreDraftIocpDispatchResultFactsRegistry"
    )
    selector_name = (
        "_c6_broker_native_core_draft_select_iocp_dispatch_result_facts"
    )
    exact_call = ast.parse(f"{class_name}()").body[0]
    malformed_calls = (
        None,
        ast.parse("_WrongRegistry()").body[0],
        ast.parse(f"{class_name}(object())").body[0],
        ast.parse(f"{class_name}(role=object())").body[0],
        ast.parse(f"holder.{class_name}()").body[0],
    )
    exact_selector = ast.parse(
        f"def {selector_name}():\n    return {class_name}()",
        type_comments=True,
    ).body[0]
    malformed_selector_sources = (
        f"@staticmethod\ndef {selector_name}():\n    return {class_name}()",
        (
            f"def {selector_name}():\n"
            "    # type: () -> object\n"
            f"    return {class_name}()"
        ),
        f"def {selector_name}(role, /):\n    return {class_name}()",
        f"def {selector_name}(role):\n    return {class_name}()",
        f"def {selector_name}(*extra):\n    return {class_name}()",
        f"def {selector_name}(*, extra):\n    return {class_name}()",
        f"def {selector_name}(*, extra=None):\n    return {class_name}()",
        f"def {selector_name}(**extra):\n    return {class_name}()",
        f"def {selector_name}(role=None):\n    return {class_name}()",
        f"def {selector_name}() -> object:\n    return {class_name}()",
        f"def {selector_name}[T]():\n    return {class_name}()",
        f"def {selector_name}():\n    pass\n    return {class_name}()",
        f"def {selector_name}():\n    return None",
        f"def {selector_name}():\n    return _WrongRegistry()",
        f"def {selector_name}():\n    return {class_name}(object())",
        f"def {selector_name}():\n    return {class_name}(role=object())",
        f"def {selector_name}():\n    return holder.{class_name}()",
    )
    malformed_selectors = tuple(
        ast.parse(source, type_comments=True).body[0]
        for source in malformed_selector_sources
    )

    assert isinstance(exact_call, ast.Expr)
    assert _broker_native_core_iocp_dispatch_result_exact_zero_arg_constructor_call(
        exact_call.value
    )
    assert all(
        not _broker_native_core_iocp_dispatch_result_exact_zero_arg_constructor_call(
            candidate.value if isinstance(candidate, ast.Expr) else candidate
        )
        for candidate in malformed_calls
    )
    assert _broker_native_core_iocp_dispatch_result_exact_selector(
        exact_selector
    )
    assert all(
        not _broker_native_core_iocp_dispatch_result_exact_selector(candidate)
        for candidate in malformed_selectors
    )


