def test_broker_native_core_iocp_successful_zero_byte_write_result_facts_cross_bind_issue_and_dispatch_without_immediate_count_or_lifecycle_authority() -> None:
    namespace = _load_broker_native_core_draft()
    registry = namespace[
        "_C6BrokerNativeCoreDraftIocpSuccessfulZeroByteWriteResultFactsRegistry"
    ]()
    issue_registry = namespace[
        "_C6BrokerNativeCoreDraftIocpOperationIssueFactsRegistry"
    ]()
    dispatch_registry = namespace[
        "_C6BrokerNativeCoreDraftIocpDispatchResultFactsRegistry"
    ]()
    identity_fields, identity_rows = registry.identity_table
    issue_identity_fields, issue_identity_rows = issue_registry.identity_table
    dispatch_identity_fields, dispatch_identity_rows = (
        dispatch_registry.identity_table
    )
    identity = dict(zip(identity_fields, identity_rows[0], strict=True))
    issue_identity = dict(
        zip(issue_identity_fields, issue_identity_rows[0], strict=True)
    )
    dispatch_identity = dict(
        zip(dispatch_identity_fields, dispatch_identity_rows[0], strict=True)
    )
    dispatch_rows = tuple(
        dict(zip(dispatch_registry.result_field_names, row, strict=True))
        for row in dispatch_registry.result_rows
    )
    successful_pipe_rows = tuple(
        row
        for row in dispatch_rows
        if row["classification"] == "successful-pipe-I/O-completion"
    )

    assert identity["implementation_id"] == namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_IMPLEMENTATION_ID"
    ] == issue_identity["implementation_id"]
    assert identity["state_machine_id"] == issue_identity["state_machine_id"]
    assert identity["write_api_literals"] == ("WriteFile",)
    assert set(identity["write_api_literals"]).issubset(
        issue_identity["issue_api_literals"]
    )
    assert dispatch_identity["dispatch_api_literals"] == (
        "GetQueuedCompletionStatus",
    )
    assert len(successful_pipe_rows) == 1
    successful_pipe_row = successful_pipe_rows[0]
    assert successful_pipe_row == {
        "gqcs_return_match": "TRUE",
        "completion_key_domain": "symbolic-registered-pipe-role-domain",
        "lp_overlapped_semantics": "non-null-exact-live-OVERLAPPED",
        "packet_dequeued": True,
        "last_error_policy": "not-applicable",
        "classification": "successful-pipe-I/O-completion",
    }
    assert identity["upstream_dispatch_classification"] == (
        successful_pipe_row["classification"]
    )
    assert identity["completion_byte_count_source"] == (
        "lpNumberOfBytesTransferred-from-the-exact-dequeued-successful-WriteFile-completion-packet"
    )
    assert (
        "the-dequeued-pipe-packet-must-match-exactly-one-LIVE_AWAIT_PACKET-OVERLAPPED"
        in registry.invariants
    )
    assert (
        "every-pipe-packet-must-match-exactly-one-live-OVERLAPPED"
        in dispatch_registry.invariants
        and "every-pipe-packet-must-match-exactly-one-live-OVERLAPPED"
        in issue_registry.invariants
    )
    assert (
        "the-immediate-WriteFile-byte-count-is-never-an-input-to-this-result"
        in registry.invariants
    )
    assert (
        "failure-is-only-a-write-result-classification-and-grants-no-retirement-continuation-reissue-cleanup-cancellation-closing-or-overall-publication-authority"
        in registry.invariants
    )


def test_broker_native_core_iocp_successful_zero_byte_write_result_facts_registry_is_zero_arg_immutable_and_bounded() -> None:
    registry_type = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftIocpSuccessfulZeroByteWriteResultFactsRegistry"
    ]
    registry = registry_type()
    expected_summary = (
        "_C6BrokerNativeCoreDraftIocpSuccessfulZeroByteWriteResultFactsRegistry("
        "identity_row_count=1, result_field_count=2, result_row_count=1, "
        "invariant_count=6)"
    )

    assert tuple(inspect.signature(registry_type.__new__).parameters) == ("cls",)
    assert tuple(inspect.signature(registry_type).parameters) == ()
    assert tuple(
        name
        for name, value in vars(registry_type).items()
        if isinstance(value, property)
    ) == (
        "identity_table",
        "result_field_names",
        "result_rows",
        "invariants",
    )
    assert repr(registry) == expected_summary
    assert str(registry) == expected_summary
    assert len(expected_summary) < 220
    assert not hasattr(registry, "__dict__")
    for arguments in ((None,), (("zero-bytes",),), (object(), object())):
        with pytest.raises(TypeError):
            registry_type(*arguments)
    for keyword in (
        "byte_count",
        "completion_packet",
        "handle",
        "overlapped",
        "role",
        "selector",
        "classifier",
        "consumer",
        "digest",
    ):
        with pytest.raises(TypeError):
            registry_type(**{keyword: object()})
    for property_name in (
        "identity_table",
        "result_field_names",
        "result_rows",
        "invariants",
    ):
        with pytest.raises(AttributeError):
            setattr(registry, property_name, ())
    with pytest.raises(TypeError):
        registry[0] = ()

    class _RegistrySubclass(registry_type):
        pass

    with pytest.raises(RuntimeError) as rejection:
        _RegistrySubclass()
    assert rejection.type is RuntimeError
    assert rejection.value.args == ("GUARDED_BOOTSTRAP_INVALID",)


def test_broker_native_core_iocp_successful_zero_byte_write_result_facts_registry_is_module_dependency_free() -> None:
    namespace = _load_broker_native_core_draft()
    registry_type = namespace[
        "_C6BrokerNativeCoreDraftIocpSuccessfulZeroByteWriteResultFactsRegistry"
    ]
    calls: list[str] = []

    class _ForbiddenModule:
        def __getattribute__(self, name: str) -> object:
            if name.startswith("__"):
                return object.__getattribute__(self, name)
            calls.append(name)
            raise AssertionError("zero-byte write facts used a module")

    originals = {
        module_name: namespace[module_name]
        for module_name in ("json", "hashlib", "os", "sys")
    }
    namespace.update(
        {module_name: _ForbiddenModule() for module_name in originals}
    )
    try:
        registry = registry_type()
    finally:
        namespace.update(originals)

    assert tuple(registry) == (
        _BROKER_NATIVE_CORE_DRAFT_IOCP_SUCCESSFUL_ZERO_BYTE_WRITE_RESULT_IDENTITY_TABLE,
        _BROKER_NATIVE_CORE_DRAFT_IOCP_SUCCESSFUL_ZERO_BYTE_WRITE_RESULT_FIELD_NAMES,
        _BROKER_NATIVE_CORE_DRAFT_IOCP_SUCCESSFUL_ZERO_BYTE_WRITE_RESULT_ROWS,
        _BROKER_NATIVE_CORE_DRAFT_IOCP_SUCCESSFUL_ZERO_BYTE_WRITE_RESULT_INVARIANTS,
    )
    assert calls == []


def test_broker_native_core_iocp_successful_zero_byte_write_result_facts_are_partial_class_only_and_dormant() -> None:
    namespace = _load_broker_native_core_draft()
    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    class_name = (
        "_C6BrokerNativeCoreDraftIocpSuccessfulZeroByteWriteResultFactsRegistry"
    )
    class_nodes = tuple(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )

    assert len(class_nodes) == 1
    class_node = class_nodes[0]
    assert tuple(
        member.name
        for member in class_node.body
        if isinstance(member, ast.FunctionDef)
    ) == (
        "__new__",
        "identity_table",
        "result_field_names",
        "result_rows",
        "invariants",
        "__repr__",
    )
    assert tuple(
        member.name
        for member in class_node.body
        if isinstance(member, ast.FunctionDef)
        and any(
            isinstance(decorator, ast.Name) and decorator.id == "property"
            for decorator in member.decorator_list
        )
    ) == (
        "identity_table",
        "result_field_names",
        "result_rows",
        "invariants",
    )
    parents = {
        child: node
        for node in ast.walk(tree)
        for child in ast.iter_child_nodes(node)
    }
    class_loads = tuple(
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Name)
        and isinstance(node.ctx, ast.Load)
        and node.id == class_name
    )
    assert len(class_loads) == 1
    class_guard = parents[class_loads[0]]
    assert isinstance(class_guard, ast.Compare)
    assert isinstance(class_guard.left, ast.Name)
    assert class_guard.left.id == "cls"
    assert len(class_guard.ops) == 1
    assert isinstance(class_guard.ops[0], ast.IsNot)
    assert class_guard.comparators == [class_loads[0]]
    assert not any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == class_name
        for node in ast.walk(tree)
    )
    assert not any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id
        in {
            "WriteFile",
            "GetQueuedCompletionStatus",
            "GetLastError",
            "CancelIoEx",
            "CloseHandle",
            "ReadFile",
        }
        for node in ast.walk(class_node)
    )
    assert not any(
        name != class_name
        and "IOCP_SUCCESSFUL_ZERO_BYTE_WRITE_RESULT" in name.upper()
        for name in namespace
    )
    class_text = ast.unparse(class_node).casefold()
    for forbidden_fragment in (
        "error_broken_pipe",
        "error_operation_aborted",
        "retry-after",
        "raw-error",
        "handle_value",
        "pointer_value",
        "completion_key",
        "pipe_ordinal",
        "role_to_key",
        "0x1000",
        "wait_timeout",
        "grace-period",
        "poll-until",
        "quarantine-operation",
        "free-operation",
        "singleton",
        "selector",
        "factory",
        "helper",
        "digest",
        "sha256",
        "canonical",
        "classifier",
        "consumer",
        "implementation-begin",
        "implementation-end",
    ):
        assert forbidden_fragment not in class_text
    assert tuple(
        (alias.name, alias.asname)
        for node in tree.body
        if isinstance(node, ast.Import)
        for alias in node.names
    ) == (
        ("hashlib", None),
        ("json", None),
        ("os", None),
        ("sys", None),
    )
    assert not BOOTSTRAP_PATH.with_name(
        "complete_suite_control_plane.ps1"
    ).exists()
    for marker in (
        "C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN",
        "C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END",
    ):
        assert marker not in source


def _broker_native_core_iocp_successful_zero_byte_write_result_constructor_signature_is_exact(
    function: ast.FunctionDef,
) -> bool:
    arguments = function.args
    all_arguments = (
        *arguments.posonlyargs,
        *arguments.args,
        *arguments.kwonlyargs,
    )
    return (
        function.name == "__new__"
        and function.decorator_list == []
        and function.type_comment is None
        and arguments.posonlyargs == []
        and tuple(argument.arg for argument in arguments.args) == ("cls",)
        and arguments.vararg is None
        and arguments.kwonlyargs == []
        and arguments.kw_defaults == []
        and arguments.kwarg is None
        and arguments.defaults == []
        and all(
            argument.annotation is None and argument.type_comment is None
            for argument in all_arguments
        )
        and function.returns is None
        and function.type_params == []
    )


def test_broker_native_core_iocp_successful_zero_byte_write_result_facts_constructor_signature_oracle_rejects_every_extra_surface() -> None:
    exact = ast.parse("def __new__(cls):\n    pass").body[0]
    extra_surface_sources = (
        "def __new__(cls, /):\n    pass",
        "def __new__(cls, byte_count):\n    pass",
        "def __new__(cls, *extra):\n    pass",
        "def __new__(cls, *, extra):\n    pass",
        "def __new__(cls, *, extra=None):\n    pass",
        "def __new__(cls, **extra):\n    pass",
        "def __new__(cls=None):\n    pass",
        "def __new__(cls: object):\n    pass",
        "def __new__(cls) -> object:\n    pass",
        "def __new__[T](cls):\n    pass",
        "@staticmethod\ndef __new__(cls):\n    pass",
        (
            "def __new__(cls):\n"
            "    # type: (object) -> object\n"
            "    pass"
        ),
        (
            "def __new__(\n"
            "    cls,  # type: object\n"
            "):\n"
            "    pass"
        ),
    )
    mutants = tuple(
        ast.parse(source, type_comments=True).body[0]
        for source in extra_surface_sources
    )

    assert isinstance(exact, ast.FunctionDef)
    assert all(isinstance(mutant, ast.FunctionDef) for mutant in mutants)
    assert _broker_native_core_iocp_successful_zero_byte_write_result_constructor_signature_is_exact(
        exact
    )
    assert all(
        not _broker_native_core_iocp_successful_zero_byte_write_result_constructor_signature_is_exact(
            mutant
        )
        for mutant in mutants
    )


