def test_broker_native_core_iocp_cancel_io_ex_accepted_call_result_facts_pin_partial_acceptance_without_retirement_or_classifier_authority() -> None:
    registry = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftIocpCancelIoExAcceptedCallResultFactsRegistry"
    ]()
    rows = tuple(
        dict(
            zip(
                registry.accepted_call_result_field_names,
                row,
                strict=True,
            )
        )
        for row in registry.accepted_call_result_rows
    )

    assert tuple(row["request_target_state"] for row in rows) == (
        "LIVE_AWAIT_PACKET",
        "LIVE_AWAIT_PACKET",
    )
    assert tuple(row["request_target_scope"] for row in rows) == (
        "every-live-operation",
        "every-live-operation",
    )
    assert tuple(row["call_result_match"] for row in rows) == (
        "Success",
        "FALSE/ERROR_NOT_FOUND",
    )
    assert tuple(row["accepted"] for row in rows) == (True, True)
    assert tuple(row["retires_operation"] for row in rows) == (False, False)
    assert len(rows) == 2
    assert not any("any-other" in row["call_result_match"] for row in rows)
    assert not any("terminal" in row["call_result_match"] for row in rows)
    assert not hasattr(registry, "classify")
    assert not hasattr(registry, "retire")


