def test_broker_native_core_iocp_cancel_io_ex_accepted_call_result_facts_registry_is_zero_arg_immutable_and_bounded() -> None:
    registry_type = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftIocpCancelIoExAcceptedCallResultFactsRegistry"
    ]
    registry = registry_type()
    expected_summary = (
        "_C6BrokerNativeCoreDraftIocpCancelIoExAcceptedCallResultFactsRegistry("
        "identity_row_count=1, accepted_call_result_field_count=5, "
        "accepted_call_result_row_count=2, invariant_count=6)"
    )

    assert tuple(inspect.signature(registry_type.__new__).parameters) == ("cls",)
    assert tuple(inspect.signature(registry_type).parameters) == ()
    assert tuple(
        name
        for name, value in vars(registry_type).items()
        if isinstance(value, property)
    ) == (
        "identity_table",
        "accepted_call_result_field_names",
        "accepted_call_result_rows",
        "invariants",
    )
    assert repr(registry) == expected_summary
    assert str(registry) == expected_summary
    assert len(expected_summary) < 240
    assert not hasattr(registry, "__dict__")
    for arguments in ((None,), (("Success",),), (object(), object())):
        with pytest.raises(TypeError):
            registry_type(*arguments)
    for keyword in (
        "handle",
        "overlapped",
        "result",
        "role",
        "selector",
        "classifier",
        "consumer",
        "digest",
    ):
        with pytest.raises(TypeError):
            registry_type(**{keyword: object()})
    for property_name in (
        "identity_table",
        "accepted_call_result_field_names",
        "accepted_call_result_rows",
        "invariants",
    ):
        with pytest.raises(AttributeError):
            setattr(registry, property_name, ())
    with pytest.raises(TypeError):
        registry[0] = ()

    class _RegistrySubclass(registry_type):
        pass

    with pytest.raises(RuntimeError) as rejection:
        _RegistrySubclass()
    assert rejection.type is RuntimeError
    assert rejection.value.args == ("GUARDED_BOOTSTRAP_INVALID",)


def test_broker_native_core_iocp_cancel_io_ex_accepted_call_result_facts_registry_is_module_dependency_free() -> None:
    namespace = _load_broker_native_core_draft()
    registry_type = namespace[
        "_C6BrokerNativeCoreDraftIocpCancelIoExAcceptedCallResultFactsRegistry"
    ]
    calls: list[str] = []

    class _ForbiddenModule:
        def __getattribute__(self, name: str) -> object:
            if name.startswith("__"):
                return object.__getattribute__(self, name)
            calls.append(name)
            raise AssertionError("IOCP cancellation facts used a module")

    originals = {
        module_name: namespace[module_name]
        for module_name in ("json", "hashlib", "os", "sys")
    }
    namespace.update(
        {module_name: _ForbiddenModule() for module_name in originals}
    )
    try:
        registry = registry_type()
    finally:
        namespace.update(originals)

    assert tuple(registry) == (
        _BROKER_NATIVE_CORE_DRAFT_IOCP_CANCEL_IO_EX_ACCEPTED_CALL_RESULT_IDENTITY_TABLE,
        _BROKER_NATIVE_CORE_DRAFT_IOCP_CANCEL_IO_EX_ACCEPTED_CALL_RESULT_FIELD_NAMES,
        _BROKER_NATIVE_CORE_DRAFT_IOCP_CANCEL_IO_EX_ACCEPTED_CALL_RESULT_ROWS,
        _BROKER_NATIVE_CORE_DRAFT_IOCP_CANCEL_IO_EX_ACCEPTED_CALL_RESULT_INVARIANTS,
    )
    assert calls == []


