@pytest.mark.parametrize(
    "mutation",
    _BROKER_NATIVE_CORE_DRAFT_IOCP_CLEANUP_COMPLETION_MUTATIONS,
)
def test_broker_native_core_iocp_cleanup_completion_facts_ast_contract_rejects_causal_mutants(
    mutation: str,
) -> None:
    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    mutated_source = _broker_native_core_iocp_cleanup_completion_mutant(mutation)
    findings = _broker_native_core_forbidden_ast_capability_calls(mutated_source)
    class_name = "_C6BrokerNativeCoreDraftIocpCleanupCompletionFactsRegistry"
    original_tree = ast.parse(source)
    mutated_tree = ast.parse(mutated_source)
    original_class = next(
        node
        for node in original_tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )
    mutated_class = next(
        node
        for node in mutated_tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )

    def literal_contract(class_node: ast.ClassDef) -> tuple[object, ...]:
        class_new = next(
            node
            for node in class_node.body
            if isinstance(node, ast.FunctionDef) and node.name == "__new__"
        )
        literal_assignments = {
            node.targets[0].id: node.value
            for node in class_new.body
            if isinstance(node, ast.Assign)
            and len(node.targets) == 1
            and isinstance(node.targets[0], ast.Name)
            and node.targets[0].id
            in {
                "identity_table",
                "cleanup_completion_field_names",
                "cleanup_completion_rows",
                "invariants",
            }
        }
        return tuple(
            ast.literal_eval(literal_assignments[name])
            for name in (
                "identity_table",
                "cleanup_completion_field_names",
                "cleanup_completion_rows",
                "invariants",
            )
        )

    original_contract = literal_contract(original_class)
    mutated_contract = literal_contract(mutated_class)
    expected_original = (
        _BROKER_NATIVE_CORE_DRAFT_IOCP_CLEANUP_COMPLETION_IDENTITY_TABLE,
        _BROKER_NATIVE_CORE_DRAFT_IOCP_CLEANUP_COMPLETION_FIELD_NAMES,
        _BROKER_NATIVE_CORE_DRAFT_IOCP_CLEANUP_COMPLETION_ROWS,
        _BROKER_NATIVE_CORE_DRAFT_IOCP_CLEANUP_COMPLETION_INVARIANTS,
    )
    expected_mutated = (
        _broker_native_core_iocp_cleanup_completion_expected_mutant_contract(
            mutation
        )
    )

    assert original_contract == expected_original
    assert mutated_contract == expected_mutated
    assert mutated_source != source
    assert "structure:module-contract" in findings

    literal_mutations = set(
        _BROKER_NATIVE_CORE_DRAFT_IOCP_CLEANUP_COMPLETION_MUTATIONS[:54]
    )
    module_only_mutations = {
        "iocp-cleanup-singleton-introduction",
        "iocp-cleanup-selector-introduction",
    }
    if mutation in module_only_mutations:
        assert ast.dump(original_class, include_attributes=False) == ast.dump(
            mutated_class,
            include_attributes=False,
        )
    else:
        assert ast.dump(original_class, include_attributes=False) != ast.dump(
            mutated_class,
            include_attributes=False,
        )
        assert f"structure:approved-body-contract:{class_name}" in findings
    if mutation in literal_mutations:
        assert mutated_contract != original_contract
    else:
        assert mutated_contract == original_contract

    original_new = next(
        node
        for node in original_class.body
        if isinstance(node, ast.FunctionDef) and node.name == "__new__"
    )
    mutated_new = next(
        node
        for node in mutated_class.body
        if isinstance(node, ast.FunctionDef) and node.name == "__new__"
    )
    assert _broker_native_core_iocp_cleanup_completion_constructor_signature_is_exact(
        original_new
    )
    if mutation == "iocp-cleanup-caller-parameter":
        assert tuple(argument.arg for argument in mutated_new.args.args) == (
            "cls",
            "packet",
        )
        assert not _broker_native_core_iocp_cleanup_completion_constructor_signature_is_exact(
            mutated_new
        )
    elif mutation == "iocp-cleanup-singleton-introduction":
        singleton_name = (
            "_C6_BROKER_NATIVE_CORE_DRAFT_IOCP_CLEANUP_COMPLETION_FACTS_REGISTRY"
        )
        singleton_assignments = tuple(
            node
            for node in mutated_tree.body
            if isinstance(node, ast.Assign)
            and len(node.targets) == 1
            and isinstance(node.targets[0], ast.Name)
            and node.targets[0].id == singleton_name
        )
        assert len(singleton_assignments) == 1
        assert _broker_native_core_iocp_cleanup_completion_exact_zero_arg_constructor_call(
            singleton_assignments[0].value
        )
    elif mutation == "iocp-cleanup-selector-introduction":
        selector_name = (
            "_c6_broker_native_core_draft_select_iocp_cleanup_completion_facts"
        )
        selectors = tuple(
            node
            for node in mutated_tree.body
            if isinstance(node, ast.FunctionDef) and node.name == selector_name
        )
        assert len(selectors) == 1
        assert _broker_native_core_iocp_cleanup_completion_exact_selector(selectors[0])
        assert f"structure:unregistered-definition:{selector_name}" in findings

    method_sources = {
        "iocp-cleanup-classifier-introduction": "def classify_cleanup_completion(self):\n    return None",
        "iocp-cleanup-consumer-introduction": "def consume_cleanup_packet(self):\n    return None",
        "iocp-cleanup-retirer-introduction": "def retire_cleanup_operation(self):\n    return None",
        "iocp-cleanup-role-mapper-introduction": "def map_raw_role_to_terminal_permission(self, raw_role):\n    return raw_role",
        "iocp-cleanup-accepted-call-result-dependency": "def require_accepted_cancel_io_ex_result(self):\n    return True",
        "iocp-cleanup-cancellation-causation": "def assert_cancellation_caused_packet(self):\n    return True",
        "iocp-cleanup-zero-write-success-authority": "def classify_successful_zero_byte_write_as_success(self):\n    return True",
        "iocp-cleanup-partial-full-write-semantics": "def continue_partial_or_full_write(self):\n    return None",
        "iocp-cleanup-grace-quarantine-publication": "def publish_after_grace_quarantine(self):\n    return ('grace', 'quarantine', 'publication')",
        "iocp-cleanup-runtime-wiring": "def wire_cleanup_runtime(self, packet):\n    return packet",
        "iocp-cleanup-helper-factory-introduction": "def make_cleanup_helper_factory(self):\n    return None",
    }
    if mutation in method_sources:
        expected_method = ast.parse(method_sources[mutation]).body[0]
        matching_methods = tuple(
            node
            for node in mutated_class.body
            if isinstance(node, ast.FunctionDef)
            and node.name == expected_method.name
        )
        assert len(matching_methods) == 1
        assert ast.dump(
            matching_methods[0], include_attributes=False
        ) == ast.dump(expected_method, include_attributes=False)

    assignment_expectations: dict[str, tuple[str, object]] = {
        "iocp-cleanup-raw-role-mapping": (
            "raw_role_mapping",
            {"stdout": "read-terminal"},
        ),
        "iocp-cleanup-digest-canonical-authority": (
            "published_authority",
            ("caller-digest", b"canonical-bytes"),
        ),
        "iocp-cleanup-raw-runtime-bindings": (
            "raw_runtime_bindings",
            (1168, 995, 109, 1, 2, 4096, {"stdout": 4096}),
        ),
        "iocp-cleanup-activation-marker": (
            "activation_marker",
            "C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN",
        ),
    }
    if mutation in assignment_expectations:
        expected_name, expected_value = assignment_expectations[mutation]
        matching_assignments = tuple(
            node
            for node in mutated_new.body
            if isinstance(node, ast.Assign)
            and len(node.targets) == 1
            and isinstance(node.targets[0], ast.Name)
            and node.targets[0].id == expected_name
        )
        assert len(matching_assignments) == 1
        assert ast.literal_eval(matching_assignments[0].value) == expected_value

    expected_call_names = {
        "iocp-cleanup-dispatch-error-calls": (
            "GetQueuedCompletionStatus",
            "GetLastError",
        ),
        "iocp-cleanup-read-write-calls": ("ReadFile", "WriteFile"),
        "iocp-cleanup-cancel-close-calls": ("CancelIoEx", "CloseHandle"),
    }
    if mutation in expected_call_names:
        actual_call_names = tuple(
            node.func.id
            for node in ast.walk(mutated_new)
            if isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id in expected_call_names[mutation]
            and node.args == []
            and node.keywords == []
        )
        assert set(actual_call_names) == set(expected_call_names[mutation])
        assert len(actual_call_names) == len(expected_call_names[mutation])


