def _broker_native_core_iocp_writer_close_eligibility_exact_selector(
    node: ast.AST | None,
) -> bool:
    if not isinstance(node, ast.FunctionDef):
        return False
    arguments = node.args
    return (
        node.name
        == "_c6_broker_native_core_draft_select_iocp_writer_close_eligibility_facts"
        and node.decorator_list == []
        and node.type_comment is None
        and arguments.posonlyargs == []
        and arguments.args == []
        and arguments.vararg is None
        and arguments.kwonlyargs == []
        and arguments.kw_defaults == []
        and arguments.kwarg is None
        and arguments.defaults == []
        and node.returns is None
        and node.type_params == []
        and len(node.body) == 1
        and isinstance(node.body[0], ast.Return)
        and _broker_native_core_iocp_writer_close_eligibility_exact_zero_arg_constructor_call(
            node.body[0].value
        )
    )


def test_broker_native_core_iocp_writer_close_eligibility_signature_call_and_selector_oracles_reject_extra_surface() -> None:
    exact_new = ast.parse("def __new__(cls):\n    pass").body[0]
    malformed_new_sources = (
        "def __new__(cls, /):\n    pass",
        "def __new__(cls, writer):\n    pass",
        "def __new__(cls, *extra):\n    pass",
        "def __new__(cls, *, extra):\n    pass",
        "def __new__(cls, **extra):\n    pass",
        "def __new__(cls=None):\n    pass",
        "def __new__(cls: object):\n    pass",
        "def __new__(cls) -> object:\n    pass",
        "def __new__[T](cls):\n    pass",
        "@staticmethod\ndef __new__(cls):\n    pass",
    )
    malformed_news = tuple(
        ast.parse(value, type_comments=True).body[0]
        for value in malformed_new_sources
    )
    assert isinstance(exact_new, ast.FunctionDef)
    assert _broker_native_core_iocp_writer_close_eligibility_constructor_signature_is_exact(
        exact_new
    )
    assert all(
        isinstance(value, ast.FunctionDef)
        and not _broker_native_core_iocp_writer_close_eligibility_constructor_signature_is_exact(
            value
        )
        for value in malformed_news
    )

    class_name = (
        "_C6BrokerNativeCoreDraftIocpWriterCloseEligibilityFactsRegistry"
    )
    selector_name = (
        "_c6_broker_native_core_draft_select_iocp_writer_close_eligibility_facts"
    )
    exact_call = ast.parse(f"{class_name}()").body[0]
    assert isinstance(exact_call, ast.Expr)
    malformed_calls = (
        None,
        ast.parse("WrongRegistry()").body[0].value,
        ast.parse(f"{class_name}(1)").body[0].value,
        ast.parse(f"{class_name}(writer=1)").body[0].value,
        ast.parse(f"owner.{class_name}()").body[0].value,
    )
    assert _broker_native_core_iocp_writer_close_eligibility_exact_zero_arg_constructor_call(
        exact_call.value
    )
    assert all(
        not _broker_native_core_iocp_writer_close_eligibility_exact_zero_arg_constructor_call(
            value
        )
        for value in malformed_calls
    )
    exact_selector = ast.parse(
        f"def {selector_name}():\n    return {class_name}()"
    ).body[0]
    malformed_selector_sources = (
        f"@staticmethod\ndef {selector_name}():\n    return {class_name}()",
        f"def {selector_name}(writer):\n    return {class_name}()",
        f"def {selector_name}(*extra):\n    return {class_name}()",
        f"def {selector_name}(**extra):\n    return {class_name}()",
        f"def {selector_name}() -> object:\n    return {class_name}()",
        f"def {selector_name}[T]():\n    return {class_name}()",
        f"def {selector_name}():\n    pass\n    return {class_name}()",
        f"def {selector_name}():\n    return {class_name}(1)",
        f"def wrong_selector():\n    return {class_name}()",
    )
    malformed_selectors = tuple(
        ast.parse(value, type_comments=True).body[0]
        for value in malformed_selector_sources
    )
    assert _broker_native_core_iocp_writer_close_eligibility_exact_selector(
        exact_selector
    )
    assert all(
        not _broker_native_core_iocp_writer_close_eligibility_exact_selector(value)
        for value in malformed_selectors
    )


