def test_broker_native_core_iocp_failure_grace_activity_and_canceled_stdio_rules_are_exact_and_bounded() -> None:
    registry = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftIocpFailureGraceFactsRegistry"
    ]()
    activity_fields, activity_literal_rows = registry.grace_activity_table
    activity_rows = tuple(
        dict(zip(activity_fields, row, strict=True))
        for row in activity_literal_rows
    )
    canceled_fields, canceled_literal_rows = registry.canceled_stdio_read_rule
    canceled_rows = tuple(
        dict(zip(canceled_fields, row, strict=True))
        for row in canceled_literal_rows
    )

    assert tuple(row["grace_activity"] for row in activity_rows) == (
        "dispatch-result-processing",
        "process-handle-polling",
        "Job-accounting-polling",
    )
    assert tuple(row["required_mode"] for row in activity_rows) == (
        "classify-and-reconcile",
        "nonblocking-query",
        "nonblocking-query",
    )
    assert canceled_rows == (
        {
            "operation_scope": "stdout-or-stderr-ReadFile",
            "completion_result_match": "ERROR_OPERATION_ABORTED",
            "accepted_cleanup_completion": True,
            "retires_operation": True,
            "recorded_stdio_outcome": "not-EOF",
        },
    )
    assert len(activity_rows) == 3
    assert len(canceled_rows) == 1
    for forbidden_attribute in (
        "dispatch",
        "consume",
        "poll",
        "wait",
        "close",
        "quarantine",
        "publish",
    ):
        assert not hasattr(registry, forbidden_attribute)


