def _broker_native_core_iocp_grace_expiry_quarantine_python_tuple_mutation(
    value: tuple[object, ...],
    path: tuple[int, ...],
    index: int,
    operation: str,
    payload: object,
) -> tuple[object, ...]:
    values = list(value)
    if path:
        nested = values[path[0]]
        assert type(nested) is tuple
        values[path[0]] = (
            _broker_native_core_iocp_grace_expiry_quarantine_python_tuple_mutation(
                nested,
                path[1:],
                index,
                operation,
                payload,
            )
        )
    elif operation == "replace":
        values[index] = payload
    elif operation == "delete":
        del values[index]
    else:
        assert operation == "swap" and type(payload) is int
        values[index], values[payload] = values[payload], values[index]
    return tuple(values)


