def test_broker_native_core_iocp_success_convergence_cross_binds_authoritative_iocp_job_and_pipe_facts_without_runtime_authority() -> None:
    namespace = _load_broker_native_core_draft()
    registry = namespace[
        "_C6BrokerNativeCoreDraftIocpSuccessConvergenceFactsRegistry"
    ]()
    gate_fields, gate_literal_rows = registry.authoritative_gate_table
    gates = {
        row[0]: dict(zip(gate_fields, row, strict=True))
        for row in gate_literal_rows
    }
    reconciled = namespace[
        "_C6BrokerNativeCoreDraftIocpGraceReconciledCloseOrderFactsRegistry"
    ]()
    reconciliation_rows = {
        row[0]: row[1]
        for row in reconciled.reconciliation_precondition_table[1]
    }
    dispatch = namespace[
        "_C6BrokerNativeCoreDraftIocpDispatchResultFactsRegistry"
    ]()
    zero_write = namespace[
        "_C6BrokerNativeCoreDraftIocpSuccessfulZeroByteWriteResultFactsRegistry"
    ]()
    applicability = namespace[
        "_C6BrokerNativeCoreDraftInternalChannelApplicabilityRegistry"
    ]()
    job_topology = namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_REGISTRY"
    ]
    applicable_roles = tuple(
        dict.fromkeys(role for row in applicability.rows for role in row[3])
    )

    assert gates["retained-process-terminal-state"][
        "required_evidence_match"
    ] == reconciliation_rows["retained-process-handles"]
    assert gates["outstanding-I/O"][
        "required_evidence_match"
    ] == reconciliation_rows["operation-ledger"]
    job_evidence = reconciliation_rows["every-applicable-owned-Job"]
    for gate_name in (
        "owned-Job-active-process-accounting",
        "owned-Job-final-process-ID-membership",
        "owned-Job-total-process-accounting",
    ):
        assert gates[gate_name]["required_evidence_match"] in job_evidence
    assert dispatch.result_rows[0][-1] == "advisory-Job-notification"
    assert (
        "Job-completion-port-notifications-are-advisory-and-never-mandatory-success-gates"
        in dispatch.invariants
    )
    assert "successful-zero-byte-write-is-failure" in zero_write.invariants
    assert applicable_roles == (
        "descriptor",
        "ack-status",
        "go",
        "broker-request",
        "broker-response",
        "stdin",
        "stdout",
        "stderr",
    )
    assert tuple(row[0] for row in job_topology.rows) == (
        "root-broker",
        "standalone-native-leaf",
        "initial-guarded-target",
        "nested-guarded-target",
        "broker-native-leaf",
        "codex-client-root",
        "codex-client-descendant",
    )
    assert (
        "failure-sequence-step-6-reconciliation-or-step-7-expiry-cleanup-never-satisfies-overall-success-convergence"
        in registry.invariants
    )


def test_broker_native_core_iocp_success_convergence_registry_is_zero_arg_immutable_module_free_and_bounded() -> None:
    namespace = _load_broker_native_core_draft()
    registry_type = namespace[
        "_C6BrokerNativeCoreDraftIocpSuccessConvergenceFactsRegistry"
    ]
    registry = registry_type()
    expected_summary = (
        "_C6BrokerNativeCoreDraftIocpSuccessConvergenceFactsRegistry("
        "identity_row_count=1, authoritative_gate_row_count=8, "
        "advisory_job_notification_row_count=4, "
        "mismatch_disposition_row_count=3, invariant_count=19)"
    )

    assert tuple(inspect.signature(registry_type.__new__).parameters) == ("cls",)
    assert tuple(inspect.signature(registry_type).parameters) == ()
    assert tuple(
        name
        for name, value in vars(registry_type).items()
        if isinstance(value, property)
    ) == (
        "identity_table",
        "authoritative_gate_table",
        "advisory_job_notification_table",
        "mismatch_disposition_table",
        "invariants",
    )
    assert repr(registry) == expected_summary
    assert str(registry) == expected_summary
    assert len(expected_summary) < 280
    assert not hasattr(registry, "__dict__")
    for arguments in ((None,), ((1,),), (object(), object())):
        with pytest.raises(TypeError):
            registry_type(*arguments)
    for keyword in (
        "processes",
        "jobs",
        "frames",
        "eofs",
        "ledger",
        "notifications",
        "deadline",
    ):
        with pytest.raises(TypeError):
            registry_type(**{keyword: object()})
    for property_name in (
        "identity_table",
        "authoritative_gate_table",
        "advisory_job_notification_table",
        "mismatch_disposition_table",
        "invariants",
    ):
        with pytest.raises(AttributeError):
            setattr(registry, property_name, ())
    with pytest.raises(TypeError):
        registry[0] = ()

    class _RegistrySubclass(registry_type):
        pass

    with pytest.raises(RuntimeError) as rejection:
        _RegistrySubclass()
    assert rejection.type is RuntimeError
    assert rejection.value.args == ("GUARDED_BOOTSTRAP_INVALID",)

    calls: list[str] = []

    class _ForbiddenModule:
        def __getattribute__(self, name: str) -> object:
            if name.startswith("__"):
                return object.__getattribute__(self, name)
            calls.append(name)
            raise AssertionError("success-convergence facts used a module")

    originals = {
        module_name: namespace[module_name]
        for module_name in ("json", "hashlib", "os", "sys")
    }
    namespace.update(
        {module_name: _ForbiddenModule() for module_name in originals}
    )
    try:
        poisoned_registry = registry_type()
    finally:
        namespace.update(originals)
    assert tuple(poisoned_registry) == tuple(registry)
    assert calls == []


def test_broker_native_core_iocp_success_convergence_facts_are_class_only_and_dormant() -> None:
    namespace = _load_broker_native_core_draft()
    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    class_name = "_C6BrokerNativeCoreDraftIocpSuccessConvergenceFactsRegistry"
    class_nodes = tuple(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )

    assert len(class_nodes) == 1
    class_node = class_nodes[0]
    assert tuple(
        member.name
        for member in class_node.body
        if isinstance(member, ast.FunctionDef)
    ) == (
        "__new__",
        "identity_table",
        "authoritative_gate_table",
        "advisory_job_notification_table",
        "mismatch_disposition_table",
        "invariants",
        "__repr__",
    )
    class_order = tuple(
        node.name for node in tree.body if isinstance(node, ast.ClassDef)
    )
    assert class_order.index(class_name) == (
        class_order.index(
            "_C6BrokerNativeCoreDraftIocpGraceExpiryQuarantineFactsRegistry"
        )
        + 1
    )
    assert class_order.index(class_name) < class_order.index(
        "_C6BrokerNativeCoreDraftIocpWaitWindow"
    )
    parents = {
        child: node
        for node in ast.walk(tree)
        for child in ast.iter_child_nodes(node)
    }
    class_loads = tuple(
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Name)
        and isinstance(node.ctx, ast.Load)
        and node.id == class_name
    )
    assert len(class_loads) == 1
    class_guard = parents[class_loads[0]]
    assert isinstance(class_guard, ast.Compare)
    assert isinstance(class_guard.left, ast.Name)
    assert class_guard.left.id == "cls"
    assert len(class_guard.ops) == 1
    assert isinstance(class_guard.ops[0], ast.IsNot)
    assert class_guard.comparators == [class_loads[0]]
    assert not any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == class_name
        for node in ast.walk(tree)
    )
    assert not any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id
        in {
            "WaitForSingleObject",
            "GetExitCodeProcess",
            "QueryInformationJobObject",
            "GetQueuedCompletionStatus",
            "ReadFile",
            "WriteFile",
            "CloseHandle",
            "TerminateJobObject",
            "CancelIoEx",
        }
        for node in ast.walk(class_node)
    )
    assert not any(
        name != class_name and "IOCP_SUCCESS_CONVERGENCE" in name.upper()
        for name in namespace
    )
    assert tuple(
        (alias.name, alias.asname)
        for node in tree.body
        if isinstance(node, ast.Import)
        for alias in node.names
    ) == (
        ("hashlib", None),
        ("json", None),
        ("os", None),
        ("sys", None),
    )
    assert not BOOTSTRAP_PATH.with_name(
        "complete_suite_control_plane.ps1"
    ).exists()
    for marker in (
        "C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN",
        "C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END",
    ):
        assert marker not in source


def _broker_native_core_iocp_success_convergence_constructor_signature_is_exact(
    function: ast.FunctionDef,
) -> bool:
    arguments = function.args
    all_arguments = (
        *arguments.posonlyargs,
        *arguments.args,
        *arguments.kwonlyargs,
    )
    return (
        function.name == "__new__"
        and function.decorator_list == []
        and function.type_comment is None
        and arguments.posonlyargs == []
        and tuple(argument.arg for argument in arguments.args) == ("cls",)
        and arguments.vararg is None
        and arguments.kwonlyargs == []
        and arguments.kw_defaults == []
        and arguments.kwarg is None
        and arguments.defaults == []
        and all(
            argument.annotation is None and argument.type_comment is None
            for argument in all_arguments
        )
        and function.returns is None
        and function.type_params == []
    )


def _broker_native_core_iocp_success_convergence_exact_zero_arg_constructor_call(
    node: ast.AST | None,
) -> bool:
    return (
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id
        == "_C6BrokerNativeCoreDraftIocpSuccessConvergenceFactsRegistry"
        and node.args == []
        and node.keywords == []
    )


def _broker_native_core_iocp_success_convergence_exact_selector(
    node: ast.AST | None,
) -> bool:
    if not isinstance(node, ast.FunctionDef):
        return False
    arguments = node.args
    return (
        node.name
        == "_c6_broker_native_core_draft_select_iocp_success_convergence_facts"
        and node.decorator_list == []
        and node.type_comment is None
        and arguments.posonlyargs == []
        and arguments.args == []
        and arguments.vararg is None
        and arguments.kwonlyargs == []
        and arguments.kw_defaults == []
        and arguments.kwarg is None
        and arguments.defaults == []
        and node.returns is None
        and node.type_params == []
        and len(node.body) == 1
        and isinstance(node.body[0], ast.Return)
        and _broker_native_core_iocp_success_convergence_exact_zero_arg_constructor_call(
            node.body[0].value
        )
    )


def test_broker_native_core_iocp_success_convergence_signature_call_and_selector_oracles_reject_extra_surface() -> None:
    exact_new = ast.parse("def __new__(cls):\n    pass").body[0]
    malformed_new_sources = (
        "def __new__(cls, /):\n    pass",
        "def __new__(cls, ledger):\n    pass",
        "def __new__(cls, *extra):\n    pass",
        "def __new__(cls, *, extra):\n    pass",
        "def __new__(cls, **extra):\n    pass",
        "def __new__(cls=None):\n    pass",
        "def __new__(cls: object):\n    pass",
        "def __new__(cls) -> object:\n    pass",
        "def __new__[T](cls):\n    pass",
        "@staticmethod\ndef __new__(cls):\n    pass",
    )
    malformed_news = tuple(
        ast.parse(value, type_comments=True).body[0]
        for value in malformed_new_sources
    )
    assert isinstance(exact_new, ast.FunctionDef)
    assert _broker_native_core_iocp_success_convergence_constructor_signature_is_exact(
        exact_new
    )
    assert all(
        isinstance(value, ast.FunctionDef)
        and not _broker_native_core_iocp_success_convergence_constructor_signature_is_exact(
            value
        )
        for value in malformed_news
    )

    class_name = "_C6BrokerNativeCoreDraftIocpSuccessConvergenceFactsRegistry"
    selector_name = (
        "_c6_broker_native_core_draft_select_iocp_success_convergence_facts"
    )
    exact_call = ast.parse(f"{class_name}()").body[0]
    assert isinstance(exact_call, ast.Expr)
    malformed_calls = (
        None,
        ast.parse("WrongRegistry()").body[0].value,
        ast.parse(f"{class_name}(1)").body[0].value,
        ast.parse(f"{class_name}(ledger=1)").body[0].value,
        ast.parse(f"owner.{class_name}()").body[0].value,
    )
    assert _broker_native_core_iocp_success_convergence_exact_zero_arg_constructor_call(
        exact_call.value
    )
    assert all(
        not _broker_native_core_iocp_success_convergence_exact_zero_arg_constructor_call(
            value
        )
        for value in malformed_calls
    )
    exact_selector = ast.parse(
        f"def {selector_name}():\n    return {class_name}()"
    ).body[0]
    malformed_selector_sources = (
        f"@staticmethod\ndef {selector_name}():\n    return {class_name}()",
        f"def {selector_name}(ledger):\n    return {class_name}()",
        f"def {selector_name}(*extra):\n    return {class_name}()",
        f"def {selector_name}(**extra):\n    return {class_name}()",
        f"def {selector_name}() -> object:\n    return {class_name}()",
        f"def {selector_name}[T]():\n    return {class_name}()",
        f"def {selector_name}():\n    pass\n    return {class_name}()",
        f"def {selector_name}():\n    return {class_name}(1)",
        f"def wrong_selector():\n    return {class_name}()",
    )
    malformed_selectors = tuple(
        ast.parse(value, type_comments=True).body[0]
        for value in malformed_selector_sources
    )
    assert _broker_native_core_iocp_success_convergence_exact_selector(
        exact_selector
    )
    assert all(
        not _broker_native_core_iocp_success_convergence_exact_selector(value)
        for value in malformed_selectors
    )


def test_broker_native_core_iocp_success_convergence_ast_contract_accepts_exact_fixed_class_hash() -> None:
    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    class_node = next(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef)
        and node.name
        == "_C6BrokerNativeCoreDraftIocpSuccessConvergenceFactsRegistry"
    )
    constructor = next(
        node
        for node in class_node.body
        if isinstance(node, ast.FunctionDef) and node.name == "__new__"
    )
    fingerprint = sha256(
        ast.dump(class_node, include_attributes=False).encode("utf-8")
    ).hexdigest()

    assert fingerprint == (
        _BROKER_NATIVE_CORE_DRAFT_IOCP_SUCCESS_CONVERGENCE_CLASS_FINGERPRINT
    )
    assert _broker_native_core_iocp_success_convergence_constructor_signature_is_exact(
        constructor
    )
    assert _broker_native_core_forbidden_ast_capability_calls(source) == frozenset()


