def _broker_native_core_iocp_success_convergence_ast_tuple_at(
    root: ast.AST,
    path: tuple[int, ...],
) -> ast.Tuple:
    node = root
    for index in path:
        assert isinstance(node, ast.Tuple)
        node = node.elts[index]
    assert isinstance(node, ast.Tuple)
    return node


def _broker_native_core_iocp_success_convergence_mutant(
    mutation: str,
) -> str:
    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    class_name = (
        "_C6BrokerNativeCoreDraftIocpSuccessConvergenceFactsRegistry"
    )
    registry_class = next(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )
    registry_new = next(
        node
        for node in registry_class.body
        if isinstance(node, ast.FunctionDef) and node.name == "__new__"
    )
    assignments = {
        node.targets[0].id: node.value
        for node in registry_new.body
        if isinstance(node, ast.Assign)
        and len(node.targets) == 1
        and isinstance(node.targets[0], ast.Name)
    }
    replacement_specs = {
        spec[0]: spec[1:]
        for spec in _BROKER_NATIVE_CORE_DRAFT_IOCP_SUCCESS_CONVERGENCE_LITERAL_REPLACEMENT_SPECS
    }
    sequence_specs = {
        spec[0]: spec[1:]
        for spec in _BROKER_NATIVE_CORE_DRAFT_IOCP_SUCCESS_CONVERGENCE_LITERAL_SEQUENCE_SPECS
    }
    assert mutation in _BROKER_NATIVE_CORE_DRAFT_IOCP_SUCCESS_CONVERGENCE_MUTATIONS

    if mutation in replacement_specs:
        assignment_name, path, index, replacement = replacement_specs[mutation]
        target = _broker_native_core_iocp_success_convergence_ast_tuple_at(
            assignments[assignment_name], path
        )
        target.elts[index] = ast.Constant(value=replacement)
    elif mutation in sequence_specs:
        assignment_name, path, index, operation, payload = sequence_specs[mutation]
        target = _broker_native_core_iocp_success_convergence_ast_tuple_at(
            assignments[assignment_name], path
        )
        if operation == "delete":
            del target.elts[index]
        else:
            assert operation == "swap" and type(payload) is int
            target.elts[index], target.elts[payload] = (
                target.elts[payload],
                target.elts[index],
            )
    elif mutation == "success-convergence-caller-parameter":
        registry_new.args.args.append(ast.arg(arg="evidence"))
    elif mutation == "success-convergence-singleton-introduction":
        tree.body.append(
            ast.parse(
                "_C6_BROKER_NATIVE_CORE_DRAFT_IOCP_SUCCESS_CONVERGENCE_FACTS_REGISTRY = "
                "_C6BrokerNativeCoreDraftIocpSuccessConvergenceFactsRegistry()"
            ).body[0]
        )
    elif mutation == "success-convergence-selector-introduction":
        tree.body.append(
            ast.parse(
                "def _c6_broker_native_core_draft_select_iocp_success_convergence_facts():\n"
                "    return _C6BrokerNativeCoreDraftIocpSuccessConvergenceFactsRegistry()"
            ).body[0]
        )
    elif mutation in (
        _BROKER_NATIVE_CORE_DRAFT_IOCP_SUCCESS_CONVERGENCE_METHOD_MUTATIONS
    ):
        registry_class.body.append(
            ast.parse(
                _BROKER_NATIVE_CORE_DRAFT_IOCP_SUCCESS_CONVERGENCE_METHOD_MUTATIONS[
                    mutation
                ]
            ).body[0]
        )
    elif mutation in (
        _BROKER_NATIVE_CORE_DRAFT_IOCP_SUCCESS_CONVERGENCE_CALL_MUTATIONS
    ):
        for call_name in _BROKER_NATIVE_CORE_DRAFT_IOCP_SUCCESS_CONVERGENCE_CALL_MUTATIONS[
            mutation
        ]:
            registry_new.body.insert(
                -1, ast.parse(f"{call_name}()").body[0]
            )
    else:
        assignment_name, assignment_value = (
            _BROKER_NATIVE_CORE_DRAFT_IOCP_SUCCESS_CONVERGENCE_ASSIGNMENT_MUTATIONS[
                mutation
            ]
        )
        registry_new.body.insert(
            -1,
            ast.Assign(
                targets=[ast.Name(id=assignment_name, ctx=ast.Store())],
                value=ast.parse(repr(assignment_value)).body[0].value,
            ),
        )

    ast.fix_missing_locations(tree)
    return ast.unparse(tree)


