def test_broker_native_core_constructor_control_frame_grammar_cross_binds_existing_role_wire_iocp_and_success_facts_without_runtime_authority() -> None:
    namespace = _load_broker_native_core_draft()
    registry = namespace[
        "_C6BrokerNativeCoreDraftConstructorControlFrameGrammarFactsRegistry"
    ]()
    token = "0123456789abcdef0123456789abcdef"
    address_type = namespace["_C6BrokerNativeCoreDraftInternalChannelAddress"]
    role_fields, role_literal_rows = registry.control_role_table
    for literal_row in role_literal_rows:
        role = dict(zip(role_fields, literal_row, strict=True))
        address = address_type(token, role["fixed_role"])
        assert (
            address.parent_action,
            address.server_open_mode,
            address.child_access,
        ) == (
            role["parent_action"],
            role["server_open_mode"],
            role["child_access"],
        )
    applicability = namespace[
        "_C6BrokerNativeCoreDraftInternalChannelApplicabilityRegistry"
    ]()
    assert registry.identity_table[1][0][3] == tuple(
        role
        for role in applicability.rows[0][3]
        if role in {"ack-status", "go"}
    )
    endpoint = namespace[
        "_C6BrokerNativeCoreDraftInternalChannelEndpointConstructionFactsRegistry"
    ]()
    assert endpoint.rows[0][-1] == "child-endpoint-only"
    assert (
        "parent-duplicate-of-child-endpoint-closed-immediately"
        in endpoint.successful_path_per_channel_phases
    )
    admission = namespace[
        "_C6BrokerNativeCoreDraftControlFrameAdmission"
    ](65_540, 65_536)
    assert tuple(admission) == (65_540, 65_536, 65_540)
    read_window = namespace[
        "_C6BrokerNativeCoreDraftWireReadWindow"
    ](65_540, 0)
    assert read_window.maximum_read_request_bytes == 65_536
    assert namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_CONTROL_FRAME_PAYLOAD_CAP_BYTES"
    ] == registry.frame_wire_rule_table[1][0][5]
    assert namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_ONE_CONTROL_FRAME_WIRE_BYTES"
    ] == registry.frame_wire_rule_table[1][0][6]
    assert namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_ORDINARY_ACK_STATUS_WIRE_BYTES"
    ] == 2 * registry.frame_wire_rule_table[1][0][6]
    assert namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_EXECUTE_ACK_STATUS_WIRE_BYTES"
    ] == 4 * registry.frame_wire_rule_table[1][0][6]
    issue = namespace[
        "_C6BrokerNativeCoreDraftIocpOperationIssueFactsRegistry"
    ]()
    assert issue.identity_table[1][0][2] == ("ReadFile", "WriteFile")
    convergence = namespace[
        "_C6BrokerNativeCoreDraftIocpSuccessConvergenceFactsRegistry"
    ]()
    convergence_gates = tuple(
        row[0] for row in convergence.authoritative_gate_table[1]
    )
    assert convergence_gates[-3:] == (
        "required-terminal-frames",
        "required-pipe-EOFs",
        "outstanding-I/O",
    )


def test_broker_native_core_constructor_control_frame_grammar_registry_is_zero_arg_immutable_module_free_and_bounded() -> None:
    namespace = _load_broker_native_core_draft()
    registry_type = namespace[
        "_C6BrokerNativeCoreDraftConstructorControlFrameGrammarFactsRegistry"
    ]
    registry = registry_type()
    expected_summary = (
        "_C6BrokerNativeCoreDraftConstructorControlFrameGrammarFactsRegistry("
        "identity_row_count=1, frame_wire_rule_row_count=1, "
        "control_role_row_count=2, grammar_row_count=6, "
        "ack_go_binding_row_count=2, invariant_count=23)"
    )

    assert tuple(inspect.signature(registry_type.__new__).parameters) == ("cls",)
    assert tuple(inspect.signature(registry_type).parameters) == ()
    assert tuple(
        name
        for name, value in vars(registry_type).items()
        if isinstance(value, property)
    ) == (
        "identity_table",
        "frame_wire_rule_table",
        "control_role_table",
        "grammar_table",
        "ack_go_binding_table",
        "invariants",
    )
    assert repr(registry) == expected_summary
    assert str(registry) == expected_summary
    assert len(expected_summary) < 320
    assert not hasattr(registry, "__dict__")
    for arguments in ((None,), ((1,),), (object(), object())):
        with pytest.raises(TypeError):
            registry_type(*arguments)
    for keyword in (
        "context",
        "frame",
        "payload",
        "authentication",
        "deadline",
        "ledger",
    ):
        with pytest.raises(TypeError):
            registry_type(**{keyword: object()})
    for property_name in (
        "identity_table",
        "frame_wire_rule_table",
        "control_role_table",
        "grammar_table",
        "ack_go_binding_table",
        "invariants",
    ):
        with pytest.raises(AttributeError):
            setattr(registry, property_name, ())
    with pytest.raises(TypeError):
        registry[0] = ()

    class _RegistrySubclass(registry_type):
        pass

    with pytest.raises(RuntimeError) as rejection:
        _RegistrySubclass()
    assert rejection.type is RuntimeError
    assert rejection.value.args == ("GUARDED_BOOTSTRAP_INVALID",)

    calls: list[str] = []

    class _ForbiddenModule:
        def __getattribute__(self, name: str) -> object:
            if name.startswith("__"):
                return object.__getattribute__(self, name)
            calls.append(name)
            raise AssertionError("constructor control grammar facts used a module")

    originals = {
        module_name: namespace[module_name]
        for module_name in ("json", "hashlib", "os", "sys")
    }
    namespace.update(
        {module_name: _ForbiddenModule() for module_name in originals}
    )
    try:
        poisoned_registry = registry_type()
    finally:
        namespace.update(originals)
    assert tuple(poisoned_registry) == tuple(registry)
    assert calls == []


def test_broker_native_core_constructor_control_frame_grammar_facts_are_class_only_and_dormant() -> None:
    namespace = _load_broker_native_core_draft()
    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    class_name = (
        "_C6BrokerNativeCoreDraftConstructorControlFrameGrammarFactsRegistry"
    )
    class_nodes = tuple(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )

    assert len(class_nodes) == 1
    class_node = class_nodes[0]
    assert tuple(
        member.name
        for member in class_node.body
        if isinstance(member, ast.FunctionDef)
    ) == (
        "__new__",
        "identity_table",
        "frame_wire_rule_table",
        "control_role_table",
        "grammar_table",
        "ack_go_binding_table",
        "invariants",
        "__repr__",
    )
    class_order = tuple(
        node.name for node in tree.body if isinstance(node, ast.ClassDef)
    )
    assert class_order.index(class_name) == (
        class_order.index(
            "_C6BrokerNativeCoreDraftIocpSuccessConvergenceFactsRegistry"
        )
        + 1
    )
    assert class_order.index(class_name) < class_order.index(
        "_C6BrokerNativeCoreDraftIocpWaitWindow"
    )
    parents = {
        child: node
        for node in ast.walk(tree)
        for child in ast.iter_child_nodes(node)
    }
    class_loads = tuple(
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Name)
        and isinstance(node.ctx, ast.Load)
        and node.id == class_name
    )
    assert len(class_loads) == 1
    class_guard = parents[class_loads[0]]
    assert isinstance(class_guard, ast.Compare)
    assert isinstance(class_guard.left, ast.Name)
    assert class_guard.left.id == "cls"
    assert len(class_guard.ops) == 1
    assert isinstance(class_guard.ops[0], ast.IsNot)
    assert class_guard.comparators == [class_loads[0]]
    assert not any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == class_name
        for node in ast.walk(tree)
    )
    assert not any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id
        in {
            "ReadFile",
            "WriteFile",
            "GetQueuedCompletionStatus",
            "CloseHandle",
            "TerminateJobObject",
            "CancelIoEx",
        }
        for node in ast.walk(class_node)
    )
    assert not any(
        name != class_name and "CONSTRUCTOR_CONTROL_FRAME_GRAMMAR" in name.upper()
        for name in namespace
    )
    assert tuple(
        (alias.name, alias.asname)
        for node in tree.body
        if isinstance(node, ast.Import)
        for alias in node.names
    ) == (
        ("hashlib", None),
        ("json", None),
        ("os", None),
        ("sys", None),
    )
    assert not BOOTSTRAP_PATH.with_name(
        "complete_suite_control_plane.ps1"
    ).exists()
    for marker in (
        "C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN",
        "C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END",
    ):
        assert marker not in source


def _broker_native_core_constructor_control_frame_grammar_constructor_signature_is_exact(
    function: ast.FunctionDef,
) -> bool:
    arguments = function.args
    all_arguments = (
        *arguments.posonlyargs,
        *arguments.args,
        *arguments.kwonlyargs,
    )
    return (
        function.name == "__new__"
        and function.decorator_list == []
        and function.type_comment is None
        and arguments.posonlyargs == []
        and tuple(argument.arg for argument in arguments.args) == ("cls",)
        and arguments.vararg is None
        and arguments.kwonlyargs == []
        and arguments.kw_defaults == []
        and arguments.kwarg is None
        and arguments.defaults == []
        and all(
            argument.annotation is None and argument.type_comment is None
            for argument in all_arguments
        )
        and function.returns is None
        and function.type_params == []
    )


def _broker_native_core_constructor_control_frame_grammar_exact_zero_arg_constructor_call(
    node: ast.AST | None,
) -> bool:
    return (
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id
        == "_C6BrokerNativeCoreDraftConstructorControlFrameGrammarFactsRegistry"
        and node.args == []
        and node.keywords == []
    )


def _broker_native_core_constructor_control_frame_grammar_exact_selector(
    node: ast.AST | None,
) -> bool:
    if not isinstance(node, ast.FunctionDef):
        return False
    arguments = node.args
    return (
        node.name
        == "_c6_broker_native_core_draft_select_constructor_control_frame_grammar_facts"
        and node.decorator_list == []
        and node.type_comment is None
        and arguments.posonlyargs == []
        and arguments.args == []
        and arguments.vararg is None
        and arguments.kwonlyargs == []
        and arguments.kw_defaults == []
        and arguments.kwarg is None
        and arguments.defaults == []
        and node.returns is None
        and node.type_params == []
        and len(node.body) == 1
        and isinstance(node.body[0], ast.Return)
        and _broker_native_core_constructor_control_frame_grammar_exact_zero_arg_constructor_call(
            node.body[0].value
        )
    )


def test_broker_native_core_constructor_control_frame_grammar_signature_call_and_selector_oracles_reject_extra_surface() -> None:
    exact_new = ast.parse("def __new__(cls):\n    pass").body[0]
    malformed_new_sources = (
        "def __new__(cls, /):\n    pass",
        "def __new__(cls, context):\n    pass",
        "def __new__(cls, *extra):\n    pass",
        "def __new__(cls, *, extra):\n    pass",
        "def __new__(cls, **extra):\n    pass",
        "def __new__(cls=None):\n    pass",
        "def __new__(cls: object):\n    pass",
        "def __new__(cls) -> object:\n    pass",
        "def __new__[T](cls):\n    pass",
        "@staticmethod\ndef __new__(cls):\n    pass",
    )
    malformed_news = tuple(
        ast.parse(value, type_comments=True).body[0]
        for value in malformed_new_sources
    )
    assert isinstance(exact_new, ast.FunctionDef)
    assert _broker_native_core_constructor_control_frame_grammar_constructor_signature_is_exact(
        exact_new
    )
    assert all(
        isinstance(value, ast.FunctionDef)
        and not _broker_native_core_constructor_control_frame_grammar_constructor_signature_is_exact(
            value
        )
        for value in malformed_news
    )

    class_name = (
        "_C6BrokerNativeCoreDraftConstructorControlFrameGrammarFactsRegistry"
    )
    selector_name = (
        "_c6_broker_native_core_draft_select_constructor_control_frame_grammar_facts"
    )
    exact_call = ast.parse(f"{class_name}()").body[0]
    assert isinstance(exact_call, ast.Expr)
    malformed_calls = (
        None,
        ast.parse("WrongRegistry()").body[0].value,
        ast.parse(f"{class_name}(1)").body[0].value,
        ast.parse(f"{class_name}(context=1)").body[0].value,
        ast.parse(f"owner.{class_name}()").body[0].value,
    )
    assert _broker_native_core_constructor_control_frame_grammar_exact_zero_arg_constructor_call(
        exact_call.value
    )
    assert all(
        not _broker_native_core_constructor_control_frame_grammar_exact_zero_arg_constructor_call(
            value
        )
        for value in malformed_calls
    )
    exact_selector = ast.parse(
        f"def {selector_name}():\n    return {class_name}()"
    ).body[0]
    malformed_selector_sources = (
        f"@staticmethod\ndef {selector_name}():\n    return {class_name}()",
        f"def {selector_name}(context):\n    return {class_name}()",
        f"def {selector_name}(*extra):\n    return {class_name}()",
        f"def {selector_name}(**extra):\n    return {class_name}()",
        f"def {selector_name}() -> object:\n    return {class_name}()",
        f"def {selector_name}[T]():\n    return {class_name}()",
        f"def {selector_name}():\n    pass\n    return {class_name}()",
        f"def {selector_name}():\n    return {class_name}(1)",
        f"def wrong_selector():\n    return {class_name}()",
    )
    malformed_selectors = tuple(
        ast.parse(value, type_comments=True).body[0]
        for value in malformed_selector_sources
    )
    assert _broker_native_core_constructor_control_frame_grammar_exact_selector(
        exact_selector
    )
    assert all(
        not _broker_native_core_constructor_control_frame_grammar_exact_selector(
            value
        )
        for value in malformed_selectors
    )


def test_broker_native_core_constructor_control_frame_grammar_ast_contract_accepts_exact_fixed_class_hash() -> None:
    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    class_node = next(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef)
        and node.name
        == "_C6BrokerNativeCoreDraftConstructorControlFrameGrammarFactsRegistry"
    )
    constructor = next(
        node
        for node in class_node.body
        if isinstance(node, ast.FunctionDef) and node.name == "__new__"
    )
    fingerprint = sha256(
        ast.dump(class_node, include_attributes=False).encode("utf-8")
    ).hexdigest()

    assert fingerprint == (
        _BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_CONTROL_FRAME_GRAMMAR_CLASS_FINGERPRINT
    )
    assert _broker_native_core_constructor_control_frame_grammar_constructor_signature_is_exact(
        constructor
    )
    assert _broker_native_core_forbidden_ast_capability_calls(source) == frozenset()


