def _broker_native_core_constructor_control_frame_grammar_python_tuple_mutation(
    value: tuple[object, ...],
    path: tuple[int, ...],
    index: int,
    operation: str,
    payload: object,
) -> tuple[object, ...]:
    mutable = list(value)
    if path:
        child_index = path[0]
        child = mutable[child_index]
        assert type(child) is tuple
        mutable[child_index] = (
            _broker_native_core_constructor_control_frame_grammar_python_tuple_mutation(
                child,
                path[1:],
                index,
                operation,
                payload,
            )
        )
    elif operation == "replace":
        mutable[index] = payload
    elif operation == "delete":
        del mutable[index]
    else:
        assert operation == "swap" and type(payload) is int
        mutable[index], mutable[payload] = mutable[payload], mutable[index]
    return tuple(mutable)


