def test_broker_native_core_constructor_control_frame_grammar_mutation_matrix_is_unique_complete_and_bounded() -> None:
    literal_mutations = (
        _BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_CONTROL_FRAME_GRAMMAR_LITERAL_MUTATIONS
    )
    structural_mutations = (
        _BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_CONTROL_FRAME_GRAMMAR_STRUCTURAL_MUTATIONS
    )
    mutations = _BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_CONTROL_FRAME_GRAMMAR_MUTATIONS
    expected_structural = {
        "constructor-control-grammar-caller-parameter",
        "constructor-control-grammar-singleton-introduction",
        "constructor-control-grammar-selector-introduction",
        *_BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_CONTROL_FRAME_GRAMMAR_METHOD_MUTATIONS,
        *_BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_CONTROL_FRAME_GRAMMAR_CALL_MUTATIONS,
        *_BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_CONTROL_FRAME_GRAMMAR_ASSIGNMENT_MUTATIONS,
    }

    assert len(literal_mutations) == 112
    assert len(structural_mutations) == 29
    assert set(structural_mutations) == expected_structural
    assert len(mutations) == 141
    assert len(set(mutations)) == len(mutations)
    assert set(literal_mutations).isdisjoint(structural_mutations)
    assert {
        spec[0]
        for spec in _BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_CONTROL_FRAME_GRAMMAR_EXPECTED_REPLACEMENT_SPECS
    } == {
        spec[0]
        for spec in _BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_CONTROL_FRAME_GRAMMAR_LITERAL_REPLACEMENT_SPECS
    }
    assert {
        spec[0]
        for spec in _BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_CONTROL_FRAME_GRAMMAR_EXPECTED_SEQUENCE_SPECS
    } == {
        spec[0]
        for spec in _BROKER_NATIVE_CORE_DRAFT_CONSTRUCTOR_CONTROL_FRAME_GRAMMAR_LITERAL_SEQUENCE_SPECS
    }
    mutant_asts = tuple(
        ast.dump(
            ast.parse(
                _broker_native_core_constructor_control_frame_grammar_mutant(
                    mutation
                )
            ),
            include_attributes=False,
        )
        for mutation in mutations
    )
    assert len(set(mutant_asts)) == len(mutations)


