def test_broker_native_core_post_capability_credential_role_names_directions_keys_and_caps_are_exact() -> None:
    registry = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftPostCapabilityCredentialRoleFactsRegistry"
    ]()
    name_fields, name_literal_rows = registry.name_derivation_table
    name = dict(zip(name_fields, name_literal_rows[0], strict=True))
    endpoint_fields, endpoint_literal_rows = registry.role_endpoint_table
    endpoints = tuple(
        dict(zip(endpoint_fields, row, strict=True))
        for row in endpoint_literal_rows
    )

    assert name == {
        "transport_version": "complete-suite-provider-credential-pipe-v1",
        "digest_algorithm": "SHA-256",
        "digest_input_encoding": "ASCII",
        "literal_first_line": "complete-suite-provider-credential-pipe-v1",
        "ordered_bound_field_lines": (
            "root_descriptor_nonce",
            "target_descriptor_nonce",
            "provider_attempt_claim_sha256",
        ),
        "line_separator": "LF",
        "terminal_line_separator_required": True,
        "suffix_projection": "first-32-lowercase-hex-characters",
        "suffix_alphabet": "0123456789abcdef",
    }
    assert tuple(row["dynamic_role"] for row in endpoints) == (
        "credential-data",
        "credential-host-status",
    )
    assert tuple(row["root_action"] for row in endpoints) == ("reads", "reads")
    assert tuple(row["host_action"] for row in endpoints) == ("writes", "writes")
    assert tuple(row["server_access_mode"] for row in endpoints) == (
        "PIPE_ACCESS_INBOUND",
        "PIPE_ACCESS_INBOUND",
    )
    assert tuple(row["client_access"] for row in endpoints) == (
        "GENERIC_WRITE",
        "GENERIC_WRITE",
    )
    assert len({row["root_completion_key"] for row in endpoints}) == 2
    assert len({row["host_completion_key"] for row in endpoints}) == 2
    assert set(row["root_completion_key"] for row in endpoints).isdisjoint(
        row["host_completion_key"] for row in endpoints
    )
    assert all(
        row["payload_cap_bytes"] == 65_536
        and row["endpoint_byte_cap_bytes"] == 65_540
        and sha256(row["name_grammar_bytes"]).hexdigest()
        == row["name_grammar_sha256"]
        for row in endpoints
    )


