def test_broker_native_core_post_capability_credential_role_admission_is_exact_partial_order() -> None:
    registry = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftPostCapabilityCredentialRoleFactsRegistry"
    ]()
    fields, literal_rows = registry.admission_table
    rows = tuple(dict(zip(fields, row, strict=True)) for row in literal_rows)

    assert tuple(row["gate"] for row in rows) == (
        "dynamic-pair-construction",
        "claim-ready-emission",
        "host-open-and-root-peer-verification",
        "root-connect-and-host-peer-verification",
        "credential-peer-accepted-and-fresh-host-revalidation",
    )
    assert rows[1]["required_action_or_match"] == (
        "each-initial-ConnectNamedPipe-result-is-FALSE/ERROR_IO_PENDING"
    )
    assert rows[1]["failure_disposition"] == (
        "synchronous-success-ERROR_PIPE_CONNECTED-or-any-other-result-is-"
        "unauthorized-pre-readiness-race-and-fail-closed"
    )
    assert "PROCESS_QUERY_LIMITED_INFORMATION" in rows[2][
        "required_action_or_match"
    ]
    assert "PROCESS_QUERY_LIMITED_INFORMATION" in rows[3][
        "required_action_or_match"
    ]
    assert rows[4]["successor_boundary"] == "credential-lookup-boundary"
    assert all(
        row["failure_disposition"].startswith(
            ("fail-closed", "synchronous-success", "consume-both")
        )
        for row in rows
    )
    assert (
        "admission-predecessor-tuples-are-conjunctive-partial-order-gates-and-"
        "registry-row-order-grants-no-extra-runtime-order"
        in registry.invariants
    )


def test_broker_native_core_post_capability_credential_role_cross_binds_existing_constructor_state_machine_without_runtime_authority() -> None:
    namespace = _load_broker_native_core_draft()
    registry = namespace[
        "_C6BrokerNativeCoreDraftPostCapabilityCredentialRoleFactsRegistry"
    ]()
    fixed_roles = namespace[
        "_C6BrokerNativeCoreDraftInternalChannelApplicabilityRegistry"
    ]().rows[0][3]
    dynamic_roles = registry.identity_table[1][0][3]
    control_excluded = namespace[
        "_C6BrokerNativeCoreDraftConstructorControlFrameGrammarFactsRegistry"
    ]().identity_table[1][0][4]
    binding_row = registry.shared_constructor_binding_table[1][0]
    bindings = binding_row[2]

    assert set(dynamic_roles).isdisjoint(fixed_roles)
    assert tuple(
        role for role in control_excluded if role.startswith("credential-")
    ) == dynamic_roles
    address_type = namespace["_C6BrokerNativeCoreDraftInternalChannelAddress"]
    for dynamic_role in dynamic_roles:
        with pytest.raises(RuntimeError) as rejection:
            address_type("0123456789abcdef0123456789abcdef", dynamic_role)
        assert rejection.value.args == ("GUARDED_BOOTSTRAP_INVALID",)
    assert binding_row[0] == registry.identity_table[1][0][1]
    assert len(bindings) == 13
    assert all(bound_type in namespace for _, bound_type in bindings)
    read_window = namespace["_C6BrokerNativeCoreDraftWireReadWindow"](65_540, 0)
    assert read_window.maximum_read_request_bytes == 65_536
    admission = namespace["_C6BrokerNativeCoreDraftControlFrameAdmission"](
        65_540,
        65_536,
    )
    assert tuple(admission) == (65_540, 65_536, 65_540)
    assert namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_ONE_CONTROL_FRAME_WIRE_BYTES"
    ] == 65_540
    assert registry.invariants[-1].endswith("runtime-authority")


def test_broker_native_core_post_capability_credential_role_registry_is_zero_arg_immutable_module_free_bounded_and_dormant() -> None:
    namespace = _load_broker_native_core_draft()
    registry_type = namespace[
        "_C6BrokerNativeCoreDraftPostCapabilityCredentialRoleFactsRegistry"
    ]
    registry = registry_type()
    expected_summary = (
        "_C6BrokerNativeCoreDraftPostCapabilityCredentialRoleFactsRegistry("
        "identity_row_count=1, name_derivation_row_count=1, "
        "role_endpoint_row_count=2, server_construction_row_count=1, "
        "host_client_construction_row_count=1, admission_row_count=5, "
        "shared_constructor_binding_row_count=1, invariant_count=28)"
    )

    assert tuple(inspect.signature(registry_type.__new__).parameters) == ("cls",)
    assert registry == _BROKER_NATIVE_CORE_DRAFT_POST_CAPABILITY_CREDENTIAL_ROLE_EXPECTED
    assert repr(registry) == expected_summary
    assert str(registry) == expected_summary
    assert len(repr(registry)) < 400
    assert "__file__" not in repr(registry)
    assert "__name__" not in repr(registry)
    assert not hasattr(registry, "__dict__")
    with pytest.raises(AttributeError):
        registry.identity_table = ()

    class Derived(registry_type):
        pass

    with pytest.raises(RuntimeError) as rejection:
        Derived()
    assert rejection.value.args == ("GUARDED_BOOTSTRAP_INVALID",)

    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    class_name = (
        "_C6BrokerNativeCoreDraftPostCapabilityCredentialRoleFactsRegistry"
    )
    class_nodes = tuple(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )
    assert len(class_nodes) == 1
    class_names = tuple(
        node.name for node in tree.body if isinstance(node, ast.ClassDef)
    )
    assert class_names.index(
        "_C6BrokerNativeCoreDraftConstructorControlFrameGrammarFactsRegistry"
    ) < class_names.index(class_name) < class_names.index(
        "_C6BrokerNativeCoreDraftIocpWaitWindow"
    )
    assert not any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == class_name
        for node in ast.walk(tree)
        if node not in tuple(ast.walk(class_nodes[0]))
    )
    assert tuple(
        alias.name
        for node in tree.body
        if isinstance(node, ast.Import)
        for alias in node.names
    ) == ("hashlib", "json", "os", "sys")


