def _broker_native_core_literal_tuple_leaf_paths(
    value: object,
    prefix: tuple[int, ...] = (),
) -> tuple[tuple[tuple[int, ...], object], ...]:
    if type(value) is not tuple:
        return ((prefix, value),)
    return tuple(
        item
        for index, child in enumerate(value)
        for item in _broker_native_core_literal_tuple_leaf_paths(
            child,
            (*prefix, index),
        )
    )


def _broker_native_core_literal_tuple_sequence_paths(
    value: object,
    prefix: tuple[int, ...] = (),
) -> tuple[tuple[tuple[int, ...], int], ...]:
    if type(value) is not tuple:
        return ()
    differing_index = next(
        (
            index
            for index in range(1, len(value))
            if value[index] != value[0]
        ),
        None,
    )
    current = ((prefix, differing_index),) if differing_index is not None else ()
    return (
        *current,
        *(
            item
            for index, child in enumerate(value)
            for item in _broker_native_core_literal_tuple_sequence_paths(
                child,
                (*prefix, index),
            )
        ),
    )


def _broker_native_core_literal_replacement(
    value: object,
) -> object:
    if type(value) is bool:
        return not value
    if type(value) is int:
        return value + 1
    if type(value) is str:
        return value + "-mutant"
    if type(value) is bytes:
        return value + b"-mutant"
    raise AssertionError(type(value))


