def test_broker_native_core_broker_duplex_protocol_facts_registry_matches_exact_literal_tuple_tree() -> None:
    namespace = _load_broker_native_core_draft()
    registry_type = namespace[
        "_C6BrokerNativeCoreDraftBrokerDuplexProtocolFactsRegistry"
    ]
    registry = registry_type()

    assert type(registry) is registry_type
    assert tuple(registry) == _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_EXPECTED
    assert registry.identity_table == registry[0]
    assert registry.frame_wire_rule_table == registry[1]
    assert registry.role_table == registry[2]
    assert registry.request_table == registry[3]
    assert registry.response_table == registry[4]
    assert registry.cap_table == registry[5]
    assert registry.state_table == registry[6]
    assert registry.shutdown_table == registry[7]
