def _broker_native_core_broker_duplex_mutant(mutation: str) -> str:
    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    class_name = "_C6BrokerNativeCoreDraftBrokerDuplexProtocolFactsRegistry"
    registry_class = next(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )
    registry_new = next(
        node
        for node in registry_class.body
        if isinstance(node, ast.FunctionDef) and node.name == "__new__"
    )
    assignment_nodes = {
        node.targets[0].id: node
        for node in registry_new.body
        if isinstance(node, ast.Assign)
        and len(node.targets) == 1
        and isinstance(node.targets[0], ast.Name)
    }
    replacement_specs = {
        spec[0]: spec
        for spec in _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_LITERAL_REPLACEMENT_SPECS
    }
    sequence_specs = {
        spec[0]: spec
        for spec in _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_LITERAL_SEQUENCE_SPECS
    }

    if mutation in replacement_specs:
        _, _, assignment_name, path, replacement = replacement_specs[mutation]
        assignment = assignment_nodes[assignment_name]
        assert isinstance(assignment.value, ast.Tuple)
        parent = _broker_native_core_ast_tuple_at(
            assignment.value,
            path[:-1],
        )
        target = parent.elts[path[-1]]
        assert isinstance(target, ast.Constant)
        parent.elts[path[-1]] = ast.copy_location(
            ast.Constant(value=replacement),
            target,
        )
    elif mutation in sequence_specs:
        _, _, assignment_name, path, swap_index = sequence_specs[mutation]
        assignment = assignment_nodes[assignment_name]
        assert isinstance(assignment.value, ast.Tuple)
        target = _broker_native_core_ast_tuple_at(
            assignment.value,
            path,
        )
        target.elts[0], target.elts[swap_index] = (
            target.elts[swap_index],
            target.elts[0],
        )
    elif mutation == "broker-duplex-caller-parameter":
        registry_new.args.args.append(ast.arg(arg="context"))
    elif mutation == "broker-duplex-singleton-introduction":
        tree.body.append(
            ast.parse(
                "_C6_BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_FACTS_REGISTRY = "
                "_C6BrokerNativeCoreDraftBrokerDuplexProtocolFactsRegistry()"
            ).body[0]
        )
    elif mutation == "broker-duplex-selector-introduction":
        tree.body.append(
            ast.parse(
                "def _c6_broker_native_core_draft_select_broker_duplex_facts():\n"
                "    return _C6BrokerNativeCoreDraftBrokerDuplexProtocolFactsRegistry()"
            ).body[0]
        )
    elif mutation in _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_METHOD_MUTATIONS:
        registry_class.body.append(
            ast.parse(
                _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_METHOD_MUTATIONS[mutation]
            ).body[0]
        )
    elif mutation in _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_CALL_MUTATIONS:
        for call_name in _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_CALL_MUTATIONS[
            mutation
        ]:
            registry_new.body.insert(
                0,
                ast.Expr(
                    value=ast.Call(
                        func=ast.Name(id=call_name, ctx=ast.Load()),
                        args=[],
                        keywords=[],
                    )
                ),
            )
    elif mutation in _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_ASSIGNMENT_MUTATIONS:
        assignment_name, assignment_value = (
            _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_ASSIGNMENT_MUTATIONS[
                mutation
            ]
        )
        registry_new.body.insert(
            -1,
            ast.Assign(
                targets=[ast.Name(id=assignment_name, ctx=ast.Store())],
                value=ast.parse(repr(assignment_value), mode="eval").body,
            ),
        )
    else:
        raise AssertionError(mutation)
    ast.fix_missing_locations(tree)
    return ast.unparse(tree) + "\n"


def _broker_native_core_broker_duplex_execute_class(
    source: str,
) -> tuple[object, ast.ClassDef]:
    tree = ast.parse(source)
    class_name = "_C6BrokerNativeCoreDraftBrokerDuplexProtocolFactsRegistry"
    class_node = next(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )
    module = ast.Module(body=[class_node], type_ignores=[])
    ast.fix_missing_locations(module)

    def reject(value: object) -> None:
        raise RuntimeError(value)

    namespace: dict[str, object] = {
        "_reject": reject,
        "GUARDED_BOOTSTRAP_INVALID": "GUARDED_BOOTSTRAP_INVALID",
    }
    exec(compile(module, "<broker-duplex-mutant>", "exec"), namespace)
    registry_type = namespace[class_name]
    assert isinstance(registry_type, type)
    return tuple(registry_type()), class_node


def _broker_native_core_broker_duplex_contract_accepts(source: str) -> bool:
    tree = ast.parse(source)
    class_name = "_C6BrokerNativeCoreDraftBrokerDuplexProtocolFactsRegistry"
    class_nodes = tuple(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )
    if len(class_nodes) != 1:
        return False
    class_node = class_nodes[0]
    if sha256(
        ast.dump(class_node, include_attributes=False).encode("utf-8")
    ).hexdigest() != _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_CLASS_FINGERPRINT:
        return False
    constructors = tuple(
        node
        for node in class_node.body
        if isinstance(node, ast.FunctionDef) and node.name == "__new__"
    )
    if len(constructors) != 1:
        return False
    constructor = constructors[0]
    if (
        tuple(argument.arg for argument in constructor.args.args) != ("cls",)
        or constructor.args.posonlyargs
        or constructor.args.kwonlyargs
        or constructor.args.vararg is not None
        or constructor.args.kwarg is not None
    ):
        return False
    permitted_methods = {
        "__new__",
        "identity_table",
        "frame_wire_rule_table",
        "role_table",
        "request_table",
        "response_table",
        "cap_table",
        "state_table",
        "shutdown_table",
        "invariants",
        "__repr__",
    }
    if {
        node.name for node in class_node.body if isinstance(node, ast.FunctionDef)
    } != permitted_methods:
        return False
    return not any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == class_name
        for statement in tree.body
        if statement is not class_node
        for node in ast.walk(statement)
    )


@pytest.mark.parametrize(
    "mutation",
    _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_LITERAL_MUTATIONS,
)
def test_broker_native_core_broker_duplex_literal_mutants_are_causal(
    mutation: str,
) -> None:
    mutated_source = _broker_native_core_broker_duplex_mutant(mutation)
    mutated_registry, mutated_class = (
        _broker_native_core_broker_duplex_execute_class(mutated_source)
    )
    original_expected = _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_EXPECTED
    replacement_specs = {
        spec[0]: spec
        for spec in _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_LITERAL_REPLACEMENT_SPECS
    }
    sequence_specs = {
        spec[0]: spec
        for spec in _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_LITERAL_SEQUENCE_SPECS
    }

    if mutation in replacement_specs:
        _, assignment_index, _, path, replacement = replacement_specs[mutation]
        expected_assignment = (
            _broker_native_core_replace_tuple_path(
                original_expected[assignment_index],
                path,
                replacement,
            )
        )
    else:
        _, assignment_index, _, path, swap_index = sequence_specs[mutation]
        target = original_expected[assignment_index]
        for index in path:
            assert type(target) is tuple
            target = target[index]
        assert type(target) is tuple
        swapped = list(target)
        swapped[0], swapped[swap_index] = (
            swapped[swap_index],
            swapped[0],
        )
        expected_assignment = (
            _broker_native_core_replace_tuple_path(
                original_expected[assignment_index],
                path,
                tuple(swapped),
            )
        )
    expected_outer = list(original_expected)
    expected_outer[assignment_index] = expected_assignment

    assert mutated_registry == tuple(expected_outer)
    assert mutated_registry != original_expected
    assert sha256(
        ast.dump(mutated_class, include_attributes=False).encode("utf-8")
    ).hexdigest() != _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_CLASS_FINGERPRINT
    assert not _broker_native_core_broker_duplex_contract_accepts(mutated_source)


@pytest.mark.parametrize(
    "mutation",
    _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_STRUCTURAL_MUTATIONS,
)
def test_broker_native_core_broker_duplex_structural_mutants_are_rejected(
    mutation: str,
) -> None:
    mutated_source = _broker_native_core_broker_duplex_mutant(mutation)
    assert not _broker_native_core_broker_duplex_contract_accepts(mutated_source)

    tree = ast.parse(mutated_source)
    class_name = "_C6BrokerNativeCoreDraftBrokerDuplexProtocolFactsRegistry"
    class_node = next(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )
    constructor = next(
        node
        for node in class_node.body
        if isinstance(node, ast.FunctionDef) and node.name == "__new__"
    )
    if mutation == "broker-duplex-caller-parameter":
        assert tuple(argument.arg for argument in constructor.args.args) == (
            "cls",
            "context",
        )
    elif mutation == "broker-duplex-singleton-introduction":
        assert any(
            isinstance(node, ast.Assign)
            and any(
                isinstance(target, ast.Name)
                and target.id
                == "_C6_BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_FACTS_REGISTRY"
                for target in node.targets
            )
            for node in tree.body
        )
    elif mutation == "broker-duplex-selector-introduction":
        assert any(
            isinstance(node, ast.FunctionDef)
            and node.name
            == "_c6_broker_native_core_draft_select_broker_duplex_facts"
            for node in tree.body
        )
    elif mutation in _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_METHOD_MUTATIONS:
        expected_name = ast.parse(
            _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_METHOD_MUTATIONS[mutation]
        ).body[0].name
        assert any(
            isinstance(node, ast.FunctionDef) and node.name == expected_name
            for node in class_node.body
        )
    elif mutation in _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_CALL_MUTATIONS:
        expected_calls = set(
            _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_CALL_MUTATIONS[mutation]
        )
        actual_calls = {
            node.func.id
            for node in ast.walk(constructor)
            if isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id in expected_calls
        }
        assert actual_calls == expected_calls
        assert _broker_native_core_forbidden_ast_capability_calls(mutated_source)
    else:
        assignment_name, assignment_value = (
            _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_ASSIGNMENT_MUTATIONS[
                mutation
            ]
        )
        assignments = tuple(
            node
            for node in constructor.body
            if isinstance(node, ast.Assign)
            and any(
                isinstance(target, ast.Name) and target.id == assignment_name
                for target in node.targets
            )
        )
        assert len(assignments) == 1
        assert ast.literal_eval(assignments[0].value) == assignment_value


def test_broker_native_core_broker_duplex_ast_contract_accepts_exact_fixed_class_hash() -> None:
    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    class_name = "_C6BrokerNativeCoreDraftBrokerDuplexProtocolFactsRegistry"
    class_nodes = tuple(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )

    assert _broker_native_core_forbidden_ast_capability_calls(source) == frozenset()
    assert len(class_nodes) == 1
    class_fingerprint = sha256(
        ast.dump(class_nodes[0], include_attributes=False).encode("utf-8")
    ).hexdigest()
    assert class_fingerprint == (
        _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_CLASS_FINGERPRINT
    )
    assert dict(_BROKER_NATIVE_CORE_APPROVED_MODULE_STATEMENT_CONTRACT)[
        f"ClassDef:{class_name}"
    ] == class_fingerprint
    assert _broker_native_core_broker_duplex_contract_accepts(source)


def test_broker_native_core_broker_duplex_mutation_matrix_is_unique_complete_and_bounded() -> None:
    literal_mutations = _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_LITERAL_MUTATIONS
    structural_mutations = (
        _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_STRUCTURAL_MUTATIONS
    )
    mutations = _BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_MUTATIONS

    assert len(_BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_LITERAL_REPLACEMENT_SPECS) == 213
    assert len(_BROKER_NATIVE_CORE_DRAFT_BROKER_DUPLEX_LITERAL_SEQUENCE_SPECS) == 41
    assert len(literal_mutations) == 254
    assert len(structural_mutations) == 29
    assert len(mutations) == 283
    assert len(set(mutations)) == len(mutations)
    assert set(literal_mutations).isdisjoint(structural_mutations)
    mutant_module_asts = tuple(
        ast.dump(
            ast.parse(_broker_native_core_broker_duplex_mutant(mutation)),
            include_attributes=False,
        )
        for mutation in mutations
    )
    assert len(set(mutant_module_asts)) == len(mutations)


