def test_broker_native_core_execute_claim_capability_payload_schema_is_exact_ordered_and_secret_free() -> None:
    registry = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftExecuteClaimCapabilityFactsRegistry"
    ]()
    schema = dict(
        zip(
            registry.payload_schema_table[0],
            registry.payload_schema_table[1][0],
            strict=True,
        )
    )

    assert schema["record_type"] == "ExecuteClaimCapability"
    assert schema["schema_version"] == (
        "complete-suite-execute-claim-capability-v1"
    )
    assert len(schema["serialized_field_order"]) == 24
    assert schema["serialized_field_order"][0] == "version"
    assert schema["serialized_field_order"][-2:] == (
        "target_pid",
        "target_creation_time",
    )
    assert schema["wrapper_only_fields"] == ("canonical_sha256",)
    assert "canonical_sha256" not in schema["serialized_field_order"]
    assert schema["raw_root_identity_field_order"] == (
        "device",
        "inode",
        "file_type",
        "reparse_tag",
        "link_count",
    )
    assert schema["forbidden_payload_categories"] == (
        "filesystem-path",
        "credential-value",
        "environment-mapping",
        "free-form-message",
        "caller-selected-expected-value",
        "unknown-or-extra-field",
    )
    assert "OPENAI_API_KEY" in schema["credential_literal_policy"]
    assert "credential-value" in schema["credential_literal_policy"]


def test_broker_native_core_execute_claim_capability_request_is_post_go_next_sequence_at_most_once_and_sole_outstanding() -> None:
    namespace = _load_broker_native_core_draft()
    registry = namespace[
        "_C6BrokerNativeCoreDraftExecuteClaimCapabilityFactsRegistry"
    ]()
    admission = dict(
        zip(
            registry.request_admission_table[0],
            registry.request_admission_table[1][0],
            strict=True,
        )
    )
    duplex = namespace[
        "_C6BrokerNativeCoreDraftBrokerDuplexProtocolFactsRegistry"
    ]()
    duplex_request = dict(
        zip(duplex.request_table[0], duplex.request_table[1][0], strict=True)
    )

    assert admission["request_role"] == "execute-claim-capability"
    assert admission["producer"] == "authenticated-execute-root-role-target"
    assert admission["admission_predecessors"][0] == "authenticated-GO"
    assert admission["sequence_binding"] == "exact-target-next-broker-sequence"
    assert admission["sequence_binding"] != str(duplex_request["initial_sequence"])
    assert admission["send_cardinality"] == "at-most-once-per-execute-target"
    assert admission["outstanding_request_cardinality"] == (
        "sole-outstanding-broker-request"
    )
    assert duplex_request["admission_boundary"] == "only-after-authenticated-GO"
    assert duplex_request["outstanding_request_cap"] == 1
    assert duplex_request["sequence_progression"] == (
        "strictly-monotonically-increasing"
    )
    assert duplex_request["payload_digest_verification"] == (
        "payload-SHA-256-must-match-canonical-payload-bytes"
    )


