def test_broker_native_core_execute_claim_capability_source_bindings_are_complete_independent_and_conjunctive() -> None:
    registry = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftExecuteClaimCapabilityFactsRegistry"
    ]()
    fields, literal_rows = registry.source_binding_table
    rows = tuple(dict(zip(fields, row, strict=True)) for row in literal_rows)
    by_source = {row["source_family"]: row for row in rows}

    assert tuple(by_source) == (
        "root-descriptor",
        "target-descriptor",
        "approved-campaign",
        "approval-envelope",
        "approval-prompt",
        "provider-approval-record",
        "authorization-reservation",
        "retained-pre-ACK-snapshot",
        "execute-consumption-marker",
        "provider-attempt-claim",
        "claimed-raw-root",
        "candidate-input-aggregate",
        "stdlib-reconstructed-detached-authorization",
    )
    authorization = by_source["stdlib-reconstructed-detached-authorization"]
    assert authorization["input_source"] == (
        "root-descriptor-plus-five-reopened-facts-and-retained-pre-ACK-snapshot"
    )
    assert authorization["bound_capability_fields"] == (
        "provider_execution_authorization_sha256",
        "approved_campaign_sha256",
        "approval_envelope_sha256",
        "approval_prompt_sha256",
        "provider_approval_sha256",
        "reservation_sha256",
        "preclaim_snapshot_sha256",
        "credential_transport_version",
        "credential_environment_name",
    )
    six_constituents = authorization["bound_capability_fields"][1:7]
    assert six_constituents == (
        "approved_campaign_sha256",
        "approval_envelope_sha256",
        "approval_prompt_sha256",
        "provider_approval_sha256",
        "reservation_sha256",
        "preclaim_snapshot_sha256",
    )
    assert "execute_consumption_sha256" not in six_constituents
    assert "provider_attempt_claim_sha256" not in six_constituents
    assert by_source["claimed-raw-root"]["bound_capability_fields"] == (
        "raw_root_identity",
    )
    assert by_source["candidate-input-aggregate"]["bound_capability_fields"] == (
        "frozen_client_identity_sha256",
        "client_launch_template_sha256",
    )


def test_broker_native_core_execute_claim_capability_validation_gates_are_exact_conjunctive_and_fail_before_pipe_creation() -> None:
    registry = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftExecuteClaimCapabilityFactsRegistry"
    ]()
    fields, literal_rows = registry.validation_gate_table
    rows = tuple(dict(zip(fields, row, strict=True)) for row in literal_rows)

    assert tuple(row["step"] for row in rows) == tuple(range(1, 9))
    assert tuple(row["gate"] for row in rows) == (
        "authenticated-request-admission",
        "strict-capability-parse",
        "descriptor-derived-path-resolution",
        "independent-source-reopen",
        "detached-authorization-reconstruction",
        "authorization-agreement",
        "remaining-source-agreement",
        "conjunctive-validation-decision",
    )
    assert all(
        row["failure_boundary"]
        == "reject-before-secret-pipe-creation-with-all-four-credential-counters-zero"
        for row in rows
    )
    assert rows[-1]["successor_boundary"] == (
        "return-validated-capability-and-permit-dynamic-pair-construction"
    )
    assert "never-capability-bytes" in rows[2]["required_action_or_match"]
    assert "stdlib-only" in rows[4]["required_action_or_match"]


def test_broker_native_core_execute_claim_capability_cross_binds_duplex_and_post_capability_admission_without_runtime_authority() -> None:
    namespace = _load_broker_native_core_draft()
    registry = namespace[
        "_C6BrokerNativeCoreDraftExecuteClaimCapabilityFactsRegistry"
    ]()
    duplex = namespace[
        "_C6BrokerNativeCoreDraftBrokerDuplexProtocolFactsRegistry"
    ]()
    post_capability = namespace[
        "_C6BrokerNativeCoreDraftPostCapabilityCredentialRoleFactsRegistry"
    ]()
    duplex_exclusions = duplex.identity_table[1][0][6]
    admission_fields, admission_literal_rows = post_capability.admission_table
    admission_rows = tuple(
        dict(zip(admission_fields, row, strict=True))
        for row in admission_literal_rows
    )

    assert "execute-claim-capability-payload-schema" in duplex_exclusions
    assert registry.identity_table[1][0][2].startswith(
        "execute-claim-capability"
    )
    dynamic_pair = admission_rows[0]
    assert dynamic_pair["gate"] == "dynamic-pair-construction"
    assert (
        "root-independent-validation-of-one-post-GO-execute-claim-capability"
        in dynamic_pair["required_predecessors"]
    )
    assert registry.request_admission_table[1][0][-1] == (
        "root-independent-validation-before-dynamic-pair-construction"
    )
    assert registry.invariants[-1].endswith("runtime-authority")


def test_broker_native_core_execute_claim_capability_registry_is_zero_arg_immutable_module_free_bounded_and_dormant() -> None:
    namespace = _load_broker_native_core_draft()
    registry_type = namespace[
        "_C6BrokerNativeCoreDraftExecuteClaimCapabilityFactsRegistry"
    ]
    registry = registry_type()
    expected_summary = (
        "_C6BrokerNativeCoreDraftExecuteClaimCapabilityFactsRegistry("
        "identity_row_count=1, payload_schema_row_count=1, "
        "request_admission_row_count=1, validator_interface_row_count=1, "
        "source_binding_row_count=13, validation_gate_row_count=8, "
        "invariant_count=27)"
    )

    assert tuple(inspect.signature(registry_type.__new__).parameters) == ("cls",)
    assert registry == _BROKER_NATIVE_CORE_DRAFT_EXECUTE_CLAIM_CAPABILITY_EXPECTED
    assert repr(registry) == expected_summary
    assert str(registry) == expected_summary
    assert len(repr(registry)) < 400
    assert "__file__" not in repr(registry)
    assert "__name__" not in repr(registry)
    assert not hasattr(registry, "__dict__")
    with pytest.raises(AttributeError):
        registry.identity_table = ()

    class Derived(registry_type):
        pass

    with pytest.raises(RuntimeError) as rejection:
        Derived()
    assert rejection.value.args == ("GUARDED_BOOTSTRAP_INVALID",)

    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    class_name = "_C6BrokerNativeCoreDraftExecuteClaimCapabilityFactsRegistry"
    class_nodes = tuple(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )
    assert len(class_nodes) == 1
    class_names = tuple(
        node.name for node in tree.body if isinstance(node, ast.ClassDef)
    )
    assert class_names.index(
        "_C6BrokerNativeCoreDraftBrokerDuplexProtocolFactsRegistry"
    ) < class_names.index(class_name) < class_names.index(
        "_C6BrokerNativeCoreDraftIocpWaitWindow"
    )
    class_descendants = frozenset(ast.walk(class_nodes[0]))
    assert not any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == class_name
        and node not in class_descendants
        for node in ast.walk(tree)
    )
    assert tuple(
        alias.name
        for node in tree.body
        if isinstance(node, ast.Import)
        for alias in node.names
    ) == ("hashlib", "json", "os", "sys")


