def test_broker_native_core_execute_claim_ready_facts_registry_matches_exact_literal_tuple_tree() -> None:
    namespace = _load_broker_native_core_draft()
    registry_type = namespace[
        "_C6BrokerNativeCoreDraftExecuteClaimReadyFactsRegistry"
    ]
    registry = registry_type()

    assert type(registry) is registry_type
    assert tuple(registry) == _BROKER_NATIVE_CORE_DRAFT_EXECUTE_CLAIM_READY_EXPECTED
    assert registry.identity_table == registry[0]
    assert registry.payload_schema_table == registry[1]
    assert registry.capability_projection_table == registry[2]
    assert registry.pipe_name_embedding_table == registry[3]
    assert registry.process_identity_binding_table == registry[4]
    assert registry.admission_gate_table == registry[5]
    assert registry.invariants == registry[6]
    assert tuple(map(len, registry.identity_table)) == (10, 1)
    assert tuple(map(len, registry.payload_schema_table)) == (8, 1)
    assert tuple(map(len, registry.capability_projection_table)) == (8, 1)
    assert tuple(map(len, registry.pipe_name_embedding_table)) == (20, 2)
    assert tuple(map(len, registry.process_identity_binding_table)) == (6, 3)
    assert tuple(map(len, registry.admission_gate_table)) == (8, 8)
    assert len(registry.invariants) == 27
    assert all(type(value) is tuple for value in registry)


def test_broker_native_core_execute_claim_ready_schema_is_exact_ordered_wrapper_hashed_and_secret_free() -> None:
    namespace = _load_broker_native_core_draft()
    registry = namespace[
        "_C6BrokerNativeCoreDraftExecuteClaimReadyFactsRegistry"
    ]()
    constructor_control = namespace[
        "_C6BrokerNativeCoreDraftConstructorControlFrameGrammarFactsRegistry"
    ]()
    schema = dict(
        zip(
            registry.payload_schema_table[0],
            registry.payload_schema_table[1][0],
            strict=True,
        )
    )

    assert schema["record_type"] == "ExecuteClaimReady"
    assert schema["schema_version"] == "complete-suite-execute-claim-ready-v1"
    assert len(schema["serialized_field_order"]) == 30
    assert schema["serialized_field_order"] == (
        _BROKER_NATIVE_CORE_DRAFT_EXECUTE_CLAIM_READY_PAYLOAD_SCHEMA_TABLE[1][0][
            2
        ]
    )
    assert schema["serialized_field_order"][0] == "version"
    assert schema["serialized_field_order"][-6:] == (
        "host_pid",
        "host_creation_time",
        "root_pid",
        "root_creation_time",
        "target_pid",
        "target_creation_time",
    )
    assert schema["wrapper_only_fields"] == ("canonical_sha256",)
    assert "canonical_sha256" not in schema["serialized_field_order"]
    assert schema["canonical_payload_contract"] == (
        "inherit-constructor-control-frame-canonical-JSON-strict-UTF-8-payload-and-SHA-256-contract"
    )
    assert schema["raw_root_identity_field_order"] == (
        "device",
        "inode",
        "file_type",
        "reparse_tag",
        "link_count",
    )
    assert schema["forbidden_payload_categories"] == (
        "credential-value",
        "credential-length-or-credential-derived-hash",
        "environment-mapping",
        "arbitrary-filesystem-path",
        "caller-supplied-pipe-name",
        "free-form-or-private-error-text",
        "pipe-or-process-handle",
        "completion-or-lifecycle-object",
        "unknown-or-extra-field",
    )
    assert "OPENAI_API_KEY" in schema["allowed_literal_policy"]
    assert "no-credential-material-or-arbitrary-path" in schema[
        "allowed_literal_policy"
    ]
    wire_rule = dict(
        zip(
            constructor_control.frame_wire_rule_table[0],
            constructor_control.frame_wire_rule_table[1][0],
            strict=True,
        )
    )
    assert wire_rule == {
        "length_prefix_bytes": 4,
        "length_prefix_type": "unsigned-payload-byte-length",
        "length_prefix_endianness": "little-endian",
        "payload_encoding": "strict-UTF-8",
        "payload_canonical_form": "canonical-JSON",
        "payload_cap_bytes": 65_536,
        "maximum_frame_wire_bytes": 65_540,
    }
    grammar_fields, grammar_literal_rows = constructor_control.grammar_table
    no_peer_rows = tuple(
        dict(zip(grammar_fields, row, strict=True))
        for row in grammar_literal_rows
        if row[0] == "ack-status"
        and row[1] == "host-facing-execute-root"
        and row[2] == "exactly-one-claim-ready"
        and row[3] == "no-peer-connection-observed"
    )
    assert no_peer_rows == (
        {
            "fixed_role": "ack-status",
            "endpoint_context": "host-facing-execute-root",
            "readiness_frame_state": "exactly-one-claim-ready",
            "peer_connection_state": "no-peer-connection-observed",
            "exact_ordered_wire_events": (
                "ack",
                "claim-ready",
                "terminal",
                "EOF",
            ),
            "maximum_frame_count_for_role_context": 4,
        },
    )


def test_broker_native_core_execute_claim_ready_projection_repeats_exact_capability_without_capability_hash() -> None:
    namespace = _load_broker_native_core_draft()
    registry = namespace[
        "_C6BrokerNativeCoreDraftExecuteClaimReadyFactsRegistry"
    ]()
    capability = namespace[
        "_C6BrokerNativeCoreDraftExecuteClaimCapabilityFactsRegistry"
    ]()
    projection = dict(
        zip(
            registry.capability_projection_table[0],
            registry.capability_projection_table[1][0],
            strict=True,
        )
    )
    capability_schema = dict(
        zip(
            capability.payload_schema_table[0],
            capability.payload_schema_table[1][0],
            strict=True,
        )
    )
    readiness_schema = dict(
        zip(
            registry.payload_schema_table[0],
            registry.payload_schema_table[1][0],
            strict=True,
        )
    )

    assert projection["source_record_type"] == capability_schema["record_type"]
    assert projection["source_version"] == capability_schema["schema_version"]
    assert projection["readiness_version"] == readiness_schema["schema_version"]
    assert projection["exact_repeated_binding_fields"] == (
        capability_schema["serialized_field_order"][1:]
    )
    assert len(projection["exact_repeated_binding_fields"]) == 23
    repeated_field_set = frozenset(projection["exact_repeated_binding_fields"])
    assert tuple(
        field
        for field in readiness_schema["serialized_field_order"]
        if field in repeated_field_set
    ) == projection["exact_repeated_binding_fields"]
    assert projection["relocated_fields"] == (
        "target_pid",
        "target_creation_time",
    )
    assert readiness_schema["serialized_field_order"][-2:] == (
        "target_pid",
        "target_creation_time",
    )
    assert "execute_claim_capability_sha256" not in readiness_schema[
        "serialized_field_order"
    ]
    assert projection["capability_hash_field_policy"].startswith(
        "execute_claim_capability_sha256-is-absent"
    )


def test_broker_native_core_execute_claim_ready_embeds_two_exact_distinct_bound_pipe_name_records() -> None:
    registry = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftExecuteClaimReadyFactsRegistry"
    ]()
    fields, literal_rows = registry.pipe_name_embedding_table
    rows = tuple(dict(zip(fields, row, strict=True)) for row in literal_rows)

    assert tuple(row["readiness_field"] for row in rows) == (
        "pipe",
        "host_status_pipe",
    )
    assert tuple(row["nested_record_type"] for row in rows) == (
        "ExecuteCredentialPipeName",
        "ExecuteCredentialHostStatusPipeName",
    )
    assert tuple(row["dynamic_role"] for row in rows) == (
        "credential-data",
        "credential-host-status",
    )
    assert tuple(row["exact_name_prefix"] for row in rows) == (
        "\\\\.\\pipe\\kokoroarc-c6-execute-",
        "\\\\.\\pipe\\kokoroarc-c6-execute-status-",
    )
    assert tuple(row["name_grammar_sha256"] for row in rows) == (
        "29078e6b8f6b81c33cbd530d75d50af49d57efeb7cbf178772b6991ceb90dba7",
        "9c3c0b32ef2fc6d043800293ae1cb964fc0a212a9107472e9a8326c855be7837",
    )
    assert tuple(row["payload_cap_bytes"] for row in rows) == (65_536, 65_536)
    assert tuple(row["transport_version_value"] for row in rows) == (
        "complete-suite-provider-credential-pipe-v1",
        "complete-suite-provider-credential-pipe-v1",
    )
    assert all(
        row["nested_serialized_field_order"]
        == (
            "version",
            "transport_version",
            "value",
            "value_sha256",
            "root_descriptor_nonce",
            "target_descriptor_nonce",
            "provider_attempt_claim_sha256",
            "payload_cap_bytes",
            "grammar_sha256",
        )
        for row in rows
    )
    assert all(row["nested_wrapper_only_fields"] == ("canonical_sha256",) for row in rows)
    suffix_source_fields = (
        "root_descriptor_nonce",
        "target_descriptor_nonce",
        "provider_attempt_claim_sha256",
    )
    suffix_source_labels = {
        "root_descriptor_nonce": "root-nonce",
        "target_descriptor_nonce": "target-nonce",
        "provider_attempt_claim_sha256": "provider-attempt-claim",
    }
    for row in rows:
        binding_sources = dict(row["nested_field_binding_sources"])
        assert tuple(binding_sources) == (
            *row["nested_serialized_field_order"],
            "canonical_sha256",
        )
        assert binding_sources["transport_version"] == (
            "outer-credential_transport_version-exact"
        )
        assert binding_sources["version"] == f"literal-{row['nested_record_version']}"
        assert binding_sources["value"] == (
            f"exact-derived-{row['dynamic_role']}-name-from-same-P"
        )
        assert binding_sources["value_sha256"] == (
            "SHA-256-of-ASCII-exact-value"
        )
        assert binding_sources["root_descriptor_nonce"] == (
            "outer-root_descriptor_nonce-exact"
        )
        assert binding_sources["target_descriptor_nonce"] == (
            "outer-target_descriptor_nonce-exact"
        )
        assert binding_sources["provider_attempt_claim_sha256"] == (
            "outer-provider_attempt_claim_sha256-exact"
        )
        assert binding_sources["payload_cap_bytes"] == "literal-65536"
        assert binding_sources["grammar_sha256"] == (
            f"literal-{row['name_grammar_sha256']}"
        )
        assert binding_sources["canonical_sha256"] == (
            "wrapper-only-SHA-256-over-exact-nested-canonical-bytes"
        )
        assert row["same_derived_suffix_binding"] == (
            "same-P-from-"
            f"{suffix_source_labels[suffix_source_fields[0]]}-"
            f"{suffix_source_labels[suffix_source_fields[1]]}-and-"
            f"{suffix_source_labels[suffix_source_fields[2]]}"
        )
    assert len({row["same_derived_suffix_binding"] for row in rows}) == 1
    assert all(row["caller_supplied"] is False for row in rows)
    assert all(row["later_status_or_lifecycle_hash_dependency"] == "none" for row in rows)
    assert all(row["handle_inheritable"] is False for row in rows)
    assert all(
        row["alias_policy"]
        == "distinct-from-other-dynamic-and-every-static-role-domain"
        for row in rows
    )
