def test_broker_native_core_execute_claim_ready_registry_is_zero_arg_immutable_module_free_bounded_and_dormant() -> None:
    namespace = _load_broker_native_core_draft()
    registry_type = namespace[
        "_C6BrokerNativeCoreDraftExecuteClaimReadyFactsRegistry"
    ]
    registry = registry_type()
    expected_summary = (
        "_C6BrokerNativeCoreDraftExecuteClaimReadyFactsRegistry("
        "identity_row_count=1, payload_schema_row_count=1, "
        "capability_projection_row_count=1, pipe_name_embedding_row_count=2, "
        "process_identity_binding_row_count=3, admission_gate_row_count=8, "
        "invariant_count=27)"
    )

    assert tuple(inspect.signature(registry_type.__new__).parameters) == ("cls",)
    assert registry == _BROKER_NATIVE_CORE_DRAFT_EXECUTE_CLAIM_READY_EXPECTED
    assert repr(registry) == expected_summary
    assert str(registry) == expected_summary
    assert len(repr(registry)) < 400
    assert "__file__" not in repr(registry)
    assert "__name__" not in repr(registry)
    assert not hasattr(registry, "__dict__")
    with pytest.raises(AttributeError):
        registry.identity_table = ()

    class Derived(registry_type):
        pass

    with pytest.raises(RuntimeError) as rejection:
        Derived()
    assert rejection.value.args == ("GUARDED_BOOTSTRAP_INVALID",)

    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    class_name = "_C6BrokerNativeCoreDraftExecuteClaimReadyFactsRegistry"
    class_nodes = tuple(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )
    assert len(class_nodes) == 1
    class_names = tuple(
        node.name for node in tree.body if isinstance(node, ast.ClassDef)
    )
    assert class_names.index(
        "_C6BrokerNativeCoreDraftExecuteClaimCapabilityFactsRegistry"
    ) < class_names.index(class_name) < class_names.index(
        "_C6BrokerNativeCoreDraftIocpWaitWindow"
    )
    class_descendants = frozenset(ast.walk(class_nodes[0]))
    assert not any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == class_name
        and node not in class_descendants
        for node in ast.walk(tree)
    )
    assert tuple(
        alias.name
        for node in tree.body
        if isinstance(node, ast.Import)
        for alias in node.names
    ) == ("hashlib", "json", "os", "sys")


