def test_broker_native_core_credential_data_transfer_facts_registry_matches_exact_literal_tuple_tree() -> None:
    namespace = _load_broker_native_core_draft()
    registry_type = namespace[
        "_C6BrokerNativeCoreDraftCredentialDataTransferFactsRegistry"
    ]
    registry = registry_type()

    assert type(registry) is registry_type
    assert tuple(registry) == _BROKER_NATIVE_CORE_DRAFT_CREDENTIAL_DATA_TRANSFER_EXPECTED
    assert registry.identity_table == registry[0]
    assert registry.wire_classification_table == registry[1]
    assert registry.lookup_value_admission_table == registry[2]
    assert registry.transfer_partial_order_table == registry[3]
    assert registry.root_validation_table == registry[4]
    assert registry.terminal_counter_table == registry[5]
    assert registry.cleanup_successor_table == registry[6]
    assert registry.invariants == registry[7]
    assert tuple(map(len, registry.identity_table)) == (11, 1)
    assert tuple(map(len, registry.wire_classification_table)) == (13, 4)
    assert tuple(map(len, registry.lookup_value_admission_table)) == (16, 3)
    assert tuple(map(len, registry.transfer_partial_order_table)) == (8, 7)
    assert tuple(map(len, registry.root_validation_table)) == (8, 4)
    assert tuple(map(len, registry.terminal_counter_table)) == (8, 6)
    assert tuple(map(len, registry.cleanup_successor_table)) == (8, 8)
    assert len(registry.invariants) == 42
    assert all(type(value) is tuple for value in registry)


def test_broker_native_core_credential_data_transfer_identity_activation_successor_and_exclusions_are_exact() -> None:
    registry = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftCredentialDataTransferFactsRegistry"
    ]()
    identity = dict(
        zip(
            registry.identity_table[0],
            registry.identity_table[1][0],
            strict=True,
        )
    )

    assert identity["implementation_id"] == "broker-native-core-v1"
    assert identity["dynamic_role"] == "credential-data"
    assert (identity["producer"], identity["consumer"]) == (
        "trusted-host",
        "execute-root-broker",
    )
    assert identity["activation_predecessors"] == (
        "canonical-ExecuteClaimReady-emitted-and-validated",
        "post-readiness-one-shot-cleanup-is-mandatory",
    )
    assert identity["lookup_admission_boundary"] == (
        "single-credential-lookup-eligibility"
    )
    assert identity["successor_boundary"] == "CredentialHostStatus-construction"
    assert identity["serialized_data_frame_policy"] == (
        "no-serialized-CredentialDataFrame-and-no-data-frame-hash"
    )
    assert identity["excluded_semantic_scopes"] == (
        "CredentialHostStatus-payload-schema-and-wire-serialization",
        "credential-and-pipe-lifecycle-record-serialization",
        "broker-request-response-sequencing",
        "durable-persistence",
        "private-error-projection",
        "runtime-I/O-authority",
    )
    fact_text = repr(tuple(registry))
    for forbidden_api_name in (
        "GetEnvironmentVariableW",
        "ReadFile",
        "WriteFile",
        "CancelIoEx",
        "CloseHandle",
        "CreateProcessW",
        "WideCharToMultiByte",
        "CryptHashData",
        "SecureZeroMemory",
    ):
        assert forbidden_api_name not in fact_text


def test_broker_native_core_credential_data_transfer_wire_classification_is_exact_bounded_incremental_and_closed() -> None:
    registry = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftCredentialDataTransferFactsRegistry"
    ]()
    fields, literal_rows = registry.wire_classification_table
    rows = tuple(dict(zip(fields, row, strict=True)) for row in literal_rows)

    assert tuple(row["classification"] for row in rows) == (
        "complete-unavailable",
        "bounded-nonzero-candidate",
        "over-cap-prefix",
        "isolation-failure-framing",
    )
    assert all(row["prefix_contract"].startswith("exactly-four-byte") for row in rows[:3])
    assert rows[0]["N_domain"] == "N-equals-0"
    assert rows[0]["payload_contract"] == "exactly-zero-payload-bytes"
    assert rows[0]["writer_termination"] == "writer-close-then-immediate-EOF"
    assert rows[0]["provider_credential_policy"] == "forbidden"
    assert rows[0]["public_disposition"] == "CAMPAIGN_CREDENTIAL_UNAVAILABLE"
    assert rows[1]["N_domain"] == (
        "1-less-than-or-equal-to-N-less-than-or-equal-to-65536"
    )
    assert rows[1]["payload_contract"] == "exactly-N-payload-bytes"
    assert rows[2]["N_domain"] == "N-greater-than-65536"
    assert rows[2]["payload_allocation_policy"] == (
        "reject-before-payload-allocation"
    )
    assert rows[2]["public_disposition"] == "CAMPAIGN_SECRET_ISOLATION_FAILED"
    assert "second-frame" in rows[3]["N_domain"]
    assert "second-connection" in rows[3]["N_domain"]
    assert "missing-EOF" in rows[3]["N_domain"]
    assert rows[3]["public_disposition"] == "CAMPAIGN_SECRET_ISOLATION_FAILED"
    assert all(row["payload_cap_bytes"] == 65_536 for row in rows)
    assert all(row["maximum_wire_bytes"] == 65_540 for row in rows)
    assert rows[0]["extra_read_contract"] == (
        "exactly-one-bounded-one-byte-extra-read"
    )
    assert rows[1]["extra_read_contract"] == (
        "exactly-one-bounded-one-byte-extra-read"
    )
    assert rows[0]["admissible_extra_read_result"] == (
        "EOF-or-ERROR_BROKEN_PIPE-at-role-permitted-read-terminal"
    )
    assert rows[1]["admissible_extra_read_result"] == (
        "EOF-or-ERROR_BROKEN_PIPE-at-role-permitted-read-terminal"
    )


def test_broker_native_core_credential_data_transfer_lookup_validates_original_value_once_without_secret_derivation() -> None:
    registry = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftCredentialDataTransferFactsRegistry"
    ]()
    fields, literal_rows = registry.lookup_value_admission_table
    rows = tuple(dict(zip(fields, row, strict=True)) for row in literal_rows)

    assert tuple(row["value_classification"] for row in rows) == (
        "pre-lookup-admission-failure",
        "accepted-visible-ASCII",
        "rejected-original-value",
    )
    assert all(
        row["registry_lifecycle_activation"]
        == (
            "canonical-ExecuteClaimReady-emitted-and-validated",
            "post-readiness-one-shot-cleanup-is-mandatory",
        )
        for row in rows
    )
    assert all(
        row["lookup_admission_boundary"]
        == "single-credential-lookup-eligibility"
        for row in rows
    )
    assert rows[0]["pre_admission_lookup_policy"] == (
        "lookup-forbidden-unless-the-exact-boundary-is-reached"
    )
    assert rows[0]["lookup_transition"] == (
        "no-lookup-and-all-four-counters-remain-zero"
    )
    assert rows[0]["character_domain"] == (
        "fresh-full-host-revalidation-failure",
        "earlier-post-readiness-gate-failure",
    )
    assert rows[0]["wire_action"] == "no-credential-data-frame"
    assert rows[0]["possible_terminal_counter_states"] == ((0, 0, 0, 0),)
    assert rows[0]["cleanup_handoff"] == (
        "continue-mandated-cleanup-and-CredentialHostStatus-handoff"
    )
    assert all(
        row["lookup_transition"]
        == "atomically-increment-credential_lookup_count-exactly-once"
        for row in rows[1:]
    )
    assert all(row["credential_name"] == "OPENAI_API_KEY" for row in rows[1:])
    assert all(
        row["validation_subject"] == "original-UTF-16-value-character-by-character"
        for row in rows[1:]
    )
    assert rows[1]["validation_order"] == (
        "complete-character-validation-before-strict-encoding"
    )
    assert rows[1]["character_domain"] == (
        "every-character-is-visible-ASCII-0x21-through-0x7e"
    )
    assert rows[1]["encoded_length_domain"] == (
        "nonempty-and-at-most-65536-encoded-bytes"
    )
    assert rows[2]["character_domain"] == (
        "NUL",
        "space",
        "control",
        "non-ASCII",
        "surrogate",
        "empty",
        "over-cap",
    )
    assert all(
        row["forbidden_transformations"]
        == (
            "no-trim",
            "no-normalize",
            "no-hash",
            "no-log",
            "no-canonicalization",
            "no-durable-serialization",
            "no-exact-or-rounded-length-retention",
        )
        for row in rows[1:]
    )
    assert rows[1]["value_retention_policy"] == (
        "root-scoped-transient-retention-only-after-root-acceptance-until-terminal-broker-shutdown"
    )
    assert rows[1]["possible_terminal_counter_states"] == (
        (1, 0, 0, 0),
        (1, 1, 0, 0),
        (1, 1, 1, 0),
        (1, 1, 1, 1),
    )
    assert rows[2]["value_retention_policy"] == "invalid-value-is-not-retained"
    assert rows[2]["wire_action"] == (
        "write-exactly-four-zero-bytes-then-close-without-payload"
    )
    assert rows[2]["provider_credential_eligibility"] == "forbidden"
    assert rows[2]["possible_terminal_counter_states"] == ((1, 0, 0, 0),)


