def test_broker_native_core_credential_data_transfer_root_validation_and_provider_credential_projection_are_exact_and_secret_free() -> None:
    registry = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftCredentialDataTransferFactsRegistry"
    ]()
    fields, literal_rows = registry.root_validation_table
    rows = tuple(dict(zip(fields, row, strict=True)) for row in literal_rows)

    assert tuple(row["validation"] for row in rows) == (
        "exact-length",
        "visible-ASCII",
        "immediate-end-of-stream",
        "accepted-nonzero-provider-credential",
    )
    assert rows[0]["required_match"] == (
        "exactly-N-nonzero-bytes-with-no-retained-completed-or-transferred-byte-count"
    )
