def test_broker_native_core_credential_data_transfer_terminal_counter_table_is_exact_closed_six_row_lattice() -> None:
    registry = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftCredentialDataTransferFactsRegistry"
    ]()
    fields, literal_rows = registry.terminal_counter_table
    rows = tuple(dict(zip(fields, row, strict=True)) for row in literal_rows)

    assert tuple(row["outcome"] for row in rows) == (
        "pre-lookup-failure",
        "prefix-incomplete-undecodable-or-unavailable-framing-rejected",
        "complete-unavailable-N-zero",
        "nonzero-started-host-write-failure",
        "host-completed-nonzero-root-rejected-framing-or-EOF",
        "accepted-nonzero-credential",
    )
    assert tuple(
        (
            row["credential_lookup_count"],
            row["credential_transfer_attempt_count"],
            row["credential_transfer_completion_count"],
            row["credential_frame_accept_count"],
        )
        for row in rows
    ) == (
        (0, 0, 0, 0),
        (1, 0, 0, 0),
        (1, 0, 0, 0),
        (1, 1, 0, 0),
        (1, 1, 1, 0),
        (1, 1, 1, 1),
    )
    assert all(row["maximum_per_counter"] == 1 for row in rows)
    assert tuple(
        row["provider_credential_construction_permitted"] for row in rows
    ) == (
        False,
        False,
        False,
        False,
        False,
        True,
    )
    assert rows[1]["public_disposition"] == "CAMPAIGN_SECRET_ISOLATION_FAILED"
    assert rows[2]["public_disposition"] == "CAMPAIGN_CREDENTIAL_UNAVAILABLE"
    assert rows[5]["public_disposition"] == (
        "ProviderCredential-construction-and-root-scoped-retention-permitted-with-no-client-materialization-authority"
    )


def test_broker_native_core_credential_data_transfer_cleanup_handoff_freezes_retires_scrubs_and_drains_concurrently() -> None:
    registry = _load_broker_native_core_draft()[
        "_C6BrokerNativeCoreDraftCredentialDataTransferFactsRegistry"
    ]()
    fields, literal_rows = registry.cleanup_successor_table
    rows = tuple(dict(zip(fields, row, strict=True)) for row in literal_rows)

    by_node = {row["node"]: row for row in rows}
    assert set(by_node) == {
        "pre-lookup-admission-failure-lane",
        "freeze-new-credential-data-work",
        "cancel-and-retire-outstanding-credential-data-I/O",
        "host-data-writer-close-and-scrub",
        "mandated-status-handoff",
        "root-concurrent-data-status-pump",
        "root-data-scrub-and-server-close",
        "provider-credential-construction-and-scoped-retention",
    }
    pre_lookup = by_node["pre-lookup-admission-failure-lane"]
    assert pre_lookup["required_action"] == (
        "perform-no-credential-lookup-and-emit-no-credential-data-frame-with-all-four-counters-0000-then-continue-mandated-cleanup-and-status-handoff"
    )
    assert pre_lookup["successor_boundary"] == "CredentialHostStatus-construction"
    freeze = by_node["freeze-new-credential-data-work"]
    assert freeze["required_action"] == (
        "freeze-all-new-credential-data-connect-read-write-and-frame-work-while-exempting-the-one-mandated-CredentialHostStatus-handoff-and-its-cleanup-I/O"
    )
    assert freeze["concurrency_rule"] == (
        "row-order-grants-no-cross-actor-temporal-authority-and-both-sides-freeze-credential-data-work-independently"
    )
    cancel = by_node["cancel-and-retire-outstanding-credential-data-I/O"]
    assert cancel["required_predecessors"] == (
        "new-credential-data-work-frozen",
    )
    assert cancel["required_action"] == (
        "request-cancellation-for-each-outstanding-credential-data-connect-read-and-write-and-consume-every-completion"
    )
    host_close = by_node["host-data-writer-close-and-scrub"]
    assert host_close["required_predecessors"] == (
        "all-host-credential-data-I/O-retired",
    )
    assert host_close["required_action"] == (
        "close-the-credential-data-writer-exactly-once-then-best-effort-overwrite-every-allocated-mutable-payload-and-frame"
    )
    status = by_node["mandated-status-handoff"]
    assert status["successor_boundary"] == (
        "CredentialHostStatus-single-frame-handoff"
    )
    assert status["serialized_or_retained_surface"] == (
        "later-status-payload-and-lifecycle-serialization-out-of-scope"
    )
    pump = by_node["root-concurrent-data-status-pump"]
    assert pump["required_action"] == (
        "drain-credential-data-and-host-status-concurrently-and-never-wait-for-status-before-draining-data"
    )
    root_close = by_node["root-data-scrub-and-server-close"]
    assert root_close["required_action"] == (
        "best-effort-overwrite-mutable-prefix-and-payload-then-close-both-servers-exactly-once"
    )
    retained = by_node["provider-credential-construction-and-scoped-retention"]
    assert retained["required_predecessors"] == (
        "terminal-counter-state-is-exactly-1111",
        "exact-root-accepted-visible-ASCII-payload-decoded-without-substitution",
    )
    assert retained["successor_boundary"] == (
        "later-H-to-P-of-H-to-C-of-H-and-P-to-authenticated-broker-response-and-persistence"
    )
    assert retained["concurrency_rule"] == (
        "1111-is-necessary-but-not-sufficient-for-a-later-authenticated-client-request-and-independently-reopened-launch-evidence-and-this-registry-grants-no-materialization-authority"
    )
    assert all(type(row["node"]) is str for row in rows)


def test_broker_native_core_credential_data_transfer_cross_binds_peer_gate_post_capability_role_caps_and_shared_iocp_facts() -> None:
    namespace = _load_broker_native_core_draft()
    registry = namespace[
        "_C6BrokerNativeCoreDraftCredentialDataTransferFactsRegistry"
    ]()
    peer = namespace[
        "_C6BrokerNativeCoreDraftExecuteCredentialPeerAcceptedFactsRegistry"
    ]()
    readiness = namespace[
        "_C6BrokerNativeCoreDraftExecuteClaimReadyFactsRegistry"
    ]()
    post_capability = namespace[
        "_C6BrokerNativeCoreDraftPostCapabilityCredentialRoleFactsRegistry"
    ]()

    peer_gate_fields, peer_gate_literal_rows = peer.admission_gate_table
    peer_gates = tuple(
        dict(zip(peer_gate_fields, row, strict=True))
        for row in peer_gate_literal_rows
    )
    identity = dict(
        zip(
            registry.identity_table[0],
            registry.identity_table[1][0],
            strict=True,
        )
    )
    assert peer_gates[-1]["gate"] == "fresh-full-host-revalidation"
    assert peer_gates[-1]["successor_boundary"] == (
        "single-credential-lookup-eligibility"
    )
    assert identity["activation_predecessors"] == (
        "canonical-ExecuteClaimReady-emitted-and-validated",
        "post-readiness-one-shot-cleanup-is-mandatory",
    )
    assert identity["lookup_admission_boundary"] == peer_gates[-1][
        "successor_boundary"
    ]
    lookup_fields, lookup_literal_rows = registry.lookup_value_admission_table
    lookup_rows = tuple(
        dict(zip(lookup_fields, row, strict=True)) for row in lookup_literal_rows
    )
    assert all(
        row["lookup_admission_boundary"] == peer_gates[-1]["successor_boundary"]
        for row in lookup_rows
    )
    partial_fields, partial_literal_rows = registry.transfer_partial_order_table
    partial_rows = tuple(
        dict(zip(partial_fields, row, strict=True)) for row in partial_literal_rows
    )
    assert partial_rows[0]["required_predecessors"] == (
        peer_gates[-1]["successor_boundary"],
    )

    counter_fields = (
        "credential_lookup_count",
        "credential_transfer_attempt_count",
        "credential_transfer_completion_count",
        "credential_frame_accept_count",
    )
    peer_named_zero = dict(peer_gates[-1]["failure_counter_state"])
    terminal_fields, terminal_literal_rows = registry.terminal_counter_table
    terminal_rows = tuple(
        dict(zip(terminal_fields, row, strict=True)) for row in terminal_literal_rows
    )
    transfer_pre_lookup = next(
        row for row in terminal_rows if row["outcome"] == "pre-lookup-failure"
    )
    joined_zero = tuple(peer_named_zero[field] for field in counter_fields)
    assert joined_zero == tuple(
        transfer_pre_lookup[field] for field in counter_fields
    ) == (0, 0, 0, 0)
    assert lookup_rows[0]["possible_terminal_counter_states"] == (
        joined_zero,
    )
    assert lookup_rows[0]["wire_action"] == "no-credential-data-frame"
    terminal_states = tuple(
        tuple(row[field] for field in counter_fields) for row in terminal_rows
    )
    assert lookup_rows[2]["possible_terminal_counter_states"] == (
        terminal_states[2],
    ) == ((1, 0, 0, 0),)
    assert lookup_rows[1]["possible_terminal_counter_states"] == tuple(
        dict.fromkeys(terminal_states[1:])
    ) == (
        (1, 0, 0, 0),
        (1, 1, 0, 0),
        (1, 1, 1, 0),
        (1, 1, 1, 1),
    )

    endpoint_fields, endpoint_literal_rows = post_capability.role_endpoint_table
    endpoints = tuple(
        dict(zip(endpoint_fields, row, strict=True)) for row in endpoint_literal_rows
    )
    credential_data = next(
        row for row in endpoints if row["dynamic_role"] == "credential-data"
    )
    assert credential_data["payload_cap_bytes"] == 65_536
    assert credential_data["endpoint_byte_cap_bytes"] == 65_540
    assert credential_data["wire_cap_formula"] == "4+65536"
    assert credential_data["root_action"] == "reads"
    assert credential_data["host_action"] == "writes"

    readiness_name_fields, readiness_name_literal_rows = (
        readiness.pipe_name_embedding_table
    )
    readiness_names = tuple(
        dict(zip(readiness_name_fields, row, strict=True))
        for row in readiness_name_literal_rows
    )
    readiness_data_name = next(
        row for row in readiness_names if row["dynamic_role"] == "credential-data"
    )
    root_fields, root_literal_rows = registry.root_validation_table
    root_rows = tuple(
        dict(zip(root_fields, row, strict=True)) for row in root_literal_rows
    )
    provider_projection = dict(root_rows[-1]["provider_credential_projection"])
    assert provider_projection["transport_version"] == readiness_data_name[
        "transport_version_value"
    ] == "complete-suite-provider-credential-pipe-v1"

    hash_fields, hash_literal_rows = peer.pipe_name_hash_binding_table
    hash_rows = tuple(
        dict(zip(hash_fields, row, strict=True)) for row in hash_literal_rows
    )
    peer_data_hash = next(
        row for row in hash_rows if row["dynamic_role"] == "credential-data"
    )
    assert (
        provider_projection["source_pipe_name_sha256"],
        peer_data_hash["exact_source_expression"],
        peer_data_hash["nested_value_hash_field"],
        readiness_data_name["readiness_field"],
    ) == (
        "validated-readiness-pipe.value_sha256",
        "ExecuteClaimReady.pipe.value_sha256",
        "value_sha256",
        "pipe",
    )
    source_fields, source_literal_rows = peer.source_binding_table
    source_rows = tuple(
        dict(zip(source_fields, row, strict=True)) for row in source_literal_rows
    )
    claim_source = next(
        row for row in source_rows if row["source_family"] == "provider-attempt-claim"
    )
    assert provider_projection["provider_attempt_claim_sha256"] == (
        "authoritative-validated-provider-attempt-claim-sha256"
    )
    assert claim_source["bound_payload_fields"] == (
        "provider_attempt_claim_sha256",
    )
    assert claim_source["caller_supplied"] is False

    shared = dict(
        zip(
            post_capability.shared_constructor_binding_table[0],
            post_capability.shared_constructor_binding_table[1][0],
            strict=True,
        )
    )
    assert tuple(item[0] for item in shared["required_fact_bindings"]) == (
        "issue-ledger-and-exact-packet-retirement",
        "symbolic-IOCP-dispatch",
        "successful-zero-byte-write-failure",
        "absolute-deadline-wait-window",
        "bounded-read-window",
        "length-prefixed-frame-cap-admission",
        "CancelIoEx-call-result",
        "cleanup-completion-retirement",
        "writer-close-eligibility",
        "single-failure-grace",
        "reconciled-close-order",
        "expiry-quarantine",
        "overall-success-convergence",
    )


