def test_broker_native_core_credential_host_status_identity_activation_successor_and_exclusions_are_exact() -> None:
    _, registry = _broker_native_core_credential_host_status_registry()
    fields, rows = registry.identity_table
    predecessor_fields, predecessor_rows = (
        _BROKER_NATIVE_CORE_DRAFT_CREDENTIAL_DATA_TRANSFER_IDENTITY_TABLE
    )
    predecessor_identity = dict(
        zip(predecessor_fields, predecessor_rows[0], strict=True)
    )
    cleanup_fields, cleanup_rows = (
        _BROKER_NATIVE_CORE_DRAFT_CREDENTIAL_DATA_TRANSFER_CLEANUP_SUCCESSOR_TABLE
    )
    cleanup_by_node = {
        row["node"]: row
        for row in (
            dict(zip(cleanup_fields, literal_row, strict=True))
            for literal_row in cleanup_rows
        )
    }

    assert fields == _BROKER_NATIVE_CORE_DRAFT_CREDENTIAL_HOST_STATUS_IDENTITY_TABLE[0]
    assert rows == _BROKER_NATIVE_CORE_DRAFT_CREDENTIAL_HOST_STATUS_IDENTITY_TABLE[1]
    assert len(rows) == 1
    identity = dict(zip(fields, rows[0], strict=True))
    assert identity["record_type"] == "CredentialHostStatus"
    assert identity["dynamic_role"] == "credential-host-status"
    assert identity["producer"] == "trusted-host"
    assert identity["consumer"] == "execute-root-broker"
    assert identity["activation_boundary"] == (
        "canonical-ExecuteClaimReady-emitted-and-validated",
        "any-terminal-CredentialDataTransfer-path-entered",
        "credential-data-writer-closed-exactly-once",
        "credential-data-writer-outstanding-I/O-final-zero",
        "host-mutable-credential-data-buffers-scrubbed-or-absent",
    )
    assert identity["predecessor_boundary"] == (
        predecessor_identity["successor_boundary"]
    ) == "CredentialHostStatus-construction"
    assert {
        cleanup_by_node[node]["successor_boundary"]
        for node in (
            "pre-lookup-admission-failure-lane",
            "host-data-writer-close-and-scrub",
        )
    } == {identity["predecessor_boundary"]}
    admission_fields, admission_rows = registry.status_handoff_table
    admission = dict(zip(admission_fields, admission_rows[0], strict=True))
    assert admission["required_predecessors"] == (
        identity["activation_boundary"][2:5]
    )
    assert identity["successor_boundary"] == (
        "CredentialPipeLifecycleRecord-construction-as-P-of-H"
    )
    assert "pre-lookup-failure" in identity["applicability"]
    assert identity["excluded_semantic_scopes"] == (
        "CredentialPipeLifecycleRecord-payload-and-serialization",
        "CredentialLifecycleRecord-construction-and-serialization",
        "broker-response-sequencing",
        "durable-persistence",
        "client-environment-materialization",
        "private-error-projection",
        "runtime-I/O-authority",
    )


def test_broker_native_core_credential_host_status_payload_schema_wire_wrapper_and_secret_exclusions_are_exact() -> None:
    _, registry = _broker_native_core_credential_host_status_registry()
    fields, rows = registry.payload_schema_table
    assert len(rows) == 1
    schema = dict(zip(fields, rows[0], strict=True))
    expected_serialized_fields = (
        "version",
        "transport_version",
        "provider_attempt_claim_sha256",
        "execute_claim_capability_sha256",
        "claim_ready_sha256",
        "peer_accepted_sha256",
        "pipe_name_sha256",
        "host_status_pipe_name_sha256",
        "host_pid",
        "host_creation_time",
        "root_pid",
        "root_creation_time",
        "frame_kind",
        "prefix_progress",
        "payload_progress",
        "outcome",
        "credential_lookup_count",
        "credential_transfer_attempt_count",
        "credential_transfer_completion_count",
        "credential_data_writer_closed",
        "credential_data_writer_outstanding_io_final",
        "host_mutable_buffers_scrubbed_or_absent",
    )

    assert schema["record_type"] == "CredentialHostStatus"
    assert schema["schema_version"] == "complete-suite-credential-host-status-v1"
    assert schema["serialized_field_order"] == expected_serialized_fields
    assert len(schema["serialized_field_order"]) == 22
    assert schema["wrapper_only_fields"] == ("canonical_sha256",)
    field_domains = dict(schema["field_domain_table"])
    assert field_domains["peer_accepted_sha256"] == (
        "null-if-no-canonical-peer-accepted-frame-was-successfully-emitted",
        "exact-emitted-wrapper-canonical_sha256-after-successful-root-emission",
    )
    assert schema["payload_cap_bytes"] == 65_536
    assert schema["maximum_wire_bytes"] == 65_540
    assert dict(schema["outer_frame_contract"]) == {
        "length_prefix_bytes": 4,
        "length_prefix_type": "unsigned-payload-byte-length",
        "length_prefix_endianness": "little-endian",
        "payload_encoding": "strict-ASCII",
        "payload_canonical_form": "compact-JSON-plus-one-LF",
        "writer_termination": "writer-close-then-EOF",
    }
    assert "canonical_sha256" not in schema["serialized_field_order"]
    assert "credential_frame_accept_count" not in schema["serialized_field_order"]
    assert {
        "N-or-credential-bytes-or-value",
        "exact-or-rounded-credential-payload-length",
        "credential-data-transferred-byte-count",
        "credential-or-length-derived-hash",
    }.issubset(schema["forbidden_payload_categories"])


def test_broker_native_core_credential_host_status_source_bindings_and_optional_peer_hash_rule_are_exact() -> None:
    _, registry = _broker_native_core_credential_host_status_registry()
    fields, rows = registry.source_binding_table
    bindings = {
        row[0]: dict(zip(fields, row, strict=True))
        for row in rows
    }

    assert tuple(bindings) == (
        "schema-and-transport-versions",
        "provider-attempt-claim-wrapper-hash",
        "execute-claim-capability-wrapper-hash",
        "execute-claim-ready-wrapper-hash",
        "optional-peer-accepted-wrapper-hash",
        "readiness-nested-pipe-name-value-hashes",
        "authenticated-host-peer-identity",
        "authenticated-root-peer-identity",
        "retired-host-credential-data-ledger-projection",
        "credential-data-cleanup-convergence",
    )
    peer_rule = bindings["optional-peer-accepted-wrapper-hash"]
    assert peer_rule["bound_payload_fields"] == ("peer_accepted_sha256",)
    assert peer_rule["authoritative_sources"] == (
        "exact-canonical-ExecuteCredentialPeerAccepted-wrapper-after-successful-root-emission",
    )
    assert peer_rule["required_agreement"] == (
        "null-if-and-only-if-no-canonical-peer-accepted-frame-was-successfully-emitted-otherwise-the-exact-emitted-wrapper-canonical_sha256"
    )
    assert peer_rule["phase_rule"] == (
        "not-emitted-implies-pre-lookup-failure-000-and-null; emitted-implies-pre-lookup-failure-or-later-outcome-with-the-exact-non-null-hash; inability-to-produce-an-exact-coherent-post-readiness-H-is-invalid_consumed_attempt"
    )
    gate_fields, gate_rows = (
        _BROKER_NATIVE_CORE_DRAFT_EXECUTE_CREDENTIAL_PEER_ACCEPTED_ADMISSION_GATE_TABLE
    )
    gates = {
        gate["gate"]: gate
        for gate in (
            dict(zip(gate_fields, literal_row, strict=True))
            for literal_row in gate_rows
        )
    }
    emission_gate = gates["root-emits-one-canonical-peer-accepted-frame"]
    host_validation_gate = gates["host-validates-one-exact-peer-accepted-frame"]
    assert emission_gate["actor"] == "execute-root-broker"
    assert emission_gate["required_action_or_match"].startswith(
        "construct-and-emit-exactly-one-canonical-ExecuteCredentialPeerAccepted"
    )
    assert emission_gate["successor_boundary"] == host_validation_gate["gate"]
    assert emission_gate["gate"] != host_validation_gate["gate"]
    pipe_rule = bindings["readiness-nested-pipe-name-value-hashes"]
    assert pipe_rule["bound_payload_fields"] == (
        "pipe_name_sha256",
        "host_status_pipe_name_sha256",
    )
    assert "nested-value-sha256" in pipe_rule["required_agreement"]
    cleanup_rule = bindings["credential-data-cleanup-convergence"]
    assert cleanup_rule["required_agreement"] == "exactly-True-zero-True"
    assert cleanup_rule["phase_rule"].endswith(
        "does-not-cover-status-writer-I/O"
    )
    assert all(binding["caller_supplied"] is False for binding in bindings.values())


def test_broker_native_core_credential_host_status_four_host_projections_are_closed_and_relational() -> None:
    _, registry = _broker_native_core_credential_host_status_registry()
    fields, rows = registry.host_projection_table
    projections = {
        row[0]: dict(zip(fields, row, strict=True))
        for row in rows
    }
    payload_fields, payload_rows = registry.payload_schema_table
    payload_schema = dict(
        zip(payload_fields, payload_rows[0], strict=True)
    )
    field_domains = dict(payload_schema["field_domain_table"])

    assert len(rows) == 4
    assert tuple(projections) == (
        "pre-lookup-failure",
        "credential-unavailable",
        "host-transfer-failure",
        "host-transfer-complete",
    )
    assert tuple(
        projections["pre-lookup-failure"][name]
        for name in (
            "frame_kind",
            "prefix_progress",
            "payload_progress",
            "credential_lookup_count",
            "credential_transfer_attempt_count",
            "credential_transfer_completion_count",
        )
    ) == ("none", "none", "not-applicable", 0, 0, 0)
    assert tuple(
        projections["credential-unavailable"][name]
        for name in (
            "frame_kind",
            "prefix_progress",
            "payload_progress",
            "credential_lookup_count",
            "credential_transfer_attempt_count",
            "credential_transfer_completion_count",
        )
    ) == ("unavailable", "complete", "not-applicable", 1, 0, 0)
    failure = projections["host-transfer-failure"]
    failure_relation = failure["admissible_cursor_projections"]
    expected_failure_relation = (
        ("indeterminate", "none", "not-applicable", 0),
        ("indeterminate", "partial", "not-applicable", 0),
        ("unavailable", "complete", "not-applicable", 0),
        ("nonzero", "complete", "none", 1),
        ("nonzero", "complete", "partial", 1),
    )
    assert failure_relation == expected_failure_relation
    assert failure["credential_lookup_count"] == 1
    assert failure["credential_transfer_attempt_count"] == (0, 1)
    assert failure["credential_transfer_completion_count"] == 0
    cursor_fields = (
        "frame_kind",
        "prefix_progress",
        "payload_progress",
        "credential_transfer_attempt_count",
    )
    for projection in projections.values():
        for field in cursor_fields:
            cell = projection[field]
            cell_values = cell if isinstance(cell, tuple) else (cell,)
            assert cell_values
            assert all(value in field_domains[field] for value in cell_values)
        assert all(
            cursor[0] in field_domains["frame_kind"]
            and cursor[1] in field_domains["prefix_progress"]
            and cursor[2] in field_domains["payload_progress"]
            and cursor[3] in field_domains["credential_transfer_attempt_count"]
            for cursor in projection["admissible_cursor_projections"]
        )
    for field_index, field in enumerate(cursor_fields):
        assert failure[field] == tuple(
            dict.fromkeys(cursor[field_index] for cursor in failure_relation)
        )
    assert all(
        (payload_progress == "not-applicable") == (frame_kind != "nonzero")
        for frame_kind, _, payload_progress, _ in failure_relation
    )
    assert all(
        frame_kind == "nonzero"
        and prefix_progress == "complete"
        and payload_progress in {"none", "partial"}
        for frame_kind, prefix_progress, payload_progress, attempt_count in failure_relation
        if attempt_count == 1
    )
    assert all(
        payload_progress == "not-applicable"
        for _, _, payload_progress, attempt_count in failure_relation
        if attempt_count == 0
    )
    assert all(
        (
            failure["credential_lookup_count"],
            failure["credential_transfer_completion_count"],
        ) == (1, 0)
        for _ in failure_relation
    )
    assert ("nonzero", "complete", "complete", 1) not in failure_relation
    assert ("unavailable", "complete", "not-applicable", 0) in failure_relation
    unavailable = projections["credential-unavailable"]
    assert unavailable["admissible_cursor_projections"] == (
        ("unavailable", "complete", "not-applicable", 0),
    )
    assert unavailable["required_host_evidence"] == (
        "authoritative-retired-host-operation-and-completion-ledger-proves-the-exact-four-byte-N-zero-prefix-completed-successfully-before-data-writer-close"
    )
    assert failure["required_host_evidence"] == (
        "authoritative-retired-host-operation-and-completion-ledger-proves-a-required-prefix-or-payload-write-did-not-complete-successfully-at-the-exact-retired-write-cursor"
    )
    assert unavailable["required_host_evidence"] != failure["required_host_evidence"]
    assert "no-Cartesian-widening" in failure["relational_rule"]
    complete = projections["host-transfer-complete"]
    assert tuple(
        complete[name]
        for name in (
            "frame_kind",
            "prefix_progress",
            "payload_progress",
            "credential_lookup_count",
            "credential_transfer_attempt_count",
            "credential_transfer_completion_count",
        )
    ) == ("nonzero", "complete", "complete", 1, 1, 1)
    assert "zero-or-one" in complete["root_accept_projection"]


