def test_broker_native_core_credential_host_status_handoff_seals_cleanup_one_frame_eof_and_distinct_status_io() -> None:
    _, registry = _broker_native_core_credential_host_status_registry()
    fields, rows = registry.status_handoff_table
    handoff = {
        row[1]: dict(zip(fields, row, strict=True))
        for row in rows
    }

    assert tuple(handoff) == (
        "status-construction-admission",
        "canonical-status-payload-construction",
        "single-status-frame-issue",
        "status-writer-close",
        "root-concurrent-data-status-pump",
    )
    assert handoff["status-construction-admission"]["required_predecessors"] == (
        "credential-data-writer-closed-exactly-once",
        "credential-data-writer-outstanding-I/O-final-zero",
        "host-mutable-credential-data-buffers-scrubbed-or-absent",
    )
    assert handoff["canonical-status-payload-construction"][
        "required_action"
    ].endswith("one-compact-strict-ASCII-JSON-object-plus-one-LF")
    assert handoff["single-status-frame-issue"]["required_action"] == (
        "issue-one-unsigned-four-byte-little-endian-payload-length-followed-by-the-exact-payload"
    )
    assert handoff["status-writer-close"]["retirement_or_hash_rule"] == (
        "the-CredentialHostStatus-data-writer-outstanding-I/O-field-does-not-claim-status-writer-retirement"
    )
    assert handoff["root-concurrent-data-status-pump"]["required_action"] == (
        "drain-both-channels-concurrently-and-never-wait-for-status-before-draining-credential-data"
    )
    transfer_cleanup_fields, transfer_cleanup_rows = (
        _BROKER_NATIVE_CORE_DRAFT_CREDENTIAL_DATA_TRANSFER_CLEANUP_SUCCESSOR_TABLE
    )
    transfer_pump = next(
        row
        for row in (
            dict(zip(transfer_cleanup_fields, literal_row, strict=True))
            for literal_row in transfer_cleanup_rows
        )
        if row["node"] == "root-concurrent-data-status-pump"
    )
    assert transfer_pump["concurrency_rule"] == (
        "both-channel-ledgers-progress-independently-under-one-deadline"
    )
    assert handoff["root-concurrent-data-status-pump"]["concurrency_rule"] == (
        "status-handoff-table-row-order-grants-no-cross-actor-temporal-authority",
        transfer_pump["concurrency_rule"].replace(
            "channel-ledgers", "read-ledgers"
        ),
    )
    assert all("waits-for-no-root-response" in row[-1] for row in rows[:1] + rows[3:4])


def test_broker_native_core_credential_host_status_root_validation_preserves_exact_H_and_advances_only_to_P_of_H() -> None:
    _, registry = _broker_native_core_credential_host_status_registry()
    fields, rows = registry.root_validation_table
    validations = {
        row[1]: dict(zip(fields, row, strict=True))
        for row in rows
    }

    assert tuple(validations) == (
        "single-bounded-canonical-frame-and-EOF",
        "binding-and-wrapper-hash-validation",
        "peer-identity-validation",
        "credential-data-observation-and-host-projection-validation",
        "post-readiness-presence-rule",
    )
    assert len(rows) == 5
    post_readiness = validations["post-readiness-presence-rule"]
    assert "invalid_consumed_attempt" in post_readiness["failure_disposition"]
    assert post_readiness["successor_boundary"] == (
        "CredentialPipeLifecycleRecord-construction-as-P-of-H"
    )
    projection = validations[
        "credential-data-observation-and-host-projection-validation"
    ]
    assert projection["input_authority"] == (
        "exact-authenticated-received-CredentialHostStatus-H-root-owned-credential-data-pipe-observations-and-closed-CredentialHostStatus-host-projection-table"
    )
    assert "retired-host" not in projection["input_authority"]
    assert projection["retained_or_serialized_surface"] == (
        "preserve-the-exact-authenticated-H-and-its-exact-hash-without-rewriting-host-outcome-from-root-acceptance"
    )
    source_fields, source_rows = registry.source_binding_table
    host_ledger_binding = next(
        binding
        for binding in (
            dict(zip(source_fields, literal_row, strict=True))
            for literal_row in source_rows
        )
        if binding["source_family"]
        == "retired-host-credential-data-ledger-projection"
    )
    assert host_ledger_binding["authoritative_sources"] == (
        "retired-host-operation-ledger",
        "immutable-coarse-terminal-counter-state",
    )
    assert host_ledger_binding["phase_rule"] == (
        "constructed-only-after-no-host-credential-data-I/O-can-reference-a-buffer"
    )
    assert all(
        "retired-host" not in validation["input_authority"]
        for validation in validations.values()
    )
    validation_names = frozenset(validations)
    assert {
        validation["successor_boundary"]
        for validation in validations.values()
        if validation["successor_boundary"] not in validation_names
    } == {"CredentialPipeLifecycleRecord-construction-as-P-of-H"}
    assert (
        "before-canonical-ExecuteClaimReady-there-is-no-H-P-or-C-and-all-four-counters-are-zero"
        in registry.invariants
    )
    assert "pre-readiness-controlled-failure-boundary" not in validations
    assert all(
        row["successor_boundary"]
        not in {
            "CredentialLifecycleRecord-construction",
            "authenticated-broker-response",
            "durable-persistence",
        }
        for row in validations.values()
    )


def test_broker_native_core_credential_host_status_cross_binds_readiness_peer_and_transfer_predecessors_relationally() -> None:
    _, registry = _broker_native_core_credential_host_status_registry()
    payload = dict(
        zip(
            registry.payload_schema_table[0],
            registry.payload_schema_table[1][0],
            strict=True,
        )
    )
    status_fields = payload["serialized_field_order"]
    readiness_fields = (
        _BROKER_NATIVE_CORE_DRAFT_EXECUTE_CLAIM_READY_PAYLOAD_SCHEMA_TABLE[1][0][2]
    )
    peer_fields = (
        _BROKER_NATIVE_CORE_DRAFT_EXECUTE_CREDENTIAL_PEER_ACCEPTED_PAYLOAD_SCHEMA_TABLE[1][0][2]
    )
    readiness_pipe_rows = (
        _BROKER_NATIVE_CORE_DRAFT_EXECUTE_CLAIM_READY_PIPE_NAME_EMBEDDING_TABLE[1]
    )
    status_pipe_row = next(
        row for row in readiness_pipe_rows if row[0] == "host_status_pipe"
    )
    status_source_fields, status_source_rows = registry.source_binding_table
    status_bindings = {
        binding["source_family"]: binding
        for binding in (
            dict(zip(status_source_fields, literal_row, strict=True))
            for literal_row in status_source_rows
        )
    }
    peer_source_fields, peer_source_rows = (
        _BROKER_NATIVE_CORE_DRAFT_EXECUTE_CREDENTIAL_PEER_ACCEPTED_SOURCE_BINDING_TABLE
    )
    peer_bindings = {
        binding["source_family"]: binding
        for binding in (
            dict(zip(peer_source_fields, literal_row, strict=True))
            for literal_row in peer_source_rows
        )
    }
    pipe_binding_fields, pipe_binding_rows = (
        _BROKER_NATIVE_CORE_DRAFT_EXECUTE_CREDENTIAL_PEER_ACCEPTED_PIPE_NAME_HASH_BINDING_TABLE
    )
    pipe_bindings = {
        binding["payload_field"]: binding
        for binding in (
            dict(zip(pipe_binding_fields, literal_row, strict=True))
            for literal_row in pipe_binding_rows
        )
    }
    process_binding_fields, process_binding_rows = (
        _BROKER_NATIVE_CORE_DRAFT_EXECUTE_CLAIM_READY_PROCESS_IDENTITY_BINDING_TABLE
    )
    process_bindings = {
        binding["identity_domain"]: binding
        for binding in (
            dict(zip(process_binding_fields, literal_row, strict=True))
            for literal_row in process_binding_rows
        )
    }

    provider_status = status_bindings["provider-attempt-claim-wrapper-hash"]
    provider_peer = peer_bindings["provider-attempt-claim"]
    assert provider_status["bound_payload_fields"] == provider_peer[
        "bound_payload_fields"
    ] == ("provider_attempt_claim_sha256",)
    assert provider_status["authoritative_sources"] == provider_peer[
        "authoritative_sources"
    ]

    capability_status = status_bindings[
        "execute-claim-capability-wrapper-hash"
    ]
    capability_peer = peer_bindings["capability-wrapper-hash"]
    assert capability_status["bound_payload_fields"] == capability_peer[
        "bound_payload_fields"
    ] == ("execute_claim_capability_sha256",)
    assert capability_status["authoritative_sources"] == capability_peer[
        "authoritative_sources"
    ]

    pipe_status = status_bindings[
        "readiness-nested-pipe-name-value-hashes"
    ]
    pipe_peer = peer_bindings["readiness-nested-name-value-hashes"]
    pipe_fields = ("pipe_name_sha256", "host_status_pipe_name_sha256")
    assert pipe_status["bound_payload_fields"] == pipe_peer[
        "bound_payload_fields"
    ] == pipe_fields
    exact_pipe_sources = tuple(
        pipe_bindings[field]["exact_source_expression"] for field in pipe_fields
    )
    assert pipe_status["authoritative_sources"] == pipe_peer[
        "authoritative_sources"
    ] == exact_pipe_sources
    assert all(
        pipe_bindings[field]["nested_value_hash_field"] == "value_sha256"
        and pipe_bindings[field]["forbidden_nested_wrapper_hash_field"]
        == "canonical_sha256"
        for field in pipe_fields
    )

    for identity_domain, status_family, peer_family in (
        (
            "host",
            "authenticated-host-peer-identity",
            "authenticated-host-peer-identity",
        ),
        (
            "root",
            "authenticated-root-peer-identity",
            "authenticated-root-peer-identity",
        ),
    ):
        process_binding = process_bindings[identity_domain]
        peer_binding = peer_bindings[peer_family]
        status_binding = status_bindings[status_family]
        exact_identity_fields = (
            process_binding["pid_field"],
            process_binding["creation_time_field"],
        )
        assert status_binding["bound_payload_fields"] == peer_binding[
            "bound_payload_fields"
        ] == exact_identity_fields
        assert status_binding["authoritative_sources"] == (
            process_binding["authoritative_source"],
            *peer_binding["authoritative_sources"],
        )
        assert process_binding["pid_only_authority"] is False

    gate_fields, gate_rows = (
        _BROKER_NATIVE_CORE_DRAFT_EXECUTE_CREDENTIAL_PEER_ACCEPTED_ADMISSION_GATE_TABLE
    )
    gates = {
        gate["gate"]: gate
        for gate in (
            dict(zip(gate_fields, literal_row, strict=True))
            for literal_row in gate_rows
        )
    }
    emission_gate = gates["root-emits-one-canonical-peer-accepted-frame"]
    peer_hash_status = status_bindings["optional-peer-accepted-wrapper-hash"]
    exact_host_status_source_by_gate = {
        "root-emits-one-canonical-peer-accepted-frame": (
            "exact-canonical-ExecuteCredentialPeerAccepted-wrapper-after-successful-root-emission"
        ),
    }
    assert peer_hash_status["bound_payload_fields"] == (
        "peer_accepted_sha256",
    )
    assert peer_hash_status["authoritative_sources"] == (
        exact_host_status_source_by_gate[emission_gate["gate"]],
    )
    assert emission_gate["successor_boundary"] == (
        "host-validates-one-exact-peer-accepted-frame"
    )
    assert emission_gate["gate"] != emission_gate["successor_boundary"]

    assert {
        "provider_attempt_claim_sha256",
        "execute_claim_capability_sha256",
        "peer_accepted_sha256",
        *pipe_fields,
        "host_pid",
        "host_creation_time",
        "root_pid",
        "root_creation_time",
    }.issubset(status_fields)
    assert {
        "provider_attempt_claim_sha256",
        "execute_claim_capability_sha256",
        *pipe_fields,
        "host_pid",
        "host_creation_time",
        "root_pid",
        "root_creation_time",
    }.issubset(peer_fields)
    assert "credential_transport_version" in readiness_fields
    assert "host_status_pipe" in readiness_fields
    assert status_pipe_row[7] == payload["payload_cap_bytes"] == 65_536
    assert payload["maximum_wire_bytes"] == payload["payload_cap_bytes"] + 4
    assert tuple(
        row[1]
        for row in registry.credential_data_join_table[1]
    ) == tuple(
        tuple(row[1:5])
        for row in _BROKER_NATIVE_CORE_DRAFT_CREDENTIAL_DATA_TRANSFER_TERMINAL_COUNTER_TABLE[1]
    )


