def test_broker_native_core_credential_host_status_registry_is_exact_class_immutable_bounded_dormant_and_hostile_protocol_safe() -> None:
    namespace = _load_broker_native_core_draft()
    registry_type, registry = _broker_native_core_credential_host_status_registry()
    property_names = (
        "identity_table",
        "payload_schema_table",
        "source_binding_table",
        "host_projection_table",
        "credential_data_join_table",
        "status_handoff_table",
        "root_validation_table",
        "invariants",
    )
    expected_summary = (
        "_C6BrokerNativeCoreDraftCredentialHostStatusFactsRegistry("
        f"identity_row_count={len(registry.identity_table[1])!r}, "
        f"payload_schema_row_count={len(registry.payload_schema_table[1])!r}, "
        f"source_binding_row_count={len(registry.source_binding_table[1])!r}, "
        f"host_projection_row_count={len(registry.host_projection_table[1])!r}, "
        f"credential_data_join_row_count={len(registry.credential_data_join_table[1])!r}, "
        f"status_handoff_row_count={len(registry.status_handoff_table[1])!r}, "
        f"root_validation_row_count={len(registry.root_validation_table[1])!r}, "
        f"invariant_count={len(registry.invariants)!r})"
    )

    assert repr(registry) == expected_summary
    assert str(registry) == expected_summary
    assert len(repr(registry)) < 500
    assert not hasattr(registry, "__dict__")
    for property_name in property_names:
        with pytest.raises(AttributeError):
            setattr(registry, property_name, ())
    with pytest.raises(TypeError):
        registry[0] = ()

    hostile_calls: list[str] = []

    class HostileProtocol:
        def __getattribute__(self, name: str) -> object:
            if name.startswith("__"):
                hostile_calls.append(name)
            return object.__getattribute__(self, name)

        def __iter__(self):
            hostile_calls.append("__iter__")
            raise AssertionError("hostile protocol iterated")

        def __index__(self):
            hostile_calls.append("__index__")
            raise AssertionError("hostile protocol indexed")

    hostile = HostileProtocol()
    with pytest.raises(TypeError):
        registry_type(hostile)
    with pytest.raises(TypeError):
        registry_type(context=hostile)
    assert hostile_calls == []

    class Derived(registry_type):
        pass

    with pytest.raises(RuntimeError) as rejection:
        Derived()
    assert rejection.value.args == ("GUARDED_BOOTSTRAP_INVALID",)

    module_calls: list[str] = []

    class ForbiddenModule:
        def __getattribute__(self, name: str) -> object:
            if name.startswith("__"):
                return object.__getattribute__(self, name)
            module_calls.append(name)
            raise AssertionError("CredentialHostStatus facts used a module")

    originals = {
        module_name: namespace[module_name]
        for module_name in ("json", "hashlib", "os", "sys")
    }
    namespace.update(
        {module_name: ForbiddenModule() for module_name in originals}
    )
    try:
        poisoned = registry_type()
        poisoned_values = tuple(
            getattr(poisoned, property_name) for property_name in property_names
        )
        poisoned_repr = repr(poisoned)
        poisoned_str = str(poisoned)
    finally:
        namespace.update(originals)
    assert tuple(poisoned) == tuple(registry)
    assert poisoned_values == tuple(registry)
    assert poisoned_repr == expected_summary
    assert poisoned_str == expected_summary
    assert module_calls == []

    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    class_name = "_C6BrokerNativeCoreDraftCredentialHostStatusFactsRegistry"
    class_node = next(
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )
    class_descendants = frozenset(ast.walk(class_node))
    assert not any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == class_name
        and node not in class_descendants
        for node in ast.walk(tree)
    )
    assert tuple(
        alias.name
        for node in tree.body
        if isinstance(node, ast.Import)
        for alias in node.names
    ) == ("hashlib", "json", "os", "sys")


