def test_broker_native_core_credential_host_status_mutation_matrix_is_unique_complete_and_bounded() -> None:
    replacement_mutations = (
        _BROKER_NATIVE_CORE_DRAFT_CREDENTIAL_HOST_STATUS_LITERAL_REPLACEMENT_SPECS
    )
    sequence_mutations = (
        _BROKER_NATIVE_CORE_DRAFT_CREDENTIAL_HOST_STATUS_LITERAL_SEQUENCE_SPECS
    )
    literal_mutations = (
        _BROKER_NATIVE_CORE_DRAFT_CREDENTIAL_HOST_STATUS_LITERAL_MUTATIONS
    )
    structural_mutations = (
        _BROKER_NATIVE_CORE_DRAFT_CREDENTIAL_HOST_STATUS_STRUCTURAL_MUTATIONS
    )
    mutations = _BROKER_NATIVE_CORE_DRAFT_CREDENTIAL_HOST_STATUS_MUTATIONS

    assert replacement_mutations
    assert sequence_mutations
    assert len(_BROKER_NATIVE_CORE_DRAFT_CREDENTIAL_HOST_STATUS_METHOD_MUTATIONS) == 18
    assert len(_BROKER_NATIVE_CORE_DRAFT_CREDENTIAL_HOST_STATUS_CALL_MUTATIONS) == 5
    assert len(
        _BROKER_NATIVE_CORE_DRAFT_CREDENTIAL_HOST_STATUS_ASSIGNMENT_MUTATIONS
    ) == 4
    assert len(structural_mutations) == 30
    assert len(literal_mutations) == len(replacement_mutations) + len(
        sequence_mutations
    )
    assert len(mutations) == len(literal_mutations) + len(structural_mutations)
    assert len(set(mutations)) == len(mutations)
    assert set(literal_mutations).isdisjoint(structural_mutations)
    assert {
        (assignment_index, assignment_name, path)
        for _, assignment_index, assignment_name, path, _ in replacement_mutations
    } == {
        (assignment_index, assignment_name, path)
        for assignment_index, (
            assignment_name,
            assignment_value,
        ) in enumerate(
            _BROKER_NATIVE_CORE_DRAFT_CREDENTIAL_HOST_STATUS_ASSIGNMENT_VALUES
        )
        for path, _ in _broker_native_core_literal_tuple_leaf_paths(assignment_value)
    }
    assert {
        (assignment_index, assignment_name, path, swap_index)
        for _, assignment_index, assignment_name, path, swap_index in sequence_mutations
    } == {
        (assignment_index, assignment_name, path, swap_index)
        for assignment_index, (
            assignment_name,
            assignment_value,
        ) in enumerate(
            _BROKER_NATIVE_CORE_DRAFT_CREDENTIAL_HOST_STATUS_ASSIGNMENT_VALUES
        )
        for path, swap_index in _broker_native_core_literal_tuple_sequence_paths(
            assignment_value
        )
    }
    mutant_module_asts = tuple(
        ast.dump(
            ast.parse(_broker_native_core_credential_host_status_mutant(mutation)),
            include_attributes=False,
        )
        for mutation in mutations
    )
    assert len(set(mutant_module_asts)) == len(mutations)


