def test_broker_native_core_draft_iocp_arithmetic_rejects_nonexact_types_before_protocols() -> None:
    namespace = _load_broker_native_core_draft()
    wait_type = namespace["_C6BrokerNativeCoreDraftIocpWaitWindow"]
    read_type = namespace["_C6BrokerNativeCoreDraftWireReadWindow"]
    frame_type = namespace["_C6BrokerNativeCoreDraftControlFrameAdmission"]
    calls: list[str] = []

    class _IntSubclass(int):
        def __bool__(self) -> bool:
            calls.append("subclass-bool")
            raise AssertionError("int subclass truth dispatched")

        def __lt__(self, _other: object) -> bool:
            calls.append("subclass-lt")
            raise AssertionError("int subclass comparison dispatched")

        def __le__(self, _other: object) -> bool:
            calls.append("subclass-le")
            raise AssertionError("int subclass comparison dispatched")

        def __gt__(self, _other: object) -> bool:
            calls.append("subclass-gt")
            raise AssertionError("int subclass comparison dispatched")

        def __add__(self, _other: object) -> object:
            calls.append("subclass-add")
            raise AssertionError("int subclass addition dispatched")

        def __radd__(self, _other: object) -> object:
            calls.append("subclass-radd")
            raise AssertionError("int subclass reverse addition dispatched")

        def __sub__(self, _other: object) -> object:
            calls.append("subclass-sub")
            raise AssertionError("int subclass subtraction dispatched")

        def __rsub__(self, _other: object) -> object:
            calls.append("subclass-rsub")
            raise AssertionError("int subclass reverse subtraction dispatched")

        def __floordiv__(self, _other: object) -> object:
            calls.append("subclass-floordiv")
            raise AssertionError("int subclass division dispatched")

    class _Hostile:
        def __bool__(self) -> bool:
            calls.append("hostile-bool")
            raise AssertionError("hostile truth dispatched")

        def __lt__(self, _other: object) -> bool:
            calls.append("hostile-lt")
            raise AssertionError("hostile comparison dispatched")

        def __le__(self, _other: object) -> bool:
            calls.append("hostile-le")
            raise AssertionError("hostile comparison dispatched")

        def __gt__(self, _other: object) -> bool:
            calls.append("hostile-gt")
            raise AssertionError("hostile comparison dispatched")

        def __add__(self, _other: object) -> object:
            calls.append("hostile-add")
            raise AssertionError("hostile addition dispatched")

        def __radd__(self, _other: object) -> object:
            calls.append("hostile-radd")
            raise AssertionError("hostile reverse addition dispatched")

        def __sub__(self, _other: object) -> object:
            calls.append("hostile-sub")
            raise AssertionError("hostile subtraction dispatched")

        def __rsub__(self, _other: object) -> object:
            calls.append("hostile-rsub")
            raise AssertionError("hostile reverse subtraction dispatched")

        def __floordiv__(self, _other: object) -> object:
            calls.append("hostile-floordiv")
            raise AssertionError("hostile division dispatched")

        def __getattribute__(self, name: str) -> object:
            if name.startswith("__"):
                return object.__getattribute__(self, name)
            calls.append(f"hostile-attribute:{name}")
            raise AssertionError("hostile attribute dispatched")

    subclass = _IntSubclass(1)
    hostile = _Hostile()
    rejected_calls = (
        (wait_type, (subclass,)),
        (wait_type, (hostile,)),
        (read_type, (subclass, 0)),
        (read_type, (1, subclass)),
        (read_type, (hostile, 0)),
        (read_type, (1, hostile)),
        (frame_type, (subclass, 0)),
        (frame_type, (4, subclass)),
        (frame_type, (hostile, 0)),
        (frame_type, (4, hostile)),
    )

    class _ForbiddenModule:
        def __getattribute__(self, name: str) -> object:
            if name.startswith("__"):
                return object.__getattribute__(self, name)
            calls.append(f"module:{name}")
            raise AssertionError("module reached before exact rejection")

    originals = {
        module_name: namespace[module_name]
        for module_name in ("json", "hashlib", "os", "sys")
    }
    namespace.update(
        {module_name: _ForbiddenModule() for module_name in originals}
    )
    try:
        for constructor, arguments in rejected_calls:
            with pytest.raises(RuntimeError) as rejection:
                constructor(*arguments)
            assert rejection.type is RuntimeError
            assert rejection.value.args == ("GUARDED_BOOTSTRAP_INVALID",)
    finally:
        namespace.update(originals)
    assert calls == []


def test_broker_native_core_draft_iocp_arithmetic_is_module_dependency_free() -> None:
    namespace = _load_broker_native_core_draft()
    wait_type = namespace["_C6BrokerNativeCoreDraftIocpWaitWindow"]
    read_type = namespace["_C6BrokerNativeCoreDraftWireReadWindow"]
    frame_type = namespace["_C6BrokerNativeCoreDraftControlFrameAdmission"]
    calls: list[str] = []

    class _ForbiddenModule:
        def __getattribute__(self, name: str) -> object:
            if name.startswith("__"):
                return object.__getattribute__(self, name)
            calls.append(f"module:{name}")
            raise AssertionError("arithmetic constructor reached a module")

    originals = {
        module_name: namespace[module_name]
        for module_name in ("json", "hashlib", "os", "sys")
    }
    namespace.update(
        {module_name: _ForbiddenModule() for module_name in originals}
    )
    try:
        assert tuple(wait_type(1_000_001)) == (1_000_001, 2)
        assert tuple(read_type(65_536, 65_535)) == (65_536, 65_535, 1, 2)
        assert tuple(frame_type(65_540, 65_536)) == (65_540, 65_536, 65_540)
    finally:
        namespace.update(originals)
    assert calls == []


def test_broker_native_core_draft_iocp_arithmetic_surfaces_are_exact_immutable_and_closed() -> None:
    namespace = _load_broker_native_core_draft()
    specifications = (
        (
            "_C6BrokerNativeCoreDraftIocpWaitWindow",
            ("remaining_monotonic_ns",),
            (1_000_001,),
            ("remaining_monotonic_ns", "wait_timeout_ms"),
        ),
        (
            "_C6BrokerNativeCoreDraftWireReadWindow",
            ("byte_cap", "completed_wire_bytes"),
            (65_536, 65_535),
            (
                "byte_cap",
                "completed_wire_bytes",
                "remaining_cap_bytes",
                "maximum_read_request_bytes",
            ),
        ),
        (
            "_C6BrokerNativeCoreDraftControlFrameAdmission",
            ("remaining_cap_bytes", "payload_length_bytes"),
            (65_540, 65_536),
            (
                "remaining_cap_bytes",
                "payload_length_bytes",
                "frame_wire_bytes",
            ),
        ),
    )

    for class_name, argument_names, arguments, property_names in specifications:
        constructor = namespace[class_name]
        assert tuple(inspect.signature(constructor.__new__).parameters) == (
            "cls",
            *argument_names,
        )
        assert tuple(inspect.signature(constructor).parameters) == argument_names
        keyword_arguments = dict(zip(argument_names, arguments, strict=True))
        assert constructor(**keyword_arguments) == constructor(*arguments)
        assert tuple(
            name
            for name, value in vars(constructor).items()
            if isinstance(value, property)
        ) == property_names
        instance = constructor(*arguments)
        assert type(instance) is constructor
        assert not hasattr(instance, "__dict__")
        for property_name in property_names:
            with pytest.raises(AttributeError):
                setattr(instance, property_name, 0)
        with pytest.raises(TypeError):
            instance[0] = 0
        with pytest.raises(TypeError):
            constructor(*arguments, authority=object())
        with pytest.raises(TypeError):
            constructor(*arguments, "extra")
        with pytest.raises(TypeError):
            constructor(*arguments[:-1])

        class _ConstructorSubclass(constructor):
            pass

        with pytest.raises(RuntimeError) as rejection:
            _ConstructorSubclass(*arguments)
        assert rejection.type is RuntimeError
        assert rejection.value.args == ("GUARDED_BOOTSTRAP_INVALID",)


def test_broker_native_core_draft_iocp_arithmetic_representations_are_bounded_numeric_facts() -> None:
    namespace = _load_broker_native_core_draft()
    huge = 10**1_000
    instances_and_expected = (
        (
            namespace["_C6BrokerNativeCoreDraftIocpWaitWindow"](huge),
            "_C6BrokerNativeCoreDraftIocpWaitWindow(wait_timeout_ms=50)",
        ),
        (
            namespace["_C6BrokerNativeCoreDraftWireReadWindow"](huge, 0),
            "_C6BrokerNativeCoreDraftWireReadWindow("
            "maximum_read_request_bytes=65536)",
        ),
        (
            namespace["_C6BrokerNativeCoreDraftControlFrameAdmission"](
                huge,
                65_536,
            ),
            "_C6BrokerNativeCoreDraftControlFrameAdmission("
            "payload_length_bytes=65536, frame_wire_bytes=65540)",
        ),
    )

    for instance, expected in instances_and_expected:
        assert repr(instance) == expected
        assert str(instance) == expected
        assert len(expected) < 140
        assert str(huge) not in expected
        assert not any(character in expected for character in ("\r", "\n", "\x00"))


def test_broker_native_core_draft_iocp_arithmetic_cross_binds_wait_and_read_caps() -> None:
    namespace = _load_broker_native_core_draft()
    wait_type = namespace["_C6BrokerNativeCoreDraftIocpWaitWindow"]
    read_type = namespace["_C6BrokerNativeCoreDraftWireReadWindow"]
    poll_quantum_ms = namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_IOCP_POLL_QUANTUM_MS"
    ]
    io_chunk_bytes = namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_IO_CHUNK_BYTES"
    ]

    for remaining_monotonic_ns, _expected in (
        _BROKER_NATIVE_CORE_DRAFT_IOCP_WAIT_WINDOW_FIXTURES
    ):
        window = wait_type(remaining_monotonic_ns)
        assert 1 <= window.wait_timeout_ms <= poll_quantum_ms == 50

    wire_cap_names = (
        "_C6_BROKER_NATIVE_CORE_DRAFT_ONE_CONTROL_FRAME_WIRE_BYTES",
        "_C6_BROKER_NATIVE_CORE_DRAFT_ORDINARY_ACK_STATUS_WIRE_BYTES",
        "_C6_BROKER_NATIVE_CORE_DRAFT_EXECUTE_ACK_STATUS_WIRE_BYTES",
        "_C6_BROKER_NATIVE_CORE_DRAFT_PER_TARGET_BROKER_REQUEST_WIRE_BYTES",
        "_C6_BROKER_NATIVE_CORE_DRAFT_PER_TARGET_BROKER_RESPONSE_WIRE_BYTES",
        "_C6_BROKER_NATIVE_CORE_DRAFT_ROOT_AGGREGATE_BROKER_REQUEST_WIRE_BYTES",
        "_C6_BROKER_NATIVE_CORE_DRAFT_ROOT_AGGREGATE_BROKER_RESPONSE_WIRE_BYTES",
    )
    for cap_name in wire_cap_names:
        byte_cap = namespace[cap_name]
        first = read_type(byte_cap, 0)
        boundary = read_type(byte_cap, byte_cap)
        assert first.remaining_cap_bytes == byte_cap
        assert first.maximum_read_request_bytes == min(
            io_chunk_bytes,
            byte_cap + 1,
        )
        assert tuple(boundary) == (byte_cap, byte_cap, 0, 1)
        assert first.maximum_read_request_bytes <= io_chunk_bytes == 65_536

    observed_stdio_caps: list[int] = []
    for table_name, _selector, _table_id, _fields, _rows, _bytes, _sha in (
        _BROKER_NATIVE_CORE_DRAFT_LIMIT_FIXTURES
    ):
        table = namespace[table_name]
        cap_indices = tuple(
            index
            for index, field_name in enumerate(table.field_names)
            if field_name
            in {"stdin_cap_bytes", "stdout_cap_bytes", "stderr_cap_bytes"}
        )
        for row in table.rows:
            for index in cap_indices:
                byte_cap = row[index]
                assert type(byte_cap) is int and byte_cap >= 0
                observed_stdio_caps.append(byte_cap)
                assert tuple(read_type(byte_cap, byte_cap)) == (
                    byte_cap,
                    byte_cap,
                    0,
                    1,
                )
                assert read_type(byte_cap, 0).maximum_read_request_bytes <= (
                    io_chunk_bytes
                )
    assert len(observed_stdio_caps) == sum(
        len(rows)
        * sum(
            field_name
            in {"stdin_cap_bytes", "stdout_cap_bytes", "stderr_cap_bytes"}
            for field_name in fields
        )
        for _table, _selector, _id, fields, rows, _bytes, _sha in (
            _BROKER_NATIVE_CORE_DRAFT_LIMIT_FIXTURES
        )
    )


def test_broker_native_core_draft_iocp_arithmetic_cross_binds_control_frame_caps_only() -> None:
    namespace = _load_broker_native_core_draft()
    admission_type = namespace[
        "_C6BrokerNativeCoreDraftControlFrameAdmission"
    ]
    payload_cap = namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_CONTROL_FRAME_PAYLOAD_CAP_BYTES"
    ]
    one_frame_wire_bytes = namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_ONE_CONTROL_FRAME_WIRE_BYTES"
    ]
    assert payload_cap == 65_536
    assert one_frame_wire_bytes == 4 + payload_cap == 65_540
    assert tuple(admission_type(one_frame_wire_bytes, payload_cap)) == (
        one_frame_wire_bytes,
        payload_cap,
        one_frame_wire_bytes,
    )

    fixed_control_caps = {
        "go": one_frame_wire_bytes,
        "credential-data": one_frame_wire_bytes,
        "credential-host-status": one_frame_wire_bytes,
        "ordinary-ack-status": namespace[
            "_C6_BROKER_NATIVE_CORE_DRAFT_ORDINARY_ACK_STATUS_WIRE_BYTES"
        ],
        "execute-ack-status": namespace[
            "_C6_BROKER_NATIVE_CORE_DRAFT_EXECUTE_ACK_STATUS_WIRE_BYTES"
        ],
        "per-target-broker-request": namespace[
            "_C6_BROKER_NATIVE_CORE_DRAFT_PER_TARGET_BROKER_REQUEST_WIRE_BYTES"
        ],
        "per-target-broker-response": namespace[
            "_C6_BROKER_NATIVE_CORE_DRAFT_PER_TARGET_BROKER_RESPONSE_WIRE_BYTES"
        ],
        "root-broker-request-aggregate": namespace[
            "_C6_BROKER_NATIVE_CORE_DRAFT_ROOT_AGGREGATE_BROKER_REQUEST_WIRE_BYTES"
        ],
        "root-broker-response-aggregate": namespace[
            "_C6_BROKER_NATIVE_CORE_DRAFT_ROOT_AGGREGATE_BROKER_RESPONSE_WIRE_BYTES"
        ],
    }
    for role, byte_cap in fixed_control_caps.items():
        assert byte_cap >= one_frame_wire_bytes, role
        assert byte_cap % one_frame_wire_bytes == 0, role
        assert admission_type(byte_cap, payload_cap).frame_wire_bytes == (
            one_frame_wire_bytes
        )

    assert "descriptor" not in fixed_control_caps
    assert not any(
        raw_stream in fixed_control_caps
        for raw_stream in ("stdin", "stdout", "stderr")
    )
    assert namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_DESCRIPTOR_TRANSPORT_PAYLOAD_CAP_BYTES"
    ] == 4_194_304


def test_broker_native_core_draft_iocp_arithmetic_types_are_constructor_only_and_dormant() -> None:
    namespace = _load_broker_native_core_draft()
    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    parents = {
        child: node
        for node in ast.walk(tree)
        for child in ast.iter_child_nodes(node)
    }
    class_names = (
        "_C6BrokerNativeCoreDraftIocpWaitWindow",
        "_C6BrokerNativeCoreDraftWireReadWindow",
        "_C6BrokerNativeCoreDraftControlFrameAdmission",
    )

    for class_name in class_names:
        class_nodes = tuple(
            node
            for node in tree.body
            if isinstance(node, ast.ClassDef) and node.name == class_name
        )
        assert len(class_nodes) == 1
        class_loads = tuple(
            node
            for node in ast.walk(tree)
            if isinstance(node, ast.Name)
            and isinstance(node.ctx, ast.Load)
            and node.id == class_name
        )
        assert len(class_loads) == 1
        class_guard = parents[class_loads[0]]
        assert isinstance(class_guard, ast.Compare)
        assert isinstance(class_guard.left, ast.Name)
        assert class_guard.left.id == "cls"
        assert len(class_guard.ops) == 1
        assert isinstance(class_guard.ops[0], ast.IsNot)
        assert class_guard.comparators == [class_loads[0]]
        assert not any(
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == class_name
            for node in ast.walk(tree)
        )

    assert {
        name
        for name, value in namespace.items()
        if name.startswith("_c6_broker_native_core_draft_")
        and any(
            fragment in name
            for fragment in ("iocp_wait", "wire_read", "frame_admission")
        )
        and callable(value)
    } == set()
    assert not any(
        name.startswith("_C6_BROKER_NATIVE_CORE_DRAFT_")
        and any(
            fragment in name
            for fragment in ("IOCP_WAIT_WINDOW", "WIRE_READ_WINDOW", "FRAME_ADMISSION")
        )
        for name in namespace
    )
    exact_top_level_imports = tuple(
        (alias.name, alias.asname)
        for node in tree.body
        if isinstance(node, ast.Import)
        for alias in node.names
    )
    assert exact_top_level_imports == (
        ("hashlib", None),
        ("json", None),
        ("os", None),
        ("sys", None),
    )
    assert not BOOTSTRAP_PATH.with_name("complete_suite_control_plane.ps1").exists()
    for marker in (
        "C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN",
        "C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END",
    ):
        assert marker not in source


