def test_broker_native_core_draft_limit_tables_match_literal_registry_and_independent_json() -> None:
    namespace = _load_broker_native_core_draft()

    for (
        table_name,
        _selector_name,
        table_id,
        field_names,
        rows,
        canonical_bytes,
        draft_sha256,
    ) in _BROKER_NATIVE_CORE_DRAFT_LIMIT_FIXTURES:
        table = namespace[table_name]
        independent_rows = tuple(
            {field: row[index] for index, field in enumerate(field_names)}
            for row in rows
        )
        independent_bytes = json.dumps(
            independent_rows,
            ensure_ascii=True,
            allow_nan=False,
            separators=(",", ":"),
        ).encode("utf-8", errors="strict") + b"\n"

        assert tuple(table) == (
            table_id,
            field_names,
            rows,
            canonical_bytes,
            draft_sha256,
        )
        assert table.table_id == table_id
        assert table.field_names == field_names
        assert table.rows == rows
        assert table.canonical_bytes == canonical_bytes == independent_bytes
        assert table.draft_sha256 == draft_sha256
        assert sha256(canonical_bytes).hexdigest() == draft_sha256
        assert len(draft_sha256) == 64
        assert all(character in "0123456789abcdef" for character in draft_sha256)

    root_rows = namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_ROOT_PROCESS_LIMIT_TABLE"
    ].rows
    target_rows = namespace[
        "_C6_BROKER_NATIVE_CORE_DRAFT_GUARDED_TARGET_PROCESS_LIMIT_TABLE"
    ].rows
    assert len(root_rows) == 17
    assert len(target_rows) == 12
    assert len(_BROKER_NATIVE_CORE_DRAFT_LIMIT_FIXTURES[2][4]) == 19
    assert len(_BROKER_NATIVE_CORE_DRAFT_LIMIT_FIXTURES[3][4]) == 4
    assert len(_BROKER_NATIVE_CORE_DRAFT_LIMIT_FIXTURES[4][4]) == 2
    assert tuple(row[0] for row in root_rows) == namespace["ROOT_ENTRYPOINT_ROLES"]
    assert tuple(row[0] for row in target_rows) == namespace["GUARDED_TARGET_ROLES"]


def test_broker_native_core_draft_limit_selectors_are_exact_role_only() -> None:
    namespace = _load_broker_native_core_draft()

    for (
        table_name,
        selector_name,
        table_id,
        field_names,
        rows,
        _canonical_bytes,
        draft_sha256,
    ) in _BROKER_NATIVE_CORE_DRAFT_LIMIT_FIXTURES:
        selector = namespace[selector_name]
        signature = inspect.signature(selector)
        assert tuple(signature.parameters) == ("role",)
        assert signature.parameters["role"].kind is inspect.Parameter.POSITIONAL_OR_KEYWORD
        assert signature.parameters["role"].default is inspect.Parameter.empty

        for row_index, row in enumerate(rows):
            selection = selector(row[0])
            assert tuple(selection) == (table_id, field_names, row, draft_sha256)
            assert selection.table_id == table_id
            assert selection.field_names == field_names
            assert selection.row == row
            assert selection.row is namespace[table_name].rows[row_index]
            assert selection.table_sha256 == draft_sha256

        sample_role = rows[0][0]
        rejected_roles = (
            "",
            sample_role.upper(),
            sample_role + " ",
            b"role",
            None,
            True,
            _BrokerNativeCoreStringSubclass(sample_role),
        )
        for rejected_role in rejected_roles:
            with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
                selector(rejected_role)


def test_broker_native_core_draft_limit_shapes_are_nested_immutable_and_repr_safe() -> None:
    namespace = _load_broker_native_core_draft()

    for (
        table_name,
        selector_name,
        _table_id,
        _field_names,
        rows,
        _canonical_bytes,
        _draft_sha256,
    ) in _BROKER_NATIVE_CORE_DRAFT_LIMIT_FIXTURES:
        table = namespace[table_name]
        selection = namespace[selector_name](rows[0][0])
        assert type(table) is namespace["_C6BrokerNativeCoreDraftLimitTable"]
        assert type(selection) is namespace["_C6BrokerNativeCoreDraftLimitSelection"]
        assert type(table.field_names) is tuple
        assert type(table.rows) is tuple
        assert all(type(row) is tuple for row in table.rows)
        assert type(selection.field_names) is tuple
        assert type(selection.row) is tuple
        assert repr(table.rows) not in repr(table)
        assert repr(table.canonical_bytes) not in repr(table)
        assert repr(selection.row) not in repr(selection)
        assert str(table) == repr(table)
        assert str(selection) == repr(selection)
        with pytest.raises(AttributeError):
            table.rows = ()
        with pytest.raises(AttributeError):
            selection.row = ()
        with pytest.raises(TypeError):
            table.rows[0][1] = 1


def test_broker_native_core_draft_limit_constructors_have_exact_signatures_and_types() -> None:
    namespace = _load_broker_native_core_draft()
    table_type = namespace["_C6BrokerNativeCoreDraftLimitTable"]
    selection_type = namespace["_C6BrokerNativeCoreDraftLimitSelection"]
    (
        _table_name,
        _selector_name,
        table_id,
        field_names,
        rows,
        canonical_bytes,
        draft_sha256,
    ) = _BROKER_NATIVE_CORE_DRAFT_LIMIT_FIXTURES[0]

    assert tuple(inspect.signature(table_type.__new__).parameters) == (
        "cls",
        "table_id",
        "field_names",
        "rows",
        "canonical_bytes",
        "draft_sha256",
    )
    assert tuple(inspect.signature(selection_type.__new__).parameters) == (
        "cls",
        "table_id",
        "field_names",
        "row",
        "table_sha256",
    )
    assert tuple(inspect.signature(table_type).parameters) == (
        "table_id",
        "field_names",
        "rows",
        "canonical_bytes",
        "draft_sha256",
    )
    assert tuple(inspect.signature(selection_type).parameters) == (
        "table_id",
        "field_names",
        "row",
        "table_sha256",
    )

    table = table_type(
        table_id,
        field_names,
        rows,
        canonical_bytes,
        draft_sha256,
    )
    selection = selection_type(table_id, field_names, rows[0], draft_sha256)
    assert tuple(table) == (
        table_id,
        field_names,
        rows,
        canonical_bytes,
        draft_sha256,
    )
    assert tuple(selection) == (table_id, field_names, rows[0], draft_sha256)

    for constructor, exact_arguments in (
        (
            table_type,
            (table_id, field_names, rows, canonical_bytes, draft_sha256),
        ),
        (selection_type, (table_id, field_names, rows[0], draft_sha256)),
    ):
        with pytest.raises(TypeError):
            constructor(*exact_arguments[:-1])
        with pytest.raises(TypeError):
            constructor(*exact_arguments, "extra")

    class _TableSubclass(table_type):
        pass

    class _SelectionSubclass(selection_type):
        pass

    with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
        _TableSubclass(table_id, field_names, rows, canonical_bytes, draft_sha256)
    with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
        _SelectionSubclass(table_id, field_names, rows[0], draft_sha256)


def test_broker_native_core_draft_limit_constructors_reject_exact_type_subclasses() -> None:
    namespace = _load_broker_native_core_draft()
    table_type = namespace["_C6BrokerNativeCoreDraftLimitTable"]
    selection_type = namespace["_C6BrokerNativeCoreDraftLimitSelection"]
    (
        _table_name,
        _selector_name,
        table_id,
        field_names,
        rows,
        canonical_bytes,
        draft_sha256,
    ) = _BROKER_NATIVE_CORE_DRAFT_LIMIT_FIXTURES[0]

    class _StringSubclass(str):
        pass

    class _IntegerSubclass(int):
        pass

    class _BytesSubclass(bytes):
        pass

    class _TupleSubclass(tuple):
        pass

    table_mutations = (
        (_StringSubclass(table_id), field_names, rows, canonical_bytes, draft_sha256),
        (table_id, _TupleSubclass(field_names), rows, canonical_bytes, draft_sha256),
        (
            table_id,
            (_StringSubclass(field_names[0]), *field_names[1:]),
            rows,
            canonical_bytes,
            draft_sha256,
        ),
        (table_id, field_names, _TupleSubclass(rows), canonical_bytes, draft_sha256),
        (
            table_id,
            field_names,
            (_TupleSubclass(rows[0]), *rows[1:]),
            canonical_bytes,
            draft_sha256,
        ),
        (
            table_id,
            field_names,
            ((_StringSubclass(rows[0][0]), *rows[0][1:]), *rows[1:]),
            canonical_bytes,
            draft_sha256,
        ),
        (
            table_id,
            field_names,
            ((rows[0][0], True, *rows[0][2:]), *rows[1:]),
            canonical_bytes,
            draft_sha256,
        ),
        (
            table_id,
            field_names,
            ((rows[0][0], _IntegerSubclass(rows[0][1]), *rows[0][2:]), *rows[1:]),
            canonical_bytes,
            draft_sha256,
        ),
        (table_id, field_names, rows, _BytesSubclass(canonical_bytes), draft_sha256),
        (table_id, field_names, rows, canonical_bytes, _StringSubclass(draft_sha256)),
    )
    for mutation in table_mutations:
        with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
            table_type(*mutation)

    selection_mutations = (
        (_StringSubclass(table_id), field_names, rows[0], draft_sha256),
        (table_id, _TupleSubclass(field_names), rows[0], draft_sha256),
        (table_id, field_names, _TupleSubclass(rows[0]), draft_sha256),
        (
            table_id,
            field_names,
            (_StringSubclass(rows[0][0]), *rows[0][1:]),
            draft_sha256,
        ),
        (table_id, field_names, (rows[0][0], True, *rows[0][2:]), draft_sha256),
        (
            table_id,
            field_names,
            (rows[0][0], _IntegerSubclass(rows[0][1]), *rows[0][2:]),
            draft_sha256,
        ),
        (table_id, field_names, rows[0], _StringSubclass(draft_sha256)),
    )
    for mutation in selection_mutations:
        with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
            selection_type(*mutation)


def test_broker_native_core_draft_limit_constructors_reject_before_hostile_protocols() -> None:
    namespace = _load_broker_native_core_draft()
    table_type = namespace["_C6BrokerNativeCoreDraftLimitTable"]
    selection_type = namespace["_C6BrokerNativeCoreDraftLimitSelection"]
    fixture = _BROKER_NATIVE_CORE_DRAFT_LIMIT_FIXTURES[0]
    table_id, field_names, rows, canonical_bytes, draft_sha256 = fixture[2:]
    calls: list[str] = []

    class _Hostile:
        def __iter__(self) -> object:
            calls.append("iter")
            raise AssertionError("hostile iteration dispatched")

        def __len__(self) -> int:
            calls.append("len")
            raise AssertionError("hostile length dispatched")

        def __getitem__(self, _key: object) -> object:
            calls.append("getitem")
            raise AssertionError("hostile indexing dispatched")

        def __eq__(self, _other: object) -> bool:
            calls.append("eq")
            raise AssertionError("hostile equality dispatched")

        def __bool__(self) -> bool:
            calls.append("bool")
            raise AssertionError("hostile truth dispatched")

    hostile = _Hostile()
    for index in range(5):
        arguments = [table_id, field_names, rows, canonical_bytes, draft_sha256]
        arguments[index] = hostile
        with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
            table_type(*arguments)
    for index in range(4):
        arguments = [table_id, field_names, rows[0], draft_sha256]
        arguments[index] = hostile
        with pytest.raises(RuntimeError, match="^GUARDED_BOOTSTRAP_INVALID$"):
            selection_type(*arguments)
    assert calls == []


def test_broker_native_core_draft_limit_digest_changes_on_order_key_or_value_mutation() -> None:
    for (
        _table_name,
        _selector_name,
        _table_id,
        field_names,
        rows,
        canonical_bytes,
        draft_sha256,
    ) in _BROKER_NATIVE_CORE_DRAFT_LIMIT_FIXTURES:
        reordered_rows = rows[1:] + rows[:1]
        reordered_bytes = json.dumps(
            tuple(
                {field: row[index] for index, field in enumerate(field_names)}
                for row in reordered_rows
            ),
            ensure_ascii=True,
            allow_nan=False,
            separators=(",", ":"),
        ).encode("utf-8") + b"\n"
        parsed = json.loads(canonical_bytes)
        first_items = tuple(parsed[0].items())
        parsed[0] = dict(reversed(first_items))
        reordered_key_bytes = json.dumps(
            parsed,
            ensure_ascii=True,
            allow_nan=False,
            separators=(",", ":"),
        ).encode("utf-8") + b"\n"
        numeric_rows = json.loads(canonical_bytes)
        numeric_rows[0][field_names[1]] += 1
        numeric_mutation = json.dumps(
            numeric_rows,
            ensure_ascii=True,
            allow_nan=False,
            separators=(",", ":"),
        ).encode("utf-8") + b"\n"

        assert reordered_bytes != canonical_bytes
        assert reordered_key_bytes != canonical_bytes
        assert numeric_mutation != canonical_bytes
        assert sha256(reordered_bytes).hexdigest() != draft_sha256
        assert sha256(reordered_key_bytes).hexdigest() != draft_sha256
        assert sha256(numeric_mutation).hexdigest() != draft_sha256


def test_broker_native_core_draft_limit_api_has_no_generic_caller_selected_surface() -> None:
    namespace = _load_broker_native_core_draft()
