        "Path('output.bin').write_bytes(b'data')",
        "Path('output.txt').write_text('data')",
        "Path('output').mkdir()",
        "Path('output').unlink()",
        "Path('output').rename('renamed')",
        "Path('output').replace('replacement')",
        "os.dup(1)",
        "os.dup2(1, 2)",
        "os.system('program.exe')",
        "subprocess.Popen(())",
        "subprocess.run(())",
        "socket.socket()",
        "socket.create_server(('127.0.0.1', 0))",
