def test_broker_native_core_internal_channel_endpoint_construction_ast_contract_rejects_causal_mutants(
    mutation: str,
) -> None:
    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    mutated_source = _broker_native_core_complete_module_mutant(mutation)
    findings = _broker_native_core_forbidden_ast_capability_calls(
        mutated_source
    )
    class_name = (
        "_C6BrokerNativeCoreDraftInternalChannelEndpointConstructionFactsRegistry"
    )
    original_tree = ast.parse(source)
    mutated_tree = ast.parse(mutated_source)
    original_class = next(
        node
        for node in original_tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )
    mutated_class = next(
        node
        for node in mutated_tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )

    def literal_contract(
        class_node: ast.ClassDef,
    ) -> tuple[tuple[object, ...], tuple[tuple[object, ...], ...], tuple[object, ...]]:
        class_new = next(
            node
            for node in class_node.body
            if isinstance(node, ast.FunctionDef) and node.name == "__new__"
        )
        assignments = {
            node.targets[0].id: node.value
            for node in class_new.body
            if isinstance(node, ast.Assign)
            and len(node.targets) == 1
            and isinstance(node.targets[0], ast.Name)
            and node.targets[0].id
            in {
                "field_names",
                "rows",
                "successful_path_per_channel_phases",
            }
        }
        evaluated = tuple(
            ast.literal_eval(assignments[name])
            for name in (
                "field_names",
                "rows",
                "successful_path_per_channel_phases",
            )
        )
        assert all(type(value) is tuple for value in evaluated)
        return evaluated

    original_contract = literal_contract(original_class)
    mutated_contract = literal_contract(mutated_class)
    assert original_contract == (
        _BROKER_NATIVE_CORE_DRAFT_INTERNAL_CHANNEL_ENDPOINT_CONSTRUCTION_FIELD_NAMES,
        _BROKER_NATIVE_CORE_DRAFT_INTERNAL_CHANNEL_ENDPOINT_CONSTRUCTION_ROWS,
        _BROKER_NATIVE_CORE_DRAFT_INTERNAL_CHANNEL_ENDPOINT_CONSTRUCTION_PHASES,
    )
    expected_fields = list(original_contract[0])
    expected_row = list(original_contract[1][0])
    expected_phases = list(original_contract[2])

    if mutation == "endpoint-server-inheritable":
        expected_row[1] = True
    elif mutation == "endpoint-common-flag-add":
        expected_row[2] = (*expected_row[2], "FILE_FLAG_WRITE_THROUGH")
    elif mutation == "endpoint-common-flag-remove":
        expected_row[2] = ("FILE_FLAG_FIRST_PIPE_INSTANCE",)
    elif mutation == "endpoint-common-flag-reorder":
        expected_row[2] = (
            "FILE_FLAG_OVERLAPPED",
            "FILE_FLAG_FIRST_PIPE_INSTANCE",
        )
    elif mutation == "endpoint-common-direction-flag":
        expected_row[2] = (*expected_row[2], "PIPE_ACCESS_OUTBOUND")
    elif mutation == "endpoint-pipe-message-mode":
        expected_row[3] = (
            "PIPE_TYPE_MESSAGE",
            *expected_row[3][1:],
        )
    elif mutation == "endpoint-pipe-nowait-mode":
        expected_row[3] = (
            *expected_row[3][:2],
            "PIPE_NOWAIT",
            expected_row[3][3],
        )
    elif mutation == "endpoint-pipe-remote-rejection-omitted":
        expected_row[3] = expected_row[3][:-1]
    elif mutation == "endpoint-maximum-instances":
        expected_row[4] = 2
    elif mutation == "endpoint-input-buffer-off-by-one":
        expected_row[5] = 65_535
    elif mutation == "endpoint-input-buffer-zero":
        expected_row[5] = 0
    elif mutation == "endpoint-output-buffer-off-by-one":
        expected_row[6] = 65_535
    elif mutation == "endpoint-output-buffer-zero":
        expected_row[6] = 0
    elif mutation == "endpoint-buffer-fields-swapped":
        expected_fields[5], expected_fields[6] = (
            expected_fields[6],
            expected_fields[5],
        )
    elif mutation == "endpoint-principals-widened":
        expected_row[7] = ("current-user-sid", "everyone")
    elif mutation == "endpoint-accepted-result-true":
        expected_row[9] = "TRUE"
    elif mutation == "endpoint-accepted-result-pipe-connected":
        expected_row[9] = "FALSE/ERROR_PIPE_CONNECTED"
    elif mutation == "endpoint-accepted-result-generic-success":
        expected_row[9] = "success"
    elif mutation in {
        "endpoint-server-created-after-association",
        "endpoint-association-after-connect",
        "endpoint-connect-after-child-open",
        "endpoint-child-open-after-completion",
        "endpoint-completion-after-handle-list",
        "endpoint-handle-list-after-process",
        "endpoint-close-before-process",
    }:
        left, right = {
            "endpoint-server-created-after-association": (0, 1),
            "endpoint-association-after-connect": (1, 2),
            "endpoint-connect-after-child-open": (2, 3),
            "endpoint-child-open-after-completion": (3, 4),
            "endpoint-completion-after-handle-list": (4, 5),
            "endpoint-handle-list-after-process": (5, 6),
            "endpoint-close-before-process": (6, 7),
        }[mutation]
        expected_phases[left], expected_phases[right] = (
            expected_phases[right],
            expected_phases[left],
        )
    elif mutation == "endpoint-overlapped-retention-false":
        expected_row[11] = False
    elif mutation == "endpoint-buffer-retention-false":
        expected_row[12] = False
    elif mutation == "endpoint-child-share-mode":
        expected_row[13] = 1
    elif mutation == "endpoint-child-disposition":
        expected_row[14] = "CREATE_NEW"
    elif mutation == "endpoint-child-inheritable-false":
        expected_row[15] = False
    elif mutation == "endpoint-child-synchronous-false":
        expected_row[16] = False
    elif mutation == "endpoint-handle-list-server-only":
        expected_row[17] = "server-endpoint-only"
    elif mutation == "endpoint-handle-list-both-endpoints":
        expected_row[17] = "server-and-child-endpoints"
    elif mutation == "endpoint-close-not-immediate":
        expected_phases[7] = (
            "parent-duplicate-of-child-endpoint-closed-eventually"
        )
    elif mutation == "endpoint-numeric-win32-constant":
        expected_row[2] = (524_288, "FILE_FLAG_OVERLAPPED")

    assert mutated_contract == (
        tuple(expected_fields),
        (tuple(expected_row),),
        tuple(expected_phases),
    )
    assert mutated_source != source
    assert "structure:module-contract" in findings
    class_preserving_mutations = {
        "endpoint-singleton-introduction",
        "endpoint-selector-introduction",
    }
    if mutation in class_preserving_mutations:
        assert ast.dump(original_class, include_attributes=False) == ast.dump(
            mutated_class,
            include_attributes=False,
        )
    else:
        assert ast.dump(original_class, include_attributes=False) != ast.dump(
            mutated_class,
            include_attributes=False,
        )
        assert f"structure:approved-body-contract:{class_name}" in findings

    mutated_new = next(
        node
        for node in mutated_class.body
        if isinstance(node, ast.FunctionDef) and node.name == "__new__"
    )
    if mutation == "endpoint-caller-parameter":
        assert (
            _broker_native_core_endpoint_caller_parameter_signature_is_exact(
                mutated_new
            )
        )
    elif mutation == "endpoint-singleton-introduction":
        singleton_assignments = tuple(
            node
            for node in mutated_tree.body
            if isinstance(node, ast.Assign)
            and len(node.targets) == 1
            and isinstance(node.targets[0], ast.Name)
            and node.targets[0].id
            == "_C6_BROKER_NATIVE_CORE_DRAFT_INTERNAL_CHANNEL_ENDPOINT_"
            "CONSTRUCTION_FACTS_REGISTRY"
        )
        assert len(singleton_assignments) == 1
        assert _broker_native_core_endpoint_construction_exact_zero_arg_constructor_call(
            singleton_assignments[0].value
        )
    elif mutation == "endpoint-selector-introduction":
        selector_nodes = tuple(
            node
            for node in mutated_tree.body
            if isinstance(node, ast.FunctionDef)
            and node.name
            == "_c6_broker_native_core_draft_select_endpoint_facts"
        )
        assert len(selector_nodes) == 1
        assert _broker_native_core_endpoint_construction_exact_selector(
            selector_nodes[0]
        )
        assert (
            "structure:unregistered-definition:"
            "_c6_broker_native_core_draft_select_endpoint_facts"
            in findings
        )
    elif mutation == "endpoint-digest-introduction":
        assert any(
            isinstance(node, ast.Name)
            and isinstance(node.ctx, ast.Store)
            and node.id == "registry_digest"
            for node in ast.walk(mutated_new)
        )
    elif mutation == "endpoint-result-classifier":
        assert any(
            isinstance(node, ast.FunctionDef)
            and node.name == "result_classifier"
            for node in mutated_new.body
        )
    elif mutation == "endpoint-production-api-call":
        assert any(
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == "CreateNamedPipeW"
            for node in ast.walk(mutated_new)
        )


def _broker_native_core_iocp_operation_issue_caller_parameter_signature_is_exact(
    function: ast.FunctionDef,
) -> bool:
    arguments = function.args
    all_arguments = (
        *arguments.posonlyargs,
        *arguments.args,
        *arguments.kwonlyargs,
    )
    return (
        function.decorator_list == []
        and function.type_comment is None
        and arguments.posonlyargs == []
        and tuple(argument.arg for argument in arguments.args)
        == ("cls", "role")
        and arguments.vararg is None
        and arguments.kwonlyargs == []
        and arguments.kw_defaults == []
        and arguments.kwarg is None
        and arguments.defaults == []
        and all(
            argument.annotation is None and argument.type_comment is None
            for argument in all_arguments
        )
        and function.returns is None
        and function.type_params == []
    )


def test_broker_native_core_iocp_operation_issue_facts_caller_parameter_signature_oracle_rejects_every_extra_surface() -> None:
    exact = ast.parse("def __new__(cls, role):\n    pass").body[0]
    extra_surface_sources = (
        "def __new__(cls, /, role):\n    pass",
        "def __new__(cls, role, *extra):\n    pass",
        "def __new__(cls, role, *, extra):\n    pass",
        "def __new__(cls, role, *, extra=None):\n    pass",
        "def __new__(cls, role, **extra):\n    pass",
        "def __new__(cls, role=None):\n    pass",
        "def __new__(cls: object, role):\n    pass",
        "def __new__(cls, role: object):\n    pass",
        "def __new__(cls, role) -> object:\n    pass",
        "def __new__[T](cls, role):\n    pass",
        "@staticmethod\ndef __new__(cls, role):\n    pass",
        (
            "def __new__(cls, role):\n"
            "    # type: (object, object) -> object\n"
            "    pass"
        ),
        (
            "def __new__(\n"
            "    cls,  # type: object\n"
            "    role,\n"
            "):\n"
            "    pass"
        ),
    )
    mutants = tuple(
        ast.parse(source, type_comments=True).body[0]
        for source in extra_surface_sources
    )

    assert isinstance(exact, ast.FunctionDef)
    assert all(isinstance(mutant, ast.FunctionDef) for mutant in mutants)
    assert not any(
        _broker_native_core_reviewed_old_partial_caller_parameter_signature_is_exact(
            mutant
        )
        for mutant in mutants[:-3]
    )
    assert all(
        _broker_native_core_reviewed_old_partial_caller_parameter_signature_is_exact(
            mutant
        )
        for mutant in mutants[-3:]
    )
    assert _broker_native_core_iocp_operation_issue_caller_parameter_signature_is_exact(
        exact
    )
    assert all(
        not _broker_native_core_iocp_operation_issue_caller_parameter_signature_is_exact(
            mutant
        )
        for mutant in mutants
    )


