def test_broker_native_core_iocp_operation_issue_facts_ast_contract_rejects_causal_mutants(
    mutation: str,
) -> None:
    source = BOOTSTRAP_PATH.read_text(encoding="utf-8")
    mutated_source = _broker_native_core_complete_module_mutant(mutation)
    findings = _broker_native_core_forbidden_ast_capability_calls(
        mutated_source
    )
    class_name = (
        "_C6BrokerNativeCoreDraftIocpOperationIssueFactsRegistry"
    )
    original_tree = ast.parse(source)
    mutated_tree = ast.parse(mutated_source)
    original_class = next(
        node
        for node in original_tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )
    mutated_class = next(
        node
        for node in mutated_tree.body
        if isinstance(node, ast.ClassDef) and node.name == class_name
    )

    def literal_contract(
        class_node: ast.ClassDef,
    ) -> tuple[object, ...]:
        class_new = next(
            node
            for node in class_node.body
            if isinstance(node, ast.FunctionDef) and node.name == "__new__"
        )
        assignments = {
            node.targets[0].id: node.value
            for node in class_new.body
            if isinstance(node, ast.Assign)
            and len(node.targets) == 1
            and isinstance(node.targets[0], ast.Name)
            and node.targets[0].id
            in {
                "identity_table",
                "issue_phases",
                "issue_return_table",
                "allocation_lifetime_table",
                "invariants",
            }
        }
        evaluated = tuple(
            ast.literal_eval(assignments[name])
            for name in (
                "identity_table",
                "issue_phases",
                "issue_return_table",
                "allocation_lifetime_table",
                "invariants",
            )
        )
        assert all(type(value) is tuple for value in evaluated)
        return evaluated

    original_contract = literal_contract(original_class)
    mutated_contract = literal_contract(mutated_class)
    assert original_contract == (
        _BROKER_NATIVE_CORE_DRAFT_IOCP_OPERATION_ISSUE_IDENTITY_TABLE,
        _BROKER_NATIVE_CORE_DRAFT_IOCP_OPERATION_ISSUE_PHASES,
        _BROKER_NATIVE_CORE_DRAFT_IOCP_OPERATION_ISSUE_RETURN_TABLE,
        _BROKER_NATIVE_CORE_DRAFT_IOCP_OPERATION_ISSUE_ALLOCATION_LIFETIME_TABLE,
        _BROKER_NATIVE_CORE_DRAFT_IOCP_OPERATION_ISSUE_INVARIANTS,
    )
    expected_phases = list(original_contract[1])
    expected_return_rows = [
        list(row) for row in original_contract[2][1]
    ]
    expected_lifetime_rows = [
        list(row) for row in original_contract[3][1]
    ]
    expected_invariants = list(original_contract[4])

    if mutation == "iocp-operation-issue-phase-omit":
        del expected_phases[3]
    elif mutation == "iocp-operation-issue-phase-reorder":
        expected_phases[0], expected_phases[1] = (
            expected_phases[1],
            expected_phases[0],
        )
    elif mutation == "iocp-operation-issue-overlapped-shared":
        expected_phases[0] = "zero-shared-OVERLAPPED"
    elif mutation == "iocp-operation-issue-overlapped-not-zeroed":
        expected_phases[0] = "dedicated-OVERLAPPED"
    elif mutation == "iocp-operation-issue-allocation-phase-omitted":
        del expected_phases[1]
    elif mutation == "iocp-operation-issue-allocation-phase-reordered":
        expected_phases[1], expected_phases[2] = (
            expected_phases[2],
            expected_phases[1],
        )
    elif mutation == "iocp-operation-issue-allocation-phase-mutable":
        expected_phases[1] = (
            "allocate-mutable-operation-buffer-and-cursor"
        )
    elif mutation == "iocp-operation-issue-live-insert-direct":
        expected_phases[2] = "insert-LIVE_AWAIT_PACKET-ledger-entry"
    elif mutation == "iocp-operation-issue-insert-before-issuing":
        expected_phases[2] = "insert-ledger-entry-before-ISSUING"
    elif mutation == "iocp-operation-issue-api-before-ledger-insert":
        expected_phases[2], expected_phases[3] = (
            expected_phases[3],
            expected_phases[2],
        )
    elif mutation == "iocp-operation-issue-true-retired":
        expected_return_rows[0][3] = None
    elif mutation == "iocp-operation-issue-true-packet-false":
        expected_return_rows[0][5] = False
    elif mutation == "iocp-operation-issue-true-byte-count-trusted":
        expected_return_rows[0][6] = "trust"
    elif mutation == "iocp-operation-issue-pending-retired":
        expected_return_rows[1][3] = None
    elif mutation == "iocp-operation-issue-pending-packet-false":
        expected_return_rows[1][5] = False
    elif mutation == "iocp-operation-issue-pipe-connected-accepted":
        expected_return_rows.insert(
            2,
            [
                "ReadFile-or-WriteFile",
                "FALSE/ERROR_PIPE_CONNECTED",
                "ISSUING",
                "LIVE_AWAIT_PACKET",
                "none",
                True,
                "not-applicable",
            ],
        )
    elif mutation == "iocp-operation-issue-broken-pipe-writes":
        expected_return_rows[2][0] = "ReadFile-or-WriteFile"
    elif mutation == (
        "iocp-operation-issue-broken-pipe-predicate-removed"
    ):
        expected_return_rows[2][1] = "FALSE/ERROR_BROKEN_PIPE"
    elif mutation == "iocp-operation-issue-eof-packet-expected":
        expected_return_rows[2][5] = True
    elif mutation == "iocp-operation-issue-other-error-left-live":
        expected_return_rows[3][3] = "LIVE_AWAIT_PACKET"
    elif mutation == (
        "iocp-operation-issue-other-error-packet-expected"
    ):
        expected_return_rows[3][5] = True
    elif mutation == "iocp-operation-issue-allocation-release":
        expected_lifetime_rows[0][1] = "release"
    elif mutation == "iocp-operation-issue-allocation-move-allowed":
        expected_lifetime_rows[0][4] = "allow-move"
    elif mutation == "iocp-operation-issue-allocation-reuse-allowed":
        expected_lifetime_rows[1][4] = "allow-reuse"
    elif mutation == (
        "iocp-operation-issue-allocation-boundary-widened"
    ):
        expected_lifetime_rows[0][3] = "any-queued-packet-consumed"
    elif mutation == (
        "iocp-operation-issue-completion-skip-invariant-removed"
    ):
        del expected_invariants[3]
    elif mutation == (
        "iocp-operation-issue-exact-match-invariant-removed"
    ):
        del expected_invariants[4]
    elif mutation == (
        "iocp-operation-issue-exact-match-invariant-widened"
    ):
        expected_invariants[4] = (
            "every-pipe-packet-may-match-one-or-more-live-OVERLAPPED"
        )
    elif mutation == "iocp-operation-issue-two-outstanding-invariant":
        expected_invariants[0] = (
            "two-outstanding-operations-per-parent-endpoint"
        )
    elif mutation == (
        "iocp-operation-issue-shared-overlapped-invariant"
    ):
        expected_invariants[1] = (
            "one-shared-OVERLAPPED-across-parent-endpoints"
        )

    expected_contract = (
        original_contract[0],
        tuple(expected_phases),
        (
            original_contract[2][0],
            tuple(tuple(row) for row in expected_return_rows),
        ),
        (
            original_contract[3][0],
            tuple(tuple(row) for row in expected_lifetime_rows),
        ),
        tuple(expected_invariants),
    )
    assert mutated_contract == expected_contract
    assert mutated_source != source
    assert "structure:module-contract" in findings
    class_preserving_mutations = {
        "iocp-operation-issue-singleton-introduction",
        "iocp-operation-issue-selector-introduction",
    }
    if mutation in class_preserving_mutations:
        assert ast.dump(original_class, include_attributes=False) == ast.dump(
            mutated_class,
            include_attributes=False,
        )
    else:
        assert ast.dump(original_class, include_attributes=False) != ast.dump(
            mutated_class,
            include_attributes=False,
        )
        assert f"structure:approved-body-contract:{class_name}" in findings

    mutated_new = next(
        node
        for node in mutated_class.body
        if isinstance(node, ast.FunctionDef) and node.name == "__new__"
    )
    if mutation == "iocp-operation-issue-caller-parameter":
        assert _broker_native_core_iocp_operation_issue_caller_parameter_signature_is_exact(
            mutated_new
        )
    elif mutation == "iocp-operation-issue-singleton-introduction":
        singleton_assignments = tuple(
            node
            for node in mutated_tree.body
            if isinstance(node, ast.Assign)
            and len(node.targets) == 1
            and isinstance(node.targets[0], ast.Name)
            and node.targets[0].id
            == "_C6_BROKER_NATIVE_CORE_DRAFT_IOCP_OPERATION_ISSUE_"
            "FACTS_REGISTRY"
        )
        assert len(singleton_assignments) == 1
        assert _broker_native_core_iocp_operation_issue_exact_zero_arg_constructor_call(
            singleton_assignments[0].value
        )
    elif mutation == "iocp-operation-issue-selector-introduction":
        selector_nodes = tuple(
            node
            for node in mutated_tree.body
            if isinstance(node, ast.FunctionDef)
            and node.name
            == "_c6_broker_native_core_draft_select_iocp_issue_facts"
        )
        assert len(selector_nodes) == 1
        selector = selector_nodes[0]
        selector_arguments = selector.args
        assert selector.decorator_list == []
        assert selector.type_comment is None
        assert selector_arguments.posonlyargs == []
        assert selector_arguments.args == []
        assert selector_arguments.vararg is None
        assert selector_arguments.kwonlyargs == []
        assert selector_arguments.kw_defaults == []
        assert selector_arguments.kwarg is None
        assert selector_arguments.defaults == []
        assert selector.returns is None
        assert selector.type_params == []
        assert len(selector.body) == 1
        assert isinstance(selector.body[0], ast.Return)
        assert _broker_native_core_iocp_operation_issue_exact_zero_arg_constructor_call(
            selector.body[0].value
        )
        assert (
            "structure:unregistered-definition:"
            "_c6_broker_native_core_draft_select_iocp_issue_facts"
            in findings
        )
    elif mutation == "iocp-operation-issue-digest-introduction":
        assert any(
            isinstance(node, ast.Name)
            and isinstance(node.ctx, ast.Store)
            and node.id == "issue_facts_digest"
            for node in ast.walk(mutated_new)
        )
    elif mutation == "iocp-operation-issue-classifier-introduction":
        assert any(
            isinstance(node, ast.FunctionDef)
            and node.name == "issue_result_classifier"
            for node in mutated_new.body
        )
    elif mutation == "iocp-operation-issue-numeric-error-binding":
        assert any(
            isinstance(node, ast.Assign)
            and isinstance(node.targets[0], ast.Name)
            and node.targets[0].id == "error_io_pending"
            and isinstance(node.value, ast.Constant)
            and node.value.value == 997
            for node in mutated_new.body
        )
    elif mutation == "iocp-operation-issue-api-call":
        assert any(
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == "ReadFile"
            for node in ast.walk(mutated_new)
        )
    elif mutation == "iocp-operation-issue-dispatch-surface":
        assert any(
            isinstance(node, ast.FunctionDef)
            and node.name == "dispatch_packet"
            for node in mutated_class.body
        )
    elif mutation == "iocp-operation-issue-cancellation-surface":
        assert any(
            isinstance(node, ast.FunctionDef)
            and node.name == "cancel_operation"
            for node in mutated_class.body
        )


