def test_broker_native_core_draft_iocp_arithmetic_range_gate_mutants_preserve_exact_type_guard(
    mutation: str,
    class_name: str,
    numeric_left_name: str,
    numeric_operator_type: type[ast.cmpop],
    numeric_comparator_kind: str,
    numeric_comparator_value: object,
) -> None:
    original_tree = ast.parse(BOOTSTRAP_PATH.read_text(encoding="utf-8"))
    mutant_tree = ast.parse(_broker_native_core_complete_module_mutant(mutation))

    def constructor(tree: ast.Module) -> ast.FunctionDef:
        class_node = next(
            node
            for node in tree.body
            if isinstance(node, ast.ClassDef) and node.name == class_name
        )
        return next(
            node
            for node in class_node.body
            if isinstance(node, ast.FunctionDef) and node.name == "__new__"
        )

    def has_exact_class_guard(node: ast.If) -> bool:
        return any(
            isinstance(descendant, ast.Compare)
            and isinstance(descendant.left, ast.Name)
            and descendant.left.id == "cls"
            and len(descendant.ops) == 1
            and isinstance(descendant.ops[0], ast.IsNot)
            and len(descendant.comparators) == 1
            and isinstance(descendant.comparators[0], ast.Name)
            and descendant.comparators[0].id == class_name
            for descendant in ast.walk(node.test)
        )

    def has_numeric_comparison(node: ast.If) -> bool:
        for descendant in ast.walk(node.test):
            if not (
                isinstance(descendant, ast.Compare)
                and isinstance(descendant.left, ast.Name)
                and descendant.left.id == numeric_left_name
                and len(descendant.ops) == 1
                and isinstance(descendant.ops[0], numeric_operator_type)
                and len(descendant.comparators) == 1
            ):
                continue
            comparator = descendant.comparators[0]
            if numeric_comparator_kind == "name":
                return (
                    isinstance(comparator, ast.Name)
                    and comparator.id == numeric_comparator_value
                )
            assert numeric_comparator_kind == "constant"
            return (
                isinstance(comparator, ast.Constant)
                and comparator.value == numeric_comparator_value
            )
        return False

    original_constructor = constructor(original_tree)
    mutant_constructor = constructor(mutant_tree)
    original_type_guards = tuple(
        node
        for node in original_constructor.body
        if isinstance(node, ast.If) and has_exact_class_guard(node)
    )
    original_numeric_gates = tuple(
        node
        for node in original_constructor.body
        if isinstance(node, ast.If) and has_numeric_comparison(node)
    )
    assert len(original_type_guards) == 1
    assert len(original_numeric_gates) == 1

    mutant_if_dumps = {
        ast.dump(node, include_attributes=False)
        for node in mutant_constructor.body
        if isinstance(node, ast.If)
    }
    assert (
        ast.dump(original_type_guards[0], include_attributes=False)
        in mutant_if_dumps
    )
    assert (
        ast.dump(original_numeric_gates[0], include_attributes=False)
        not in mutant_if_dumps
    )
    assert not any(
        has_numeric_comparison(node)
        for node in mutant_constructor.body
        if isinstance(node, ast.If)
    )


