def test_broker_native_core_structural_contract_fingerprint_generation_audit() -> None:
    tree = ast.parse(BOOTSTRAP_PATH.read_text(encoding="utf-8"))

    def statement_label(node: ast.AST) -> str:
        if isinstance(node, (ast.AsyncFunctionDef, ast.ClassDef, ast.FunctionDef)):
            return f"{type(node).__name__}:{node.name}"
        if isinstance(node, ast.Import):
            return "Import:" + ",".join(alias.name for alias in node.names)
        if isinstance(node, ast.Assign):
            target = node.targets[0]
            if isinstance(target, ast.Name):
                return f"Assign:{target.id}"
            return "Assign:" + ast.dump(target, include_attributes=False)
        return type(node).__name__

    statement_contract = tuple(
        (
            statement_label(node),
            sha256(
                ast.dump(node, include_attributes=False).encode("utf-8")
            ).hexdigest(),
        )
        for node in tree.body
    )
    safe_fragments = (
        "def _path_components(value):\n"
        "    return tuple(\n"
        "        component.casefold()\n"
        "        for component in value.replace('\\\\', '/').split('/')\n"
        "        if component\n"
        "    )\n"
        "def decode_guarded_target_request(payload, expected_sha256):\n"
        "    payload.endswith(b'\\n')\n"
        "    payload[:-1].decode('utf-8')\n"
        "    canonical = json.dumps({}).encode('utf-8')\n"
        "    return hashlib.sha256(payload).hexdigest(), json.loads('{}'), canonical\n"
        "def _c6_broker_native_core_draft_utf16_ordinal_name_key(name):\n"
        "    return name.encode('utf-16-be')\n"
        "os.path.normpath('value')",
        "tuple([1]); type({}); any(set()); sorted(dict())",
    )
    safe_contract = tuple(
        sha256(
            ast.dump(
                ast.parse(fragment),
                include_attributes=False,
            ).encode("utf-8")
        ).hexdigest()
        for fragment in safe_fragments
    )

    assert (
        statement_contract
        == _BROKER_NATIVE_CORE_APPROVED_MODULE_STATEMENT_CONTRACT
    ), (
        len(statement_contract),
        len(_BROKER_NATIVE_CORE_APPROVED_MODULE_STATEMENT_CONTRACT),
        tuple(
            (index, actual, expected)
            for index, (actual, expected) in enumerate(
                zip(
                    statement_contract,
                    _BROKER_NATIVE_CORE_APPROVED_MODULE_STATEMENT_CONTRACT,
                )
            )
            if actual != expected
        ),
    )
    assert frozenset(safe_contract) == (
        _BROKER_NATIVE_CORE_SAFE_FRAGMENT_FINGERPRINTS
    )


