def test_broker_native_core_ast_capability_scanner_rejects_lambda_receiver_rebinding() -> None:
    source = (
        "def _clean_text(value):\n"
        "    return value\n"
        "def validate_guarded_environment(environment):\n"
        "    pairs = []\n"
        "    seen = set()\n"
        "    forbidden = {name.casefold() for name in ()}\n"
        "    allowed = {name.casefold() for name in ()}\n"
        "    for item in environment:\n"
        "        name = _clean_text(item[0])\n"
        "        folded = name.casefold()\n"
        "        folded.startswith('python')\n"
        "        seen.add(folded)\n"
        "        pairs.append((name, item))\n"
        "    expected = tuple(sorted(\n"
        "        pairs,\n"
        "        key=lambda item: (\n"
        "            (item := environment[0]),\n"
        "            item[0].casefold(),\n"
        "            item[0],\n"
        "        ),\n"
        "    ))\n"
        "    return expected"
    )

    findings = _broker_native_core_forbidden_ast_capability_calls(source)

    assert any(
        finding.startswith(
            "receiver-bindings:validate_guarded_environment:item:"
        )
        and "assign-subscript" in finding
        for finding in findings
    )
    assert any(
        finding.startswith(
            "receiver-lambda-contract:validate_guarded_environment:"
        )
        for finding in findings
    )


