def test_validator_bundle_models_have_exact_frozen_shape() -> None:
    preflight = _preflight()
    command_plan = _command_plan()
    command_policy = _command_policy()
    expected_fields = {
        preflight.FrozenValidatorInput: (
            "role",
            "bundle_path",
            "source_locator",
            "size",
            "sha256",
            "identity",
        ),
        preflight.FrozenValidatorRuntime: (
            "root",
            "root_identity",
            "source_wheel_name",
            "source_wheel_size",
            "source_wheel_sha256",
            "source_wheel_identity",
            "entries",
            "manifest_sha256",
        ),
        preflight.FrozenValidatorBundle: (
            "root",
            "root_identity",
            "inputs",
            "runtime",
            "manifest_sha256",
        ),
    }
    for model, names in expected_fields.items():
        assert model.__dataclass_params__.frozen is True
        assert tuple(field.name for field in fields(model)) == names

    input_hints = get_type_hints(preflight.FrozenValidatorInput)
    runtime_hints = get_type_hints(preflight.FrozenValidatorRuntime)
    bundle_hints = get_type_hints(preflight.FrozenValidatorBundle)
    assert input_hints == {
        "role": Literal["plugin", "skill"],
        "bundle_path": str,
        "source_locator": str,
        "size": int,
        "sha256": str,
        "identity": command_plan.FilesystemObjectIdentity,
    }
    assert runtime_hints == {
        "root": str,
        "root_identity": command_plan.FilesystemObjectIdentity,
        "source_wheel_name": str,
        "source_wheel_size": int,
        "source_wheel_sha256": str,
        "source_wheel_identity": command_plan.FilesystemObjectIdentity,
        "entries": tuple[command_policy.FilesystemSnapshotEntry, ...],
        "manifest_sha256": str,
    }
    assert bundle_hints == {
        "root": str,
        "root_identity": command_plan.FilesystemObjectIdentity,
        "inputs": tuple[preflight.FrozenValidatorInput, ...],
        "runtime": preflight.FrozenValidatorRuntime,
        "manifest_sha256": str,
    }

    freeze_signature = inspect.signature(preflight.freeze_validator_bundle)
    assert tuple(freeze_signature.parameters) == (
        "codex_home",
        "pyyaml_wheel",
        "output_root",
    )
    assert all(
        parameter.kind is inspect.Parameter.KEYWORD_ONLY
        for parameter in freeze_signature.parameters.values()
    )
    freeze_hints = get_type_hints(preflight.freeze_validator_bundle)
    assert freeze_hints == {
        "codex_home": Path,
        "pyyaml_wheel": Path,
        "output_root": Path,
        "return": preflight.FrozenValidatorBundle,
    }
    validate_signature = inspect.signature(
        preflight.validate_frozen_validator_bundle
    )
    assert tuple(validate_signature.parameters) == ("bundle",)
    assert (
        validate_signature.parameters["bundle"].kind
        is inspect.Parameter.POSITIONAL_OR_KEYWORD
    )
    validate_hints = get_type_hints(
        preflight.validate_frozen_validator_bundle
    )
    assert validate_hints == {
        "bundle": preflight.FrozenValidatorBundle,
        "return": preflight.FrozenValidatorBundle,
    }


