def test_validator_bundle_freezes_and_revalidates_exact_synthetic_bundle(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    paths = _validator_fixture(tmp_path, monkeypatch)

    bundle = _freeze_validator(paths)

    assert bundle.root == str(paths["output_root"])
    assert tuple(item.role for item in bundle.inputs) == ("plugin", "skill")
    assert tuple(item.source_locator for item in bundle.inputs) == (
        VALIDATOR_PLUGIN_LOCATOR,
        VALIDATOR_SKILL_LOCATOR,
    )
    assert tuple(Path(item.bundle_path).name for item in bundle.inputs) == (
        "validate_plugin.py",
        "quick_validate.py",
    )
    assert tuple(sorted(path.name for path in paths["output_root"].iterdir())) == (
        "quick_validate.py",
        "runtime",
        "validate_plugin.py",
    )
    assert (paths["output_root"] / "validate_plugin.py").read_bytes() == (
        paths["plugin_source"].read_bytes()
    )
    assert (paths["output_root"] / "quick_validate.py").read_bytes() == (
        paths["skill_source"].read_bytes()
    )
    expected_runtime_entries: set[str] = set()
    for member, _content in VALIDATOR_WHEEL_MEMBERS:
        assert isinstance(member, str)
        parts = member.split("/")
        for index in range(1, len(parts)):
            expected_runtime_entries.add("/".join(parts[:index]))
        expected_runtime_entries.add(member)
    assert {entry.relative_path for entry in bundle.runtime.entries} == (
        expected_runtime_entries
    )
    assert bundle.runtime.source_wheel_name == VALIDATOR_WHEEL_NAME
    assert bundle.runtime.source_wheel_size == paths["wheel"].stat().st_size
    assert bundle.runtime.source_wheel_sha256 == sha256(
        paths["wheel"].read_bytes()
    ).hexdigest()
    assert str(paths["codex_home"]) not in repr(bundle)
    assert len(bundle.runtime.manifest_sha256) == 64
    assert len(bundle.manifest_sha256) == 64

    paths["plugin_source"].write_bytes(b"source changed after freeze\n")
    paths["skill_source"].write_bytes(b"source changed after freeze\n")
    paths["wheel"].write_bytes(b"source wheel changed after freeze\n")
    validated = _preflight().validate_frozen_validator_bundle(bundle)

    assert validated == bundle
    assert validated is not bundle
    assert validated.runtime is not bundle.runtime
    assert validated.inputs is not bundle.inputs
    assert all(
        left is not right
        for left, right in zip(validated.inputs, bundle.inputs, strict=True)
    )


