@pytest.mark.parametrize(
    ("boundary", "accepted"),
    (
        ("script-exact", True),
        ("script-one-over", False),
        ("member-count-exact", True),
        ("member-count-one-over", False),
        ("member-bytes-exact", True),
        ("member-bytes-one-over", False),
        ("aggregate-bytes-exact", True),
        ("aggregate-bytes-one-over", False),
    ),
)
def test_validator_bundle_limits_exactly_at_and_one_over(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    boundary: str,
    accepted: bool,
) -> None:
    members: tuple[tuple[str | zipfile.ZipInfo, bytes], ...] = (
        VALIDATOR_WHEEL_MEMBERS
    )
    plugin_content = b"plugin\n"
    skill_content = b"skill\n"
    if boundary == "script-exact":
        plugin_content = b"p" * (256 * 1024)
        skill_content = b"s" * (256 * 1024)
    elif boundary == "script-one-over":
        plugin_content = b"p" * (256 * 1024 + 1)
    elif boundary.startswith("member-count-"):
        extra_count = 251 if accepted else 252
        members = members + tuple(
            (f"yaml/generated/member-{index:03d}.py", b"")
            for index in range(extra_count)
        )
    elif boundary == "member-bytes-exact":
        members = members + (("yaml/exact-member.bin", b"x" * (4 * 1024 * 1024)),)
    elif boundary == "member-bytes-one-over":
        members = members + (
            ("yaml/oversized-member.bin", b"x" * (4 * 1024 * 1024 + 1)),
        )
    elif boundary.startswith("aggregate-bytes-"):
        baseline_size = sum(len(content) for _name, content in members)
        remaining = 16 * 1024 * 1024 - baseline_size + (0 if accepted else 1)
        chunks = []
        for index in range(4):
            size = min(4 * 1024 * 1024, remaining)
            chunks.append((f"yaml/aggregate-{index}.bin", b"a" * size))
            remaining -= size
        assert remaining == 0
        members = members + tuple(chunks)
    else:
        raise AssertionError(boundary)
    paths = _validator_fixture(
        tmp_path,
        monkeypatch,
        members=members,
        plugin_content=plugin_content,
        skill_content=skill_content,
    )

    if accepted:
        bundle = _freeze_validator(paths)
        assert bundle.root == str(paths["output_root"])
        assert _preflight().validate_frozen_validator_bundle(bundle) == bundle
    else:
        with pytest.raises(RuntimeError) as error:
            _freeze_validator(paths)
        assert str(error.value) == "VALIDATOR_BUNDLE_INVALID"
        assert not paths["output_root"].exists()


