def test_validator_cleanup_retains_attempt_on_parent_identity_drift(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    preflight = _preflight()
    root = tmp_path / "validator-cleanup-parent-drift"
    nested = root / "runtime"
    member = nested / "member.py"
    nested.mkdir(parents=True)
    payload = b"created content\n"
    member.write_bytes(payload)

    parent_identity = preflight._validator_plain_directory_identity(root.parent)
    root_identity = preflight._validator_plain_directory_identity(root)
    nested_identity = preflight._validator_plain_directory_identity(nested)
    member_identity = preflight._validator_plain_file_identity(member)
    created_objects = {
        root: preflight._ValidatorCreatedObject(
            path=str(root),
            parent_identity=parent_identity,
            kind="directory",
            identity=root_identity,
            size=None,
            sha256=None,
        ),
        nested: preflight._ValidatorCreatedObject(
            path=str(nested),
            parent_identity=root_identity,
            kind="directory",
            identity=nested_identity,
            size=None,
            sha256=None,
        ),
        member: preflight._ValidatorCreatedObject(
            path=str(member),
            parent_identity=nested_identity,
            kind="file",
            identity=member_identity,
            size=len(payload),
            sha256=sha256(payload).hexdigest(),
        ),
    }

    displaced = root / "runtime-displaced"
    nested.rename(displaced)
    nested.mkdir()
    (nested / "member.py").write_bytes(payload)
    cleanup_session = _file_change_policy()._HeldNoFollowCreationSession(
        root.parent,
        code="VALIDATOR_BUNDLE_INVALID",
    )
    cleanup_session.hold_directory(root)
    cleanup_session.hold_directory(nested)
    removals: list[tuple[str, Path]] = []
    original_remove_file = cleanup_session.remove_file
    original_remove_directory = cleanup_session.remove_directory

    def recording_remove_file(path: Path, **kwargs: object) -> None:
        removals.append(("file", path))
        original_remove_file(path, **kwargs)

    def recording_remove_directory(path: Path, **kwargs: object) -> None:
        removals.append(("directory", path))
        original_remove_directory(path, **kwargs)

    monkeypatch.setattr(cleanup_session, "remove_file", recording_remove_file)
    monkeypatch.setattr(
        cleanup_session,
        "remove_directory",
        recording_remove_directory,
    )
    try:
        preflight._validator_remove_created_root(
            root,
            expected_root_identity=root_identity,
            created_objects=created_objects,
            creation_session=cleanup_session,
        )
    finally:
        cleanup_session.close()

    assert removals == []
    assert root.is_dir()
    assert displaced.is_dir()


@pytest.mark.parametrize("mutation", ("content", "same-content-replacement"))
def test_validator_cleanup_retains_final_handle_drift_before_delete(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    mutation: str,
) -> None:
    paths = _validator_fixture(tmp_path, monkeypatch)
    preflight = _preflight()
    policy = _file_change_policy()
    drifted: list[Path] = []
    before_paths: set[str] = set()

    def source_drift(stage: str, root: Path) -> None:
        if stage == "after-output-write":
            before_paths.update(
                path.relative_to(root).as_posix() for path in root.rglob("*")
            )
            paths["wheel"].write_bytes(paths["wheel"].read_bytes() + b"x")

    def mutate_at_final_open(path: Path) -> None:
        if drifted:
            return
        payload = path.read_bytes()
        if mutation == "content":
            path.write_bytes(b"x" * len(payload))
        elif mutation == "same-content-replacement":
            before = preflight._validator_plain_file_identity(path)
            path.unlink()
            path.write_bytes(payload)
            assert preflight._validator_plain_file_identity(path) != before
        else:
            raise AssertionError(mutation)
        drifted.append(path)

    monkeypatch.setattr(preflight, "_validator_freeze_checkpoint", source_drift)
    monkeypatch.setattr(policy, "_before_held_remove_file", mutate_at_final_open)

    with pytest.raises(RuntimeError) as error:
        _freeze_validator(paths)

    assert str(error.value) == "VALIDATOR_BUNDLE_INVALID"
    assert len(drifted) == 1
    assert paths["output_root"].is_dir()
    assert {
        path.relative_to(paths["output_root"]).as_posix()
        for path in paths["output_root"].rglob("*")
    } == before_paths


