@pytest.mark.parametrize(
    "mutation",
    (
        "record-order", "record-case", "record-variant", "record-ordinal",
        "record-duplicate", "record-missing", "record-extra",
        "policy-body", "policy-hash", "unhashable-action-token",
        "unhashable-output-category", "read-surface", "command-grammar",
        "file-grammar", "boolean-record-limit",
        "policy-bytes", "policy-binding-runtime-digest",
        "limits-key", "limits-value", "limits-order", "variant-pair",
        "manifest-bytes", "manifest-sha",
    ),
)
def test_operation_policy_authority_rejects_registry_and_policy_mutants(
    mutation: str,
) -> None:
    module = _approved_operation_policy()
    authorities = list(module._OPERATION_POLICY_AUTHORITIES)
    bindings = list(module._APPROVED_CAMPAIGN_OPERATION_POLICY_REGISTRY)
    canonical_bytes = module._APPROVED_CAMPAIGN_OPERATION_POLICY_REGISTRY_BYTES
    canonical_sha256 = module._APPROVED_CAMPAIGN_OPERATION_POLICY_REGISTRY_SHA256
    direct_policy = None

    if mutation == "record-order":
        bindings[0], bindings[1] = bindings[1], bindings[0]
    elif mutation == "record-case":
        bindings[0] = replace(bindings[0], case_id=CAMPAIGN_CASE_IDS[1])
    elif mutation == "record-variant":
        bindings[0] = replace(bindings[0], variant="suite-enabled")
    elif mutation == "record-ordinal":
        bindings[0] = replace(bindings[0], ordinal=2)
    elif mutation == "record-duplicate":
        bindings[1] = bindings[0]
    elif mutation == "record-missing":
        bindings.pop()
    elif mutation == "record-extra":
        bindings.append(bindings[0])
    elif mutation == "policy-body":
        authorities[0] = replace(
            authorities[0],
            command_actions=authorities[0].command_actions + (("pack", "test"),),
        )
    elif mutation == "policy-hash":
        authorities[0] = replace(
            authorities[0],
            operation_policy_sha256="0" * 64,
        )
    elif mutation == "unhashable-action-token":
        authorities[0] = replace(
            authorities[0],
            command_actions=((["pack"],),),
        )
    elif mutation == "unhashable-output-category":
        authorities[0] = replace(
            authorities[0],
            declared_output_categories=([],),
        )
    elif mutation == "read-surface":
        authorities[0] = replace(
            authorities[0],
            read_only_actions=authorities[0].read_only_actions[:-1],
        )
    elif mutation == "command-grammar":
        authorities[0] = replace(
            authorities[0],
            command_policy_version="complete-suite-kokoro-command-policy-v2",
        )
    elif mutation == "file-grammar":
        authorities[0] = replace(
            authorities[0],
            file_change_policy_version="complete-suite-file-change-policy-v2",
        )
    elif mutation == "boolean-record-limit":
        prototype = replace(
            authorities[0],
            record_constraints=(
                ("max_operational_cli_per_shell_record", True),
            ),
            canonical_bytes=b"",
            operation_policy_sha256="0" * 64,
        )
        policy_bytes = _canonical(module._operation_policy_payload(prototype))
        direct_policy = replace(
            prototype,
            canonical_bytes=policy_bytes,
            operation_policy_sha256=sha256(policy_bytes).hexdigest(),
        )
    elif mutation == "policy-bytes":
        authorities[0] = replace(
            authorities[0],
            canonical_bytes=authorities[0].canonical_bytes + b" ",
        )
    elif mutation == "policy-binding-runtime-digest":
        bindings[0] = replace(bindings[0], operation_policy_sha256="0" * 64)
    elif mutation == "limits-key":
        bindings[0] = replace(
            bindings[0],
            operation_limits=(
                ("file_adds", 0), ("file_updates", 0), ("tool_calls", 32),
            ),
        )
    elif mutation == "limits-value":
        bindings[0] = replace(
            bindings[0],
            operation_limits=(
                ("file_adds", 1), ("file_updates", 0), ("shell_calls", 32),
            ),
        )
    elif mutation == "limits-order":
        bindings[0] = replace(
            bindings[0],
            operation_limits=tuple(reversed(bindings[0].operation_limits)),
        )
    elif mutation == "variant-pair":
        bindings[12] = replace(
            bindings[12],
            operation_policy_sha256="f" * 64,
        )
    elif mutation == "manifest-bytes":
        canonical_bytes += b"\n"
    elif mutation == "manifest-sha":
        canonical_sha256 = "f" * 64

    if direct_policy is not None:
        with pytest.raises(
            RuntimeError,
            match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$",
        ):
            module._validate_policy(direct_policy)
        return

    with pytest.raises(RuntimeError, match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$"):
        module._validate_operation_policy_registry(
            tuple(bindings),
            authorities=tuple(authorities),
            canonical_bytes=canonical_bytes,
            canonical_sha256=canonical_sha256,
        )


def test_approved_evaluation_envelope_cross_checks_operation_policy_authority() -> None:
    module = _preflight()
    policy = _approved_operation_policy()
    for ordinal, variant, case_id in (
        (ordinal, variant, case_id)
        for ordinal, (variant, case_id) in enumerate(
            (
                *(("baseline", case_id) for case_id in CAMPAIGN_CASE_IDS),
                *(("suite-enabled", case_id) for case_id in CAMPAIGN_CASE_IDS),
            ),
            start=1,
        )
    ):
        binding = policy._operation_policy_binding(
            ordinal,
            variant=variant,
            case_id=case_id,
        )
        evaluation = _client_evaluation(
            mode="real_campaign_template",
            ordinal=ordinal,
            variant=variant,
            case_id=case_id,
        )
        assert evaluation.operation_policy_sha256 == (
            binding.operation_policy_sha256
        )
        assert evaluation.operation_limits == binding.operation_limits

    approved = _client_evaluation(mode="real_campaign_template")
    for updates in (
        {"case_id": CAMPAIGN_CASE_IDS[1]},
        {"variant": "suite-enabled"},
        {"probe_ordinal": 2},
        {"operation_policy_sha256": "0" * 64},
        {
            "operation_limits": (
                ("file_adds", 0), ("file_updates", 0), ("shell_calls", 31),
            )
        },
    ):
        with pytest.raises(
            RuntimeError,
            match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$",
        ):
            _recanonical_evaluation(approved, **updates)
    for lookup in (
        lambda: policy._operation_policy_authority("unknown-case"),
        lambda: policy._operation_policy_binding(0),
        lambda: policy._operation_policy_binding(25),
        lambda: policy._operation_policy_binding(
            1, variant="suite-enabled", case_id=CAMPAIGN_CASE_IDS[0]
        ),
    ):
        with pytest.raises(
            RuntimeError,
            match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$",
        ):
            lookup()


class _OperationPolicyOrdinaryComparisonError(Exception):
    pass


class _OperationPolicyHostileEquality:
    def __init__(self, exception: BaseException) -> None:
        self.exception = exception

    def __eq__(self, _other: object) -> bool:
        raise self.exception

    def __ne__(self, _other: object) -> bool:
        raise self.exception


@pytest.mark.parametrize(
    "boundary",
    (
        "file-rule-hostile",
        "policy-hostile",
        "registry-hostile",
        "authority-hostile",
        "binding-hostile-variant",
        "binding-hostile-case",
        "projection-hostile",
        "file-rule-missing",
        "policy-missing",
        "binding-missing",
        "projection-missing",
        "authorization-missing-projection",
    ),
)
def test_operation_policy_exception_normalization_rejects_malformed_objects(
    boundary: str,
) -> None:
    module = _approved_operation_policy()
    hostile = _OperationPolicyHostileEquality(
        _OperationPolicyOrdinaryComparisonError("hostile-policy-equality")
    )
    source_policy = module._operation_policy_authority(CAMPAIGN_CASE_IDS[0])
    authoring_policy = module._operation_policy_authority(
        "original-authoring-route"
    )
    binding = module._operation_policy_binding(1)
    projected = module._project_kokoro_cli_operation(
        ("portable-adapter", "pack", "install", "archive", "--json"),
        operational_json=True,
    )
    forged_rule = _unchecked_replace(
        authoring_policy.file_change_rules[0],
        root_token=hostile,
    )
    forged_policy = _unchecked_replace(source_policy, version=hostile)
    missing_rule = object.__new__(module._PortableFileChangeRule)
    missing_policy = object.__new__(module._OperationPolicyAuthority)
    missing_binding = object.__new__(
        module._ApprovedCampaignOperationPolicyBinding
    )
    missing_projection = object.__new__(module._ProjectedKokoroCliOperation)
    authorities = (
        forged_policy,
        *module._OPERATION_POLICY_AUTHORITIES[1:],
    )

    attempts = {
        "file-rule-hostile": lambda: module._validate_file_rule(forged_rule),
        "policy-hostile": lambda: module._validate_policy(forged_policy),
        "registry-hostile": lambda: module._validate_operation_policy_registry(
            module._APPROVED_CAMPAIGN_OPERATION_POLICY_REGISTRY,
            authorities=authorities,
        ),
        "authority-hostile": lambda: module._operation_policy_authority(
            hostile
        ),
        "binding-hostile-variant": lambda: module._operation_policy_binding(
            1,
            variant=hostile,
        ),
        "binding-hostile-case": lambda: module._operation_policy_binding(
            1,
            case_id=hostile,
        ),
        "projection-hostile": lambda: module._project_kokoro_cli_operation(
            ("portable-adapter", hostile),
            operational_json=True,
        ),
        "file-rule-missing": lambda: module._validate_file_rule(missing_rule),
        "policy-missing": lambda: module._validate_policy(missing_policy),
        "binding-missing": lambda: (
            module._validated_registered_operation_policy_pair(
                missing_binding,
                source_policy,
            )
        ),
        "projection-missing": lambda: (
            module._validate_projected_kokoro_cli_operation(
                missing_projection
            )
        ),
        "authorization-missing-projection": lambda: (
            module._authorize_operation_policy_shell_record_prerequisite(
                (missing_projection,),
                binding=binding,
                policy=source_policy,
            )
        ),
    }
    assert projected.kind == "operational"
    with pytest.raises(
        RuntimeError,
        match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$",
    ):
        attempts[boundary]()


@pytest.mark.parametrize(
    "exception_type",
    (KeyboardInterrupt, SystemExit, GeneratorExit),
)
def test_operation_policy_exception_normalization_preserves_baseexception(
    exception_type: type[BaseException],
) -> None:
    module = _approved_operation_policy()
    policy = module._operation_policy_authority("original-authoring-route")
    sentinel = f"unmasked-{exception_type.__name__}"
    forged_rule = _unchecked_replace(
        policy.file_change_rules[0],
        root_token=_OperationPolicyHostileEquality(exception_type(sentinel)),
    )
    with pytest.raises(exception_type, match=sentinel):
        module._validate_file_rule(forged_rule)


def test_operation_policy_cli_projection_is_closed_portable_and_strict() -> None:
    module = _approved_operation_policy()

    assert len(module._KOKORO_CLI_ACTION_LEAVES) == 31
    assert module._KOKORO_CLI_ACTION_LEAVES == _command_policy()._CLI_ACTIONS
    assert module._APPROVED_CAMPAIGN_OPERATION_POLICY_REGISTRY_SHA256 == (
        "21c78cd15e472a729401ba6da52667c76161d49fba9c5aa210af6694189deaf0"
    )

    operational = module._project_kokoro_cli_operation(
        ("adapter-entrypoint", "pack", "install", "--source", "fixture"),
        operational_json=True,
    )
    assert operational.kind == "operational"
    assert operational.arguments == (
        "pack", "install", "--source", "fixture",
    )
    assert operational.operational_json is True
    assert operational.selector == ("pack", "install")
    assert operational.action == ("pack", "install")
    same_semantics_different_adapter = module._project_kokoro_cli_operation(
        ("another-adapter", "pack", "install", "--source", "fixture"),
        operational_json=True,
    )
    assert same_semantics_different_adapter == operational
    with pytest.raises(FrozenInstanceError):
        operational.kind = "help"

    help_prefix = module._project_kokoro_cli_operation(
        ("different-adapter", "character", "draft"),
        operational_json=False,
    )
    assert help_prefix.kind == "help"
    assert help_prefix.operational_json is False
    assert help_prefix.selector == ("character", "draft")
    assert help_prefix.action is None

    full_help = module._project_kokoro_cli_operation(
        ("ignored-adapter", "runtime", "validate", "--help"),
        operational_json=False,
    )
    assert full_help.kind == "help"
    assert full_help.selector == ("runtime", "validate")
    assert full_help.action == ("runtime", "validate")

    bare_help = module._project_kokoro_cli_operation(
        ("portable-adapter",),
        operational_json=False,
    )
    assert bare_help.kind == "help"
    assert bare_help.selector == ()
    assert bare_help.action is None


