def test_operation_policy_shell_record_prerequisite_authorizes_case_scoped_cli() -> None:
    module = _approved_operation_policy()

    examples = (
        (
            1,
            ("portable-adapter", "pack", "install", "archive", "--json"),
            ("pack", "install"),
        ),
        (
            2,
            (
                "portable-adapter", "runtime", "plan", "--semantic",
                "input", "--policy", "policy", "--json",
            ),
            ("runtime", "plan"),
        ),
        (
            10,
            (
                "portable-adapter", "character", "draft", "compile",
                "source", "--json",
            ),
            ("character", "draft", "compile"),
        ),
    )
    for ordinal, argv, expected_action in examples:
        binding = module._operation_policy_binding(ordinal)
        policy = module._operation_policy_authority(binding.case_id)
        projected = module._project_kokoro_cli_operation(
            argv,
            operational_json=True,
        )
        assert module._authorize_operation_policy_shell_record_prerequisite(
            (projected,),
            binding=binding,
            policy=policy,
        ) == (projected,)
        assert projected.action == expected_action


def test_operation_policy_shell_record_prerequisite_derives_help_from_case_leaves() -> None:
    module = _approved_operation_policy()
    global_binding = module._operation_policy_binding(1)
    global_policy = module._operation_policy_authority(global_binding.case_id)

    allowed_help = tuple(
        module._project_kokoro_cli_operation(argv, operational_json=False)
        for argv in (
            ("portable-adapter",),
            ("portable-adapter", "pack"),
            ("portable-adapter", "config", "default"),
            ("portable-adapter", "pack", "install", "--help"),
        )
    )
    assert module._authorize_operation_policy_shell_record_prerequisite(
        allowed_help,
        binding=global_binding,
        policy=global_policy,
    ) == allowed_help

    for argv in (
        ("portable-adapter", "runtime"),
        ("portable-adapter", "runtime", "validate", "--help"),
    ):
        projected = module._project_kokoro_cli_operation(
            argv,
            operational_json=False,
        )
        with pytest.raises(
            RuntimeError,
            match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$",
        ):
            module._authorize_operation_policy_shell_record_prerequisite(
                (projected,),
                binding=global_binding,
                policy=global_policy,
            )

    research_binding = module._operation_policy_binding(11)
    research_policy = module._operation_policy_authority(
        research_binding.case_id
    )
    assert module._authorize_operation_policy_shell_record_prerequisite(
        (),
        binding=research_binding,
        policy=research_policy,
    ) == ()
    for argv in (
        ("portable-adapter",),
        ("portable-adapter", "research"),
        ("portable-adapter", "research", "request", "validate", "--help"),
    ):
        projected = module._project_kokoro_cli_operation(
            argv,
            operational_json=False,
        )
        with pytest.raises(
            RuntimeError,
            match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$",
        ):
            module._authorize_operation_policy_shell_record_prerequisite(
                (projected,),
                binding=research_binding,
                policy=research_policy,
            )


def test_operation_policy_shell_record_prerequisite_rejects_mixed_or_multiple_cli() -> None:
    module = _approved_operation_policy()
    binding = module._operation_policy_binding(1)
    policy = module._operation_policy_authority(binding.case_id)
    operational = module._project_kokoro_cli_operation(
        ("portable-adapter", "pack", "list", "--scope", "global", "--json"),
        operational_json=True,
    )
    second_operational = module._project_kokoro_cli_operation(
        ("portable-adapter", "session", "show", "--json"),
        operational_json=True,
    )
    help_record = module._project_kokoro_cli_operation(
        ("portable-adapter", "pack"),
        operational_json=False,
    )

    for records in (
        (operational, second_operational),
        (help_record, operational),
    ):
        with pytest.raises(
            RuntimeError,
            match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$",
        ):
            module._authorize_operation_policy_shell_record_prerequisite(
                records,
                binding=binding,
                policy=policy,
            )

    disallowed = module._project_kokoro_cli_operation(
        ("portable-adapter", "runtime", "validate", "--json"),
        operational_json=True,
    )
    with pytest.raises(
        RuntimeError,
        match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$",
    ):
        module._authorize_operation_policy_shell_record_prerequisite(
            (disallowed,),
            binding=binding,
            policy=policy,
        )


def test_operation_policy_shell_record_prerequisite_rejects_forgery_and_malformed() -> None:
    module = _approved_operation_policy()
    binding = module._operation_policy_binding(1)
    policy = module._operation_policy_authority(binding.case_id)
    projected = module._project_kokoro_cli_operation(
        ("portable-adapter", "pack", "install", "archive", "--json"),
        operational_json=True,
    )
    forged_projected = _unchecked_frozen(
        type(projected),
        arguments=projected.arguments,
        operational_json=projected.operational_json,
        kind=projected.kind,
        selector=("runtime", "validate"),
        action=("runtime", "validate"),
    )
    forged_binding = replace(binding, operation_policy_sha256="0" * 64)
    workspace_policy = module._operation_policy_authority(
        "workspace-override-explicit-activation"
    )

    attempts = (
        ((forged_projected,), binding, policy),
        ((projected,), forged_binding, policy),
        ((projected,), binding, workspace_policy),
        ([projected], binding, policy),
        ((object(),), binding, policy),
    )
    for records, attempted_binding, attempted_policy in attempts:
        with pytest.raises(
            RuntimeError,
            match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$",
        ):
            module._authorize_operation_policy_shell_record_prerequisite(
                records,
                binding=attempted_binding,
                policy=attempted_policy,
            )

    for values in (
        {
            "arguments": (),
            "operational_json": False,
            "kind": "operational",
            "selector": (),
            "action": None,
        },
        {
            "arguments": ("pack", "install", "--json"),
            "operational_json": True,
            "kind": "operational",
            "selector": ["pack", "install"],
            "action": ("pack", "install"),
        },
    ):
        with pytest.raises(
            RuntimeError,
            match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$",
        ):
            module._ProjectedKokoroCliOperation(**values)


def _operation_budget_allowed_shell_record(module: object) -> object:
    return module._project_kokoro_cli_operation(
        ("portable-adapter", "pack", "install", "archive", "--json"),
        operational_json=True,
    )


def test_operation_budget_reservation_ledger_starts_zero_and_returns_detached_frozen_snapshots() -> None:
    module = _approved_operation_policy()
    binding = module._operation_policy_binding(1)
    ledger = module._OperationBudgetReservationLedger(binding)

    initial = ledger.snapshot()
    assert tuple(field.name for field in fields(initial)) == (
        "ordinal",
        "variant",
        "case_id",
        "operation_policy_sha256",
        "operation_limits",
        "operation_counts",
    )
    assert (
        initial.ordinal,
        initial.variant,
        initial.case_id,
        initial.operation_policy_sha256,
        initial.operation_limits,
    ) == (
        binding.ordinal,
        binding.variant,
        binding.case_id,
        binding.operation_policy_sha256,
        binding.operation_limits,
    )
    assert initial.operation_counts == (
        ("file_adds", 0),
        ("file_updates", 0),
        ("shell_calls", 0),
    )
    with pytest.raises(FrozenInstanceError):
        initial.operation_counts = (("shell_calls", 99),)

    projected = _operation_budget_allowed_shell_record(module)
    reserved = ledger.authorize_and_reserve_shell_record((projected,))
    current = ledger.snapshot()
    assert reserved.projected_records == (projected,)
    assert reserved.usage_snapshot == current
    assert reserved.usage_snapshot is not current
    assert current is not initial
    assert current.operation_counts == (
        ("file_adds", 0),
        ("file_updates", 0),
        ("shell_calls", 1),
    )
    assert initial.operation_counts == (
        ("file_adds", 0),
        ("file_updates", 0),
        ("shell_calls", 0),
    )
    assert module._APPROVED_CAMPAIGN_OPERATION_POLICY_REGISTRY_SHA256 == (
        "21c78cd15e472a729401ba6da52667c76161d49fba9c5aa210af6694189deaf0"
    )


def test_operation_budget_reservation_ledger_requires_an_exact_registered_binding() -> None:
    module = _approved_operation_policy()
    binding = module._operation_policy_binding(1)

    class BindingSubclass(type(binding)):
        pass

    subclass = BindingSubclass(
        ordinal=binding.ordinal,
        variant=binding.variant,
        case_id=binding.case_id,
        operation_policy_sha256=binding.operation_policy_sha256,
        operation_limits=binding.operation_limits,
    )
    missing = object.__new__(type(binding))
    attempts = (
        replace(binding, operation_policy_sha256="0" * 64),
        replace(
            binding,
            operation_limits=(
                ("file_adds", 0),
                ("file_updates", 0),
                ("shell_calls", True),
            ),
        ),
        subclass,
        missing,
        object(),
        True,
    )
    for attempted in attempts:
        with pytest.raises(
            RuntimeError,
            match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$",
        ):
            module._OperationBudgetReservationLedger(attempted)


def test_operation_budget_reservation_ledger_authorization_failures_consume_nothing() -> None:
    module = _approved_operation_policy()
    ledger = module._OperationBudgetReservationLedger(
        module._operation_policy_binding(1)
    )
    allowed = _operation_budget_allowed_shell_record(module)
    second_allowed = module._project_kokoro_cli_operation(
        ("portable-adapter", "session", "show", "--json"),
        operational_json=True,
    )
    disallowed = module._project_kokoro_cli_operation(
        ("portable-adapter", "runtime", "validate", "--json"),
        operational_json=True,
    )
    attempts = (
        (disallowed,),
        (allowed, second_allowed),
        (object(),),
        [allowed],
        True,
    )
    for records in attempts:
        with pytest.raises(
            RuntimeError,
            match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$",
        ):
            ledger.authorize_and_reserve_shell_record(records)
        assert ledger.snapshot().operation_counts == (
            ("file_adds", 0),
            ("file_updates", 0),
            ("shell_calls", 0),
        )


def test_operation_budget_reservation_ledger_enforces_shell_limit_without_rollback() -> None:
    module = _approved_operation_policy()
    ledger = module._OperationBudgetReservationLedger(
        module._operation_policy_binding(1)
    )
    record = _operation_budget_allowed_shell_record(module)

    old_snapshots = tuple(
        ledger.authorize_and_reserve_shell_record((record,)).usage_snapshot
        for _index in range(32)
    )
    assert old_snapshots[-1].operation_counts[-1] == ("shell_calls", 32)
    with pytest.raises(
        RuntimeError,
        match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$",
    ):
        ledger.authorize_and_reserve_shell_record((record,))
    assert ledger.snapshot() == old_snapshots[-1]
    assert old_snapshots[0].operation_counts[-1] == ("shell_calls", 1)

    for forbidden_surface in (
        "rollback",
        "reset",
        "decrement",
        "reserve",
        "reserve_delta",
        "_reserve_counter_locked",
        "counts",
        "operation_counts",
    ):
        assert not hasattr(ledger, forbidden_surface)


def test_operation_budget_reservation_ledger_enforces_file_limits_independently() -> None:
    module = _approved_operation_policy()
    workspace = module._OperationBudgetReservationLedger(
        module._operation_policy_binding(2)
    )

    for _index in range(5):
        workspace.reserve_file_change("add")
    for _index in range(5):
        workspace.reserve_file_change("update")
    at_limit = workspace.snapshot()
    assert at_limit.operation_counts == (
        ("file_adds", 5),
        ("file_updates", 5),
        ("shell_calls", 0),
    )
    for kind in ("add", "update"):
        with pytest.raises(
            RuntimeError,
            match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$",
        ):
            workspace.reserve_file_change(kind)
        assert workspace.snapshot() == at_limit

    authoring = module._OperationBudgetReservationLedger(
        module._operation_policy_binding(10)
    )
    authoring_add_snapshots = tuple(
        authoring.reserve_file_change("add") for _index in range(21)
    )
    assert authoring_add_snapshots[-1].operation_counts == (
        ("file_adds", 21),
        ("file_updates", 0),
        ("shell_calls", 0),
    )
    authoring_update_snapshots = tuple(
        authoring.reserve_file_change("update") for _index in range(21)
    )
    authoring_at_limit = authoring.snapshot()
    assert authoring_update_snapshots[-1] == authoring_at_limit
    assert authoring_at_limit.operation_counts == (
        ("file_adds", 21),
        ("file_updates", 21),
        ("shell_calls", 0),
    )
    for kind in ("add", "update"):
        with pytest.raises(
            RuntimeError,
            match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$",
        ):
            authoring.reserve_file_change(kind)
        assert authoring.snapshot() == authoring_at_limit

    zero_limit = module._OperationBudgetReservationLedger(
        module._operation_policy_binding(1)
    )
    for kind in ("add", "update", "delete", "", True, None, object()):
        with pytest.raises(
            RuntimeError,
            match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$",
        ):
            zero_limit.reserve_file_change(kind)
        assert zero_limit.snapshot().operation_counts == (
            ("file_adds", 0),
            ("file_updates", 0),
            ("shell_calls", 0),
        )


def test_operation_budget_reservation_ledger_is_atomic_at_final_shell_slot() -> None:
    import threading

    module = _approved_operation_policy()
    ledger = module._OperationBudgetReservationLedger(
        module._operation_policy_binding(1)
    )
    record = _operation_budget_allowed_shell_record(module)
    for _index in range(31):
        ledger.authorize_and_reserve_shell_record((record,))

    barrier = threading.Barrier(3)
    outcome_lock = threading.Lock()
    outcomes: list[tuple[str, object]] = []

    def race_for_slot() -> None:
        barrier.wait()
        try:
            result = ledger.authorize_and_reserve_shell_record((record,))
        except RuntimeError as exc:
            outcome = ("rejected", exc.args)
        else:
            outcome = ("reserved", result.usage_snapshot.operation_counts)
        with outcome_lock:
            outcomes.append(outcome)

    workers = tuple(threading.Thread(target=race_for_slot) for _ in range(2))
    for worker in workers:
        worker.start()
    barrier.wait()
    for worker in workers:
        worker.join(timeout=10)
        assert not worker.is_alive()

    assert sorted(kind for kind, _value in outcomes) == [
        "rejected",
        "reserved",
    ]
    assert next(value for kind, value in outcomes if kind == "rejected") == (
        "COMMAND_LAUNCH_SPEC_MISMATCH",
    )
    assert ledger.snapshot().operation_counts == (
        ("file_adds", 0),
        ("file_updates", 0),
        ("shell_calls", 32),
    )


def _captured_launch_input_record(value: object) -> dict[str, object]:
    return {
        "identity": _identity_record(value.identity),
        "path": value.path,
        "sha256": value.sha256,
        "utf8_bytes": value.utf8_bytes,
    }


def _codex_identity_payload(value: object) -> dict[str, object]:
    return {
        "client_label": value.client_label,
        "distribution_manifest": _captured_launch_input_record(
            value.distribution_manifest
        ),
        "distribution_name": value.distribution_name,
        "distribution_version": value.distribution_version,
        "executable_identity": _identity_record(value.executable_identity),
        "executable_path": value.executable_path,
        "executable_sha256": value.executable_sha256,
        "executable_size": value.executable_size,
        "platform_manifest": _captured_launch_input_record(
            value.platform_manifest
        ),
        "platform_name": value.platform_name,
        "platform_package_key": value.platform_package_key,
        "platform_version": value.platform_version,
        "version": value.version,
    }


def _recanonical_codex(value: object, **updates: object) -> object:
    values = {
        field.name: updates.get(field.name, getattr(value, field.name))
        for field in fields(value)
        if field.name != "canonical_sha256"
    }
    prototype = _unchecked_frozen(type(value), **values, canonical_sha256="0" * 64)
    return _unchecked_frozen(
        type(value),
        **values,
        canonical_sha256=sha256(_canonical(_codex_identity_payload(prototype))).hexdigest(),
    )


def _filesystem_codex_identity(tmp_path: Path) -> tuple[object, dict[str, Path]]:
    module = _preflight()
    distribution_root = tmp_path / "codex-distribution"
    platform_root = (
        distribution_root
        / "node_modules"
        / "@openai"
        / "codex-win32-x64"
    )
    executable = (
        platform_root
        / "vendor"
        / "x86_64-pc-windows-msvc"
        / "bin"
        / "codex.exe"
    )
    executable.parent.mkdir(parents=True)
    distribution_manifest = distribution_root / "package.json"
    distribution_manifest.parent.mkdir(parents=True, exist_ok=True)
    distribution_manifest.write_bytes(
        b'{"bin":{"codex":"bin/codex.js"},'
        b'"name":"@openai/codex",'
        b'"optionalDependencies":{'
        b'"@openai/codex-win32-x64":'
        b'"npm:@openai/codex@0.149.0-win32-x64"},'
        b'"version":"0.149.0"}'
    )
    platform_manifest = platform_root / "package.json"
    platform_manifest.write_bytes(
        b'{"name":"@openai/codex","version":"0.149.0-win32-x64"}'
    )
    executable.write_bytes(b"MZ synthetic pinned codex 0.149.0\n")
    executable_payload, executable_identity = (
        module._validator_capture_plain_file(
            executable,
            max_bytes=64 * 1024 * 1024,
        )
    )
    prototype = _unchecked_frozen(
        module.FrozenCodexClientIdentity,
        version="complete-suite-codex-client-identity-v1",
        executable_path=str(executable),
        executable_size=len(executable_payload),
        executable_sha256=sha256(executable_payload).hexdigest(),
        executable_identity=executable_identity,
        distribution_manifest=_actual_capture(distribution_manifest),
        platform_manifest=_actual_capture(platform_manifest),
        distribution_name="@openai/codex",
        distribution_version="0.149.0",
        platform_package_key="@openai/codex-win32-x64",
        platform_name="@openai/codex",
        platform_version="0.149.0-win32-x64",
        client_label="codex-cli 0.149.0",
        canonical_sha256="0" * 64,
    )
    return _recanonical_codex(prototype), {
        "distribution_manifest": distribution_manifest,
        "platform_manifest": platform_manifest,
        "executable": executable,
    }


def _native_leaf_payload(value: object) -> dict[str, object]:
    return {
        "ancestor_identities": [
            _identity_record(identity) for identity in value.ancestor_identities
        ],
        "argv_grammar_sha256": value.argv_grammar_sha256,
        "constructor_attribute_set_sha256": (
            value.constructor_attribute_set_sha256
        ),
        "constructor_class": value.constructor_class,
        "constructor_implementation_set_sha256": (
            value.constructor_implementation_set_sha256
        ),
        "cwd_role": value.cwd_role,
        "descendant_policy": value.descendant_policy,
        "environment_grammar_sha256": value.environment_grammar_sha256,
        "executable_identity": _identity_record(value.executable_identity),
        "executable_path": value.executable_path,
        "executable_sha256": value.executable_sha256,
        "executable_size": value.executable_size,
        "file_version": value.file_version,
        "hardlink_manifest_sha256": value.hardlink_manifest_sha256,
        "hardlink_paths": list(value.hardlink_paths),
        "job_topology_sha256": value.job_topology_sha256,
        "permitted_constructor_implementations": [
            list(item) for item in value.permitted_constructor_implementations
        ],
        "product_version": value.product_version,
        "role": value.role,
        "version": value.version,
    }


def _recanonical_native_leaf(value: object, **updates: object) -> object:
    values = {
        field.name: updates.get(field.name, getattr(value, field.name))
        for field in fields(value)
        if field.name != "canonical_sha256"
    }
    prototype = _unchecked_frozen(type(value), **values, canonical_sha256="0" * 64)
    return _unchecked_frozen(
        type(value),
        **values,
        canonical_sha256=sha256(_canonical(_native_leaf_payload(prototype))).hexdigest(),
    )


def _recanonical_guarded_runtime(value: object, **updates: object) -> object:
    module = _preflight()
    values = {
        field.name: updates.get(field.name, getattr(value, field.name))
        for field in fields(value)
        if field.name != "canonical_sha256"
    }
    prototype = _unchecked_frozen(type(value), **values, canonical_sha256="0" * 64)
    return _unchecked_frozen(
        type(value),
        **values,
        canonical_sha256=sha256(
            _canonical(module._guarded_runtime_payload(prototype))
        ).hexdigest(),
    )


def _evaluation_records(root: Path) -> tuple[object, ...]:
    records: list[object] = []
    evaluations = [
        _client_evaluation(mode="loopback_probe", ordinal=ordinal)
        for ordinal in range(1, 5)
    ]
    ordinal = 1
    for variant in ("baseline", "suite-enabled"):
        for case_id in CAMPAIGN_CASE_IDS:
            evaluations.append(
                _client_evaluation(
                    mode="real_campaign_template",
                    ordinal=ordinal,
                    variant=variant,
                    case_id=case_id,
                )
            )
            ordinal += 1
    names = (
        *(f"loopback-{ordinal:02d}.json" for ordinal in range(1, 5)),
        *(f"template-{ordinal:02d}.json" for ordinal in range(1, 25)),
    )
    for name, evaluation in zip(names, evaluations, strict=True):
        records.append(
            _capture(
                root / name,
                evaluation.canonical_bytes,
                inode=500 + len(records) + 1,
            )
        )
    return tuple(records)


def _evaluation_manifest_bytes(records: tuple[object, ...]) -> bytes:
    return _canonical(
        {
            "records": [
                _captured_launch_input_record(record) for record in records
            ],
            "version": "complete-suite-client-evaluation-manifest-v1",
        }
    )


def _evaluation_manifest_sha256(records: tuple[object, ...]) -> str:
    return sha256(_evaluation_manifest_bytes(records)).hexdigest()


def _synthetic_launch_executable_descriptors(
    module: object,
    launch_preflight: object,
    *,
    updates: dict[str, dict[str, object]] | None = None,
) -> tuple[object, ...]:
    descriptors = (
        module._LaunchExecutableDescriptor(
            role="codex",
            path=launch_preflight.codex.executable_path,
            size=launch_preflight.codex.executable_size,
            sha256=launch_preflight.codex.executable_sha256,
            identity=launch_preflight.codex.executable_identity,
            version_fields=(
                ("client_label", launch_preflight.codex.client_label),
                (
                    "distribution_version",
                    launch_preflight.codex.distribution_version,
                ),
                ("platform_version", launch_preflight.codex.platform_version),
            ),
            hardlink_paths=(launch_preflight.codex.executable_path,),
        ),
        module._LaunchExecutableDescriptor(
            role="pwsh",
            path=launch_preflight.shell.path,
            size=201,
            sha256=launch_preflight.shell.sha256,
            identity=_identity(341),
            version_fields=(
                ("edition", launch_preflight.shell.edition),
                ("file_version", launch_preflight.shell.file_version),
                ("parser_version", launch_preflight.shell.parser_version),
                ("product_version", launch_preflight.shell.product_version),
            ),
            hardlink_paths=(launch_preflight.shell.path,),
        ),
        module._LaunchExecutableDescriptor(
            role="powershell_decoder",
            path=launch_preflight.decoder_path,
            size=202,
            sha256=launch_preflight.decoder_sha256,
            identity=_identity(342),
            version_fields=(),
            hardlink_paths=(launch_preflight.decoder_path,),
        ),
        module._LaunchExecutableDescriptor(
            role="python",
            path=launch_preflight.guarded_python.python_path,
            size=launch_preflight.guarded_python.python_size,
            sha256=launch_preflight.guarded_python.python_sha256,
            identity=launch_preflight.guarded_python.python_identity,
            version_fields=(
                ("cache_tag", launch_preflight.guarded_python.cache_tag),
                (
                    "python_version",
                    launch_preflight.guarded_python.python_version,
                ),
            ),
            hardlink_paths=(launch_preflight.guarded_python.python_path,),
        ),
        module._LaunchExecutableDescriptor(
            role="rg",
            path=launch_preflight.rg_path,
            size=203,
            sha256=launch_preflight.rg_sha256,
            identity=_identity(343),
            version_fields=(),
            hardlink_paths=(launch_preflight.rg_path,),
        ),
        module._LaunchExecutableDescriptor(
            role="comspec",
            path=launch_preflight.comspec_path,
            size=204,
            sha256=launch_preflight.comspec_sha256,
            identity=_identity(344),
            version_fields=(),
            hardlink_paths=(launch_preflight.comspec_path,),
        ),
    )
    if updates is None:
        return descriptors
    return tuple(
        replace(descriptor, **updates.get(descriptor.role, {}))
        for descriptor in descriptors
    )


def test_launch_executable_descriptor_binds_explicit_hardlink_manifest() -> None:
    module = _preflight()
    system_path = r"C:\Windows\System32\cmd.exe"
    component_path = (
        r"C:\Windows\WinSxS\amd64_microsoft-windows-commandprompt_"
        r"31bf3856ad364e35_10.0.26100.8972_none_269f7821ca85a37b\cmd.exe"
    )
    paths = tuple(
        sorted((system_path, component_path), key=lambda item: (item.casefold(), item))
    )
    identity = _unchecked_replace(_identity(344), link_count=2)

    descriptor = module._LaunchExecutableDescriptor(
        role="comspec",
        path=system_path,
        size=204,
        sha256="7" * 64,
        identity=identity,
        version_fields=(),
        hardlink_paths=paths,
    )

    assert module._launch_executable_descriptor_record(descriptor)[
        "hardlink_paths"
    ] == list(paths)
    for mutation in (
        (system_path,),
        tuple(reversed(paths)),
        (component_path, component_path),
    ):
        with pytest.raises(
            RuntimeError,
            match=f"^{module.COMMAND_LAUNCH_SPEC_MISMATCH}$",
        ):
            replace(descriptor, hardlink_paths=mutation)


def _install_synthetic_validated_launch_authority(
    launch_preflight: object,
    *,
    loopback_port: int = 43123,
    descriptor_updates: dict[str, dict[str, object]] | None = None,
    expected_updates: dict[str, str] | None = None,
) -> object:
    module = _preflight()
    descriptors = _synthetic_launch_executable_descriptors(
        module,
        launch_preflight,
        updates=descriptor_updates,
    )
    initial_expected = module._launch_reference_expected_digests(
        preflight=launch_preflight,
        executable_descriptors=descriptors,
        loopback_port=loopback_port,
    )
    precontract_preflight = _unchecked_replace(
        launch_preflight,
        exact_config_sha256=initial_expected[0],
        normalized_config_sha256=initial_expected[1],
    )
    expected = module._launch_reference_expected_digests(
        preflight=precontract_preflight,
        executable_descriptors=descriptors,
        loopback_port=loopback_port,
    )
    expected_values = dict(
        zip(
            (
                "exact_config_sha256",
                "normalized_config_sha256",
                "loopback_launch_sha256",
                "real_launch_template_sha256",
            ),
            expected,
            strict=True,
        )
    )
    if expected_updates is not None:
        expected_values.update(expected_updates)
    authorized_preflight = _unchecked_replace(
        precontract_preflight,
        **expected_values,
    )
    authority = module._ValidatedLaunchPreflightAuthority(
        preflight_binding_sha256=module._launch_preflight_binding_sha256(
            authorized_preflight
        ),
        prelaunch_binding_sha256=module._launch_prelaunch_binding_sha256(
            authorized_preflight
        ),
        prelaunch_authority=module._launch_detach_prelaunch_authority(
            authorized_preflight._launch_durable_authority.prelaunch
        ),
        executable_descriptors=descriptors,
        **expected_values,
    )
    object.__setattr__(
        authorized_preflight,
        "_validated_launch_authority",
        authority,
    )
    return authorized_preflight


def _launch_preflight(
    tmp_path: Path,
    *,
    bootstrap_content: bytes = b"bootstrap\n",
):
    preflight = _preflight()
    command_plan = _command_plan()
    tool_root = tmp_path / "frozen-tools"
    guarded_root = tmp_path / "guarded-python-runtime"
    codex_path = tool_root / "codex" / "codex.exe"
    shell_path = tool_root / "pwsh" / "pwsh.exe"
    decoder_path = tool_root / "decoder" / "decoder.ps1"
    python_path = tool_root / "python" / "python.exe"
    rg_path = tool_root / "rg" / "rg.exe"
    comspec_path = Path(r"C:\Windows\System32\cmd.exe")
    distribution_manifest = _capture(
        tool_root / "codex" / "package.json",
        (
            b'{"bin":{"codex":"bin/codex.js"},'
            b'"name":"@openai/codex",'
            b'"optionalDependencies":{"@openai/codex-win32-x64":"0.149.0-win32-x64"},'
            b'"version":"0.149.0"}'
        ),
        inode=302,
    )
    platform_manifest = _capture(
        tool_root / "codex" / "platform-package.json",
        b'{"name":"@openai/codex-win32-x64","version":"0.149.0-win32-x64"}',
        inode=303,
    )
    codex = _recanonical_codex(_unchecked_frozen(
        preflight.FrozenCodexClientIdentity,
        version="complete-suite-codex-client-identity-v1",
        executable_path=str(codex_path),
        executable_size=101,
        executable_sha256="d" * 64,
        executable_identity=_identity(301),
        distribution_manifest=distribution_manifest,
        platform_manifest=platform_manifest,
        distribution_name="@openai/codex",
        distribution_version="0.149.0",
        platform_package_key="@openai/codex-win32-x64",
        platform_name="@openai/codex",
        platform_version="0.149.0-win32-x64",
        client_label="codex-cli 0.149.0",
        canonical_sha256="0" * 64,
    ))
    native_leaves = tuple(
        _recanonical_native_leaf(_unchecked_frozen(
            preflight.FrozenNativeLeaf,
            version="complete-suite-native-leaf-v1",
            role=role,
            executable_path=str(tool_root / role / f"{role}.exe"),
            executable_size=111 + index,
            executable_sha256=character * 64,
            executable_identity=_identity(310 + index),
            ancestor_identities=(_identity(320 + index),),
            hardlink_paths=(str(tool_root / role / f"{role}.exe"),),
            hardlink_manifest_sha256=sha256(
                _canonical(
                    {
                        "paths": [str(tool_root / role / f"{role}.exe")],
                        "version": "complete-suite-native-hardlink-manifest-v1",
                    }
                )
            ).hexdigest(),
            file_version="1.0.0.0",
            product_version="1.0.0",
            argv_grammar_sha256="1" * 64,
            environment_grammar_sha256="2" * 64,
            cwd_role="case-root",
            constructor_class="guarded-target-or-native-leaf",
            permitted_constructor_implementations=(
                (
                    ("host-native-core-v1", "0" * 64),
                    ("broker-native-core-v1", "3" * 64),
                )
                if role == "git"
                else (("broker-native-core-v1", "3" * 64),)
            ),
            constructor_implementation_set_sha256=sha256(
                _canonical(
                    {
                        "implementations": (
                            [
                                ["host-native-core-v1", "0" * 64],
                                ["broker-native-core-v1", "3" * 64],
                            ]
                            if role == "git"
                            else [["broker-native-core-v1", "3" * 64]]
                        ),
                        "version": (
                            "complete-suite-constructor-implementation-set-v1"
                        ),
                    }
                )
            ).hexdigest(),
            constructor_attribute_set_sha256="5" * 64,
            job_topology_sha256="6" * 64,
            descendant_policy="child-process-restricted-zero-descendants",
            canonical_sha256="0" * 64,
        ))
        for index, (role, character) in enumerate((('git', 'f'), ('node', 'e')))
    )
    import_entry = preflight.FrozenImportEntry(
        relative_path="python.exe",
        kind="file",
        byte_count=10,
        sha256="1" * 64,
        identity=_identity(334),
    )
    runtime_entry = preflight.FrozenImportEntry(
        relative_path="placeholder.py",
        kind="file",
        byte_count=1,
        sha256="2" * 64,
        identity=_identity(335),
    )
    import_roots = (
        preflight._guarded_make_import_root(
            role="python_home",
            path=str(guarded_root),
            identity=_identity(330),
            entries=(import_entry,),
        ),
        preflight._guarded_make_import_root(
            role="runtime_site",
            path=str(guarded_root / "runtime-site"),
            identity=_identity(336),
            entries=(runtime_entry,),
        ),
    )
    guarded_python = _recanonical_guarded_runtime(_unchecked_frozen(
        preflight.FrozenGuardedPythonRuntime,
        version="complete-suite-guarded-python-runtime-v1",
        root=str(guarded_root),
        root_identity=_identity(330),
        python_path=str(guarded_root / "python.exe"),
        python_size=10,
        python_sha256="1" * 64,
        python_identity=_identity(331),
        bootstrap=_capture(
            guarded_root / "complete_suite_release_python_bootstrap.py",
            bootstrap_content,
            inode=332,
        ),
        project_metadata=_capture(
            guarded_root / "pyproject.toml", b"[project]\n", inode=333
        ),
        python_version="3.14.0",
        cache_tag="cpython-314",
        startup_sys_path_roles=("python_home", "runtime_site"),
        base_sys_path_roles=("python_home",),
        import_roots=import_roots,
        distributions=(),
        entry_count=2,
        byte_count=11,
        canonical_sha256="0" * 64,
    ))
    shell = command_plan.ShellIdentity(
        path=str(shell_path),
        sha256="3" * 64,
        file_version="7.6.4.500",
        product_version="7.6.4",
        edition="Core",
        parser_version="7.6.4",
    )
    case_root = tmp_path / "case"
    executable_identities = (
        ("codex", codex.executable_path, codex.executable_sha256),
        ("pwsh", shell.path, shell.sha256),
        ("powershell_decoder", str(decoder_path), "4" * 64),
        ("python", guarded_python.python_path, guarded_python.python_sha256),
        ("rg", str(rg_path), "5" * 64),
        ("comspec", str(comspec_path), "7" * 64),
    )
    launcher_environment, shell_environment = preflight._launch_expected_environments(
        case_root=str(case_root),
        executable_identities=executable_identities,
    )
    environment_sha256 = sha256(
        _canonical(
            {
                "launcher_environment": [list(item) for item in launcher_environment],
                "shell_environment": [list(item) for item in shell_environment],
                "version": "complete-suite-client-environment-manifest-v1",
            }
        )
    ).hexdigest()
    frozen_meta_root = tmp_path / "frozen-meta"
    evaluation_records = _evaluation_records(
        tmp_path / "evaluation-envelopes"
    )
    file_change = _validate(_inputs(tmp_path / "file-change"))
    launch_preflight = preflight.LaunchPreflight(
        codex=codex,
        native_leaves=native_leaves,
        guarded_python=guarded_python,
        shell=shell,
        decoder_path=str(decoder_path),
        decoder_sha256="4" * 64,
        rg_path=str(rg_path),
        rg_sha256="5" * 64,
        python_path=guarded_python.python_path,
        python_sha256=guarded_python.python_sha256,
        python_version=guarded_python.python_version,
        comspec_path=str(comspec_path),
        comspec_sha256="7" * 64,
        launcher_environment=launcher_environment,
        shell_environment=shell_environment,
        environment_sha256=environment_sha256,
        exact_config_sha256="9" * 64,
        normalized_config_sha256="a" * 64,
        loopback_launch_sha256="b" * 64,
        real_launch_template_sha256="c" * 64,
        frozen_meta_root=str(frozen_meta_root),
        frozen_meta_manifest_sha256="d" * 64,
        loopback_contract_sha256="e" * 64,
        loopback_transcript_manifest_sha256="f" * 64,
        rendered_event_utf8_bytes=1,
        rendered_event_sha256="0" * 64,
        advertised_tools_sha256=file_change.advertised_tools_sha256,
        evaluation_records=evaluation_records,
        evaluation_manifest_sha256=_evaluation_manifest_sha256(
            evaluation_records
        ),
        loopback_expected_shell_calls=2,
        loopback_expected_file_adds=1,
        loopback_expected_file_updates=1,
        file_change=file_change,
    )
    object.__setattr__(
        launch_preflight,
        "_launch_durable_authority",
        _synthetic_durable_authority(case_root),
    )
    return _install_synthetic_validated_launch_authority(launch_preflight)


def _workspace_snapshot(*, root_inode: int = 360, file_inode: int = 361):
    module = _preflight()
    root_identity = _identity(root_inode)
    ancestor_identities = (_identity(root_inode - 1),)
    entry = module.FilesystemSnapshotEntry(
        relative_path="case.json",
        kind="file",
        size=3,
        sha256=sha256(b"{}\n").hexdigest(),
        link_count=1,
        identity=_identity(file_inode),
    )
    payload = {
        "ancestor_identities": [
            _identity_record(identity) for identity in ancestor_identities
        ],
        "entries": [
            {
                "identity": _identity_record(entry.identity),
                "kind": entry.kind,
                "link_count": entry.link_count,
                "relative_path": entry.relative_path,
                "sha256": entry.sha256,
                "size": entry.size,
            }
        ],
        "present": True,
        "relative_root": "workspace",
        "root_identity": _identity_record(root_identity),
        "root_index": 0,
    }
    return module.FilesystemRootSnapshot(
        root_index=0,
        relative_root="workspace",
        present=True,
        root_identity=root_identity,
        ancestor_identities=ancestor_identities,
        entries=(entry,),
        manifest_sha256=sha256(_canonical(payload)).hexdigest(),
    )


def _synthetic_durable_authority(root: Path, *, suffix: bytes = b"\n"):
    module = _preflight()
    schema_bytes = Path(__file__).with_name(
        "complete-suite-output.schema.json"
    ).read_bytes()
    workspace = _workspace_snapshot()
    prompts = (
        _capture(
            root / "raw" / "prompts" / "shell.md",
            f"shell\ncase-root={root / 'workspace'}".encode("utf-8"),
            inode=370,
        ),
        _capture(
            root / "raw" / "prompts" / "file-add.md",
            f"file_add\ncase-root={root / 'file-change-audit'}".encode("utf-8"),
            inode=371,
        ),
        _capture(
            root / "raw" / "prompts" / "file-update.md",
            f"file_update\ncase-root={root / 'file-change-audit'}".encode("utf-8"),
            inode=372,
        ),
    )
    schema = _capture(
        root / "raw" / "output.schema.json",
        schema_bytes,
        inode=373,
    )
    final_payload = b"campaign6-loopback-complete" + suffix
    finals = tuple(
        _capture(path, final_payload, inode=374 + ordinal)
        for ordinal, path in enumerate(
            (
                root / "raw" / "final" / "shell-01.md",
                root / "raw" / "final" / "shell-02.md",
                root / "raw" / "final" / "file-add.md",
                root / "raw" / "final" / "file-update.md",
            )
        )
    )
    workspace_manifest = _capture(
        root / "filesystem-snapshots" / "workspace.json",
        _canonical(module._snapshot_record(workspace)),
        inode=380,
    )
    return module._launch_make_durable_authority(
        bundle_root=root,
        prompts=prompts,
        output_schema=schema,
        workspace_snapshot=workspace,
        workspace_snapshot_manifest=workspace_manifest,
        final_message_paths=tuple(record.path for record in finals),
        final_paths_were_absent=(True, True, True, True),
        final_messages=finals,
        final_serialization_suffix=suffix,
    )


