        source_relative_path=_NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_RELATIVE_PATH,
        source_policy_bytes=_NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_BYTES,
