_HOST_NATIVE_VECTOR_SOURCE_BYTES = rb"""function Assert-C6HostNativeVectorString {
    param(
        [Parameter(Mandatory)]
        [AllowNull()]
        [AllowEmptyString()]
        [object]$Value
    )
    if ($null -eq $Value) { throw 'host native vector contains null string' }
    if ($Value -isnot [string]) {
        throw 'host native vector value is not a string'
    }
    [string]$text=$Value
    for ($index=0; $index -lt $text.Length; $index++) {
        $character=$text[$index]
        if ($character -eq [char]0) { throw 'host native vector contains NUL' }
        if ([char]::IsHighSurrogate($character)) {
            if ($index + 1 -ge $text.Length -or
                -not [char]::IsLowSurrogate($text[$index + 1])) {
                throw 'host native vector contains unpaired high surrogate'
            }
            $index++
        } elseif ([char]::IsLowSurrogate($character)) {
            throw 'host native vector contains unpaired low surrogate'
        }
    }
}

function ConvertTo-C6HostNativeArgument {
    param(
        [Parameter(Mandatory)]
        [AllowNull()]
        [AllowEmptyString()]
        [object]$Value
    )
    Assert-C6HostNativeVectorString -Value $Value
    [string]$text=$Value
    $requiresQuotes=($text.Length -eq 0)
    if (-not $requiresQuotes) {
        foreach ($character in $text.ToCharArray()) {
            if ($character -eq '"' -or $character -eq ' ' -or
                $character -eq [char]9) {
                $requiresQuotes=$true
                break
            }
        }
    }
    if (-not $requiresQuotes) { return $text }
    $builder=[Text.StringBuilder]::new()
    [void]$builder.Append('"')
    $backslashes=0
    foreach ($character in $text.ToCharArray()) {
        if ($character -eq '\') {
            $backslashes++
            continue
        }
        if ($character -eq '"') {
            if ($backslashes -gt 0) {
                [void]$builder.Append(('\' * (2 * $backslashes)))
            }
            [void]$builder.Append('\')
            [void]$builder.Append('"')
            $backslashes=0
            continue
        }
        if ($backslashes -gt 0) {
            [void]$builder.Append(('\' * $backslashes))
            $backslashes=0
        }
        [void]$builder.Append($character)
    }
    if ($backslashes -gt 0) {
        [void]$builder.Append(('\' * (2 * $backslashes)))
    }
    [void]$builder.Append('"')
    return $builder.ToString()
}

function New-C6HostNativeVector {
    param(
        [Parameter(Mandatory)][AllowNull()][object]$Executable,
        [Parameter(Mandatory)]
        [AllowNull()]
        [AllowEmptyCollection()]
        [object]$ArgumentList
    )
    Assert-C6HostNativeVectorString -Value $Executable
    [string]$executableText=$Executable
    if ($executableText.Length -eq 0 -or
        -not [IO.Path]::IsPathFullyQualified($executableText) -or
        [IO.Path]::GetFullPath($executableText) -cne $executableText) {
        throw 'host native vector executable is not canonical absolute'
    }
    if ($null -eq $ArgumentList -or $ArgumentList -isnot [object[]]) {
        throw 'host native vector argument list is not an array'
    }
    $serialized=[Collections.Generic.List[string]]::new()
    [void]$serialized.Add(
        (ConvertTo-C6HostNativeArgument -Value $executableText)
    )
    foreach ($argument in [object[]]$ArgumentList) {
        [void]$serialized.Add(
            (ConvertTo-C6HostNativeArgument -Value $argument)
        )
    }
    $commandLine=[string]::Join(' ',$serialized)
    [long]$unitCount=[long]$commandLine.Length + 1
    if ($unitCount -lt 1 -or $unitCount -gt 30000) {
        throw 'host native vector exceeds 30000 UTF-16 units'
    }
    $serializedBytes=[Text.Encoding]::Unicode.GetBytes(
        $commandLine + [char]0
    )
    $digest=[Convert]::ToHexString(
        [Security.Cryptography.SHA256]::HashData($serializedBytes)
    ).ToLowerInvariant()
    return [pscustomobject]@{
        contract='complete-suite-windows-native-vector-v1'
        utf16_units=[int]$unitCount
        utf16le_sha256=$digest
        command_line=$commandLine
    }
}
"""


_NATIVE_LEAF_SYNTHETIC_HOST_CONSTRUCTOR_BODY = (
    b"function Invoke-C6SyntheticHostNativeCore {\n"
    b"    param([string]$ApplicationName,[string[]]$ArgumentList)\n"
    b"    $startupInfo = [ordered]@{ HandleList=@(); JobList=@() }\n"
    b"    $descriptor = [ordered]@{ Image=$ApplicationName; Argv=$ArgumentList }\n"
    b"    return [pscustomobject]@{ Startup=$startupInfo; Descriptor=$descriptor }\n"
    b"}\n"
)
_NATIVE_LEAF_SYNTHETIC_BROKER_CONSTRUCTOR_BODY = (
    b"def _c6_synthetic_broker_native_core(application_name, argv):\n"
    b"    startup = {\"handle_list\": (), \"job_list\": ()}\n"
    b"    descriptor = {\"image\": application_name, \"argv\": tuple(argv)}\n"
    b"    if not application_name or not descriptor[\"argv\"]:\n"
    b"        raise ValueError(\"closed synthetic descriptor required\")\n"
    b"    return startup, descriptor\n"
)


def _native_leaf_construction_registry_block(
    *,
    begin: bytes,
    end: bytes,
    variable: bytes,
    payload: bytes,
) -> bytes:
    return b"\n".join(
        (begin, b"$script:" + variable + b"=@'", payload, b"'@", end, b"")
    )


def _native_leaf_construction_source_fixture(
    tmp_path: Path,
    *,
    host_body: bytes = _NATIVE_LEAF_SYNTHETIC_HOST_CONSTRUCTOR_BODY,
    broker_body: bytes = _NATIVE_LEAF_SYNTHETIC_BROKER_CONSTRUCTOR_BODY,
) -> dict[str, object]:
    source_root = tmp_path / "source-root"
    skills_root = source_root / "tests" / "skills"
    skills_root.mkdir(parents=True)
    control_path = skills_root / "complete_suite_control_plane.ps1"
    broker_path = skills_root / "complete_suite_release_python_bootstrap.py"
    implementation_template, attribute_bytes, topology_bytes = (
        _expected_native_leaf_authority_registry_bytes()
    )
    post_trust_selection_bytes = (
        _expected_post_trust_selection_registry_bytes()
    )
    host_sha256 = sha256(host_body).hexdigest().encode("ascii")
    broker_sha256 = sha256(broker_body).hexdigest().encode("ascii")
    implementation_bytes = implementation_template.replace(
        b"a" * 64,
        host_sha256,
        1,
    ).replace(
        b"b" * 64,
        broker_sha256,
        1,
    )
    host_fragment = (
        b"# C6-HOST-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN\n"
        + host_body
        + b"# C6-HOST-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END\n"
    )
    broker_fragment = (
        b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN\n"
        + broker_body
        + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END\n"
    )
    implementation_block = _native_leaf_construction_registry_block(
        begin=b"# C6-CONSTRUCTOR-IMPLEMENTATION-SET-BEGIN",
        end=b"# C6-CONSTRUCTOR-IMPLEMENTATION-SET-END",
        variable=b"C6ConstructorImplementationSetJson",
        payload=implementation_bytes,
    )
    post_trust_selection_block = _native_leaf_construction_registry_block(
        begin=b"# C6-POST-TRUST-SELECTION-REGISTRY-BEGIN",
        end=b"# C6-POST-TRUST-SELECTION-REGISTRY-END",
        variable=b"C6PostTrustSelectionRegistryJson",
        payload=post_trust_selection_bytes,
    )
    attribute_block = _native_leaf_construction_registry_block(
        begin=b"# C6-CONSTRUCTOR-ATTRIBUTE-SET-BEGIN",
        end=b"# C6-CONSTRUCTOR-ATTRIBUTE-SET-END",
        variable=b"C6ConstructorAttributeSetJson",
        payload=attribute_bytes,
    )
    topology_block = _native_leaf_construction_registry_block(
        begin=b"# C6-JOB-TOPOLOGY-BEGIN",
        end=b"# C6-JOB-TOPOLOGY-END",
        variable=b"C6JobTopologyJson",
        payload=topology_bytes,
    )
    control_bytes = (
        b"Set-StrictMode -Version Latest\n"
        + post_trust_selection_block
        + implementation_block
        + attribute_block
        + topology_block
        + host_fragment
    )
    broker_bytes = b"from __future__ import annotations\n" + broker_fragment
    control_path.write_bytes(control_bytes)
    broker_path.write_bytes(broker_bytes)
    return {
        "source_root": source_root,
        "control_path": control_path,
        "broker_path": broker_path,
        "control_bytes": control_bytes,
        "broker_bytes": broker_bytes,
        "control_capture": _actual_capture(control_path),
        "broker_capture": _actual_capture(broker_path),
        "host_body": host_body,
        "broker_body": broker_body,
        "post_trust_selection_bytes": post_trust_selection_bytes,
        "post_trust_selection_block": post_trust_selection_block,
        "registry_bytes": (
            implementation_bytes,
            attribute_bytes,
            topology_bytes,
        ),
        "registry_blocks": (
            implementation_block,
            attribute_block,
            topology_block,
        ),
    }


