def _guard_native_leaf_side_effects(
    monkeypatch: pytest.MonkeyPatch,
) -> list[str]:
    calls: list[str] = []

    def forbidden(*_args: object, **_kwargs: object) -> object:
        calls.append("forbidden")
        pytest.fail("native leaf capture reached a process, network, or output surface")

    monkeypatch.setattr(subprocess, "Popen", forbidden)
    monkeypatch.setattr(subprocess, "run", forbidden)
    monkeypatch.setattr(socket, "socket", forbidden)
    monkeypatch.setattr(socket, "create_connection", forbidden)
    monkeypatch.setattr(os, "system", forbidden)
    monkeypatch.setattr(Path, "write_bytes", forbidden)
    monkeypatch.setattr(Path, "write_text", forbidden)
    return calls


def _filesystem_launch_bundle(root: Path, launch_preflight: object) -> object:
    module = _preflight()
    root.mkdir()
    (root / "bundle-marker.txt").write_bytes(b"frozen launch bundle\n")
    values = {
        "version": "complete-suite-launch-preflight-bundle-v1",
        "root": str(root),
        "root_identity": module._validator_plain_directory_identity(root),
        "preflight": launch_preflight,
        "entries": module._validator_capture_entries(
            root,
            max_entries=32_768,
            max_bytes=2 * 1024 * 1024 * 1024,
        ),
    }
    prototype = _unchecked_frozen(
        module.FrozenLaunchPreflightBundle,
        **values,
        manifest_sha256="0" * 64,
    )
    return module.FrozenLaunchPreflightBundle(
        **values,
        manifest_sha256=sha256(
            _canonical(module._launch_bundle_manifest_payload(prototype))
        ).hexdigest(),
    )


def _launch_membership_preflight(root: Path) -> object:
    module = _preflight()
    supplied = _launch_preflight(root)
    guarded = supplied.guarded_python
    runtime_site = guarded.import_roots[-1]
    direct_entries = tuple(
        sorted(
            (
                module.FrozenImportEntry(
                    relative_path="complete_suite_release_python_bootstrap.py",
                    kind="file",
                    byte_count=guarded.bootstrap.utf8_bytes,
                    sha256=guarded.bootstrap.sha256,
                    identity=guarded.bootstrap.identity,
                ),
                module.FrozenImportEntry(
                    relative_path="pyproject.toml",
                    kind="file",
                    byte_count=guarded.project_metadata.utf8_bytes,
                    sha256=guarded.project_metadata.sha256,
                    identity=guarded.project_metadata.identity,
                ),
                module.FrozenImportEntry(
                    relative_path="python.exe",
                    kind="file",
                    byte_count=guarded.python_size,
                    sha256=guarded.python_sha256,
                    identity=guarded.python_identity,
                ),
                module.FrozenImportEntry(
                    relative_path="runtime-site",
                    kind="directory",
                    byte_count=0,
                    sha256=None,
                    identity=runtime_site.identity,
                ),
            ),
            key=lambda item: (item.relative_path.casefold(), item.relative_path),
        )
    )
    python_home = module._guarded_make_import_root(
        role="python_home",
        path=guarded.root,
        identity=guarded.root_identity,
        entries=direct_entries,
    )
    runtime_entry_count = len(direct_entries) + len(runtime_site.entries)
    runtime_byte_count = sum(
        item.byte_count for item in (*direct_entries, *runtime_site.entries)
        if item.kind == "file"
    )
    guarded = _unchecked_replace(
        guarded,
        import_roots=(python_home, runtime_site),
        entry_count=runtime_entry_count,
        byte_count=runtime_byte_count,
    )
    layout = module._launch_bundle_layout(root)
    advertised_tools_sha256 = sha256(
        module._launch_advertised_tools_bytes()
    ).hexdigest()
    real_config, _transport, _credential = module._launch_configuration(
        mode="real",
        loopback_port=None,
        shell_environment=supplied.shell_environment,
    )
    normalized_config_sha256 = sha256(
        module._launch_normalized_config_bytes(
            case_root=str(root),
            loopback_port=None,
            config_overrides=real_config,
        )
    ).hexdigest()
    file_change = _unchecked_replace(
        supplied.file_change,
        audit_root=str(layout["file_change_audit_root"]),
        add_capture_path=str(layout["file_add_capture"]),
        update_capture_path=str(layout["file_update_capture"]),
        advertised_tools_sha256=advertised_tools_sha256,
    )
    return _unchecked_replace(
        supplied,
        guarded_python=guarded,
        file_change=file_change,
        advertised_tools_sha256=advertised_tools_sha256,
        loopback_contract_sha256=sha256(
            module._launch_loopback_contract_bytes()
        ).hexdigest(),
        normalized_config_sha256=normalized_config_sha256,
        evaluation_manifest_sha256=_evaluation_manifest_sha256(
            supplied.evaluation_records
        ),
    )


def _launch_membership_entries(
    specs: tuple[object, ...],
) -> tuple[object, ...]:
    module = _preflight()
    entries: list[object] = []
    for ordinal, spec in enumerate(specs, start=10_000):
        identity = spec.identity or _identity(ordinal)
        size = 0 if spec.kind == "directory" else (
            spec.size if spec.size is not None else 1
        )
        digest = None if spec.kind == "directory" else (
            spec.sha256
            if spec.sha256 is not None
            else sha256(spec.relative_path.encode("utf-8")).hexdigest()
        )
        entries.append(
            module.FilesystemSnapshotEntry(
                relative_path=spec.relative_path,
                kind=spec.kind,
                size=size,
                sha256=digest,
                link_count=identity.link_count,
                identity=identity,
            )
        )
    return tuple(entries)


