    assert captured.output_schema_source.path == str(source_schema)
    assert captured.output_schema_source.content == payload
    assert captured.output_schema_source.utf8_bytes == PINNED_OUTPUT_SCHEMA_SIZE
    assert captured.output_schema_source.sha256 == PINNED_OUTPUT_SCHEMA_SHA256


