@pytest.mark.parametrize(
    ("ordinal", "prompt_index"),
    ((1, 0), (2, 0), (3, 1), (4, 2)),
)
def test_durable_local_launch_accepts_exact_role_prompt_and_schema_semantics(
    tmp_path: Path,
    ordinal: int,
    prompt_index: int,
) -> None:
    module = _preflight()
    case_root, _prompt, _schema, value = _launch_inputs(tmp_path)
    authority = value._validated_launch_authority
    prompt = authority.prelaunch_authority.prompts[prompt_index]
    schema = authority.prelaunch_authority.output_schema
    evaluation = _client_evaluation(mode="loopback_probe", ordinal=ordinal)

    spec = module.build_client_launch_spec(
        mode="loopback_probe",
        preflight=value,
        case_root=case_root,
        evaluation=evaluation,
        output_schema=schema,
        prompt=prompt,
        loopback_port=43123,
    )
    assert spec.prompt is prompt
    assert spec.output_schema is schema

    reconstructed_prompt = _unchecked_replace(prompt)
    reconstructed_schema = _unchecked_replace(schema)
    reconstructed = module.build_client_launch_spec(
        mode="loopback_probe",
        preflight=value,
        case_root=case_root,
        evaluation=evaluation,
        output_schema=reconstructed_schema,
        prompt=reconstructed_prompt,
        loopback_port=43123,
    )
    assert reconstructed.prompt is reconstructed_prompt
    assert reconstructed.output_schema is reconstructed_schema

    wrong_prompt = authority.prelaunch_authority.prompts[(prompt_index + 1) % 3]
    for forged_prompt, forged_schema in (
        (wrong_prompt, schema),
        (
            _unchecked_replace(
                prompt,
                path=str(case_root / "raw" / "prompts" / "forged.md"),
            ),
            schema,
        ),
        (
            prompt,
            _unchecked_replace(schema, identity=_identity(899)),
        ),
    ):
        with pytest.raises(RuntimeError, match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$"):
            module.build_client_launch_spec(
                mode="loopback_probe",
                preflight=value,
                case_root=case_root,
                evaluation=evaluation,
                output_schema=forged_schema,
                prompt=forged_prompt,
                loopback_port=43123,
            )


def test_durable_local_construction_authority_binds_selected_aggregate_member(
    tmp_path: Path,
) -> None:
    module = _preflight()
    case_root, _prompt, _schema, value = _launch_inputs(tmp_path)
    preflight_authority = value._validated_launch_authority
    selections = (
        ("shell_renderer", 1, 0),
        ("shell_renderer", 2, 0),
        ("file_add", 3, 1),
        ("file_update", 4, 2),
    )
    authorities: list[object] = []
    for role, ordinal, prompt_index in selections:
        spec = module.build_client_launch_spec(
            mode="loopback_probe",
            preflight=value,
            case_root=case_root,
            evaluation=_client_evaluation(
                mode="loopback_probe",
                ordinal=ordinal,
            ),
            output_schema=preflight_authority.prelaunch_authority.output_schema,
            prompt=preflight_authority.prelaunch_authority.prompts[prompt_index],
            loopback_port=43123,
        )
        construction = getattr(spec, "_launch_construction_authority")
        authorities.append(construction)
        assert construction.launch_member_key == (role, ordinal)
        assert sha256(construction.retained_launch_contract_bytes).hexdigest() == (
            preflight_authority.loopback_launch_sha256
        )
        assert construction.launch_contract_sha256 == (
            module._launch_loopback_aggregate_member_sha256(
                construction.retained_launch_contract_bytes,
                probe_role=role,
                probe_ordinal=ordinal,
                expected_base_mode_contract_bytes=(
                    construction.expected_base_mode_contract_bytes
                ),
            )
        )

    assert len(
        {authority.launch_contract_sha256 for authority in authorities}
    ) == 4
    wrong_member = _unchecked_replace(
        authorities[0],
        launch_member_key=("shell_renderer", 2),
    )
    with pytest.raises(RuntimeError, match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$"):
        wrong_member.__post_init__()


def test_durable_local_rejection_precedes_process_socket_and_network_callbacks(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    case_root, _prompt, _schema, value = _launch_inputs(tmp_path)
    authority = value._validated_launch_authority
    calls: list[str] = []

    def forbidden(*_args: object, **_kwargs: object) -> object:
        calls.append("forbidden")
        pytest.fail("durable local rejection reached a runtime callback")

    monkeypatch.setattr(subprocess, "Popen", forbidden)
    monkeypatch.setattr(subprocess, "run", forbidden)
    monkeypatch.setattr(socket, "socket", forbidden)
    with pytest.raises(RuntimeError, match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$"):
        module.build_client_launch_spec(
            mode="loopback_probe",
            preflight=value,
            case_root=case_root,
            evaluation=_client_evaluation(mode="loopback_probe", ordinal=3),
            output_schema=authority.prelaunch_authority.output_schema,
            prompt=authority.prelaunch_authority.prompts[0],
            loopback_port=43123,
        )
    assert calls == []


