@pytest.mark.parametrize("suffix", (b"", b"\n"))
def test_durable_offline_recapture_crossbinds_finals_and_detaches_recursively(
    tmp_path: Path,
    suffix: bytes,
) -> None:
    module = _preflight()
    supplied, root, _layout = _filesystem_durable_authority_fixture(
        tmp_path,
        suffix=suffix,
    )
    original = supplied._launch_durable_authority

    detached = module._launch_recapture_durable_authority(supplied, root)

    assert detached == original
    assert detached is not original
    assert detached.prelaunch is not original.prelaunch
    assert detached.prelaunch.prompts is not original.prelaunch.prompts
    assert all(
        actual is not expected
        for actual, expected in zip(
            detached.prelaunch.prompts,
            original.prelaunch.prompts,
            strict=True,
        )
    )
    assert detached.prelaunch.workspace_snapshot is not (
        original.prelaunch.workspace_snapshot
    )
    assert detached.final_messages is not original.final_messages


@pytest.mark.parametrize(
    "mutation",
    (
        "prompt",
        "schema",
        "workspace",
        "workspace-manifest",
        "final",
        "final-suffix",
        "jsonl-final",
        "extra-jsonl-final",
        "extra-final",
        "missing-final",
        "swapped-final-identities",
        "hardlinked-finals",
    ),
)
def test_durable_offline_recapture_rejects_every_input_output_drift(
    tmp_path: Path,
    mutation: str,
) -> None:
    module = _preflight()
    supplied, root, layout = _filesystem_durable_authority_fixture(tmp_path)
    if mutation == "prompt":
        layout["prompt_shell"].write_bytes(layout["prompt_shell"].read_bytes() + b" ")
    elif mutation == "schema":
        layout["output_schema"].write_bytes(layout["output_schema"].read_bytes() + b" ")
    elif mutation == "workspace":
        (layout["workspace_root"] / "extra.txt").write_bytes(b"extra\n")
    elif mutation == "workspace-manifest":
        layout["workspace_snapshot"].write_bytes(
            layout["workspace_snapshot"].read_bytes() + b"\n"
        )
    elif mutation == "final":
        layout["final_message_shell_01"].write_bytes(b"wrong\n")
    elif mutation == "final-suffix":
        layout["final_message_shell_01"].write_bytes(
            b"campaign6-loopback-complete"
        )
    elif mutation == "jsonl-final":
        layout["shell_capture_01"].write_bytes(
            layout["shell_capture_01"].read_bytes().replace(
                b"campaign6-loopback-complete",
                b"wrong-final-text",
            )
        )
    elif mutation == "extra-jsonl-final":
        layout["shell_capture_01"].write_bytes(
            layout["shell_capture_01"].read_bytes()
            + _canonical(
                {
                    "type": "item.completed",
                    "item": {
                        "id": "extra-final-message",
                        "type": "agent_message",
                        "text": "campaign6-loopback-complete",
                    },
                }
            )
            + b"\n"
        )
    elif mutation == "extra-final":
        (layout["final_message_shell_01"].parent / "extra.md").write_bytes(
            b"campaign6-loopback-complete\n"
        )
    elif mutation == "missing-final":
        layout["final_message_shell_01"].unlink()
    elif mutation == "swapped-final-identities":
        first = layout["final_message_shell_01"]
        second = layout["final_message_shell_02"]
        temporary = root / "raw" / "final" / "temporary.md"
        first.rename(temporary)
        second.rename(first)
        temporary.rename(second)
    else:
        second = layout["final_message_shell_02"]
        second.unlink()
        os.link(layout["final_message_shell_01"], second)

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_recapture_durable_authority(supplied, root)


