def test_launch_expected_bundle_membership_covers_each_owned_namespace(
    tmp_path: Path,
) -> None:
    module = _preflight()
    root = tmp_path / "launch-bundle"
    supplied = _launch_membership_preflight(root)

    expected = module._launch_expected_bundle_membership(supplied, root)

    assert type(expected) is tuple
    assert all(
        type(item) is module._LaunchExpectedBundleMember for item in expected
    )
    assert tuple(item.relative_path for item in expected) == tuple(
        sorted(
            (item.relative_path for item in expected),
            key=lambda item: (item.casefold(), item),
        )
    )
    by_path = {item.relative_path: item for item in expected}
    assert set(by_path) >= {
        "client-captures",
        "client-captures/file-add.jsonl",
        "client-captures/file-update.jsonl",
        "client-captures/shell-01.jsonl",
        "client-captures/shell-02.jsonl",
        "contracts",
        "contracts/advertised-tools.json",
        "contracts/exact-config.toml",
        "contracts/loopback-contract.json",
        "contracts/loopback-launch.json",
        "contracts/normalized-config.json",
        "contracts/real-launch-template.json",
        "contracts/rendered-event.jsonl",
        "evaluation-envelopes",
        "evaluation-envelopes/manifest.json",
        "file-change-audit",
        f"file-change-audit/{AUDIT_FILENAME}",
        "filesystem-snapshots",
        "filesystem-snapshots/after-add.json",
        "filesystem-snapshots/after-update.json",
        "filesystem-snapshots/before.json",
        "frozen-meta",
        "guarded-python-runtime",
        "guarded-python-runtime/complete_suite_release_python_bootstrap.py",
        "guarded-python-runtime/pyproject.toml",
        "guarded-python-runtime/python.exe",
        "guarded-python-runtime/runtime-site",
        "guarded-python-runtime/runtime-site/placeholder.py",
        "loopback-transcripts",
        "loopback-transcripts/file-add.bin",
        "loopback-transcripts/file-update.bin",
        "loopback-transcripts/manifest.json",
        "loopback-transcripts/shell-01.bin",
        "loopback-transcripts/shell-02.bin",
    }
    evaluation_paths = tuple(
        path
        for path in by_path
        if path.startswith("evaluation-envelopes/")
        and path != "evaluation-envelopes/manifest.json"
    )
    assert evaluation_paths == (
        *(f"evaluation-envelopes/loopback-{ordinal:02d}.json" for ordinal in range(1, 5)),
        *(f"evaluation-envelopes/template-{ordinal:02d}.json" for ordinal in range(1, 25)),
    )

    guarded_python = by_path["guarded-python-runtime/python.exe"]
    assert (
        guarded_python.kind,
        guarded_python.size,
        guarded_python.sha256,
        guarded_python.identity,
    ) == (
        "file",
        supplied.guarded_python.python_size,
        supplied.guarded_python.python_sha256,
        supplied.guarded_python.python_identity,
    )
    audit_root = by_path["file-change-audit"]
    audit_file = by_path[f"file-change-audit/{AUDIT_FILENAME}"]
    final_audit_entry = supplied.file_change.after_update_snapshot.entries[0]
    assert audit_root.identity == (
        supplied.file_change.after_update_snapshot.root_identity
    )
    assert (
        audit_file.kind,
        audit_file.size,
        audit_file.sha256,
        audit_file.identity,
    ) == (
        final_audit_entry.kind,
        final_audit_entry.size,
        final_audit_entry.sha256,
        final_audit_entry.identity,
    )
    assert by_path["client-captures/file-add.jsonl"].identity == (
        supplied.file_change.add_capture_identity
    )
    assert by_path["loopback-transcripts/manifest.json"].sha256 == (
        supplied.loopback_transcript_manifest_sha256
    )
    for relative_path, snapshot in (
        ("filesystem-snapshots/before.json", supplied.file_change.before_snapshot),
        (
            "filesystem-snapshots/after-add.json",
            supplied.file_change.after_add_snapshot,
        ),
        (
            "filesystem-snapshots/after-update.json",
            supplied.file_change.after_update_snapshot,
        ),
    ):
        canonical_snapshot = module._canonical_json_bytes(
            module._snapshot_record(snapshot)
        )
        assert (
            by_path[relative_path].size,
            by_path[relative_path].sha256,
        ) == (
            len(canonical_snapshot),
            sha256(canonical_snapshot).hexdigest(),
        )

    deterministic_artifacts = {
        "contracts/advertised-tools.json": (
            module._launch_advertised_tools_bytes()
        ),
        "contracts/loopback-contract.json": (
            module._launch_loopback_contract_bytes()
        ),
        "evaluation-envelopes/manifest.json": (
            _evaluation_manifest_bytes(supplied.evaluation_records)
        ),
    }
    real_config, _transport, _credential = module._launch_configuration(
        mode="real",
        loopback_port=None,
        shell_environment=supplied.shell_environment,
    )
    deterministic_artifacts["contracts/normalized-config.json"] = (
        module._launch_normalized_config_bytes(
            case_root=str(root),
            loopback_port=None,
            config_overrides=real_config,
        )
    )
    for relative_path, canonical_bytes in deterministic_artifacts.items():
        assert (
            by_path[relative_path].size,
            by_path[relative_path].sha256,
        ) == (
            len(canonical_bytes),
            sha256(canonical_bytes).hexdigest(),
        )

    module._launch_validate_bundle_membership(
        supplied,
        root,
        _launch_membership_entries(expected),
    )


@pytest.mark.parametrize(
    "artifact",
    (
        "advertised-tools",
        "loopback-contract",
        "evaluation-manifest",
        "normalized-config",
    ),
)
def test_launch_expected_bundle_membership_rejects_resealed_metadata(
    tmp_path: Path,
    artifact: str,
) -> None:
    module = _preflight()
    root = tmp_path / "launch-bundle"
    supplied = _launch_membership_preflight(root)
    correct_digest = {
        "advertised-tools": supplied.advertised_tools_sha256,
        "loopback-contract": supplied.loopback_contract_sha256,
        "evaluation-manifest": supplied.evaluation_manifest_sha256,
        "normalized-config": supplied.normalized_config_sha256,
    }[artifact]
    wrong_digest = (
        ("0" if correct_digest[0] != "0" else "1") + correct_digest[1:]
    )
    if artifact == "advertised-tools":
        file_change = _unchecked_replace(
            supplied.file_change,
            advertised_tools_sha256=wrong_digest,
        )
        supplied = _unchecked_replace(
            supplied,
            advertised_tools_sha256=wrong_digest,
            file_change=file_change,
        )
    elif artifact == "loopback-contract":
        supplied = _unchecked_replace(
            supplied,
            loopback_contract_sha256=wrong_digest,
        )
    elif artifact == "evaluation-manifest":
        supplied = _unchecked_replace(
            supplied,
            evaluation_manifest_sha256=wrong_digest,
        )
    else:
        supplied = _unchecked_replace(
            supplied,
            normalized_config_sha256=wrong_digest,
        )

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ) as error:
        module._launch_expected_bundle_membership(supplied, root)
    assert error.value.__cause__ is None


@pytest.mark.parametrize(
    "mutation",
    (
        "extra",
        "missing",
        "wrong-kind",
        "wrong-digest",
        "wrong-snapshot-digest",
        "wrong-identity",
        "duplicate-identity",
        "reordered",
    ),
)
def test_launch_validate_bundle_membership_rejects_each_inventory_mutation(
    tmp_path: Path,
    mutation: str,
) -> None:
    module = _preflight()
    root = tmp_path / "launch-bundle"
    supplied = _launch_membership_preflight(root)
    expected = module._launch_expected_bundle_membership(supplied, root)
    entries = list(_launch_membership_entries(expected))

    def entry_index(relative_path: str) -> int:
        return next(
            index
            for index, entry in enumerate(entries)
            if entry.relative_path == relative_path
        )

    if mutation == "extra":
        entries.append(
            module.FilesystemSnapshotEntry(
                relative_path="fabricated-extra.bin",
                kind="file",
                size=1,
                sha256=sha256(b"fabricated-extra.bin").hexdigest(),
                link_count=1,
                identity=_identity(20_001),
            )
        )
        entries.sort(key=lambda item: (item.relative_path.casefold(), item.relative_path))
    elif mutation == "missing":
        entries.pop(entry_index("contracts/advertised-tools.json"))
    elif mutation == "wrong-kind":
        index = entry_index("guarded-python-runtime/python.exe")
        original = entries[index]
        entries[index] = module.FilesystemSnapshotEntry(
            relative_path=original.relative_path,
            kind="directory",
            size=0,
            sha256=None,
            link_count=original.link_count,
            identity=original.identity,
        )
    elif mutation == "wrong-digest":
        index = entry_index("guarded-python-runtime/python.exe")
        original = entries[index]
        entries[index] = module.FilesystemSnapshotEntry(
            relative_path=original.relative_path,
            kind=original.kind,
            size=original.size,
            sha256="8" * 64,
            link_count=original.link_count,
            identity=original.identity,
        )
    elif mutation == "wrong-snapshot-digest":
        index = entry_index("filesystem-snapshots/after-update.json")
        original = entries[index]
        entries[index] = module.FilesystemSnapshotEntry(
            relative_path=original.relative_path,
            kind=original.kind,
            size=original.size,
            sha256="7" * 64,
            link_count=original.link_count,
            identity=original.identity,
        )
    elif mutation == "wrong-identity":
        index = entry_index("guarded-python-runtime/python.exe")
        original = entries[index]
        replacement_identity = _identity(20_002)
        entries[index] = module.FilesystemSnapshotEntry(
            relative_path=original.relative_path,
            kind=original.kind,
            size=original.size,
            sha256=original.sha256,
            link_count=replacement_identity.link_count,
            identity=replacement_identity,
        )
    elif mutation == "duplicate-identity":
        first_index = entry_index("contracts/advertised-tools.json")
        second_index = entry_index("contracts/loopback-contract.json")
        first = entries[first_index]
        second = entries[second_index]
        assert expected[first_index].identity is None
        assert expected[second_index].identity is None
        entries[second_index] = module.FilesystemSnapshotEntry(
            relative_path=second.relative_path,
            kind=second.kind,
            size=second.size,
            sha256=second.sha256,
            link_count=first.identity.link_count,
            identity=first.identity,
        )
    else:
        entries[0], entries[1] = entries[1], entries[0]

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ) as error:
        module._launch_validate_bundle_membership(
            supplied,
            root,
            tuple(entries),
        )
    assert error.value.__cause__ is None


