def test_shell_client_jsonl_binds_payload_tool_item_and_normalizes_only_id(
    tmp_path: Path,
) -> None:
    module = _preflight()
    value = _launch_preflight(tmp_path / "synthetic")
    item_id = "item_c6_00000000000000000000000000000014"
    content = _shell_client_jsonl(
        shell_path=value.shell.path,
        item_id=item_id,
        thread_id="thread-one",
    )
    capture = _capture(tmp_path / "shell-01.jsonl", content, inode=601)

    decoded = module._decode_shell_client_capture(
        capture,
        shell=value.shell,
        expected_tool_item_id=item_id,
    )

    expected = _expected_normalized_shell_events(content, item_id)
    assert decoded.capture is not capture
    assert decoded.tool_item_id == item_id
    assert decoded.started_event_ordinal == 2
    assert decoded.completed_event_ordinal == 3
    assert decoded.extracted.payload == _SHELL_PREFLIGHT_PAYLOAD
    assert decoded.exit_code == 0
    assert decoded.normalized_event_bytes == expected
    assert decoded.normalized_event_sha256 == sha256(expected).hexdigest()
    assert item_id.encode("ascii") not in decoded.normalized_event_bytes
    assert decoded.normalized_event_bytes.count(
        _NORMALIZED_SHELL_ITEM_ID.encode("ascii")
    ) == 2
    assert b'"thread_id":"thread-one"' not in decoded.normalized_event_bytes


def test_shell_client_jsonl_accepts_reordered_keys_and_preserves_non_id_text(
    tmp_path: Path,
) -> None:
    module = _preflight()
    value = _launch_preflight(tmp_path / "synthetic")
    item_id = "item_c6_00000000000000000000000000000014"
    content = _shell_client_jsonl(
        shell_path=value.shell.path,
        item_id=item_id,
        thread_id="thread-one",
        aggregated_output=item_id,
    )
    lines = content.removesuffix(b"\n").split(b"\n")
    for index, status, output, exit_code in (
        (2, "in_progress", "", None),
        (3, "completed", item_id, 0),
    ):
        lines[index] = _ordered_json(
            {
                "item": {
                    "status": status,
                    "exit_code": exit_code,
                    "aggregated_output": output,
                    "command": _shell_rendered_command(value.shell.path),
                    "type": "command_execution",
                    "id": item_id,
                },
                "type": "item.started" if index == 2 else "item.completed",
            }
        )
    content = b"\n".join(lines) + b"\n"

    decoded = module._decode_shell_client_capture(
        _capture(tmp_path / "reordered.jsonl", content, inode=606),
        shell=value.shell,
        expected_tool_item_id=item_id,
    )

    expected = _expected_normalized_shell_events(content, item_id)
    assert decoded.normalized_event_bytes == expected
    assert decoded.normalized_event_bytes.endswith(b"\n")
    assert decoded.normalized_event_bytes.count(item_id.encode("ascii")) == 1
    assert (
        b'"aggregated_output":' + _ordered_json(item_id)
        in decoded.normalized_event_bytes
    )


