@pytest.mark.parametrize(
    ("mutation", "expected_code"),
    (
        ("missing-final-lf", "COMMAND_EVENT_LIFECYCLE_INVALID"),
        ("crlf", "COMMAND_EVENT_LIFECYCLE_INVALID"),
        ("bom", "COMMAND_EVENT_LIFECYCLE_INVALID"),
        ("nul", "COMMAND_EVENT_LIFECYCLE_INVALID"),
        ("empty-line", "COMMAND_EVENT_LIFECYCLE_INVALID"),
        ("capture-size", "COMMAND_EVENT_LIFECYCLE_INVALID"),
        ("event-count", "COMMAND_EVENT_LIFECYCLE_INVALID"),
        ("duplicate-item-id", "COMMAND_EVENT_LIFECYCLE_INVALID"),
        ("wrong-tool-item-id", "COMMAND_EVENT_PAIR_MISMATCH"),
        ("mismatched-lifecycle-ids", "COMMAND_EVENT_PAIR_MISMATCH"),
        ("wrong-payload", "COMMAND_EVENT_PAIR_MISMATCH"),
        ("noninteger-exit", "COMMAND_EVENT_LIFECYCLE_INVALID"),
        ("nonzero-exit", "COMMAND_EVENT_LIFECYCLE_INVALID"),
        ("wrong-status", "COMMAND_EVENT_LIFECYCLE_INVALID"),
        ("stdout-field", "COMMAND_EVENT_LIFECYCLE_INVALID"),
        ("outer-extra", "COMMAND_EVENT_LIFECYCLE_INVALID"),
        ("extra-command", "COMMAND_EVENT_LIFECYCLE_INVALID"),
        ("unknown-state-change", "COMMAND_EVENT_LIFECYCLE_INVALID"),
        ("unknown-completed", "COMMAND_EVENT_LIFECYCLE_INVALID"),
        ("file-change", "COMMAND_EVENT_LIFECYCLE_INVALID"),
    ),
)
def test_shell_client_jsonl_rejects_framing_lifecycle_or_wrapper_mutation(
    tmp_path: Path,
    mutation: str,
    expected_code: str,
) -> None:
    module = _preflight()
    value = _launch_preflight(tmp_path / "synthetic")
    item_id = "item_c6_00000000000000000000000000000014"
    expected_id = item_id
    content = _shell_client_jsonl(
        shell_path=value.shell.path,
        item_id=item_id,
        thread_id="thread-one",
    )
    if mutation == "missing-final-lf":
        content = content[:-1]
    elif mutation == "crlf":
        content = content.replace(b"\n", b"\r\n")
    elif mutation == "bom":
        content = b"\xef\xbb\xbf" + content
    elif mutation == "nul":
        content = content.replace(b'"turn.started"', b'"turn.started"\x00', 1)
    elif mutation == "empty-line":
        content = content.replace(b"\n", b"\n\n", 1)
    elif mutation == "capture-size":
        oversized = (
            b'{"type":"thread.started","opaque":"'
            + b"x" * (4 * 1024 * 1024)
            + b'"}\n'
        )
        content = oversized + content
    elif mutation == "event-count":
        passive = _ordered_json({"type": "thread.started", "metadata": {}})
        content = (passive + b"\n") * 257 + content
    elif mutation == "duplicate-item-id":
        needle = b'"id":' + _ordered_json(item_id)
        content = content.replace(needle, needle + b"," + needle, 1)
    elif mutation == "wrong-tool-item-id":
        expected_id = "item_c6_00000000000000000000000000000015"
    elif mutation == "mismatched-lifecycle-ids":
        completed_id = "item_c6_00000000000000000000000000000015"
        needle = b'"id":' + _ordered_json(item_id)
        content = content.replace(
            needle,
            b'"id":' + _ordered_json(completed_id),
            2,
        )
        content = content.replace(
            b'"id":' + _ordered_json(completed_id),
            needle,
            1,
        )
    elif mutation == "wrong-payload":
        content = content.replace(b"case.json", b"other.json")
    elif mutation == "noninteger-exit":
        content = content.replace(b'"exit_code":0', b'"exit_code":true')
    elif mutation == "nonzero-exit":
        content = content.replace(b'"exit_code":0', b'"exit_code":1')
    elif mutation == "wrong-status":
        content = content.replace(b'"status":"completed"', b'"status":"failed"')
    elif mutation == "stdout-field":
        content = content.replace(
            b'"exit_code":0',
            b'"stdout":"","exit_code":0',
        )
    elif mutation == "outer-extra":
        content = content.replace(
            b'{"type":"item.started","item":',
            b'{"type":"item.started","unexpected":true,"item":',
            1,
        )
    elif mutation == "extra-command":
        lines = content.removesuffix(b"\n").split(b"\n")
        lines.insert(4, lines[2])
        content = b"\n".join(lines) + b"\n"
    elif mutation == "unknown-state-change":
        unknown = _ordered_json(
            {
                "type": "item.started",
                "item": {
                    "id": "unknown-1",
                    "type": "unknown_state_change",
                    "status": "in_progress",
                },
            }
        )
        lines = content.removesuffix(b"\n").split(b"\n")
        lines.insert(2, unknown)
        content = b"\n".join(lines) + b"\n"
    elif mutation == "unknown-completed":
        unknown = _ordered_json(
            {
                "type": "item.completed",
                "item": {
                    "id": "unknown-1",
                    "type": "unknown_state_change",
                    "status": "completed",
                },
            }
        )
        lines = content.removesuffix(b"\n").split(b"\n")
        lines.insert(4, unknown)
        content = b"\n".join(lines) + b"\n"
    elif mutation == "file-change":
        file_change = _ordered_json(
            {
                "type": "item.completed",
                "item": {
                    "id": "file-change-1",
                    "type": "file_change",
                    "status": "completed",
                    "changes": [],
                },
            }
        )
        lines = content.removesuffix(b"\n").split(b"\n")
        lines.insert(4, file_change)
        content = b"\n".join(lines) + b"\n"
    capture = _capture(tmp_path / f"{mutation}.jsonl", content, inode=602)

    with pytest.raises(RuntimeError, match=rf"^{expected_code}$"):
        module._decode_shell_client_capture(
            capture,
            shell=value.shell,
            expected_tool_item_id=expected_id,
        )


