def test_shell_client_jsonl_repeated_projection_ignores_only_bound_item_ids(
    tmp_path: Path,
) -> None:
    module = _preflight()
    value = _launch_preflight(tmp_path / "synthetic")
    item_ids = (
        "item_c6_00000000000000000000000000000014",
        "item_c6_00000000000000000000000000000024",
    )
    first_content = _shell_client_jsonl(
        shell_path=value.shell.path,
        item_id=item_ids[0],
        thread_id="thread-one",
    )
    second_content = _shell_client_jsonl(
        shell_path=value.shell.path,
        item_id=item_ids[1],
        thread_id="thread-two",
    )
    first = _capture(tmp_path / "shell-01.jsonl", first_content, inode=603)
    second = _capture(tmp_path / "shell-02.jsonl", second_content, inode=604)

    decoded = module._validate_repeated_shell_client_captures(
        first,
        second,
        shell=value.shell,
        expected_tool_item_ids=item_ids,
    )

    assert decoded[0].normalized_event_bytes == decoded[1].normalized_event_bytes
    assert decoded[0].capture.path != decoded[1].capture.path
    assert decoded[0].capture.sha256 != decoded[1].capture.sha256
    drifted_content = _shell_client_jsonl(
        shell_path=value.shell.path,
        item_id=item_ids[1],
        thread_id="thread-two",
        aggregated_output="False\n",
    )
    drifted = _capture(tmp_path / "shell-drifted.jsonl", drifted_content, inode=605)
    with pytest.raises(RuntimeError, match=r"^COMMAND_EVENT_PAIR_MISMATCH$"):
        module._validate_repeated_shell_client_captures(
            first,
            drifted,
            shell=value.shell,
            expected_tool_item_ids=item_ids,
        )


