def _offline_shell_transcripts(
    tmp_path: Path,
    *,
    shared_tool_item_id: str | None = None,
) -> tuple[object, object]:
    server = _loopback_server_module()
    return tuple(
        server.decode_loopback_transcript(
            _offline_loopback_transcript_bytes(
                server,
                "shell",
                tmp_path / f"case-{ordinal}",
                port=43122 + ordinal,
                seed=ordinal * 16,
                tool_item_id=shared_tool_item_id,
            )
        )
        for ordinal in (1, 2)
    )


def _shell_client_capture_bundle_fixture(
    tmp_path: Path,
    *,
    shared_tool_item_id: str | None = None,
) -> tuple[object, Path, dict[str, Path], tuple[object, object]]:
    module = _preflight()
    bundle_root = tmp_path / "launch-bundle"
    bundle_root.mkdir()
    layout = module._launch_bundle_layout(bundle_root)
    layout["shell_capture_01"].parent.mkdir()
    layout["rendered_event"].parent.mkdir()
    transcripts = _offline_shell_transcripts(
        tmp_path,
        shared_tool_item_id=shared_tool_item_id,
    )
    contents = tuple(
        _shell_client_jsonl(
            shell_path=_launch_preflight(tmp_path / "synthetic").shell.path,
            item_id=transcript.tool_item_id,
            thread_id=f"thread-{ordinal}",
        )
        for ordinal, transcript in enumerate(transcripts, 1)
    )
    layout["shell_capture_01"].write_bytes(contents[0])
    layout["shell_capture_02"].write_bytes(contents[1])
    rendered = _expected_normalized_shell_events(
        contents[0], transcripts[0].tool_item_id
    )
    layout["rendered_event"].write_bytes(rendered)
    supplied = _unchecked_replace(
        _launch_preflight(tmp_path / "synthetic"),
        rendered_event_utf8_bytes=len(rendered),
        rendered_event_sha256=sha256(rendered).hexdigest(),
    )
    return supplied, bundle_root, layout, transcripts


