@pytest.mark.parametrize(
    "racing_role",
    ("shell_capture_01", "shell_capture_02", "rendered_event"),
)
def test_shell_client_capture_recapture_rejects_each_second_capture_race(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    racing_role: str,
) -> None:
    module = _preflight()
    supplied, bundle_root, layout, transcripts = (
        _shell_client_capture_bundle_fixture(tmp_path)
    )
    original = module._validator_capture_plain_file
    calls: dict[Path, int] = {}

    def racing_capture(path: Path, *, max_bytes: int):
        payload, identity = original(path, max_bytes=max_bytes)
        calls[path] = calls.get(path, 0) + 1
        if path == layout[racing_role]:
            if calls[path] == 2:
                return payload + b" ", identity
        return payload, identity

    monkeypatch.setattr(module, "_validator_capture_plain_file", racing_capture)

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_recapture_shell_client_captures(
            supplied,
            bundle_root,
            transcripts,
        )


@pytest.mark.parametrize(
    "mutation",
    (
        "same-raw-hash",
        "same-identity",
        "wrong-transcript-scenario",
        "swapped-tool-item-ids",
        "rendered-event-byte",
        "stale-rendered-length",
        "stale-rendered-sha",
    ),
)
def test_shell_client_capture_recapture_rejects_crossbinding_or_retention_drift(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    mutation: str,
) -> None:
    module = _preflight()
    supplied, bundle_root, layout, transcripts = (
        _shell_client_capture_bundle_fixture(tmp_path)
    )
    if mutation == "same-raw-hash":
        layout["shell_capture_02"].write_bytes(
            layout["shell_capture_01"].read_bytes()
        )
    elif mutation == "same-identity":
        original = module._validator_capture_plain_file
        _payload, shared_identity = original(
            layout["shell_capture_01"],
            max_bytes=module._MAX_CAPTURE_BYTES,
        )

        def aliased_capture(path: Path, *, max_bytes: int):
            payload, identity = original(path, max_bytes=max_bytes)
            if path == layout["shell_capture_02"]:
                identity = shared_identity
            return payload, identity

        monkeypatch.setattr(
            module,
            "_validator_capture_plain_file",
            aliased_capture,
        )
    elif mutation == "wrong-transcript-scenario":
        transcripts = (
            replace(transcripts[0], scenario="file_add"),
            transcripts[1],
        )
    elif mutation == "swapped-tool-item-ids":
        transcripts = (
            replace(transcripts[0], tool_item_id=transcripts[1].tool_item_id),
            replace(transcripts[1], tool_item_id=transcripts[0].tool_item_id),
        )
    elif mutation == "rendered-event-byte":
        rendered = layout["rendered_event"].read_bytes()
        assert b'"status":"completed"' in rendered
        layout["rendered_event"].write_bytes(
            rendered.replace(
                b'"status":"completed"',
                b'"status":"completex"',
                1,
            )
        )
    elif mutation == "stale-rendered-length":
        supplied = _unchecked_replace(
            supplied,
            rendered_event_utf8_bytes=supplied.rendered_event_utf8_bytes + 1,
        )
    elif mutation == "stale-rendered-sha":
        supplied = _unchecked_replace(
            supplied,
            rendered_event_sha256=ZERO_SHA256,
        )

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_recapture_shell_client_captures(
            supplied,
            bundle_root,
            transcripts,
        )


def test_launch_recapture_loopback_transcripts_accepts_detached_manifest(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    server = _loopback_server_module()
    bundle_root = tmp_path / "launch-bundle"
    bundle_root.mkdir()
    layout = module._launch_bundle_layout(bundle_root)
    transcript_root = layout["loopback_transcript_root"]
    transcript_root.mkdir()
    raw_payloads = tuple(
        _offline_loopback_transcript_bytes(
            server,
            scenario,
            tmp_path / f"case-{ordinal}",
            port=43122 + ordinal,
            seed=ordinal * 16,
        )
        for ordinal, scenario in (
            (1, "shell"),
            (2, "shell"),
            (3, "file_add"),
            (4, "file_update"),
        )
    )
    assert len(set(raw_payloads)) == 4
    assert len({sha256(payload).hexdigest() for payload in raw_payloads}) == 4
    decoded = tuple(server.decode_loopback_transcript(payload) for payload in raw_payloads)
    manifest = _independent_loopback_transcript_manifest(decoded)
    manifest_bytes = _canonical(manifest)
    assert manifest_bytes == _canonical(
        module._launch_loopback_transcript_manifest_payload(decoded)
    )
    layout["loopback_transcript_manifest"].write_bytes(manifest_bytes)
    for payload, (_ordinal, _scenario, _relative_path, role) in zip(
        raw_payloads,
        module._LOOPBACK_TRANSCRIPT_RECORDS,
        strict=True,
    ):
        layout[role].write_bytes(payload)
    supplied = _unchecked_replace(
        _launch_preflight(tmp_path / "synthetic"),
        loopback_contract_sha256=server.LOOPBACK_CONTRACT_SHA256,
        loopback_transcript_manifest_sha256=sha256(
            manifest_bytes
        ).hexdigest(),
    )
    monkeypatch.setattr(
        server.LoopbackPreflightServer,
        "start",
        lambda *_args, **_kwargs: pytest.fail("recapture started a server"),
    )
    monkeypatch.setattr(
        socket,
        "socket",
        lambda *_args, **_kwargs: pytest.fail("recapture opened a socket"),
    )

    detached = module._launch_recapture_loopback_transcripts(
        supplied,
        bundle_root,
    )

    assert tuple(item.raw_bytes for item in detached) == raw_payloads
    assert all(item is not original for item, original in zip(detached, decoded, strict=True))
    assert detached[0].shell_repeat_normalized_bytes == (
        detached[1].shell_repeat_normalized_bytes
    )
    assert detached[0].exchanges[0].request_sha256 == sha256(
        detached[0].exchanges[0].request_head
        + detached[0].exchanges[0].request_body
    ).hexdigest()


