@pytest.mark.parametrize(
    "mutation",
    ("byte-drift", "identity-drift", "extra-entry", "renamed-entry"),
)
def test_launch_recapture_loopback_transcripts_rejects_second_capture_races(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    mutation: str,
) -> None:
    (
        module,
        _server,
        bundle_root,
        layout,
        _raw_payloads,
        _manifest,
        supplied,
    ) = _loopback_transcript_bundle_fixture(tmp_path)
    original_capture = module._validator_capture_plain_file
    target_role = "loopback_transcript_file_update"
    target = layout[target_role]
    transcript_root = layout["loopback_transcript_root"]
    call_count = 0

    def capture(path: Path, *, max_bytes: int):
        nonlocal call_count
        call_count += 1
        payload, identity = original_capture(path, max_bytes=max_bytes)
        if call_count == 10 and path == target:
            if mutation == "byte-drift":
                target.write_bytes(payload + b"race")
            elif mutation == "identity-drift":
                replacement = bundle_root / "replacement.bin"
                replacement.write_bytes(payload)
                replacement.replace(target)
                assert module._validator_plain_file_identity(target) != identity
            elif mutation == "extra-entry":
                (transcript_root / "race-extra.bin").write_bytes(b"race")
            else:
                target.rename(transcript_root / "race-renamed.bin")
        return payload, identity

    monkeypatch.setattr(module, "_validator_capture_plain_file", capture)

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_recapture_loopback_transcripts(supplied, bundle_root)
    assert call_count == 10


