def _offline_file_change_transcripts(
    tmp_path: Path,
    *,
    add_tool_item_id: str = "item_c6_00000000000000000000000000000034",
    update_tool_item_id: str = "item_c6_00000000000000000000000000000044",
    scenarios: tuple[str, str] = ("file_add", "file_update"),
    case_roots: tuple[Path, Path] | None = None,
) -> tuple[object, object]:
    server = _loopback_server_module()
    if case_roots is None:
        audit_root = tmp_path / "launch-bundle" / AUDIT_RELATIVE_ROOT
        case_roots = (audit_root, audit_root)
    return tuple(
        server.decode_loopback_transcript(
            _offline_loopback_transcript_bytes(
                server,
                scenario,
                case_root,
                port=43124 + ordinal,
                seed=ordinal * 16,
                tool_item_id=tool_item_id,
            )
        )
        for ordinal, (scenario, tool_item_id, case_root) in enumerate(
            zip(
                scenarios,
                (add_tool_item_id, update_tool_item_id),
                case_roots,
                strict=True,
            ),
            3,
        )
    )


def test_launch_recapture_file_change_preflight_reopens_history_and_live_tree(
    tmp_path: Path,
) -> None:
    module = _preflight()
    item_ids = (
        "item_c6_00000000000000000000000000000034",
        "item_c6_00000000000000000000000000000044",
    )
    supplied, bundle_root, layout = _filesystem_file_change_fixture(
        tmp_path,
        add_event_id=item_ids[0],
        update_event_id=item_ids[1],
    )
    transcripts = _offline_file_change_transcripts(
        tmp_path,
        add_tool_item_id=item_ids[0],
        update_tool_item_id=item_ids[1],
    )
    assert tuple(item.case_root for item in transcripts) == (
        str(layout["file_change_audit_root"]),
        str(layout["file_change_audit_root"]),
    )

    detached = module._launch_recapture_file_change_preflight(
        supplied,
        bundle_root,
        transcripts[0],
        transcripts[1],
    )

    assert detached == supplied
    assert detached is not supplied
    assert detached.add_capture_identity is not supplied.add_capture_identity
    assert detached.update_capture_identity is not supplied.update_capture_identity
    assert detached.before_snapshot is not supplied.before_snapshot
    assert detached.after_add_snapshot is not supplied.after_add_snapshot
    assert detached.after_update_snapshot is not supplied.after_update_snapshot
    assert (
        detached.after_update_snapshot.entries[0]
        is not supplied.after_update_snapshot.entries[0]
    )
    assert (
        detached.after_update_snapshot.entries[0].identity
        is not supplied.after_update_snapshot.entries[0].identity
    )


