def test_launch_plain_file_digest_accepts_only_explicit_hardlink_cardinality(
    tmp_path: Path,
) -> None:
    module = _preflight()
    executable = tmp_path / "git.exe"
    payload = b"MZ synthetic native leaf\n"
    executable.write_bytes(payload)
    for name in (
        "git-receive-pack.exe",
        "git-upload-archive.exe",
        "git-upload-pack.exe",
    ):
        os.link(executable, tmp_path / name)

    size, digest, identity = module._launch_capture_plain_file_digest(
        executable,
        max_bytes=1024,
        expected_link_count=4,
    )

    assert size == len(payload)
    assert digest == sha256(payload).hexdigest()
    assert identity.link_count == 4
    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_capture_plain_file_digest(
            executable,
            max_bytes=1024,
            expected_link_count=1,
        )


