class _FakeVersionFunction:
    def __init__(self, implementation: object) -> None:
        self._implementation = implementation

    def __call__(self, *args: object) -> object:
        return self._implementation(*args)  # type: ignore[operator]


class _FakeNeutralVersionDll:
    def __init__(
        self,
        *,
        translations: tuple[tuple[int, int], ...],
        values: dict[tuple[int, int, str], str],
        signature: int = 0xFEEF04BD,
    ) -> None:
        self.flags: list[int] = []
        self._fixed = (ctypes.c_uint32 * 13)(signature, *([0] * 12))
        translation_bytes = b"".join(
            struct.pack("<HH", language, code_page)
            for language, code_page in translations
        )
        self._translations = ctypes.create_string_buffer(translation_bytes)
        self._strings = {
            key: ctypes.create_unicode_buffer(value)
            for key, value in values.items()
        }
        self.GetFileVersionInfoSizeExW = _FakeVersionFunction(self._get_size)
        self.GetFileVersionInfoExW = _FakeVersionFunction(self._get_info)
        self.VerQueryValueW = _FakeVersionFunction(self._query)

    def _get_size(self, flags: int, _path: str, _ignored: object) -> int:
        self.flags.append(int(flags))
        return 128

    def _get_info(
        self,
        flags: int,
        _path: str,
        _ignored: int,
        _size: int,
        _buffer: object,
    ) -> int:
        self.flags.append(int(flags))
        return 1

    @staticmethod
    def _set_query_result(
        pointer_output: object,
        length_output: object,
        value: object,
        length: int,
    ) -> None:
        ctypes.cast(
            pointer_output,
            ctypes.POINTER(ctypes.c_void_p),
        )[0] = ctypes.cast(value, ctypes.c_void_p)
        ctypes.cast(
            length_output,
            ctypes.POINTER(ctypes.c_uint),
        )[0] = length

    def _query(
        self,
        _buffer: object,
        block: str,
        pointer_output: object,
        length_output: object,
    ) -> int:
        if block == "\\":
            self._set_query_result(
                pointer_output,
                length_output,
                self._fixed,
                ctypes.sizeof(self._fixed),
            )
            return 1
        if block == "\\VarFileInfo\\Translation":
            self._set_query_result(
                pointer_output,
                length_output,
                self._translations,
                ctypes.sizeof(self._translations) - 1,
            )
            return 1
        parts = block.split("\\")
        if len(parts) != 4 or parts[1] != "StringFileInfo":
            return 0
        translation = parts[2]
        key = (int(translation[:4], 16), int(translation[4:], 16), parts[3])
        value = self._strings.get(key)
        if value is None:
            return 0
        self._set_query_result(
            pointer_output,
            length_output,
            value,
            len(value.value) + 1,
        )
        return 1


def test_launch_pe_version_fields_use_neutral_image_resources(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    translation = (0x0409, 0x04B0)
    fake = _FakeNeutralVersionDll(
        translations=(translation,),
        values={
            (*translation, "FileVersion"): " 1.2.3 exact ",
            (*translation, "ProductVersion"): "product-exact+metadata",
        },
    )
    monkeypatch.setattr(module.ctypes, "WinDLL", lambda *_args, **_kwargs: fake)

    assert module._launch_pe_version_fields(Path(sys.executable)) == (
        " 1.2.3 exact ",
        "product-exact+metadata",
    )
    assert fake.flags == [0x00000002, 0x00000002]


@pytest.mark.parametrize("mutation", ("signature", "duplicate", "missing-field"))
def test_launch_pe_version_fields_reject_ambiguous_or_incomplete_resources(
    monkeypatch: pytest.MonkeyPatch,
    mutation: str,
) -> None:
    module = _preflight()
    first = (0x0409, 0x04B0)
    second = (0x0411, 0x04B0)
    translations = (first, second)
    values = {
        (*first, "FileVersion"): "1.2.3",
        (*first, "ProductVersion"): "1.2.3",
        (*second, "FileVersion"): "1.2.3",
        (*second, "ProductVersion"): "1.2.3",
    }
    signature = 0xFEEF04BD
    if mutation == "signature":
        signature = 0
    elif mutation == "duplicate":
        translations = (first, first)
    else:
        del values[(*second, "ProductVersion")]
    fake = _FakeNeutralVersionDll(
        translations=translations,
        values=values,
        signature=signature,
    )
    monkeypatch.setattr(module.ctypes, "WinDLL", lambda *_args, **_kwargs: fake)

    with pytest.raises(
        RuntimeError,
        match=f"^{module.LAUNCH_PREFLIGHT_BUNDLE_INVALID}$",
    ):
        module._launch_pe_version_fields(Path(sys.executable))


