def test_launch_recapture_executable_closure_rebuilds_six_detached_descriptors(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    supplied = _launch_preflight(tmp_path)
    paths = {
        "codex_distribution_manifest": Path(
            supplied.codex.distribution_manifest.path
        ),
        "codex_platform_manifest": Path(supplied.codex.platform_manifest.path),
        "codex": Path(supplied.codex.executable_path),
        "pwsh": Path(supplied.shell.path),
        "powershell_decoder": Path(supplied.decoder_path),
        "python": Path(supplied.guarded_python.python_path),
        "rg": Path(supplied.rg_path),
        "comspec": Path(supplied.comspec_path),
    }
    identities = {
        "codex": supplied.codex.executable_identity,
        "pwsh": _identity(341),
        "powershell_decoder": _identity(342),
        "python": supplied.guarded_python.python_identity,
        "rg": _identity(343),
        "comspec": _identity(344),
    }
    facts = {
        "codex": (
            supplied.codex.executable_size,
            supplied.codex.executable_sha256,
            identities["codex"],
            (supplied.codex.executable_path,),
            None,
        ),
        "pwsh": (
            201,
            supplied.shell.sha256,
            identities["pwsh"],
            (supplied.shell.path,),
            (supplied.shell.file_version, supplied.shell.product_version),
        ),
        "powershell_decoder": (
            202,
            supplied.decoder_sha256,
            identities["powershell_decoder"],
            (supplied.decoder_path,),
            None,
        ),
        "python": (
            supplied.guarded_python.python_size,
            supplied.guarded_python.python_sha256,
            identities["python"],
            (supplied.guarded_python.python_path,),
            ("3.14.0", "3.14.0"),
        ),
        "rg": (
            203,
            supplied.rg_sha256,
            identities["rg"],
            (supplied.rg_path,),
            None,
        ),
        "comspec": (
            204,
            supplied.comspec_sha256,
            identities["comspec"],
            (supplied.comspec_path,),
            None,
        ),
    }
    fixed = {
        "codex": facts["codex"][:2] + (None, None),
        "pwsh": facts["pwsh"][:2] + facts["pwsh"][4],
        "python": facts["python"][:2] + facts["python"][4],
    }

    def detached_codex(_value: object) -> object:
        value = supplied.codex
        return module.FrozenCodexClientIdentity(
            version=value.version,
            executable_path=value.executable_path,
            executable_size=value.executable_size,
            executable_sha256=value.executable_sha256,
            executable_identity=module._launch_copy_plain_identity(
                value.executable_identity
            ),
            distribution_manifest=module._launch_detach_capture(
                value.distribution_manifest
            ),
            platform_manifest=module._launch_detach_capture(
                value.platform_manifest
            ),
            distribution_name=value.distribution_name,
            distribution_version=value.distribution_version,
            platform_package_key=value.platform_package_key,
            platform_name=value.platform_name,
            platform_version=value.platform_version,
            client_label=value.client_label,
            canonical_sha256=value.canonical_sha256,
        )

    def capture(path: Path, **_kwargs: object) -> object:
        role = next(name for name, expected in paths.items() if expected == path)
        return facts[role]

    monkeypatch.setattr(module, "_launch_expected_executable_paths", lambda _root: paths)
    monkeypatch.setattr(module, "validate_frozen_codex_client_identity", detached_codex)
    monkeypatch.setattr(
        module,
        "validate_frozen_guarded_python_runtime",
        lambda _value: supplied.guarded_python,
    )
    monkeypatch.setattr(module, "_launch_capture_executable_file_facts", capture)
    monkeypatch.setattr(
        module,
        "_launch_executable_fixed_facts",
        lambda role: fixed.get(role),
        raising=False,
    )

    codex, guarded, shell, descriptors = (
        module._launch_recapture_executable_closure(
            supplied,
            tmp_path,
        )
    )

    assert codex == supplied.codex and codex is not supplied.codex
    assert guarded == supplied.guarded_python and guarded is not supplied.guarded_python
    assert shell == supplied.shell and shell is not supplied.shell
    assert tuple(item.role for item in descriptors) == (
        "codex",
        "pwsh",
        "powershell_decoder",
        "python",
        "rg",
        "comspec",
    )
    assert tuple(item.path for item in descriptors) == tuple(
        str(paths[role])
        for role in ("codex", "pwsh", "powershell_decoder", "python", "rg", "comspec")
    )
    assert len({item.identity for item in descriptors}) == 6


