def test_host_native_core_source_contract_pins_exact_30000_unit_semantics() -> None:
    module = _preflight()
    executable = "C:\\x.exe"
    fixed_units = len((executable + " " + "\x00").encode("utf-16-le")) // 2
    exact_argument = "a" * (30_000 - fixed_units)
    over_argument = exact_argument + "a"
    exact_command_line, exact_units, exact_sha256 = (
        _broker_native_core_ms_crt_reference_render(
            executable,
            (exact_argument,),
        )
    )
    _, over_units, _ = _broker_native_core_ms_crt_reference_render(
        executable,
        (over_argument,),
    )
    empty_command_line, empty_units, empty_sha256 = (
        _broker_native_core_ms_crt_reference_render(
            executable,
            ("",),
        )
    )

    fragment = module._launch_extract_host_native_vector_source_fragment(
        _HOST_NATIVE_VECTOR_SOURCE_BYTES
    )

    assert exact_units == 30_000
    assert over_units == 30_001
    assert exact_sha256 == sha256(
        (exact_command_line + "\x00").encode("utf-16-le")
    ).hexdigest()
    assert empty_command_line == 'C:\\x.exe ""'
    assert empty_units == len(
        (empty_command_line + "\x00").encode("utf-16-le")
    ) // 2
    assert empty_sha256 == sha256(
        (empty_command_line + "\x00").encode("utf-16-le")
    ).hexdigest()
    assert fragment.source_bytes.count(b"[AllowEmptyString()]") == 2
    assert fragment.source_bytes.count(b"[AllowEmptyCollection()]") == 1
    assert b"[long]$unitCount=[long]$commandLine.Length + 1" in (
        fragment.source_bytes
    )
    assert b"$unitCount -lt 1 -or $unitCount -gt 30000" in (
        fragment.source_bytes
    )
    assert b"$commandLine + [char]0" in fragment.source_bytes
    assert (
        b"complete-suite-windows-native-vector-v1"
        in fragment.source_bytes
    )


@pytest.mark.parametrize(
    ("mutation", "old", "new"),
    (
        (
            "typed-value-binder",
            (
                b"function Assert-C6HostNativeVectorString {\n"
                b"    param(\n"
                b"        [Parameter(Mandatory)]\n"
                b"        [AllowNull()]\n"
                b"        [AllowEmptyString()]\n"
                b"        [object]$Value"
            ),
            (
                b"function Assert-C6HostNativeVectorString {\n"
                b"    param(\n"
                b"        [Parameter(Mandatory)]\n"
                b"        [AllowNull()]\n"
                b"        [AllowEmptyString()]\n"
                b"        [string]$Value"
            ),
        ),
        (
            "missing-empty-string-binder-evidence",
            (
                b"function ConvertTo-C6HostNativeArgument {\n"
                b"    param(\n"
                b"        [Parameter(Mandatory)]\n"
                b"        [AllowNull()]\n"
                b"        [AllowEmptyString()]\n"
            ),
            (
                b"function ConvertTo-C6HostNativeArgument {\n"
                b"    param(\n"
                b"        [Parameter(Mandatory)]\n"
                b"        [AllowNull()]\n"
            ),
        ),
        (
            "missing-empty-collection-binder-evidence",
            b"        [AllowEmptyCollection()]\n",
            b"",
        ),
        (
            "missing-null-guard",
            b"    if ($null -eq $Value) { throw 'host native vector contains null string' }\n",
            b"",
        ),
        (
            "missing-string-type-guard",
            (
                b"    if ($Value -isnot [string]) {\n"
                b"        throw 'host native vector value is not a string'\n"
                b"    }\n"
            ),
            b"",
        ),
        (
            "missing-nul-guard",
            b"        if ($character -eq [char]0) { throw 'host native vector contains NUL' }\n",
            b"",
        ),
        (
            "missing-high-surrogate-guard",
            b"        if ([char]::IsHighSurrogate($character)) {\n",
            b"        if ($false) {\n",
        ),
        (
            "missing-low-surrogate-guard",
            b"        } elseif ([char]::IsLowSurrogate($character)) {\n",
            b"        } elseif ($false) {\n",
        ),
        (
            "argument-list-binder-erases-evidence",
            b"$ArgumentList -isnot [object[]]",
            b"$ArgumentList -isnot [string[]]",
        ),
        (
            "wrong-unit-limit",
            b"$unitCount -gt 30000",
            b"$unitCount -gt 32767",
        ),
        (
            "terminal-nul-not-counted",
            b"[long]$commandLine.Length + 1",
            b"[long]$commandLine.Length",
        ),
        (
            "terminal-nul-not-hashed",
            b"$commandLine + [char]0",
            b"$commandLine",
        ),
        (
            "wrong-encoding",
            b"[Text.Encoding]::Unicode.GetBytes",
            b"[Text.Encoding]::UTF8.GetBytes",
        ),
        (
            "wrong-digest",
            b"[Security.Cryptography.SHA256]::HashData",
            b"[Security.Cryptography.SHA1]::HashData",
        ),
        (
            "wrong-contract",
            b"complete-suite-windows-native-vector-v1",
            b"complete-suite-windows-native-vector-v2",
        ),
        (
            "missing-command-line-material",
            b"        command_line=$commandLine\n",
            b"",
        ),
    ),
)
def test_host_native_core_source_contract_rejects_native_vector_mutants(
    mutation: str,
    old: bytes,
    new: bytes,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    assert _HOST_NATIVE_VECTOR_SOURCE_BYTES.count(old) == 1, mutation
    mutated_fragment = _HOST_NATIVE_VECTOR_SOURCE_BYTES.replace(old, new, 1)
    host_body = mutated_fragment

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_extract_host_native_vector_source_fragment(host_body)

    assert side_effect_calls == []


def test_host_native_abi_contract_facts_registry_is_exact_immutable_and_dormant(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)

    registry = module._launch_host_native_abi_contract_facts_registry()
    decoded = json.loads(registry.payload_bytes.decode("ascii"))
    tables = {record["table"]: record for record in decoded}

    assert registry.version == "complete-suite-host-native-abi-contract-facts-v1"
    assert registry.implementation_id == "host-native-core-v1"
    assert registry.payload_sha256 == sha256(registry.payload_bytes).hexdigest()
    assert len(registry.payload_bytes) == 17295
    assert (
        registry.payload_sha256
        == "d3c8da5b697b7038caa51beebdede2760ac2f2646a97a97502a360692a482277"
    )
    assert tuple(tables) == (
        "identity",
        "initialization-order",
        "structure-layout",
        "variable-allocation",
        "constant",
        "api-declaration",
        "forbidden-substitution",
        "unresolved-oracle",
    )
    assert tables["identity"] == {
        "table": "identity",
        "columns": [
            "implementation_id",
            "platform",
            "architecture",
            "pointer_bytes",
            "bool_bytes",
            "pack",
            "interop_mechanism",
            "fixed_type_name",
            "type_cache_authority",
        ],
        "rows": [
            [
                "host-native-core-v1",
                "windows",
                "x64",
                8,
                4,
                8,
                "lazy-in-function-csharp-add-type-v1",
                "C6HostNativeCoreV1",
                "private-successful-add-type-return-only",
            ]
        ],
    }
    assert tables["initialization-order"]["columns"] == [
        "ordinal",
        "phase",
        "required_predecessor",
        "permitted_effect",
    ]
    assert tables["initialization-order"]["rows"] == [
        [0, "dot-source", "none", "define-functions-only"],
        [
            1,
            "native-vector",
            "dot-source",
            "validate-and-bind-native-vector-only",
        ],
        [
            2,
            "descriptor-cross-binding",
            "native-vector",
            "compare-vector-contract-units-and-sha256",
        ],
        [
            3,
            "type-collision-check",
            "descriptor-cross-binding",
            "reject-preloaded-fixed-type-without-private-cache",
        ],
        [
            4,
            "lazy-add-type",
            "type-collision-check",
            "compile-fixed-source-and-cache-returned-type-only",
        ],
        [
            5,
            "x64-abi-assertion",
            "lazy-add-type",
            "assert-pointer-bool-pack-sizes-and-critical-offsets",
        ],
        [
            6,
            "native-preparation",
            "x64-abi-assertion",
            "allow-first-native-preparation-or-pinvoke",
        ],
        [
            7,
            "create-process",
            "native-preparation",
            "allow-one-createprocessw-under-exact-constructor-contract",
        ],
    ]
    with pytest.raises(FrozenInstanceError):
        registry.payload_bytes = b"[]"
    assert not hasattr(registry, "__dict__")
    assert side_effect_calls == []


