@pytest.mark.parametrize(
    "mutation",
    (
        "table-order",
        "identity-implementation",
        "identity-interop",
        "initialization-order",
        "layout-size",
        "allocation-formula",
        "constant-value",
        "api-signature",
        "missing-forbidden",
        "missing-unresolved",
        "extra-table",
        "noncanonical-whitespace",
        "bytes-subclass",
        "bytearray",
    ),
)
def test_broker_native_abi_contract_facts_scanner_rejects_mutants(
    mutation: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    canonical = (
        module._launch_broker_native_abi_contract_facts_registry().payload_bytes
    )
    decoded = json.loads(canonical.decode("ascii"))
    tables = {record["table"]: record for record in decoded}
    if mutation == "table-order":
        decoded[0], decoded[1] = decoded[1], decoded[0]
    elif mutation == "identity-implementation":
        tables["identity"]["rows"][0][0] = "host-native-core-v1"
    elif mutation == "identity-interop":
        tables["identity"]["rows"][0][6] = "ctypes"
    elif mutation == "initialization-order":
        rows = tables["initialization-order"]["rows"]
        rows[3], rows[4] = rows[4], rows[3]
    elif mutation == "layout-size":
        tables["structure-layout"]["rows"][2][1] = 104
    elif mutation == "allocation-formula":
        tables["variable-allocation"]["rows"][0][1] = "16 + 8 * capacity"
    elif mutation == "constant-value":
        tables["constant"]["rows"][4][1] = 525312
    elif mutation == "api-signature":
        tables["api-declaration"]["rows"][3][2] = "BOOL(PWSTR)"
    elif mutation == "missing-forbidden":
        del tables["forbidden-substitution"]["rows"][0]
    elif mutation == "missing-unresolved":
        del tables["unresolved-oracle"]["rows"][0]
    elif mutation == "extra-table":
        decoded.append({"table": "extra", "columns": [], "rows": []})
    elif mutation in {
        "noncanonical-whitespace",
        "bytes-subclass",
        "bytearray",
    }:
        pass
    else:
        raise AssertionError(mutation)
    payload: object = json.dumps(
        decoded,
        ensure_ascii=True,
        allow_nan=False,
        sort_keys=False,
        separators=(",", ":"),
    ).encode("ascii")
    if mutation == "noncanonical-whitespace":
        payload = b" " + payload
    elif mutation == "bytes-subclass":

        class _BytesSubclass(bytes):
            pass

        payload = _BytesSubclass(payload)
    elif mutation == "bytearray":
        payload = bytearray(payload)

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_extract_broker_native_abi_contract_facts(payload)

    assert side_effect_calls == []


