@pytest.mark.parametrize(
    "mutation",
    (
        "wrong-pipe-source-hash",
        "wrong-abi-hash",
        "wrong-filetime-pack",
        "wrong-process-entry-size",
        "wrong-image-array",
        "wrong-query-access",
        "wrong-api-name",
        "dynamic-dll-name",
        "use-last-error-false",
        "missing-argtypes",
        "get-process-id-call",
        "top-level-binder-call",
        "constructor-begin-marker",
        "constructor-end-marker",
        "bom",
        "cr",
        "nul",
        "missing-terminal-lf",
        "bytes-subclass",
        "bytearray",
    ),
)
def test_broker_native_process_observation_ctypes_source_extractor_rejects_mutants(
    mutation: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    source: object = (
        module._launch_broker_native_process_observation_ctypes_source_fragment().source_bytes
    )
    if mutation == "wrong-pipe-source-hash":
        source = source.replace(
            b"6b3bc0d117186bdcd0e5b832b98210edc37cb9b6c5b21ba0b69b61cf98cef3e3",
            b"0" * 64,
            1,
        )
    elif mutation == "wrong-abi-hash":
        source = source.replace(
            b"d3dabd196c134fca03f5459b73562c9f5a6e2f04d770e26be692480fe7969661",
            b"0" * 64,
            1,
        )
    elif mutation == "wrong-filetime-pack":
        source = source.replace(b"_pack_ = 8", b"_pack_ = 4", 1)
    elif mutation == "wrong-process-entry-size":
        source = source.replace(
            b"ctypes.sizeof(_C6BrokerNativeCoreV1ProcessEntry32W) != 568",
            b"ctypes.sizeof(_C6BrokerNativeCoreV1ProcessEntry32W) != 567",
            1,
        )
    elif mutation == "wrong-image-array":
        source = source.replace(
            b'("szExeFile", ctypes.wintypes.WCHAR * 260)',
            b'("szExeFile", ctypes.wintypes.WCHAR * 259)',
            1,
        )
    elif mutation == "wrong-query-access":
        source = source.replace(
            b"_C6_BROKER_NATIVE_CORE_V1_PROCESS_QUERY_LIMITED_INFORMATION = 4096",
            b"_C6_BROKER_NATIVE_CORE_V1_PROCESS_QUERY_LIMITED_INFORMATION = 0",
            1,
        )
    elif mutation == "wrong-api-name":
        source = source.replace(
            b"kernel32.OpenProcess",
            b"kernel32.OpenThread",
            1,
        )
    elif mutation == "dynamic-dll-name":
        source = source.replace(
            b'ctypes.WinDLL("kernel32.dll", use_last_error=True)',
            b"ctypes.WinDLL(dll_name, use_last_error=True)",
            1,
        )
    elif mutation == "use-last-error-false":
        source = source.replace(b"use_last_error=True", b"use_last_error=False", 1)
    elif mutation == "missing-argtypes":
        source = source.replace(b".argtypes = ", b".argument_types = ", 1)
    elif mutation == "get-process-id-call":
        source = source.replace(
            b"    return _C6BrokerNativeCoreV1ProcessObservationBindings(\n",
            b"    get_process_id(None)\n"
            b"    return _C6BrokerNativeCoreV1ProcessObservationBindings(\n",
            1,
        )
    elif mutation == "top-level-binder-call":
        source += b"_c6_broker_native_core_v1_bind_process_observation_apis()\n"
    elif mutation == "constructor-begin-marker":
        source += b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN\n"
    elif mutation == "constructor-end-marker":
        source += b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END\n"
    elif mutation == "bom":
        source = b"\xef\xbb\xbf" + source
    elif mutation == "cr":
        source = source.replace(b"\n", b"\r\n", 1)
    elif mutation == "nul":
        source = source.replace(b"\n", b"\x00\n", 1)
    elif mutation == "missing-terminal-lf":
        source = source[:-1]
    elif mutation == "bytes-subclass":

        class _BytesSubclass(bytes):
            pass

        source = _BytesSubclass(source)
    elif mutation == "bytearray":
        source = bytearray(source)
    else:
        raise AssertionError(mutation)

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_extract_broker_native_process_observation_ctypes_source_fragment(
            source
        )

    assert side_effect_calls == []


def test_broker_native_handle_inspection_ctypes_source_is_exact_cross_bound_and_dormant(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    abi_registry = module._launch_broker_native_abi_contract_facts_registry()
    process_fragment = (
        module._launch_broker_native_process_observation_ctypes_source_fragment()
    )

    fragment = (
        module._launch_broker_native_handle_inspection_ctypes_source_fragment()
    )

    assert fragment.version == (
        "complete-suite-broker-native-handle-inspection-ctypes-source-fragment-v1"
    )
    assert fragment.implementation_id == "broker-native-core-v1"
    assert fragment.activation_state == "dormant-source-only"
    assert (
        fragment.completeness_state
        == "handle-inspection-and-duplication-abi-only"
    )
    assert fragment.abi_contract_facts_version == abi_registry.version
    assert fragment.abi_contract_facts_size == 17_337
    assert fragment.abi_contract_facts_sha256 == (
        "d3dabd196c134fca03f5459b73562c9f5a6e2f04d770e26be692480fe7969661"
    )
    assert (
        fragment.process_observation_source_version == process_fragment.version
    )
    assert fragment.process_observation_source_size == 8_224
    assert (
        fragment.process_observation_source_sha256
        == process_fragment.source_sha256
    )
    assert fragment.class_names == (
        "_C6BrokerNativeCoreV1PublicObjectBasicInformation",
        "_C6BrokerNativeCoreV1UnicodeString",
        "_C6BrokerNativeCoreV1PublicObjectTypeInformation",
        "_C6BrokerNativeCoreV1HandleInspectionBindings",
    )
    assert fragment.function_names == (
        "_c6_broker_native_core_v1_assert_handle_inspection_abi",
        "_c6_broker_native_core_v1_bind_handle_inspection_apis",
    )
    assert type(fragment.source_bytes) is bytes
    assert fragment.source_bytes.startswith(
        b"_C6_BROKER_NATIVE_CORE_V1_HANDLE_INSPECTION_ABI_FACTS_VERSION = "
    )
    assert fragment.source_bytes.endswith(b"\n")
    assert b"\r" not in fragment.source_bytes
    assert b"\x00" not in fragment.source_bytes
    assert b"C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN" not in (
        fragment.source_bytes
    )
    assert b"C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END" not in (
        fragment.source_bytes
    )
    assert abi_registry.version.encode("ascii") in fragment.source_bytes
    assert abi_registry.payload_sha256.encode("ascii") in fragment.source_bytes
    assert process_fragment.version.encode("ascii") in fragment.source_bytes
    assert process_fragment.source_sha256.encode("ascii") in fragment.source_bytes
    assert fragment.source_sha256 == sha256(fragment.source_bytes).hexdigest()
    assert not hasattr(fragment, "__dict__")
    with pytest.raises((AttributeError, FrozenInstanceError)):
        fragment.activation_state = "active"
    assert not (
        Path(module.__file__).parent / "complete_suite_control_plane.ps1"
    ).exists()
    assert side_effect_calls == []


