def test_broker_native_token_security_ctypes_source_has_exact_static_surface(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    source = (
        module._launch_broker_native_token_security_ctypes_source_fragment().source_bytes
    )
    tree = ast.parse(source.decode("ascii", errors="strict"))

    assert not any(
        isinstance(node, (ast.Import, ast.ImportFrom))
        for node in ast.walk(tree)
    )
    assert tuple(
        node.name for node in tree.body if isinstance(node, ast.ClassDef)
    ) == (
        "_C6BrokerNativeCoreV1SidIdentifierAuthority",
        "_C6BrokerNativeCoreV1SidAndAttributes",
        "_C6BrokerNativeCoreV1Acl",
        "_C6BrokerNativeCoreV1AceHeader",
        "_C6BrokerNativeCoreV1AccessAllowedAce",
        "_C6BrokerNativeCoreV1AclSizeInformation",
        "_C6BrokerNativeCoreV1SecurityDescriptor",
        "_C6BrokerNativeCoreV1SecurityDescriptorRelative",
        "_C6BrokerNativeCoreV1TokenSecurityBindings",
    )
    assert tuple(
        node.name for node in tree.body if isinstance(node, ast.FunctionDef)
    ) == (
        "_c6_broker_native_core_v1_assert_token_security_abi",
        "_c6_broker_native_core_v1_bind_token_security_apis",
    )
    assert not any(
        isinstance(node, (ast.AsyncFunctionDef, ast.Await))
        for node in ast.walk(tree)
    )
    assert source.count(b"_pack_ = 8") == 8
    assert b'("Value", ctypes.wintypes.BYTE * 6)' in source
    assert b'("Sid", ctypes.c_void_p)' in source
    assert b'("SidStart", ctypes.wintypes.DWORD)' in source

    binder = next(
        node
        for node in tree.body
        if isinstance(node, ast.FunctionDef)
        and node.name == "_c6_broker_native_core_v1_bind_token_security_apis"
    )
    win_dll_calls = tuple(
        node
        for node in ast.walk(binder)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
        and isinstance(node.func.value, ast.Name)
        and node.func.value.id == "ctypes"
        and node.func.attr == "WinDLL"
    )
    assert len(win_dll_calls) == 1
    assert len(win_dll_calls[0].args) == 1
    assert isinstance(win_dll_calls[0].args[0], ast.Constant)
    assert win_dll_calls[0].args[0].value == "advapi32.dll"
    assert len(win_dll_calls[0].keywords) == 1
    assert win_dll_calls[0].keywords[0].arg == "use_last_error"
    assert isinstance(win_dll_calls[0].keywords[0].value, ast.Constant)
    assert win_dll_calls[0].keywords[0].value.value is True

    bound_api_names = tuple(
        node.value.attr
        for node in binder.body
        if isinstance(node, ast.Assign)
        and isinstance(node.value, ast.Attribute)
        and isinstance(node.value.value, ast.Name)
        and node.value.value.id == "advapi32"
    )
    assert bound_api_names == (
        "OpenProcessToken",
        "GetTokenInformation",
        "IsValidSid",
        "GetLengthSid",
        "CopySid",
        "EqualSid",
        "InitializeAcl",
        "AddAccessAllowedAceEx",
        "InitializeSecurityDescriptor",
        "SetSecurityDescriptorOwner",
        "SetSecurityDescriptorDacl",
        "SetSecurityDescriptorControl",
    )
    assert source.count(b".argtypes = ") == 12
    assert source.count(b".restype = ") == 12
    called_api_names = {
        node.func.attr
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
        and node.func.attr in bound_api_names
    }
    assert called_api_names == set()
    assert not any(
        isinstance(node, ast.Call)
        for statement in tree.body
        for node in ast.walk(statement)
        if not isinstance(statement, (ast.ClassDef, ast.FunctionDef))
    )
    assert b"GetSecurityInfo" not in source
    assert b"GetAclInformation" not in source
    assert b"GetAce" not in source
    assert b"LocalFree" not in source
    assert b"kernel32" not in source
    assert b"ntdll" not in source
    assert b"CreateProcessW" not in source
    assert b"ctypes.windll" not in source
    assert b"ctypes.CDLL" not in source
    assert b"ctypes.PyDLL" not in source
    assert b"getattr(" not in source
    assert side_effect_calls == []


