@pytest.mark.parametrize(
    "mutation",
    (
        "wrong-handle-source-hash",
        "wrong-abi-hash",
        "wrong-sid-authority-pack",
        "wrong-sid-authority-size",
        "wrong-sid-attributes-size",
        "wrong-acl-size",
        "wrong-ace-size",
        "wrong-security-descriptor-size",
        "wrong-relative-descriptor-size",
        "wrong-token-query",
        "wrong-protected-dacl",
        "wrong-api-name",
        "dynamic-dll-name",
        "use-last-error-false",
        "missing-argtypes",
        "open-process-token-call",
        "top-level-binder-call",
        "constructor-begin-marker",
        "constructor-end-marker",
        "bom",
        "cr",
        "nul",
        "missing-terminal-lf",
        "bytes-subclass",
        "bytearray",
    ),
)
def test_broker_native_token_security_ctypes_source_extractor_rejects_mutants(
    mutation: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    source: object = (
        module._launch_broker_native_token_security_ctypes_source_fragment().source_bytes
    )
    if mutation == "wrong-handle-source-hash":
        source = source.replace(
            b"f87e972c383897e62530e348ae042c1619d5efa1efff06ea86e6335666dc9f34",
            b"0" * 64,
            1,
        )
    elif mutation == "wrong-abi-hash":
        source = source.replace(
            b"d3dabd196c134fca03f5459b73562c9f5a6e2f04d770e26be692480fe7969661",
            b"0" * 64,
            1,
        )
    elif mutation == "wrong-sid-authority-pack":
        source = source.replace(b"_pack_ = 8", b"_pack_ = 4", 1)
    elif mutation == "wrong-sid-authority-size":
        source = source.replace(
            b"ctypes.sizeof(_C6BrokerNativeCoreV1SidIdentifierAuthority) != 6",
            b"ctypes.sizeof(_C6BrokerNativeCoreV1SidIdentifierAuthority) != 7",
            1,
        )
    elif mutation == "wrong-sid-attributes-size":
        source = source.replace(
            b"ctypes.sizeof(_C6BrokerNativeCoreV1SidAndAttributes) != 16",
            b"ctypes.sizeof(_C6BrokerNativeCoreV1SidAndAttributes) != 15",
            1,
        )
    elif mutation == "wrong-acl-size":
        source = source.replace(
            b"ctypes.sizeof(_C6BrokerNativeCoreV1Acl) != 8",
            b"ctypes.sizeof(_C6BrokerNativeCoreV1Acl) != 7",
            1,
        )
    elif mutation == "wrong-ace-size":
        source = source.replace(
            b"ctypes.sizeof(_C6BrokerNativeCoreV1AccessAllowedAce) != 12",
            b"ctypes.sizeof(_C6BrokerNativeCoreV1AccessAllowedAce) != 11",
            1,
        )
    elif mutation == "wrong-security-descriptor-size":
        source = source.replace(
            b"ctypes.sizeof(_C6BrokerNativeCoreV1SecurityDescriptor) != 40",
            b"ctypes.sizeof(_C6BrokerNativeCoreV1SecurityDescriptor) != 39",
            1,
        )
    elif mutation == "wrong-relative-descriptor-size":
        source = source.replace(
            b"ctypes.sizeof(_C6BrokerNativeCoreV1SecurityDescriptorRelative) != 20",
            b"ctypes.sizeof(_C6BrokerNativeCoreV1SecurityDescriptorRelative) != 19",
            1,
        )
    elif mutation == "wrong-token-query":
        source = source.replace(
            b"_C6_BROKER_NATIVE_CORE_V1_TOKEN_QUERY = 8",
            b"_C6_BROKER_NATIVE_CORE_V1_TOKEN_QUERY = 0",
            1,
        )
    elif mutation == "wrong-protected-dacl":
        source = source.replace(
            b"_C6_BROKER_NATIVE_CORE_V1_SE_DACL_PROTECTED = 4096",
            b"_C6_BROKER_NATIVE_CORE_V1_SE_DACL_PROTECTED = 0",
            1,
        )
    elif mutation == "wrong-api-name":
        source = source.replace(
            b"advapi32.OpenProcessToken",
            b"advapi32.OpenThreadToken",
            1,
        )
    elif mutation == "dynamic-dll-name":
        source = source.replace(
            b'ctypes.WinDLL("advapi32.dll", use_last_error=True)',
            b"ctypes.WinDLL(dll_name, use_last_error=True)",
            1,
        )
    elif mutation == "use-last-error-false":
        source = source.replace(b"use_last_error=True", b"use_last_error=False", 1)
    elif mutation == "missing-argtypes":
        source = source.replace(b".argtypes = ", b".argument_types = ", 1)
    elif mutation == "open-process-token-call":
        source = source.replace(
            b"    return _C6BrokerNativeCoreV1TokenSecurityBindings(\n",
            b"    open_process_token(None, 0, None)\n"
            b"    return _C6BrokerNativeCoreV1TokenSecurityBindings(\n",
            1,
        )
    elif mutation == "top-level-binder-call":
        source += b"_c6_broker_native_core_v1_bind_token_security_apis()\n"
    elif mutation == "constructor-begin-marker":
        source += b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN\n"
    elif mutation == "constructor-end-marker":
        source += b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END\n"
    elif mutation == "bom":
        source = b"\xef\xbb\xbf" + source
    elif mutation == "cr":
        source = source.replace(b"\n", b"\r\n", 1)
    elif mutation == "nul":
        source = source.replace(b"\n", b"\x00\n", 1)
    elif mutation == "missing-terminal-lf":
        source = source[:-1]
    elif mutation == "bytes-subclass":

        class _BytesSubclass(bytes):
            pass

        source = _BytesSubclass(source)
    elif mutation == "bytearray":
        source = bytearray(source)
    else:
        raise AssertionError(mutation)

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_extract_broker_native_token_security_ctypes_source_fragment(
            source
        )

    assert side_effect_calls == []


