def test_broker_native_environment_ctypes_source_is_exact_cross_bound_and_dormant(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    abi_registry = module._launch_broker_native_abi_contract_facts_registry()
    inspection_fragment = (
        module._launch_broker_native_security_inspection_ctypes_source_fragment()
    )

    fragment = module._launch_broker_native_environment_ctypes_source_fragment()

    assert fragment.version == (
        "complete-suite-broker-native-environment-ctypes-source-fragment-v1"
    )
    assert fragment.implementation_id == "broker-native-core-v1"
    assert fragment.activation_state == "dormant-source-only"
    assert fragment.completeness_state == "environment-read-abi-only"
    assert fragment.abi_contract_facts_version == abi_registry.version
    assert fragment.abi_contract_facts_size == 17_337
    assert fragment.abi_contract_facts_sha256 == (
        "d3dabd196c134fca03f5459b73562c9f5a6e2f04d770e26be692480fe7969661"
    )
    assert (
        fragment.security_inspection_source_version == inspection_fragment.version
    )
    assert fragment.security_inspection_source_size == 5_526
    assert (
        fragment.security_inspection_source_sha256
        == inspection_fragment.source_sha256
    )
    assert fragment.class_names == (
        "_C6BrokerNativeCoreV1EnvironmentBindings",
    )
    assert fragment.function_names == (
        "_c6_broker_native_core_v1_assert_environment_abi",
        "_c6_broker_native_core_v1_bind_environment_apis",
    )
    assert type(fragment.source_bytes) is bytes
    assert fragment.source_bytes.startswith(
        b"_C6_BROKER_NATIVE_CORE_V1_ENVIRONMENT_ABI_FACTS_VERSION = "
    )
    assert fragment.source_bytes.endswith(b"\n")
    assert b"\r" not in fragment.source_bytes
    assert b"\x00" not in fragment.source_bytes
    assert b"C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN" not in (
        fragment.source_bytes
    )
    assert b"C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END" not in (
        fragment.source_bytes
    )
    assert abi_registry.version.encode("ascii") in fragment.source_bytes
    assert abi_registry.payload_sha256.encode("ascii") in fragment.source_bytes
    assert inspection_fragment.version.encode("ascii") in fragment.source_bytes
    assert inspection_fragment.source_sha256.encode("ascii") in fragment.source_bytes
    assert fragment.source_sha256 == sha256(fragment.source_bytes).hexdigest()
    assert not hasattr(fragment, "__dict__")
    with pytest.raises((AttributeError, FrozenInstanceError)):
        fragment.activation_state = "active"
    assert not (
        Path(module.__file__).parent / "complete_suite_control_plane.ps1"
    ).exists()
    assert side_effect_calls == []


def test_broker_native_environment_ctypes_source_has_exact_static_surface(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    source = module._launch_broker_native_environment_ctypes_source_fragment().source_bytes
    tree = ast.parse(source.decode("ascii", errors="strict"))

    assert not any(
        isinstance(node, (ast.Import, ast.ImportFrom))
        for node in ast.walk(tree)
    )
    assert tuple(
        node.name for node in tree.body if isinstance(node, ast.ClassDef)
    ) == ("_C6BrokerNativeCoreV1EnvironmentBindings",)
    assert tuple(
        node.name for node in tree.body if isinstance(node, ast.FunctionDef)
    ) == (
        "_c6_broker_native_core_v1_assert_environment_abi",
        "_c6_broker_native_core_v1_bind_environment_apis",
    )
    assert not any(
        isinstance(node, (ast.AsyncFunctionDef, ast.Await))
        for node in ast.walk(tree)
    )

    binder = next(
        node
        for node in tree.body
        if isinstance(node, ast.FunctionDef)
        and node.name == "_c6_broker_native_core_v1_bind_environment_apis"
    )
    win_dll_calls = tuple(
        node
        for node in ast.walk(binder)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
        and isinstance(node.func.value, ast.Name)
        and node.func.value.id == "ctypes"
        and node.func.attr == "WinDLL"
    )
    assert len(win_dll_calls) == 1
    assert len(win_dll_calls[0].args) == 1
    assert isinstance(win_dll_calls[0].args[0], ast.Constant)
    assert win_dll_calls[0].args[0].value == "kernel32.dll"
    assert len(win_dll_calls[0].keywords) == 1
    assert win_dll_calls[0].keywords[0].arg == "use_last_error"
    assert isinstance(win_dll_calls[0].keywords[0].value, ast.Constant)
    assert win_dll_calls[0].keywords[0].value.value is True
    bound_api_names = tuple(
        node.value.attr
        for node in binder.body
        if isinstance(node, ast.Assign)
        and isinstance(node.value, ast.Attribute)
        and isinstance(node.value.value, ast.Name)
        and node.value.value.id == "kernel32"
    )
    assert bound_api_names == ("GetEnvironmentVariableW",)
    assert source.count(b".argtypes = ") == 1
    assert source.count(b".restype = ") == 1
    assert not any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
        and node.func.attr == "GetEnvironmentVariableW"
        for node in ast.walk(tree)
    )
    assert not any(
        isinstance(node, ast.Call)
        for statement in tree.body
        for node in ast.walk(statement)
        if not isinstance(statement, (ast.ClassDef, ast.FunctionDef))
    )
    assert b"SetEnvironmentVariableW" not in source
    assert b"os.environ" not in source
    assert b"advapi32" not in source
    assert b"ntdll" not in source
    assert b"CreateProcessW" not in source
    assert b"ctypes.windll" not in source
    assert b"ctypes.CDLL" not in source
    assert b"ctypes.PyDLL" not in source
    assert b"getattr(" not in source
    assert side_effect_calls == []


