def test_broker_native_core_initializer_source_has_exact_static_surface(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    source = module._launch_broker_native_core_initializer_source_fragment().source_bytes
    tree = ast.parse(source.decode("ascii"))
    imports = tuple(
        node
        for node in ast.walk(tree)
        if isinstance(node, (ast.Import, ast.ImportFrom))
    )
    top_level_calls = tuple(
        node
        for statement in tree.body
        if not isinstance(statement, (ast.ClassDef, ast.FunctionDef))
        for node in ast.walk(statement)
        if isinstance(node, ast.Call)
    )
    class_names = tuple(
        node.name for node in tree.body if isinstance(node, ast.ClassDef)
    )
    function_names = tuple(
        node.name for node in tree.body if isinstance(node, ast.FunctionDef)
    )
    initialize = next(
        node
        for node in tree.body
        if isinstance(node, ast.FunctionDef)
        and node.name
        == "_c6_broker_native_core_v1_initialize_native_bindings"
    )
    call_names = tuple(
        node.func.id
        for node in ast.walk(initialize)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
    )
    expected_assertions = (
        "_c6_broker_native_core_v1_assert_process_creation_abi",
        "_c6_broker_native_core_v1_assert_job_abi",
        "_c6_broker_native_core_v1_assert_iocp_abi",
        "_c6_broker_native_core_v1_assert_pipe_io_abi",
        "_c6_broker_native_core_v1_assert_process_observation_abi",
        "_c6_broker_native_core_v1_assert_handle_inspection_abi",
        "_c6_broker_native_core_v1_assert_token_security_abi",
        "_c6_broker_native_core_v1_assert_security_inspection_abi",
        "_c6_broker_native_core_v1_assert_environment_abi",
    )
    expected_binders = tuple(
        name.replace("_assert_", "_bind_").replace("_abi", "_apis")
        for name in expected_assertions
    )

    assert imports == ()
    assert top_level_calls == ()
    assert class_names == ("_C6BrokerNativeCoreV1",)
    assert function_names == (
        "_c6_broker_native_core_v1_validate_descriptor_native_vector",
        "_c6_broker_native_core_v1_initialize_native_bindings",
    )
    assert all(name in call_names for name in expected_assertions)
    assert all(name in call_names for name in expected_binders)
    assert max(source.index(name.encode("ascii")) for name in expected_assertions) < min(
        source.index(name.encode("ascii")) for name in expected_binders
    )
    assert source.count(b"_C6_BROKER_NATIVE_CORE_V1_BINDING_CACHE = None") == 1
    assert b"global _C6_BROKER_NATIVE_CORE_V1_BINDING_CACHE" in source
    assert b"ctypes" not in source
    assert b"WinDLL" not in source
    assert b"CreateProcessW" not in source
    assert b"C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN" not in source
    assert b"C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END" not in source
    assert side_effect_calls == []


def test_broker_native_core_initializer_source_enforces_order_and_lazy_cache(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    source = module._launch_broker_native_core_initializer_source_fragment().source_bytes
    trace: list[str] = []

    class DraftNativeVector(tuple):
        __slots__ = ()

        def __new__(cls, contract: str, units: int, digest: str, text: str):
            return tuple.__new__(cls, (contract, units, digest, text))

        contract = property(lambda self: self[0])
        utf16_units = property(lambda self: self[1])
        utf16le_sha256 = property(lambda self: self[2])
        command_line = property(lambda self: self[3])

    def reject(reason: str) -> None:
        raise RuntimeError(reason)

    assertion_names = (
        "_c6_broker_native_core_v1_assert_process_creation_abi",
        "_c6_broker_native_core_v1_assert_job_abi",
        "_c6_broker_native_core_v1_assert_iocp_abi",
        "_c6_broker_native_core_v1_assert_pipe_io_abi",
        "_c6_broker_native_core_v1_assert_process_observation_abi",
        "_c6_broker_native_core_v1_assert_handle_inspection_abi",
        "_c6_broker_native_core_v1_assert_token_security_abi",
        "_c6_broker_native_core_v1_assert_security_inspection_abi",
        "_c6_broker_native_core_v1_assert_environment_abi",
    )
    binding_type_names = (
        "_C6BrokerNativeCoreV1ProcessCreationBindings",
        "_C6BrokerNativeCoreV1JobBindings",
        "_C6BrokerNativeCoreV1IocpBindings",
        "_C6BrokerNativeCoreV1PipeIoBindings",
        "_C6BrokerNativeCoreV1ProcessObservationBindings",
        "_C6BrokerNativeCoreV1HandleInspectionBindings",
        "_C6BrokerNativeCoreV1TokenSecurityBindings",
        "_C6BrokerNativeCoreV1SecurityInspectionBindings",
        "_C6BrokerNativeCoreV1EnvironmentBindings",
    )
    binder_names = tuple(
        name.replace("_assert_", "_bind_").replace("_abi", "_apis")
        for name in assertion_names
    )
    namespace: dict[str, object] = {
        "GUARDED_BOOTSTRAP_INVALID": "GUARDED_BOOTSTRAP_INVALID",
        "_reject": reject,
        "_C6BrokerNativeCoreDraftNativeVector": DraftNativeVector,
        "_C6_BROKER_NATIVE_CORE_DRAFT_VECTOR_CONTRACT": (
            "complete-suite-windows-native-vector-v1"
        ),
        "_C6_BROKER_NATIVE_CORE_DRAFT_MAX_COMMAND_LINE_UNITS": 30_000,
    }

    def make_assertion(name: str):
        def assertion() -> None:
            trace.append(name)

        return assertion

    def make_binder(name: str, binding_type: type):
        def binder() -> object:
            trace.append(name)
            return binding_type()

        return binder

    for name in assertion_names:
        namespace[name] = make_assertion(name)
    for name, type_name in zip(binder_names, binding_type_names, strict=True):
        binding_type = type(type_name, (), {})
        namespace[type_name] = binding_type
        namespace[name] = make_binder(name, binding_type)

    exec(compile(source, "<broker-native-core-initializer>", "exec"), namespace)
    vector = DraftNativeVector(
        "complete-suite-windows-native-vector-v1",
        7,
        "a" * 64,
        "x",
    )
    validated = namespace[
        "_c6_broker_native_core_v1_validate_descriptor_native_vector"
    ](
        vector,
        "complete-suite-windows-native-vector-v1",
        7,
        "a" * 64,
    )
    assert validated is vector
    assert trace == []

    initialize = namespace[
        "_c6_broker_native_core_v1_initialize_native_bindings"
    ]
    core = initialize()
    assert type(core).__name__ == "_C6BrokerNativeCoreV1"
    assert trace == [*assertion_names, *binder_names]
    trace.clear()
    assert initialize() is core
    assert trace == []
    with pytest.raises(AttributeError):
        core.process_creation = object()

    with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
        namespace[
            "_c6_broker_native_core_v1_validate_descriptor_native_vector"
        ](
            vector,
            "complete-suite-windows-native-vector-v1",
            8,
            "a" * 64,
        )
    namespace["_C6_BROKER_NATIVE_CORE_V1_BINDING_CACHE"] = object()
    with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
        initialize()
    assert trace == []
    assert side_effect_calls == []


@pytest.mark.parametrize(
    "mutation",
    (
        "composition-hash",
        "assertion-order",
        "binder-order",
        "missing-assertion",
        "missing-binder",
        "cache-preinitialized",
        "import",
        "top-level-call",
        "ctypes",
        "constructor-begin-marker",
        "constructor-end-marker",
        "bom",
        "cr",
        "nul",
        "missing-terminal-lf",
        "bytes-subclass",
        "bytearray",
    ),
)
def test_broker_native_core_initializer_source_extractor_rejects_mutants(
    mutation: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    source: object = (
        module._launch_broker_native_core_initializer_source_fragment().source_bytes
    )
    if mutation == "composition-hash":
        source = source.replace(
            b"7b63887c1052b68abe03dbf5a14e3b2c8407cbe7ad4a9b350d4ca7a23fae0019",
            b"0" * 64,
            1,
        )
    elif mutation == "assertion-order":
        first = b"_c6_broker_native_core_v1_assert_process_creation_abi()"
        second = b"_c6_broker_native_core_v1_assert_job_abi()"
        source = source.replace(first, b"__C6_SWAP__", 1)
        source = source.replace(second, first, 1)
        source = source.replace(b"__C6_SWAP__", second, 1)
    elif mutation == "binder-order":
        first = b"_c6_broker_native_core_v1_bind_process_creation_apis()"
        second = b"_c6_broker_native_core_v1_bind_job_apis()"
        source = source.replace(first, b"__C6_SWAP__", 1)
        source = source.replace(second, first, 1)
        source = source.replace(b"__C6_SWAP__", second, 1)
    elif mutation == "missing-assertion":
        source = source.replace(
            b"    _c6_broker_native_core_v1_assert_environment_abi()\n",
            b"",
            1,
        )
    elif mutation == "missing-binder":
        source = source.replace(
            b"    environment = _c6_broker_native_core_v1_bind_environment_apis()\n",
            b"    environment = None\n",
            1,
        )
    elif mutation == "cache-preinitialized":
        source = source.replace(
            b"_C6_BROKER_NATIVE_CORE_V1_BINDING_CACHE = None",
            b"_C6_BROKER_NATIVE_CORE_V1_BINDING_CACHE = object()",
            1,
        )
    elif mutation == "import":
        source = b"import os\n" + source
    elif mutation == "top-level-call":
        source += b"_c6_broker_native_core_v1_initialize_native_bindings()\n"
    elif mutation == "ctypes":
        source += b"ctypes.WinDLL('kernel32.dll', use_last_error=True)\n"
    elif mutation == "constructor-begin-marker":
        source += b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN\n"
    elif mutation == "constructor-end-marker":
        source += b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END\n"
    elif mutation == "bom":
        source = b"\xef\xbb\xbf" + source
    elif mutation == "cr":
        source = source.replace(b"\n", b"\r\n", 1)
    elif mutation == "nul":
        source = source.replace(b"\n", b"\x00\n", 1)
    elif mutation == "missing-terminal-lf":
        source = source[:-1]
    elif mutation == "bytes-subclass":

        class _BytesSubclass(bytes):
            pass

        source = _BytesSubclass(source)
    elif mutation == "bytearray":
        source = bytearray(source)
    else:
        raise AssertionError(mutation)

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_extract_broker_native_core_initializer_source_fragment(
            source
        )

    assert side_effect_calls == []


