def test_broker_native_pipe_security_source_builds_and_cleans_synthetically(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    fragments = (
        module._launch_broker_native_process_creation_ctypes_source_fragment(),
        module._launch_broker_native_job_ctypes_source_fragment(),
        module._launch_broker_native_iocp_ctypes_source_fragment(),
        module._launch_broker_native_pipe_io_ctypes_source_fragment(),
        module._launch_broker_native_process_observation_ctypes_source_fragment(),
        module._launch_broker_native_handle_inspection_ctypes_source_fragment(),
        module._launch_broker_native_token_security_ctypes_source_fragment(),
        module._launch_broker_native_security_inspection_ctypes_source_fragment(),
        module._launch_broker_native_environment_ctypes_source_fragment(),
        module._launch_broker_native_core_initializer_source_fragment(),
        module._launch_broker_native_supervisor_resources_source_fragment(),
        module._launch_broker_native_pipe_security_source_fragment(),
    )
    trace: list[object] = []
    sid_bytes = b"\x01\x01\x00\x00\x00\x00\x00\x05\x15\x00\x00\x00"

    def reject(reason: str) -> None:
        raise RuntimeError(reason)

    namespace: dict[str, object] = {
        "GUARDED_BOOTSTRAP_INVALID": "GUARDED_BOOTSTRAP_INVALID",
        "_reject": reject,
    }
    for fragment in fragments:
        exec(
            compile(fragment.source_bytes, "<broker-pipe-security-test>", "exec"),
            namespace,
        )

    class FakeProcessCreation:
        def close_handle(self, handle: int) -> int:
            trace.append(("close", handle))
            return 1

    class FakeProcessObservation:
        def get_current_process(self) -> int:
            trace.append(("current-process",))
            return 909

    class FakeTokenSecurity:
        fail_copy = False

        def open_process_token(
            self,
            process: int,
            desired_access: int,
            token_pointer: object,
        ) -> int:
            trace.append(("open-token", process, desired_access))
            ctypes.cast(token_pointer, ctypes.POINTER(ctypes.c_void_p))[0] = 303
            return 1

        def get_token_information(
            self,
            token: int,
            information_class: int,
            buffer: object,
            buffer_size: int,
            required_pointer: object,
        ) -> int:
            required = ctypes.cast(
                required_pointer,
                ctypes.POINTER(ctypes.wintypes.DWORD),
            )
            if buffer is None:
                trace.append(("query-token-size", token, information_class))
                required.contents.value = 32
                ctypes.set_last_error(122)
                return 0
            trace.append(
                ("query-token", token, information_class, buffer_size)
            )
            required.contents.value = 32
            token_address = ctypes.addressof(buffer)
            sid_address = token_address + 16
            ctypes.memmove(sid_address, sid_bytes, len(sid_bytes))
            token_user = ctypes.cast(
                buffer,
                ctypes.POINTER(
                    namespace["_C6BrokerNativeCoreV1SidAndAttributes"]
                ),
            ).contents
            token_user.Sid = sid_address
            token_user.Attributes = 0
            return 1

        def is_valid_sid(self, sid: int) -> int:
            trace.append(("valid-sid", sid))
            return 1

        def get_length_sid(self, sid: int) -> int:
            trace.append(("sid-length", sid))
            return len(sid_bytes)

        def copy_sid(self, size: int, destination: object, source: int) -> int:
            trace.append(("copy-sid", size))
            if self.fail_copy:
                return 0
            ctypes.memmove(destination, source, size)
            return 1

        def equal_sid(self, first: int, second: int) -> int:
            trace.append(("equal-sid", first, second))
            return int(
                ctypes.string_at(first, len(sid_bytes))
                == ctypes.string_at(second, len(sid_bytes))
            )

        def initialize_acl(
            self,
            acl: object,
            acl_size: int,
            revision: int,
        ) -> int:
            trace.append(("initialize-acl", acl_size, revision))
            return 1

        def add_access_allowed_ace_ex(
            self,
            acl: object,
            revision: int,
            ace_flags: int,
            access_mask: int,
            sid: int,
        ) -> int:
            trace.append(
                ("add-ace", revision, ace_flags, access_mask, sid)
            )
            return 1

        def initialize_security_descriptor(
            self,
            descriptor: object,
            revision: int,
        ) -> int:
            trace.append(("initialize-descriptor", revision))
            return 1

        def set_security_descriptor_owner(
            self,
            descriptor: object,
            owner: int,
            defaulted: bool,
        ) -> int:
            trace.append(("set-owner", owner, defaulted))
            return 1

        def set_security_descriptor_dacl(
            self,
            descriptor: object,
            present: bool,
            acl: object,
            defaulted: bool,
        ) -> int:
            trace.append(("set-dacl", present, defaulted))
            return 1

        def set_security_descriptor_control(
            self,
            descriptor: object,
            interest: int,
            control: int,
        ) -> int:
            trace.append(("set-control", interest, control))
            return 1

    token_security = FakeTokenSecurity()
    core = namespace["_C6BrokerNativeCoreV1"](
        FakeProcessCreation(),
        object(),
        object(),
        object(),
        FakeProcessObservation(),
        object(),
        token_security,
        object(),
        object(),
    )
    build = namespace[
        "_c6_broker_native_core_v1_build_current_user_pipe_security"
    ]

    read_security = build(core, 2_147_483_648)
    assert read_security.child_access == 2_147_483_648
    assert read_security.ace_access_mask == 1_179_785
    assert read_security.sid_size == len(sid_bytes)
    assert read_security.acl_size == 16 + len(sid_bytes)
    assert read_security.sid_buffer.raw == sid_bytes
    assert read_security.security_attributes.nLength == ctypes.sizeof(
        namespace["_C6BrokerNativeCoreV1SecurityAttributes"]
    )
    assert read_security.security_attributes.lpSecurityDescriptor == (
        ctypes.addressof(read_security.security_descriptor)
    )
    assert read_security.security_attributes.bInheritHandle == 0
    assert ("add-ace", 2, 0, 1_179_785, ctypes.addressof(read_security.sid_buffer)) in trace
    assert ("set-control", 4_096, 4_096) in trace
    assert trace.index(("close", 303)) < trace.index(("initialize-acl", 28, 2))

    trace.clear()
    write_security = build(core, 1_073_741_824)
    assert write_security.child_access == 1_073_741_824
    assert write_security.ace_access_mask == 1_179_926
    assert ("add-ace", 2, 0, 1_179_926, ctypes.addressof(write_security.sid_buffer)) in trace
    assert trace.count(("close", 303)) == 1

    trace.clear()
    for invalid_access in (0, True, 1_179_785, 1_179_926):
        with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
            build(core, invalid_access)
    assert trace == []

    token_security.fail_copy = True
    with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
        build(core, 2_147_483_648)
    assert trace[-1] == ("close", 303)
    assert trace.count(("close", 303)) == 1
    assert side_effect_calls == []


@pytest.mark.parametrize(
    "mutation",
    (
        "resources-hash",
        "read-mask",
        "write-mask",
        "ace-flags",
        "unprotected-dacl",
        "inheritable",
        "missing-token-close",
        "security-requery",
        "create-pipe",
        "import",
        "top-level-call",
        "constructor-begin-marker",
        "constructor-end-marker",
        "bom",
        "cr",
        "nul",
        "missing-terminal-lf",
        "bytes-subclass",
        "bytearray",
    ),
)
def test_broker_native_pipe_security_source_extractor_rejects_mutants(
    mutation: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    fragment = module._launch_broker_native_pipe_security_source_fragment()
    source: object = fragment.source_bytes
    if mutation == "resources-hash":
        source = source.replace(
            fragment.supervisor_resources_source_sha256.encode(),
            b"0" * 64,
            1,
        )
    elif mutation == "read-mask":
        source = source.replace(b"= 1179785", b"= 1179786", 1)
    elif mutation == "write-mask":
        source = source.replace(b"= 1179926", b"= 1179927", 1)
    elif mutation == "ace-flags":
        source = source.replace(b"EXACT_ACE_FLAGS = 0", b"EXACT_ACE_FLAGS = 1", 1)
    elif mutation == "unprotected-dacl":
        source = source.replace(b"SE_DACL_PROTECTED = 4096", b"SE_DACL_PROTECTED = 0", 1)
    elif mutation == "inheritable":
        source = source.replace(
            b"security_attributes.bInheritHandle = False",
            b"security_attributes.bInheritHandle = True",
            1,
        )
    elif mutation == "missing-token-close":
        source = source.replace(
            b"        _c6_broker_native_core_v1_close_supervisor_handle(\n"
            b"            core, token_handle.value\n"
            b"        )\n",
            b"",
            1,
        )
    elif mutation == "security-requery":
        source += b"core.security_inspection.GetSecurityInfo()\n"
    elif mutation == "create-pipe":
        source += b"core.pipe_io.CreateNamedPipeW()\n"
    elif mutation == "import":
        source = b"import os\n" + source
    elif mutation == "top-level-call":
        source += b"_c6_broker_native_core_v1_copy_current_user_sid(None)\n"
    elif mutation == "constructor-begin-marker":
        source += b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN\n"
    elif mutation == "constructor-end-marker":
        source += b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END\n"
    elif mutation == "bom":
        source = b"\xef\xbb\xbf" + source
    elif mutation == "cr":
        source = source.replace(b"\n", b"\r\n", 1)
    elif mutation == "nul":
        source = source.replace(b"\n", b"\x00\n", 1)
    elif mutation == "missing-terminal-lf":
        source = source[:-1]
    elif mutation == "bytes-subclass":

        class _BytesSubclass(bytes):
            pass

        source = _BytesSubclass(source)
    elif mutation == "bytearray":
        source = bytearray(source)
    else:
        raise AssertionError(mutation)

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_extract_broker_native_pipe_security_source_fragment(
            source
        )

    assert side_effect_calls == []


