    namespace: dict[str, object] = {
        "GUARDED_BOOTSTRAP_INVALID": "GUARDED_BOOTSTRAP_INVALID",
        "_reject": reject,
        "hashlib": hashlib,
        "json": json,
        "os": os,
    }
    for fragment in fragments:
        exec(
            compile(fragment.source_bytes, "<broker-endpoint-test>", "exec"),
            namespace,
        )

    next_server = 1_000
    next_child = 2_000

    def fake_security(core: object, child_access: int) -> object:
        trace.append(("security", child_access))
        sid_buffer = ctypes.create_string_buffer(8)
        acl_buffer = ctypes.create_string_buffer(24)
        descriptor = namespace["_C6BrokerNativeCoreV1SecurityDescriptor"]()
        attributes = namespace["_C6BrokerNativeCoreV1SecurityAttributes"]()
        attributes.nLength = ctypes.sizeof(type(attributes))
        attributes.lpSecurityDescriptor = ctypes.addressof(descriptor)
        attributes.bInheritHandle = False
        ace_mask = 1_179_785 if child_access == 2_147_483_648 else 1_179_926
        return namespace["_C6BrokerNativeCoreV1CurrentUserPipeSecurity"](
            child_access,
            ace_mask,
            8,
            24,
            sid_buffer,
            acl_buffer,
            descriptor,
            attributes,
        )

    namespace[
        "_c6_broker_native_core_v1_build_current_user_pipe_security"
    ] = fake_security

    class FakeProcessCreation:
        def close_handle(self, handle: int) -> int:
            trace.append(("close", handle))
            return 1

    class FakeIocp:
        def create_completion_port(
            self,
            file_handle: int,
            existing_port: int,
            completion_key: int,
            threads: int,
        ) -> int:
            trace.append(
                (
                    "associate",
                    file_handle,
                    existing_port,
                    completion_key,
                    threads,
                )
            )
            return existing_port

    class FakePipeIo:
        def create_named_pipe(
            self,
            name: str,
            open_mode: int,
            pipe_mode: int,
            maximum_instances: int,
            output_buffer: int,
            input_buffer: int,
            timeout: int,
            security_pointer: object,
        ) -> int:
            nonlocal next_server
            attributes = ctypes.cast(
                security_pointer,
                ctypes.POINTER(
                    namespace["_C6BrokerNativeCoreV1SecurityAttributes"]
                ),
            ).contents
            trace.append(
                (
                    "create-server",
                    name,
                    open_mode,
                    pipe_mode,
                    maximum_instances,
                    output_buffer,
                    input_buffer,
                    timeout,
                    attributes.bInheritHandle,
                )
            )
            handle = next_server
            next_server += 1
            return handle

        def connect_named_pipe(
            self,
            server_handle: int,
            overlapped_pointer: object,
        ) -> int:
            overlapped = ctypes.cast(
                overlapped_pointer,
                ctypes.POINTER(namespace["_C6BrokerNativeCoreV1Overlapped"]),
            ).contents
            trace.append(
                ("connect", server_handle, ctypes.addressof(overlapped))
            )
            ctypes.set_last_error(997)
            return 0

        def create_file(
            self,
            name: str,
            access: int,
            share_mode: int,
            security_pointer: object,
            disposition: int,
            flags: int,
            template: object,
        ) -> int:
            nonlocal next_child
            attributes = ctypes.cast(
                security_pointer,
                ctypes.POINTER(
                    namespace["_C6BrokerNativeCoreV1SecurityAttributes"]
                ),
            ).contents
            trace.append(
                (
                    "open-child",
                    name,
                    access,
                    share_mode,
                    disposition,
                    flags,
                    template,
                    attributes.bInheritHandle,
                )
            )
            handle = next_child
            next_child += 1
            return handle

    class FakeHandleInspection:
        def get_handle_information(
            self,
            handle: int,
            flags_pointer: object,
        ) -> int:
            flags = int(handle >= 2_000)
            ctypes.cast(
                flags_pointer,
                ctypes.POINTER(ctypes.wintypes.DWORD),
            ).contents.value = flags
            trace.append(("handle-flags", handle, flags))
            return 1

        def get_file_type(self, handle: int) -> int:
            trace.append(("file-type", handle, 3))
            return 3

    core = namespace["_C6BrokerNativeCoreV1"](
        FakeProcessCreation(),
        object(),
        FakeIocp(),
        FakePipeIo(),
        object(),
        FakeHandleInspection(),
        object(),
        object(),
        object(),
    )
    completion_port = namespace["_C6BrokerNativeCoreV1CompletionPort"](700)
    address_type = namespace[
        "_C6BrokerNativeCoreDraftInternalChannelAddress"
    ]
    prepare = namespace[
        "_c6_broker_native_core_v1_prepare_internal_channel_endpoint"
    ]
    token = "0123456789abcdef0123456789abcdef"
    expected = (
        ("descriptor", 1_074_266_114, 2_147_483_648),
        ("ack-status", 1_074_266_113, 1_073_741_824),
        ("go", 1_074_266_114, 2_147_483_648),
        ("broker-request", 1_074_266_113, 1_073_741_824),
        ("broker-response", 1_074_266_114, 2_147_483_648),
        ("stdin", 1_074_266_114, 2_147_483_648),
        ("stdout", 1_074_266_113, 1_073_741_824),
        ("stderr", 1_074_266_113, 1_073_741_824),
    )

    endpoints = tuple(
        prepare(core, completion_port, address_type(token, role))
        for role, _server_mode, _child_access in expected
    )

    assert tuple(endpoint.pipe_ordinal for endpoint in endpoints) == tuple(
        range(8)
    )
    assert tuple(endpoint.completion_key for endpoint in endpoints) == tuple(
        range(4_096, 4_104)
    )
    assert tuple(endpoint.server_open_mode for endpoint in endpoints) == tuple(
        row[1] for row in expected
    )
    assert tuple(endpoint.child_access for endpoint in endpoints) == tuple(
        row[2] for row in expected
    )
    assert tuple(endpoint.server_handle for endpoint in endpoints) == tuple(
        range(1_000, 1_008)
    )
    assert tuple(endpoint.child_handle for endpoint in endpoints) == tuple(
        range(2_000, 2_008)
    )
    assert all(endpoint.connect_completion_consumed is False for endpoint in endpoints)
    assert all(ctypes.sizeof(endpoint.connect_buffer) == 1 for endpoint in endpoints)
    assert all(
        ctypes.string_at(
            ctypes.byref(endpoint.connect_overlapped),
            ctypes.sizeof(endpoint.connect_overlapped),
        )
        == b"\x00" * 32
        for endpoint in endpoints
    )
    assert all(call[0] != "close" for call in trace)
    assert tuple(call[3] for call in trace if call[0] == "associate") == tuple(
        range(4_096, 4_104)
    )
    assert all(
        call[3:] == (8, 1, 65_536, 65_536, 0, 0)
        for call in trace
        if call[0] == "create-server"
    )
    assert all(
        call[3:] == (0, 3, 0, None, 1)
        for call in trace
        if call[0] == "open-child"
    )
    assert side_effect_calls == []


