_BROKER_NATIVE_CONNECT_DRAIN_ROLES = (
    "descriptor",
    "ack-status",
    "go",
    "broker-request",
    "broker-response",
    "stdin",
    "stdout",
    "stderr",
)


@lru_cache(maxsize=1)
def _broker_native_connect_drain_test_namespace(module: object) -> dict[str, object]:
    bootstrap_source = BOOTSTRAP_PATH.read_bytes()
    draft = (
        module._launch_extract_broker_native_control_plane_candidate_from_bootstrap_source(
            bootstrap_source
        )
    )
    fragments = (
        draft,
        module._launch_broker_native_process_creation_ctypes_source_fragment(),
        module._launch_broker_native_job_ctypes_source_fragment(),
        module._launch_broker_native_iocp_ctypes_source_fragment(),
        module._launch_broker_native_pipe_io_ctypes_source_fragment(),
        module._launch_broker_native_process_observation_ctypes_source_fragment(),
        module._launch_broker_native_handle_inspection_ctypes_source_fragment(),
        module._launch_broker_native_token_security_ctypes_source_fragment(),
        module._launch_broker_native_security_inspection_ctypes_source_fragment(),
        module._launch_broker_native_environment_ctypes_source_fragment(),
        module._launch_broker_native_core_initializer_source_fragment(),
        module._launch_broker_native_supervisor_resources_source_fragment(),
        module._launch_broker_native_pipe_security_source_fragment(),
        module._launch_broker_native_internal_channel_endpoint_source_fragment(),
        module._launch_broker_native_connect_completion_drain_source_fragment(),
    )

    def reject(reason: str) -> None:
        raise RuntimeError(reason)

    namespace: dict[str, object] = {
        "GUARDED_BOOTSTRAP_INVALID": "GUARDED_BOOTSTRAP_INVALID",
        "_reject": reject,
        "ctypes": ctypes,
        "hashlib": hashlib,
        "json": json,
        "os": os,
    }
    for fragment in fragments:
        exec(
            compile(fragment.source_bytes, "<broker-connect-drain-test>", "exec"),
            namespace,
        )
    return namespace


def _broker_native_connect_drain_endpoints(
    namespace: dict[str, object],
    ordinals: tuple[int, ...] = tuple(range(8)),
) -> tuple[object, ...]:
    token = "0123456789abcdef0123456789abcdef"
    address_type = namespace[
        "_C6BrokerNativeCoreDraftInternalChannelAddress"
    ]
    endpoint_type = namespace[
        "_C6BrokerNativeCoreV1InternalChannelEndpoint"
    ]
    security_type = namespace[
        "_C6BrokerNativeCoreV1CurrentUserPipeSecurity"
    ]
    descriptor_type = namespace[
        "_C6BrokerNativeCoreV1SecurityDescriptor"
    ]
    attributes_type = namespace[
        "_C6BrokerNativeCoreV1SecurityAttributes"
    ]
    overlapped_type = namespace["_C6BrokerNativeCoreV1Overlapped"]
    route = namespace[
        "_c6_broker_native_core_v1_exact_internal_channel_route"
    ]
    endpoints: list[object] = []
    for selected_ordinal in ordinals:
        address = address_type(
            token,
            _BROKER_NATIVE_CONNECT_DRAIN_ROLES[selected_ordinal],
        )
        (
            pipe_ordinal,
            server_open_mode,
            child_access,
            completion_key,
        ) = route(address)
        sid_buffer = ctypes.create_string_buffer(8)
        acl_buffer = ctypes.create_string_buffer(24)
        descriptor = descriptor_type()
        attributes = attributes_type()
        attributes.nLength = ctypes.sizeof(attributes_type)
        attributes.lpSecurityDescriptor = ctypes.addressof(descriptor)
        attributes.bInheritHandle = False
        pipe_security = security_type(
            child_access,
            1_179_785 if child_access == 2_147_483_648 else 1_179_926,
            8,
            24,
            sid_buffer,
            acl_buffer,
            descriptor,
            attributes,
        )
        endpoints.append(
            endpoint_type(
                address,
                pipe_ordinal,
                completion_key,
                1_000 + pipe_ordinal,
                2_000 + pipe_ordinal,
                server_open_mode,
                child_access,
                pipe_security,
                overlapped_type(),
                ctypes.create_string_buffer(1),
                False,
            )
        )
    return tuple(endpoints)


def _broker_native_connect_drain_core(
    namespace: dict[str, object],
    events: list[dict[str, object]],
    trace: list[object],
    *,
    query_result: int = 1,
    return_length_delta: int = 0,
    total_processes: int = 0,
    active_processes: int = 0,
    terminated_processes: int = 0,
) -> object:
    accounting_type = namespace[
        "_C6BrokerNativeCoreV1JobObjectBasicAccountingInformation"
    ]

    class FakeIocp:
        def get_queued_completion_status(
            self,
            completion_port: int,
            bytes_pointer: object,
            key_pointer: object,
            overlapped_pointer: object,
            timeout_ms: int,
        ) -> int:
            if not events:
                raise AssertionError("unexpected completion dequeue")
            event = events.pop(0)
            ctypes.cast(
                bytes_pointer,
                ctypes.POINTER(ctypes.wintypes.DWORD),
            ).contents.value = int(event.get("bytes_transferred", 0))
            ctypes.cast(
                key_pointer,
                ctypes.POINTER(ctypes.c_size_t),
            ).contents.value = int(event.get("completion_key", 0))
            ctypes.cast(
                overlapped_pointer,
                ctypes.POINTER(ctypes.c_void_p),
            ).contents.value = event.get("overlapped_address")
            ctypes.set_last_error(int(event.get("error_code", 0)))
            trace.append(
                (
                    "dequeue",
                    completion_port,
                    timeout_ms,
                    int(event.get("result", 0)),
                    int(event.get("completion_key", 0)),
                    event.get("overlapped_address"),
                    int(event.get("error_code", 0)),
                )
            )
            return int(event.get("result", 0))

    class FakeJob:
        def query_job_information(
            self,
            job_handle: int,
            information_class: int,
            information_pointer: object,
            information_size: int,
            return_length_pointer: object,
        ) -> int:
            accounting = ctypes.cast(
                information_pointer,
                ctypes.POINTER(accounting_type),
            ).contents
            accounting.TotalProcesses = total_processes
            accounting.ActiveProcesses = active_processes
            accounting.TotalTerminatedProcesses = terminated_processes
            ctypes.cast(
                return_length_pointer,
                ctypes.POINTER(ctypes.wintypes.DWORD),
            ).contents.value = information_size + return_length_delta
            trace.append(
                (
                    "query-job",
                    job_handle,
                    information_class,
                    information_size,
                )
            )
            return query_result

    return namespace["_C6BrokerNativeCoreV1"](
        object(),
        FakeJob(),
        FakeIocp(),
        object(),
        object(),
        object(),
        object(),
        object(),
        object(),
    )


def test_broker_native_connect_completion_drain_source_is_cross_bound_and_dormant(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    endpoint = (
        module._launch_broker_native_internal_channel_endpoint_source_fragment()
    )

    fragment = (
        module._launch_broker_native_connect_completion_drain_source_fragment()
    )

    assert fragment.version == (
        "complete-suite-broker-native-connect-completion-drain-source-fragment-v1"
    )
    assert fragment.implementation_id == "broker-native-core-v1"
    assert fragment.activation_state == "dormant-source-only"
    assert fragment.completeness_state == (
        "all-connect-packets-drained-preprocess-job-empty-only"
    )
    assert fragment.endpoint_source_version == endpoint.version
    assert fragment.endpoint_source_size == len(endpoint.source_bytes)
    assert fragment.endpoint_source_sha256 == endpoint.source_sha256
    assert fragment.class_names == (
        "_C6BrokerNativeCoreV1ConnectDrainResult",
    )
    assert fragment.function_names == (
        "_c6_broker_native_core_v1_validate_pending_connect_endpoints",
        "_c6_broker_native_core_v1_assert_prelaunch_job_empty",
        "_c6_broker_native_core_v1_copy_endpoint_connect_consumed",
        "_c6_broker_native_core_v1_drain_internal_channel_connect_completions",
    )
    assert type(fragment.source_bytes) is bytes
    assert len(fragment.source_bytes) == 10_480
    assert fragment.source_sha256 == (
        "d9ed7640eadc98f76264adb500a55e6db40d3f0900c1186fbece3602ce598f4b"
    )
    assert fragment.source_bytes.endswith(b"\n")
    assert b"\r" not in fragment.source_bytes
    assert fragment.source_sha256 == sha256(fragment.source_bytes).hexdigest()
    assert not hasattr(fragment, "__dict__")
    with pytest.raises((AttributeError, FrozenInstanceError)):
        fragment.activation_state = "active"
    assert not BOOTSTRAP_PATH.with_name(
        "complete_suite_control_plane.ps1"
    ).exists()
    assert side_effect_calls == []


