def test_broker_native_connect_completion_drain_consumes_all_roles_out_of_order(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_connect_drain_test_namespace(module)
    endpoints = _broker_native_connect_drain_endpoints(namespace)
    packet_order = (7, 0, 4, 2, 6, 1, 5, 3)
    events: list[dict[str, object]] = [
        {
            "result": 0,
            "error_code": 258,
            "completion_key": 0,
            "overlapped_address": None,
        }
    ]
    events.extend(
        {
            "result": 1,
            "completion_key": endpoints[index].completion_key,
            "overlapped_address": ctypes.addressof(
                endpoints[index].connect_overlapped
            ),
            "bytes_transferred": 0,
            "error_code": 0,
        }
        for index in packet_order
    )
    trace: list[object] = []
    core = _broker_native_connect_drain_core(
        namespace,
        events,
        trace,
    )
    completion_port = namespace["_C6BrokerNativeCoreV1CompletionPort"](700)
    owned_job = namespace["_C6BrokerNativeCoreV1OwnedJob"](
        "a" * 32,
        900,
        True,
    )
    now_values = iter(range(0, 9_000_000, 1_000_000))

    def monotonic_ns() -> int:
        value = next(now_values)
        trace.append(("clock", value))
        return value

    result = namespace[
        "_c6_broker_native_core_v1_drain_internal_channel_connect_completions"
    ](
        core,
        completion_port,
        owned_job,
        endpoints,
        1_000_000_000,
        monotonic_ns,
    )

    assert type(result) is namespace["_C6BrokerNativeCoreV1ConnectDrainResult"]
    assert result.packet_count == 8
    assert result.poll_timeout_count == 1
    assert len(result.endpoints) == 8
    assert all(
        endpoint.connect_completion_consumed is False for endpoint in endpoints
    )
    assert all(
        endpoint.connect_completion_consumed is True
        for endpoint in result.endpoints
    )
    assert tuple(
        endpoint.pipe_ordinal for endpoint in result.endpoints
    ) == tuple(range(8))
    assert all(
        retained.channel_address is original.channel_address
        and retained.pipe_security is original.pipe_security
        and retained.connect_overlapped is original.connect_overlapped
        and retained.connect_buffer is original.connect_buffer
        for original, retained in zip(endpoints, result.endpoints, strict=True)
    )
    assert len(tuple(item for item in trace if item[0] == "dequeue")) == 9
    assert len(tuple(item for item in trace if item[0] == "query-job")) == 9
    assert all(
        item[2] == 50 for item in trace if item[0] == "dequeue"
    )
    assert tuple(item[0] for item in trace) == (
        "clock",
        "dequeue",
        "query-job",
    ) * 9
    assert events == []
    assert side_effect_calls == []


def test_broker_native_connect_completion_drain_rejects_endpoint_collection_mutants(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
