def test_broker_native_connect_completion_drain_source_extractor_rejects_mutants(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    fragment = (
        module._launch_broker_native_connect_completion_drain_source_fragment()
    )
    mutations = (
        "endpoint-hash",
        "wait-timeout",
        "job-key",
        "pipe-key-base",
        "poll-quantum",
        "gqcs",
        "job-query",
        "endpoint-address",
        "timeout-condition",
        "completion-state",
        "import",
        "top-level-call",
        "read",
        "process-create",
        "constructor-begin-marker",
        "constructor-end-marker",
    )
    for mutation in mutations:
        source = fragment.source_bytes
        if mutation == "endpoint-hash":
            source = source.replace(
                fragment.endpoint_source_sha256.encode("ascii"),
                b"0" * 64,
                1,
            )
        elif mutation == "wait-timeout":
            source = source.replace(
                b"WAIT_TIMEOUT = 258",
                b"WAIT_TIMEOUT = 259",
                1,
            )
        elif mutation == "job-key":
            source = source.replace(
                b"JOB_IOCP_KEY = 1",
                b"JOB_IOCP_KEY = 2",
                1,
            )
        elif mutation == "pipe-key-base":
            source = source.replace(
                b"PIPE_IOCP_KEY_BASE = 4096",
                b"PIPE_IOCP_KEY_BASE = 4097",
                1,
            )
        elif mutation == "poll-quantum":
            source = source.replace(
                b"IOCP_POLL_QUANTUM_MS = 50",
                b"IOCP_POLL_QUANTUM_MS = 51",
                1,
            )
        elif mutation == "gqcs":
            source = source.replace(
                b"core.iocp.get_queued_completion_status(",
                b"core.iocp.cancel_io(",
                1,
            )
        elif mutation == "job-query":
            source = source.replace(
                b"core.job.query_job_information(",
                b"core.job.terminate_job(",
                1,
            )
        elif mutation == "endpoint-address":
            source = source.replace(
                b"ctypes.addressof(endpoint.connect_overlapped)",
                b"id(endpoint.connect_overlapped)",
                1,
            )
        elif mutation == "timeout-condition":
            source = source.replace(
                b"error_code == _C6_BROKER_NATIVE_CORE_V1_WAIT_TIMEOUT",
                b"error_code != _C6_BROKER_NATIVE_CORE_V1_WAIT_TIMEOUT",
                1,
            )
        elif mutation == "completion-state":
            source = source.replace(
                b"connect_completion_consumed=True",
                b"connect_completion_consumed=False",
                1,
            )
        elif mutation == "import":
            source = b"import os\n" + source
        elif mutation == "top-level-call":
            source += (
                b"_c6_broker_native_core_v1_assert_prelaunch_job_empty()\n"
            )
        elif mutation == "read":
            source += b"core.pipe_io.ReadFile()\n"
        elif mutation == "process-create":
            source += b"core.process_creation.CreateProcessW()\n"
        elif mutation == "constructor-begin-marker":
            source += (
                b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN\n"
            )
        elif mutation == "constructor-end-marker":
            source += (
                b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END\n"
            )
        assert source != fragment.source_bytes

        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ):
            module._launch_extract_broker_native_connect_completion_drain_source_fragment(
                source
            )
    assert side_effect_calls == []


