@pytest.mark.parametrize(
    (
        "api_result",
        "error_code",
        "role_permitted_terminal",
        "expected_classification",
        "expected_live",
        "immediate_ignored",
    ),
    (
        (1, 0, False, "live-await-packet", True, True),
        (0, 997, False, "live-await-packet", True, False),
        (0, 109, True, "immediate-eof", False, False),
        (0, 109, False, "immediate-terminal-error", False, False),
        (0, 5, True, "immediate-terminal-error", False, False),
    ),
)
def test_broker_native_iocp_operation_issue_read_transitions_are_exhaustive(
    api_result: int,
    error_code: int,
    role_permitted_terminal: bool,
    expected_classification: str,
    expected_live: bool,
    immediate_ignored: bool,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_iocp_issue_test_namespace(module)
    endpoint = _broker_native_connected_endpoints(namespace, (1,))[0]
    trace: list[object] = []
    core = _broker_native_iocp_issue_core(
        namespace,
        trace,
        read_result=api_result,
        read_error=error_code,
        read_immediate_bytes=4_294_967_295,
    )

    result = namespace["_c6_broker_native_core_v1_issue_pipe_read"](
        core,
        (),
        endpoint,
        65_536,
        0,
        role_permitted_terminal,
    )

    assert result.classification == expected_classification
    assert result.immediate_byte_count_ignored is immediate_ignored
    assert (result.live_operation is not None) is expected_live
    assert len(result.ledger) == int(expected_live)
    assert trace == [
        (
            "read",
            endpoint.server_handle,
            ctypes.addressof(result.live_operation.native_buffer)
            if expected_live
            else trace[0][2],
            65_536,
            ctypes.addressof(endpoint.connect_overlapped),
        )
    ]
    if expected_live:
        operation = result.live_operation
        assert operation.state == "LIVE_AWAIT_PACKET"
        assert operation.operation_kind == "read"
        assert operation.request_bytes == 65_536
        assert operation.operation_buffer_bytes == b"\x00" * 65_536
        assert operation.endpoint is endpoint
        assert result.error_code is None
    else:
        assert result.ledger == ()
        assert result.live_operation is None
        assert result.error_code == error_code
    assert ctypes.string_at(
        ctypes.byref(endpoint.connect_overlapped),
        ctypes.sizeof(endpoint.connect_overlapped),
    ) == b"\x00" * 32
    assert side_effect_calls == []


