def test_broker_native_iocp_operation_issue_write_retains_cursor_and_blocks_overlap(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_iocp_issue_test_namespace(module)
    first, second = _broker_native_connected_endpoints(namespace, (0, 2))
    payload = b"a" * 65_536 + b"tail"
    trace: list[object] = []
    core = _broker_native_iocp_issue_core(
        namespace,
        trace,
        write_result=1,
        write_error=0,
        write_immediate_bytes=1,
    )
    issue_write = namespace["_c6_broker_native_core_v1_issue_pipe_write"]

    first_result = issue_write(
        core,
        (),
        first,
        payload,
        0,
        len(payload),
        0,
    )

    operation = first_result.live_operation
    assert first_result.classification == "live-await-packet"
    assert first_result.immediate_byte_count_ignored is True
    assert operation.operation_kind == "write"
    assert operation.state == "LIVE_AWAIT_PACKET"
    assert operation.operation_buffer_bytes == b"a" * 65_536
    assert ctypes.string_at(
        ctypes.addressof(operation.native_buffer),
        operation.request_bytes,
    ) == operation.operation_buffer_bytes
    assert operation.write_cursor_start == 0
    assert operation.write_cursor_end == 65_536
    assert operation.request_bytes == 65_536
    assert operation.byte_cap == len(payload)
    assert operation.completed_wire_bytes == 0

    with pytest.raises(
        RuntimeError,
        match=r"^GUARDED_BOOTSTRAP_INVALID$",
    ):
        issue_write(
            core,
            first_result.ledger,
            first,
            payload,
            0,
            len(payload),
            0,
        )

    second_result = issue_write(
        core,
        first_result.ledger,
        second,
        b"tail",
        0,
        4,
        0,
    )
    assert len(second_result.ledger) == 2
    assert second_result.ledger[0] is operation
    assert second_result.live_operation.endpoint is second
    assert tuple(item[0] for item in trace) == ("write", "write")
    assert side_effect_calls == []


