@pytest.mark.parametrize(
    "failure_case",
    (
        "unconsumed-endpoint",
        "wrong-direction-read",
        "wrong-direction-write",
        "ledger-list",
        "duplicate-live-endpoint",
        "negative-cap",
        "completed-over-cap",
        "empty-write",
        "cursor-at-end",
        "payload-over-cap",
        "bool-cap",
        "invalid-api-result",
    ),
)
def test_broker_native_iocp_operation_issue_rejects_invalid_inputs(
    failure_case: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_iocp_issue_test_namespace(module)
    read_endpoint = _broker_native_connected_endpoints(namespace, (1,))[0]
    write_endpoint = _broker_native_connected_endpoints(namespace, (0,))[0]
    false_endpoint = _broker_native_connect_drain_endpoints(namespace, (1,))[0]
    trace: list[object] = []
    core = _broker_native_iocp_issue_core(
        namespace,
        trace,
        read_result=2 if failure_case == "invalid-api-result" else 1,
    )
    issue_read = namespace["_c6_broker_native_core_v1_issue_pipe_read"]
    issue_write = namespace["_c6_broker_native_core_v1_issue_pipe_write"]

    with pytest.raises(
        RuntimeError,
        match=r"^GUARDED_BOOTSTRAP_INVALID$",
    ):
        if failure_case == "unconsumed-endpoint":
            issue_read(core, (), false_endpoint, 1, 0, True)
        elif failure_case == "wrong-direction-read":
            issue_read(core, (), write_endpoint, 1, 0, True)
        elif failure_case == "wrong-direction-write":
            issue_write(core, (), read_endpoint, b"x", 0, 1, 0)
        elif failure_case == "ledger-list":
            issue_read(core, [], read_endpoint, 1, 0, True)
        elif failure_case == "duplicate-live-endpoint":
            live = issue_read(core, (), read_endpoint, 1, 0, True)
            issue_read(core, live.ledger, read_endpoint, 1, 0, True)
        elif failure_case == "negative-cap":
            issue_read(core, (), read_endpoint, -1, 0, True)
        elif failure_case == "completed-over-cap":
            issue_read(core, (), read_endpoint, 1, 2, True)
        elif failure_case == "empty-write":
            issue_write(core, (), write_endpoint, b"", 0, 0, 0)
        elif failure_case == "cursor-at-end":
            issue_write(core, (), write_endpoint, b"x", 1, 1, 0)
        elif failure_case == "payload-over-cap":
            issue_write(core, (), write_endpoint, b"xy", 0, 1, 0)
        elif failure_case == "bool-cap":
            issue_read(core, (), read_endpoint, True, 0, True)
        elif failure_case == "invalid-api-result":
            issue_read(core, (), read_endpoint, 1, 0, True)
    if failure_case == "duplicate-live-endpoint":
        assert len(trace) == 1
    elif failure_case == "invalid-api-result":
        assert len(trace) == 1
    else:
        assert trace == []
    assert side_effect_calls == []


