def test_broker_native_iocp_operation_issue_source_extractor_rejects_mutants(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    fragment = module._launch_broker_native_iocp_operation_issue_source_fragment()
    mutations = (
        (
            fragment.connect_drain_source_sha256.encode("ascii"),
            b"0" * 64,
        ),
        (b"IO_CHUNK_BYTES = 65536", b"IO_CHUNK_BYTES = 65535"),
        (b"ERROR_BROKEN_PIPE = 109", b"ERROR_BROKEN_PIPE = 110"),
        (b"ERROR_IO_PENDING = 997", b"ERROR_IO_PENDING = 996"),
        (b'"ISSUING"', b'"ISSUED"'),
        (b'"LIVE_AWAIT_PACKET"', b'"LIVE"'),
        (
            b"core.pipe_io.read_file(",
            b"core.pipe_io.write_file(",
        ),
        (
            b"core.pipe_io.write_file(",
            b"core.pipe_io.read_file(",
        ),
        (
            b"ctypes.memset(",
            b"ctypes.string_at(",
        ),
        (
            b"immediate_byte_count_ignored=True",
            b"immediate_byte_count_ignored=False",
        ),
    )
    sources = [
        fragment.source_bytes.replace(before, after, 1)
        for before, after in mutations
    ]
    sources.extend(
        (
            b"import os\n" + fragment.source_bytes,
            fragment.source_bytes + b"core.iocp.cancel_io()\n",
            fragment.source_bytes + b"core.process_creation.CreateProcessW()\n",
            fragment.source_bytes
            + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN\n",
            fragment.source_bytes
            + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END\n",
        )
    )
    assert all(source != fragment.source_bytes for source in sources)

    for source in sources:
        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ):
            module._launch_extract_broker_native_iocp_operation_issue_source_fragment(
                source
            )
    assert side_effect_calls == []


