def test_broker_native_iocp_operation_dispatch_source_is_cross_bound_and_dormant(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    issue = module._launch_broker_native_iocp_operation_issue_source_fragment()

    fragment = (
        module._launch_broker_native_iocp_operation_dispatch_source_fragment()
    )

    assert fragment.version == (
        "complete-suite-broker-native-iocp-operation-dispatch-source-fragment-v1"
    )
    assert fragment.implementation_id == "broker-native-core-v1"
    assert fragment.activation_state == "dormant-source-only"
    assert fragment.completeness_state == (
        "single-packet-classification-retirement-reconcile-callback-only"
    )
    assert fragment.operation_issue_source_version == issue.version
    assert fragment.operation_issue_source_size == len(issue.source_bytes)
    assert fragment.operation_issue_source_sha256 == issue.source_sha256
    assert fragment.class_names == (
        "_C6BrokerNativeCoreV1PipeDispatchResult",
    )
    assert fragment.function_names == (
        "_c6_broker_native_core_v1_assert_iocp_dispatch_facts",
        "_c6_broker_native_core_v1_retire_live_pipe_operation",
        "_c6_broker_native_core_v1_dispatch_one_iocp_completion",
    )
    assert type(fragment.source_bytes) is bytes
    assert len(fragment.source_bytes) == 18_342
    assert fragment.source_sha256 == (
        "6eaf5f9ba89cfdd9d9e8e58524497d380910c29c39515868fec70b33b13d9b73"
    )
    assert fragment.source_bytes.endswith(b"\n")
    assert b"\r" not in fragment.source_bytes
    assert fragment.source_sha256 == sha256(fragment.source_bytes).hexdigest()
    assert not hasattr(fragment, "__dict__")
    with pytest.raises((AttributeError, FrozenInstanceError)):
        fragment.activation_state = "active"
    assert not BOOTSTRAP_PATH.with_name(
        "complete_suite_control_plane.ps1"
    ).exists()
    assert side_effect_calls == []


def test_broker_native_iocp_operation_dispatch_source_has_exact_static_surface(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
