    source = (
        module._launch_broker_native_iocp_operation_dispatch_source_fragment()
        .source_bytes
    )
    tree = ast.parse(source.decode("ascii"))
    class_names = tuple(
        node.name for node in tree.body if isinstance(node, ast.ClassDef)
    )
    function_names = tuple(
        node.name for node in tree.body if isinstance(node, ast.FunctionDef)
    )
    imports = tuple(
        node
        for node in ast.walk(tree)
        if isinstance(node, (ast.Import, ast.ImportFrom))
    )
    top_level_calls = tuple(
        node
        for statement in tree.body
        for node in ast.walk(statement)
        if not isinstance(statement, (ast.ClassDef, ast.FunctionDef))
        and isinstance(node, ast.Call)
    )
    member_calls = tuple(
        node.func.attr
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
    )

    assert class_names == ("_C6BrokerNativeCoreV1PipeDispatchResult",)
    assert function_names == (
        "_c6_broker_native_core_v1_assert_iocp_dispatch_facts",
        "_c6_broker_native_core_v1_retire_live_pipe_operation",
        "_c6_broker_native_core_v1_dispatch_one_iocp_completion",
    )
    assert imports == ()
    assert top_level_calls == ()
    assert member_calls.count("get_queued_completion_status") == 1
    assert b"_C6_BROKER_NATIVE_CORE_V1_JOB_IOCP_KEY = 1" in source
    assert b"_C6_BROKER_NATIVE_CORE_V1_WAIT_TIMEOUT = 258" in source
    assert b"_C6_BROKER_NATIVE_CORE_V1_ERROR_BROKEN_PIPE = 109" in source
    assert b"_C6_BROKER_NATIVE_CORE_V1_ERROR_OPERATION_ABORTED = 995" in source
    assert b"_C6BrokerNativeCoreDraftIocpWaitWindow(" in source
    assert b"ctypes.cast(overlapped_pointer, ctypes.c_void_p).value" in source
    assert b"overlapped_pointer.contents" not in source
    assert b"read_file" not in source
    assert b"write_file" not in source
    assert b"cancel_io" not in source
    assert b"CreateProcessW" not in source
    assert b"SetFileCompletionNotificationModes" not in source
    assert b"WinDLL" not in source
    assert b"C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN" not in source
    assert b"C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END" not in source
    assert side_effect_calls == []


