def test_broker_native_iocp_operation_dispatch_handles_job_timeout_and_terminal_poll(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_iocp_dispatch_test_namespace(module)
    operation = _broker_native_live_read_operation(namespace)
    completion_port = namespace["_C6BrokerNativeCoreV1CompletionPort"](700)
    dispatch = namespace[
        "_c6_broker_native_core_v1_dispatch_one_iocp_completion"
    ]
    cases = (
        (
            {
                "result": 1,
                "bytes_transferred": 6,
                "completion_key": 1,
                "overlapped_address": 0xDEADBEEF,
                "error_code": 0,
            },
            "advisory-job-notification",
            True,
        ),
        (
            {
                "result": 0,
                "bytes_transferred": 0,
                "completion_key": 0,
                "overlapped_address": None,
                "error_code": 258,
            },
            "poll-timeout",
            True,
        ),
        (
            {
                "result": 0,
                "bytes_transferred": 0,
                "completion_key": 0,
                "overlapped_address": None,
                "error_code": 5,
            },
            "terminal-dispatcher-failure",
            False,
        ),
    )

    for event, expected_classification, expects_reconcile in cases:
        events = [event]
        trace: list[object] = []
        core = _broker_native_iocp_dispatch_core(namespace, events, trace)
        result = dispatch(
            core,
            completion_port,
            (operation,),
            50_000_001,
            False,
            lambda: trace.append(("reconcile",)),
        )
        assert result.classification == expected_classification
        assert result.ledger == (operation,)
        assert result.operation is None
        assert tuple(item[0] for item in trace) == (
            ("dequeue", "reconcile")
            if expects_reconcile
            else ("dequeue",)
        )
        if expected_classification == "advisory-job-notification":
            assert result.job_message_id == 6
            assert result.job_message_value == 0xDEADBEEF
            assert result.error_code is None
        elif expected_classification == "poll-timeout":
            assert result.poll_timeout is True
            assert result.error_code == 258
        else:
            assert result.poll_timeout is False
            assert result.error_code == 5
    assert side_effect_calls == []


@pytest.mark.parametrize(
    "failure_case",
    (
        "wrong-key",
        "unknown-overlapped",
        "null-success-pipe",
        "bytes-over-request",
        "invalid-result",
        "noncallable-reconcile",
        "nonpositive-remaining",
        "ledger-list",
    ),
)
def test_broker_native_iocp_operation_dispatch_rejects_malformed_input_or_packet(
    failure_case: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_iocp_dispatch_test_namespace(module)
    operation = _broker_native_live_read_operation(namespace)
    event: dict[str, object] = {
        "result": 1,
        "bytes_transferred": 1,
        "completion_key": operation.endpoint.completion_key,
        "overlapped_address": ctypes.addressof(
            operation.endpoint.connect_overlapped
        ),
        "error_code": 0,
    }
    if failure_case == "wrong-key":
        event["completion_key"] = operation.endpoint.completion_key + 1
    elif failure_case == "unknown-overlapped":
        event["overlapped_address"] = 0xABCDEF
    elif failure_case == "null-success-pipe":
        event["overlapped_address"] = None
    elif failure_case == "bytes-over-request":
        event["bytes_transferred"] = operation.request_bytes + 1
    elif failure_case == "invalid-result":
        event["result"] = 2
    events = [event]
    trace: list[object] = []
    core = _broker_native_iocp_dispatch_core(namespace, events, trace)
    completion_port = namespace["_C6BrokerNativeCoreV1CompletionPort"](700)
    reconcile: object = lambda: trace.append(("reconcile",))
    remaining = 1
    ledger: object = (operation,)
    if failure_case == "noncallable-reconcile":
        reconcile = None
    elif failure_case == "nonpositive-remaining":
        remaining = 0
    elif failure_case == "ledger-list":
        ledger = [operation]

    with pytest.raises(
        RuntimeError,
        match=r"^GUARDED_BOOTSTRAP_INVALID$",
    ):
        namespace[
            "_c6_broker_native_core_v1_dispatch_one_iocp_completion"
        ](
            core,
            completion_port,
            ledger,
            remaining,
            False,
            reconcile,
        )

    if failure_case in {
        "noncallable-reconcile",
        "nonpositive-remaining",
        "ledger-list",
    }:
        assert trace == []
        assert len(events) == 1
    elif failure_case == "invalid-result":
        assert tuple(item[0] for item in trace) == ("dequeue",)
    else:
        assert tuple(item[0] for item in trace) == (
            "dequeue",
            "reconcile",
        )
    assert side_effect_calls == []


