def test_broker_native_iocp_operation_dispatch_source_extractor_rejects_mutants(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    fragment = (
        module._launch_broker_native_iocp_operation_dispatch_source_fragment()
    )
    mutations = (
        (
            fragment.operation_issue_source_sha256.encode("ascii"),
            b"0" * 64,
        ),
        (b"JOB_IOCP_KEY = 1", b"JOB_IOCP_KEY = 2"),
        (b"WAIT_TIMEOUT = 258", b"WAIT_TIMEOUT = 259"),
        (b"ERROR_BROKEN_PIPE = 109", b"ERROR_BROKEN_PIPE = 110"),
        (
            b"ERROR_OPERATION_ABORTED = 995",
            b"ERROR_OPERATION_ABORTED = 996",
        ),
        (
            b"core.iocp.get_queued_completion_status(",
            b"core.iocp.cancel_io(",
        ),
        (
            b"ctypes.cast(overlapped_pointer, ctypes.c_void_p).value",
            b"overlapped_pointer.contents",
        ),
        (
            b'reconcile_after_dispatch()',
            b'pass',
        ),
        (
            b'"successful-zero-byte-write-failure"',
            b'"successful-write-completion"',
        ),
    )
    sources = [
        fragment.source_bytes.replace(before, after, 1)
        for before, after in mutations
    ]
    sources.extend(
        (
            b"import os\n" + fragment.source_bytes,
            fragment.source_bytes + b"core.pipe_io.read_file()\n",
            fragment.source_bytes + b"core.process_creation.CreateProcessW()\n",
            fragment.source_bytes
            + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN\n",
            fragment.source_bytes
            + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END\n",
        )
    )
    assert all(source != fragment.source_bytes for source in sources)

    for source in sources:
        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ):
            module._launch_extract_broker_native_iocp_operation_dispatch_source_fragment(
                source
            )
    assert side_effect_calls == []


