@lru_cache(maxsize=1)
def _broker_native_iocp_cancel_test_namespace(
    module: object,
) -> dict[str, object]:
    namespace = dict(_broker_native_iocp_dispatch_test_namespace(module))
    fragment = (
        module._launch_broker_native_iocp_operation_cancel_source_fragment()
    )
    exec(
        compile(fragment.source_bytes, "<broker-iocp-cancel-test>", "exec"),
        namespace,
    )
    return namespace


def _broker_native_iocp_cancel_core(
    namespace: dict[str, object],
    outcomes: list[dict[str, int]],
    trace: list[object],
) -> object:
    class FakeIocp:
        def cancel_io(
            self,
            handle: int,
            overlapped_pointer: object,
        ) -> int:
            if not outcomes:
                raise AssertionError("unexpected cancellation request")
            outcome = outcomes.pop(0)
            result = int(outcome["result"])
            error_code = int(outcome["error_code"])
            trace.append(
                (
                    "cancel",
                    handle,
                    ctypes.cast(
                        overlapped_pointer,
                        ctypes.c_void_p,
                    ).value,
                    result,
                    error_code,
                )
            )
            ctypes.set_last_error(error_code)
            return result

    return namespace["_C6BrokerNativeCoreV1"](
        object(),
        object(),
        FakeIocp(),
        object(),
        object(),
        object(),
        object(),
        object(),
        object(),
    )


def test_broker_native_iocp_operation_cancel_source_is_cross_bound_and_dormant(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    dispatch = (
        module._launch_broker_native_iocp_operation_dispatch_source_fragment()
    )

    fragment = module._launch_broker_native_iocp_operation_cancel_source_fragment()

    assert fragment.version == (
        "complete-suite-broker-native-iocp-operation-cancel-source-fragment-v1"
    )
    assert fragment.implementation_id == "broker-native-core-v1"
    assert fragment.activation_state == "dormant-source-only"
    assert fragment.completeness_state == (
        "failure-sequence-cancel-requests-without-retirement-only"
    )
    assert fragment.operation_dispatch_source_version == dispatch.version
    assert fragment.operation_dispatch_source_size == len(dispatch.source_bytes)
    assert fragment.operation_dispatch_source_sha256 == dispatch.source_sha256
    assert fragment.class_names == (
        "_C6BrokerNativeCoreV1PipeCancellationRequestResult",
    )
    assert fragment.function_names == (
        "_c6_broker_native_core_v1_assert_iocp_cancel_request_facts",
        "_c6_broker_native_core_v1_request_live_pipe_operation_cancellations",
    )
    assert type(fragment.source_bytes) is bytes
    assert len(fragment.source_bytes) == 6_021
    assert fragment.source_sha256 == (
        "835841d0ddf680e0deed7ff3b77b43bc5441f1b4be81899b4317b8815f0173c9"
    )
    assert fragment.source_bytes.endswith(b"\n")
    assert b"\r" not in fragment.source_bytes
