def test_broker_native_iocp_operation_cancel_source_extractor_rejects_mutants(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    fragment = module._launch_broker_native_iocp_operation_cancel_source_fragment()
    mutations = (
        (
            fragment.operation_dispatch_source_sha256.encode("ascii"),
            b"0" * 64,
        ),
        (b"ERROR_NOT_FOUND = 1168", b"ERROR_NOT_FOUND = 1169"),
        (b"core.iocp.cancel_io(", b"core.iocp.get_queued_completion_status("),
        (
            b"ctypes.byref(operation.endpoint.connect_overlapped)",
            b"None",
        ),
        (b'"error-not-found"', b'"failed"'),
    )
    sources = [
        fragment.source_bytes.replace(before, after, 1)
        for before, after in mutations
    ]
    sources.extend(
        (
            b"import os\n" + fragment.source_bytes,
            fragment.source_bytes + b"core.pipe_io.read_file()\n",
            fragment.source_bytes + b"core.process_creation.CreateProcessW()\n",
            fragment.source_bytes
            + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN\n",
            fragment.source_bytes
            + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END\n",
        )
    )
    assert all(source != fragment.source_bytes for source in sources)

    for source in sources:
        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ):
            module._launch_extract_broker_native_iocp_operation_cancel_source_fragment(
                source
            )
    assert side_effect_calls == []


