def _broker_native_iocp_writer_close_case(
    namespace: dict[str, object],
) -> tuple[tuple[object, ...], object, object, object, object]:
    prepared_endpoints = _broker_native_connect_drain_endpoints(
        namespace,
        tuple(range(8)),
    )
    connect_events = [
        {
            "result": 1,
            "completion_key": endpoint.completion_key,
            "overlapped_address": ctypes.addressof(
                endpoint.connect_overlapped
            ),
            "bytes_transferred": 0,
            "error_code": 0,
        }
        for endpoint in prepared_endpoints
    ]
    connect_result = namespace[
        "_c6_broker_native_core_v1_drain_internal_channel_connect_completions"
    ](
        _broker_native_connect_drain_core(namespace, connect_events, []),
        namespace["_C6BrokerNativeCoreV1CompletionPort"](700),
        namespace["_C6BrokerNativeCoreV1OwnedJob"](
            "b" * 32,
            900,
            True,
        ),
        prepared_endpoints,
        1_000_000_000,
        iter(range(0, 9_000_000, 1_000_000)).__next__,
    )
    endpoints = connect_result.endpoints
    core = _broker_native_iocp_issue_core(
        namespace,
        [],
        read_result=0,
        read_error=997,
        write_result=0,
        write_error=997,
    )
    write_operation = namespace[
        "_c6_broker_native_core_v1_issue_pipe_write"
    ](
        core,
        (),
        endpoints[0],
        b"pending-writer",
        0,
        14,
        0,
    ).live_operation
    read_operation = namespace[
        "_c6_broker_native_core_v1_issue_pipe_read"
    ](
        core,
        (write_operation,),
        endpoints[1],
        65_536,
        0,
        True,
    ).live_operation
    frozen_ledger = (write_operation, read_operation)
    cancellation_result = namespace[
        "_c6_broker_native_core_v1_request_live_pipe_operation_cancellations"
    ](
        _broker_native_iocp_cancel_core(
            namespace,
            [
                {"result": 1, "error_code": 0},
                {"result": 0, "error_code": 1168},
            ],
            [],
        ),
        frozen_ledger,
        True,
        True,
    )
    return (
        prepared_endpoints,
        connect_result,
        cancellation_result,
        write_operation,
        read_operation,
    )


def _broker_native_iocp_writer_close_retire_write(
    namespace: dict[str, object],
    cancellation_result: object,
    write_operation: object,
) -> object:
    event = {
        "result": 1,
        "error_code": 0,
        "bytes_transferred": write_operation.request_bytes,
        "completion_key": write_operation.endpoint.completion_key,
        "overlapped_address": ctypes.addressof(
            write_operation.endpoint.connect_overlapped
        ),
    }
    return namespace[
        "_c6_broker_native_core_v1_dispatch_one_iocp_completion"
    ](
        _broker_native_iocp_dispatch_core(namespace, [event], []),
        namespace["_C6BrokerNativeCoreV1CompletionPort"](701),
        cancellation_result.ledger,
        1_000_000_000,
        True,
        lambda: None,
    )


