def _broker_native_iocp_failure_grace_case(
    namespace: dict[str, object],
    *,
    include_live_read: bool = True,
) -> tuple[object, object | None, object, object]:
    prepared_endpoints = _broker_native_connect_drain_endpoints(
        namespace,
        (5, 6, 7),
    )
    connect_events = [
        {
            "result": 1,
            "completion_key": endpoint.completion_key,
            "overlapped_address": ctypes.addressof(
                endpoint.connect_overlapped
            ),
            "bytes_transferred": 0,
            "error_code": 0,
        }
        for endpoint in prepared_endpoints
    ]
    connect_result = namespace[
        "_c6_broker_native_core_v1_drain_internal_channel_connect_completions"
    ](
        _broker_native_connect_drain_core(namespace, connect_events, []),
        namespace["_C6BrokerNativeCoreV1CompletionPort"](700),
        namespace["_C6BrokerNativeCoreV1OwnedJob"](
            "c" * 32,
            899,
            True,
        ),
        prepared_endpoints,
        1_000_000_000,
        iter(range(0, 4_000_000, 1_000_000)).__next__,
    )
    operation = None
    frozen_ledger = ()
    cancellation_outcomes: list[dict[str, int]] = []
    if include_live_read:
        endpoint = connect_result.endpoints[1]
        operation = namespace[
            "_c6_broker_native_core_v1_issue_pipe_read"
        ](
            _broker_native_iocp_issue_core(
                namespace,
                [],
                read_result=0,
                read_error=997,
            ),
            (),
            endpoint,
            65_536,
            0,
            True,
        ).live_operation
        frozen_ledger = (operation,)
        cancellation_outcomes.append({"result": 1, "error_code": 0})
    cancellation_result = namespace[
        "_c6_broker_native_core_v1_request_live_pipe_operation_cancellations"
    ](
        _broker_native_iocp_cancel_core(
            namespace,
            cancellation_outcomes,
            [],
        ),
        frozen_ledger,
        True,
        True,
    )
    writer_close_result = namespace[
        "_c6_broker_native_core_v1_classify_failure_step_4_writer_close_eligibility"
    ](
        "native-leaf",
        prepared_endpoints,
        connect_result,
        cancellation_result,
        (),
        True,
        4,
    )
    completion_port = namespace[
        "_C6BrokerNativeCoreV1CompletionPort"
    ](900)
    owned_job = namespace["_C6BrokerNativeCoreV1OwnedJob"](
        "a" * 32,
        901,
        True,
    )
    return writer_close_result, operation, completion_port, owned_job


