def _broker_native_iocp_failure_cleanup_resources(
    namespace: dict[str, object],
    core: object,
    *,
    include_live_read: bool = False,
    monotonic_ns: object | None = None,
) -> tuple[
    object,
    object,
    tuple[object, ...],
    tuple[object, ...],
]:
    writer_close_result, _operation, completion_port, associated_job = (
        _broker_native_iocp_failure_grace_case(
            namespace,
            include_live_read=include_live_read,
        )
    )
    retained_process_type = namespace[
        "_C6BrokerNativeCoreV1RetainedProcessResource"
    ]
    job_resource_type = namespace[
        "_C6BrokerNativeCoreV1OwnedJobResource"
    ]
    owned_job_type = namespace["_C6BrokerNativeCoreV1OwnedJob"]
    associated_job_id = associated_job.logical_job_id
    tier_job = owned_job_type("b" * 32, 904, False)
    leaf_job = owned_job_type("d" * 32, 905, False)
    retained_processes = (
        retained_process_type(
            902,
            101,
            10_001,
            (associated_job_id, tier_job.logical_job_id),
        ),
        retained_process_type(
            903,
            102,
            10_002,
            (
                associated_job_id,
                tier_job.logical_job_id,
                leaf_job.logical_job_id,
            ),
        ),
    )
    job_resources = (
        job_resource_type(
            associated_job,
            "J1",
            None,
            "root-broker",
        ),
        job_resource_type(
            tier_job,
            "T",
            associated_job_id,
            "root-broker",
        ),
        job_resource_type(
            leaf_job,
            "Ln",
            tier_job.logical_job_id,
            "root-broker",
        ),
    )
    state = namespace[
        "_c6_broker_native_core_v1_begin_failure_cleanup_state"
    ](core, (lambda: 0) if monotonic_ns is None else monotonic_ns)
    namespace[
        "_c6_broker_native_core_v1_register_failure_cleanup_completion_port"
    ](state, completion_port)
    for prepared_endpoint in writer_close_result.prepared_endpoints:
        namespace[
            "_c6_broker_native_core_v1_register_failure_cleanup_endpoint"
        ](state, prepared_endpoint)
    for job_resource in job_resources:
        namespace[
            "_c6_broker_native_core_v1_register_failure_cleanup_owned_job"
        ](state, job_resource)
    for retained_process in retained_processes:
        namespace[
            "_c6_broker_native_core_v1_register_failure_cleanup_retained_process"
        ](state, retained_process)
    manifest = namespace[
        "_c6_broker_native_core_v1_freeze_failure_cleanup_manifest"
    ](
        state,
        writer_close_result,
    )
    return state, manifest, retained_processes, job_resources


def _broker_native_iocp_failure_cleanup_poll_core(
    namespace: dict[str, object],
    process_outcomes: dict[int, dict[str, object]],
    job_outcomes: dict[int, dict[str, object]],
    trace: list[object],
    *,
    events: list[dict[str, object]] | None = None,
    close_trace: list[object] | None = None,
    close_failure_handle: int | None = None,
    close_binding_outcomes: dict[int, object] | None = None,
    close_observer: object | None = None,
) -> object:
    def next_value(
        outcome: dict[str, object],
        key: str,
        default: object,
    ) -> object:
        value = outcome.get(key, default)
        if type(value) is list:
            if not value:
                raise AssertionError(f"exhausted fake outcome {key!r}")
            return value.pop(0)
        return value

    class FakeProcessObservation:
        def wait_for_single_object(
            self,
            handle: int,
            timeout_ms: int,
        ) -> object:
            outcome = process_outcomes[handle]
            trace.append(("wait", handle, timeout_ms))
            ctypes.set_last_error(
                int(next_value(outcome, "wait_error", 0))
            )
            return next_value(outcome, "wait_result", 0)

        def get_exit_code_process(
            self,
            handle: int,
            exit_code_pointer: object,
        ) -> object:
            outcome = process_outcomes[handle]
            trace.append(("exit", handle))
            exit_result = next_value(outcome, "exit_result", 1)
            if exit_result == 1:
                ctypes.cast(
                    exit_code_pointer,
                    ctypes.POINTER(ctypes.wintypes.DWORD),
                ).contents.value = int(
                    next_value(outcome, "exit_code", 0)
                )
            ctypes.set_last_error(
                int(next_value(outcome, "exit_error", 0))
            )
            return exit_result

    class FakeJob:
        def query_job_information(
            self,
            handle: int,
            information_class: int,
            information_pointer: object,
            information_size: int,
            return_length_pointer: object,
        ) -> object:
            outcome = job_outcomes[handle]
            return_length = ctypes.cast(
                return_length_pointer,
                ctypes.POINTER(ctypes.wintypes.DWORD),
            ).contents
            if information_class == 1:
                trace.append(("job-accounting", handle))
                result = next_value(outcome, "accounting_result", 1)
                ctypes.set_last_error(
                    int(next_value(outcome, "accounting_error", 0))
                )
                if result == 1:
                    accounting_type = namespace[
                        "_C6BrokerNativeCoreV1JobObjectBasicAccountingInformation"
                    ]
                    accounting = ctypes.cast(
                        information_pointer,
                        ctypes.POINTER(accounting_type),
                    ).contents
                    accounting.TotalProcesses = int(
                        next_value(outcome, "total_processes", 0)
                    )
                    accounting.ActiveProcesses = int(
                        next_value(outcome, "active_processes", 0)
                    )
                    return_length.value = int(
                        next_value(
                            outcome,
                            "accounting_return_length",
                            ctypes.sizeof(accounting_type),
                        )
                    )
                return result
            if information_class != 3:
                raise AssertionError(
                    f"unexpected Job information class {information_class!r}"
                )
            trace.append(("job-process-ids", handle))
            result = next_value(
                outcome,
                "process_id_list_result",
                1,
            )
            ctypes.set_last_error(
                int(next_value(outcome, "process_id_list_error", 0))
            )
            if result == 1:
                process_ids = tuple(
                    next_value(outcome, "process_ids", ())
                )
                header_type = namespace[
                    "_C6BrokerNativeCoreV1JobObjectBasicProcessIdListHeader"
                ]
                header_size = ctypes.sizeof(header_type)
                required_size = (
                    header_size
                    + len(process_ids) * ctypes.sizeof(ctypes.c_size_t)
                )
                if required_size > information_size:
                    raise AssertionError("fake process-ID list exceeds buffer")
                information_address = ctypes.cast(
                    information_pointer,
                    ctypes.c_void_p,
                ).value
                assert information_address is not None
                header = header_type.from_address(information_address)
                header.NumberOfAssignedProcesses = int(
                    next_value(
                        outcome,
                        "assigned_processes",
                        len(process_ids),
                    )
                )
                header.NumberOfProcessIdsInList = int(
                    next_value(
                        outcome,
                        "listed_process_count",
                        len(process_ids),
                    )
                )
                if process_ids:
                    process_id_array_type = ctypes.c_size_t * len(process_ids)
                    process_id_array = process_id_array_type.from_address(
                        information_address + header_size
                    )
                    for index, process_id in enumerate(process_ids):
                        process_id_array[index] = int(process_id)
                return_length.value = int(
                    next_value(
                        outcome,
                        "process_id_list_return_length",
                        required_size,
                    )
                )
            return result

    core = _broker_native_iocp_dispatch_core(
        namespace,
        [] if events is None else events,
        trace,
        close_trace=close_trace,
        close_failure_handle=close_failure_handle,
        close_binding_outcomes=close_binding_outcomes,
        job_bindings=FakeJob(),
        process_observation_bindings=FakeProcessObservation(),
    )
    if close_observer is None:
        return core

    original_process_creation = core.process_creation

    class ObservedProcessCreation:
        def close_handle(self, handle: int) -> object:
            close_observer(handle)
            return original_process_creation.close_handle(handle)

    return namespace["_C6BrokerNativeCoreV1"](
        ObservedProcessCreation(),
        core.job,
        core.iocp,
        core.pipe_io,
        core.process_observation,
        core.handle_inspection,
        core.token_security,
        core.security_inspection,
        core.environment,
    )


