def _broker_native_iocp_failure_cleanup_acquisition_core(
    namespace: dict[str, object],
    trace: list[object],
    *,
    observed_pid: int = 101,
    observed_creation_time_100ns: int = 10_001,
    membership_by_job_handle: dict[int, bool] | None = None,
) -> object:
    class FakeProcessCreation:
        def close_handle(self, handle: int) -> int:
            trace.append(("close-handle", handle))
            return 1

    class FakeJob:
        def is_process_in_job(
            self,
            process_handle: int,
            job_handle: int,
            membership_pointer: object,
        ) -> int:
            trace.append(
                ("is-process-in-job", process_handle, job_handle)
            )
            membership = True
            if membership_by_job_handle is not None:
                membership = membership_by_job_handle[job_handle]
            ctypes.cast(
                membership_pointer,
                ctypes.POINTER(ctypes.wintypes.BOOL),
            ).contents.value = int(membership)
            ctypes.set_last_error(0)
            return 1

    class FakeProcessObservation:
        def get_process_id(self, process_handle: int) -> int:
            trace.append(("get-process-id", process_handle))
            ctypes.set_last_error(0)
            return observed_pid

        def get_process_times(
            self,
            process_handle: int,
            creation_time_pointer: object,
            exit_time_pointer: object,
            kernel_time_pointer: object,
            user_time_pointer: object,
        ) -> int:
            trace.append(("get-process-times", process_handle))
            file_time_type = namespace[
                "_C6BrokerNativeCoreV1FileTime"
            ]
            creation_time = ctypes.cast(
                creation_time_pointer,
                ctypes.POINTER(file_time_type),
            ).contents
            creation_time.dwLowDateTime = (
                observed_creation_time_100ns & 0xFFFFFFFF
            )
            creation_time.dwHighDateTime = (
                observed_creation_time_100ns >> 32
            )
            ctypes.set_last_error(0)
            return 1

    return namespace["_C6BrokerNativeCoreV1"](
        FakeProcessCreation(),
        FakeJob(),
        object(),
        object(),
        FakeProcessObservation(),
        object(),
        object(),
        object(),
        object(),
    )


