        "_c6_broker_native_core_v1_acquire_and_register_completion_port",
        "_c6_broker_native_core_v1_prepare_and_register_internal_channel_endpoint",
        "_c6_broker_native_core_v1_create_and_register_owned_job",
        "_c6_broker_native_core_v1_verify_and_register_retained_process",
