def test_broker_native_iocp_failure_cleanup_acquisition_journals_exact_returned_objects_and_verified_process(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = (
        _broker_native_iocp_failure_cleanup_acquisition_test_namespace(
            module
        )
    )
    trace: list[object] = []
    core = _broker_native_iocp_failure_cleanup_acquisition_core(
        namespace,
        trace,
    )
    clock = lambda: 123
    completion_port = namespace[
        "_C6BrokerNativeCoreV1CompletionPort"
    ](900)
    prepared_endpoint = _broker_native_connect_drain_endpoints(
        namespace,
        (5,),
    )[0]
    owned_job_type = namespace["_C6BrokerNativeCoreV1OwnedJob"]
    associated_job = owned_job_type("a" * 32, 901, True)
    inner_job = owned_job_type("b" * 32, 904, False)

    def create_completion_port(actual_core: object) -> object:
        trace.append(("create-completion-port", actual_core))
        assert actual_core is core
        return completion_port

    def prepare_endpoint(
        actual_core: object,
        actual_port: object,
        channel_address: object,
    ) -> object:
        trace.append(("prepare-endpoint", actual_port, channel_address))
        assert actual_core is core
        assert actual_port is completion_port
        assert channel_address is prepared_endpoint.channel_address
        return prepared_endpoint

    jobs = iter((associated_job, inner_job))

    def create_owned_job(
        actual_core: object,
        logical_job_id: str,
        actual_port: object,
        associate_completion: bool,
    ) -> object:
        job = next(jobs)
        trace.append(
            (
                "create-owned-job",
                logical_job_id,
                actual_port,
                associate_completion,
            )
        )
        assert actual_core is core
        assert logical_job_id == job.logical_job_id
        return job

    monkeypatch.setitem(
        namespace,
        "_c6_broker_native_core_v1_create_completion_port",
        create_completion_port,
    )
    monkeypatch.setitem(
        namespace,
        "_c6_broker_native_core_v1_prepare_internal_channel_endpoint",
        prepare_endpoint,
    )
    monkeypatch.setitem(
        namespace,
        "_c6_broker_native_core_v1_create_owned_job",
        create_owned_job,
    )

    authority = namespace[
        "_c6_broker_native_core_v1_begin_failure_cleanup_attempt"
    ](core, clock)
    acquired_port = namespace[
        "_c6_broker_native_core_v1_acquire_and_register_completion_port"
    ](authority)
    acquired_endpoint = namespace[
        "_c6_broker_native_core_v1_prepare_and_register_internal_channel_endpoint"
    ](
        authority,
        acquired_port,
        prepared_endpoint.channel_address,
    )
    associated_resource = namespace[
        "_c6_broker_native_core_v1_create_and_register_owned_job"
    ](
        authority,
        associated_job.logical_job_id,
        acquired_port,
        True,
        "J1",
        None,
        "root-broker",
    )
    inner_resource = namespace[
        "_c6_broker_native_core_v1_create_and_register_owned_job"
    ](
        authority,
        inner_job.logical_job_id,
        None,
        False,
        "T",
        associated_job.logical_job_id,
        "root-broker",
    )
    retained_process = namespace[
        "_c6_broker_native_core_v1_verify_and_register_retained_process"
    ](
        authority,
        902,
        (101, 10_001),
        (associated_job.logical_job_id, inner_job.logical_job_id),
    )

    state = authority.state
    assert authority.core is core
    assert authority.monotonic_ns is clock
    assert state.core is core
    assert state.monotonic_ns is clock
    assert acquired_port is completion_port
    assert state.completion_port is completion_port
    assert acquired_endpoint is prepared_endpoint
    assert state.prepared_endpoints == (prepared_endpoint,)
    assert state.owned_job_resources == (
        associated_resource,
        inner_resource,
    )
    assert associated_resource.owned_job is associated_job
    assert inner_resource.owned_job is inner_job
    assert retained_process is state.retained_processes[0]
    assert retained_process.handle == 902
    assert retained_process.process_identity == (101, 10_001)
    assert retained_process.campaign_job_ids == (
        associated_job.logical_job_id,
        inner_job.logical_job_id,
    )
    assert trace[-4:] == [
        ("get-process-id", 902),
        ("get-process-times", 902),
        ("is-process-in-job", 902, 901),
        ("is-process-in-job", 902, 904),
    ]
    with pytest.raises(
        RuntimeError,
        match=r"^GUARDED_BOOTSTRAP_INVALID$",
    ):
        namespace[
            "_C6BrokerNativeCoreV1FailureCleanupAttemptAuthority"
        ]()
    assert side_effect_calls == []


def test_broker_native_iocp_failure_cleanup_acquisition_rejects_reconstructed_or_foreign_attempt_resources_before_native_call(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = (
        _broker_native_iocp_failure_cleanup_acquisition_test_namespace(
            module
        )
    )
    trace: list[object] = []
    core = _broker_native_iocp_failure_cleanup_acquisition_core(
        namespace,
        trace,
    )
    authority_one = namespace[
        "_c6_broker_native_core_v1_begin_failure_cleanup_attempt"
    ](core, lambda: 1)
    authority_two = namespace[
        "_c6_broker_native_core_v1_begin_failure_cleanup_attempt"
    ](core, lambda: 2)
    port_type = namespace["_C6BrokerNativeCoreV1CompletionPort"]
    port_one = port_type(900)
    port_two = port_type(901)
    ports = iter((port_one, port_two))
    monkeypatch.setitem(
        namespace,
        "_c6_broker_native_core_v1_create_completion_port",
        lambda actual_core: next(ports),
    )
    namespace[
        "_c6_broker_native_core_v1_acquire_and_register_completion_port"
    ](authority_one)
    namespace[
        "_c6_broker_native_core_v1_acquire_and_register_completion_port"
    ](authority_two)
    prepare_calls: list[object] = []
    monkeypatch.setitem(
        namespace,
        "_c6_broker_native_core_v1_prepare_internal_channel_endpoint",
        lambda *args: prepare_calls.append(args),
    )
    channel_address = _broker_native_connect_drain_endpoints(
        namespace,
        (5,),
    )[0].channel_address

    for rejected_port in (port_type(900), port_two):
        with pytest.raises(
            RuntimeError,
            match=r"^GUARDED_BOOTSTRAP_INVALID$",
        ):
            namespace[
                "_c6_broker_native_core_v1_prepare_and_register_internal_channel_endpoint"
            ](authority_one, rejected_port, channel_address)
    assert prepare_calls == []

    authority_type = namespace[
        "_C6BrokerNativeCoreV1FailureCleanupAttemptAuthority"
    ]
    forged = object.__new__(authority_type)
    forged._state = authority_one.state
    forged._core = _broker_native_iocp_failure_cleanup_acquisition_core(
        namespace,
        trace,
    )
    forged._monotonic_ns = authority_one.monotonic_ns
    forged._success_resource_manifest = None
    forged._success_resource_results = ()
    forged._success_resource_phase = "unfrozen"
    forged._success_resource_last_monotonic_ns = None
    forged._success_job_notification_authority = None
    forged._success_ack_status_expectation_authority = None
    forged._success_ack_status_authority = None
    with pytest.raises(
        RuntimeError,
        match=r"^GUARDED_BOOTSTRAP_INVALID$",
    ):
        namespace[
            "_c6_broker_native_core_v1_acquire_and_register_completion_port"
        ](forged)
    assert side_effect_calls == []


