def test_broker_native_iocp_failure_cleanup_acquisition_source_extractor_rejects_mutants(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    fragment = (
        module._launch_broker_native_iocp_failure_cleanup_acquisition_source_fragment()
    )
    mutations = (
        (
            fragment.manifest_source_sha256.encode("ascii"),
            b"0" * 64,
        ),
        (
            b"_c6_broker_native_core_v1_begin_failure_cleanup_state(",
            b"_c6_broker_native_core_v1_begin_failure_cleanup_state_bypass(",
        ),
        (
            b"state._completion_port is not completion_port",
            b"state._completion_port == completion_port",
        ),
        (
            b"observed_pid != expected_identity[0]",
            b"observed_pid == expected_identity[0]",
        ),
        (
            b"bool(membership_value) is not expected_membership",
            b"bool(membership_value) is expected_membership",
        ),
    )
    sources = [
        fragment.source_bytes.replace(before, after, 1)
        for before, after in mutations
    ]
    sources.extend(
        (
            b"import os\n" + fragment.source_bytes,
            fragment.source_bytes + b"core.iocp.get_queued_completion_status()\n",
            fragment.source_bytes + b"core.job.terminate_job()\n",
            fragment.source_bytes
            + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN\n",
            fragment.source_bytes
            + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END\n",
        )
    )
    assert all(source != fragment.source_bytes for source in sources)

    for source in sources:
        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ):
            module._launch_extract_broker_native_iocp_failure_cleanup_acquisition_source_fragment(
                source
            )
    assert side_effect_calls == []


