def test_broker_native_iocp_failure_cleanup_manifest_source_is_exact_and_dormant(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    writer_close = (
        module._launch_broker_native_iocp_writer_close_eligibility_source_fragment()
    )

    fragment = (
        module._launch_broker_native_iocp_failure_cleanup_manifest_source_fragment()
    )

    assert fragment.version == (
        "complete-suite-broker-native-iocp-failure-cleanup-manifest-source-fragment-v1"
    )
    assert fragment.implementation_id == "broker-native-core-v1"
    assert fragment.activation_state == "dormant-source-only"
    assert fragment.completeness_state == (
        "trusted-per-attempt-resource-manifest-and-topology-only"
    )
    assert fragment.writer_close_source_version == writer_close.version
    assert fragment.writer_close_source_size == len(writer_close.source_bytes)
    assert fragment.writer_close_source_sha256 == writer_close.source_sha256
    assert fragment.class_names == (
        "_C6BrokerNativeCoreV1RetainedProcessResource",
        "_C6BrokerNativeCoreV1OwnedJobResource",
        "_C6BrokerNativeCoreV1OwnedJobCleanupTarget",
        "_C6BrokerNativeCoreV1FailureCleanupManifest",
        "_C6BrokerNativeCoreV1FailureCleanupState",
    )
    assert fragment.function_names == (
        "_c6_broker_native_core_v1_validate_cleanup_process_identity",
        "_c6_broker_native_core_v1_authenticate_writer_close_result",
        "_c6_broker_native_core_v1_begin_failure_cleanup_state",
        "_c6_broker_native_core_v1_register_failure_cleanup_completion_port",
        "_c6_broker_native_core_v1_register_failure_cleanup_endpoint",
        "_c6_broker_native_core_v1_register_failure_cleanup_owned_job",
        "_c6_broker_native_core_v1_register_failure_cleanup_retained_process",
        "_c6_broker_native_core_v1_freeze_failure_cleanup_manifest",
    )
    assert type(fragment.source_bytes) is bytes
    assert len(fragment.source_bytes) == 51_069
    assert fragment.source_sha256 == (
        "809d5768d7f2ef21670e9c19a6645a53f9d44b7f2623a197b3ae5a6148e06d6c"
    )
    assert fragment.source_bytes.endswith(b"\n")
    assert b"\r" not in fragment.source_bytes
    assert b"WinDLL" not in fragment.source_bytes
    assert b"CreateProcessW" not in fragment.source_bytes
    assert b"ResumeThread" not in fragment.source_bytes
    tree = ast.parse(fragment.source_bytes.decode("ascii"))
    member_calls = tuple(
        node.func.attr
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
    )
    assert "close_handle" not in member_calls
    assert not hasattr(fragment, "__dict__")
    with pytest.raises((AttributeError, FrozenInstanceError)):
        fragment.activation_state = "active"
    assert not BOOTSTRAP_PATH.with_name(
        "complete_suite_control_plane.ps1"
    ).exists()
    assert side_effect_calls == []


def test_broker_native_iocp_failure_cleanup_manifest_derives_exact_live_handles_and_leaf_first_topology(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_iocp_failure_cleanup_test_namespace(module)
    core = _broker_native_iocp_dispatch_core(namespace, [], [])

    state, manifest, retained_processes, job_resources = (
        _broker_native_iocp_failure_cleanup_resources(namespace, core)
    )

    assert manifest.state is state
    assert manifest.core is core
    assert state.manifest is manifest
    assert state.phase == "step-5-ready"
    assert state.failure_grace_result is None
    assert state.reconciled_cleanup_result is None
    assert state.closed_idle_writer_handles == ()
    assert state.failed_idle_writer_handle is None
    assert manifest.retained_processes is state.retained_processes
    assert all(
        actual is expected
        for actual, expected in zip(
            manifest.retained_processes,
            retained_processes,
        )
    )
    assert tuple(
        target.owned_job_resource
        for target in manifest.applicable_owned_jobs
    ) == job_resources
    assert manifest.associated_job_binding is (
        manifest.applicable_owned_jobs[0]
    )
    assert manifest.associated_job_binding.known_processes == (
        retained_processes
    )
    assert manifest.applicable_owned_jobs[1].known_processes == (
        retained_processes
    )
    assert manifest.applicable_owned_jobs[2].known_processes == (
        retained_processes[1],
    )
    assert manifest.inner_job_bindings_leaf_first == (
        manifest.applicable_owned_jobs[2],
        manifest.applicable_owned_jobs[1],
    )
    assert manifest.all_pipe_handles == tuple(
        endpoint.server_handle
        for endpoint in manifest.writer_close_result.endpoints
    )
    assert manifest.immediate_idle_writer_handles == (
        manifest.writer_close_result.immediate_close_handles
    )
    assert manifest.remaining_open_pipe_handles == tuple(
        handle
        for handle in manifest.all_pipe_handles
        if handle not in manifest.immediate_idle_writer_handles
    )
    assert manifest.stage_1_close_handles == (
        manifest.remaining_open_pipe_handles
        + tuple(process.handle for process in retained_processes)
    )
    assert manifest.inner_job_close_handles_leaf_first == (905, 904)
    assert manifest.associated_job_close_handle == 901
    assert manifest.completion_port.handle == 900
    with pytest.raises(
        RuntimeError,
        match=r"^GUARDED_BOOTSTRAP_INVALID$",
    ):
        namespace["_C6BrokerNativeCoreV1FailureCleanupState"]()
    assert side_effect_calls == []


@pytest.mark.parametrize(
    "mutation",
    (
        "duplicate-process-handle",
        "duplicate-process-identity",
        "duplicate-live-handle",
        "missing-associated-job",
        "two-associated-jobs",
        "orphan-parent",
        "cycle",
        "child-known-process-not-in-parent",
        "root-known-process-mismatch",
        "ambient-owner",
        "ambient-kind",
        "mismatched-owner-kind",
        "late-completion-port-collision",
    ),
)
def test_broker_native_iocp_failure_cleanup_manifest_rejects_incomplete_or_ambient_resource_sets(
    mutation: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_iocp_failure_cleanup_test_namespace(module)
    core = _broker_native_iocp_dispatch_core(namespace, [], [])
    _state, manifest, retained_processes, job_resources = (
        _broker_native_iocp_failure_cleanup_resources(namespace, core)
    )
    process_type = namespace["_C6BrokerNativeCoreV1RetainedProcessResource"]
    resource_type = namespace["_C6BrokerNativeCoreV1OwnedJobResource"]
    owned_job_type = namespace["_C6BrokerNativeCoreV1OwnedJob"]
    begin = namespace[
        "_c6_broker_native_core_v1_begin_failure_cleanup_state"
    ]
    register_port = namespace[
        "_c6_broker_native_core_v1_register_failure_cleanup_completion_port"
    ]
    register_endpoint = namespace[
        "_c6_broker_native_core_v1_register_failure_cleanup_endpoint"
    ]
    register_job = namespace[
        "_c6_broker_native_core_v1_register_failure_cleanup_owned_job"
    ]
    register_process = namespace[
        "_c6_broker_native_core_v1_register_failure_cleanup_retained_process"
    ]
    freeze = namespace[
        "_c6_broker_native_core_v1_freeze_failure_cleanup_manifest"
    ]
    candidate_state = begin(core, lambda: 0)

    if mutation == "late-completion-port-collision":
        register_job(candidate_state, job_resources[0])
        invalid_action = lambda: register_port(
            candidate_state,
            namespace["_C6BrokerNativeCoreV1CompletionPort"](
                job_resources[0].owned_job.handle
            ),
        )
    else:
        register_port(candidate_state, manifest.completion_port)
        for prepared_endpoint in manifest.writer_close_result.prepared_endpoints:
            register_endpoint(candidate_state, prepared_endpoint)
        if mutation == "missing-associated-job":
            invalid_action = lambda: freeze(
                candidate_state,
                manifest.writer_close_result,
            )
        elif mutation == "two-associated-jobs":
            register_job(candidate_state, job_resources[0])
            invalid_action = lambda: register_job(
                candidate_state,
                resource_type(
                    owned_job_type("e" * 32, 906, True),
                    "J1",
                    None,
                    "root-broker",
                ),
            )
        elif mutation in ("orphan-parent", "cycle"):
            parent_id = (
                "f" * 32
                if mutation == "orphan-parent"
                else "e" * 32
            )
            invalid_action = lambda: register_job(
                candidate_state,
                resource_type(
                    owned_job_type("e" * 32, 906, False),
                    "T",
                    parent_id,
                    "root-broker",
                ),
            )
        elif mutation in (
            "ambient-owner",
            "ambient-kind",
            "mismatched-owner-kind",
        ):
            invalid_action = lambda: register_job(
                candidate_state,
                resource_type(
                    owned_job_type("e" * 32, 906, True),
                    "A0" if mutation == "ambient-kind" else "J1",
                    None,
                    (
                        "ambient"
                        if mutation == "ambient-owner"
                        else "host-control-plane"
                        if mutation == "mismatched-owner-kind"
                        else "root-broker"
                    ),
                ),
            )
        else:
            for job_resource in job_resources:
                register_job(candidate_state, job_resource)
            if mutation == "duplicate-process-handle":
                register_process(candidate_state, retained_processes[0])
                candidate_process = process_type(
                    retained_processes[0].handle,
                    102,
                    10_002,
                    retained_processes[1].campaign_job_ids,
                )
            elif mutation == "duplicate-process-identity":
                register_process(candidate_state, retained_processes[0])
                candidate_process = process_type(
                    903,
                    101,
                    10_001,
                    retained_processes[0].campaign_job_ids,
                )
            elif mutation == "duplicate-live-handle":
                candidate_process = process_type(
                    manifest.completion_port.handle,
                    101,
                    10_001,
                    retained_processes[0].campaign_job_ids,
                )
            elif mutation == "child-known-process-not-in-parent":
                candidate_process = process_type(
                    906,
                    103,
                    10_003,
                    (
                        job_resources[0].owned_job.logical_job_id,
                        job_resources[2].owned_job.logical_job_id,
                    ),
                )
            else:
                candidate_process = process_type(
                    906,
                    103,
                    10_003,
                    (job_resources[1].owned_job.logical_job_id,),
                )
            invalid_action = lambda: register_process(
                candidate_state,
                candidate_process,
            )

    with pytest.raises(
        RuntimeError,
        match=r"^GUARDED_BOOTSTRAP_INVALID$",
    ):
        invalid_action()
    assert side_effect_calls == []


