@pytest.mark.parametrize(
    "failure_case",
    (
        "manifest-tuple",
        "reconstructed-manifest",
        "cross-attempt-manifest",
        "replay",
    ),
)
def test_broker_native_iocp_failure_grace_rejects_invalid_context_before_clock_or_calls(
    failure_case: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_iocp_failure_grace_test_namespace(module)
    events: list[dict[str, object]] = [
        {
            "result": 0,
            "error_code": 258,
            "completion_key": 0,
            "overlapped_address": None,
        }
    ]
    trace: list[object] = []
    calls: list[str] = []

    def monotonic_ns() -> int:
        calls.append("clock")
        return len(calls) - 1

    core = _broker_native_iocp_failure_cleanup_poll_core(
        namespace,
        {
            902: {"wait_result": 0, "exit_code": 7},
            903: {"wait_result": 0, "exit_code": 8},
        },
        {
            901: {"total_processes": 2},
            904: {"total_processes": 2},
            905: {"total_processes": 1},
        },
        trace,
        events=events,
        close_trace=trace,
    )
    state, manifest, _retained_processes, _job_resources = (
        _broker_native_iocp_failure_cleanup_resources(
            namespace,
            core,
            monotonic_ns=monotonic_ns,
        )
    )
    candidate_manifest: object
    if failure_case == "manifest-tuple":
        candidate_manifest = tuple(manifest)
    elif failure_case == "reconstructed-manifest":
        candidate_manifest = type(manifest)(*manifest)
    elif failure_case == "cross-attempt-manifest":
        foreign_state, _foreign_manifest, _processes, _jobs = (
            _broker_native_iocp_failure_cleanup_resources(
                namespace,
                core,
                monotonic_ns=monotonic_ns,
            )
        )
        candidate_manifest = type(manifest)(
            foreign_state,
            *manifest[1:],
        )
    else:
        first_result = namespace[
            "_c6_broker_native_core_v1_run_failure_grace"
        ](manifest)
        assert first_result.terminal_state == "reconciled"
        trace.clear()
        calls.clear()
        candidate_manifest = manifest

    with pytest.raises(
        RuntimeError,
        match=r"^GUARDED_BOOTSTRAP_INVALID$",
    ):
        namespace["_c6_broker_native_core_v1_run_failure_grace"](
            candidate_manifest
        )
    assert calls == []
    assert trace == []
    assert state.phase == (
        "step-6-ready" if failure_case == "replay" else "step-5-ready"
    )
    assert side_effect_calls == []


