def test_broker_native_iocp_failure_grace_source_extractor_rejects_mutants(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    fragment = module._launch_broker_native_iocp_failure_grace_source_fragment()
    mutations = (
        (
            fragment.reconciliation_source_sha256.encode("ascii"),
            b"0" * 64,
        ),
        (b"10_000_000_000", b"10_000_000_001"),
        (b"cleanup_mode=True", b"cleanup_mode=False"),
        (
            b"attempt_state._begin_failure_grace()",
            b"attempt_state._record_failure_grace_abort()",
        ),
        (
            b"_c6_broker_native_core_v1_poll_failure_cleanup_manifest(manifest)",
            b"_c6_broker_native_core_v1_poll_failure_cleanup_manifest(None)",
        ),
        (
            b"attempt_state._bind_failure_grace_result(result)",
            b"attempt_state._record_failure_grace_abort()",
        ),
    )
    sources = [
        fragment.source_bytes.replace(before, after, 1)
        for before, after in mutations
    ]
    sources.extend(
        (
            b"import os\n" + fragment.source_bytes,
            fragment.source_bytes + b"core.iocp.cancel_io()\n",
            fragment.source_bytes + b"core.job.query_job_information()\n",
            fragment.source_bytes
            + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN\n",
            fragment.source_bytes
            + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END\n",
        )
    )
    assert all(source != fragment.source_bytes for source in sources)

    for source in sources:
        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ):
            module._launch_extract_broker_native_iocp_failure_grace_source_fragment(
                source
            )
    assert side_effect_calls == []


