@lru_cache(maxsize=1)
def _broker_native_iocp_reconciled_cleanup_test_namespace(
    module: object,
) -> dict[str, object]:
    namespace = _broker_native_iocp_failure_grace_test_namespace(module)
    fragment = (
        module._launch_broker_native_iocp_reconciled_cleanup_source_fragment()
    )
    exec(
        compile(
            fragment.source_bytes,
            "<broker-iocp-reconciled-cleanup-test>",
            "exec",
        ),
        namespace,
    )
    return namespace


def _broker_native_iocp_reconciled_cleanup_attempt(
    namespace: dict[str, object],
    *,
    close_failure_handle: int | None = None,
    close_binding_outcomes: dict[int, object] | None = None,
    protocol_failure: bool = False,
    process_outcomes: dict[int, dict[str, object]] | None = None,
    job_outcomes: dict[int, dict[str, object]] | None = None,
) -> tuple[object, object, object, object, list[object]]:
    trace: list[object] = []
    events: list[dict[str, object]] = [
        {
            "result": 0,
            "error_code": 5 if protocol_failure else 258,
            "completion_key": 0,
            "overlapped_address": None,
        }
    ]
    if process_outcomes is None:
        process_outcomes = {
            902: {"wait_result": 0, "exit_code": 7},
            903: {"wait_result": 0, "exit_code": 8},
        }
    if job_outcomes is None:
        job_outcomes = {
            901: {"total_processes": 2},
            904: {"total_processes": 2},
            905: {"total_processes": 1},
        }
    core = _broker_native_iocp_failure_cleanup_poll_core(
        namespace,
        process_outcomes,
        job_outcomes,
        trace,
        events=events,
        close_trace=trace,
        close_failure_handle=close_failure_handle,
        close_binding_outcomes=close_binding_outcomes,
    )
    state, manifest, _retained_processes, _job_resources = (
        _broker_native_iocp_failure_cleanup_resources(
            namespace,
            core,
            include_live_read=protocol_failure,
            monotonic_ns=iter((0, 1, 2)).__next__,
        )
    )
    if protocol_failure:
        operation = manifest.writer_close_result.ledger[0]
        events[0]["completion_key"] = operation.endpoint.completion_key
        events[0]["overlapped_address"] = ctypes.addressof(
            operation.endpoint.connect_overlapped
        )
    grace_result = namespace[
        "_c6_broker_native_core_v1_run_failure_grace"
    ](manifest)
    assert grace_result.terminal_state == (
        "reconciled-with-protocol-failure"
        if protocol_failure
        else "reconciled"
    )
    assert state.failure_grace_result is grace_result
    assert state.phase == "step-6-ready"
    assert events == []
    trace.clear()
    return core, state, manifest, grace_result, trace


def test_broker_native_iocp_reconciled_cleanup_source_is_cross_bound_and_dormant(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    grace = module._launch_broker_native_iocp_failure_grace_source_fragment()

    fragment = (
        module._launch_broker_native_iocp_reconciled_cleanup_source_fragment()
    )

    assert fragment.version == (
        "complete-suite-broker-native-iocp-reconciled-cleanup-source-fragment-v1"
    )
    assert fragment.implementation_id == "broker-native-core-v1"
    assert fragment.activation_state == "dormant-source-only"
    assert fragment.completeness_state == (
        "authenticated-step-6-authoritative-repoll-and-strict-close-order-only"
    )
    assert fragment.grace_source_version == grace.version
    assert fragment.grace_source_size == len(grace.source_bytes)
    assert fragment.grace_source_sha256 == grace.source_sha256
    reconciliation = (
        module._launch_broker_native_iocp_failure_cleanup_reconciliation_source_fragment()
    )
    assert fragment.reconciliation_source_version == reconciliation.version
    assert fragment.reconciliation_source_size == len(
        reconciliation.source_bytes
    )
    assert (
        fragment.reconciliation_source_sha256
        == reconciliation.source_sha256
    )
    assert fragment.class_names == (
        "_C6BrokerNativeCoreV1ReconciledCleanupCloseTarget",
        "_C6BrokerNativeCoreV1ReconciledCleanupResult",
    )
    assert fragment.function_names == (
        "_c6_broker_native_core_v1_assert_iocp_reconciled_cleanup_facts",
        "_c6_broker_native_core_v1_run_reconciled_cleanup",
    )
    assert type(fragment.source_bytes) is bytes
    assert len(fragment.source_bytes) == 22_489
    assert fragment.source_sha256 == (
        "de8277b4ef474d5f738c63197d5a911884898ab3a416fe8f0476f62104448c2b"
    )
    assert fragment.source_bytes.endswith(b"\n")
    assert b"\r" not in fragment.source_bytes
    assert fragment.source_sha256 == sha256(fragment.source_bytes).hexdigest()
    assert not hasattr(fragment, "__dict__")
    with pytest.raises((AttributeError, FrozenInstanceError)):
        fragment.activation_state = "active"
    assert not BOOTSTRAP_PATH.with_name(
        "complete_suite_control_plane.ps1"
    ).exists()
    assert side_effect_calls == []


@pytest.mark.parametrize("protocol_failure", (False, True))
def test_broker_native_iocp_reconciled_cleanup_repolls_then_closes_exact_manifest_order(
    protocol_failure: bool,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_iocp_reconciled_cleanup_test_namespace(module)
    _core, state, manifest, grace_result, trace = (
        _broker_native_iocp_reconciled_cleanup_attempt(
            namespace,
            protocol_failure=protocol_failure,
        )
    )

    result = namespace[
        "_c6_broker_native_core_v1_run_reconciled_cleanup"
    ](grace_result)

    expected_close_handles = (
        manifest.stage_1_close_handles
        + manifest.inner_job_close_handles_leaf_first
        + (manifest.associated_job_close_handle,)
        + (manifest.completion_port.handle,)
    )
    expected_poll_trace = [
        ("wait", 902, 0),
        ("exit", 902),
        ("wait", 903, 0),
        ("exit", 903),
        ("job-accounting", 901),
        ("job-process-ids", 901),
        ("job-accounting", 904),
        ("job-process-ids", 904),
        ("job-accounting", 905),
        ("job-process-ids", 905),
    ]
    assert trace == expected_poll_trace + [
        ("close", handle) for handle in expected_close_handles
    ]
    assert result.attempt_state is state
    assert result.failure_grace_result is grace_result
    assert result.manifest is manifest
    assert result.preclose_reconciliation_snapshot.manifest is manifest
    assert result.preclose_reconciliation_snapshot.reconciled is True
    assert tuple(target.handle for target in result.close_targets) == (
        expected_close_handles
    )
    assert tuple(target.stage_ordinal for target in result.close_targets) == (
        (1,) * len(manifest.stage_1_close_handles)
        + (2,) * len(manifest.inner_job_close_handles_leaf_first)
        + (3, 4)
    )
    assert result.closed_targets == result.close_targets
    assert result.failed_target is None
    assert result.untouched_targets == ()
    assert result.terminal_state == "reconciled-cleanup-complete"
    assert result.protocol_failure_classifications == (
        grace_result.protocol_failure_classifications
    )
    assert state.reconciled_cleanup_result is result
    assert state.phase == "failure-cleanup-complete"
    assert side_effect_calls == []


