def test_broker_native_iocp_grace_expiry_quarantine_binds_exact_live_allocations_before_strict_close_order(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_iocp_grace_expiry_quarantine_test_namespace(
        module
    )
    state_box: dict[str, object] = {}
    step_7_started = False

    def observe_close(_handle: int) -> None:
        if not step_7_started:
            return
        state = state_box["state"]
        assert state.phase == "step-7-expiry-running"
        assert state.expiry_quarantine_result is None
        assert state.expiry_quarantined_allocations
        assert state.expiry_close_targets

    _core, state, manifest, grace_result, trace = (
        _broker_native_iocp_grace_expiry_quarantine_attempt(
            namespace,
            close_observer=observe_close,
        )
    )
    state_box["state"] = state
    step_7_started = True

    result = namespace[
        "_c6_broker_native_core_v1_run_grace_expiry_quarantine"
    ](grace_result)

    operation = grace_result.ledger[0]
    allocation = result.quarantined_allocations[0]
    assert allocation.operation is operation
    assert allocation.overlapped is operation.endpoint.connect_overlapped
    assert allocation.buffer is operation.native_buffer
    assert allocation.retention_boundary == (
        "through-owning-host-or-root-process-exit"
    )
    assert result.quarantined_allocations is (
        state.expiry_quarantined_allocations
    )
    assert result.close_targets is state.expiry_close_targets
    assert result.expiry_entry_monotonic_ns == 10_000_000_001
    assert state.expiry_entry_monotonic_ns == 10_000_000_001
    assert tuple(target.stage_ordinal for target in result.close_targets) == (
        1,
        1,
        1,
        2,
        2,
        2,
        2,
        4,
    )
    assert tuple(target.resource_kind for target in result.close_targets) == (
        "kill-on-close-job",
        "kill-on-close-job",
        "kill-on-close-job",
        "pipe",
        "pipe",
        "process",
        "process",
        "completion-port",
    )
    assert tuple(target.handle for target in result.close_targets) == (
        901,
        904,
        905,
        1_006,
        1_007,
        902,
        903,
        900,
    )
    assert trace == [
        ("clock", 10_000_000_001),
        *(("close", target.handle) for target in result.close_targets),
    ]
    assert len(result.closed_targets) == len(result.close_targets)
    assert all(
        actual is expected
        for actual, expected in zip(
            result.closed_targets,
            result.close_targets,
        )
    )
    assert result.failed_target is None
    assert result.failed_error_code is None
    assert result.failure_disposition is None
    assert result.untouched_targets == ()
    assert result.pump_stopped is True
    assert result.completion_port_close_attempted is True
    assert result.terminal_state == "expiry-quarantine-complete"
    assert state.expiry_quarantine_result is result
    assert state.phase == "failure-cleanup-expired-quarantined"
    assert side_effect_calls == []


