def _broker_native_success_resource_reconciliation_attempt(
    namespace: dict[str, object],
    *,
    clock_values: tuple[int, ...] = (1_000, 2_000),
    process_outcomes: dict[int, dict[str, object]] | None = None,
    job_outcomes: dict[int, dict[str, object]] | None = None,
    prepared_endpoints: tuple[object, ...] = (),
) -> tuple[object, object, object, list[object]]:
    trace: list[object] = []
    clock_iterator = iter(clock_values)
    process_rows = (
        {
            902: {
                "pid": 101,
                "creation_time": 10_001,
                "wait_result": 0,
                "exit_result": 1,
                "exit_code": 0,
            },
            903: {
                "pid": 102,
                "creation_time": 10_002,
                "wait_result": 0,
                "exit_result": 1,
                "exit_code": 0,
            },
        }
        if process_outcomes is None
        else process_outcomes
    )
    job_rows = (
        {
            901: {
                "total_processes": 2,
                "active_processes": 0,
                "process_ids": (),
            },
            904: {
                "total_processes": 2,
                "active_processes": 0,
                "process_ids": (),
            },
            905: {
                "total_processes": 1,
                "active_processes": 0,
                "process_ids": (),
            },
        }
        if job_outcomes is None
        else job_outcomes
    )

    def next_value(
        outcome: dict[str, object],
        key: str,
        default: object,
    ) -> object:
        value = outcome.get(key, default)
        if type(value) is list:
            if not value:
                raise AssertionError(f"exhausted fake outcome {key!r}")
            return value.pop(0)
        return value

    def monotonic_ns() -> int:
        value = next(clock_iterator)
        trace.append(("clock", value))
        return value

    class FakeProcessCreation:
        def close_handle(self, handle: int) -> int:
            trace.append(("unexpected-close", handle))
            return 1

    class FakeProcessObservation:
        def get_process_id(self, process_handle: int) -> int:
            trace.append(("get-process-id", process_handle))
            ctypes.set_last_error(0)
            return int(process_rows[process_handle]["pid"])

        def get_process_times(
            self,
            process_handle: int,
            creation_time_pointer: object,
            exit_time_pointer: object,
            kernel_time_pointer: object,
            user_time_pointer: object,
        ) -> int:
            trace.append(("get-process-times", process_handle))
            creation_time = int(
                process_rows[process_handle]["creation_time"]
            )
            file_time_type = namespace[
                "_C6BrokerNativeCoreV1FileTime"
            ]
            value = ctypes.cast(
                creation_time_pointer,
                ctypes.POINTER(file_time_type),
            ).contents
            value.dwLowDateTime = creation_time & 0xFFFFFFFF
            value.dwHighDateTime = creation_time >> 32
            ctypes.set_last_error(0)
            return 1

        def wait_for_single_object(
            self,
            handle: int,
            timeout_ms: int,
        ) -> object:
            trace.append(("wait", handle, timeout_ms))
            outcome = process_rows[handle]
            ctypes.set_last_error(
                int(next_value(outcome, "wait_error", 0))
            )
            return next_value(outcome, "wait_result", 0)

        def get_exit_code_process(
            self,
            handle: int,
            exit_code_pointer: object,
        ) -> object:
            trace.append(("exit", handle))
            outcome = process_rows[handle]
            result = next_value(outcome, "exit_result", 1)
            if result == 1:
                ctypes.cast(
                    exit_code_pointer,
                    ctypes.POINTER(ctypes.wintypes.DWORD),
                ).contents.value = int(
                    next_value(outcome, "exit_code", 0)
                )
            ctypes.set_last_error(
                int(next_value(outcome, "exit_error", 0))
            )
            return result

    membership = {
        (902, 901): True,
        (902, 904): True,
        (902, 905): False,
        (903, 901): True,
        (903, 904): True,
        (903, 905): True,
    }

    class FakeJob:
        def is_process_in_job(
            self,
            process_handle: int,
            job_handle: int,
            membership_pointer: object,
        ) -> int:
            trace.append(
                ("is-process-in-job", process_handle, job_handle)
            )
            ctypes.cast(
                membership_pointer,
                ctypes.POINTER(ctypes.wintypes.BOOL),
            ).contents.value = int(
                membership[(process_handle, job_handle)]
            )
            ctypes.set_last_error(0)
            return 1

        def query_job_information(
            self,
            handle: int,
            information_class: int,
            information_pointer: object,
            information_size: int,
            return_length_pointer: object,
        ) -> object:
            outcome = job_rows[handle]
            return_length = ctypes.cast(
                return_length_pointer,
                ctypes.POINTER(ctypes.wintypes.DWORD),
            ).contents
            if information_class == 1:
                trace.append(("job-accounting", handle))
                result = next_value(outcome, "accounting_result", 1)
                ctypes.set_last_error(
                    int(next_value(outcome, "accounting_error", 0))
                )
                if result == 1:
                    accounting_type = namespace[
                        "_C6BrokerNativeCoreV1JobObjectBasicAccountingInformation"
                    ]
                    accounting = ctypes.cast(
                        information_pointer,
                        ctypes.POINTER(accounting_type),
                    ).contents
                    accounting.TotalProcesses = int(
                        next_value(outcome, "total_processes", 0)
                    )
                    accounting.ActiveProcesses = int(
                        next_value(outcome, "active_processes", 0)
                    )
                    return_length.value = int(
                        next_value(
                            outcome,
                            "accounting_return_length",
                            ctypes.sizeof(accounting_type),
                        )
                    )
                return result
            if information_class != 3:
                raise AssertionError(
                    f"unexpected Job information class {information_class!r}"
                )
            trace.append(("job-process-ids", handle))
            result = next_value(outcome, "process_id_list_result", 1)
            ctypes.set_last_error(
                int(next_value(outcome, "process_id_list_error", 0))
            )
            if result == 1:
                process_ids = tuple(
                    next_value(outcome, "process_ids", ())
                )
                header_type = namespace[
                    "_C6BrokerNativeCoreV1JobObjectBasicProcessIdListHeader"
                ]
                header_size = ctypes.sizeof(header_type)
                required_size = (
                    header_size
                    + len(process_ids) * ctypes.sizeof(ctypes.c_size_t)
                )
                assert required_size <= information_size
                address = ctypes.cast(
                    information_pointer,
                    ctypes.c_void_p,
                ).value
                assert address is not None
                header = header_type.from_address(address)
                header.NumberOfAssignedProcesses = int(
                    next_value(
                        outcome,
                        "assigned_processes",
                        len(process_ids),
                    )
                )
                header.NumberOfProcessIdsInList = int(
                    next_value(
                        outcome,
                        "listed_process_count",
                        len(process_ids),
                    )
                )
                if process_ids:
                    array_type = ctypes.c_size_t * len(process_ids)
                    array = array_type.from_address(address + header_size)
                    for index, process_id in enumerate(process_ids):
                        array[index] = int(process_id)
                return_length.value = int(
                    next_value(
                        outcome,
                        "process_id_list_return_length",
                        required_size,
                    )
                )
            return result

    core = namespace["_C6BrokerNativeCoreV1"](
        FakeProcessCreation(),
        FakeJob(),
        object(),
        object(),
        FakeProcessObservation(),
        object(),
        object(),
        object(),
        object(),
    )
    authority = namespace[
        "_c6_broker_native_core_v1_begin_failure_cleanup_attempt"
    ](core, monotonic_ns)
    state = authority.state
    completion_port = namespace[
        "_C6BrokerNativeCoreV1CompletionPort"
    ](900)
    namespace[
        "_c6_broker_native_core_v1_register_failure_cleanup_completion_port"
    ](state, completion_port)
    for prepared_endpoint in prepared_endpoints:
        namespace[
            "_c6_broker_native_core_v1_register_failure_cleanup_endpoint"
        ](state, prepared_endpoint)
    owned_job_type = namespace["_C6BrokerNativeCoreV1OwnedJob"]
    job_resource_type = namespace[
        "_C6BrokerNativeCoreV1OwnedJobResource"
    ]
    job_resources = (
        job_resource_type(
            owned_job_type("a" * 32, 901, True),
            "J1",
            None,
            "root-broker",
        ),
        job_resource_type(
            owned_job_type("b" * 32, 904, False),
            "T",
            "a" * 32,
            "root-broker",
        ),
        job_resource_type(
            owned_job_type("d" * 32, 905, False),
            "Ln",
            "b" * 32,
            "root-broker",
        ),
    )
    for job_resource in job_resources:
        namespace[
            "_c6_broker_native_core_v1_register_failure_cleanup_owned_job"
        ](state, job_resource)
    namespace[
        "_c6_broker_native_core_v1_verify_and_register_retained_process"
    ](authority, 902, (101, 10_001), ("a" * 32, "b" * 32))
    namespace[
        "_c6_broker_native_core_v1_verify_and_register_retained_process"
    ](
        authority,
        903,
        (102, 10_002),
        ("a" * 32, "b" * 32, "d" * 32),
    )
    manifest = namespace[
        "_c6_broker_native_core_v1_freeze_success_resource_manifest"
    ](authority, 10_000_000_000)
    return core, authority, manifest, trace


def test_broker_native_success_resource_reconciliation_source_is_cross_bound_and_dormant(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    acquisition = (
        module._launch_broker_native_iocp_failure_cleanup_acquisition_source_fragment()
    )
    fragment = (
        module._launch_broker_native_success_resource_reconciliation_source_fragment()
    )

    assert fragment.version == (
        "complete-suite-broker-native-success-resource-reconciliation-source-fragment-v1"
    )
    assert fragment.implementation_id == "broker-native-core-v1"
    assert fragment.activation_state == "dormant-source-only"
    assert fragment.completeness_state == (
        "attempt-bound-authoritative-success-gates-1-through-5-only"
    )
    assert fragment.acquisition_source_version == acquisition.version
    assert fragment.acquisition_source_size == len(acquisition.source_bytes)
    assert fragment.acquisition_source_sha256 == acquisition.source_sha256
    assert fragment.class_names == (
        "_C6BrokerNativeCoreV1SuccessProcessTarget",
        "_C6BrokerNativeCoreV1SuccessJobTarget",
        "_C6BrokerNativeCoreV1SuccessResourceManifest",
        "_C6BrokerNativeCoreV1SuccessProcessSnapshot",
        "_C6BrokerNativeCoreV1SuccessJobSnapshot",
        "_C6BrokerNativeCoreV1SuccessResourceResult",
    )
    assert fragment.function_names == (
        "_c6_broker_native_core_v1_assert_iocp_success_convergence_facts",
        "_c6_broker_native_core_v1_freeze_success_resource_manifest",
        "_c6_broker_native_core_v1_poll_success_resources",
    )
    assert len(fragment.source_bytes) == 35_866
    assert fragment.source_sha256 == (
        "5619b3e82c045b646cc14c65996afd5db802316c248e2fe2f9ad9e2cd1114b6d"
    )
    assert fragment.source_bytes.endswith(b"\n")
    assert b"\r" not in fragment.source_bytes
    assert fragment.source_sha256 == sha256(fragment.source_bytes).hexdigest()
    assert not hasattr(fragment, "__dict__")
    with pytest.raises((AttributeError, FrozenInstanceError)):
        fragment.activation_state = "active"
    assert not BOOTSTRAP_PATH.with_name(
        "complete_suite_control_plane.ps1"
    ).exists()
    assert side_effect_calls == []


def test_broker_native_success_resource_reconciliation_source_has_exact_static_surface(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    source = (
        module._launch_broker_native_success_resource_reconciliation_source_fragment()
        .source_bytes
    )
    tree = ast.parse(source.decode("ascii"))
    class_names = tuple(
        node.name for node in tree.body if isinstance(node, ast.ClassDef)
    )
    function_names = tuple(
        node.name for node in tree.body if isinstance(node, ast.FunctionDef)
    )
    imports = tuple(
        node
        for node in ast.walk(tree)
        if isinstance(node, (ast.Import, ast.ImportFrom))
    )
    top_level_calls = tuple(
        node
        for statement in tree.body
        if not isinstance(statement, (ast.ClassDef, ast.FunctionDef))
        for node in ast.walk(statement)
        if isinstance(node, ast.Call)
    )
    member_calls = tuple(
        node.func.attr
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
    )

    assert class_names == (
        "_C6BrokerNativeCoreV1SuccessProcessTarget",
        "_C6BrokerNativeCoreV1SuccessJobTarget",
        "_C6BrokerNativeCoreV1SuccessResourceManifest",
        "_C6BrokerNativeCoreV1SuccessProcessSnapshot",
        "_C6BrokerNativeCoreV1SuccessJobSnapshot",
        "_C6BrokerNativeCoreV1SuccessResourceResult",
    )
    assert function_names == (
        "_c6_broker_native_core_v1_assert_iocp_success_convergence_facts",
        "_c6_broker_native_core_v1_freeze_success_resource_manifest",
        "_c6_broker_native_core_v1_poll_success_resources",
    )
    assert imports == ()
    assert top_level_calls == ()
    assert member_calls.count("wait_for_single_object") == 1
    assert member_calls.count("get_exit_code_process") == 1
    assert member_calls.count("query_job_information") == 2
    for forbidden in (
        "get_queued_completion_status",
        "read_file",
        "write_file",
        "cancel_io",
        "close_handle",
        "terminate_job",
        "create_process",
        "resume_thread",
    ):
        assert forbidden not in member_calls
    assert b"publish" not in source.lower()
    assert b"overall_success = True" not in source
    assert side_effect_calls == []


def test_broker_native_success_resource_reconciliation_source_extractor_rejects_mutants(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    fragment = (
        module._launch_broker_native_success_resource_reconciliation_source_fragment()
    )
    mutations = (
        (
            fragment.acquisition_source_sha256.encode("ascii"),
            b"0" * 64,
        ),
        (
            b"_C6BrokerNativeCoreV1SuccessProcessTarget(process, 0)",
            b"_C6BrokerNativeCoreV1SuccessProcessTarget(process, 1)",
        ),
        (
            b"    _c6_broker_native_core_v1_assert_iocp_success_convergence_facts()\n",
            b"    _c6_broker_native_core_v1_assert_iocp_success_convergence_facts_bypass()\n",
        ),
        (
            b"identity_membership_gate = True",
            b"identity_membership_gate = False",
        ),
        (
            b'manifest.core.process_observation.wait_for_single_object(',
            b'manifest.core.process_observation.get_queued_completion_status(',
        ),
    )
    sources = [
        fragment.source_bytes.replace(before, after, 1)
        for before, after in mutations
    ]
    sources.extend(
        (
            b"import os\n" + fragment.source_bytes,
            fragment.source_bytes + b"core.iocp.cancel_io()\n",
            fragment.source_bytes + b"core.job.terminate_job()\n",
            fragment.source_bytes
            + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN\n",
            fragment.source_bytes
            + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END\n",
        )
    )
    assert all(source != fragment.source_bytes for source in sources)

    for source in sources:
        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ):
            module._launch_extract_broker_native_success_resource_reconciliation_source_fragment(
                source
            )
    assert side_effect_calls == []


