def test_broker_native_success_resource_reconciliation_requires_all_five_resource_gates_without_overall_success(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_success_resource_reconciliation_test_namespace(
        module
    )
    _core, authority, manifest, trace = (
        _broker_native_success_resource_reconciliation_attempt(namespace)
    )
    registration_trace = tuple(trace)

    result = namespace[
        "_c6_broker_native_core_v1_poll_success_resources"
    ](manifest)

    assert result.manifest is manifest
    assert result.poll_ordinal == 1
    assert result.poll_monotonic_ns == 2_000
    assert result.process_terminal_gate is True
    assert result.job_active_process_gate is True
    assert result.job_final_pid_gate is True
    assert result.job_total_process_gate is True
    assert result.identity_membership_gate is True
    assert result.resource_converged is True
    assert result.overall_success_authority == "forbidden"
    assert result.terminal_state == "resource-converged"
    assert len(result.process_snapshots) == 2
    assert len(result.job_snapshots) == 3
    assert all(snapshot.exit_contract_match for snapshot in result.process_snapshots)
    assert all(snapshot.active_processes == 0 for snapshot in result.job_snapshots)
    assert all(snapshot.process_ids == () for snapshot in result.job_snapshots)
    assert authority.success_resource_manifest is manifest
    assert authority.success_resource_results == (result,)
    assert authority.success_resource_phase == "resource-converged"
    assert tuple(trace[: len(registration_trace)]) == registration_trace
    assert trace[len(registration_trace) :] == [
        ("clock", 2_000),
        ("wait", 902, 0),
        ("exit", 902),
        ("wait", 903, 0),
        ("exit", 903),
        ("job-accounting", 901),
        ("job-process-ids", 901),
        ("job-accounting", 904),
        ("job-process-ids", 904),
        ("job-accounting", 905),
        ("job-process-ids", 905),
    ]
    assert side_effect_calls == []


def test_broker_native_success_resource_reconciliation_allows_bounded_pending_then_converges(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_success_resource_reconciliation_test_namespace(
        module
    )
    process_outcomes = {
        902: {
            "pid": 101,
            "creation_time": 10_001,
            "wait_result": [258, 0],
            "exit_result": 1,
            "exit_code": 0,
        },
        903: {
            "pid": 102,
            "creation_time": 10_002,
            "wait_result": 0,
            "exit_result": 1,
            "exit_code": 0,
        },
    }
    job_outcomes = {
        901: {
            "total_processes": 2,
            "active_processes": [1, 0],
            "process_ids": [(101,), ()],
        },
        904: {
            "total_processes": 2,
            "active_processes": [1, 0],
            "process_ids": [(101,), ()],
        },
        905: {
            "total_processes": 1,
            "active_processes": 0,
            "process_ids": (),
        },
    }
    _core, authority, manifest, _trace = (
        _broker_native_success_resource_reconciliation_attempt(
            namespace,
            clock_values=(1_000, 2_000, 3_000),
            process_outcomes=process_outcomes,
            job_outcomes=job_outcomes,
        )
    )

    pending = namespace[
        "_c6_broker_native_core_v1_poll_success_resources"
    ](manifest)
    converged = namespace[
        "_c6_broker_native_core_v1_poll_success_resources"
    ](manifest)

    assert pending.poll_ordinal == 1
    assert pending.process_terminal_gate is False
    assert pending.job_active_process_gate is False
    assert pending.job_final_pid_gate is False
    assert pending.job_total_process_gate is True
    assert pending.identity_membership_gate is True
    assert pending.resource_converged is False
    assert pending.terminal_state == "pending"
    assert converged.poll_ordinal == 2
    assert converged.resource_converged is True
    assert converged.terminal_state == "resource-converged"
    assert authority.success_resource_results == (pending, converged)
    assert authority.success_resource_phase == "resource-converged"
    assert side_effect_calls == []


