    with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
        namespace[
            "_c6_broker_native_core_v1_poll_success_resources"
        ](candidate)
    assert trace[poll_boundary:] == []
    assert authority.success_resource_results == ()
    assert authority.success_resource_phase == "poll-ready"
    assert side_effect_calls == []


