def test_broker_native_job_notification_reducer_source_is_cross_bound_pure_and_dormant(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    dispatch = module._launch_broker_native_iocp_operation_dispatch_source_fragment()
    resource = (
        module._launch_broker_native_success_resource_reconciliation_source_fragment()
    )
    fragment = (
        module._launch_broker_native_job_notification_reducer_source_fragment()
    )

    assert fragment.version == (
        "complete-suite-broker-native-job-notification-reducer-source-fragment-v1"
    )
    assert fragment.implementation_id == "broker-native-core-v1"
    assert fragment.activation_state == "dormant-source-only"
    assert fragment.completeness_state == (
        "attempt-bound-typed-monotonic-advisory-job-ledger-only"
    )
    assert fragment.dispatch_source_version == dispatch.version
    assert fragment.dispatch_source_size == len(dispatch.source_bytes)
    assert fragment.dispatch_source_sha256 == dispatch.source_sha256
    assert fragment.resource_source_version == resource.version
    assert fragment.resource_source_size == len(resource.source_bytes)
    assert fragment.resource_source_sha256 == resource.source_sha256
    assert fragment.class_names == (
        "_C6BrokerNativeCoreV1JobNotificationEvent",
        "_C6BrokerNativeCoreV1JobNotificationState",
        "_C6BrokerNativeCoreV1JobNotificationAuthority",
    )
    assert fragment.function_names == (
        "_c6_broker_native_core_v1_assert_job_notification_facts",
        "_c6_broker_native_core_v1_find_associated_job_target",
        "_c6_broker_native_core_v1_make_job_notification_state",
        "_c6_broker_native_core_v1_begin_job_notification_ledger",
        "_c6_broker_native_core_v1_authenticate_job_notification_state",
        "_c6_broker_native_core_v1_fail_job_notification",
        "_c6_broker_native_core_v1_apply_job_notification",
    )
    assert len(fragment.source_bytes) == 20_485
    assert fragment.source_sha256 == (
        "29d5607c71c16587e4fa2d496820e5740ac231b0ea1ffcf13f8dbcc4ad368f86"
    )
    assert fragment.source_bytes.endswith(b"\n")
    assert b"\r" not in fragment.source_bytes
    assert fragment.source_sha256 == sha256(fragment.source_bytes).hexdigest()
    assert not hasattr(fragment, "__dict__")
    with pytest.raises((AttributeError, FrozenInstanceError)):
        fragment.activation_state = "active"
    source = fragment.source_bytes
    tree = ast.parse(source.decode("ascii"))
    assert not tuple(
        node
        for node in ast.walk(tree)
        if isinstance(node, (ast.Import, ast.ImportFrom))
    )
    assert not tuple(
        node
        for statement in tree.body
        if not isinstance(statement, (ast.ClassDef, ast.FunctionDef))
        for node in ast.walk(statement)
        if isinstance(node, ast.Call)
    )
    member_calls = tuple(
        node.func.attr
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
    )
    for forbidden in (
        "get_queued_completion_status",
        "query_job_information",
        "wait_for_single_object",
        "get_exit_code_process",
        "read_file",
        "write_file",
        "close_handle",
        "terminate_job",
        "create_process",
    ):
        assert forbidden not in member_calls
    assert b"publish" not in source.lower()
    assert b"overall_success = True" not in source
    assert not BOOTSTRAP_PATH.with_name(
        "complete_suite_control_plane.ps1"
    ).exists()
    assert side_effect_calls == []


def test_broker_native_job_notification_reducer_records_exact_monotonic_typed_events(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_job_notification_reducer_test_namespace(module)
    (
        _core,
        attempt_authority,
        resource_manifest,
        job_authority,
        _trace,
    ) = _broker_native_job_notification_attempt(namespace)
    state = job_authority.state
    rows = (
        (6, 101, "JOB_OBJECT_MSG_NEW_PROCESS", (101, 10_001)),
        (7, 101, "JOB_OBJECT_MSG_EXIT_PROCESS", (101, 10_001)),
        (6, 102, "JOB_OBJECT_MSG_NEW_PROCESS", (102, 10_002)),
        (8, 102, "JOB_OBJECT_MSG_ABNORMAL_EXIT_PROCESS", (102, 10_002)),
        (4, None, "JOB_OBJECT_MSG_ACTIVE_PROCESS_ZERO", None),
    )
    dispatch_results = []

    for ordinal, (
        message_id,
        message_value,
        message_name,
        process_identity,
    ) in enumerate(rows, start=1):
        dispatch_result = _broker_native_job_notification_dispatch(
            namespace,
            (),
            message_id,
            message_value,
        )
        dispatch_results.append(dispatch_result)
        state = namespace[
            "_c6_broker_native_core_v1_apply_job_notification"
        ](job_authority, state, dispatch_result)
        event = state.events[-1]
        assert event.ordinal == ordinal
        assert event.job_target is state.associated_job_target
        assert event.dispatch_result is dispatch_result
        assert event.message_id == message_id
        assert event.message_name == message_name
        if process_identity is None:
            assert event.process_target is None
        else:
            assert event.process_target.process_identity == process_identity

    assert state.manifest is resource_manifest
    assert state.event_ordinal == len(rows)
    assert state.active_process_zero_event_ordinal == 5
    assert state.terminal_failure is None
    assert state.failure_dispatch_result is None
    assert state.overall_success_authority == "forbidden"
    assert tuple(event.dispatch_result for event in state.events) == tuple(
        dispatch_results
    )
    assert attempt_authority.success_job_notification_authority is job_authority
    assert attempt_authority.success_resource_results == ()
    assert attempt_authority.success_resource_phase == "poll-ready"
    assert side_effect_calls == []


@pytest.mark.parametrize(
    ("message_id", "message_value", "expected_failure"),
    (
        (4, 0, "invalid-active-process-zero-value"),
        (4, 101, "invalid-active-process-zero-value"),
        (6, None, "invalid-process-message-value"),
        (7, 0, "invalid-process-message-value"),
        (8, 4_294_967_296, "invalid-process-message-value"),
        (5, 101, "unknown-job-message-id"),
        (6, 999, "unknown-job-process"),
    ),
)
def test_broker_native_job_notification_reducer_terminalizes_malformed_or_unknown_packets(
    message_id: int,
    message_value: int | None,
    expected_failure: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_job_notification_reducer_test_namespace(module)
    _core, _attempt, _manifest, authority, _trace = (
        _broker_native_job_notification_attempt(namespace)
    )
    state = authority.state
    dispatch_result = _broker_native_job_notification_dispatch(
        namespace,
        (),
        message_id,
        message_value,
    )

    failed = namespace[
        "_c6_broker_native_core_v1_apply_job_notification"
    ](authority, state, dispatch_result)

    assert failed.events == ()
    assert failed.event_ordinal == 0
    assert failed.terminal_failure == expected_failure
    assert failed.failure_dispatch_result is dispatch_result
    assert failed.overall_success_authority == "forbidden"
    assert authority.state is failed
    with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
        namespace[
            "_c6_broker_native_core_v1_apply_job_notification"
        ](authority, failed, dispatch_result)
    assert side_effect_calls == []


@pytest.mark.parametrize(
    ("first", "second", "expected_failure"),
    (
        ((6, 101), (6, 101), "duplicate-new-process"),
        ((7, 101), (7, 101), "duplicate-or-conflicting-process-exit"),
        ((7, 101), (8, 101), "duplicate-or-conflicting-process-exit"),
        ((4, None), (4, None), "job-notification-after-active-process-zero"),
        ((4, None), (6, 101), "job-notification-after-active-process-zero"),
    ),
)
def test_broker_native_job_notification_reducer_rejects_duplicate_or_contradictory_events(
    first: tuple[int, int | None],
    second: tuple[int, int | None],
    expected_failure: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_job_notification_reducer_test_namespace(module)
    _core, _attempt, _manifest, authority, _trace = (
        _broker_native_job_notification_attempt(namespace)
    )
    first_result = _broker_native_job_notification_dispatch(
        namespace,
        (),
        *first,
    )
    state = namespace[
        "_c6_broker_native_core_v1_apply_job_notification"
    ](authority, authority.state, first_result)
    second_result = _broker_native_job_notification_dispatch(
        namespace,
        (),
        *second,
    )

    failed = namespace[
        "_c6_broker_native_core_v1_apply_job_notification"
    ](authority, state, second_result)

    assert failed.events is state.events
    assert failed.event_ordinal == state.event_ordinal
    assert failed.terminal_failure == expected_failure
    assert failed.failure_dispatch_result is second_result
    assert failed.overall_success_authority == "forbidden"
    assert side_effect_calls == []


