@pytest.mark.parametrize("forgery", ("plain-tuple", "reconstructed", "cross-attempt"))
def test_broker_native_job_notification_reducer_rejects_unbound_state_before_event_consumption(
    forgery: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
