def _broker_native_ack_status_wire(payload: bytes) -> bytes:
    return len(payload).to_bytes(4, "little") + payload


def _broker_native_constructor_control_payload(
    kind: str,
    *,
    replacements: dict[str, object] | None = None,
) -> bytes:
    document: dict[str, object] = {
        "constructor_class": "guarded-target-or-native-leaf",
        "constructor_attribute_set_sha256": "c" * 64,
        "creation_time_100ns": 10_001,
        "descriptor_nonce": "0123456789abcdef0123456789abcdef",
        "descriptor_sha256": "b" * 64,
        "kind": kind,
        "pid": 101,
        "protocol_version": (
            "complete-suite-native-constructor-state-machine-v1"
        ),
    }
    if replacements is not None:
        document.update(replacements)
    return json.dumps(
        document,
        ensure_ascii=False,
        allow_nan=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8", errors="strict")


def _broker_native_begin_job_notification_authority(
    namespace: dict[str, object],
    resource_manifest: object,
) -> object:
    return namespace[
        "_c6_broker_native_core_v1_begin_job_notification_ledger"
    ](resource_manifest)


def _broker_native_test_bind_ack_status_expectation_authority(
    namespace: dict[str, object],
    attempt_authority: object,
    resource_manifest: object,
    connected_endpoint: object,
    *,
    grammar_context: str,
    expected_payloads: tuple[bytes, ...],
    process_target: object | None = None,
) -> object:
    if process_target is None:
        process_target = resource_manifest.process_targets[0]
    binding_type = namespace[
        "_C6BrokerNativeCoreV1AckStatusExpectationAuthority"
    ]
    binding = object.__new__(binding_type)
    binding._attempt_authority = attempt_authority
    binding._resource_manifest = resource_manifest
    binding._endpoint = connected_endpoint
    binding._process_target = process_target
    binding._grammar_context = grammar_context
    binding._expected_payloads = expected_payloads
    attempt_authority._success_ack_status_expectation_authority = binding
    return binding


def _broker_native_ack_status_protocol_attempt(
    namespace: dict[str, object],
    *,
    grammar_context: str = "ordinary-root",
    expected_payloads: tuple[bytes, ...] | None = None,
) -> tuple[object, object, object, object, object, list[object]]:
    if expected_payloads is None:
        expected_payloads = (
            _broker_native_constructor_control_payload("ack"),
            b'{"kind":"terminal"}',
        )
    prepared_endpoint = _broker_native_connect_drain_endpoints(
        namespace,
        (1,),
    )[0]
    _core, attempt_authority, resource_manifest, trace = (
        _broker_native_success_resource_reconciliation_attempt(
            namespace,
            prepared_endpoints=(prepared_endpoint,),
        )
    )
    connected_endpoint = namespace[
        "_c6_broker_native_core_v1_copy_endpoint_connect_consumed"
    ](prepared_endpoint)
    _broker_native_begin_job_notification_authority(
        namespace,
        resource_manifest,
    )
    expectation_authority = (
        _broker_native_test_bind_ack_status_expectation_authority(
            namespace,
            attempt_authority,
            resource_manifest,
            connected_endpoint,
            grammar_context=grammar_context,
            expected_payloads=expected_payloads,
        )
    )
    protocol_authority = namespace[
        "_c6_broker_native_core_v1_begin_ack_status_protocol"
    ](expectation_authority)
    return (
        attempt_authority,
        resource_manifest,
        protocol_authority,
        protocol_authority.state,
        connected_endpoint,
        trace,
    )


def _broker_native_ack_status_live_read_issue(
    namespace: dict[str, object],
    state: object,
) -> tuple[object, object]:
    request_bytes = min(
        65_536,
        state.manifest.byte_cap - state.completed_wire_bytes + 1,
    )
    native_buffer = ctypes.create_string_buffer(request_bytes)
    operation = namespace[
        "_C6BrokerNativeCoreV1PipeOperation"
    ](
        state.manifest.endpoint,
        "read",
        "LIVE_AWAIT_PACKET",
        b"\x00" * request_bytes,
        native_buffer,
        request_bytes,
        None,
        None,
        state.manifest.byte_cap,
        state.completed_wire_bytes,
        True,
    )
    issue_result = namespace[
        "_C6BrokerNativeCoreV1PipeIssueResult"
    ](
        (operation,),
        operation,
        "live-await-packet",
        None,
        False,
    )
    return operation, issue_result


def _broker_native_ack_status_successful_read_dispatch(
    namespace: dict[str, object],
    operation: object,
    payload: bytes,
) -> object:
    ctypes.memmove(
        ctypes.addressof(operation.native_buffer),
        payload,
        len(payload),
    )
    return namespace[
        "_C6BrokerNativeCoreV1PipeDispatchResult"
    ](
        (),
        "successful-read-completion",
        operation,
        len(payload),
        None,
        payload,
        None,
        None,
        None,
        False,
    )


def _broker_native_ack_status_apply_read(
    namespace: dict[str, object],
    protocol_authority: object,
    state: object,
    payload: bytes,
) -> tuple[object, object]:
    operation, issue_result = _broker_native_ack_status_live_read_issue(
        namespace,
        state,
    )
    live_state = namespace[
        "_c6_broker_native_core_v1_apply_ack_status_issue_result"
    ](protocol_authority, state, issue_result)
    dispatch_result = _broker_native_ack_status_successful_read_dispatch(
        namespace,
        operation,
        payload,
    )
    next_state = namespace[
        "_c6_broker_native_core_v1_apply_ack_status_dispatch_result"
    ](protocol_authority, live_state, dispatch_result)
    return live_state, next_state


