def test_broker_native_ack_status_protocol_reducer_static_surface_has_no_native_or_publication_authority(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    source = (
        module._launch_broker_native_ack_status_protocol_reducer_source_fragment()
        .source_bytes
    )
    tree = ast.parse(source.decode("ascii"))
    imports = tuple(
        node
        for node in ast.walk(tree)
        if isinstance(node, (ast.Import, ast.ImportFrom))
    )
    top_level_calls = tuple(
        node
        for statement in tree.body
        if not isinstance(statement, (ast.ClassDef, ast.FunctionDef))
        for node in ast.walk(statement)
        if isinstance(node, ast.Call)
    )
    member_calls = tuple(
        node.func.attr
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
    )

    assert imports == ()
    assert top_level_calls == ()
    for forbidden in (
        "read_file",
        "write_file",
        "get_queued_completion_status",
        "wait_for_single_object",
        "get_exit_code_process",
        "query_job_information",
        "cancel_io",
        "close_handle",
        "terminate_job",
        "create_process",
        "resume_thread",
    ):
        assert forbidden not in member_calls
    assert b"publish" not in source.lower()
    assert b"overall_success = True" not in source
    namespace = _broker_native_ack_status_protocol_test_namespace(module)
    with pytest.raises(
        RuntimeError,
        match=r"^GUARDED_BOOTSTRAP_INVALID$",
    ):
        namespace[
            "_C6BrokerNativeCoreV1AckStatusExpectationAuthority"
        ]()
    assert (
        "_c6_broker_native_core_v1_bind_ack_status_expectation_authority"
        not in namespace
    )
    assert side_effect_calls == []


def test_broker_native_ack_status_protocol_reducer_source_extractor_rejects_mutants(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    fragment = (
        module._launch_broker_native_ack_status_protocol_reducer_source_fragment()
    )
    mutations = (
        (
            fragment.dispatch_source_sha256.encode("ascii"),
            b"0" * 64,
        ),
        (
            fragment.resource_source_sha256.encode("ascii"),
            b"1" * 64,
        ),
        (
            b'"single-bound-ack-status-endpoint-only"',
            b'"overall-run"',
        ),
        (
            b'"protocol-convergence-candidate"',
            b'"overall-success"',
        ),
        (
            b"_C6_BROKER_NATIVE_CORE_V1_ACK_STATUS_PAYLOAD_CAP_BYTES = 65536",
            b"_C6_BROKER_NATIVE_CORE_V1_ACK_STATUS_PAYLOAD_CAP_BYTES = 65537",
        ),
    )
    sources = [
        fragment.source_bytes.replace(before, after, 1)
        for before, after in mutations
    ]
    sources.extend(
        (
            b"import os\n" + fragment.source_bytes,
            fragment.source_bytes + b"core.pipe_io.read_file()\n",
            fragment.source_bytes
            + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN\n",
            fragment.source_bytes
            + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END\n",
        )
    )
    assert all(source != fragment.source_bytes for source in sources)

    for source in sources:
        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ):
            module._launch_extract_broker_native_ack_status_protocol_reducer_source_fragment(
                source
            )
    assert side_effect_calls == []


