def test_broker_native_ack_status_protocol_reducer_accepts_fragmented_frames_then_immediate_eof(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_ack_status_protocol_test_namespace(module)
    (
        attempt_authority,
        resource_manifest,
        protocol_authority,
        state,
        connected_endpoint,
        _trace,
    ) = _broker_native_ack_status_protocol_attempt(namespace)
    expected_wire = b"".join(
        _broker_native_ack_status_wire(payload)
        for payload in (
            _broker_native_constructor_control_payload("ack"),
            b'{"kind":"terminal"}',
        )
    )
    chunks = (
        expected_wire[:2],
        expected_wire[2:11],
        expected_wire[11:-3],
        expected_wire[-3:],
    )

    for chunk in chunks:
        _live_state, state = _broker_native_ack_status_apply_read(
            namespace,
            protocol_authority,
            state,
            chunk,
        )

    assert state.manifest.endpoint is connected_endpoint
    assert state.completed_wire_bytes == len(expected_wire)
    assert state.received_wire_bytes == expected_wire
    assert state.buffered_wire_bytes == b""
    assert state.observed_frame_kinds == ("ack", "terminal")
    assert state.required_terminal_frames_complete is True
    assert state.required_eofs_complete is False
    assert state.zero_outstanding_io is False
    assert state.action == "issue-read"
    assert state.overall_success_authority == "forbidden"

    immediate_eof = namespace[
        "_C6BrokerNativeCoreV1PipeIssueResult"
    ]((), None, "immediate-eof", 109, False)
    state = namespace[
        "_c6_broker_native_core_v1_apply_ack_status_issue_result"
    ](protocol_authority, state, immediate_eof)

    assert state.required_terminal_frames_complete is True
    assert state.required_eofs_complete is True
    assert state.zero_outstanding_io is True
    assert state.protocol_failure is None
    assert state.action == "protocol-convergence-candidate"
    assert state.convergence_scope == "single-bound-ack-status-endpoint-only"
    assert protocol_authority.state is state
    assert attempt_authority.success_resource_manifest is resource_manifest
    assert attempt_authority.success_ack_status_authority is protocol_authority
    assert side_effect_calls == []


