@pytest.mark.parametrize(
    ("failure_case", "expected_failure"),
    (
        ("oversized-length", "frame-payload-cap-exceeded"),
        ("out-of-order", "unexpected-frame-bytes"),
        ("trailing", "trailing-wire-bytes-after-terminal"),
        ("premature-eof", "premature-eof"),
        ("zero-byte-read", "successful-zero-byte-read-failure"),
    ),
)
def test_broker_native_ack_status_protocol_reducer_fails_closed_on_wire_or_io_failure(
    failure_case: str,
    expected_failure: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_ack_status_protocol_test_namespace(module)
    (
        _attempt,
        _resource,
        protocol_authority,
        state,
        _endpoint,
        _trace,
    ) = _broker_native_ack_status_protocol_attempt(namespace)
    ack_wire = _broker_native_ack_status_wire(
        _broker_native_constructor_control_payload("ack")
    )
    terminal_wire = _broker_native_ack_status_wire(
        b'{"kind":"terminal"}'
    )

    if failure_case == "premature-eof":
        event = namespace[
            "_C6BrokerNativeCoreV1PipeIssueResult"
        ]((), None, "immediate-eof", 109, False)
        state = namespace[
            "_c6_broker_native_core_v1_apply_ack_status_issue_result"
        ](protocol_authority, state, event)
    elif failure_case == "zero-byte-read":
        operation, issue_result = _broker_native_ack_status_live_read_issue(
            namespace,
            state,
        )
        live_state = namespace[
            "_c6_broker_native_core_v1_apply_ack_status_issue_result"
        ](protocol_authority, state, issue_result)
        event = namespace[
            "_C6BrokerNativeCoreV1PipeDispatchResult"
        ](
            (),
            "successful-zero-byte-read-failure",
            operation,
            0,
            None,
            b"",
            None,
            None,
            None,
            False,
        )
        state = namespace[
            "_c6_broker_native_core_v1_apply_ack_status_dispatch_result"
        ](protocol_authority, live_state, event)
    else:
        wire = (
            (65_537).to_bytes(4, "little")
            if failure_case == "oversized-length"
            else terminal_wire
            if failure_case == "out-of-order"
            else ack_wire + terminal_wire + b"x"
        )
        _live_state, state = _broker_native_ack_status_apply_read(
            namespace,
            protocol_authority,
            state,
            wire,
        )

    assert state.action == "protocol-failure"
    assert state.protocol_failure == expected_failure
    assert state.required_eofs_complete is False
    assert state.zero_outstanding_io is False
    assert state.overall_success_authority == "forbidden"
    with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
        namespace[
            "_c6_broker_native_core_v1_apply_ack_status_issue_result"
        ](
            protocol_authority,
            state,
            namespace["_C6BrokerNativeCoreV1PipeIssueResult"](
                (), None, "immediate-eof", 109, False
            ),
        )
    assert side_effect_calls == []


