def _broker_native_go_writer_protocol_prerequisites(
    namespace: dict[str, object],
    *,
    ack_payload: bytes | None = None,
) -> tuple[
    object,
    object,
    object,
    object,
    object,
    list[object],
]:
    if ack_payload is None:
        ack_payload = _broker_native_constructor_control_payload("ack")
    prepared_ack, prepared_go = _broker_native_connect_drain_endpoints(
        namespace,
        (1, 2),
    )
    _core, attempt_authority, resource_manifest, trace = (
        _broker_native_success_resource_reconciliation_attempt(
            namespace,
            prepared_endpoints=(prepared_ack, prepared_go),
        )
    )
    copy_connected = namespace[
        "_c6_broker_native_core_v1_copy_endpoint_connect_consumed"
    ]
    connected_ack = copy_connected(prepared_ack)
    connected_go = copy_connected(prepared_go)
    _broker_native_begin_job_notification_authority(
        namespace,
        resource_manifest,
    )
    ack_expectation_authority = (
        _broker_native_test_bind_ack_status_expectation_authority(
            namespace,
            attempt_authority,
            resource_manifest,
            connected_ack,
            grammar_context="ordinary-root",
            expected_payloads=(
                ack_payload,
                b'{"kind":"terminal"}',
            ),
        )
    )
    ack_authority = namespace[
        "_c6_broker_native_core_v1_begin_ack_status_protocol"
    ](ack_expectation_authority)
    _live_ack_state, ack_state = _broker_native_ack_status_apply_read(
        namespace,
        ack_authority,
        ack_authority.state,
        _broker_native_ack_status_wire(ack_payload),
    )
    return (
        attempt_authority,
        resource_manifest,
        ack_authority,
        ack_state,
        connected_go,
        trace,
    )


