def test_broker_native_go_writer_protocol_reducer_retires_partial_writes_before_close_eligibility(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_go_writer_protocol_test_namespace(module)
    (
        _attempt,
        _resource,
        ack_authority,
        ack_state,
        go_authority,
        state,
        connected_go,
        _trace,
    ) = _broker_native_go_writer_protocol_attempt(namespace)
    wire_bytes = _broker_native_ack_status_wire(
        _broker_native_constructor_control_payload("go")
    )

    operation, issue_result = _broker_native_go_live_write_issue(
        namespace,
        state,
    )
    live_state = namespace[
        "_c6_broker_native_core_v1_apply_go_writer_issue_result"
    ](go_authority, state, issue_result)
    partial_dispatch = _broker_native_go_successful_write_dispatch(
        namespace,
        operation,
        5,
    )
    state = namespace[
        "_c6_broker_native_core_v1_apply_go_writer_dispatch_result"
    ](go_authority, live_state, partial_dispatch)

    assert state.manifest.endpoint is connected_go
    assert state.manifest.wire_bytes == wire_bytes
    assert state.manifest.byte_cap == 65_540
    assert state.completed_wire_bytes == 5
    assert state.write_cursor == 5
    assert state.ledger == ()
    assert state.action == "issue-write"
    assert state.go_frame_complete is False
    assert state.writer_close_eligible is False
    assert state.zero_outstanding_io is False
    assert go_authority.writer_close_capability is None

    operation, issue_result = _broker_native_go_live_write_issue(
        namespace,
        state,
    )
    live_state = namespace[
        "_c6_broker_native_core_v1_apply_go_writer_issue_result"
    ](go_authority, state, issue_result)
    final_dispatch = _broker_native_go_successful_write_dispatch(
        namespace,
        operation,
        operation.request_bytes,
    )
    state = namespace[
        "_c6_broker_native_core_v1_apply_go_writer_dispatch_result"
    ](go_authority, live_state, final_dispatch)

    assert state.completed_wire_bytes == len(wire_bytes)
    assert state.write_cursor == len(wire_bytes)
    assert state.ledger == ()
    assert state.action == "close-now-idle-writer"
    assert state.go_frame_complete is True
    assert state.writer_close_eligible is True
    assert state.zero_outstanding_io is True
    assert state.required_peer_eof_complete is False
    assert state.protocol_failure is None
    assert state.overall_success_authority == "forbidden"
    assert state.convergence_scope == "single-bound-go-writer-only"
    assert go_authority.state is state
    assert ack_authority.state is ack_state
    assert ack_authority.go_writer_protocol_authority is go_authority
    assert go_authority.writer_close_capability is None
    assert side_effect_calls == []


