    if forgery == "plain-tuple":
        candidate = tuple(capability.manifest)
    elif forgery == "reconstructed":
        candidate = object.__new__(type(capability))
        candidate._manifest = capability.manifest
        candidate._phase = capability.phase
        candidate._receipt = None
    elif forgery == "foreign":
        (
            _attempt_two,
            _resource_two,
            _ack_two,
            _ack_state_two,
            go_two,
            initial_two,
            _connected_two,
            _trace_two,
        ) = _broker_native_go_writer_protocol_attempt(namespace)
        _op_two, _live_two, final_two = _broker_native_complete_go_writer(
            namespace,
            go_two,
            initial_two,
        )
        candidate = mint(go_two, final_two)
        foreign_context = (
            go_two,
            final_two,
            _connected_two,
            _trace_two,
            len(_trace_two),
        )
    else:
        manifest_fields = list(capability.manifest)
        manifest_fields[2 if forgery == "stale-state-manifest" else 8] = (
            initial_state
            if forgery == "stale-state-manifest"
            else ack_authority.manifest.endpoint
        )
        capability._manifest = tuple.__new__(
            type(capability.manifest),
            tuple(manifest_fields),
        )
        candidate = capability
    boundary = len(trace)

    if forgery in ("plain-tuple", "reconstructed"):
        with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
            namespace[
                "_c6_broker_native_core_v1_authenticate_go_writer_close_capability"
            ](candidate)
    else:
        if forgery == "foreign":
            go_authority._writer_close_capability = candidate
        with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
            namespace[
                "_c6_broker_native_core_v1_consume_go_writer_close_capability"
            ](go_authority, final_state)
    assert trace[boundary:] == []
    if forgery == "foreign":
        assert foreign_context is not None
        (
            foreign_go,
            foreign_state,
            foreign_endpoint,
            foreign_trace,
            foreign_boundary,
        ) = foreign_context
        receipt = namespace[
            "_c6_broker_native_core_v1_consume_go_writer_close_capability"
        ](foreign_go, foreign_state)
        assert receipt.capability is candidate
        assert foreign_trace[foreign_boundary:] == [
            ("unexpected-close", foreign_endpoint.server_handle)
        ]
    assert side_effect_calls == []


