def test_broker_native_constructor_runtime_prefix_rejects_component_mutants(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    draft = (
        module._launch_extract_broker_native_control_plane_candidate_from_bootstrap_source(
            BOOTSTRAP_PATH.read_bytes()
        )
    )
    components = module._launch_broker_native_constructor_runtime_prefix_components(
        draft_fragment=draft
    )
    fragment = (
        module._launch_broker_native_constructor_runtime_prefix_source_fragment(
            draft_fragment=draft
        )
    )
    sources = (
        b"".join((components[0], components[2], components[1], *components[3:])),
        fragment.source_bytes[: -len(components[-1])],
        fragment.source_bytes + components[-1],
        fragment.source_bytes.replace(
            fragment.component_sha256s[-2].encode("ascii"),
            b"0" * 64,
            1,
        ),
        fragment.source_bytes.replace(
            b"_C6_BROKER_NATIVE_CORE_V1_WAIT_TIMEOUT = 258",
            b"_C6_BROKER_NATIVE_CORE_V1_WAIT_TIMEOUT = 259",
            1,
        ),
        fragment.source_bytes
        + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN\n",
        fragment.source_bytes
        + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END\n",
    )
    assert all(source != fragment.source_bytes for source in sources)

    for source in sources:
        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ):
            module._launch_extract_broker_native_constructor_runtime_prefix_source_fragment(
                source
            )
    assert side_effect_calls == []


