def test_broker_native_guarded_target_precreation_installs_slot_ownership_before_reentrant_helpers_without_claim_cleanup(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    source = module._launch_broker_native_guarded_target_precreation_source_fragment().source_bytes.decode(
        "ascii"
    )
    tree = ast.parse(source)
    binder = next(
        node
        for node in tree.body
        if isinstance(node, ast.FunctionDef)
        and node.name
        == "_c6_broker_native_core_v1_bind_guarded_target_precreation_exports"
    )
    functions = {
        node.name: node
        for node in binder.body
        if isinstance(node, ast.FunctionDef)
    }

    begin_source = ast.get_source_segment(
        source,
        functions["_c6_broker_native_core_v1_begin_guarded_target_precreation"],
    )
    bind_source = ast.get_source_segment(
        source,
        functions["_c6_broker_native_core_v1_bind_guarded_target_precreation_facts"],
    )
    assert begin_source is not None and bind_source is not None
    assert "trusted_begin_claims" not in begin_source
    assert "trusted_consumed_attempts" not in begin_source
    assert "trusted_bind_claims" not in bind_source
    assert "finally:" not in begin_source
    assert "finally:" not in bind_source
    assert begin_source.find("ownership_installed = True") < begin_source.find(
        "decode_and_revalidate_request("
    )
    assert bind_source.find('"binding"') < bind_source.find(
        "_c6_broker_native_core_v1_authenticate_guarded_target_precreation_authority("
    )
    assert side_effect_calls == []


def test_broker_native_guarded_target_precreation_begin_claim_cleans_base_exception_and_allows_retry(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    namespace = _broker_native_guarded_target_precreation_test_namespace(
        module
    )
    attempt, _resources, trace, clock_calls = (
        _broker_native_guarded_target_precreation_attempt(namespace)
    )
    begin = namespace[
        "_c6_broker_native_core_v1_begin_guarded_target_precreation"
    ]
    journal = _broker_native_guarded_target_precreation_closure_value(
        begin,
        "trusted_journal",
    )
    original_clock = attempt._monotonic_ns

    class BeginClaimProbe(BaseException):
        pass

    failure = BeginClaimProbe("begin-claim-probe")

    def faulting_clock() -> int:
        raise failure

    attempt._monotonic_ns = faulting_clock
    attempt._state._monotonic_ns = faulting_clock
    with pytest.raises(BeginClaimProbe) as raised:
        begin(
            attempt,
            _broker_native_guarded_target_precreation_payload(),
            2_000,
        )
    assert raised.value is failure
    assert all(entry[0] is not attempt for entry in journal)

    attempt._monotonic_ns = original_clock
    attempt._state._monotonic_ns = original_clock
    authority = begin(
        attempt,
        _broker_native_guarded_target_precreation_payload(),
        2_000,
    )
    matching_entries = [
        entry
        for entry in journal
        if entry[0] is attempt and entry[2] is authority
    ]
    assert len(matching_entries) == 1
    assert authority.phase == "request-bound"
    assert clock_calls == [1_000]
    assert trace == []
    assert side_effect_calls == []


