def test_broker_native_guarded_target_precreation_deadline_and_unbound_arguments_reject_without_consumption(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    monkeypatch.setattr(os, "urandom", lambda size: bytes(range(size)))
    namespace = _broker_native_guarded_target_precreation_test_namespace(
        module
    )
    payload = _broker_native_guarded_target_precreation_payload()
    begin = namespace[
        "_c6_broker_native_core_v1_begin_guarded_target_precreation"
    ]

    for deadline in (True, 0, 1_000):
        attempt, _resources, trace, clock_calls = (
            _broker_native_guarded_target_precreation_attempt(
                namespace,
                id_offset=100 + int(deadline),
            )
        )
        with pytest.raises(
            RuntimeError,
            match=r"^GUARDED_BOOTSTRAP_INVALID$",
        ):
            begin(attempt, payload, deadline)
        authority = begin(attempt, payload, 2_000)
        assert authority.phase == "request-bound"
        assert clock_calls == ([1_000] if deadline is True or deadline == 0 else [1_000, 1_000])
        assert trace == []

    attempt, _resources, trace, clock_calls = (
        _broker_native_guarded_target_precreation_attempt(
            namespace,
            id_offset=500,
        )
    )
    with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
        begin(attempt, payload, 2_000, "unexpected")
    assert begin(attempt, payload, 2_000).phase == "request-bound"
    assert clock_calls == [1_000]
    assert trace == []
    assert side_effect_calls == []


def test_broker_native_guarded_target_precreation_identity_journal_rejects_reconstruction_cross_attempt_mutation_and_replay(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    monkeypatch.setattr(os, "urandom", lambda size: bytes(range(size)))
    namespace = _broker_native_guarded_target_precreation_test_namespace(
        module
    )
    attempt, _resources, trace, _clock_calls = (
        _broker_native_guarded_target_precreation_attempt(namespace)
    )
    other_attempt, _other_resources, other_trace, _other_clock_calls = (
        _broker_native_guarded_target_precreation_attempt(
            namespace,
            id_offset=100,
        )
    )
    payload = _broker_native_guarded_target_precreation_payload()
    begin = namespace[
        "_c6_broker_native_core_v1_begin_guarded_target_precreation"
    ]
    bind = namespace[
        "_c6_broker_native_core_v1_bind_guarded_target_precreation_facts"
    ]
    authenticate = namespace[
        "_c6_broker_native_core_v1_authenticate_guarded_target_precreation_authority"
    ]
    authority = begin(attempt, payload, 2_000)

    with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
        begin(attempt, payload, 2_000)

    reconstructed = object.__new__(type(authority))
    reconstructed._attempt_authority = authority.attempt_authority
    reconstructed._request_receipt = authority.request_receipt
    reconstructed._absolute_deadline_monotonic_ns = (
        authority.absolute_deadline_monotonic_ns
    )
    reconstructed._manifest = authority.manifest
    reconstructed._phase = authority.phase
    with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
        authenticate(reconstructed)

    original_receipt = authority._request_receipt
    authority._request_receipt = namespace[
        "_C6BrokerNativeCoreV1GuardedTargetRequestReceipt"
    ](*original_receipt)
    with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
        authenticate(authority)
    authority._request_receipt = original_receipt

    authority._attempt_authority = other_attempt
    with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
        authenticate(authority)
    authority._attempt_authority = attempt

    authority._phase = "precreation-frozen"
    with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
        authenticate(authority)
    authority._phase = "request-bound"
    assert authenticate(authority) is authority

    manifest = bind(authority)
    assert manifest is authority.manifest
    assert authority.phase == "precreation-frozen"
    assert authenticate(authority) is authority
    with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
        bind(authority)
    with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
        bind(authority, "unexpected")
    assert trace == []
    assert other_trace == []
    assert side_effect_calls == []


def test_broker_native_guarded_target_precreation_freezes_policy_limit_topology_resources_and_eight_internal_addresses(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    generated = iter(
        (
            bytes(range(16)),
            bytes(range(16, 32)),
            bytes(range(32, 48)),
        )
    )
    urandom_calls: list[int] = []

    def fake_urandom(size: int) -> bytes:
        urandom_calls.append(size)
        return next(generated)

    monkeypatch.setattr(os, "urandom", fake_urandom)
    namespace = _broker_native_guarded_target_precreation_test_namespace(
        module
    )
    payload = _broker_native_guarded_target_precreation_payload()
    begin = namespace[
        "_c6_broker_native_core_v1_begin_guarded_target_precreation"
    ]
    bind = namespace[
        "_c6_broker_native_core_v1_bind_guarded_target_precreation_facts"
    ]
    authenticate = namespace[
        "_c6_broker_native_core_v1_authenticate_guarded_target_precreation_authority"
    ]
    expected_roles = (
        "descriptor",
        "ack-status",
        "go",
        "broker-request",
        "broker-response",
        "stdin",
        "stdout",
        "stderr",
    )
    expected_address_facts = {
        "descriptor": ("writes", "PIPE_ACCESS_OUTBOUND", "GENERIC_READ"),
        "ack-status": ("reads", "PIPE_ACCESS_INBOUND", "GENERIC_WRITE"),
        "go": ("writes", "PIPE_ACCESS_OUTBOUND", "GENERIC_READ"),
        "broker-request": ("reads", "PIPE_ACCESS_INBOUND", "GENERIC_WRITE"),
        "broker-response": ("writes", "PIPE_ACCESS_OUTBOUND", "GENERIC_READ"),
        "stdin": ("writes", "PIPE_ACCESS_OUTBOUND", "GENERIC_READ"),
        "stdout": ("reads", "PIPE_ACCESS_INBOUND", "GENERIC_WRITE"),
        "stderr": ("reads", "PIPE_ACCESS_INBOUND", "GENERIC_WRITE"),
    }

    for ordinal, (job_count, expected_topology) in enumerate(
        (
            (2, "initial-guarded-target"),
            (3, "nested-guarded-target"),
            (4, "nested-guarded-target"),
        )
    ):
        attempt, resources, trace, clock_calls = (
            _broker_native_guarded_target_precreation_attempt(
                namespace,
                job_count=job_count,
                id_offset=ordinal * 100,
            )
        )
        authority = begin(attempt, payload, 2_000)
        manifest = bind(authority)

        assert manifest.attempt_authority is attempt
        assert manifest.request_receipt is authority.request_receipt
        assert manifest.absolute_deadline_monotonic_ns == 2_000
        policy = manifest.constructor_policy_projection
        assert type(policy) is namespace[
            "_C6BrokerNativeCoreDraftPolicyProjection"
        ]
        assert policy.implementation_id == "broker-native-core-v1"
        assert policy.constructor_class == "guarded-target-or-native-leaf"
        assert policy.subject_kind == "guarded-python-target"
        assert policy.attributes is namespace[
            "_C6_BROKER_NATIVE_CORE_DRAFT_LEAF_ATTRIBUTES"
        ]
        assert policy.direct_child_authority == "none"
        selection = manifest.guarded_target_limit_selection
        assert type(selection) is namespace[
            "_C6BrokerNativeCoreDraftLimitSelection"
        ]
        assert selection.table_id == "guarded-python-target"
        assert selection.row[0] == "pytest_capture"
        assert manifest.topology_id == expected_topology
        assert manifest.job_topology_sha256 == namespace[
            "_C6_BROKER_NATIVE_CORE_DRAFT_JOB_TOPOLOGY_REGISTRY"
        ].job_topology_sha256
        assert manifest.explicit_job_list_resources is (
            attempt.state.owned_job_resources
        )
        assert len(manifest.explicit_job_list_resources) == len(resources)
        assert all(
            actual is expected
            for actual, expected in zip(
                manifest.explicit_job_list_resources,
                resources,
            )
        )
        assert type(manifest.explicit_job_list_projection) is namespace[
            "_C6BrokerNativeCoreDraftJobListProjection"
        ]
        assert (
            manifest.explicit_job_list_projection.explicit_job_list_ids
            == tuple(resource.owned_job.logical_job_id for resource in resources)
        )
        assert len(manifest.channel_token) == 32
        assert manifest.channel_token == manifest.channel_token.lower()
        assert all(
            character in "0123456789abcdef"
            for character in manifest.channel_token
        )
        assert type(manifest.channel_addresses) is tuple
        assert tuple(
            address.fixed_role for address in manifest.channel_addresses
        ) == expected_roles
        assert len({id(address) for address in manifest.channel_addresses}) == 8
        assert len({address.pipe_name for address in manifest.channel_addresses}) == 8
        for address in manifest.channel_addresses:
            assert type(address) is namespace[
                "_C6BrokerNativeCoreDraftInternalChannelAddress"
            ]
            assert address.token == manifest.channel_token
            assert (
                address.parent_action,
                address.server_open_mode,
                address.child_access,
            ) == expected_address_facts[address.fixed_role]
            assert address.pipe_name == (
                r"\\.\pipe\kokoroarc-c6-control-"
                + manifest.channel_token
                + "-"
                + address.fixed_role
            )
        assert authenticate(authority) is authority
        assert clock_calls == [1_000]
        assert trace == []
        rendered = repr(authority)
        assert payload.decode("ascii").strip() not in rendered
        assert manifest.channel_token not in rendered

    assert urandom_calls == [16, 16, 16]
    assert side_effect_calls == []


