def test_broker_native_guarded_target_precreation_reachable_graph_checks_duplicate_before_exact_512_cap(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    source = module._launch_broker_native_guarded_target_precreation_source_fragment().source_bytes.decode(
        "ascii"
    )
    tree = ast.parse(source)
    binder = next(
        node
        for node in tree.body
        if isinstance(node, ast.FunctionDef)
        and node.name
        == "_c6_broker_native_core_v1_bind_guarded_target_precreation_exports"
    )
    loop = next(
        node
        for node in binder.body
        if isinstance(node, ast.While)
        and "trusted_json_pending_reachable_values" in (
            ast.get_source_segment(source, node.test) or ""
        )
    )
    duplicate_index = next(
        index
        for index, node in enumerate(loop.body)
        if isinstance(node, ast.If)
        and any(isinstance(item, ast.Continue) for item in node.body)
    )
    cap_index = next(
        index
        for index, node in enumerate(loop.body)
        if isinstance(node, ast.If)
        and "trusted_json_visited_reachable_values" in (
            ast.get_source_segment(source, node.test) or ""
        )
        and "512" in (ast.get_source_segment(source, node.test) or "")
    )
    append_index = next(
        index
        for index, node in enumerate(loop.body)
        if isinstance(node, ast.Expr)
        and "trusted_json_visited_reachable_values" in (
            ast.get_source_segment(source, node) or ""
        )
    )
    cap = loop.body[cap_index]
    assert isinstance(cap, ast.If)
    assert isinstance(cap.test, ast.Compare)
    assert len(cap.test.ops) == 1
    assert isinstance(cap.test.ops[0], ast.GtE)
    assert duplicate_index < cap_index < append_index
    assert side_effect_calls == []


