def test_broker_native_guarded_target_precreation_dependency_and_helper_state_seals_are_exhaustive() -> None:
    module = _preflight()
    namespace = _broker_native_guarded_target_precreation_test_namespace(module)
    begin = namespace["_c6_broker_native_core_v1_begin_guarded_target_precreation"]
    verifier = _broker_native_guarded_target_precreation_closure_value(
        begin, "authenticate_local_helper_trust"
    )
    helpers = _broker_native_guarded_target_precreation_closure_value(
        verifier, "trusted_local_helper_table"
    )
    behaviors = _broker_native_guarded_target_precreation_closure_value(
        verifier, "trusted_local_helper_behavior_table"
    )
    separately_sealed = {
        *(helper.__name__ for helper in helpers),
        "trusted_invalid", "trusted_runtime_error", "trusted_value_error",
        "trusted_attribute_error", "trusted_base_exception",
        "trusted_invalid_anchor", "trusted_runtime_error_anchor",
        "trusted_value_error_anchor", "trusted_attribute_error_anchor",
        "trusted_base_exception_anchor", "trusted_rejection_basis",
        "trusted_rejection_basis_a", "trusted_rejection_basis_b",
        "trusted_rejection_basis_c", "trusted_local_helper_table",
        "trusted_local_helper_table_anchor", "trusted_local_helper_verifier",
        "trusted_local_helper_behavior_table",
        "trusted_local_helper_behavior_table_anchor",
        "trusted_dependency_table", "trusted_dependency_table_anchor",
    }
    dependency_names = sorted(
        set().union(*(set(helper.__code__.co_freevars) for helper in helpers))
        - separately_sealed
    )
    dependencies = _broker_native_guarded_target_precreation_closure_value(
        verifier, "trusted_dependency_table"
    )
    assert len(helpers) == len(behaviors) == 24
    assert len(dependency_names) == len(dependencies) == 209
    for helper, state in zip(helpers, behaviors, strict=True):
        assert state == (
            helper, helper.__code__, helper.__defaults__, helper.__kwdefaults__,
            helper.__globals__, helper.__closure__, helper.__builtins__, state[7],
        )
        assert tuple(item[0] for item in state[7]) == helper.__code__.co_names
    for name, dependency in zip(dependency_names, dependencies, strict=True):
        assert _broker_native_guarded_target_precreation_closure_value(
            verifier, name
        ) is dependency
    source_tree = ast.parse(
        module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_BYTES
    )
    binder_node = next(
        node for node in source_tree.body
        if isinstance(node, ast.FunctionDef)
        and node.name
        == "_c6_broker_native_core_v1_bind_guarded_target_precreation_exports"
    )
    verifier_node = next(
        node for node in binder_node.body
        if isinstance(node, ast.FunctionDef)
        and node.name == "authenticate_local_helper_trust"
    )
    assert not any(
        isinstance(operator, (ast.Eq, ast.NotEq))
        for compare in ast.walk(verifier_node)
        if isinstance(compare, ast.Compare)
        for operator in compare.ops
    )
    literal_index_sets = {
        tuple(
            element.value for element in node.iter.elts
            if isinstance(element, ast.Constant)
        )
        for node in ast.walk(verifier_node)
        if isinstance(node, ast.For) and isinstance(node.iter, ast.Tuple)
    }
    assert tuple(range(209)) in literal_index_sets
    assert tuple(range(24)) in literal_index_sets
    mechanism_anchors = {
        "trusted_dependency_table": "trusted_dependency_table_anchor",
        "trusted_local_helper_table": "trusted_local_helper_table_anchor",
        "trusted_local_helper_behavior_table": (
            "trusted_local_helper_behavior_table_anchor"
        ),
    }
    for function_node in (
        node for node in ast.walk(binder_node)
        if isinstance(node, ast.FunctionDef)
    ):
        for table_name, anchor_name in mechanism_anchors.items():
            subscript_lines = [
                node.lineno for node in ast.walk(function_node)
                if isinstance(node, ast.Subscript)
                and isinstance(node.value, ast.Name)
                and node.value.id == table_name
            ]
            if not subscript_lines:
                continue
            guard_lines = [
                node.lineno for node in ast.walk(function_node)
                if isinstance(node, ast.Compare)
                and isinstance(node.left, ast.Name)
                and node.left.id == table_name
                and len(node.ops) == 1
                and isinstance(node.ops[0], ast.IsNot)
                and len(node.comparators) == 1
                and isinstance(node.comparators[0], ast.Name)
                and node.comparators[0].id == anchor_name
            ]
            assert guard_lines
            assert min(guard_lines) < min(subscript_lines)


