@pytest.mark.parametrize("entry_name", ("begin", "authenticate", "bind"))
def test_broker_native_guarded_target_precreation_checks_behavior_table_identity_before_subscript(
    entry_name: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    monkeypatch.setattr(os, "urandom", lambda size: bytes(range(size)))
    namespace = _broker_native_guarded_target_precreation_test_namespace(module)
    attempt, _resources, trace, clock_calls = (
        _broker_native_guarded_target_precreation_attempt(namespace)
    )
    begin = namespace["_c6_broker_native_core_v1_begin_guarded_target_precreation"]
    authenticate = namespace[
        "_c6_broker_native_core_v1_authenticate_guarded_target_precreation_authority"
    ]
    bind = namespace["_c6_broker_native_core_v1_bind_guarded_target_precreation_facts"]
    authority = (
        begin(attempt, _broker_native_guarded_target_precreation_payload(), 2_000)
        if entry_name != "begin"
        else None
    )
    target = {"begin": begin, "authenticate": authenticate, "bind": bind}[entry_name]
    table_cell = _broker_native_guarded_target_precreation_closure_cell(
        target, "trusted_local_helper_behavior_table"
    )
    original = table_cell.cell_contents
    dispatches: list[int] = []

    class SubscriptProbe:
        def __getitem__(self, index: int) -> object:
            dispatches.append(index)
            raise AssertionError("behavior table subscript dispatched")

    table_cell.cell_contents = SubscriptProbe()
    try:
        with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
            if entry_name == "begin":
                begin(
                    attempt,
                    _broker_native_guarded_target_precreation_payload(),
                    2_000,
                )
            elif entry_name == "authenticate":
                authenticate(authority)
            else:
                bind(authority)
    finally:
        table_cell.cell_contents = original
    assert dispatches == []
    if authority is None:
        assert clock_calls == []
    else:
        assert object.__getattribute__(authority, "_phase") == "request-bound"
    assert trace == []
    assert side_effect_calls == []


