def _task9_successor_source_inputs() -> tuple[bytes, bytes]:
    plan_root = Path(__file__).resolve().parents[2]
    plan = plan_root / "docs/superpowers/plans/2026-08-21-kokoroarc-complete-suite-campaign-6.md"
    producer = plan_root / (
        "docs/superpowers/plans/"
        "2026-08-21-kokoroarc-complete-suite-campaign-6-task9-transition.ps1"
    )
    return plan.read_bytes(), producer.read_bytes()


def test_task9_successor_source_contract_captures_exact_dormant_loader_and_producer() -> None:
    module = _preflight()
    plan_bytes, producer_bytes = _task9_successor_source_inputs()
    contract = module._launch_task9_successor_source_contract(
        plan_bytes, producer_bytes
    )
    assert contract.producer_relative_path == (
        "docs/superpowers/plans/"
        "2026-08-21-kokoroarc-complete-suite-campaign-6-task9-transition.ps1"
    )
    assert contract.producer_size == 196_512
    assert contract.producer_sha256 == (
        "e22ac3bb1f8f35ef3a7875ef118100868e766db316b50fae2abd73cd1a69b0b2"
    )
    assert contract.producer_blob == "6c3eb9fe48aab7ba8f4044e594d37849e88bc9fe"
    assert len(contract.loader_source_bytes) == 11_508
    assert sha256(contract.loader_source_bytes).hexdigest() == (
        "116583d65f752baa1b93d9db80617030a4f68f3caff95f4268b848e6528059db"
    )
    assert contract.loader_source_bytes.endswith(b"# C6-SUCCESSOR-LOADER-END\n")
    placeholders = re.findall(rb"<[^>\n]+>", contract.loader_source_bytes)
    assert len(placeholders) == 18
    assert len(set(placeholders)) == 12
    loader_end = plan_bytes.index(b"# C6-SUCCESSOR-LOADER-END\n")
    closing_fence = loader_end + len(b"# C6-SUCCESSOR-LOADER-END\n")
    assert plan_bytes[closing_fence : closing_fence + 4] == b"```\n"
    assert len(contract.verifier_source_bytes) == 39_689
    assert sha256(contract.verifier_source_bytes).hexdigest() == (
        "a84d12d48b95b820c2bbbbc301879cb90bb30aac6203a6cd3368c19fff78719c"
    )
    assert not hasattr(module, "_launch_task9_activate_successor")


