def test_task9_native_vector_validator_type_checks_contract_before_comparison() -> None:
    module = _preflight()
    dispatches: list[str] = []

    class ComparisonProbe:
        def __eq__(self, other: object) -> bool:
            dispatches.append("eq")
            return True

        def __ne__(self, other: object) -> bool:
            dispatches.append("ne")
            return False

    expected = "x"
    raw = (expected + "\x00").encode("utf-16-le")
    vector = module.command_plan._WindowsNativeVector(
        contract=ComparisonProbe(),
        utf16_units=len(raw) // 2,
        utf16le_sha256=sha256(raw).hexdigest(),
        command_line=expected,
    )
    with pytest.raises(RuntimeError, match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$"):
        module._launch_validate_task9_native_vector(vector, expected)
    assert dispatches == []


@pytest.mark.parametrize(
    "mutation", ("code", "global", "vector-type", "transitive-function")
)
def test_task9_vector_provenance_rejects_live_state_mutation(
    monkeypatch: pytest.MonkeyPatch,
    mutation: str,
) -> None:
    module = _preflight()
    builder = module.command_plan._windows_native_vector
    if mutation == "code":
        original_code = builder.__code__
        original_source = inspect.getsource(builder)

        def replacement(*args: object, **kwargs: object) -> object:
            raise AssertionError("mutated builder dispatched")

        monkeypatch.setattr(module.inspect, "getsource", lambda value: original_source)
        builder.__code__ = replacement.__code__.replace(
            co_freevars=original_code.co_freevars
        )
        try:
            with pytest.raises(RuntimeError, match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$"):
                module._launch_authenticate_task9_vector_provenance()
        finally:
            builder.__code__ = original_code
    elif mutation == "global":
        monkeypatch.setitem(builder.__globals__, "sha256", lambda value: None)
        with pytest.raises(RuntimeError, match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$"):
            module._launch_authenticate_task9_vector_provenance()
    elif mutation == "vector-type":
        monkeypatch.setattr(module.command_plan, "_WindowsNativeVector", tuple)
        with pytest.raises(RuntimeError, match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$"):
            module._launch_authenticate_task9_vector_provenance()
    else:
        dispatches: list[str] = []

        def forged_quote(value: str) -> str:
            dispatches.append("quote")
            return value

        monkeypatch.setattr(
            module.command_plan, "_quote_windows_native_argument", forged_quote
        )
        with pytest.raises(RuntimeError, match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$"):
            module._launch_authenticate_task9_vector_provenance()
        assert dispatches == []


