def test_task9_vector_provenance_raw_namespace_precedes_member_resolution() -> None:
    module = _preflight()
    source = inspect.getsource(module._launch_authenticate_task9_vector_provenance)
    tree = ast.parse(source)
    vector_namespace = source.index(
        'vector_namespace = basis[23](vector_type, "__dict__")'
    )
    raw_bases = source.index('basis[23](vector_type, "__bases__")')
    raw_mro = source.index('basis[23](vector_type, "__mro__")')
    raw_new = source.index('vector_namespace.get("__new__") is not None')
    constructor = source.index('constructor = vector_namespace.get("__init__")')
    assert vector_namespace < raw_bases < constructor
    assert vector_namespace < raw_mro < constructor
    assert vector_namespace < raw_new < constructor
    forbidden = {
        "_TASK9_SUCCESSOR_VECTOR_TRUSTED_TYPE.__init__",
        "_TASK9_SUCCESSOR_VECTOR_TRUSTED_TYPE.__new__",
        "vector_type.__init__",
        "vector_type.__new__",
    }
    assert all(token not in source for token in forbidden)
    constructor_assignments = [
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Assign)
        and any(
            isinstance(target, ast.Name) and target.id == "constructor"
            for target in node.targets
        )
    ]
    assert len(constructor_assignments) == 1
    assert isinstance(constructor_assignments[0].value, ast.Call)
    assert isinstance(constructor_assignments[0].value.func, ast.Attribute)
    assert constructor_assignments[0].value.func.attr == "get"


def test_task9_source_contract_raw_namespace_precedes_member_resolution() -> None:
    module = _preflight()
    source = inspect.getsource(module._launch_task9_successor_source_contract)
    raw_namespace = source.index(
        'raw_source_namespace = basis[29](_trusted_source_type, "__dict__")'
    )
    raw_bases = source.index('basis[29](_trusted_source_type, "__bases__")')
    raw_mro = source.index('basis[29](_trusted_source_type, "__mro__")')
    raw_new = source.index('raw_source_namespace.get("__new__") is not None')
    constructor = source.index(
        'source_constructor = raw_source_namespace.get("__init__")'
    )
    assert raw_namespace < raw_bases < constructor
    assert raw_namespace < raw_mro < constructor
    assert raw_namespace < raw_new < constructor
    forbidden = (
        "_trusted_source_type.__init__",
        "_trusted_source_type.__new__",
        "_trusted_source_type.__bases__",
        "_trusted_source_type.__mro__",
        "_trusted_source_type.__dict__",
    )
    assert all(token not in source for token in forbidden)
    return_offset = source.rindex("    source_instance = trusted_object_new(")
    final_namespace = source.rindex(
        'raw_source_namespace = basis[29](_trusted_source_type, "__dict__")',
        0,
        return_offset,
    )
    final_barrier = source[final_namespace:return_offset]
    assert 'basis[29](_trusted_source_type, "__bases__")' in final_barrier
    assert 'basis[29](_trusted_source_type, "__mro__")' in final_barrier
    assert 'raw_source_namespace.get("__init__")' in final_barrier
    assert "_trusted_loader_scanner.__code__" in final_barrier
    assert "_trusted_producer_scanner.__code__" in final_barrier
    loader_call = source.index("    _trusted_loader_scanner(loader_source)")
    producer_call = source.index("    verifier_source = _trusted_producer_scanner(")
    assert "_trusted_producer_scanner.__code__" in source[loader_call:producer_call]


def test_task9_source_contract_rejects_late_restoring_init_descriptor_without_dispatch() -> None:
    module = _preflight()
    plan, producer = _task9_successor_source_inputs()
    target = module._TASK9_SUCCESSOR_SOURCE_CONTRACT_TYPE
    original = type.__getattribute__(target, "__dict__")["__init__"]
    dispatches: list[str] = []
    injections: list[str] = []

    class RestoringDescriptor:
        def __get__(self, instance: object, owner: type | None = None) -> object:
            dispatches.append("__init__")
            type.__setattr__(target, "__init__", original)
            return original

    target_code = module._launch_task9_successor_source_contract.__code__

    def trace(frame: object, event: str, arg: object) -> object:
        if (
            event == "line"
            and frame.f_code is target_code
            and "verifier_source" in frame.f_locals
            and not injections
        ):
            injections.append("installed")
            type.__setattr__(target, "__init__", RestoringDescriptor())
        return trace

    prior_trace = sys.gettrace()
    sys.settrace(trace)
