def test_task9_command_constructor_has_immediate_raw_revalidation_barrier() -> None:
    module = _preflight()
    source = inspect.getsource(module._launch_task9_successor_command_contract)
    tree = ast.parse(source)
    body = tree.body[0].body
    construction_index = next(
        index
        for index, statement in enumerate(body)
        if isinstance(statement, ast.Assign)
        and any(isinstance(target, ast.Name) and target.id == "contract" for target in statement.targets)
    )
    barrier = body[construction_index - 1]
    assert isinstance(barrier, ast.If)
    barrier_dump = ast.dump(barrier.test, include_attributes=False)
    assert "raw_contract_namespace" in barrier_dump
    assert "_trusted_contract_constructor_code" in barrier_dump
    assert "_trusted_validate_helper" not in ast.dump(
        ast.Module(body=body[construction_index:], type_ignores=[]),
        include_attributes=False,
    )
    first_provenance = source.index("    _trusted_provenance_helper()")
    canonical = source.index("    canonical_loader = _trusted_canonical_helper(")
    assert "_trusted_canonical_helper.__code__" in source[first_provenance:canonical]
    second_provenance = source.index(
        "        _trusted_provenance_helper()", first_provenance + 1
    )
    builder = source.index("        vector = _trusted_builder(", second_provenance)
    assert "_trusted_builder.__globals__ is not basis[21]" in source[
        second_provenance:builder
    ]
    canonical_call = source.index("    canonical_loader = _trusted_canonical_helper(")
    composition_call = source.index("    _trusted_composition_helper(", canonical_call)
    assert "_trusted_composition_helper.__code__" in source[
        canonical_call:composition_call
    ]
    assert "_trusted_provenance_helper.__code__" in source[
        composition_call:second_provenance
    ]
    quote_loop = source.index("    for value in (executable,", builder)
    quote_call = source.index("quoted_values.append(_trusted_quote_helper(value))", quote_loop)
    assert "_trusted_quote_helper.__code__" in source[quote_loop:quote_call]
    validate_call = source.index("    _trusted_validate_helper(", quote_call)
    assert "_trusted_validate_helper.__code__" in source[quote_call:validate_call]


@pytest.mark.parametrize("dependency_name", ("sha256", "type", "len", "any"))
def test_task9_command_rejects_post_provenance_dependency_replacement_before_dispatch(
    dependency_name: str,
) -> None:
    module = _preflight()
    plan, producer = _task9_successor_source_inputs()
