def test_task9_command_post_callback_computation_uses_only_retained_dependencies() -> None:
    module = _preflight()
    tree = ast.parse(inspect.getsource(module._launch_task9_successor_command_contract))
    function = tree.body[0]
    first_callback = next(
        index
        for index, statement in enumerate(function.body)
        if isinstance(statement, ast.Expr)
        and isinstance(statement.value, ast.Call)
        and isinstance(statement.value.func, ast.Name)
        and statement.value.func.id == "_trusted_provenance_helper"
    )
    tail = ast.Module(body=function.body[first_callback + 1 :], type_ignores=[])
    forbidden_calls = {
        "RuntimeError",
        "UnicodeError",
        "any",
        "bytes",
        "len",
        "list",
        "sha256",
        "str",
        "type",
    }
    observed = {
        node.func.id
        for node in ast.walk(tail)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
    }
    assert observed.isdisjoint(forbidden_calls)
    assert {
        "trusted_builtin_any",
        "trusted_builtin_len",
        "trusted_builtin_type",
        "trusted_sha256",
        "stable_runtime_error",
    } <= observed


