def test_task9_successor_contract_helpers_are_dormant_source_only() -> None:
    module = _preflight()
    helper_names = (
        "_launch_require_task9_closed_region",
        "_launch_scan_task9_transition_producer_semantics",
        "_launch_scan_task9_transition_producer_structure",
        "_launch_scan_task9_successor_loader_semantics",
        "_launch_scan_task9_successor_loader_structure",
        "_launch_task9_successor_source_contract",
        "_launch_task9_canonical_successor_loader",
        "_launch_scan_task9_successor_composition",
        "_launch_quote_task9_windows_argument",
        "_launch_authenticate_task9_vector_provenance",
        "_launch_validate_task9_native_vector",
        "_launch_task9_successor_command_contract",
    )
    forbidden_calls = {
        "Popen", "run", "call", "check_call", "check_output", "socket",
        "exec", "eval", "compile", "open", "write_bytes", "write_text",
    }
    for name in helper_names:
        tree = ast.parse(inspect.getsource(getattr(module, name)))
        call_names = {
            node.func.attr if isinstance(node.func, ast.Attribute) else node.func.id
            for node in ast.walk(tree)
            if isinstance(node, ast.Call)
            and isinstance(node.func, (ast.Attribute, ast.Name))
        }
        assert not call_names & forbidden_calls
    command_tree = ast.parse(
        inspect.getsource(module._launch_task9_successor_command_contract)
    )
    direct_delegated = [
        node
        for node in ast.walk(command_tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
        and node.func.attr == "_windows_native_vector"
    ]
    assert direct_delegated == []
    trusted_calls = [
        node
        for node in ast.walk(command_tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == "_trusted_builder"
    ]
    assert len(trusted_calls) == 1
    assert not [
        node
        for node in ast.walk(command_tree)
        if isinstance(node, (ast.Assign, ast.NamedExpr))
        and isinstance(node.value, ast.Attribute)
        and node.value.attr == "_windows_native_vector"
    ]


@pytest.mark.parametrize(
    "mutation",
    ("missing-loader-end", "duplicate-loader-end", "producer-byte", "late-source-branch"),
)
def test_task9_successor_source_contract_rejects_marker_hash_and_branch_mutants(
    mutation: str,
) -> None:
    module = _preflight()
    plan_bytes, producer_bytes = _task9_successor_source_inputs()
    marker = b"# C6-SUCCESSOR-LOADER-END\n"
    if mutation == "missing-loader-end":
        plan_bytes = plan_bytes.replace(marker, b"# C6-SUCCESSOR-LOADER-MISSING\n", 1)
    elif mutation == "duplicate-loader-end":
        plan_bytes = plan_bytes.replace(marker, marker + marker, 1)
    elif mutation == "producer-byte":
        producer_bytes = producer_bytes.replace(b"Set-StrictMode", b"Set-StrictNode", 1)
    else:
        producer_bytes = producer_bytes.replace(
            b"if ($PSCmdlet.ParameterSetName -eq 'SuccessorVerifierSource') {",
            b"$script:C6LateSourceBranch=$null\n"
            b"if ($PSCmdlet.ParameterSetName -eq 'SuccessorVerifierSource') {",
            1,
        )
