def test_broker_native_guarded_target_precreation_scanner_is_strict_source_only_and_exports_deleted_binder(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    monkeypatch.setattr(os, "urandom", lambda size: bytes(range(size)))
    fragment = (
        module._launch_broker_native_guarded_target_precreation_source_fragment()
    )
    source = fragment.source_bytes
    tree = ast.parse(source.decode("ascii"))
    imports = tuple(
        node
        for node in ast.walk(tree)
        if isinstance(node, (ast.Import, ast.ImportFrom))
    )
    async_nodes = tuple(
        node
        for node in ast.walk(tree)
        if isinstance(node, (ast.AsyncFunctionDef, ast.Await))
    )
    class_names = tuple(
        node.name for node in tree.body if isinstance(node, ast.ClassDef)
    )
    top_level_function_names = tuple(
        node.name for node in tree.body if isinstance(node, ast.FunctionDef)
    )
    top_level_calls = tuple(
        node
        for statement in tree.body[:-2]
        if not isinstance(statement, (ast.ClassDef, ast.FunctionDef))
        for node in ast.walk(statement)
        if isinstance(node, ast.Call)
    )

    assert imports == ()
    assert async_nodes == ()
    assert class_names == fragment.class_names
    assert top_level_function_names == (
        "_c6_broker_native_core_v1_bind_guarded_target_precreation_exports",
    )
    assert top_level_calls == ()
    for forbidden in (
        b"CreateProcessW",
        b"ResumeThread",
        b"TerminateProcess",
        b"Popen",
        b"subprocess",
        b"socket",
        b"ctypes",
        b"descriptor_sha256",
        b"descriptor_nonce",
        b"GuardedPythonTarget",
        b"AckStatusExpectationAuthority",
        b"terminal_payload",
        b"read_file",
        b"write_file",
        b"publish",
    ):
        assert forbidden not in source
    namespace = _broker_native_guarded_target_precreation_test_namespace(
        module
    )
    assert (
        "_c6_broker_native_core_v1_bind_guarded_target_precreation_exports"
        not in namespace
    )
    assert all(name in namespace for name in fragment.function_names)
    assert side_effect_calls == []


def test_broker_native_guarded_target_precreation_scanner_rejects_cross_binding_structure_forbidden_surface_and_activation_mutants(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    fragment = (
        module._launch_broker_native_guarded_target_precreation_source_fragment()
    )
    source = fragment.source_bytes
    mutants = (
        source.replace(
            b"61cf4e298938f0627b94b150725ac27af923a49d83d52a1b5c94ec33eff0f5db",
            b"0" * 64,
            1,
        ),
        source.replace(
            b"class _C6BrokerNativeCoreV1GuardedTargetRequestReceipt(tuple):",
            b"class _C6BrokerNativeCoreV1GuardedTargetRequestReceipx(tuple):",
            1,
        ),
        source.replace(
            b"def _c6_broker_native_core_v1_begin_guarded_target_precreation(",
            b"async def _c6_broker_native_core_v1_begin_guarded_target_precreation(",
            1,
        ),
        source.replace(
            b"def _c6_broker_native_core_v1_bind_guarded_target_precreation_facts(",
            b"def _c6_broker_native_core_v1_bind_guarded_target_precreation_factx(",
            1,
        ),
        source + b"import subprocess\n",
        source + b"CreateProcessW()\n",
        source + b"descriptor_sha256 = '0' * 64\n",
        source + b"AckStatusExpectationAuthority()\n",
        source + b"terminal_payload = b''\n",
        source + b"# C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN\n",
        source + b"# ACTIVATION-ENABLED\n",
        source.replace(
            b"del _c6_broker_native_core_v1_bind_guarded_target_precreation_exports",
            b"del _c6_broker_native_core_v1_bind_guarded_target_precreation_exportx",
            1,
        ),
    )
    assert all(mutant != source for mutant in mutants)

    for mutant in mutants:
        with monkeypatch.context() as aligned_metadata:
            aligned_metadata.setattr(
                module,
                "_BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_BYTES",
                mutant,
            )
            aligned_metadata.setattr(
                module,
                "_BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_SIZE",
                len(mutant),
            )
            aligned_metadata.setattr(
                module,
                "_BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_SHA256",
                sha256(mutant).hexdigest(),
            )
            assert (
                mutant
                == module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_BYTES
            )
            assert (
                len(mutant)
                == module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_SIZE
            )
            assert sha256(mutant).hexdigest() == (
                module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_SHA256
            )
            with pytest.raises(
                RuntimeError,
                match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
            ):
                module._launch_scan_broker_native_guarded_target_precreation_source(
                    mutant
                )
    for field_name, replacement_value in (
        ("version", fragment.version + "-replacement"),
        ("implementation_id", "host-native-core-v1"),
        ("activation_state", "active"),
        ("completeness_state", "complete"),
        (
            "constructor_runtime_prefix_source_version",
            fragment.constructor_runtime_prefix_source_version
            + "-replacement",
        ),
        ("constructor_runtime_prefix_source_size", 1),
        ("constructor_runtime_prefix_source_sha256", "0" * 64),
        ("class_names", fragment.class_names[:-1]),
        ("function_names", fragment.function_names[:-1]),
        ("source_bytes", b"pass\n"),
    ):
        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ):
            replace(fragment, **{field_name: replacement_value})
    assert side_effect_calls == []


@pytest.mark.parametrize(
    ("surface", "injected_statement"),
    (
        ("imports_or_async", b"        import subprocess\n"),
        ("call_names", b"        CreateProcessW()\n"),
        ("loaded_names", b"        candidate = socket\n"),
    ),
)
def test_broker_native_guarded_target_precreation_scanner_reaches_causal_in_body_forbidden_branches(
    surface: str,
    injected_statement: bytes,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    fragment = (
        module._launch_broker_native_guarded_target_precreation_source_fragment()
    )
    source = fragment.source_bytes
    needle = b"    def fail_invalid():\n"
    assert source.count(needle) == 1
    mutant = source.replace(
        needle,
        needle + injected_statement,
        1,
    )
    assert mutant != source
    original_tree = ast.parse(source.decode("ascii"))
    mutant_tree = ast.parse(mutant.decode("ascii"))
    assert tuple(type(node) for node in mutant_tree.body) == tuple(
        type(node) for node in original_tree.body
    )
    original_binder = original_tree.body[7]
    mutant_binder = mutant_tree.body[7]
    assert isinstance(original_binder, ast.FunctionDef)
    assert isinstance(mutant_binder, ast.FunctionDef)
    assert tuple(
        node.name
        for node in mutant_binder.body
        if isinstance(node, ast.FunctionDef)
    ) == tuple(
        node.name
        for node in original_binder.body
        if isinstance(node, ast.FunctionDef)
    )
    for top_level_index in (0, 1, 2, 3, 4, 5, 6, 8, 9):
        assert ast.dump(mutant_tree.body[top_level_index]) == ast.dump(
            original_tree.body[top_level_index]
        )
    assert all(
        token not in mutant
        for token in (
            module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_FORBIDDEN_SOURCE_TOKENS
        )
    )
    if surface == "imports_or_async":
        assert any(isinstance(node, ast.Import) for node in ast.walk(mutant_tree))
    elif surface == "call_names":
        assert any(
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == "CreateProcessW"
            for node in ast.walk(mutant_tree)
        )
    else:
        assert any(
            isinstance(node, ast.Name)
            and isinstance(node.ctx, ast.Load)
            and node.id == "socket"
            for node in ast.walk(mutant_tree)
        )

    with monkeypatch.context() as aligned_metadata:
        aligned_metadata.setattr(
            module,
            "_BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_BYTES",
            mutant,
        )
        aligned_metadata.setattr(
            module,
            "_BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_SIZE",
            len(mutant),
        )
        aligned_metadata.setattr(
            module,
            "_BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_SHA256",
            sha256(mutant).hexdigest(),
        )
        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ):
            module._launch_scan_broker_native_guarded_target_precreation_source(
                mutant
            )
    assert side_effect_calls == []


@pytest.mark.parametrize(
    "surface",
    (
        "top-level-decorator-call",
        "bare-property-decorator",
        "nested-default-expression",
        "nested-annotation-expression",
        "class-base-expression",
        "class-keyword-expression",
        "class-type-parameter-expression",
        "class-body-expression",
    ),
)
def test_broker_native_guarded_target_precreation_scanner_rejects_causal_definition_time_surfaces_with_aligned_metadata(
    surface: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    fragment = (
        module._launch_broker_native_guarded_target_precreation_source_fragment()
    )
    source = fragment.source_bytes
    binder_header = (
        b"def _c6_broker_native_core_v1_bind_guarded_target_precreation_exports():\n"
    )
    receipt_header = (
        b"class _C6BrokerNativeCoreV1GuardedTargetRequestReceipt(tuple):\n"
    )
    if surface == "top-level-decorator-call":
        mutant = source.replace(
            binder_header,
            b"@native_action()\n" + binder_header,
            1,
        )
    elif surface == "bare-property-decorator":
        mutant = source.replace(
            b"    @property\n",
            b"    @native_action\n",
            1,
        )
    elif surface == "nested-default-expression":
        mutant = source.replace(
            b"    def fail_invalid():\n",
            b"    def fail_invalid(candidate=native_action()):\n",
            1,
        )
    elif surface == "nested-annotation-expression":
        mutant = source.replace(
            b"    def fail_invalid():\n",
            b"    def fail_invalid() -> native_action():\n",
            1,
        )
    elif surface == "class-base-expression":
        mutant = source.replace(
            receipt_header,
            b"class _C6BrokerNativeCoreV1GuardedTargetRequestReceipt(native_base()):\n",
            1,
        )
    elif surface == "class-keyword-expression":
        mutant = source.replace(
            receipt_header,
            b"class _C6BrokerNativeCoreV1GuardedTargetRequestReceipt(tuple, metaclass=native_action()):\n",
            1,
        )
    elif surface == "class-type-parameter-expression":
        mutant = source.replace(
            receipt_header,
            b"class _C6BrokerNativeCoreV1GuardedTargetRequestReceipt[T: native_action()](tuple):\n",
            1,
        )
    else:
        assert surface == "class-body-expression"
        mutant = source.replace(
            receipt_header + b"    __slots__ = ()\n",
            receipt_header
            + b"    __slots__ = ()\n"
            + b"    native_action()\n",
            1,
        )
    assert mutant != source
    assert all(
        token not in mutant
        for token in (
            module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_FORBIDDEN_SOURCE_TOKENS
        )
    )
    original_tree = ast.parse(source.decode("ascii"))
    mutant_tree = ast.parse(mutant.decode("ascii"))
    assert tuple(type(node) for node in mutant_tree.body) == tuple(
        type(node) for node in original_tree.body
    )
    assert tuple(
        node.name for node in mutant_tree.body if isinstance(node, ast.ClassDef)
    ) == fragment.class_names
    assert tuple(
        node.name
        for node in mutant_tree.body
        if isinstance(node, ast.FunctionDef)
    ) == (
        "_c6_broker_native_core_v1_bind_guarded_target_precreation_exports",
    )
    original_binder = original_tree.body[7]
    mutant_binder = mutant_tree.body[7]
    assert isinstance(original_binder, ast.FunctionDef)
    assert isinstance(mutant_binder, ast.FunctionDef)
    assert tuple(
        node.name
        for node in mutant_binder.body
        if isinstance(node, ast.FunctionDef)
    ) == tuple(
        node.name
        for node in original_binder.body
        if isinstance(node, ast.FunctionDef)
    )
    mutant_classes = tuple(
        node for node in mutant_tree.body if isinstance(node, ast.ClassDef)
    )
    if surface == "top-level-decorator-call":
        assert any(
            isinstance(decorator, ast.Call)
            for decorator in mutant_binder.decorator_list
        )
    elif surface == "bare-property-decorator":
        first_property = next(
            node
            for node in mutant_classes[0].body
            if isinstance(node, ast.FunctionDef) and node.name == "payload_bytes"
        )
        assert isinstance(first_property.decorator_list[0], ast.Name)
        assert first_property.decorator_list[0].id == "native_action"
    elif surface in (
        "nested-default-expression",
        "nested-annotation-expression",
    ):
        fail_invalid = next(
            node
            for node in mutant_binder.body
            if isinstance(node, ast.FunctionDef) and node.name == "fail_invalid"
        )
        if surface == "nested-default-expression":
            assert any(
                isinstance(default, ast.Call)
                for default in fail_invalid.args.defaults
            )
        else:
            assert isinstance(fail_invalid.returns, ast.Call)
    elif surface == "class-base-expression":
        assert isinstance(mutant_classes[0].bases[0], ast.Call)
    elif surface == "class-keyword-expression":
        assert isinstance(mutant_classes[0].keywords[0].value, ast.Call)
    elif surface == "class-type-parameter-expression":
        assert mutant_classes[0].type_params
        assert isinstance(mutant_classes[0].type_params[0].bound, ast.Call)
    else:
        assert any(
            isinstance(statement, ast.Expr)
            and isinstance(statement.value, ast.Call)
            for statement in mutant_classes[0].body
        )

    with monkeypatch.context() as aligned_metadata:
        aligned_metadata.setattr(
            module,
            "_BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_BYTES",
            mutant,
        )
        aligned_metadata.setattr(
            module,
            "_BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_SIZE",
            len(mutant),
        )
        aligned_metadata.setattr(
            module,
            "_BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_SHA256",
            sha256(mutant).hexdigest(),
        )
        assert mutant == (
            module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_BYTES
        )
        assert len(mutant) == (
            module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_SIZE
        )
        assert sha256(mutant).hexdigest() == (
            module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_SHA256
        )
        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ):
            module._launch_scan_broker_native_guarded_target_precreation_source(
                mutant
            )
    assert side_effect_calls == []


@pytest.mark.parametrize(
    "surface",
    ("call-expression", "call-assignment", "replacement-same-count"),
)
def test_broker_native_guarded_target_precreation_scanner_rejects_aligned_binder_initialization_fingerprint_mutants(
    surface: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    fragment = (
        module._launch_broker_native_guarded_target_precreation_source_fragment()
    )
    source = fragment.source_bytes
    anchor = b"    trusted_journal = []\n"
    assert source.count(anchor) == 1
    if surface == "replacement-same-count":
        mutant = source.replace(
            anchor,
            b"    trusted_journal = local_probe()\n",
            1,
        )
    else:
        insertion = (
            b"    local_probe()\n"
            if surface == "call-expression"
            else b"    local_probe_result = local_probe()\n"
        )
        mutant = source.replace(anchor, anchor + insertion, 1)
    assert mutant != source
    assert all(
        token not in mutant
        for token in (
            module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_FORBIDDEN_SOURCE_TOKENS
        )
    )

    original_tree = ast.parse(source.decode("ascii"))
    mutant_tree = ast.parse(mutant.decode("ascii"))
    original_binder = original_tree.body[7]
    mutant_binder = mutant_tree.body[7]
    assert isinstance(original_binder, ast.FunctionDef)
    assert isinstance(mutant_binder, ast.FunctionDef)
    assert tuple(type(node) for node in mutant_tree.body) == tuple(
        type(node) for node in original_tree.body
    )
    assert tuple(
        node.name for node in mutant_tree.body if isinstance(node, ast.ClassDef)
    ) == fragment.class_names
    assert tuple(
        node.name
        for node in mutant_tree.body
        if isinstance(node, ast.FunctionDef)
    ) == (
        "_c6_broker_native_core_v1_bind_guarded_target_precreation_exports",
    )
    assert tuple(
        node.name
        for node in mutant_binder.body
        if isinstance(node, ast.FunctionDef)
    ) == tuple(
        node.name
        for node in original_binder.body
        if isinstance(node, ast.FunctionDef)
    )
    assert not (
        {
            node.func.id
            if isinstance(node.func, ast.Name)
            else node.func.attr
            for node in ast.walk(mutant_tree)
            if isinstance(node, ast.Call)
            and isinstance(node.func, (ast.Name, ast.Attribute))
        }
        & module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_FORBIDDEN_CALL_NAMES
    )
    assert not (
        {
            node.id
            for node in ast.walk(mutant_tree)
            if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load)
        }
        & module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_FORBIDDEN_RUNTIME_NAMES
    )

    def binder_initialization_fingerprint(binder: ast.FunctionDef) -> str:
        initialization = ast.Module(
            body=[
                statement
                for statement in binder.body
                if not isinstance(statement, ast.FunctionDef)
            ],
            type_ignores=[],
        )
        dumped = ast.dump(
            initialization,
            annotate_fields=True,
            include_attributes=False,
        ).encode("ascii")
        return sha256(dumped).hexdigest()

    original_fingerprint = binder_initialization_fingerprint(original_binder)
    mutant_fingerprint = binder_initialization_fingerprint(mutant_binder)
    assert mutant_fingerprint != original_fingerprint
    mutant_initialization_count = len(
        [
            statement
            for statement in mutant_binder.body
            if not isinstance(statement, ast.FunctionDef)
        ]
    )
    original_initialization_count = len(
        [
            statement
            for statement in original_binder.body
            if not isinstance(statement, ast.FunctionDef)
        ]
    )
    if surface == "replacement-same-count":
        assert mutant_initialization_count == original_initialization_count
        assert (
            mutant_initialization_count
            == module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_BINDER_INITIALIZATION_STATEMENT_COUNT
        )
    else:
        assert mutant_initialization_count == 1 + original_initialization_count
    assert module._launch_scan_broker_native_guarded_target_precreation_source(
        source
    ) == (fragment.class_names, fragment.function_names)

    with monkeypatch.context() as aligned_metadata:
        aligned_metadata.setattr(
            module,
            "_BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_BYTES",
            mutant,
        )
        aligned_metadata.setattr(
            module,
            "_BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_SIZE",
            len(mutant),
        )
        aligned_metadata.setattr(
            module,
            "_BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_SHA256",
            sha256(mutant).hexdigest(),
        )
        assert mutant == (
            module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_BYTES
        )
        assert len(mutant) == (
            module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_SIZE
        )
        assert sha256(mutant).hexdigest() == (
            module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_SHA256
        )
        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ):
            module._launch_scan_broker_native_guarded_target_precreation_source(
                mutant
            )
    assert side_effect_calls == []


def test_host_native_core_csharp_source_fragment_is_immutable_cross_bound_and_dormant(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)

    fragment = module._launch_host_native_core_csharp_source_fragment()

    assert fragment.version == (
        "complete-suite-host-native-csharp-source-fragment-v1"
    )
    assert fragment.implementation_id == "host-native-core-v1"
    assert fragment.fixed_type_name == "C6HostNativeCoreV1"
    assert fragment.abi_contract_facts_version == (
        "complete-suite-host-native-abi-contract-facts-v1"
    )
    assert fragment.abi_contract_facts_size == 17295
    assert fragment.abi_contract_facts_sha256 == (
        "d3c8da5b697b7038caa51beebdede2760ac2f2646a97a97502a360692a482277"
    )
    assert type(fragment.source_bytes) is bytes
    assert fragment.source_bytes.endswith(b"\n")
    assert fragment.source_sha256 == sha256(fragment.source_bytes).hexdigest()
    assert fragment.source_bytes.count(b"public static class C6HostNativeCoreV1") == 1
    assert b"complete-suite-host-native-abi-contract-facts-v1" in (
        fragment.source_bytes
    )
    assert fragment.abi_contract_facts_sha256.encode("ascii") in (
        fragment.source_bytes
    )
    assert not hasattr(fragment, "__dict__")
    with pytest.raises((AttributeError, FrozenInstanceError)):
        fragment.fixed_type_name = "C6HostNativeCoreV2"
    assert side_effect_calls == []


