def test_host_native_core_csharp_source_pins_all_x64_assertions_and_formulas(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    source = module._launch_host_native_core_csharp_source_fragment().source_bytes
    helper = b"""    private static void RequireAbi(bool condition, string fact)
    {
        if (!condition)
        {
            throw new InvalidOperationException("C6 host native x64 ABI mismatch: " + fact);
        }
    }
"""
    assert source.count(helper) == 1
    method_match = re.search(
        rb"    public static void AssertX64Abi\(\)\n"
        rb"    \{\n(.*?)    \}\n",
        source,
        re.DOTALL,
    )
    assert method_match is not None
    actual = tuple(
        (
            match.group(1).decode("ascii"),
            match.group(2).decode("ascii"),
        )
        for match in re.finditer(
            rb'        RequireAbi\(([^;\n]+), "([^"]+)"\);\n',
            method_match.group(1),
        )
    )
    layout_manifest = """SECURITY_ATTRIBUTES|24|nLength=0,lpSecurityDescriptor=8,bInheritHandle=16
STARTUPINFOW|104|cb=0,lpReserved=8,lpDesktop=16,lpTitle=24,dwX=32,dwFlags=60,wShowWindow=64,cbReserved2=66,lpReserved2=72,hStdInput=80,hStdOutput=88,hStdError=96
STARTUPINFOEXW|112|StartupInfo=0,lpAttributeList=104
PROCESS_INFORMATION|24|hProcess=0,hThread=8,dwProcessId=16,dwThreadId=20
OVERLAPPED|32|Internal=0,InternalHigh=8,Offset=16,OffsetHigh=20,Pointer=16,hEvent=24
JOBOBJECT_BASIC_ACCOUNTING_INFORMATION|48|TotalUserTime=0,TotalKernelTime=8,ThisPeriodTotalUserTime=16,ThisPeriodTotalKernelTime=24,TotalPageFaultCount=32,TotalProcesses=36,ActiveProcesses=40,TotalTerminatedProcesses=44
JOBOBJECT_BASIC_LIMIT_INFORMATION|64|PerProcessUserTimeLimit=0,PerJobUserTimeLimit=8,LimitFlags=16,MinimumWorkingSetSize=24,MaximumWorkingSetSize=32,ActiveProcessLimit=40,Affinity=48,PriorityClass=56,SchedulingClass=60
IO_COUNTERS|48|ReadOperationCount=0,WriteOperationCount=8,OtherOperationCount=16,ReadTransferCount=24,WriteTransferCount=32,OtherTransferCount=40
JOBOBJECT_EXTENDED_LIMIT_INFORMATION|144|BasicLimitInformation=0,IoInfo=64,ProcessMemoryLimit=112,JobMemoryLimit=120,PeakProcessMemoryUsed=128,PeakJobMemoryUsed=136
JOBOBJECT_ASSOCIATE_COMPLETION_PORT|16|CompletionKey=0,CompletionPort=8
JOBOBJECT_BASIC_PROCESS_ID_LIST_HEADER|8|NumberOfAssignedProcesses=0,NumberOfProcessIdsInList=4,ProcessIdList=8
FILETIME|8|dwLowDateTime=0,dwHighDateTime=4
SID_IDENTIFIER_AUTHORITY|6|Value=0
SID_AND_ATTRIBUTES|16|Sid=0,Attributes=8
ACL|8|AclRevision=0,Sbz1=1,AclSize=2,AceCount=4,Sbz2=6
ACE_HEADER|4|AceType=0,AceFlags=1,AceSize=2
ACCESS_ALLOWED_ACE|12|Header=0,Mask=4,SidStart=8
ACL_SIZE_INFORMATION|12|AceCount=0,AclBytesInUse=4,AclBytesFree=8
SECURITY_DESCRIPTOR|40|Revision=0,Sbz1=1,Control=2,Owner=8,Group=16,Sacl=24,Dacl=32
SECURITY_DESCRIPTOR_RELATIVE|20|Revision=0,Sbz1=1,Control=2,Owner=4,Group=8,Sacl=12,Dacl=16
PROCESSENTRY32W|568|dwSize=0,cntUsage=4,th32ProcessID=8,th32DefaultHeapID=16,th32ModuleID=24,cntThreads=28,th32ParentProcessID=32,pcPriClassBase=36,dwFlags=40,szExeFile=44
PUBLIC_OBJECT_BASIC_INFORMATION|56|Attributes=0,GrantedAccess=4,HandleCount=8,PointerCount=12,Reserved=16
UNICODE_STRING|16|Length=0,MaximumLength=2,Buffer=8
PUBLIC_OBJECT_TYPE_INFORMATION|104|TypeName=0,Reserved=16"""
    expected_checks: list[tuple[str, str]] = [
        ("IntPtr.Size == 8", "pointer-size"),
        ("Marshal.SizeOf(typeof(bool)) == 4", "BOOL-size"),
    ]
    for row in layout_manifest.splitlines():
        type_name, size_text, offsets_text = row.split("|", 2)
        expected_checks.append(
            (
                f"Marshal.SizeOf(typeof({type_name})) == {size_text}",
                f"{type_name}.size",
            )
        )
        for field_and_offset in offsets_text.split(","):
            field_name, offset_text = field_and_offset.split("=", 1)
            if (
                type_name == "JOBOBJECT_BASIC_PROCESS_ID_LIST_HEADER"
                and field_name == "ProcessIdList"
            ):
                condition = (
                    "Marshal.SizeOf(typeof("
                    "JOBOBJECT_BASIC_PROCESS_ID_LIST_HEADER)) == 8"
                )
            else:
                condition = (
                    f'Marshal.OffsetOf(typeof({type_name}), "{field_name}")'
                    f".ToInt64() == {offset_text}"
                )
            expected_checks.append(
                (condition, f"{type_name}.{field_name}")
            )
    expected_checks.extend(
        (
            (
                "C6_EXACT_CREATION_FLAGS == (CREATE_SUSPENDED | "
                "CREATE_UNICODE_ENVIRONMENT | EXTENDED_STARTUPINFO_PRESENT)",
                "C6_EXACT_CREATION_FLAGS.formula",
            ),
            (
                "C6_PIPE_SERVER_INBOUND_OPEN_MODE == (PIPE_ACCESS_INBOUND | "
                "FILE_FLAG_FIRST_PIPE_INSTANCE | FILE_FLAG_OVERLAPPED)",
                "C6_PIPE_SERVER_INBOUND_OPEN_MODE.formula",
            ),
            (
                "C6_PIPE_SERVER_OUTBOUND_OPEN_MODE == (PIPE_ACCESS_OUTBOUND | "
                "FILE_FLAG_FIRST_PIPE_INSTANCE | FILE_FLAG_OVERLAPPED)",
                "C6_PIPE_SERVER_OUTBOUND_OPEN_MODE.formula",
            ),
            (
                "C6_PIPE_CLIENT_OPEN_FLAGS == (FILE_FLAG_OVERLAPPED | "
                "SECURITY_IDENTIFICATION | SECURITY_SQOS_PRESENT)",
                "C6_PIPE_CLIENT_OPEN_FLAGS.formula",
            ),
        )
    )

    assert actual == tuple(expected_checks)
    assert source.count(b"AssertX64Abi(") == 1
    assert b"static C6HostNativeCoreV1(" not in source
    assert b"new C6HostNativeCoreV1(" not in source
    assert side_effect_calls == []


def test_host_native_core_csharp_source_scanner_pins_bytes_digest_and_copy(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    canonical = module._launch_host_native_core_csharp_source_fragment()
    extracted = module._launch_extract_host_native_core_csharp_source_fragment(
        memoryview(canonical.source_bytes).tobytes()
    )

    assert module._HOST_NATIVE_CORE_CSHARP_SOURCE_SIZE == 48305
    assert module._HOST_NATIVE_CORE_CSHARP_SOURCE_SHA256 == (
        "dc5f453f074de7cbd7a0af6f262104d9f9881278194d7876adb25ccb8507691d"
    )
    assert len(extracted.source_bytes) == 48305
    assert extracted.source_sha256 == (
        "dc5f453f074de7cbd7a0af6f262104d9f9881278194d7876adb25ccb8507691d"
    )
    assert extracted == canonical
    assert extracted is not canonical
    assert extracted.source_bytes == canonical.source_bytes
    assert extracted.source_bytes is not canonical.source_bytes
    assert b"Add-Type" not in extracted.source_bytes
    assert b"Initialize-C6HostNativeCoreV1" not in extracted.source_bytes
    assert extracted.source_bytes.count(b"CreateProcessW(") == 1
    assert side_effect_calls == []


