def test_host_native_core_csharp_source_scanner_rejects_mutants_without_effects(
    mutation: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    canonical = module._launch_host_native_core_csharp_source_fragment().source_bytes
    replacements = {
        "abi-version": (
            b"complete-suite-host-native-abi-contract-facts-v1",
            b"complete-suite-host-native-abi-contract-facts-v2",
        ),
        "abi-size": (b"AbiContractFactsPayloadBytes = 17295", b"AbiContractFactsPayloadBytes = 17296"),
        "abi-hash": (
            b"d3c8da5b697b7038caa51beebdede2760ac2f2646a97a97502a360692a482277",
            b"03c8da5b697b7038caa51beebdede2760ac2f2646a97a97502a360692a482277",
        ),
        "type-name": (b"C6HostNativeCoreV1", b"C6HostNativeCoreV2"),
        "layout-kind": (
            b"StructLayout(LayoutKind.Explicit, Pack = 8)",
            b"StructLayout(LayoutKind.Sequential, Pack = 8)",
        ),
        "pack": (b"StructLayout(LayoutKind.Sequential, Pack = 8)", b"StructLayout(LayoutKind.Sequential, Pack = 4)"),
        "field-type": (b"public IntPtr InternalHigh;", b"public uint InternalHigh;"),
        "fixed-array-width": (b"SizeConst = 260", b"SizeConst = 259"),
        "union-offset": (b"[FieldOffset(16)] public IntPtr Pointer;", b"[FieldOffset(20)] public IntPtr Pointer;"),
        "constant": (b"C6_JOB_OWNER_ACCESS = 15U", b"C6_JOB_OWNER_ACCESS = 14U"),
        "api-dll": (b'DllImport("ntdll.dll"', b'DllImport("kernel32.dll"'),
        "api-name": (b"NtQueryObject(", b"NtQueryObjectV2("),
        "charset": (b"CharSet = CharSet.Unicode", b"CharSet = CharSet.Auto"),
        "calling-convention": (b"CallingConvention.StdCall", b"CallingConvention.Winapi"),
        "exact-spelling": (b"ExactSpelling = true", b"ExactSpelling = false"),
        "set-last-error": (b"SetLastError = false", b"SetLastError = true"),
        "return-marshalling": (
            b"[return: MarshalAs(UnmanagedType.Bool)]",
            b"[return: MarshalAs(UnmanagedType.I1)]",
        ),
        "api-parameter": (
            b"UIntPtr attribute, IntPtr value",
            b"uint attribute, IntPtr value",
        ),
        "pointer-assertion": (b"IntPtr.Size == 8", b"IntPtr.Size == 4"),
        "bool-assertion": (
            b"Marshal.SizeOf(typeof(bool)) == 4",
            b"Marshal.SizeOf(typeof(bool)) == 1",
        ),
        "size-assertion": (
            b"Marshal.SizeOf(typeof(STARTUPINFOEXW)) == 112",
            b"Marshal.SizeOf(typeof(STARTUPINFOEXW)) == 104",
        ),
        "offset-assertion": (
            b'Marshal.OffsetOf(typeof(OVERLAPPED), "Pointer").ToInt64() == 16',
            b'Marshal.OffsetOf(typeof(OVERLAPPED), "Pointer").ToInt64() == 20',
        ),
        "formula-assertion": (
            b"CREATE_SUSPENDED | CREATE_UNICODE_ENVIRONMENT | EXTENDED_STARTUPINFO_PRESENT",
            b"CREATE_SUSPENDED | EXTENDED_STARTUPINFO_PRESENT",
        ),
        "pipe-client-access-domain-alias": (
            b"C6_PIPE_CLIENT_OPEN_FLAGS == (FILE_FLAG_OVERLAPPED | SECURITY_IDENTIFICATION | SECURITY_SQOS_PRESENT)",
            b"C6_PIPE_CLIENT_OPEN_FLAGS == (GENERIC_WRITE | SECURITY_IDENTIFICATION | SECURITY_SQOS_PRESENT)",
        ),
    }
    if mutation in replacements:
        old, new = replacements[mutation]
        assert canonical.count(old) >= 1, mutation
        mutated: object = canonical.replace(old, new, 1)
    elif mutation == "api-order":
        first = canonical.index(b"    [DllImport(")
        second = canonical.index(b"    [DllImport(", first + 1)
        third = canonical.index(b"    [DllImport(", second + 1)
        first_block = canonical[first:second]
        second_block = canonical[second:third]
        mutated = canonical[:first] + second_block + first_block + canonical[third:]
    elif mutation == "static-constructor":
        mutated = canonical.replace(
            b"    private static void RequireAbi",
            b"    static C6HostNativeCoreV1() {}\n\n    private static void RequireAbi",
            1,
        )
    elif mutation == "second-type":
        mutated = canonical + b"public static class SecondType {}\n"
    elif mutation == "namespace":
        mutated = b"namespace Replacement {\n" + canonical + b"}\n"
    elif mutation == "add-type-marker":
        mutated = canonical.replace(
            b"public static class C6HostNativeCoreV1",
            b"public static class Add-Type_C6HostNativeCoreV1",
            1,
        )
    elif mutation == "prefix":
        mutated = b" " + canonical
    elif mutation == "suffix":
        mutated = canonical + b"\n"
    elif mutation == "bom":
        mutated = b"\xef\xbb\xbf" + canonical
    elif mutation == "cr":
        mutated = canonical.replace(b"\n", b"\r\n", 1)
    elif mutation == "nul":
        mutated = canonical.replace(b"\n", b"\x00\n", 1)
    elif mutation == "missing-terminal-lf":
        mutated = canonical[:-1]
    elif mutation == "bytes-subclass":

        class _BytesSubclass(bytes):
            pass

        mutated = _BytesSubclass(canonical)
    elif mutation == "bytearray":
        mutated = bytearray(canonical)
    else:
        raise AssertionError(mutation)

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_extract_host_native_core_csharp_source_fragment(mutated)

    assert side_effect_calls == []


@pytest.mark.parametrize(
    ("field_name", "replacement_value"),
    (
        ("version", "complete-suite-host-native-csharp-source-fragment-v2"),
        ("implementation_id", "broker-native-core-v1"),
        ("fixed_type_name", "C6HostNativeCoreV2"),
        ("abi_contract_facts_version", "complete-suite-host-native-abi-contract-facts-v2"),
        ("abi_contract_facts_size", 17296),
        (
            "abi_contract_facts_sha256",
            "03c8da5b697b7038caa51beebdede2760ac2f2646a97a97502a360692a482277",
        ),
        ("source_bytes", b"using System;\n"),
    ),
)
def test_host_native_core_csharp_source_fragment_rejects_metadata_drift(
    field_name: str,
    replacement_value: object,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    fragment = module._launch_host_native_core_csharp_source_fragment()

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        replace(fragment, **{field_name: replacement_value})

    assert side_effect_calls == []


