@pytest.mark.parametrize(
    "mutation",
    (
        "top-level-add-type",
        "prefix",
        "suffix",
        "bom",
        "cr",
        "nul",
        "missing-terminal-lf",
        "bytes-subclass",
        "bytearray",
    ),
)
def test_host_native_core_initializer_source_extractor_rejects_boundary_mutants(
    mutation: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    csharp = module._launch_host_native_core_csharp_source_fragment()
    canonical = (
        _HOST_NATIVE_CORE_INITIALIZER_EXPECTED_PREFIX
        + csharp.source_bytes
        + _HOST_NATIVE_CORE_INITIALIZER_EXPECTED_SUFFIX
    )
    mutated: object = canonical
    if mutation == "top-level-add-type":
        mutated = b"Add-Type -TypeDefinition 'forged'\n" + canonical
    elif mutation == "prefix":
        mutated = b" " + canonical
    elif mutation == "suffix":
        mutated = canonical + b"\n"
    elif mutation == "bom":
        mutated = b"\xef\xbb\xbf" + canonical
    elif mutation == "cr":
        mutated = canonical.replace(b"\n", b"\r\n", 1)
    elif mutation == "nul":
        mutated = canonical.replace(b"\n", b"\x00\n", 1)
    elif mutation == "missing-terminal-lf":
        mutated = canonical[:-1]
    elif mutation == "bytes-subclass":

        class _BytesSubclass(bytes):
            pass

        mutated = _BytesSubclass(canonical)
    elif mutation == "bytearray":
        mutated = bytearray(canonical)
    else:
        raise AssertionError(mutation)

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_extract_host_native_core_initializer_source_fragment(mutated)

    assert side_effect_calls == []


def test_host_native_constructor_call_graph_composes_exact_dormant_fragments(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    csharp = module._launch_host_native_core_csharp_source_fragment()
    initializer_source = (
        _HOST_NATIVE_CORE_INITIALIZER_EXPECTED_PREFIX
        + csharp.source_bytes
        + _HOST_NATIVE_CORE_INITIALIZER_EXPECTED_SUFFIX
    )
    expected_source = (
        _HOST_NATIVE_VECTOR_SOURCE_BYTES
        + initializer_source
        + _HOST_NATIVE_CONSTRUCTOR_CALL_GRAPH_SYNTHETIC_SOURCE_BYTES
    )

    fragment = (
        module._launch_extract_host_native_constructor_call_graph_source_fragment(
            expected_source
        )
    )

    assert fragment.version == (
        "complete-suite-host-native-constructor-call-graph-source-fragment-v1"
    )
    assert fragment.implementation_id == "host-native-core-v1"
    assert fragment.activation_state == "synthetic-dormant"
    assert fragment.function_names == (
        _HOST_NATIVE_CONSTRUCTOR_CALL_GRAPH_FUNCTION_NAMES
    )
    assert fragment.native_vector_source_sha256 == sha256(
        _HOST_NATIVE_VECTOR_SOURCE_BYTES
    ).hexdigest()
    assert fragment.initializer_source_sha256 == sha256(
        initializer_source
    ).hexdigest()
    assert fragment.call_graph_source_bytes == (
        _HOST_NATIVE_CONSTRUCTOR_CALL_GRAPH_SYNTHETIC_SOURCE_BYTES
    )
    assert fragment.call_graph_source_sha256 == sha256(
        _HOST_NATIVE_CONSTRUCTOR_CALL_GRAPH_SYNTHETIC_SOURCE_BYTES
    ).hexdigest()
    assert len(fragment.call_graph_source_bytes) == 4050
    assert fragment.call_graph_source_sha256 == (
        "29cdb68eae78de6ec75c3830475b22822f00024f2060deeb1ffb97cd81fb2e18"
    )
    assert fragment.source_bytes == expected_source
    assert fragment.source_bytes is not expected_source
    assert fragment.source_sha256 == sha256(expected_source).hexdigest()
    assert len(fragment.source_bytes) == 65493
    assert fragment.source_sha256 == (
        "b2f23e9a9c4bb7a013cff2d717a3ba97535c334d061becec722decd7282c4b47"
    )
    assert fragment.source_bytes.startswith(
        _HOST_NATIVE_VECTOR_SOURCE_BYTES + initializer_source
    )
    assert fragment.source_bytes.endswith(
        _HOST_NATIVE_CONSTRUCTOR_CALL_GRAPH_SYNTHETIC_SOURCE_BYTES
    )
    assert not hasattr(fragment, "__dict__")
    with pytest.raises((AttributeError, FrozenInstanceError)):
        fragment.source_bytes = b"mutated\n"
    assert not (Path(module.__file__).parent / "complete_suite_control_plane.ps1").exists()
    assert side_effect_calls == []


