def test_host_native_constructor_call_graph_uses_alias_proof_initializer_scriptblock(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    initializer = module._launch_host_native_core_initializer_source_fragment()
    source = (
        _HOST_NATIVE_VECTOR_SOURCE_BYTES
        + initializer.source_bytes
        + _HOST_NATIVE_CONSTRUCTOR_CALL_GRAPH_SYNTHETIC_SOURCE_BYTES
    )

    fragment = (
        module._launch_extract_host_native_constructor_call_graph_source_fragment(
            source
        )
    )
    tail = fragment.call_graph_source_bytes

    provider_lookup = (
        b"[object]$initializerItem="
        b"Microsoft.PowerShell.Management\\Get-Item `\n"
        b"        -LiteralPath "
        b"'Function:\\script:Initialize-C6HostNativeCoreV1' `\n"
        b"        -ErrorAction Stop\n"
    )
    scriptblock_invocation = (
        b"[object[]]$initializerOutput=@(\n"
        b"        & ([scriptblock]$initializerItem.ScriptBlock)\n"
        b"    )\n"
    )
    assert tail.count(provider_lookup) == 1
    assert tail.count(scriptblock_invocation) == 1
    assert tail.count(b"Initialize-C6HostNativeCoreV1") == 2
    assert b"\n    Initialize-C6HostNativeCoreV1" not in tail
    assert b"& 'Initialize-C6HostNativeCoreV1'" not in tail
    preparation_index = tail.find(
        b"[object]$preparation=New-C6HostNativeLaunchPreparation"
    )
    provider_index = tail.find(provider_lookup)
    invocation_index = tail.find(scriptblock_invocation)
    assert 0 <= preparation_index < provider_index < invocation_index
    for function_name in _HOST_NATIVE_CONSTRUCTOR_CALL_GRAPH_FUNCTION_NAMES:
        assert tail.count(f"function {function_name} {{".encode("ascii")) == 1
    assert side_effect_calls == []


@pytest.mark.parametrize(
    "mutation",
    (
        "initializer-before-vector",
        "unqualified-initializer-call",
        "name-call-operator",
        "unqualified-provider-lookup",
        "wrapper-bypasses-generic",
        "reordered-public-functions",
        "duplicate-function",
        "alias-rebinding",
        "missing-type-identity",
        "bytes-subclass",
        "bytearray",
    ),
)
def test_host_native_constructor_call_graph_rejects_order_alias_and_identity_mutants(
    mutation: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    initializer = module._launch_host_native_core_initializer_source_fragment()
    tail = _HOST_NATIVE_CONSTRUCTOR_CALL_GRAPH_SYNTHETIC_SOURCE_BYTES
    source: object = _HOST_NATIVE_VECTOR_SOURCE_BYTES + initializer.source_bytes + tail
    if mutation == "initializer-before-vector":
        source = initializer.source_bytes + _HOST_NATIVE_VECTOR_SOURCE_BYTES + tail
    elif mutation == "unqualified-initializer-call":
        source = source.replace(
            b"& ([scriptblock]$initializerItem.ScriptBlock)",
            b"Initialize-C6HostNativeCoreV1",
            1,
        )
    elif mutation == "name-call-operator":
        source = source.replace(
            b"& ([scriptblock]$initializerItem.ScriptBlock)",
            b"& 'Initialize-C6HostNativeCoreV1'",
            1,
        )
    elif mutation == "unqualified-provider-lookup":
        source = source.replace(
            b"Microsoft.PowerShell.Management\\Get-Item `",
            b"Get-Item `",
            1,
        )
    elif mutation == "wrapper-bypasses-generic":
        wrapper_offset = source.find(b"function Invoke-C6Git {")
        assert wrapper_offset >= 0
        source = (
            source[:wrapper_offset]
            + source[wrapper_offset:].replace(
                b"Invoke-C6HostNativeConstructor",
                b"New-C6HostNativeLaunchPreparation",
                1,
            )
        )
    elif mutation == "reordered-public-functions":
        git_offset = tail.find(b"function Invoke-C6Git {")
        root_offset = tail.find(b"function Invoke-C6RootPython {")
        assert 0 <= git_offset < root_offset
        reordered_tail = (
            tail[:git_offset]
            + tail[root_offset:]
            + tail[git_offset:root_offset]
        )
        source = (
            _HOST_NATIVE_VECTOR_SOURCE_BYTES
            + initializer.source_bytes
            + reordered_tail
        )
    elif mutation == "duplicate-function":
        source = source + tail[tail.find(b"function Invoke-C6Git {") :]
    elif mutation == "alias-rebinding":
        source = source + (
            b"Set-Alias -Name Initialize-C6HostNativeCoreV1 "
            b"-Value Write-Output\n"
        )
    elif mutation == "missing-type-identity":
        source = source.replace(
            b"        -not [Object]::ReferenceEquals(\n"
            b"            $nativeCoreType,\n"
            b"            ('C6HostNativeCoreV1' -as [type])\n"
            b"        )",
            b"        $false",
            1,
        )
    elif mutation == "bytes-subclass":

        class _BytesSubclass(bytes):
            pass

        source = _BytesSubclass(source)
    elif mutation == "bytearray":
        source = bytearray(source)
    else:
        raise AssertionError(mutation)

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_extract_host_native_constructor_call_graph_source_fragment(
            source
        )

    assert side_effect_calls == []


def test_native_constructor_atomic_completeness_gate_binds_both_dormant_candidates(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    host_fragment = (
        module._launch_host_native_control_plane_candidate_source_fragment()
    )
    broker_fragment = (
        module._launch_extract_broker_native_control_plane_candidate_from_bootstrap_source(
            BOOTSTRAP_PATH.read_bytes()
        )
    )

    gate = module._launch_build_native_constructor_atomic_completeness_gate(
        host_fragment=host_fragment,
        broker_fragment=broker_fragment,
    )

    assert gate.version == (
        "complete-suite-native-constructor-atomic-completeness-gate-v1"
    )
    assert gate.gate_state == "closed"
    assert gate.activation_permitted is False
    assert gate.implementation_ids == (
        "host-native-core-v1",
        "broker-native-core-v1",
    )
    assert gate.host_activation_state == "synthetic-dormant"
    assert gate.broker_activation_state == "draft-dormant-incomplete"
    assert gate.host_source_sha256 == host_fragment.source_sha256
    assert gate.broker_source_sha256 == broker_fragment.source_sha256
    assert gate.host_source_size == 90297
    assert gate.broker_source_size == 299650
    assert gate.canonical_bytes.endswith(b"\n")
    assert gate.canonical_sha256 == (
        "265f84eda663656ca0dfc97726fa1d9e53c3e46dc39217d2b27245b8fc461a92"
    )
    assert gate.canonical_sha256 == sha256(gate.canonical_bytes).hexdigest()
    decoded = json.loads(gate.canonical_bytes)
    assert decoded == {
        "version": "complete-suite-native-constructor-atomic-completeness-gate-v1",
        "gate_state": "closed",
        "activation_permitted": False,
        "implementations": [
            {
                "implementation_id": "host-native-core-v1",
                "activation_state": "synthetic-dormant",
                "source_size": 90297,
                "source_sha256": host_fragment.source_sha256,
            },
            {
                "implementation_id": "broker-native-core-v1",
                "activation_state": "draft-dormant-incomplete",
                "source_size": 299650,
                "source_sha256": broker_fragment.source_sha256,
            },
        ],
    }
    assert not hasattr(gate, "__dict__")
    with pytest.raises((AttributeError, FrozenInstanceError)):
        gate.gate_state = "open"
    assert not (Path(module.__file__).parent / "complete_suite_control_plane.ps1").exists()
    assert side_effect_calls == []


@pytest.mark.parametrize(
    "mutation",
    (
        "missing-host",
        "missing-broker",
        "swapped-members",
        "broker-source-drift",
        "broker-activation-forgery",
        "broker-completeness-forgery",
        "broker-raw-bytes",
        "broker-bytearray",
    ),
)
def test_native_constructor_atomic_completeness_gate_rejects_partial_swapped_or_drifted_pairs(
    mutation: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    host: object = (
        module._launch_host_native_control_plane_candidate_source_fragment()
    )
    broker: object = (
        module._launch_extract_broker_native_control_plane_candidate_from_bootstrap_source(
            BOOTSTRAP_PATH.read_bytes()
        )
    )
    if mutation == "missing-host":
        host = None
    elif mutation == "missing-broker":
        broker = None
    elif mutation == "swapped-members":
        host, broker = broker, host
    elif mutation == "broker-source-drift":
        broker = _unchecked_replace(
            broker,
            source_bytes=broker.source_bytes.replace(
                b"CreateProcessW",
                b"CreateProcessX",
                1,
            ),
        )
    elif mutation == "broker-activation-forgery":
        broker = _unchecked_replace(broker, activation_state="complete")
    elif mutation == "broker-completeness-forgery":
        broker = _unchecked_replace(broker, completeness_state="complete")
    elif mutation == "broker-raw-bytes":
        broker = broker.source_bytes
    elif mutation == "broker-bytearray":
        broker = bytearray(broker.source_bytes)
    else:
        raise AssertionError(mutation)

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_build_native_constructor_atomic_completeness_gate(
            host_fragment=host,
            broker_fragment=broker,
        )

    assert side_effect_calls == []


