def test_host_root_python_fixed_loader_source_fragment_is_exact_immutable_and_dormant(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)

    fragment = module._launch_host_root_python_fixed_loader_source_fragment()

    assert fragment.version == (
        "complete-suite-host-root-python-fixed-loader-source-fragment-v1"
    )
    assert fragment.implementation_id == "host-native-core-v1"
    assert fragment.role == "root-python-fixed-loader"
    assert fragment.import_names == ("hashlib", "io", "os", "stat", "sys")
    assert fragment.function_names == ("fail", "configure_utf8_stream")
    assert fragment.argument_labels == (
        "--bootstrap-path",
        "--bootstrap-sha256",
        "--descriptor-handle",
        "--ack-handle",
        "--go-handle",
    )
    assert fragment.source_bytes == _HOST_ROOT_PYTHON_FIXED_LOADER_EXPECTED_SOURCE_BYTES
    assert fragment.source_bytes is not _HOST_ROOT_PYTHON_FIXED_LOADER_EXPECTED_SOURCE_BYTES
    assert len(fragment.source_bytes) == 3532
    assert fragment.source_sha256 == (
        "cdc669417a69976cda27ba6bb4b3f027a7aaf022a99664630e1a207cf32ad666"
    )
    assert fragment.source_sha256 == sha256(fragment.source_bytes).hexdigest()
    assert fragment.source_bytes.endswith(b"\n")
    assert not hasattr(fragment, "__dict__")
    with pytest.raises((AttributeError, FrozenInstanceError)):
        fragment.source_bytes = b"pass\n"
    assert not (Path(module.__file__).parent / "complete_suite_control_plane.ps1").exists()
    assert side_effect_calls == []


def test_host_root_python_fixed_loader_ast_and_trust_order_are_exact(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    source = module._launch_host_root_python_fixed_loader_source_fragment().source_bytes

    tree = ast.parse(source, filename="<host-root-python-fixed-loader>", mode="exec")
    imports = tuple(
        alias.name
        for statement in tree.body
        if isinstance(statement, ast.Import)
        for alias in statement.names
    )
    functions = tuple(
        statement.name
        for statement in tree.body
        if isinstance(statement, (ast.FunctionDef, ast.AsyncFunctionDef))
    )
    name_calls = tuple(
        node.func.id
        for node in ast.walk(tree)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
    )
    attribute_calls = tuple(
        (
            node.func.value.id,
            node.func.attr,
        )
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
        and isinstance(node.func.value, ast.Name)
    )
    assert imports == ("hashlib", "io", "os", "stat", "sys")
    assert functions == ("fail", "configure_utf8_stream")
    assert name_calls.count("compile") == 1
    assert name_calls.count("exec") == 1
    assert attribute_calls.count(("os", "lstat")) == 1
    assert attribute_calls.count(("os", "open")) == 1
    assert attribute_calls.count(("os", "fstat")) == 2
    assert attribute_calls.count(("os", "read")) == 1
    assert attribute_calls.count(("os", "close")) == 1
    ordered_tokens = (
        b"configure_utf8_stream(sys.stdout, \"stdout\")",
        b"configure_utf8_stream(sys.stderr, \"stderr\")",
        b"if len(args) != 11 or args[0] != \"--\":",
        b"if tuple(args[index] for index in (1, 3, 5, 7, 9)) != labels:",
        b"before = os.lstat(bootstrap_path)",
        b"descriptor = os.open(bootstrap_path, flags)",
        b"opened_before = os.fstat(descriptor)",
        b"chunk = os.read(descriptor, min(65536, 1048577 - byte_count))",
        b"opened_after = os.fstat(descriptor)",
        b"os.close(descriptor)",
        b"if identity_before != identity_after or byte_count != opened_before.st_size:",
        b"if hashlib.sha256(bootstrap_bytes).hexdigest() != expected_sha256:",
        b"bootstrap_code = compile(",
        b"exec(bootstrap_code, bootstrap_globals, bootstrap_globals)",
    )
    cursor = 0
    for token in ordered_tokens:
        token_index = source.find(token, cursor)
        assert token_index >= 0
        cursor = token_index + len(token)
    assert side_effect_calls == []


