@pytest.mark.parametrize(
    "mutation",
    (
        "argument-count",
        "argument-sentinel",
        "argument-label",
        "absolute-path-check",
        "hash-alphabet",
        "positive-handle-check",
        "nofollow-lstat",
        "symlink-check",
        "size-cap",
        "read-chunk-cap",
        "identity-cross-check",
        "hash-check",
        "compile-input",
        "dont-inherit",
        "optimize",
        "exec-globals",
        "extra-import",
        "bom",
        "cr",
        "nul",
        "missing-terminal-lf",
        "bytes-subclass",
        "bytearray",
    ),
)
def test_host_root_python_fixed_loader_source_extractor_rejects_trust_and_boundary_mutants(
    mutation: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    source: object = _HOST_ROOT_PYTHON_FIXED_LOADER_EXPECTED_SOURCE_BYTES
    replacements = {
        "argument-count": (b"len(args) != 11", b"len(args) != 10"),
        "argument-sentinel": (b'args[0] != "--"', b'args[0] != "-"'),
        "argument-label": (
            b'    "--go-handle",\n)\n',
            b'    "--start-handle",\n)\n',
        ),
        "absolute-path-check": (
            b"if not os.path.isabs(bootstrap_path):",
            b"if False:",
        ),
        "hash-alphabet": (
            b'"0123456789abcdef"',
            b'"0123456789abcdefABCDEF"',
        ),
        "positive-handle-check": (b"int(value) <= 0", b"int(value) < 0"),
        "nofollow-lstat": (b"os.lstat(bootstrap_path)", b"os.stat(bootstrap_path)"),
        "symlink-check": (b"stat.S_ISLNK(before.st_mode)", b"False"),
        "size-cap": (b"opened_before.st_size > 1048576", b"False"),
        "read-chunk-cap": (b"min(65536, 1048577 - byte_count)", b"65536"),
        "identity-cross-check": (
            b"identity_before != identity_after",
            b"False",
        ),
        "hash-check": (
            b"hashlib.sha256(bootstrap_bytes).hexdigest() != expected_sha256",
            b"False",
        ),
        "compile-input": (b"        bootstrap_bytes,", b"        b'pass\\n',"),
        "dont-inherit": (b"        dont_inherit=True,", b"        dont_inherit=False,"),
        "optimize": (b"        optimize=0,", b"        optimize=1,"),
        "exec-globals": (
            b"exec(bootstrap_code, bootstrap_globals, bootstrap_globals)",
            b"exec(bootstrap_code, {}, {})",
        ),
        "extra-import": (b"import sys\n", b"import sys\nimport subprocess\n"),
    }
    if mutation in replacements:
        old, new = replacements[mutation]
        assert source.count(old) == 1
        source = source.replace(old, new, 1)
    elif mutation == "bom":
        source = b"\xef\xbb\xbf" + source
    elif mutation == "cr":
        source = source.replace(b"\n", b"\r\n", 1)
    elif mutation == "nul":
        source = source.replace(b"\n", b"\x00\n", 1)
    elif mutation == "missing-terminal-lf":
        source = source[:-1]
    elif mutation == "bytes-subclass":

        class _BytesSubclass(bytes):
            pass

        source = _BytesSubclass(source)
    elif mutation == "bytearray":
        source = bytearray(source)
    else:
        raise AssertionError(mutation)

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_extract_host_root_python_fixed_loader_source_fragment(source)

    assert side_effect_calls == []


def _expected_host_root_python_fixed_loader_binding_source_bytes() -> bytes:
    encoded = base64.b64encode(
        _HOST_ROOT_PYTHON_FIXED_LOADER_EXPECTED_SOURCE_BYTES
    ).decode("ascii")
    lines = (
        f"[string]$loaderBase64='{encoded}'",
        "[byte[]]$loaderBytes=[Convert]::FromBase64String($loaderBase64)",
        "[string]$loaderSha256=[Convert]::ToHexString(",
        "    [Security.Cryptography.SHA256]::HashData($loaderBytes)",
        ").ToLowerInvariant()",
        "if ($loaderBytes.Length -ne 3532 -or",
        "    $loaderSha256 -cne",
        "        'cdc669417a69976cda27ba6bb4b3f027a7aaf022a99664630e1a207cf32ad666') {",
        "    throw 'C6 host root Python fixed loader byte binding mismatch'",
        "}",
        "[Text.UTF8Encoding]$strictUtf8=[Text.UTF8Encoding]::new($false,$true)",
        "[string]$loaderText=$strictUtf8.GetString($loaderBytes)",
        "[byte[]]$roundTripBytes=$strictUtf8.GetBytes($loaderText)",
        "if (-not [Security.Cryptography.CryptographicOperations]::FixedTimeEquals(",
        "        $loaderBytes,",
        "        $roundTripBytes",
        "    )) {",
        "    throw 'C6 host root Python fixed loader UTF-8 round trip mismatch'",
        "}",
        "Microsoft.PowerShell.Utility\\Set-Variable `",
        "    -Scope Script `",
        "    -Name C6HostRootPythonFixedLoaderSourceText `",
        "    -Value $loaderText `",
        "    -Option Constant",
        "Microsoft.PowerShell.Utility\\Set-Variable `",
        "    -Scope Script `",
        "    -Name C6HostRootPythonFixedLoaderSourceSize `",
        "    -Value 3532 `",
        "    -Option Constant",
        "Microsoft.PowerShell.Utility\\Set-Variable `",
        "    -Scope Script `",
        "    -Name C6HostRootPythonFixedLoaderSourceSha256 `",
        "    -Value 'cdc669417a69976cda27ba6bb4b3f027a7aaf022a99664630e1a207cf32ad666' `",
        "    -Option Constant",
        "",
    )
    return "\n".join(lines).encode("ascii")


def test_host_root_python_fixed_loader_binding_source_is_exact_and_dormant(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    expected_source = (
        _expected_host_root_python_fixed_loader_binding_source_bytes()
    )

    fragment = module._launch_host_root_python_fixed_loader_binding_source_fragment()

    assert fragment.version == (
        "complete-suite-host-root-python-fixed-loader-binding-source-fragment-v1"
    )
    assert fragment.implementation_id == "host-native-core-v1"
    assert fragment.activation_state == "dormant"
    assert fragment.loader_source_size == 3_532
    assert fragment.loader_source_sha256 == (
        "cdc669417a69976cda27ba6bb4b3f027a7aaf022a99664630e1a207cf32ad666"
    )
    assert fragment.variable_names == (
        "C6HostRootPythonFixedLoaderSourceText",
        "C6HostRootPythonFixedLoaderSourceSize",
        "C6HostRootPythonFixedLoaderSourceSha256",
    )
    assert fragment.source_bytes == expected_source
    assert fragment.source_bytes is not expected_source
    assert len(fragment.source_bytes) == 6_051
    assert fragment.source_sha256 == (
        "cbae9c5b94f6adb7eb60f1ec9a6c0c87306d4562cebf209bb8d66bebc74caf2d"
    )
    assert fragment.source_sha256 == sha256(expected_source).hexdigest()
    assert not hasattr(fragment, "__dict__")
    with pytest.raises((AttributeError, FrozenInstanceError)):
        fragment.source_bytes = b"$loaderText=''\n"
    assert not (Path(module.__file__).parent / "complete_suite_control_plane.ps1").exists()
    assert side_effect_calls == []


def test_host_root_python_fixed_loader_binding_decodes_only_normative_bytes(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    source = (
        module._launch_host_root_python_fixed_loader_binding_source_fragment()
        .source_bytes
    )
    match = re.search(rb"\[string\]\$loaderBase64='([A-Za-z0-9+/=]+)'\n", source)

    assert match is not None
    assert base64.b64decode(match.group(1), validate=True) == (
        _HOST_ROOT_PYTHON_FIXED_LOADER_EXPECTED_SOURCE_BYTES
    )
    assert source.count(b"[Convert]::FromBase64String($loaderBase64)") == 1
    assert source.count(b"[Text.UTF8Encoding]::new($false,$true)") == 1
    assert source.count(b"FixedTimeEquals(") == 1
    assert source.count(b"Microsoft.PowerShell.Utility\\Set-Variable") == 3
    assert source.count(b"-Option Constant") == 3
    for forbidden in (
        b"ScriptBlock",
        b"Invoke-Expression",
        b"Set-Alias",
        b"Import-Module",
        b"Add-Type",
        b"CreateProcessW",
        b"Start-Process",
        b"Process.Start",
        b"$env:",
        b"|",
    ):
        assert forbidden not in source
    assert side_effect_calls == []


