@pytest.mark.parametrize(
    "mutation",
    (
        "base64-byte",
        "decoder",
        "size",
        "hash",
        "decode-before-hash",
        "permissive-utf8",
        "missing-roundtrip",
        "roundtrip-input",
        "variable-order",
        "nonconstant",
        "alternate-set-variable",
        "scriptblock",
        "pipeline",
        "prefix",
        "suffix",
        "bom",
        "cr",
        "nul",
        "missing-terminal-lf",
        "bytes-subclass",
        "bytearray",
    ),
)
def test_host_root_python_fixed_loader_binding_extractor_rejects_mutants(
    mutation: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    source: object = (
        _expected_host_root_python_fixed_loader_binding_source_bytes()
    )
    replacements = {
        "decoder": (
            b"[Convert]::FromBase64String($loaderBase64)",
            b"[Text.Encoding]::UTF8.GetBytes($loaderBase64)",
        ),
        "size": (b"$loaderBytes.Length -ne 3532", b"$loaderBytes.Length -ne 3531"),
        "hash": (
            b"cdc669417a69976cda27ba6bb4b3f027a7aaf022a99664630e1a207cf32ad666",
            b"0dc669417a69976cda27ba6bb4b3f027a7aaf022a99664630e1a207cf32ad666",
        ),
        "permissive-utf8": (
            b"[Text.UTF8Encoding]::new($false,$true)",
            b"[Text.UTF8Encoding]::new($false,$false)",
        ),
        "missing-roundtrip": (
            b"-not [Security.Cryptography.CryptographicOperations]::FixedTimeEquals(",
            b"$false -and [Security.Cryptography.CryptographicOperations]::FixedTimeEquals(",
        ),
        "roundtrip-input": (b"$roundTripBytes", b"$loaderBytes",),
        "nonconstant": (b"-Option Constant", b"-Option ReadOnly"),
        "alternate-set-variable": (
            b"Microsoft.PowerShell.Utility\\Set-Variable",
            b"Set-Variable",
        ),
    }
    if mutation == "base64-byte":
        match = re.search(rb"loaderBase64='([A-Za-z0-9+/=]+)'", source)
        assert match is not None
        encoded = match.group(1)
        replacement = (b"A" if encoded[:1] != b"A" else b"B") + encoded[1:]
        source = source.replace(encoded, replacement, 1)
    elif mutation in replacements:
        old, new = replacements[mutation]
        assert source.count(old) >= 1
        source = source.replace(old, new, 1)
    elif mutation == "decode-before-hash":
        decode = b"[string]$loaderText=$strictUtf8.GetString($loaderBytes)\n"
        source = source.replace(decode, b"", 1).replace(
            b"[string]$loaderSha256=",
            decode + b"[string]$loaderSha256=",
            1,
        )
    elif mutation == "variable-order":
        source = source.replace(
            b"C6HostRootPythonFixedLoaderSourceText",
            b"C6HostRootPythonFixedLoaderSourceSize",
            1,
        )
    elif mutation == "scriptblock":
        source += b"[ScriptBlock]::Create($loaderText)\n"
    elif mutation == "pipeline":
        source += b"$loaderText | Write-Output\n"
    elif mutation == "prefix":
        source = b"$unexpected=$true\n" + source
    elif mutation == "suffix":
        source += b"\n"
    elif mutation == "bom":
        source = b"\xef\xbb\xbf" + source
    elif mutation == "cr":
        source = source.replace(b"\n", b"\r\n", 1)
    elif mutation == "nul":
        source = source.replace(b"\n", b"\x00\n", 1)
    elif mutation == "missing-terminal-lf":
        source = source[:-1]
    elif mutation == "bytes-subclass":

        class _BytesSubclass(bytes):
            pass

        source = _BytesSubclass(source)
    elif mutation == "bytearray":
        source = bytearray(source)
    else:
        raise AssertionError(mutation)

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_extract_host_root_python_fixed_loader_binding_source_fragment(
            source
        )

    assert side_effect_calls == []


def test_host_native_process_limit_registry_matches_exact_broker_root_and_git_tables(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    root_fixture = _BROKER_NATIVE_CORE_DRAFT_LIMIT_FIXTURES[0]
    git_fixture = _BROKER_NATIVE_CORE_DRAFT_LIMIT_FIXTURES[2]

    registry = module._launch_host_native_process_limit_registry()

    assert registry.version == "complete-suite-host-native-process-limit-registry-v1"
    assert registry.implementation_id == "host-native-core-v1"
    assert registry.table_ids == ("invoke-c6-root-python", "invoke-c6-git")
    assert registry.root_field_names == root_fixture[3]
    assert registry.root_rows == root_fixture[4]
    assert registry.root_payload_bytes == root_fixture[5]
    assert registry.root_payload_sha256 == root_fixture[6]
    assert registry.git_field_names == git_fixture[3]
    assert registry.git_rows == git_fixture[4]
    assert registry.git_payload_bytes == git_fixture[5]
    assert registry.git_payload_sha256 == git_fixture[6]
    assert len(registry.root_rows) == 17
    assert len(registry.git_rows) == 19
    assert len({row[0] for row in registry.root_rows}) == 17
    assert len({row[0] for row in registry.git_rows}) == 19
    assert sha256(registry.root_payload_bytes).hexdigest() == (
        "5ad682096b40c0a64c4792d5e1c17b3e350b0347751838309e1429a4848491c6"
    )
    assert sha256(registry.git_payload_bytes).hexdigest() == (
        "efa0f8e58274d800341664793fe6d84bf4407a159edf074c1279eeaeede8dd5f"
    )
    assert not hasattr(registry, "__dict__")
    with pytest.raises((AttributeError, FrozenInstanceError)):
        registry.root_rows = ()
    assert side_effect_calls == []


