def _expected_host_native_process_limit_source_bytes() -> bytes:
    root_fixture = _BROKER_NATIVE_CORE_DRAFT_LIMIT_FIXTURES[0]
    git_fixture = _BROKER_NATIVE_CORE_DRAFT_LIMIT_FIXTURES[2]
    lines = [
        "function Get-C6HostNativeProcessLimit {",
        "    [CmdletBinding()]",
        "    param(",
        "        [Parameter(Mandatory)][AllowNull()][object]$Launcher,",
        "        [Parameter(Mandatory)][AllowNull()][object]$Role",
        "    )",
        "    if ($Launcher -isnot [string] -or $Role -isnot [string]) {",
        "        throw 'C6 host native process limit selector type mismatch'",
        "    }",
        "    [string]$launcherText=$Launcher",
        "    [string]$roleText=$Role",
        "    [object[]]$rows=$null",
        "    switch -CaseSensitive ($launcherText) {",
    ]
    for launcher, fixture in (("root-python", root_fixture), ("git", git_fixture)):
        _constant, _selector, table_id, field_names, rows, _payload, digest = fixture
        lines.extend((f"        '{launcher}' {{", "            [object[]]$rows=@("))
        for row in rows:
            lines.append("                [pscustomobject][ordered]@{")
            lines.append(f"                    table_id='{table_id}'")
            for field_name, value in zip(field_names, row, strict=True):
                rendered = f"'{value}'" if isinstance(value, str) else str(value)
                lines.append(f"                    {field_name}={rendered}")
            lines.append(f"                    table_sha256='{digest}'")
            lines.append("                }")
        lines.extend(("            )", "            break", "        }"))
    lines.extend(
        (
            "        default {",
            "            throw 'C6 host native process limit launcher is not closed'",
            "        }",
            "    }",
            "    if ($null -eq $rows -or $rows.Count -eq 0) {",
            "        throw 'C6 host native process limit table is empty'",
            "    }",
            "    [Collections.Generic.List[object]]$matches=",
            "        [Collections.Generic.List[object]]::new()",
            "    foreach ($row in $rows) {",
            "        if ($row.role -ceq $roleText) {",
            "            [void]$matches.Add($row)",
            "        }",
            "    }",
            "    if ($matches.Count -ne 1) {",
            "        throw 'C6 host native process limit role is not closed'",
            "    }",
            "    return $matches[0]",
            "}",
            "",
        )
    )
    return "\n".join(lines).encode("ascii")


