@pytest.mark.parametrize(
    "mutation",
    (
        "typed-launcher",
        "typed-role",
        "case-insensitive-switch",
        "case-insensitive-role",
        "missing-root-row",
        "missing-git-row",
        "root-deadline",
        "git-cap",
        "root-digest",
        "git-digest",
        "duplicate-match-accepted",
        "unknown-launcher-fallback",
        "pipeline",
        "alias",
        "prefix",
        "suffix",
        "bom",
        "cr",
        "nul",
        "missing-terminal-lf",
        "bytes-subclass",
        "bytearray",
    ),
)
def test_host_native_process_limit_source_extractor_rejects_closed_surface_mutants(
    mutation: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    source: object = _expected_host_native_process_limit_source_bytes()
    replacements = {
        "typed-launcher": (
            b"[Parameter(Mandatory)][AllowNull()][object]$Launcher",
            b"[Parameter(Mandatory)][string]$Launcher",
        ),
        "typed-role": (
            b"[Parameter(Mandatory)][AllowNull()][object]$Role",
            b"[Parameter(Mandatory)][string]$Role",
        ),
        "case-insensitive-switch": (
            b"switch -CaseSensitive ($launcherText)",
            b"switch ($launcherText)",
        ),
        "case-insensitive-role": (b"$row.role -ceq $roleText", b"$row.role -eq $roleText"),
        "missing-root-row": (
            b"                    role='development-pytest'",
            b"                    role='development-pytest-missing'",
        ),
        "missing-git-row": (
            b"                    role='read-source-identity'",
            b"                    role='read-source-identity-missing'",
        ),
        "root-deadline": (b"                    deadline_ms=900000", b"                    deadline_ms=900001"),
        "git-cap": (
            b"                    table_id='invoke-c6-git'\n"
            b"                    role='read-source-identity'\n"
            b"                    deadline_ms=120000\n"
            b"                    stdout_cap_bytes=4194304",
            b"                    table_id='invoke-c6-git'\n"
            b"                    role='read-source-identity'\n"
            b"                    deadline_ms=120000\n"
            b"                    stdout_cap_bytes=4194305",
        ),
        "root-digest": (
            b"5ad682096b40c0a64c4792d5e1c17b3e350b0347751838309e1429a4848491c6",
            b"0ad682096b40c0a64c4792d5e1c17b3e350b0347751838309e1429a4848491c6",
        ),
        "git-digest": (
            b"efa0f8e58274d800341664793fe6d84bf4407a159edf074c1279eeaeede8dd5f",
            b"0fa0f8e58274d800341664793fe6d84bf4407a159edf074c1279eeaeede8dd5f",
        ),
        "duplicate-match-accepted": (b"$matches.Count -ne 1", b"$matches.Count -lt 1"),
        "unknown-launcher-fallback": (
            b"throw 'C6 host native process limit launcher is not closed'",
            b"[object[]]$rows=@()",
        ),
    }
    if mutation in replacements:
        old, new = replacements[mutation]
        assert source.count(old) >= 1
        source = source.replace(old, new, 1)
    elif mutation == "pipeline":
        source = source.replace(b"    return $matches[0]\n", b"    $matches | Write-Output\n", 1)
    elif mutation == "alias":
        source += b"Set-Alias -Name Get-C6HostNativeProcessLimit -Value Write-Output\n"
    elif mutation == "prefix":
        source = b"$unexpected=$true\n" + source
    elif mutation == "suffix":
        source += b"\n"
    elif mutation == "bom":
        source = b"\xef\xbb\xbf" + source
    elif mutation == "cr":
        source = source.replace(b"\n", b"\r\n", 1)
    elif mutation == "nul":
        source = source.replace(b"\n", b"\x00\n", 1)
    elif mutation == "missing-terminal-lf":
        source = source[:-1]
    elif mutation == "bytes-subclass":

        class _BytesSubclass(bytes):
            pass

        source = _BytesSubclass(source)
    elif mutation == "bytearray":
        source = bytearray(source)
    else:
        raise AssertionError(mutation)

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_extract_host_native_process_limit_source_fragment(source)

    assert side_effect_calls == []


_HOST_NATIVE_ENVIRONMENT_BLOCK_EXPECTED_SOURCE_BYTES = rb"""function New-C6HostNativeEnvironmentBlock {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][AllowNull()][object]$Environment
    )
    if ($null -eq $Environment -or
        $Environment.GetType() -ne
            [Collections.Specialized.OrderedDictionary]) {
        throw 'C6 host native environment is not an exact ordered dictionary'
    }
    [object[]]$entries=@($Environment.GetEnumerator())
    if ($entries.Count -eq 0 -or
        $entries.Count -ne $Environment.Count) {
        throw 'C6 host native environment is empty or unstable'
    }
    [Collections.Generic.HashSet[string]]$caseKeys=
        [Collections.Generic.HashSet[string]]::new(
            [StringComparer]::OrdinalIgnoreCase
        )
    [Collections.Generic.List[string]]$names=
        [Collections.Generic.List[string]]::new()
    foreach ($entry in $entries) {
        if ($entry -isnot [Collections.DictionaryEntry] -or
            $entry.Key -isnot [string] -or
            $entry.Value -isnot [string]) {
            throw 'C6 host native environment entry type mismatch'
        }
        [string]$name=$entry.Key
        [string]$value=$entry.Value
        Assert-C6HostNativeVectorString -Value $name
        Assert-C6HostNativeVectorString -Value $value
        if ($name -cnotmatch '^[A-Z][A-Z0-9_]*$' -or
            $value.IndexOf([char]13) -ge 0 -or
            $value.IndexOf([char]10) -ge 0 -or
            -not $caseKeys.Add($name)) {
            throw 'C6 host native environment entry is not closed'
        }
        [void]$names.Add($name)
    }
    $names.Sort([StringComparer]::Ordinal)
    $builder=[Text.StringBuilder]::new()
    foreach ($name in $names) {
        [string]$value=$Environment[$name]
        [void]$builder.Append($name)
        [void]$builder.Append('=')
        [void]$builder.Append($value)
        [void]$builder.Append([char]0)
    }
    [void]$builder.Append([char]0)
    [string]$blockText=$builder.ToString()
    if ($blockText.Length -lt 2 -or
        $blockText[$blockText.Length - 1] -ne [char]0 -or
        $blockText[$blockText.Length - 2] -ne [char]0) {
        throw 'C6 host native environment block termination mismatch'
    }
    [byte[]]$serializedBytes=[Text.Encoding]::Unicode.GetBytes($blockText)
    if ($serializedBytes.Length -ne 2 * $blockText.Length) {
        throw 'C6 host native environment UTF-16 length mismatch'
    }
    [string]$digest=[Convert]::ToHexString(
        [Security.Cryptography.SHA256]::HashData($serializedBytes)
    ).ToLowerInvariant()
    return [pscustomobject][ordered]@{
        contract='complete-suite-windows-environment-block-v1'
        entry_count=$names.Count
        utf16_units=$blockText.Length
        utf16le_sha256=$digest
        block_text=$blockText
        block_bytes=$serializedBytes
    }
}
"""


