        b"$env:",
        b"GetEnvironmentVariable",
        b"GetEnvironmentVariables",
        b"ConvertFrom-Json",
        b"Invoke-Expression",
        b"Set-Alias",
        b"Import-Module",
        b"Add-Type",
        b"CreateProcessW",
