def test_host_native_control_plane_candidate_has_exact_component_and_function_order(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    fragment = module._launch_host_native_control_plane_candidate_source_fragment()
    source = fragment.source_bytes
    components = (
        _HOST_NATIVE_VECTOR_SOURCE_BYTES,
        module._launch_host_native_core_initializer_source_fragment().source_bytes,
        _expected_host_root_python_fixed_loader_binding_source_bytes(),
        _expected_host_native_process_limit_source_bytes(),
        _HOST_NATIVE_ENVIRONMENT_BLOCK_EXPECTED_SOURCE_BYTES,
        _HOST_NATIVE_CONSTRUCTOR_CALL_GRAPH_SYNTHETIC_SOURCE_BYTES,
    )
    cursor = 0
    for component, digest in zip(
        components,
        fragment.component_sha256s,
        strict=True,
    ):
        assert source[cursor : cursor + len(component)] == component
        assert sha256(component).hexdigest() == digest
        cursor += len(component)
    assert cursor == len(source)
    function_names = tuple(
        match.group(1).decode("ascii")
        for match in re.finditer(rb"(?m)^function ([A-Za-z][A-Za-z0-9-]*) \{\n", source)
    )
    assert function_names == (
        "Assert-C6HostNativeVectorString",
        "ConvertTo-C6HostNativeArgument",
        "New-C6HostNativeVector",
        "Get-C6HostNativeProcessLimit",
        "New-C6HostNativeEnvironmentBlock",
        *_HOST_NATIVE_CONSTRUCTOR_CALL_GRAPH_FUNCTION_NAMES,
    )
    assert len({name.casefold() for name in function_names}) == len(function_names)
    assert source.count(b"process_created=$false") == 1
    assert source.count(b"Microsoft.PowerShell.Management\\Set-Item") == 2
    assert source.count(b"Microsoft.PowerShell.Utility\\Set-Variable") == 3
    assert source.count(b"Function:\\script:Initialize-C6HostNativeCoreV1") == 4
    assert side_effect_calls == []


