    drift_indexes = {
        "vector-drift": 0,
        "initializer-drift": 1,
        "loader-binding-drift": 2,
        "process-limit-drift": 3,
        "environment-block-drift": 4,
        "call-graph-drift": 5,
    }
    if mutation in missing_indexes:
        del components[missing_indexes[mutation]]
        source = b"".join(components)
    elif mutation == "swap-loader-and-limit":
        components[2], components[3] = components[3], components[2]
        source = b"".join(components)
    elif mutation == "duplicate-vector":
        source = components[0] + source
    elif mutation in drift_indexes:
        index = drift_indexes[mutation]
        component = components[index]
        components[index] = component[:-2] + b" \n"
        source = b"".join(components)
    elif mutation == "prefix":
        source = b"$unexpected=$true\n" + source
