def test_broker_native_control_plane_candidate_extracts_exact_dormant_tail(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    bootstrap = BOOTSTRAP_PATH.read_bytes()
    expected_source = (
        _expected_broker_native_control_plane_candidate_source_bytes()
    )

    fragment = (
        module._launch_extract_broker_native_control_plane_candidate_from_bootstrap_source(
            bootstrap
        )
    )

    assert fragment.version == (
        "complete-suite-broker-native-control-plane-candidate-source-fragment-v1"
    )
    assert fragment.implementation_id == "broker-native-core-v1"
    assert fragment.source_relative_path == (
        "tests/skills/complete_suite_release_python_bootstrap.py"
    )
    assert fragment.activation_state == "draft-dormant-incomplete"
    assert fragment.completeness_state == (
        "facts-and-helper-prerequisites-only"
    )
    assert fragment.class_names == (
        _BROKER_NATIVE_CONTROL_PLANE_CANDIDATE_CLASS_NAMES
    )
    assert fragment.function_names == (
        _BROKER_NATIVE_CONTROL_PLANE_CANDIDATE_FUNCTION_NAMES
    )
    assert fragment.source_bytes == expected_source
    assert fragment.source_bytes is not expected_source
    assert len(fragment.source_bytes) == 299_650
    assert fragment.source_sha256 == (
        "64abf0e86c9fb674fff613a7659bc3bf1a9b314b985844304f16f869b4325aae"
    )
    assert fragment.source_sha256 == sha256(expected_source).hexdigest()
    assert fragment.source_bytes.startswith(
        _BROKER_NATIVE_CONTROL_PLANE_CANDIDATE_SENTINEL
    )
    assert fragment.source_bytes.endswith(b"\n")
    assert b"\r" not in fragment.source_bytes
    assert b"\x00" not in fragment.source_bytes
    assert b"C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-BEGIN" not in (
        fragment.source_bytes
    )
    assert b"C6-BROKER-NATIVE-CONSTRUCTOR-IMPLEMENTATION-END" not in (
        fragment.source_bytes
    )

    tree = ast.parse(fragment.source_bytes.decode("utf-8", errors="strict"))
    assert not any(
        isinstance(node, (ast.Import, ast.ImportFrom)) for node in ast.walk(tree)
    )
    forbidden_call_names = {
        "CreateProcess",
        "CreateProcessW",
        "Popen",
        "WinDLL",
        "__import__",
        "compile",
        "eval",
        "exec",
        "open",
        "run",
        "spawnv",
        "spawnve",
        "startfile",
        "system",
    }
    observed_call_names = {
        node.func.id
        if isinstance(node.func, ast.Name)
        else node.func.attr
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, (ast.Name, ast.Attribute))
    }
    assert not observed_call_names & forbidden_call_names
    assert not hasattr(fragment, "__dict__")
    with pytest.raises((AttributeError, FrozenInstanceError)):
        fragment.activation_state = "complete"
    assert not (
        Path(module.__file__).parent / "complete_suite_control_plane.ps1"
    ).exists()
    assert side_effect_calls == []


