def test_native_leaf_capture_binds_literal_source_policy_material() -> None:
    module = _preflight()
    source_authority = _native_leaf_source_policy_authority(module)
    source_sha256 = sha256(
        _NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_BYTES
    ).hexdigest()
    expected = (
        (
            "git",
            _NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_RELATIVE_PATH,
            source_sha256,
            _NATIVE_LEAF_SYNTHETIC_GIT_ARGV_POLICY_BYTES,
            sha256(_NATIVE_LEAF_SYNTHETIC_GIT_ARGV_POLICY_BYTES).hexdigest(),
            _NATIVE_LEAF_SYNTHETIC_GIT_ENVIRONMENT_POLICY_BYTES,
            sha256(
                _NATIVE_LEAF_SYNTHETIC_GIT_ENVIRONMENT_POLICY_BYTES
            ).hexdigest(),
            _NATIVE_LEAF_SYNTHETIC_GIT_CWD_POLICY_BYTES,
            sha256(_NATIVE_LEAF_SYNTHETIC_GIT_CWD_POLICY_BYTES).hexdigest(),
            "case-root",
        ),
        (
            "node",
            _NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_RELATIVE_PATH,
            source_sha256,
            _NATIVE_LEAF_SYNTHETIC_NODE_ARGV_POLICY_BYTES,
            sha256(_NATIVE_LEAF_SYNTHETIC_NODE_ARGV_POLICY_BYTES).hexdigest(),
            _NATIVE_LEAF_SYNTHETIC_NODE_ENVIRONMENT_POLICY_BYTES,
            sha256(
                _NATIVE_LEAF_SYNTHETIC_NODE_ENVIRONMENT_POLICY_BYTES
            ).hexdigest(),
            _NATIVE_LEAF_SYNTHETIC_NODE_CWD_POLICY_BYTES,
            sha256(_NATIVE_LEAF_SYNTHETIC_NODE_CWD_POLICY_BYTES).hexdigest(),
            "case-root",
        ),
    )
    assert source_authority.source_policy_bytes == (
        _NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_BYTES
    )
    assert source_authority.source_sha256 == source_sha256
    assert source_authority.constructor_implementations == (
        ("host-native-core-v1", "a" * 64),
        ("broker-native-core-v1", "b" * 64),
    )
    with pytest.raises(FrozenInstanceError):
        source_authority.source_sha256 = "f" * 64
    assert "git.exe" not in repr(source_authority)
    with pytest.raises(TypeError):
        module._launch_build_native_leaf_construction_authority(
            host_implementation_sha256="a" * 64,
            broker_implementation_sha256="b" * 64,
        )
    assert tuple(
        (
            policy.role,
            policy.source_relative_path,
            policy.source_sha256,
            policy.argv_grammar_bytes,
            policy.argv_grammar_sha256,
            policy.environment_grammar_bytes,
            policy.environment_grammar_sha256,
            policy.cwd_policy_bytes,
            policy.cwd_policy_sha256,
            policy.cwd_role,
        )
        for policy in source_authority.role_policies
    ) == expected

    construction_authority = (
        module._launch_build_native_leaf_construction_authority(
            source_policy_authority=source_authority,
        )
    )
    assert tuple(
        (
            policy.role,
            policy.source_relative_path,
            policy.source_sha256,
            policy.argv_grammar_bytes,
            policy.argv_grammar_sha256,
            policy.environment_grammar_bytes,
            policy.environment_grammar_sha256,
            policy.cwd_policy_bytes,
            policy.cwd_policy_sha256,
            policy.cwd_role,
        )
        for policy in construction_authority.role_policies
    ) == expected


@pytest.mark.parametrize(
    "mutation",
    (
        "leading-whitespace",
        "duplicate-key",
        "unknown-key",
        "wrong-role-order",
        "non-ascii",
        "mutable-bytes",
        "parent-source-path",
        "implementation-order",
    ),
)
def test_native_leaf_capture_source_policy_parser_rejects_noncanonical_material(
    mutation: str,
) -> None:
    module = _preflight()
    source_relative_path = _NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_RELATIVE_PATH
    source_policy_bytes: object = _NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_BYTES
    constructor_implementations = (
        ("host-native-core-v1", "a" * 64),
        ("broker-native-core-v1", "b" * 64),
    )
    if mutation == "leading-whitespace":
        source_policy_bytes = b" " + _NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_BYTES
    elif mutation == "duplicate-key":
        source_policy_bytes = _NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_BYTES.replace(
            b'{"role":"git",',
            b'{"role":"git","role":"git",',
            1,
        )
    elif mutation == "unknown-key":
        source_policy_bytes = _NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_BYTES.replace(
            b'{"role":"git","argv_grammar":',
            b'{"role":"git","unknown":false,"argv_grammar":',
            1,
        )
    elif mutation == "wrong-role-order":
        source_policy_bytes = _NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_BYTES.replace(
            b'"role":"git"',
            b'"role":"node"',
            1,
        )
    elif mutation == "non-ascii":
        source_policy_bytes = _NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_BYTES + b"\x80"
    elif mutation == "mutable-bytes":
        source_policy_bytes = bytearray(_NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_BYTES)
    elif mutation == "parent-source-path":
        source_relative_path = "../synthetic-native-leaf-source-policy.json"
    elif mutation == "implementation-order":
        constructor_implementations = tuple(reversed(constructor_implementations))
    else:
        raise AssertionError(mutation)
    digest_bytes = (
        bytes(source_policy_bytes)
        if isinstance(source_policy_bytes, (bytes, bytearray))
        else b""
    )
    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_parse_native_leaf_source_policy_authority(
            source_relative_path=source_relative_path,
            source_policy_bytes=source_policy_bytes,
            source_sha256=sha256(digest_bytes).hexdigest(),
            constructor_implementations=constructor_implementations,
        )


def test_native_leaf_capture_rejects_coordinated_source_policy_drift_before_callbacks(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    _git_supplied, program_files, git_paths, git_facts = (
        _filesystem_native_leaf_fixture(tmp_path, role="git")
    )
    _node_supplied, _node_program_files, node_paths, node_facts = (
        _filesystem_native_leaf_fixture(tmp_path, role="node")
    )
    authority = _native_leaf_construction_authority(module)
    monkeypatch.setattr(module, "_launch_program_files_root", lambda: program_files)
    monkeypatch.setattr(
        module,
        "_launch_pe_version_fields",
        lambda path: git_facts[2:] if Path(path).name == "git.exe" else node_facts[2:],
    )
    monkeypatch.setattr(
        module,
        "_launch_native_leaf_fixed_facts",
        lambda role: git_facts if role == "git" else None,
        raising=False,
    )
    monkeypatch.setattr(
        module,
        "_launch_load_native_leaf_construction_authority",
        lambda: authority,
        raising=False,
    )
    captured = module._launch_capture_native_leaves(
        git_path=git_paths[-1],
        node_path=node_paths[0],
    )
    calls = _guard_native_leaf_side_effects(monkeypatch)
    drifted_source_bytes = _NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_BYTES.replace(
        b'"executable":"git.exe"',
        b'"executable":"git.com"',
        1,
    )
    assert drifted_source_bytes != _NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_BYTES
    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_parse_native_leaf_source_policy_authority(
            source_relative_path=(
                _NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_RELATIVE_PATH
            ),
            source_policy_bytes=drifted_source_bytes,
            source_sha256=sha256(
                _NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_BYTES
            ).hexdigest(),
            constructor_implementations=(
                ("host-native-core-v1", "a" * 64),
                ("broker-native-core-v1", "b" * 64),
            ),
        )
    drifted_source_authority = (
        module._launch_parse_native_leaf_source_policy_authority(
            source_relative_path=(
                _NATIVE_LEAF_SYNTHETIC_POLICY_SOURCE_RELATIVE_PATH
            ),
            source_policy_bytes=drifted_source_bytes,
            source_sha256=sha256(drifted_source_bytes).hexdigest(),
            constructor_implementations=(
                ("host-native-core-v1", "a" * 64),
                ("broker-native-core-v1", "b" * 64),
            ),
        )
    )
    drifted_authority = module._launch_build_native_leaf_construction_authority(
        source_policy_authority=drifted_source_authority,
    )
    monkeypatch.setattr(
        module,
        "_launch_load_native_leaf_construction_authority",
        lambda: drifted_authority,
    )

    def forbidden_capture(*_args: object, **_kwargs: object) -> object:
        calls.append("capture")
        pytest.fail("source-policy drift reached executable capture")

    monkeypatch.setattr(
        module,
        "_launch_capture_native_leaf_facts",
        forbidden_capture,
    )
    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_recapture_native_leaf(captured[0])
    assert calls == []


def test_native_leaf_capture_binds_main_git_and_node_without_execution(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    git_supplied, program_files, git_paths, git_facts = (
        _filesystem_native_leaf_fixture(tmp_path, role="git")
    )
    node_supplied, node_program_files, node_paths, node_facts = (
        _filesystem_native_leaf_fixture(tmp_path, role="node")
    )
    assert node_program_files == program_files
    authority = _native_leaf_construction_authority(module)
    monkeypatch.setattr(module, "_launch_program_files_root", lambda: program_files)
    monkeypatch.setattr(
        module,
        "_launch_pe_version_fields",
        lambda path: git_facts[2:] if Path(path).name == "git.exe" else node_facts[2:],
    )
    monkeypatch.setattr(
        module,
        "_launch_native_leaf_fixed_facts",
        lambda role: git_facts if role == "git" else None,
        raising=False,
    )
    calls = _guard_native_leaf_side_effects(monkeypatch)
    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_capture_native_leaves(
            git_path=git_paths[-1],
            node_path=node_paths[0],
        )
    monkeypatch.setattr(
        module,
        "_launch_load_native_leaf_construction_authority",
        lambda: authority,
        raising=False,
    )

    captured = module._launch_capture_native_leaves(
        git_path=git_paths[-1],
        node_path=node_paths[0],
    )

    assert tuple(item.role for item in captured) == ("git", "node")
    assert tuple(item.executable_path for item in captured) == (
        str(git_paths[-1]),
        str(node_paths[0]),
    )
    assert tuple(item.hardlink_paths for item in captured) == (
        tuple(sorted((str(path) for path in git_paths), key=lambda item: (item.casefold(), item))),
        (str(node_paths[0]),),
    )
    assert tuple(
        (
            item.executable_size,
            item.executable_sha256,
            item.file_version,
            item.product_version,
        )
        for item in captured
    ) == (git_facts, node_facts)
    policies = {policy.role: policy for policy in authority.role_policies}
    for item in captured:
        policy = policies[item.role]
        assert (
            item.argv_grammar_sha256,
            item.environment_grammar_sha256,
            item.cwd_role,
            item.permitted_constructor_implementations,
            item.constructor_implementation_set_sha256,
            item.constructor_attribute_set_sha256,
            item.job_topology_sha256,
        ) == (
            policy.argv_grammar_sha256,
            policy.environment_grammar_sha256,
            policy.cwd_role,
            policy.permitted_constructor_implementations,
            policy.constructor_implementation_set_sha256,
            authority.constructor_attribute_set_sha256,
            authority.job_topology_sha256,
        )
    assert captured[0] == git_supplied and captured[0] is not git_supplied
    assert captured[1] == node_supplied and captured[1] is not node_supplied
    assert tuple(
        module._launch_recapture_native_leaf(item) for item in captured
    ) == captured
    assert calls == []


