def test_launch_snapshot_manifest_decoder_round_trips_only_canonical_bytes(
    tmp_path: Path,
) -> None:
    module = _preflight()
    snapshot = _snapshot(present=True, content=UPDATE_BYTES)
    path = tmp_path / "after-update.json"
    payload = _canonical(module._snapshot_record(snapshot))
    path.write_bytes(payload)

    detached = module._launch_decode_snapshot_manifest(
        path,
        expected=snapshot,
    )

    assert detached == snapshot
    assert detached is not snapshot
    assert detached.root_identity is not snapshot.root_identity
    assert detached.entries[0] is not snapshot.entries[0]
    assert detached.entries[0].identity is not snapshot.entries[0].identity

    path.write_bytes(payload + b"\n")
    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_decode_snapshot_manifest(path, expected=snapshot)


