def test_launch_evaluation_records_reject_recanonicalized_alternate_case_universe(
    tmp_path: Path,
) -> None:
    module = _preflight()
    original = _launch_preflight(tmp_path)
    records = list(original.evaluation_records)
    alternate_case_ids = tuple(
        f"unapproved-alternate-case-{ordinal:02d}"
        for ordinal in range(1, 13)
    )
    for offset, record in enumerate(records[4:]):
        evaluation = module._launch_decode_evaluation_record(record)
        recanonicalized = _unchecked_recanonical_evaluation(
            evaluation,
            case_id=alternate_case_ids[offset % 12],
        )
        records[offset + 4] = module.CapturedLaunchInput(
            path=record.path,
            content=recanonicalized.canonical_bytes,
            utf8_bytes=len(recanonicalized.canonical_bytes),
            sha256=sha256(recanonicalized.canonical_bytes).hexdigest(),
            identity=record.identity,
        )
    forged_records = tuple(records)
    forged = _unchecked_replace(
        original,
        evaluation_records=forged_records,
        evaluation_manifest_sha256=_evaluation_manifest_sha256(forged_records),
    )

    with pytest.raises(RuntimeError, match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$"):
        module._validate_launch_preflight_structure(forged)


