def _forbid_launch_freeze_runtime(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    def forbidden(*_args: object, **_kwargs: object) -> object:
        pytest.fail("synthetic launch freeze attempted process or socket activity")

    monkeypatch.setattr(subprocess, "Popen", forbidden)
    monkeypatch.setattr(subprocess, "run", forbidden)
    monkeypatch.setattr(socket, "socket", forbidden)


def _launch_guarded_runtime_transaction_fixture(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> tuple[object, dict[str, object], object, object]:
    module = _preflight()
    guarded_paths = _guarded_runtime_fixture(
        tmp_path / "guarded-runtime-sources",
        monkeypatch,
    )
    api_inputs = _launch_freeze_api_inputs(tmp_path / "launch-inputs")
    source_root = api_inputs["source_root"]
    project_path = source_root / "pyproject.toml"
    bootstrap_path = (
        source_root
        / "tests"
        / "skills"
        / "complete_suite_release_python_bootstrap.py"
    )
    project_path.write_bytes(guarded_paths["project_path"].read_bytes())
    bootstrap_path.write_bytes(guarded_paths["bootstrap_path"].read_bytes())
    project_capture = _actual_capture(project_path)
    bootstrap_capture = _actual_capture(bootstrap_path)
    api_inputs.update(
        {
            "python_path": guarded_paths["python_path"],
            "project_metadata": project_capture,
            "expected_project_metadata_sha256": project_capture.sha256,
            "guard_bootstrap": bootstrap_capture,
            "expected_guard_bootstrap_sha256": bootstrap_capture.sha256,
            "python_distribution_roots": guarded_paths["distribution_roots"],
        }
    )
    inputs = module._launch_capture_freeze_inputs(**api_inputs)
    created_objects: dict[Path, object] = {}
    creation_session = module.file_change_policy._HeldNoFollowCreationSession(
        inputs.output_root.parent,
        code=module.LAUNCH_PREFLIGHT_BUNDLE_INVALID,
    )
    root_identity = module._validator_create_directory(
        inputs.output_root,
        creation_session=creation_session,
        created_objects=created_objects,
    )
    transaction = module._LaunchFreezeTransaction(
        root=inputs.output_root,
        root_identity=root_identity,
        creation_session=creation_session,
        created_objects=created_objects,
    )
    return module, guarded_paths, inputs, transaction


def _cleanup_launch_guarded_runtime_transaction(
    module: object,
    transaction: object,
) -> None:
    if transaction.root.exists():
        module._validator_remove_created_root(
            transaction.root,
            expected_root_identity=transaction.root_identity,
            created_objects=transaction.created_objects,
            creation_session=transaction.creation_session,
            max_entries=module._LAUNCH_BUNDLE_ENTRY_CAP,
            max_bytes=module._LAUNCH_BUNDLE_BYTE_CAP,
        )
    if not transaction.creation_session.closed:
        transaction.creation_session.close()


def test_launch_guarded_runtime_materialization_reuses_transaction_authority(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    _forbid_launch_freeze_runtime(monkeypatch)
    module, _guarded_paths, inputs, transaction = (
        _launch_guarded_runtime_transaction_fixture(tmp_path, monkeypatch)
    )
    native_create_directory = module._validator_create_directory
    native_exclusive_write = module._validator_exclusive_write
    observed_creations: list[tuple[str, Path]] = []

    def create_directory(
        path: Path,
        *,
        creation_session: object,
        created_objects: object,
    ) -> object:
        assert creation_session is transaction.creation_session
        assert created_objects is transaction.created_objects
        observed_creations.append(("directory", path))
        return native_create_directory(
            path,
            creation_session=creation_session,
            created_objects=created_objects,
        )

    def write_file(
        path: Path,
        payload: bytes,
        *,
        creation_session: object,
        created_objects: object,
    ) -> object:
        assert creation_session is transaction.creation_session
        assert created_objects is transaction.created_objects
        observed_creations.append(("file", path))
        return native_exclusive_write(
            path,
            payload,
            creation_session=creation_session,
            created_objects=created_objects,
        )

    def forbidden_session(*_args: object, **_kwargs: object) -> object:
        pytest.fail("launch guarded runtime opened a second creation session")

    def forbidden_flush(_path: Path) -> None:
        pytest.fail("launch guarded runtime flushed the outer transaction")

    monkeypatch.setattr(module, "_validator_create_directory", create_directory)
    monkeypatch.setattr(module, "_validator_exclusive_write", write_file)
    monkeypatch.setattr(module, "_validator_flush_directory", forbidden_flush)
    monkeypatch.setattr(
        module.file_change_policy,
        "_HeldNoFollowCreationSession",
        forbidden_session,
    )

    try:
        runtime = module._launch_materialize_guarded_python_runtime(
            transaction=transaction,
            inputs=inputs,
        )

        runtime_root = transaction.root / "guarded-python-runtime"
        assert runtime.root == str(runtime_root)
        assert runtime == module.validate_frozen_guarded_python_runtime(runtime)
        assert observed_creations
        assert observed_creations[0] == ("directory", runtime_root)
        assert transaction.creation_session.closed is False
        assert transaction.publication_fence_reached is False
        expected_entries = module._launch_expected_transaction_entries(transaction)
        actual_entries = module._validator_capture_entries(
            transaction.root,
            max_entries=module._LAUNCH_BUNDLE_ENTRY_CAP,
            max_bytes=module._LAUNCH_BUNDLE_BYTE_CAP,
        )
        assert expected_entries == actual_entries
        assert set(transaction.created_objects) == {
            transaction.root,
            *(
                transaction.root.joinpath(
                    *Path(entry.relative_path).parts,
                )
                for entry in actual_entries
            ),
        }
    finally:
        _cleanup_launch_guarded_runtime_transaction(module, transaction)
    assert not transaction.root.exists()


def test_launch_guarded_runtime_failure_preserves_outer_cleanup_authority(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    _forbid_launch_freeze_runtime(monkeypatch)
    module, _guarded_paths, inputs, transaction = (
        _launch_guarded_runtime_transaction_fixture(tmp_path, monkeypatch)
    )
    native_exclusive_write = module._validator_exclusive_write
    write_count = 0

    def fail_second_write(
        path: Path,
        payload: bytes,
        *,
        creation_session: object,
        created_objects: object,
    ) -> object:
        nonlocal write_count
        assert creation_session is transaction.creation_session
        assert created_objects is transaction.created_objects
        write_count += 1
        if write_count == 2:
            raise RuntimeError(module.GUARDED_PYTHON_RUNTIME_INVALID)
        return native_exclusive_write(
            path,
            payload,
            creation_session=creation_session,
            created_objects=created_objects,
        )

    def forbidden_session(*_args: object, **_kwargs: object) -> object:
        pytest.fail("launch guarded runtime opened a second creation session")

    def forbidden_flush(_path: Path) -> None:
        pytest.fail("launch guarded runtime flushed the outer transaction")

    monkeypatch.setattr(module, "_validator_exclusive_write", fail_second_write)
    monkeypatch.setattr(module, "_validator_flush_directory", forbidden_flush)
    monkeypatch.setattr(
        module.file_change_policy,
        "_HeldNoFollowCreationSession",
        forbidden_session,
    )

    try:
        with pytest.raises(
            RuntimeError,
            match=r"^GUARDED_PYTHON_RUNTIME_INVALID$",
        ) as exc_info:
            module._launch_materialize_guarded_python_runtime(
                transaction=transaction,
                inputs=inputs,
            )
        assert exc_info.value.__cause__ is None
        assert write_count == 2
        assert transaction.creation_session.closed is False
        assert transaction.publication_fence_reached is False
        assert transaction.root.is_dir()
        assert (transaction.root / "guarded-python-runtime").is_dir()
        assert module._launch_expected_transaction_entries(
            transaction
        ) == module._validator_capture_entries(
            transaction.root,
            max_entries=module._LAUNCH_BUNDLE_ENTRY_CAP,
            max_bytes=module._LAUNCH_BUNDLE_BYTE_CAP,
        )
    finally:
        _cleanup_launch_guarded_runtime_transaction(module, transaction)
    assert transaction.creation_session.closed is True
    assert not transaction.root.exists()


@pytest.mark.parametrize(
    ("limit_name", "existing_kind"),
    (
        ("_LAUNCH_BUNDLE_ENTRY_CAP", "directory"),
        ("_LAUNCH_BUNDLE_BYTE_CAP", "file"),
    ),
)
def test_launch_guarded_runtime_rejects_exhausted_combined_transaction_limit(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    limit_name: str,
    existing_kind: Literal["directory", "file"],
) -> None:
    _forbid_launch_freeze_runtime(monkeypatch)
    module, _guarded_paths, inputs, transaction = (
        _launch_guarded_runtime_transaction_fixture(tmp_path, monkeypatch)
    )
    original_entry_cap = module._LAUNCH_BUNDLE_ENTRY_CAP
    original_byte_cap = module._LAUNCH_BUNDLE_BYTE_CAP
    if existing_kind == "directory":
        transaction.create_directory("existing")
        exhausted_limit = len(transaction.created_objects) - 1
    else:
        transaction.write_file("existing.bin", b"x")
        exhausted_limit = 1
    baseline_entries = module._validator_capture_entries(
        transaction.root,
        max_entries=original_entry_cap,
        max_bytes=original_byte_cap,
    )
    baseline_ledger = dict(transaction.created_objects)
    native_create_directory = module._validator_create_directory
    runtime_create_attempted = False

    def reject_runtime_create(
        path: Path,
        *,
        creation_session: object,
        created_objects: object,
    ) -> object:
        nonlocal runtime_create_attempted
        if path == transaction.root / "guarded-python-runtime":
            runtime_create_attempted = True
        return native_create_directory(
            path,
            creation_session=creation_session,
            created_objects=created_objects,
        )

    def forbidden_session(*_args: object, **_kwargs: object) -> object:
        pytest.fail("launch guarded runtime opened a second creation session")

    def forbidden_flush(_path: Path) -> None:
        pytest.fail("launch guarded runtime flushed the outer transaction")

    monkeypatch.setattr(module, limit_name, exhausted_limit)
    monkeypatch.setattr(
        module,
        "_validator_create_directory",
        reject_runtime_create,
    )
    monkeypatch.setattr(module, "_validator_flush_directory", forbidden_flush)
    monkeypatch.setattr(
        module.file_change_policy,
        "_HeldNoFollowCreationSession",
        forbidden_session,
    )

    try:
        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ) as exc_info:
            module._launch_materialize_guarded_python_runtime(
                transaction=transaction,
                inputs=inputs,
            )
        assert exc_info.value.__cause__ is None
        assert runtime_create_attempted is False
        assert transaction.creation_session.closed is False
        assert transaction.publication_fence_reached is False
        assert transaction.created_objects == baseline_ledger
        assert module._validator_capture_entries(
            transaction.root,
            max_entries=original_entry_cap,
            max_bytes=original_byte_cap,
        ) == baseline_entries
    finally:
        module._validator_remove_created_root(
            transaction.root,
            expected_root_identity=transaction.root_identity,
            created_objects=transaction.created_objects,
            creation_session=transaction.creation_session,
            max_entries=original_entry_cap,
            max_bytes=original_byte_cap,
        )
        if not transaction.creation_session.closed:
            transaction.creation_session.close()
    assert not transaction.root.exists()


