def _install_synthetic_launch_freeze_producer(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    *,
    failure: BaseException | None = None,
    mark_publication_fence: bool = True,
    inject_unknown_member: bool = False,
) -> tuple[object, dict[str, object], dict[str, object]]:
    module = _preflight()
    api_inputs = _launch_freeze_api_inputs(tmp_path)
    synthetic_preflight = _launch_preflight(tmp_path / "synthetic-preflight")
    observed: dict[str, object] = {"producer_calls": 0}

    def producer(*, transaction: object, inputs: object) -> object:
        observed["producer_calls"] = int(observed["producer_calls"]) + 1
        observed["transaction"] = transaction
        observed["inputs"] = inputs
        transaction.create_directory("contracts")
        transaction.write_file(
            "contracts/exact-config.toml",
            b"# synthetic exact config\n",
        )
        if inject_unknown_member:
            (transaction.root / "unexpected-untracked.bin").write_bytes(
                b"untracked\n"
            )
        if mark_publication_fence:
            transaction.mark_publication_fence()
        if failure is not None:
            raise failure
        return module._LaunchFreezeProducerResult(
            preflight=synthetic_preflight,
            client_invocations=4,
            loopback_exchanges=8,
            shell_invocations=2,
            file_add_invocations=1,
            file_update_invocations=1,
        )

    monkeypatch.setattr(
        module,
        "_launch_produce_preflight",
        producer,
        raising=False,
    )
    _forbid_launch_freeze_runtime(monkeypatch)
    return module, api_inputs, observed


def test_freeze_launch_preflight_uses_durable_private_transaction_and_detaches(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module, api_inputs, observed = _install_synthetic_launch_freeze_producer(
        tmp_path,
        monkeypatch,
    )
    output_root = api_inputs["output_root"]
    checkpoints: list[str] = []
    flushes: list[Path] = []
    real_flush = module._validator_flush_directory

    def checkpoint(stage: str, path: Path) -> None:
        checkpoints.append(stage)
        if stage == "after-input-capture":
            assert path == output_root
            assert not output_root.exists()
        elif stage == "after-output-write":
            assert path == output_root
            assert output_root.is_dir()

    def flush(path: Path) -> None:
        flushes.append(path)
        real_flush(path)

    def validate(bundle: object) -> object:
        observed["validated_bundle"] = bundle
        transaction = observed["transaction"]
        assert transaction.creation_session.closed
        return _unchecked_replace(
            bundle,
            root_identity=_unchecked_replace(bundle.root_identity),
            preflight=_unchecked_replace(bundle.preflight),
            entries=tuple(
                _unchecked_replace(
                    entry,
                    identity=_unchecked_replace(entry.identity),
                )
                for entry in bundle.entries
            ),
        )

    monkeypatch.setattr(
        module,
        "_launch_freeze_checkpoint",
        checkpoint,
        raising=False,
    )
    monkeypatch.setattr(module, "_validator_flush_directory", flush)
    monkeypatch.setattr(module, "validate_frozen_launch_preflight", validate)

    detached = module.freeze_launch_preflight(**api_inputs)

    supplied = observed["validated_bundle"]
    assert detached == supplied
    assert detached is not supplied
    assert detached.root == str(output_root)
    assert detached.root_identity is not supplied.root_identity
    assert tuple(entry.relative_path for entry in detached.entries) == (
        "contracts",
        "contracts/exact-config.toml",
    )
    assert checkpoints == ["after-input-capture", "after-output-write"]
    assert flushes == [
        output_root / "contracts",
        output_root,
        output_root.parent,
    ]
    transaction = observed["transaction"]
    assert transaction.publication_fence_reached is True
    assert transaction.creation_session.closed
    assert observed["producer_calls"] == 1


