def _install_launch_recapture_preflight_fakes(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    *,
    launch_port: object = 43123,
    transcript_ports: tuple[int, int, int, int] = (
        43123,
        43123,
        43123,
        43123,
    ),
    second_pass_drift: Literal[
        "git",
        "node",
        "codex",
        "guarded_python",
        "shell",
        "descriptor",
    ]
    | None = None,
    final_failure: BaseException | None = None,
) -> tuple[
    object,
    object,
    Path,
    tuple[object, ...],
    list[str],
    dict[str, object],
]:
    module = _preflight()
    supplied = _launch_preflight(tmp_path / "synthetic-preflight")
    bundle_root = tmp_path / "launch-bundle"
    bundle_root.mkdir()
    original_bundle_layout = module._launch_bundle_layout
    synthetic_layout = module._launch_bundle_layout(bundle_root)
    evaluation_root = Path(supplied.evaluation_records[0].path).parent
    synthetic_layout["frozen_meta_root"] = Path(supplied.frozen_meta_root)
    synthetic_layout["evaluation_root"] = evaluation_root
    synthetic_layout["evaluation_manifest"] = evaluation_root / "manifest.json"
    monkeypatch.setattr(
        module,
        "_launch_bundle_layout",
        lambda requested_root: (
            dict(synthetic_layout)
            if requested_root == bundle_root
            else original_bundle_layout(requested_root)
        ),
    )
    server = _loopback_server_module()
    transcripts = tuple(
        server.decode_loopback_transcript(
            _offline_loopback_transcript_bytes(
                server,
                scenario,
                tmp_path / f"case-{ordinal}",
                port=port,
                seed=ordinal * 16,
            )
        )
        for ordinal, (scenario, port) in enumerate(
            zip(
                ("shell", "shell", "file_add", "file_update"),
                transcript_ports,
                strict=True,
            ),
            start=1,
        )
    )
    calls: list[str] = []
    observed: dict[str, object] = {}
    native_rounds = {"git": 0, "node": 0}
    executable_round = 0
    descriptor_rounds: list[tuple[object, ...]] = []
    closure_values: list[object] = []

    def recapture_native(value: object) -> object:
        role = value.role
        native_rounds[role] += 1
        calls.append(f"native-{role}-{native_rounds[role]}")
        updates = (
            {"executable_sha256": "0" * 64}
            if native_rounds[role] == 2 and second_pass_drift == role
            else {}
        )
        return _unchecked_replace(value, **updates)

    def recapture_executables(
        value: object,
        root: Path,
    ) -> tuple[object, object, object, tuple[object, ...]]:
        nonlocal executable_round
        executable_round += 1
        calls.append(f"executables-{executable_round}")
        closure_values.append(value)
        assert root == bundle_root
        if executable_round == 2 and final_failure is not None:
            raise final_failure
        descriptors = _synthetic_launch_executable_descriptors(module, value)
        codex = _unchecked_replace(value.codex)
        guarded_python = _unchecked_replace(value.guarded_python)
        shell = replace(value.shell)
        if executable_round == 2:
            if second_pass_drift == "codex":
                codex = _unchecked_replace(codex, executable_sha256="0" * 64)
            elif second_pass_drift == "guarded_python":
                guarded_python = _unchecked_replace(
                    guarded_python,
                    python_sha256="0" * 64,
                )
            elif second_pass_drift == "shell":
                shell = _unchecked_replace(shell, sha256="0" * 64)
            elif second_pass_drift == "descriptor":
                descriptors = (
                    _unchecked_replace(descriptors[0], sha256="0" * 64),
                    *descriptors[1:],
                )
        descriptor_rounds.append(descriptors)
        return (
            codex,
            guarded_python,
            shell,
            descriptors,
        )

    def recapture_frozen_meta(value: object, root: Path) -> None:
        calls.append("frozen-meta")
        assert value == supplied
        assert root == bundle_root

    def recapture_server_contracts(value: object, root: Path) -> None:
        calls.append("server-contracts")
        assert value == supplied
        assert root == bundle_root

    def recapture_transcripts(value: object, root: Path) -> tuple[object, ...]:
        calls.append("transcripts")
        assert value == supplied
        assert root == bundle_root
        return transcripts

    def recapture_durable(value: object, root: Path) -> object:
        calls.append("durable")
        assert value == supplied
        assert root == bundle_root
        detached = module._launch_detach_durable_authority(
            value._launch_durable_authority
        )
        observed["durable"] = detached
        return detached

    def recapture_shell(
        value: object,
        root: Path,
        selected: tuple[object, object],
    ) -> tuple[object, object]:
        calls.append("shell-captures")
        assert value == supplied
        assert root == bundle_root
        observed["shell_transcripts"] = selected
        return object(), object()

    def recapture_file_change(
        value: object,
        root: Path,
        add_transcript: object,
        update_transcript: object,
    ) -> object:
        calls.append("file-change")
        assert value == supplied.file_change
        assert root == bundle_root
        observed["file_transcripts"] = (
            add_transcript,
            update_transcript,
        )
        return _unchecked_replace(value)

    def recapture_evaluations(
        value: object,
        evaluation_root: Path,
        manifest_path: Path,
    ) -> tuple[object, ...]:
        calls.append("evaluations")
        assert value == supplied
        observed["evaluation_paths"] = (evaluation_root, manifest_path)
        return tuple(_unchecked_replace(record) for record in value.evaluation_records)

    def recapture_launch_contracts(
        value: object,
        root: Path,
        descriptors: tuple[object, ...],
    ) -> object:
        calls.append("launch-contracts")
        assert root == bundle_root
        observed["launch_value"] = value
        observed["launch_descriptors"] = descriptors
        return launch_port

    monkeypatch.setattr(module, "_launch_recapture_native_leaf", recapture_native)
    monkeypatch.setattr(
        module,
        "_launch_recapture_executable_closure",
        recapture_executables,
    )
    monkeypatch.setattr(
        module,
        "_launch_recapture_frozen_meta",
        recapture_frozen_meta,
    )
    monkeypatch.setattr(
        module,
        "_launch_recapture_server_contracts",
        recapture_server_contracts,
    )
    monkeypatch.setattr(
        module,
        "_launch_recapture_loopback_transcripts",
        recapture_transcripts,
    )
    monkeypatch.setattr(
        module,
        "_launch_recapture_durable_authority",
        recapture_durable,
    )
    monkeypatch.setattr(
        module,
        "_launch_recapture_shell_client_captures",
        recapture_shell,
    )
    monkeypatch.setattr(
        module,
        "_launch_recapture_file_change_preflight",
        recapture_file_change,
    )
    monkeypatch.setattr(
        module,
        "_launch_recapture_evaluation_records",
        recapture_evaluations,
    )
    monkeypatch.setattr(
        module,
        "_launch_recapture_launch_contracts",
        recapture_launch_contracts,
    )
    observed["descriptor_rounds"] = descriptor_rounds
    observed["closure_values"] = closure_values

    def forbidden_runtime_call(*_args: object, **_kwargs: object) -> object:
        pytest.fail("launch recapture attempted a process or socket operation")

    monkeypatch.setattr(subprocess, "Popen", forbidden_runtime_call)
    monkeypatch.setattr(subprocess, "run", forbidden_runtime_call)
    monkeypatch.setattr(socket, "socket", forbidden_runtime_call)
    return module, supplied, bundle_root, transcripts, calls, observed


def test_launch_recapture_preflight_orders_dependencies_and_detaches(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    (
        module,
        supplied,
        bundle_root,
        transcripts,
        calls,
        observed,
    ) = _install_launch_recapture_preflight_fakes(tmp_path, monkeypatch)

    detached, descriptors = module._launch_recapture_preflight(
        supplied,
        bundle_root,
    )

    assert detached == supplied
    assert detached is not supplied
    assert detached.codex is not supplied.codex
    assert all(
        actual is not expected
        for actual, expected in zip(
            detached.native_leaves,
            supplied.native_leaves,
            strict=True,
        )
    )
    assert detached.guarded_python is not supplied.guarded_python
    assert detached.shell is not supplied.shell
    assert detached.file_change is not supplied.file_change
    assert detached._launch_durable_authority == supplied._launch_durable_authority
    assert detached._launch_durable_authority is not supplied._launch_durable_authority
    assert detached._launch_durable_authority is not observed["durable"]
    assert detached._launch_durable_authority.prelaunch is not (
        supplied._launch_durable_authority.prelaunch
    )
    assert detached.evaluation_records is not supplied.evaluation_records
    assert all(
        actual is not expected
        for actual, expected in zip(
            detached.evaluation_records,
            supplied.evaluation_records,
            strict=True,
        )
    )
    assert observed["shell_transcripts"] == transcripts[:2]
    assert observed["file_transcripts"] == transcripts[2:]
    layout = module._launch_bundle_layout(bundle_root)
    assert observed["evaluation_paths"] == (
        layout["evaluation_root"],
        layout["evaluation_manifest"],
    )
    assert observed["launch_value"] == detached
    assert observed["launch_value"] is not detached
    assert observed["launch_value"]._launch_durable_authority is observed["durable"]
    descriptor_rounds = observed["descriptor_rounds"]
    closure_values = observed["closure_values"]
    assert closure_values[0] is supplied
    assert closure_values[1] is observed["launch_value"]
    assert observed["launch_descriptors"] is descriptor_rounds[0]
    assert descriptors == descriptor_rounds[1]
    assert descriptors is descriptor_rounds[1]
    assert calls == [
        "native-git-1",
        "native-node-1",
        "executables-1",
        "frozen-meta",
        "server-contracts",
        "transcripts",
        "durable",
        "shell-captures",
        "file-change",
        "evaluations",
        "launch-contracts",
        "native-git-2",
        "native-node-2",
        "executables-2",
    ]


