def test_validated_frozen_launch_bundle_issues_noncopyable_launch_authority(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    synthetic_launch_authority_adapter: object,
) -> None:
    module = _preflight()
    case_root, prompt, schema, synthetic_preflight = _launch_inputs(
        tmp_path / "synthetic-preflight"
    )
    synthetic_authority = synthetic_preflight._validated_launch_authority
    detached_preflight = _unchecked_replace(synthetic_preflight)
    bundle_root = tmp_path / "launch-bundle"
    bundle = _filesystem_launch_bundle(bundle_root, synthetic_preflight)

    validation_events: list[tuple[str, object, object]] = []

    def accept_synthetic_membership(
        preflight: object,
        root: Path,
        entries: tuple[object, ...],
    ) -> None:
        validation_events.append(("membership", preflight, (root, entries)))

    def recapture_synthetic_preflight(
        value: object,
        root: Path,
    ) -> tuple[object, tuple[object, ...]]:
        validation_events.append(("recapture", value, root))
        return (
            detached_preflight,
            synthetic_authority.executable_descriptors,
        )

    monkeypatch.setattr(
        module,
        "_launch_validate_bundle_membership",
        accept_synthetic_membership,
    )
    monkeypatch.setattr(
        module,
        "_launch_recapture_preflight",
        recapture_synthetic_preflight,
        raising=False,
    )
    monkeypatch.setattr(
        module,
        "_lookup_validated_launch_authority",
        synthetic_launch_authority_adapter,
    )

    validated = module.validate_frozen_launch_preflight(bundle)

    assert tuple(event[0] for event in validation_events) == (
        "membership",
        "recapture",
        "membership",
    )
    first_membership = validation_events[0]
    recapture = validation_events[1]
    final_membership = validation_events[2]
    assert first_membership[1] is synthetic_preflight
    assert recapture[1] is synthetic_preflight
    assert final_membership[1] is detached_preflight
    first_root, first_entries = first_membership[2]
    final_root, final_entries = final_membership[2]
    assert first_root == bundle_root
    assert final_root == bundle_root
    assert first_entries == bundle.entries
    assert final_entries == bundle.entries
    assert first_entries is not final_entries
    assert validated == bundle
    assert validated is not bundle
    assert validated.preflight is detached_preflight
    assert validated.preflight is not synthetic_preflight
    spec = module.build_client_launch_spec(
        mode="loopback_probe",
        preflight=validated.preflight,
        case_root=case_root,
        evaluation=_client_evaluation(mode="loopback_probe"),
        output_schema=schema,
        prompt=prompt,
        loopback_port=43123,
    )
    assert spec.argv[0] == validated.preflight.codex.executable_path
    for unregistered in (
        synthetic_preflight,
        _unchecked_replace(validated.preflight),
    ):
        with pytest.raises(
            RuntimeError,
            match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$",
        ):
            module.build_client_launch_spec(
                mode="loopback_probe",
                preflight=unregistered,
                case_root=case_root,
                evaluation=_client_evaluation(mode="loopback_probe"),
                output_schema=schema,
                prompt=prompt,
                loopback_port=43123,
            )

    (bundle_root / "bundle-marker.txt").write_bytes(b"changed after freeze\n")
    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module.validate_frozen_launch_preflight(bundle)
    assert len(validation_events) == 3


