def _registered_guarded_runtime_image_preflight(
    module: object,
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    production_lookup: object,
    *,
    bootstrap_content: bytes = b"bootstrap\n",
) -> tuple[object, object]:
    production_validator, fixture_validator = (
        _guarded_runtime_image_fixture_output_validator(module, tmp_path)
    )
    monkeypatch.setattr(module, "_validator_absolute_path", fixture_validator)
    try:
        synthetic_preflight = _launch_preflight(
            tmp_path / "synthetic-preflight",
            bootstrap_content=bootstrap_content,
        )
        synthetic_authority = synthetic_preflight._validated_launch_authority
        detached_preflight = _unchecked_replace(synthetic_preflight)
        bundle = _filesystem_launch_bundle(
            tmp_path / "launch-bundle",
            synthetic_preflight,
        )

        monkeypatch.setattr(
            module,
            "_launch_validate_bundle_membership",
            lambda _preflight, _root, _entries: None,
        )
        monkeypatch.setattr(
            module,
            "_launch_recapture_preflight",
            lambda _value, _root: (
                detached_preflight,
                synthetic_authority.executable_descriptors,
            ),
            raising=False,
        )
        validated = module.validate_frozen_launch_preflight(bundle)
    finally:
        monkeypatch.setattr(
            module,
            "_validator_absolute_path",
            production_validator,
        )
    monkeypatch.setattr(module, "_lookup_validated_launch_authority", production_lookup)
    authority = production_lookup(validated.preflight)
    return validated.preflight, authority


def _guarded_runtime_image_fixture_output_validator(
    module: object,
    fixture_root: Path,
) -> tuple[object, object]:
    production_validator = module._validator_absolute_path
    canonical_fixture_root = production_validator(fixture_root, output=False)
    fixture_root_text = ntpath.normpath(str(canonical_fixture_root))

    def validate(value: object, *, output: bool = False) -> Path:
        if not output:
            return production_validator(value, output=False)
        canonical = production_validator(value, output=False)
        normalized = str(canonical)
        try:
            for component in module.PureWindowsPath(normalized).parts[1:]:
                module._validator_win32_component_key(component)
            common = ntpath.commonpath((fixture_root_text, normalized))
        except (RuntimeError, UnicodeError, ValueError) as exc:
            module._validator_reject(exc)
        if ntpath.normcase(common) == ntpath.normcase(fixture_root_text):
            return canonical
        return production_validator(value, output=True)

    return production_validator, validate


def test_guarded_runtime_image_fixture_output_validator_is_exactly_scoped_and_restored(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    synthetic_launch_authority_adapter: object,
) -> None:
    module = _preflight()
    production_validator, fixture_validator = (
        _guarded_runtime_image_fixture_output_validator(module, tmp_path)
    )
    accepted = tmp_path / "accepted" / "bundle"
    outside = (
        Path(module.__file__).parent
        / ".guarded-runtime-image-outside-fixture"
        / "bundle"
    )

    assert fixture_validator(accepted, output=True) == accepted
    with pytest.raises(RuntimeError, match=r"^VALIDATOR_BUNDLE_INVALID$"):
        fixture_validator(outside, output=True)
    _registered_guarded_runtime_image_preflight(
        module,
        tmp_path,
        monkeypatch,
        synthetic_launch_authority_adapter,
    )
    assert module._validator_absolute_path is production_validator


def _guarded_runtime_image_projection_payload(
    module: object,
    projection: object,
) -> dict[str, object]:
    return {
        "authority_state": projection.authority_state,
        "bootstrap": {
            "byte_size": projection.bootstrap_byte_size,
            "identity": module._identity_record(projection.bootstrap_identity),
            "path": projection.bootstrap_path,
            "sha256": projection.bootstrap_sha256,
        },
        "preflight_binding_sha256": projection.preflight_binding_sha256,
        "python_image": {
            "identity": module._identity_record(projection.python_identity),
            "path": projection.python_path,
            "sha256": projection.python_sha256,
            "size": projection.python_size,
        },
        "runtime_canonical_sha256": projection.runtime_canonical_sha256,
        "version": projection.version,
    }


def test_guarded_runtime_image_producer_projection_binds_registered_preflight_and_detaches_canonical_evidence(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    synthetic_launch_authority_adapter: object,
) -> None:
    module = _preflight()
    preflight, authority = _registered_guarded_runtime_image_preflight(
        module,
        tmp_path,
        monkeypatch,
        synthetic_launch_authority_adapter,
    )
    runtime = preflight.guarded_python

    first = module._launch_project_guarded_runtime_image_producer(preflight)
    second = module._launch_project_guarded_runtime_image_producer(preflight)
    expected_runtime_bytes = module.preparation.canonical_bytes(
        module._guarded_runtime_payload(runtime)
    )
    expected_projection_bytes = module._canonical_json_bytes(
        _guarded_runtime_image_projection_payload(module, first)
    )

    assert first == second
    assert first is not second
    assert first.version == "complete-suite-guarded-runtime-image-producer-projection-v1"
    assert (
        first.authority_state
        == "producer-local-evidence-only-no-parent-guard-or-broker-consumption-authority"
    )
    assert first.preflight_binding_sha256 == authority.preflight_binding_sha256
    assert first.preflight_binding_sha256 != authority.prelaunch_binding_sha256
    assert first.runtime_canonical_bytes == expected_runtime_bytes
    assert first.runtime_canonical_bytes is not second.runtime_canonical_bytes
    assert first.runtime_canonical_sha256 == runtime.canonical_sha256 == sha256(
        expected_runtime_bytes
    ).hexdigest()
    assert (first.python_path, first.python_size, first.python_sha256) == (
        runtime.python_path,
        runtime.python_size,
        runtime.python_sha256,
    )
    assert (
        first.bootstrap_path,
        first.bootstrap_byte_size,
        first.bootstrap_sha256,
    ) == (runtime.bootstrap.path, runtime.bootstrap.utf8_bytes, runtime.bootstrap.sha256)
    assert first.python_identity == runtime.python_identity
    assert first.python_identity is not runtime.python_identity
    assert first.python_identity is not second.python_identity
    assert first.bootstrap_identity == runtime.bootstrap.identity
    assert first.bootstrap_identity is not runtime.bootstrap.identity
    assert first.bootstrap_identity is not second.bootstrap_identity
    assert first.canonical_bytes == expected_projection_bytes
    assert first.canonical_bytes is not second.canonical_bytes
    assert first.canonical_sha256 == sha256(expected_projection_bytes).hexdigest()


@pytest.mark.parametrize("case", ("copy", "wrong-type", "subclass", "mutated"))
def test_guarded_runtime_image_producer_projection_rejects_unregistered_or_mutated_inputs_without_hostile_dispatch(
    case: str,
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    synthetic_launch_authority_adapter: object,
) -> None:
    module = _preflight()
    preflight, _authority = _registered_guarded_runtime_image_preflight(
        module,
        tmp_path,
        monkeypatch,
        synthetic_launch_authority_adapter,
    )
    hostile_calls: list[str] = []

    class Hostile:
        def __getattribute__(self, name: str) -> object:
            if name not in {"__class__"}:
                hostile_calls.append("dispatch")
            raise AssertionError(f"hostile attribute dispatched: {name}")

    class LaunchPreflightSubclass(module.LaunchPreflight):
        pass

    if case == "copy":
        supplied = _unchecked_replace(preflight)
        object.__setattr__(supplied, "_validated_launch_authority", _authority)
    elif case == "wrong-type":
        supplied = Hostile()
    elif case == "subclass":
        supplied = object.__new__(LaunchPreflightSubclass)
    else:
        assert case == "mutated"
        supplied = preflight
        object.__setattr__(supplied, "decoder_sha256", "0" * 64)

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_project_guarded_runtime_image_producer(supplied)
    assert hostile_calls == []


