    runtime = preflight.guarded_python
    producer = module._launch_project_guarded_runtime_image_producer
    cells = dict(zip(producer.__code__.co_freevars, producer.__closure__, strict=True))
    worker = cells["project_worker"].cell_contents
    source_lines = Path(module.__file__).read_text(encoding="utf-8").splitlines()
    worker_lines = tuple(
        dict.fromkeys(line for _start, _end, line in worker.__code__.co_lines() if line is not None)
    )
    if mutation == "python-identity-field":
        mutate_text = "initial_python_identity.device,"
        restore_text = "final_authority = trusted_lookup(preflight)"
    elif mutation == "python-identity-object":
        mutate_text = "and runtime.python_identity is initial_python_identity"
        restore_text = "final_authority = trusted_lookup(preflight)"
    elif mutation == "bootstrap-identity-object":
        mutate_text = "and initial_bootstrap.identity is initial_bootstrap_identity"
        restore_text = "final_authority = trusted_lookup(preflight)"
    else:
        assert mutation == "runtime-payload"
        mutate_text = "runtime_bytes_value = trusted_runtime_canonical_bytes("
        restore_text = "snapshot_authority_binding = authority.preflight_binding_sha256"
    mutate_line = next(line for line in worker_lines if source_lines[line - 1].strip() == mutate_text)
    restore_line = next(line for line in worker_lines if source_lines[line - 1].strip().startswith(restore_text))
    original_python_identity = runtime.python_identity
    original_python_device = original_python_identity.device
    original_bootstrap_identity = runtime.bootstrap.identity
    original_roles = runtime.base_sys_path_roles
    original_runtime_sha = runtime.canonical_sha256

    def trace(frame: object, event: str, _argument: object) -> object:
        if event == "line" and frame.f_code is worker.__code__:
            if frame.f_lineno == mutate_line:
                if mutation == "python-identity-field":
                    object.__setattr__(runtime.python_identity, "device", runtime.python_identity.device + 1)
                elif mutation == "python-identity-object":
                    object.__setattr__(runtime, "python_identity", _unchecked_replace(runtime.python_identity))
                elif mutation == "bootstrap-identity-object":
                    object.__setattr__(runtime.bootstrap, "identity", _unchecked_replace(runtime.bootstrap.identity))
                else:
                    object.__setattr__(runtime, "base_sys_path_roles", runtime.base_sys_path_roles + ("transient",))
                    changed = module.preparation.canonical_bytes(module._guarded_runtime_payload(runtime))
                    object.__setattr__(runtime, "canonical_sha256", sha256(changed).hexdigest())
            elif frame.f_lineno == restore_line:
                object.__setattr__(runtime, "python_identity", original_python_identity)
                object.__setattr__(runtime.bootstrap, "identity", original_bootstrap_identity)
                object.__setattr__(original_python_identity, "device", original_python_device)
                object.__setattr__(runtime, "base_sys_path_roles", original_roles)
                object.__setattr__(runtime, "canonical_sha256", original_runtime_sha)
        return trace

    previous_trace = sys.gettrace()
    sys.settrace(trace)
    try:
        with pytest.raises(RuntimeError, match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$"):
            producer(preflight)
    finally:
        sys.settrace(previous_trace)
        object.__setattr__(runtime, "python_identity", original_python_identity)
        object.__setattr__(runtime.bootstrap, "identity", original_bootstrap_identity)
        object.__setattr__(original_python_identity, "device", original_python_device)
        object.__setattr__(runtime, "base_sys_path_roles", original_roles)
        object.__setattr__(runtime, "canonical_sha256", original_runtime_sha)


