def test_guarded_runtime_image_parent_handoff_reliability_rolls_back_final_ready_publication_baseexception(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    synthetic_launch_authority_adapter: object,
) -> None:
    module = _preflight()
    preflight, _preflight_authority = _registered_guarded_runtime_image_preflight(
        module,
        tmp_path,
        monkeypatch,
        synthetic_launch_authority_adapter,
    )
    projection = module._launch_project_guarded_runtime_image_producer(preflight)
    mint = module._launch_mint_guarded_runtime_image_parent_handoff
    authenticate = module._launch_authenticate_guarded_runtime_image_parent_handoff
    warmup = mint(preflight, projection)
    assert authenticate(warmup) is warmup
    worker = _guarded_runtime_image_parent_handoff_export_worker(
        mint,
        "mint_worker",
    )
    cells = dict(
        zip(worker.__code__.co_freevars, worker.__closure__ or (), strict=True)
    )
    setter_cell = cells["trusted_object_setattr"]
    journal = cells["trusted_journal"].cell_contents
    original_setter = setter_cell.cell_contents
    original_journal = tuple(journal)
    retained: list[object] = []

    class PublicationFailure(BaseException):
        pass

    failure = PublicationFailure("synthetic final publication failure")

    def fail_final_ready(instance: object, name: str, value: object) -> None:
        if (
            type(instance) is module._GuardedRuntimeImageParentHandoffAuthority
            and name == "_phase"
            and value == "parent-handoff-ready"
        ):
            retained.append(instance)
            raise failure
        original_setter(instance, name, value)

    def trace(frame: object, event: str, _argument: object) -> object:
        if event == "call" and frame.f_code is worker.__code__:
            setter_cell.cell_contents = fail_final_ready
        return trace

    previous_trace = sys.gettrace()
    sys.settrace(trace)
    try:
        with pytest.raises(PublicationFailure) as error:
            mint(preflight, projection)
    finally:
        sys.settrace(previous_trace)
        setter_cell.cell_contents = original_setter
    assert error.value is failure
    assert len(retained) == 1
    failed_authority = retained[0]
    assert tuple(journal) == original_journal
    assert all(
        entry[0]() is not failed_authority
        for entry in journal
    )
    for name in module._GuardedRuntimeImageParentHandoffAuthority.__slots__:
        if name != "__weakref__":
            with pytest.raises(AttributeError):
                object.__getattribute__(failed_authority, name)

    subsequent = mint(preflight, projection)
    assert authenticate(subsequent) is subsequent


def _registered_guarded_runtime_launch_adapter_parent(
    module: object,
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    production_lookup: object,
    *,
    bootstrap_content: bytes = b"bootstrap\n",
) -> tuple[object, object]:
    preflight, _preflight_authority = _registered_guarded_runtime_image_preflight(
        module,
        tmp_path,
        monkeypatch,
        production_lookup,
        bootstrap_content=bootstrap_content,
    )
    image_projection = module._launch_project_guarded_runtime_image_producer(
        preflight
    )
    parent = module._launch_mint_guarded_runtime_image_parent_handoff(
        preflight,
        image_projection,
    )
    return preflight, parent


def _guarded_runtime_launch_adapter_component_bindings(
    module: object,
) -> tuple[tuple[str, str, int, str], ...]:
    prefix_size = sum(
        descriptor[4]
        for descriptor in module._BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_COMPONENT_DESCRIPTORS
    )
    prefix_fact = (
        module._BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_SOURCE_FRAGMENT_VERSION,
        prefix_size,
        module._BROKER_NATIVE_CONSTRUCTOR_RUNTIME_PREFIX_SOURCE_SHA256,
    )
    precreation_source = (
        module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_BYTES
    )
    precreation_fact = (
        module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_SOURCE_FRAGMENT_VERSION,
        len(precreation_source),
        sha256(precreation_source).hexdigest(),
    )
    assert tuple(
        token
        for token in module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_FORBIDDEN_SOURCE_TOKENS
        if token in precreation_source
    ) == ()
    descriptor_source = (
        module._BROKER_NATIVE_GUARDED_TARGET_DESCRIPTOR_PROJECTION_SOURCE_BYTES
    )
    descriptor_fact = (
        module._BROKER_NATIVE_GUARDED_TARGET_DESCRIPTOR_PROJECTION_SOURCE_FRAGMENT_VERSION,
        len(descriptor_source),
        sha256(descriptor_source).hexdigest(),
    )
    assert prefix_fact == (
        module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_PREFIX_SOURCE_VERSION,
        module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_PREFIX_SOURCE_SIZE,
        module._BROKER_NATIVE_GUARDED_TARGET_PRECREATION_PREFIX_SOURCE_SHA256,
    )
    assert prefix_fact == (
        module._BROKER_NATIVE_GUARDED_TARGET_DESCRIPTOR_PROJECTION_PREFIX_SOURCE_VERSION,
        module._BROKER_NATIVE_GUARDED_TARGET_DESCRIPTOR_PROJECTION_PREFIX_SOURCE_SIZE,
        module._BROKER_NATIVE_GUARDED_TARGET_DESCRIPTOR_PROJECTION_PREFIX_SOURCE_SHA256,
    )
    expected_precreation_fact = (
        module._BROKER_NATIVE_GUARDED_TARGET_DESCRIPTOR_PROJECTION_PRECREATION_SOURCE_VERSION,
        module._BROKER_NATIVE_GUARDED_TARGET_DESCRIPTOR_PROJECTION_PRECREATION_SOURCE_SIZE,
        module._BROKER_NATIVE_GUARDED_TARGET_DESCRIPTOR_PROJECTION_PRECREATION_SOURCE_SHA256,
    )
    assert precreation_fact == expected_precreation_fact
    assert descriptor_fact[1:] == (
        module._BROKER_NATIVE_GUARDED_TARGET_DESCRIPTOR_PROJECTION_SOURCE_SIZE,
        module._BROKER_NATIVE_GUARDED_TARGET_DESCRIPTOR_PROJECTION_SOURCE_SHA256,
    )
    return (
        (
            "constructor-runtime-prefix",
            *prefix_fact,
        ),
        (
            "guarded-target-precreation",
            *precreation_fact,
        ),
        (
            "guarded-target-descriptor-projection",
            *descriptor_fact,
        ),
    )


def _guarded_runtime_launch_adapter_payload(
    projection: object,
) -> dict[str, object]:
    return {
        "adapter_implementation_id": projection.adapter_implementation_id,
        "adapter_platform": projection.adapter_platform,
        "authority_state": projection.authority_state,
        "component_bindings": [
            {
                "role": role,
                "sha256": component_sha256,
                "size": size,
                "version": component_version,
            }
            for role, component_version, size, component_sha256 in projection.component_bindings
        ],
        "constructor_class": projection.constructor_class,
        "parent_handoff_manifest_sha256": (
            projection.parent_handoff_manifest_sha256
        ),
        "parent_handoff_nonce": projection.parent_handoff_nonce,
        "runtime_canonical_sha256": projection.runtime_canonical_sha256,
        "version": projection.version,
    }


def test_guarded_runtime_launch_adapter_projection_has_exact_generic_evidence_only_surface() -> None:
    module = _preflight()
    projection_type = module._GuardedRuntimeLaunchAdapterProjection
    producer = module._launch_project_broker_native_guarded_runtime_adapter

    assert projection_type.__dataclass_params__.frozen is True
    assert projection_type.__dataclass_params__.repr is False
    assert "__slots__" in projection_type.__dict__
    assert "__dict__" not in projection_type.__dict__
    assert tuple(field.name for field in fields(projection_type)) == (
        "version",
        "authority_state",
        "parent_handoff_nonce",
        "parent_handoff_manifest_sha256",
        "runtime_canonical_sha256",
        "adapter_platform",
        "adapter_implementation_id",
        "constructor_class",
        "component_bindings",
        "canonical_bytes",
        "canonical_sha256",
    )
    assert get_type_hints(projection_type) == {
        "version": Literal[
            "complete-suite-guarded-runtime-launch-adapter-projection-v1"
        ],
        "authority_state": Literal[
            "adapter-source-evidence-only-parent-handoff-remains-ready-no-successor-or-launch-authority"
        ],
        "parent_handoff_nonce": str,
        "parent_handoff_manifest_sha256": str,
        "runtime_canonical_sha256": str,
        "adapter_platform": str,
        "adapter_implementation_id": str,
        "constructor_class": str,
        "component_bindings": tuple[tuple[str, str, int, str], ...],
        "canonical_bytes": bytes,
        "canonical_sha256": str,
    }
    assert tuple(inspect.signature(producer).parameters) == ("authority",)
    assert get_type_hints(producer) == {
        "authority": module._GuardedRuntimeImageParentHandoffAuthority,
        "return": projection_type,
    }
    assert {
        "authority",
        "parent_authority",
        "manifest",
        "runtime",
        "preflight",
        "path",
        "argv",
        "environment",
        "vector",
        "handle",
        "channel",
        "job",
        "process",
        "credential",
        "successor",
        "consumer",
        "receipt",
    }.isdisjoint(projection_type.__dataclass_fields__)
    assert not hasattr(module, "_launch_consume_guarded_runtime_launch_adapter")
    assert not hasattr(module, "_GuardedRuntimeLaunchAdapterAuthority")


def test_broker_native_guarded_runtime_adapter_binds_parent_runtime_and_exact_detached_component_facts(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    synthetic_launch_authority_adapter: object,
) -> None:
    module = _preflight()
    preflight, parent = _registered_guarded_runtime_launch_adapter_parent(
        module,
        tmp_path,
        monkeypatch,
        synthetic_launch_authority_adapter,
    )
    expected_bindings = _guarded_runtime_launch_adapter_component_bindings(module)
    parent_manifest = parent.manifest
    forbidden_calls: list[str] = []

    def forbidden_image_producer(*_args: object, **_kwargs: object) -> object:
        forbidden_calls.append("runtime-image-producer")
        raise AssertionError("adapter producer called runtime-image producer")

    monkeypatch.setattr(
        module,
        "_launch_project_guarded_runtime_image_producer",
        forbidden_image_producer,
    )
    first = module._launch_project_broker_native_guarded_runtime_adapter(parent)
    second = module._launch_project_broker_native_guarded_runtime_adapter(parent)
    expected_canonical = module._canonical_json_bytes(
        _guarded_runtime_launch_adapter_payload(first)
    )

    assert first == second
    assert first is not second
    assert first.version == (
        "complete-suite-guarded-runtime-launch-adapter-projection-v1"
    )
    assert first.authority_state == (
        "adapter-source-evidence-only-parent-handoff-remains-ready-no-successor-or-launch-authority"
    )
    assert first.parent_handoff_nonce == parent_manifest.parent_handoff_nonce
    assert first.parent_handoff_manifest_sha256 == parent_manifest.canonical_sha256
    assert first.runtime_canonical_sha256 == (
        preflight.guarded_python.canonical_sha256
    )
    assert first.runtime_canonical_sha256 == (
        parent_manifest.runtime_canonical_sha256
    )
    assert first.adapter_platform == "windows"
    assert first.adapter_implementation_id == "broker-native-core-v1"
    assert first.constructor_class == "guarded-target-or-native-leaf"
    assert first.component_bindings == expected_bindings
    assert first.component_bindings is not second.component_bindings
    assert all(
        left is not right
        for left, right in zip(
            first.component_bindings,
            second.component_bindings,
            strict=True,
        )
    )
    assert first.canonical_bytes == expected_canonical
    assert first.canonical_bytes is not second.canonical_bytes
    assert first.canonical_sha256 == sha256(expected_canonical).hexdigest()
    assert parent.phase == "parent-handoff-ready"
    assert module._launch_authenticate_guarded_runtime_image_parent_handoff(
        parent
    ) is parent
    assert forbidden_calls == []


def test_broker_native_guarded_runtime_adapter_rejects_invalid_parent_authority_before_component_or_hostile_dispatch(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    synthetic_launch_authority_adapter: object,
) -> None:
    module = _preflight()
    _preflight_value, genuine = _registered_guarded_runtime_launch_adapter_parent(
        module,
        tmp_path,
        monkeypatch,
        synthetic_launch_authority_adapter,
    )
    producer = module._launch_project_broker_native_guarded_runtime_adapter
    worker_cells = dict(
        zip(producer.__code__.co_freevars, producer.__closure__ or (), strict=True)
    )
    worker = worker_cells["project_worker"].cell_contents
    component_helper = dict(
        zip(worker.__code__.co_freevars, worker.__closure__ or (), strict=True)
    )["component_evidence"].cell_contents
    component_codes = {
        component_helper.__code__,
        module._launch_broker_native_constructor_runtime_prefix_source_fragment.__code__,
        module._launch_broker_native_guarded_target_precreation_source_fragment.__code__,
        module._launch_broker_native_guarded_target_descriptor_projection_source_fragment.__code__,
    }
    component_calls: list[str] = []
    hostile_calls: list[str] = []

    class Hostile:
        def __getattribute__(self, name: str) -> object:
            if name != "__class__":
                hostile_calls.append(f"attribute:{name}")
            raise AssertionError("hostile parent attribute dispatched")

        def __eq__(self, _other: object) -> bool:
            hostile_calls.append("equality")
            raise AssertionError("hostile parent equality dispatched")

    authority_type = module._GuardedRuntimeImageParentHandoffAuthority

    class ParentSubclass(authority_type):
        pass

    copied = object.__new__(authority_type)
    for name in authority_type.__slots__:
        if name != "__weakref__":
            object.__setattr__(
                copied,
                name,
                object.__getattribute__(genuine, name),
            )
    subclass = object.__new__(ParentSubclass)

    def profile(frame: object, event: str, _argument: object) -> None:
        if event == "call" and frame.f_code in component_codes:
            component_calls.append(frame.f_code.co_name)

    previous_profile = sys.getprofile()
    sys.setprofile(profile)
    try:
        for supplied in (Hostile(), subclass, copied):
            with pytest.raises(
                RuntimeError,
                match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
            ):
                producer(supplied)

        original_entry = object.__getattribute__(genuine, "_journal_entry")
        object.__setattr__(genuine, "_journal_entry", tuple(list(original_entry)))
        try:
            with pytest.raises(
                RuntimeError,
                match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
            ):
                producer(genuine)
        finally:
            object.__setattr__(genuine, "_journal_entry", original_entry)
    finally:
        sys.setprofile(previous_profile)
    assert component_calls == []
    assert hostile_calls == []
    assert module._launch_authenticate_guarded_runtime_image_parent_handoff(
        genuine
    ) is genuine


