def test_broker_native_guarded_runtime_adapter_review_rejects_coherent_component_fact_drift_against_independent_pins(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    synthetic_launch_authority_adapter: object,
) -> None:
    module = _preflight()
    _preflight_value, parent = _registered_guarded_runtime_launch_adapter_parent(
        module,
        tmp_path,
        monkeypatch,
        synthetic_launch_authority_adapter,
    )
    producer = module._launch_project_broker_native_guarded_runtime_adapter
    worker = dict(
        zip(producer.__code__.co_freevars, producer.__closure__ or (), strict=True)
    )["project_worker"].cell_contents
    component_helper = dict(
        zip(worker.__code__.co_freevars, worker.__closure__ or (), strict=True)
    )["component_evidence"].cell_contents
    component_cells = dict(
        zip(
            component_helper.__code__.co_freevars,
            component_helper.__closure__ or (),
            strict=True,
        )
    )
    original_values = {
        name: component_cells[name].cell_contents
        for name in (
            "trusted_precreation_source",
            "trusted_precreation_source_anchor",
            "trusted_precreation_size",
            "trusted_precreation_size_anchor",
            "trusted_precreation_sha256",
            "trusted_precreation_sha256_anchor",
            "trusted_descriptor_precreation_binding",
            "trusted_descriptor_precreation_binding_anchor",
        )
    }
    changed_source = original_values["trusted_precreation_source"] + (
        b"# coherent component drift\n"
    )
    changed_size = len(changed_source)
    changed_sha256 = sha256(changed_source).hexdigest()
    changed_binding = (
        component_cells["trusted_precreation_version"].cell_contents,
        changed_size,
        changed_sha256,
    )
    changed_values = {
        "trusted_precreation_source": changed_source,
        "trusted_precreation_source_anchor": changed_source,
        "trusted_precreation_size": changed_size,
        "trusted_precreation_size_anchor": changed_size,
        "trusted_precreation_sha256": changed_sha256,
        "trusted_precreation_sha256_anchor": changed_sha256,
        "trusted_descriptor_precreation_binding": changed_binding,
        "trusted_descriptor_precreation_binding_anchor": changed_binding,
    }
    source_lines = Path(module.__file__).read_text(encoding="utf-8").splitlines()
    initial_component_line = next(
        line
        for _start, _end, line in worker.__code__.co_lines()
        if line is not None
        and source_lines[line - 1].strip()
        == "initial_component_bindings = component_evidence()"
    )
    armed = True

    def trace(frame: object, event: str, _argument: object) -> object:
        nonlocal armed
        if (
            armed
            and event == "line"
            and frame.f_code is worker.__code__
            and frame.f_lineno == initial_component_line
        ):
            armed = False
            for name, value in changed_values.items():
                component_cells[name].cell_contents = value
        return trace

    previous_trace = sys.gettrace()
    sys.settrace(trace)
    try:
        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ):
            producer(parent)
    finally:
        sys.settrace(previous_trace)
        for name, value in original_values.items():
            component_cells[name].cell_contents = value
    assert armed is False
    recovered = producer(parent)
    assert recovered.component_bindings == (
        _guarded_runtime_launch_adapter_component_bindings(module)
    )
    assert parent.phase == "parent-handoff-ready"


