    target_line = next(
        line
        for _start, _end, line in worker.__code__.co_lines()
        if line is not None and source_lines[line - 1].strip() == final_line_text
    )
    runtime = preflight.guarded_python
    if surface == "parent-runtime":
        owner = runtime
        name = "python_path"
        original = runtime.python_path
        changed = original + ".drift"
    else:
        source_cell = component_cells["trusted_precreation_source"]
        owner = source_cell
        name = "cell_contents"
        original = source_cell.cell_contents
        changed = original + b"# drift\n"
    armed = True

    def trace(frame: object, event: str, _argument: object) -> object:
        nonlocal armed
        if (
            armed
            and event == "line"
            and frame.f_code is worker.__code__
            and frame.f_lineno == target_line
        ):
            armed = False
            if surface == "parent-runtime":
                object.__setattr__(owner, name, changed)
            else:
                owner.cell_contents = changed
        return trace

    previous_trace = sys.gettrace()
    sys.settrace(trace)
    try:
        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ):
            producer(parent)
    finally:
        sys.settrace(previous_trace)
        if surface == "parent-runtime":
            object.__setattr__(owner, name, original)
        else:
            owner.cell_contents = original
    assert armed is False
    assert producer(parent).parent_handoff_nonce == (
        parent.manifest.parent_handoff_nonce
    )
    assert parent.phase == "parent-handoff-ready"


