def test_broker_native_guarded_runtime_adapter_is_offline_cross_os_generic_and_side_effect_free(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    synthetic_launch_authority_adapter: object,
) -> None:
    module = _preflight()
    _preflight_value, parent = _registered_guarded_runtime_launch_adapter_parent(
        module,
        tmp_path,
        monkeypatch,
        synthetic_launch_authority_adapter,
    )
    parent_nonce = parent.manifest.parent_handoff_nonce
    calls = _guard_native_leaf_side_effects(monkeypatch)

    def forbidden(*_args: object, **_kwargs: object) -> object:
        calls.append("forbidden")
        raise AssertionError("adapter projection reached a side-effect surface")

    for owner, name in (
        (builtins, "open"),
        (os, "open"),
        (os, "stat"),
        (os, "lstat"),
        (Path, "open"),
        (Path, "read_bytes"),
        (Path, "read_text"),
        (Path, "resolve"),
        (Path, "absolute"),
        (ctypes, "CDLL"),
        (ctypes, "WinDLL"),
    ):
        monkeypatch.setattr(owner, name, forbidden, raising=False)
    for name in (
        "_launch_project_guarded_runtime_image_producer",
        "_launch_create_guarded_target_precreation",
        "_launch_project_guarded_target_descriptors",
        "_launch_broker_native_control_plane",
        "_launch_guarded_runtime_adapter_successor",
    ):
        monkeypatch.setattr(module, name, forbidden, raising=False)
    entropy_source = os.urandom
    entropy_calls: list[object] = []
    previous_profile = sys.getprofile()

    def profile(_frame: object, event: str, argument: object) -> None:
        if event == "c_call" and argument is entropy_source:
            entropy_calls.append(argument)

    sys.setprofile(profile)
    try:
        projection = (
            module._launch_project_broker_native_guarded_runtime_adapter(parent)
        )
    finally:
        sys.setprofile(previous_profile)

    assert projection.adapter_platform == "windows"
    assert type(projection.adapter_platform) is str
    assert type(projection.adapter_implementation_id) is str
    assert type(projection.constructor_class) is str
    assert all(
        type(role) is str
        and type(version) is str
        and type(size) is int
        and type(component_sha256) is str
        for role, version, size, component_sha256 in projection.component_bindings
    )
    assert parent.manifest.parent_handoff_nonce == parent_nonce
    assert parent.phase == "parent-handoff-ready"
    assert entropy_calls == []
    assert calls == []


def _broker_native_guarded_runtime_source_fragments(
    module: object,
    preflight: object,
) -> tuple[object, object, object]:
    bootstrap_source = bytes(bytearray(preflight.guarded_python.bootstrap.content))
    draft = (
        module._launch_extract_broker_native_control_plane_candidate_from_bootstrap_source(
            bootstrap_source
        )
    )
    prefix = module._launch_broker_native_constructor_runtime_prefix_source_fragment(
        draft_fragment=draft
    )
    precreation = (
        module._launch_broker_native_guarded_target_precreation_source_fragment()
    )
    descriptor = (
        module._launch_broker_native_guarded_target_descriptor_projection_source_fragment()
    )
    return prefix, precreation, descriptor


def _registered_broker_native_guarded_runtime_source_parent(
    module: object,
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    production_lookup: object,
) -> tuple[object, object]:
    return _registered_guarded_runtime_launch_adapter_parent(
        module,
        tmp_path,
        monkeypatch,
        production_lookup,
        bootstrap_content=BOOTSTRAP_PATH.read_bytes(),
    )


def _detached_guarded_runtime_launch_adapter(adapter: object) -> object:
    return _unchecked_frozen(
        type(adapter),
        version=adapter.version,
        authority_state=adapter.authority_state,
        parent_handoff_nonce=adapter.parent_handoff_nonce,
        parent_handoff_manifest_sha256=(
            adapter.parent_handoff_manifest_sha256
        ),
        runtime_canonical_sha256=adapter.runtime_canonical_sha256,
        adapter_platform=adapter.adapter_platform,
        adapter_implementation_id=adapter.adapter_implementation_id,
        constructor_class=adapter.constructor_class,
        component_bindings=tuple(
            tuple(item) for item in adapter.component_bindings
        ),
        canonical_bytes=bytes(bytearray(adapter.canonical_bytes)),
        canonical_sha256=adapter.canonical_sha256,
    )


def _broker_native_guarded_runtime_source_payload(
    projection: object,
) -> dict[str, object]:
    return {
        "adapter_canonical_sha256": projection.adapter_canonical_sha256,
        "authority_state": projection.authority_state,
        "constructor_class": projection.constructor_class,
        "constructor_implementation_id": (
            projection.constructor_implementation_id
        ),
        "parent_handoff_manifest_sha256": (
            projection.parent_handoff_manifest_sha256
        ),
        "parent_handoff_nonce": projection.parent_handoff_nonce,
        "source_layout": [
            {
                "role": role,
                "sha256": component_sha256,
                "size": size,
                "version": component_version,
            }
            for role, component_version, size, component_sha256 in projection.source_layout
        ],
        "source_sha256": projection.source_sha256,
        "source_size": projection.source_size,
        "version": projection.version,
    }


