def test_launch_spec_loopback_has_exact_argv_and_closed_environments(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    case_root, prompt, schema, launch_preflight = _launch_inputs(tmp_path)

    def forbidden(*_args: object, **_kwargs: object) -> object:
        raise AssertionError("launch builder attempted a process or network action")

    monkeypatch.setattr(subprocess, "Popen", forbidden)
    monkeypatch.setattr(subprocess, "run", forbidden)
    monkeypatch.setattr(socket, "socket", forbidden)
    before = tuple(case_root.parent.iterdir()) if case_root.parent.exists() else ()
    spec = module.build_client_launch_spec(
        mode="loopback_probe",
        preflight=launch_preflight,
        case_root=case_root,
        evaluation=_client_evaluation(mode="loopback_probe"),
        output_schema=schema,
        prompt=prompt,
        loopback_port=43123,
    )
    after = tuple(case_root.parent.iterdir()) if case_root.parent.exists() else ()

    assert before == after
    assert spec.version == "complete-suite-client-launch-spec-v1"
    assert spec.cwd == str(case_root / "workspace")
    assert spec.argv[:20] == (
        launch_preflight.codex.executable_path,
        "exec", "--ephemeral", "--ignore-user-config", "--ignore-rules",
        "--strict-config", "--skip-git-repo-check", "--approve-for-me",
        "--model", "gpt-5.6-terra", "--color", "never", "--json",
        "--output-schema", schema.path, "--output-last-message",
        str(case_root / "raw" / "final" / "shell-01.md"), "--cd",
        str(case_root / "workspace"), "-c",
    )
    assert spec.argv.count("--approve-for-me") == 1
    assert "--sandbox" not in spec.argv
    assert spec.argv[-1] == "-"
    assert spec.config_overrides[:4] == (
        'model_provider="campaign6_provider"',
        'model_providers.campaign6_provider.name="Campaign 6 loopback renderer probe"',
        'model_providers.campaign6_provider.base_url="http://127.0.0.1:43123/v1"',
        'model_providers.campaign6_provider.wire_api="responses"',
    )
    assert (
        'model_providers.campaign6_provider.http_headers."User-Agent"='
        '"kokoroarc-campaign6-client-preflight-v1"'
    ) in spec.config_overrides
    assert not any("env_key" in item for item in spec.config_overrides)
    expected_argv = list(spec.argv[:19])
    for override in spec.config_overrides:
        expected_argv.extend(("-c", override))
    expected_argv.append("-")
    assert spec.argv == tuple(expected_argv)
    assert spec.config_bytes == (
        "\n".join(spec.config_overrides) + "\n"
    ).encode("utf-8")
    assert spec.config_sha256 == sha256(spec.config_bytes).hexdigest()
    launcher = dict(spec.launcher_environment)
    shell = dict(spec.shell_environment)
    assert tuple(name for name, _value in spec.launcher_environment) == tuple(
        sorted(launcher)
    )
    assert tuple(name for name, _value in spec.shell_environment) == tuple(
        sorted(shell)
    )
    assert set(launcher) == {
        "APPDATA", "CODEX_HOME", "COMSPEC", "HOME", "LOCALAPPDATA",
        "NO_COLOR", "PATH", "PATHEXT", "POWERSHELL_TELEMETRY_OPTOUT",
        "POWERSHELL_UPDATECHECK", "PYTHONDONTWRITEBYTECODE", "PYTHONUTF8",
        "SYSTEMROOT", "TEMP", "TMP", "USERPROFILE", "WINDIR",
    }
    assert set(shell) == {
        "COMSPEC", "KOKOROARC_DATA_DIR", "PATH", "PATHEXT", "PIP_CACHE_DIR",
        "PIP_CONFIG_FILE", "PIP_DISABLE_PIP_VERSION_CHECK", "PIP_NO_INDEX",
        "POWERSHELL_TELEMETRY_OPTOUT", "POWERSHELL_UPDATECHECK",
        "PYTHONDONTWRITEBYTECODE", "PYTHONHASHSEED", "PYTHONNOUSERSITE",
        "PYTHONPATH", "PYTHONSAFEPATH", "PYTHONUTF8", "RIPGREP_CONFIG_PATH",
        "SYSTEMROOT", "TEMP", "TMP", "WINDIR",
    }
    assert launcher["HOME"] == launcher["USERPROFILE"] == str(
        case_root / "launcher" / "profile"
    )
    assert launcher["CODEX_HOME"] == str(case_root / "launcher" / "codex-home")
    assert shell["PYTHONPATH"] == str(case_root / "runtime")
    assert shell["KOKOROARC_DATA_DIR"] == str(case_root / "workspace" / "data")
    assert not set(launcher) & {"OPENAI_API_KEY", "HTTP_PROXY", "PSModulePath"}
    assert not set(shell) & {"OPENAI_API_KEY", "HTTP_PROXY", "PSModulePath"}
    assert prompt.content not in b"\x00".join(
        value.encode("utf-8") for value in spec.argv
    )
    vector = _command_plan()._windows_native_vector(spec.argv[0], spec.argv[1:])
    assert spec.native_vector_contract == vector.contract
    assert spec.native_vector_utf16_units == vector.utf16_units
    assert spec.native_vector_utf16le_sha256 == vector.utf16le_sha256
    assert spec.credential_transport_version == "complete-suite-no-credential-v1"
    assert spec.credential_environment_name is None
    with pytest.raises(FrozenInstanceError):
        spec.cwd = "mutated"


