@pytest.mark.parametrize(
    "mutation",
    (
        "missing-preflight", "missing-port", "real-port", "wrong-purpose",
        "wrong-credential", "wrong-constructor", "noncanonical-envelope",
        "prompt-outside-case", "schema-outside-case", "count-drift",
    ),
)
def test_launch_spec_rejects_mode_envelope_and_input_mutation_before_action(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    mutation: str,
) -> None:
    module = _preflight()
    case_root, prompt, schema, launch_preflight = _launch_inputs(tmp_path)
    mode = "loopback_probe"
    port = 43123
    evaluation = _client_evaluation(mode="loopback_probe")
    if mutation == "missing-preflight":
        launch_preflight = None
    elif mutation == "missing-port":
        port = None
    elif mutation == "real-port":
        mode = "real_campaign_template"
        port = 43123
        evaluation = _client_evaluation(mode="real_campaign_template")
    elif mutation == "wrong-purpose":
        evaluation = _client_evaluation(mode="real_campaign_template")
    elif mutation == "wrong-credential":
        evaluation = _unchecked_replace(evaluation, credential_present=True)
    elif mutation == "wrong-constructor":
        evaluation = _unchecked_replace(
            evaluation,
            client_constructor_implementation_sha256="d" * 64,
        )
    elif mutation == "noncanonical-envelope":
        evaluation = _unchecked_replace(
            evaluation,
            canonical_bytes=evaluation.canonical_bytes + b" ",
        )
    elif mutation == "prompt-outside-case":
        prompt = _capture(tmp_path / "outside-prompt.md", b"probe prompt\n", inode=411)
    elif mutation == "schema-outside-case":
        schema = _capture(
            tmp_path / "outside-schema.json", b'{"type":"object"}\n', inode=412
        )
    elif mutation == "count-drift":
        evaluation = _unchecked_replace(evaluation, expected_shell_calls=0)

    def forbidden(*_args: object, **_kwargs: object) -> object:
        raise AssertionError("rejected launch attempted a side effect")

    monkeypatch.setattr(subprocess, "Popen", forbidden)
    monkeypatch.setattr(subprocess, "run", forbidden)
    monkeypatch.setattr(socket, "socket", forbidden)
    before = tuple(tmp_path.iterdir())
    with pytest.raises(RuntimeError, match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$"):
        module.build_client_launch_spec(
            mode=mode,
            preflight=launch_preflight,
            case_root=case_root,
            evaluation=evaluation,
            output_schema=schema,
            prompt=prompt,
            loopback_port=port,
        )
    assert tuple(tmp_path.iterdir()) == before


