def test_launch_spec_normalization_does_not_hide_port_digits_in_executable_path(
    tmp_path: Path,
) -> None:
    module = _preflight()
    case_root, prompt, schema, launch_preflight = _launch_inputs(tmp_path)
    evaluation = _client_evaluation(mode="loopback_probe")

    def with_codex_path(path: Path, port: int) -> object:
        codex = _recanonical_codex(
            launch_preflight.codex,
            executable_path=str(path),
        )
        identities = (
            ("codex", codex.executable_path, codex.executable_sha256),
            ("pwsh", launch_preflight.shell.path, launch_preflight.shell.sha256),
            (
                "powershell_decoder",
                launch_preflight.decoder_path,
                launch_preflight.decoder_sha256,
            ),
            (
                "python",
                launch_preflight.python_path,
                launch_preflight.python_sha256,
            ),
            ("rg", launch_preflight.rg_path, launch_preflight.rg_sha256),
            (
                "comspec",
                launch_preflight.comspec_path,
                launch_preflight.comspec_sha256,
            ),
        )
        launcher, shell = module._launch_expected_environments(
            case_root=str(case_root),
            executable_identities=identities,
        )
        authority = _unchecked_replace(
            launch_preflight,
            codex=codex,
            launcher_environment=launcher,
            shell_environment=shell,
            environment_sha256=sha256(
                _canonical(
                    {
                        "launcher_environment": [list(item) for item in launcher],
                        "shell_environment": [list(item) for item in shell],
                        "version": (
                            "complete-suite-client-environment-manifest-v1"
                        ),
                    }
                )
            ).hexdigest(),
        )
        return _install_synthetic_validated_launch_authority(
            authority,
            loopback_port=port,
        )

    first_preflight = with_codex_path(
        tmp_path / "codex-43123" / "codex.exe",
        43123,
    )
    second_preflight = with_codex_path(
        tmp_path / "codex-58761" / "codex.exe",
        58761,
    )
    first_authority = first_preflight._validated_launch_authority
    second_authority = second_preflight._validated_launch_authority
    first = module.build_client_launch_spec(
        mode="loopback_probe",
        preflight=first_preflight,
        case_root=case_root,
        evaluation=evaluation,
        output_schema=first_authority.prelaunch_authority.output_schema,
        prompt=first_authority.prelaunch_authority.prompts[0],
        loopback_port=43123,
    )
    second = module.build_client_launch_spec(
        mode="loopback_probe",
        preflight=second_preflight,
        case_root=case_root,
        evaluation=evaluation,
        output_schema=second_authority.prelaunch_authority.output_schema,
        prompt=second_authority.prelaunch_authority.prompts[0],
        loopback_port=58761,
    )

    assert first.normalized_sha256 != second.normalized_sha256


@pytest.mark.parametrize(
    "mutation",
    (
        "argv-selector",
        "launcher-environment-extra",
        "shell-environment-extra",
        "codex-executable-cross-binding",
        "normalized-hash",
    ),
)
def test_client_launch_spec_direct_construction_cannot_bypass_builder(
    tmp_path: Path,
    mutation: str,
) -> None:
    module = _preflight()
    case_root, prompt, schema, launch_preflight = _launch_inputs(tmp_path)
    spec = module.build_client_launch_spec(
        mode="loopback_probe",
        preflight=launch_preflight,
        case_root=case_root,
        evaluation=_client_evaluation(mode="loopback_probe"),
        output_schema=schema,
        prompt=prompt,
        loopback_port=43123,
    )
    updates: dict[str, object] = {}
    if mutation == "argv-selector":
        argv = tuple(
            "--sandbox" if value == "--strict-config" else value
            for value in spec.argv
        )
        vector = _command_plan()._windows_native_vector(argv[0], argv[1:])
        updates = {
            "argv": argv,
            "native_vector_utf16_units": vector.utf16_units,
            "native_vector_utf16le_sha256": vector.utf16le_sha256,
        }
    elif mutation == "launcher-environment-extra":
        updates["launcher_environment"] = tuple(
            sorted((*spec.launcher_environment, ("HTTP_PROXY", "http://proxy")))
        )
    elif mutation == "shell-environment-extra":
        updates["shell_environment"] = tuple(
            sorted((*spec.shell_environment, ("PSModulePath", r"C:\Modules")))
        )
    elif mutation == "codex-executable-cross-binding":
        entries = list(spec.executable_identities)
        role, _path, digest = entries[0]
        entries[0] = (role, str(tmp_path / "alternate" / "codex.exe"), digest)
        updates["executable_identities"] = tuple(entries)
    elif mutation == "normalized-hash":
        updates["normalized_sha256"] = "0" * 64

    forged = _unchecked_replace(spec, **updates)
    object.__setattr__(
        forged,
        "_launch_construction_authority",
        getattr(spec, "_launch_construction_authority"),
    )
    with pytest.raises(RuntimeError, match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$"):
        forged.__post_init__()


@pytest.mark.parametrize("mutation", ("cwd", "final-message"))
def test_client_launch_spec_rejects_role_mismatched_legacy_paths(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    mutation: str,
) -> None:
    module = _preflight()
    case_root, prompt, schema, launch_preflight = _launch_inputs(tmp_path)
    authority = launch_preflight._validated_launch_authority
    spec = module.build_client_launch_spec(
        mode="loopback_probe",
        preflight=launch_preflight,
        case_root=case_root,
        evaluation=_client_evaluation(mode="loopback_probe", ordinal=3),
        output_schema=authority.prelaunch_authority.output_schema,
        prompt=authority.prelaunch_authority.prompts[1],
        loopback_port=43123,
    )
    argv = list(spec.argv)
    cwd = spec.cwd
    if mutation == "cwd":
        cwd = str(case_root / "workspace")
        argv[argv.index("--cd") + 1] = cwd
    else:
        argv[argv.index("--output-last-message") + 1] = str(
            case_root / "raw" / "final.md"
        )
    forged_argv = tuple(argv)
    vector = _command_plan()._windows_native_vector(
        forged_argv[0],
        forged_argv[1:],
    )
    construction_authority = getattr(
        spec,
        "_launch_construction_authority",
    )
    preflight_authority = construction_authority.preflight_authority
    normalized_sha256 = module._launch_normalized_sha256(
        case_root=str(case_root),
        loopback_port=43123,
        argv=forged_argv,
        config_overrides=spec.config_overrides,
        evaluation=spec.evaluation,
        prompt=spec.prompt,
        output_schema=spec.output_schema,
        launcher_environment=spec.launcher_environment,
        shell_environment=spec.shell_environment,
        credential_transport_version=spec.credential_transport_version,
        credential_environment_name=spec.credential_environment_name,
        executable_descriptors=preflight_authority.executable_descriptors,
        preflight_authority_sha256=module._launch_validated_authority_sha256(
            preflight_authority
        ),
    )
    forged_authority = _unchecked_replace(
        construction_authority,
        normalized_sha256=normalized_sha256,
    )
    forged = _unchecked_replace(
        spec,
        argv=forged_argv,
        native_vector_utf16_units=vector.utf16_units,
        native_vector_utf16le_sha256=vector.utf16le_sha256,
        cwd=cwd,
        normalized_sha256=normalized_sha256,
    )
    monkeypatch.setattr(
        module,
        "_launch_current_construction_authority",
        lambda: forged_authority,
    )

    def forbidden_mode_contract(*_args: object, **_kwargs: object) -> str:
        raise AssertionError("legacy topology reached launch-contract digest defense")

    monkeypatch.setattr(
        module,
        "_launch_mode_contract_sha256",
        forbidden_mode_contract,
    )

    with pytest.raises(RuntimeError, match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$"):
        forged.__post_init__()


