def test_launch_recapture_rebuilds_all_four_retained_launch_contracts(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    supplied, descriptors, root, layout, loopback_port = (
        _filesystem_launch_contract_fixture(tmp_path)
    )
    observed: list[tuple[str, str, str, str]] = []
    original_mode_contract_bytes = module._launch_mode_contract_bytes

    def record_mode_contract(**kwargs: object) -> bytes:
        observed.append(
            (
                kwargs["mode"],
                kwargs["cwd"],
                kwargs["final_message_path"],
                kwargs["output_schema_path"],
            )
        )
        return original_mode_contract_bytes(**kwargs)

    monkeypatch.setattr(
        module,
        "_launch_mode_contract_bytes",
        record_mode_contract,
    )

    assert module._launch_recapture_launch_contracts(
        supplied,
        root,
        descriptors,
    ) == loopback_port
    durable = supplied._launch_durable_authority.prelaunch
    expected_local = (
        (str(layout["workspace_root"]), durable.final_message_paths[0]),
        (str(layout["workspace_root"]), durable.final_message_paths[1]),
        (str(layout["file_change_audit_root"]), durable.final_message_paths[2]),
        (str(layout["file_change_audit_root"]), durable.final_message_paths[3]),
    )
    aggregate = json.loads(
        layout["loopback_launch_contract"].read_text(encoding="utf-8")
    )
    assert aggregate["version"] == (
        "complete-suite-loopback-launch-aggregate-v1"
    )
    assert [
        (
            member["probe_role"],
            member["probe_ordinal"],
            member["prompt_index"],
            member["cwd"],
            member["final_message_path"],
        )
        for member in aggregate["members"]
    ] == [
        (
            "shell_renderer",
            1,
            0,
            r"<case_root>\workspace",
            r"<case_root>\raw\final\shell-01.md",
        ),
        (
            "shell_renderer",
            2,
            0,
            r"<case_root>\workspace",
            r"<case_root>\raw\final\shell-02.md",
        ),
        (
            "file_add",
            3,
            1,
            r"<case_root>\file-change-audit",
            r"<case_root>\raw\final\file-add.md",
        ),
        (
            "file_update",
            4,
            2,
            r"<case_root>\file-change-audit",
            r"<case_root>\raw\final\file-update.md",
        ),
    ]
    assert len(
        {member["member_sha256"] for member in aggregate["members"]}
    ) == 4
    assert len(
        {member["mode_contract_sha256"] for member in aggregate["members"]}
    ) == 4
    for cwd, final_message_path in expected_local:
        assert observed.count(
            (
                "loopback",
                cwd,
                final_message_path,
                durable.output_schema.path,
            )
        ) == 2
    assert observed.count(
        (
            "real",
            str(layout["workspace_root"]),
            str(root / "raw" / "final.md"),
            durable.output_schema.path,
        )
    ) == 2
    assert len(observed) == 10


def test_loopback_aggregate_rejects_swapped_recomputed_role_mode_wrapper(
    tmp_path: Path,
) -> None:
    module = _preflight()
    supplied, descriptors, root, layout, loopback_port = (
        _filesystem_launch_contract_fixture(tmp_path)
    )
    expected_base = _expected_loopback_base_mode_contract_bytes(
        module,
        supplied,
        descriptors,
        root,
        layout,
        loopback_port,
    )
    aggregate = json.loads(
        layout["loopback_launch_contract"].read_text(encoding="utf-8")
    )
    first = aggregate["members"][0]
    third = aggregate["members"][2]
    first["mode_contract"], third["mode_contract"] = (
        third["mode_contract"],
        first["mode_contract"],
    )
    for member in (first, third):
        member["mode_contract_sha256"] = sha256(
            _canonical(member["mode_contract"])
        ).hexdigest()
        member_payload = dict(member)
        member_payload.pop("member_sha256")
        member["member_sha256"] = sha256(
            _canonical(member_payload)
        ).hexdigest()
    tampered = _canonical(aggregate)

    with pytest.raises(RuntimeError, match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$"):
        module._launch_loopback_aggregate_members(
            tampered,
            expected_base_mode_contract_bytes=expected_base,
        )


def _recompute_loopback_aggregate_member(member: dict[str, object]) -> None:
    member["mode_contract_sha256"] = sha256(
        _canonical(member["mode_contract"])
    ).hexdigest()
    member_payload = dict(member)
    member_payload.pop("member_sha256")
    member["member_sha256"] = sha256(
        _canonical(member_payload)
    ).hexdigest()


