def test_launch_spec_normalization_binds_prompt_identity_and_tool_versions(
    tmp_path: Path,
) -> None:
    module = _preflight()
    case_root, prompt, schema, launch_preflight = _launch_inputs(tmp_path)
    evaluation = _client_evaluation(mode="loopback_probe")

    def build(
        authority: object,
        *,
        selected_prompt: object | None = None,
        descriptor_updates: dict[str, dict[str, object]] | None = None,
    ) -> object:
        authority = _install_synthetic_validated_launch_authority(
            authority,
            descriptor_updates=descriptor_updates,
        )
        validated = authority._validated_launch_authority
        if selected_prompt is None:
            selected_prompt = validated.prelaunch_authority.prompts[0]
        return module.build_client_launch_spec(
            mode="loopback_probe",
            preflight=authority,
            case_root=case_root,
            evaluation=evaluation,
            output_schema=validated.prelaunch_authority.output_schema,
            prompt=selected_prompt,
            loopback_port=43123,
        )

    baseline = build(launch_preflight)
    with pytest.raises(RuntimeError, match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$"):
        build(
            launch_preflight,
            selected_prompt=_unchecked_replace(prompt, identity=_identity(902)),
        )
    codex_size = build(
        _unchecked_replace(
            launch_preflight,
            codex=_recanonical_codex(
                launch_preflight.codex,
                executable_size=launch_preflight.codex.executable_size + 1,
            ),
        )
    )
    shell_version = build(
        _unchecked_replace(
            launch_preflight,
            shell=replace(launch_preflight.shell, file_version="7.6.4.501"),
        )
    )
    guarded = _recanonical_guarded_runtime(
        launch_preflight.guarded_python,
        python_version="3.14.1",
    )
    python_version = build(
        _unchecked_replace(
            launch_preflight,
            guarded_python=guarded,
            python_version=guarded.python_version,
        )
    )
    hidden_size_variants = tuple(
        build(
            launch_preflight,
            descriptor_updates={role: {"size": size}},
        )
        for role, size in (
            ("pwsh", 1201),
            ("powershell_decoder", 1202),
            ("rg", 1203),
            ("comspec", 1204),
        )
    )

    assert len(
        {
            baseline.normalized_sha256,
            codex_size.normalized_sha256,
            shell_version.normalized_sha256,
            python_version.normalized_sha256,
            *(item.normalized_sha256 for item in hidden_size_variants),
        }
    ) == 8


def test_client_launch_spec_rejects_fully_recanonicalized_direct_forgery(
    tmp_path: Path,
) -> None:
    module = _preflight()
    case_root, prompt, schema, launch_preflight = _launch_inputs(tmp_path)
    spec = module.build_client_launch_spec(
        mode="loopback_probe",
        preflight=launch_preflight,
        case_root=case_root,
        evaluation=_client_evaluation(mode="loopback_probe"),
        output_schema=schema,
        prompt=prompt,
        loopback_port=43123,
    )
    alternate_codex = str(tmp_path / "alternate" / "codex.exe")
    executable_identities = (
        ("codex", alternate_codex, spec.executable_identities[0][2]),
        *spec.executable_identities[1:],
    )
    launcher_environment, shell_environment = module._launch_expected_environments(
        case_root=str(case_root),
        executable_identities=executable_identities,
    )
    argv = (alternate_codex, *spec.argv[1:])
    vector = _command_plan()._windows_native_vector(argv[0], argv[1:])
    construction_authority = getattr(
        spec,
        "_launch_construction_authority",
    )
    preflight_authority = construction_authority.preflight_authority
    executable_descriptors = (
        replace(
            preflight_authority.executable_descriptors[0],
            path=alternate_codex,
            hardlink_paths=(alternate_codex,),
        ),
        *preflight_authority.executable_descriptors[1:],
    )
    normalized_arguments: dict[str, object] = {
        "case_root": str(case_root),
        "loopback_port": 43123,
        "argv": argv,
        "config_overrides": spec.config_overrides,
        "evaluation": spec.evaluation,
        "prompt": spec.prompt,
        "output_schema": spec.output_schema,
        "launcher_environment": launcher_environment,
        "shell_environment": shell_environment,
        "credential_transport_version": spec.credential_transport_version,
        "credential_environment_name": spec.credential_environment_name,
        "executable_descriptors": executable_descriptors,
        "preflight_authority_sha256": (
            module._launch_validated_authority_sha256(preflight_authority)
        ),
    }
    forged = _unchecked_replace(
        spec,
        argv=argv,
        native_vector_utf16_units=vector.utf16_units,
        native_vector_utf16le_sha256=vector.utf16le_sha256,
        launcher_environment=launcher_environment,
        shell_environment=shell_environment,
        executable_identities=executable_identities,
        normalized_sha256=module._launch_normalized_sha256(
            **normalized_arguments
        ),
    )
    object.__setattr__(
        forged,
        "_launch_construction_authority",
        construction_authority,
    )

    with pytest.raises(RuntimeError, match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$"):
        forged.__post_init__()


def test_launch_spec_rejects_caller_minted_matching_preflight_authority(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    synthetic_launch_authority_adapter: object,
) -> None:
    module = _preflight()
    case_root, prompt, schema, launch_preflight = _launch_inputs(tmp_path)
    alternate_path = str(tmp_path / "attacker" / "codex.exe")
    alternate_sha256 = "1" * 64
    alternate_identity = _identity(9_999)
    alternate_codex = _recanonical_codex(
        launch_preflight.codex,
        executable_path=alternate_path,
        executable_size=launch_preflight.codex.executable_size + 1,
        executable_sha256=alternate_sha256,
        executable_identity=alternate_identity,
    )
    executable_identities = (
        ("codex", alternate_path, alternate_sha256),
        (
            "pwsh",
            launch_preflight.shell.path,
            launch_preflight.shell.sha256,
        ),
        (
            "powershell_decoder",
            launch_preflight.decoder_path,
            launch_preflight.decoder_sha256,
        ),
        (
            "python",
            launch_preflight.python_path,
            launch_preflight.python_sha256,
        ),
        ("rg", launch_preflight.rg_path, launch_preflight.rg_sha256),
        (
            "comspec",
            launch_preflight.comspec_path,
            launch_preflight.comspec_sha256,
        ),
    )
    launcher, shell = module._launch_expected_environments(
        case_root=str(case_root),
        executable_identities=executable_identities,
    )
    recanonicalized = _unchecked_replace(
        launch_preflight,
        codex=alternate_codex,
        launcher_environment=launcher,
        shell_environment=shell,
        environment_sha256=sha256(
            _canonical(
                {
                    "launcher_environment": [list(item) for item in launcher],
                    "shell_environment": [list(item) for item in shell],
                    "version": "complete-suite-client-environment-manifest-v1",
                }
            )
        ).hexdigest(),
    )
    caller_minted = _install_synthetic_validated_launch_authority(
        recanonicalized,
        descriptor_updates={
            "codex": {
                "path": alternate_path,
                "size": alternate_codex.executable_size,
                "sha256": alternate_sha256,
                "identity": alternate_identity,
            }
        },
    )
    monkeypatch.setattr(
        module,
        "_lookup_validated_launch_authority",
        synthetic_launch_authority_adapter,
    )

    with pytest.raises(RuntimeError, match=r"^COMMAND_LAUNCH_SPEC_MISMATCH$"):
        module.build_client_launch_spec(
            mode="loopback_probe",
            preflight=caller_minted,
            case_root=case_root,
            evaluation=_client_evaluation(mode="loopback_probe"),
            output_schema=schema,
            prompt=prompt,
            loopback_port=43123,
        )


def _loopback_server_module():
    return importlib.import_module("complete_suite_client_preflight_server")


def _loopback_prompt(scenario: str, case_root: Path) -> str:
    return f"{scenario}\ncase-root={case_root}"


def _loopback_first_request(
    module: object,
    scenario: str,
    case_root: Path,
) -> dict[str, object]:
    return {
        "input": [
            {
                "content": [
                    {
                        "text": _loopback_prompt(scenario, case_root),
                        "type": "input_text",
                    }
                ],
                "role": "user",
            }
        ],
        "model": "gpt-5.6-terra",
        "parallel_tool_calls": False,
        "store": False,
        "stream": True,
        "tool_choice": "auto",
        "tools": module.advertised_tools(),
    }


def _loopback_second_request(
    module: object,
    scenario: str,
    response_id: str,
    call_id: str,
) -> dict[str, object]:
    return {
        "input": [
            {
                "call_id": call_id,
                "output": module.scenario_contract(scenario).tool_output,
                "type": "function_call_output",
            }
        ],
        "model": "gpt-5.6-terra",
        "parallel_tool_calls": False,
        "previous_response_id": response_id,
        "store": False,
        "stream": True,
        "tool_choice": "auto",
        "tools": module.advertised_tools(),
    }


def _loopback_http_request(
    host: str,
    port: int,
    body: bytes,
    *,
    method: str = "POST",
    route: str = "/v1/responses",
    extra_headers: tuple[tuple[str, str], ...] = (),
    request_headers: tuple[tuple[str, str], ...] | None = None,
    declared_length: int | None = None,
) -> tuple[int, tuple[tuple[str, str], ...], bytes]:
    content_length = len(body) if declared_length is None else declared_length
    if request_headers is None:
        headers = (
            ("Host", f"127.0.0.1:{port}"),
            ("User-Agent", "kokoroarc-campaign6-client-preflight-v1"),
            ("Accept", "text/event-stream"),
            ("Content-Type", "application/json"),
            ("Content-Length", str(content_length)),
            ("Connection", "close"),
            *extra_headers,
        )
    else:
        assert not extra_headers
        headers = tuple(
            (
                name,
                value.replace("<port>", str(port)).replace(
                    "<content-length>", str(content_length)
                ),
            )
            for name, value in request_headers
        )
    head = (
        f"{method} {route} HTTP/1.1\r\n"
        + "".join(f"{name}: {value}\r\n" for name, value in headers)
        + "\r\n"
    ).encode("ascii")
    chunks: list[bytes] = []
    with socket.create_connection((host, port), timeout=5.0) as client:
        client.settimeout(5.0)
        client.sendall(head + body)
        client.shutdown(socket.SHUT_WR)
        while True:
            chunk = client.recv(65536)
            if not chunk:
                break
            chunks.append(chunk)
    raw = b"".join(chunks)
    head_bytes, separator, response_body = raw.partition(b"\r\n\r\n")
    assert separator == b"\r\n\r\n"
    head_lines = head_bytes.decode("ascii").split("\r\n")
    _http_version, status_text, _reason = head_lines[0].split(" ", 2)
    response_headers = tuple(
        tuple(line.split(": ", 1)) for line in head_lines[1:]
    )
    lengths = tuple(
        value for name, value in response_headers if name == "Content-Length"
    )
    assert lengths == (str(len(response_body)),)
    return int(status_text), response_headers, response_body


def _loopback_sse_events(body: bytes) -> tuple[tuple[str, object], ...]:
    events: list[tuple[str, object]] = []
    frames = body.split(b"\n\n")
    assert frames[-1] == b""
    for frame in frames[:-1]:
        lines = frame.split(b"\n")
        if len(lines) == 1:
            assert lines[0].startswith(b"data: ")
            payload = lines[0][len(b"data: ") :]
            decoded = json.loads(payload)
            assert isinstance(decoded, dict)
            event_name = decoded["type"]
            events.append((event_name, decoded))
            continue
        assert len(lines) == 2
        assert lines[0].startswith(b"event: ")
        assert lines[1].startswith(b"data: ")
        event_name = lines[0][len(b"event: ") :].decode("ascii")
        payload = lines[1][len(b"data: ") :]
        if payload == b"[DONE]":
            events.append((event_name, "[DONE]"))
        else:
            events.append((event_name, json.loads(payload)))
    return tuple(events)


def _loopback_exchange(
    server: object,
    scenario: str,
    case_root: Path,
    *,
    request_headers: tuple[tuple[str, str], ...] | None = None,
) -> tuple[tuple[tuple[str, object], ...], tuple[tuple[str, object], ...]]:
    module = _loopback_server_module()
    first_status, _first_headers, first_body = _loopback_http_request(
        server.host,
        server.port,
        _canonical(_loopback_first_request(module, scenario, case_root)),
        request_headers=request_headers,
    )
    assert first_status == 200
    first_events = _loopback_sse_events(first_body)
    completed_response = next(
        payload
        for name, payload in first_events
        if name == "response.completed"
    )
    completed_call = next(
        payload["item"]
        for name, payload in first_events
        if name == "response.output_item.done"
    )
    second_status, _second_headers, second_body = _loopback_http_request(
        server.host,
        server.port,
        _canonical(
            _loopback_second_request(
                module,
                scenario,
                completed_response["response"]["id"],
                completed_call["call_id"],
            )
        ),
        request_headers=request_headers,
    )
    assert second_status == 200
    return first_events, _loopback_sse_events(second_body)


def _offline_loopback_transcript_bytes(
    module: object,
    scenario: str,
    case_root: Path,
    *,
    port: int,
    seed: int,
    tool_item_id: str | None = None,
    extra_header: tuple[str, str] | None = None,
) -> bytes:
    contract = module.scenario_contract(scenario)
    response_ids = tuple(
        "resp_c6_" + f"{seed + ordinal:032x}" for ordinal in (1, 2)
    )
    call_id = "call_c6_" + f"{seed + 3:032x}"
    item_id = (
        "item_c6_" + f"{seed + 4:032x}"
        if tool_item_id is None
        else tool_item_id
    )
    exchanges = []
    for ordinal in (1, 2):
        body = _canonical(
            module._first_request_body(contract, str(case_root))
            if ordinal == 1
            else module._second_request_body(
                contract,
                response_id=response_ids[0],
                call_id=call_id,
            )
        )
        extra_header_text = (
            ""
            if extra_header is None
            else f"{extra_header[0]}: {extra_header[1]}\r\n"
        )
        head = (
            f"POST /v1/responses HTTP/1.1\r\n"
            f"Host: 127.0.0.1:{port}\r\n"
            "User-Agent: kokoroarc-campaign6-client-preflight-v1\r\n"
            "Accept: text/event-stream\r\n"
            "Content-Type: application/json\r\n"
            + extra_header_text
            + f"Content-Length: {len(body)}\r\n"
            "Connection: close\r\n"
            "\r\n"
        ).encode("ascii")
        response_head, response_body = module._build_loopback_response(
            contract,
            ordinal=ordinal,
            response_ids=response_ids,
            call_id=call_id,
            tool_item_id=item_id,
        )
        exchanges.append(
            module.LoopbackExchange(
                ordinal=ordinal,
                request_head=head,
                request_body=body,
                response_head=response_head,
                response_body=response_body,
                request_sha256=sha256(head + body).hexdigest(),
                response_sha256=sha256(
                    response_head + response_body
                ).hexdigest(),
            )
        )
    transcript = module.LoopbackTranscript(
        version="complete-suite-loopback-transcript-v1",
        host="127.0.0.1",
        port=port,
        scenario=scenario,
        case_root=str(case_root),
        request_count=2,
        response_ids=response_ids,
        call_id=call_id,
        tool_item_id=item_id,
        exchanges=tuple(exchanges),
    )
    return transcript.raw_bytes


def test_launch_loopback_contract_rejects_self_consistent_server_rebinding(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    server = _loopback_server_module()
    forged = {"forged": True}
    forged_bytes = _canonical(forged)
    monkeypatch.setattr(server, "loopback_contract_manifest", lambda: forged)
    monkeypatch.setattr(
        server,
        "LOOPBACK_CONTRACT_SHA256",
        sha256(forged_bytes).hexdigest(),
    )

    with pytest.raises(RuntimeError) as error:
        module._launch_loopback_contract_bytes()

    assert str(error.value) == module.LAUNCH_PREFLIGHT_BUNDLE_INVALID
    assert error.value.__cause__ is None


def test_launch_independent_loopback_contract_payload_has_no_server_builder_dependency(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    server = _loopback_server_module()
    for name in (
        "loopback_contract_manifest",
        "scenario_contract",
        "_first_request_body",
        "_second_request_body",
        "_tool_call_sse",
        "_final_text_sse",
        "_build_loopback_response",
    ):
        monkeypatch.setattr(
            server,
            name,
            lambda *args, _name=name, **kwargs: pytest.fail(
                f"independent contract called server builder {_name}"
            ),
        )

    payload = module._launch_independent_loopback_contract_payload()

    assert sha256(_canonical(payload)).hexdigest() == PINNED_LOOPBACK_CONTRACT_SHA256
    assert set(payload) == {
        "advertised_tools_sha256",
        "bind_host",
        "capabilities",
        "max_request_bytes",
        "method",
        "model",
        "native_tool_schema_provenance",
        "normalizable_fields",
        "port_assignment",
        "request_header_contract",
        "request_optional_fields",
        "request_ordinals",
        "route",
        "scenarios",
        "shell_repeat_additional_normalizable_fields",
        "tools",
        "version",
    }
    assert [scenario["name"] for scenario in payload["scenarios"]] == [
        "shell",
        "file_add",
        "file_update",
    ]
    assert payload["version"] == "complete-suite-loopback-contract-v1"


def test_launch_independent_response_sse_builders_are_branch_specific() -> None:
    module = _preflight()

    assert tuple(
        inspect.signature(module._launch_independent_tool_call_sse).parameters
    ) == ("arguments", "response_id", "call_id", "tool_item_id", "tool_name")
    assert tuple(
        inspect.signature(module._launch_independent_final_text_sse).parameters
    ) == ("response_id",)


def test_loopback_server_contract_freezes_tools_capabilities_and_payloads() -> None:
    module = _loopback_server_module()
    tools = module.advertised_tools()
    assert [tool["name"] for tool in tools] == ["shell", "apply_patch"]
    assert tools == [
        {
            "description": "Execute exactly one inert PowerShell payload.",
            "name": "shell",
            "parameters": {
                "additionalProperties": False,
                "properties": {"command": {"type": "string"}},
                "required": ["command"],
                "type": "object",
            },
            "strict": True,
            "type": "function",
        },
        {
            "description": "Apply exactly one campaign-owned file patch.",
            "name": "apply_patch",
            "parameters": {
                "additionalProperties": False,
                "properties": {"patch": {"type": "string"}},
                "required": ["patch"],
                "type": "object",
            },
            "strict": True,
            "type": "function",
        },
    ]
    tool_manifest = {
        "capabilities": {
            "parallel_tool_calls": False,
            "tool_choice": "auto",
        },
        "model": "gpt-5.6-terra",
        "tools": tools,
        "version": "complete-suite-advertised-tools-v1",
    }
    assert module.ADVERTISED_TOOLS_SHA256 == sha256(
        _canonical(tool_manifest)
    ).hexdigest()
    tools[0]["name"] = "mutated"
    assert module.advertised_tools()[0]["name"] == "shell"

    assert module.scenario_contract("shell").arguments == _canonical(
        {"command": r"Test-Path -LiteralPath '.\case.json'"}
    ).decode("utf-8")
    assert module.scenario_contract("file_add").arguments == _canonical(
        {
            "patch": (
                "*** Begin Patch\n"
                "*** Add File: preflight-file-change.txt\n"
                "+campaign6-add\n"
                "*** End Patch"
            )
        }
    ).decode("utf-8")
    assert module.scenario_contract("file_update").arguments == _canonical(
        {
            "patch": (
                "*** Begin Patch\n"
                "*** Update File: preflight-file-change.txt\n"
                "@@\n"
                "-campaign6-add\n"
                "+campaign6-update\n"
                "*** End Patch"
            )
        }
    ).decode("utf-8")
    assert module.FILE_ADD_BYTES == b"campaign6-add\n"
    assert module.FILE_UPDATE_BYTES == b"campaign6-update\n"
    manifest = module.loopback_contract_manifest()
    assert module.LOOPBACK_CONTRACT_SHA256 == sha256(
        _canonical(manifest)
    ).hexdigest()
    assert module.LOOPBACK_CONTRACT_SHA256 == PINNED_LOOPBACK_CONTRACT_SHA256
    assert manifest["request_header_contract"] == {
        "allow_duplicate_names": False,
        "comparison": "case-insensitive-name-unordered",
        "content_length": "canonical-decimal-body-bytes",
        "content_type": "application/json",
        "host": "127.0.0.1:<owned-ephemeral-port>",
        "optional_names": [
            "accept",
            "accept-encoding",
            "connection",
            "openai-beta",
            "traceparent",
            "tracestate",
            "x-client-request-id",
            "x-codex-installation-id",
            "x-codex-routing-hint",
            "x-codex-turn-metadata",
            "x-codex-turn-state",
            "x-oai-attestation",
            "x-openai-subagent",
            "x-responsesapi-include-timing-metrics",
        ],
        "required_names": [
            "content-length",
            "content-type",
            "host",
            "user-agent",
        ],
        "user_agent": "kokoroarc-campaign6-client-preflight-v1",
    }
    scenario_manifests = {
        value["name"]: value for value in manifest["scenarios"]
    }
    for scenario in ("shell", "file_add", "file_update"):
        contract = module.scenario_contract(scenario)
        assert {
            key: scenario_manifests[scenario][key]
            for key in (
                "first_request_sha256",
                "first_sse_sha256",
                "second_request_sha256",
                "second_sse_sha256",
            )
        } == PINNED_LOOPBACK_SCENARIO_DIGESTS[scenario]
        first_request = {
            "input": [
                {
                    "content": [
                        {
                            "text": f"{scenario}\ncase-root=<case-root>",
                            "type": "input_text",
                        }
                    ],
                    "role": "user",
                }
            ],
            "model": "gpt-5.6-terra",
            "parallel_tool_calls": False,
            "store": False,
            "stream": True,
            "tool_choice": "auto",
            "tools": module.advertised_tools(),
        }
        second_request = {
            "input": [
                {
                    "call_id": "<response-call-id>",
                    "output": contract.tool_output,
                    "type": "function_call_output",
                }
            ],
            "model": "gpt-5.6-terra",
            "parallel_tool_calls": False,
            "previous_response_id": "<response-id-1>",
            "store": False,
            "stream": True,
            "tool_choice": "auto",
            "tools": module.advertised_tools(),
        }
        assert scenario_manifests[scenario]["first_request_sha256"] == sha256(
            _canonical(first_request)
        ).hexdigest()
        assert scenario_manifests[scenario]["second_request_sha256"] == sha256(
            _canonical(second_request)
        ).hexdigest()
    assert module.server_module_sha256() == sha256(
        Path(module.__file__).read_bytes()
    ).hexdigest()


@pytest.mark.parametrize("scenario", ("shell", "file_add", "file_update"))
def test_loopback_server_serves_exact_two_response_sse_scenario(
    tmp_path: Path,
    scenario: str,
) -> None:
    module = _loopback_server_module()
    case_root = tmp_path / f"case-{scenario}"
    case_root.mkdir()
    with module.LoopbackPreflightServer(
        scenario=scenario,
        case_root=str(case_root),
    ) as server:
        assert server.host == "127.0.0.1"
        assert 0 < server.port <= 65535
        first_events, second_events = _loopback_exchange(
            server,
            scenario,
            case_root,
        )
        transcript = server.assert_complete()

    assert [name for name, _payload in first_events] == [
        "response.output_item.done",
        "response.completed",
    ]
    tool_item = first_events[0][1]["item"]
    contract = module.scenario_contract(scenario)
    assert tool_item["type"] == "function_call"
    assert tool_item["name"] == contract.tool_name
    assert tool_item["arguments"] == contract.arguments
    assert [name for name, _payload in second_events] == [
        "response.output_item.done",
        "response.completed",
    ]
    final_item = second_events[0][1]["item"]
    assert final_item["content"] == [
        {
            "annotations": [],
            "text": "campaign6-loopback-complete",
            "type": "output_text",
        }
    ]
    assert transcript.scenario == scenario
    assert transcript.request_count == 2
    assert len(transcript.exchanges) == 2
    assert transcript.raw_sha256 == sha256(transcript.raw_bytes).hexdigest()
    assert transcript.normalized_sha256 == sha256(
        transcript.normalized_bytes
    ).hexdigest()
    assert str(case_root).encode("utf-8") in transcript.raw_bytes
    assert str(case_root).encode("utf-8") not in transcript.normalized_bytes
    assert f"127.0.0.1:{transcript.port}".encode("ascii") in transcript.raw_bytes
    assert f"127.0.0.1:{transcript.port}".encode("ascii") not in (
        transcript.normalized_bytes
    )


