@pytest.mark.parametrize(
    "mutation",
    (
        "route",
        "method",
        "header",
        "duplicate-header",
        "credential-header",
        "transfer-encoding",
        "model",
        "tools",
        "prompt",
        "duplicate-key",
        "oversize",
    ),
)
def test_loopback_server_rejects_unexpected_request_contract(
    tmp_path: Path,
    mutation: str,
) -> None:
    module = _loopback_server_module()
    case_root = tmp_path / "case"
    case_root.mkdir()
    body_value = _loopback_first_request(module, "shell", case_root)
    method = "POST"
    route = "/v1/responses"
    extra_headers: tuple[tuple[str, str], ...] = ()
    declared_length: int | None = None
    if mutation == "route":
        route = "/v1/chat/completions"
    elif mutation == "method":
        method = "GET"
    elif mutation == "header":
        extra_headers = (("X-Unexpected", "1"),)
    elif mutation == "duplicate-header":
        extra_headers = (("host", "127.0.0.1:1"),)
    elif mutation == "credential-header":
        extra_headers = (("Authorization", "Bearer forbidden"),)
    elif mutation == "transfer-encoding":
        extra_headers = (("Transfer-Encoding", "chunked"),)
    elif mutation == "model":
        body_value["model"] = "gpt-5.6-sol"
    elif mutation == "tools":
        body_value["tools"] = list(reversed(body_value["tools"]))
    elif mutation == "prompt":
        body_value["input"][0]["content"][0]["text"] = "shell"
    body = _canonical(body_value)
    if mutation == "duplicate-key":
        body = body[:-1] + b',"model":"gpt-5.6-terra"}'
    elif mutation == "oversize":
        body = b""
        declared_length = module.MAX_REQUEST_BYTES + 1

    with module.LoopbackPreflightServer(
        scenario="shell",
        case_root=str(case_root),
    ) as server:
        status, _headers, response_body = _loopback_http_request(
            server.host,
            server.port,
            body,
            method=method,
            route=route,
            extra_headers=extra_headers,
            declared_length=declared_length,
        )
        with pytest.raises(
            RuntimeError,
            match=r"^LOOPBACK_SERVER_CONTRACT_MISMATCH$",
        ):
            server.assert_complete()

    assert status in {400, 405, 413}
    assert json.loads(response_body) == {
        "error": "LOOPBACK_SERVER_CONTRACT_MISMATCH"
    }


@pytest.mark.parametrize("mutation", ("retry", "wrong-output", "extra"))
def test_loopback_server_rejects_retry_missing_followup_or_extra_request(
    tmp_path: Path,
    mutation: str,
) -> None:
    module = _loopback_server_module()
    case_root = tmp_path / "case"
    case_root.mkdir()
    with module.LoopbackPreflightServer(
        scenario="shell",
        case_root=str(case_root),
    ) as server:
        first_request = _canonical(
            _loopback_first_request(module, "shell", case_root)
        )
        first_status, _headers, first_body = _loopback_http_request(
            server.host,
            server.port,
            first_request,
        )
        assert first_status == 200
        first_events = _loopback_sse_events(first_body)
        response_id = next(
            payload["response"]["id"]
            for name, payload in first_events
            if name == "response.completed"
        )
        call_id = next(
            payload["item"]["call_id"]
            for name, payload in first_events
            if name == "response.output_item.done"
        )

        if mutation == "retry":
            rejected = first_request
        else:
            second = _loopback_second_request(
                module,
                "shell",
                response_id,
                call_id,
            )
            if mutation == "wrong-output":
                second["input"][0]["output"] = "False\n"
            second_status, _headers, _body = _loopback_http_request(
                server.host,
                server.port,
                _canonical(second),
            )
            if mutation == "wrong-output":
                assert second_status == 400
                rejected = None
            else:
                assert second_status == 200
                rejected = _canonical(second)
        if rejected is not None:
            rejected_status, _headers, _body = _loopback_http_request(
                server.host,
                server.port,
                rejected,
            )
            assert rejected_status == 400
        with pytest.raises(
            RuntimeError,
            match=r"^LOOPBACK_SERVER_CONTRACT_MISMATCH$",
        ):
            server.assert_complete()


