def _broker_native_guarded_target_constructor_plan_namespace(
    module: object,
) -> dict[str, object]:
    draft_value_namespace = _load_broker_native_core_draft()
    namespace = _broker_native_guarded_target_precreation_test_namespace(module)
    fragment = (
        module._launch_broker_native_guarded_target_constructor_plan_source_fragment()
    )
    exec(
        compile(
            fragment.source_bytes,
            "<broker-native-guarded-target-constructor-plan-test>",
            "exec",
        ),
        namespace,
    )
    namespace["_constructor_plan_draft_value_namespace"] = draft_value_namespace
    return namespace


def _broker_native_guarded_target_constructor_plan_prerequisites(
    namespace: dict[str, object],
    *,
    id_offset: int = 0,
    handle_offset: int = 0,
) -> tuple[object, object, object, object, tuple[object, ...]]:
    draft_value_namespace = namespace["_constructor_plan_draft_value_namespace"]
    attempt, resources, _trace, _clock_calls = (
        _broker_native_guarded_target_precreation_attempt(
            namespace,
            id_offset=id_offset,
            handle_offset=handle_offset,
        )
    )
    precreation_authority = namespace[
        "_c6_broker_native_core_v1_begin_guarded_target_precreation"
    ](
        attempt,
        _broker_native_guarded_target_precreation_payload(),
        2_000,
    )
    manifest = namespace[
        "_c6_broker_native_core_v1_bind_guarded_target_precreation_facts"
    ](precreation_authority)
    draft_vector = draft_value_namespace[
        "_c6_broker_native_core_draft_native_vector"
    ](
        r"C:\Python\python.exe",
        ("pytest", "-q"),
    )
    native_vector = namespace["_C6BrokerNativeCoreDraftNativeVector"](
        *tuple(draft_vector)
    )
    draft_environment = draft_value_namespace[
        "_c6_broker_native_core_draft_environment_block"
    ](
        (
            ("KOKOROARC_ORDINAL_Z", "last"),
            ("KOKOROARC_PRIVATE_VALUE", "synthetic-private-value"),
            ("KOKOROARC_ORDINAL_A", "first"),
        )
    )
    environment_block = namespace["_C6BrokerNativeCoreDraftEnvironmentBlock"](
        *tuple(draft_environment)
    )
    return (
        precreation_authority,
        manifest,
        native_vector,
        environment_block,
        resources,
    )


def _broker_native_guarded_target_constructor_plan_authority(
    namespace: dict[str, object],
    *,
    id_offset: int = 0,
    handle_offset: int = 0,
) -> tuple[object, object, object, object, tuple[object, ...]]:
    (
        precreation_authority,
        manifest,
        native_vector,
        environment_block,
        resources,
    ) = _broker_native_guarded_target_constructor_plan_prerequisites(
        namespace,
        id_offset=id_offset,
        handle_offset=handle_offset,
    )
    authority = namespace[
        "_c6_broker_native_core_v1_bind_guarded_target_constructor_plan"
    ](
        precreation_authority,
        native_vector,
        environment_block,
    )
    return authority, manifest, native_vector, environment_block, resources


def _broker_native_guarded_target_constructor_plan_exact_resource_projection_sha256(
    manifest: object,
) -> str:
    payload = {
        "version": (
            "complete-suite-broker-native-guarded-target-precreation-"
            "exact-resource-projection-v1"
        ),
        "owned_job_resources": tuple(
            (
                resource.owned_job.logical_job_id,
                resource.owned_job.handle,
                resource.owned_job.completion_associated,
                resource.job_kind,
                resource.parent_logical_job_id,
                resource.owner,
            )
            for resource in manifest.explicit_job_list_resources
        ),
        "channel_addresses": tuple(
            (
                address.token,
                address.fixed_role,
                address.pipe_name,
                address.parent_action,
                address.server_open_mode,
                address.child_access,
            )
            for address in manifest.channel_addresses
        ),
    }
    canonical = json.dumps(
        payload,
        ensure_ascii=True,
        allow_nan=False,
        sort_keys=False,
        separators=(",", ":"),
    ).encode("ascii", errors="strict") + b"\n"
    return sha256(canonical).hexdigest()


