def test_broker_native_guarded_target_constructor_plan_rejects_policy_limit_topology_handle_order_or_native_vector_drift(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    monkeypatch.setattr(os, "urandom", lambda size: bytes(range(size)))
    namespace = _broker_native_guarded_target_constructor_plan_namespace(module)
    bind_constructor = namespace[
        "_c6_broker_native_core_v1_bind_guarded_target_constructor_plan"
    ]

    for ordinal, mutation in enumerate(
        ("policy", "limit", "topology", "handle-order", "native-vector")
    ):
        (
            precreation_authority,
            manifest,
            native_vector,
            environment_block,
            _resources,
        ) = _broker_native_guarded_target_constructor_plan_prerequisites(
            namespace,
            id_offset=(ordinal + 1) * 1_000,
        )
        if mutation == "policy":
            policy = manifest.constructor_policy_projection
            replacement = type(policy)(
                policy.implementation_id,
                policy.constructor_class,
                policy.subject_kind,
                ("HANDLE_LIST", "JOB_LIST"),
                policy.direct_child_authority,
            )
            precreation_authority._manifest = (
                _broker_native_guarded_target_precreation_manifest_copy(
                    namespace,
                    manifest,
                    constructor_policy_projection=replacement,
                )
            )
        elif mutation == "limit":
            selection = manifest.guarded_target_limit_selection
            replacement = type(selection)(
                selection.table_id,
                selection.field_names,
                (
                    selection.row[0],
                    selection.row[1] + 1,
                    *selection.row[2:],
                ),
                selection.table_sha256,
            )
            precreation_authority._manifest = (
                _broker_native_guarded_target_precreation_manifest_copy(
                    namespace,
                    manifest,
                    guarded_target_limit_selection=replacement,
                )
            )
        elif mutation == "topology":
            precreation_authority._manifest = (
                _broker_native_guarded_target_precreation_manifest_copy(
                    namespace,
                    manifest,
                    job_topology_sha256="0" * 64,
                )
            )
        elif mutation == "handle-order":
            precreation_authority._manifest = (
                _broker_native_guarded_target_precreation_manifest_copy(
                    namespace,
                    manifest,
                    channel_addresses=tuple(reversed(manifest.channel_addresses)),
                )
            )
        elif mutation == "native-vector":
            native_vector = type(native_vector)(
                native_vector.contract,
                native_vector.utf16_units,
                "0" * 64,
                native_vector.command_line,
            )
        else:
            raise AssertionError(mutation)

        with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
            bind_constructor(
                precreation_authority,
                native_vector,
                environment_block,
            )
    assert side_effect_calls == []


def test_broker_native_guarded_target_constructor_plan_canonical_descriptor_bytes_and_hash_are_exact(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    monkeypatch.setattr(os, "urandom", lambda size: bytes(range(size)))
    namespace = _broker_native_guarded_target_constructor_plan_namespace(module)
    authority, _manifest, _vector, _environment, _resources = (
        _broker_native_guarded_target_constructor_plan_authority(namespace)
    )
    descriptor = authority.plan.descriptor_bytes
    expected_key_order = (
        "version",
        "activation_state",
        "completeness_state",
        "constructor_runtime_prefix_source_version",
        "constructor_runtime_prefix_source_size",
        "constructor_runtime_prefix_source_sha256",
        "precreation_source_version",
        "precreation_source_size",
        "precreation_source_sha256",
        "precreation_binding_sha256",
        "request_payload_sha256",
        "constructor_implementation_id",
        "constructor_implementation_authority_state",
        "constructor_class",
        "draft_constructor_attribute_projection_sha256",
        "proc_thread_attribute_tokens",
        "topology_id",
        "draft_job_topology_projection_sha256",
        "explicit_job_list_ids",
        "explicit_job_list_sha256",
        "guarded_target_limit_table_id",
        "guarded_target_limit_role",
        "guarded_target_limit_row",
        "guarded_target_process_limit_table_sha256",
        "native_vector_contract",
        "native_vector_utf16_units",
        "native_vector_utf16le_sha256",
        "environment_pair_count",
        "environment_utf16_units",
        "environment_utf16le_byte_count",
        "environment_utf16le_sha256",
        "broker_owned_inherited_handle_roles",
        "precreation_exact_resource_projection_sha256",
    )

    def exact_pairs(pairs: list[tuple[str, object]]) -> dict[str, object]:
        keys = tuple(key for key, _value in pairs)
        assert len(keys) == len(set(keys))
        return dict(pairs)

    decoded = json.loads(
        descriptor.decode("ascii", errors="strict"),
        object_pairs_hook=exact_pairs,
        parse_constant=lambda value: pytest.fail(
            f"non-finite descriptor number: {value}"
        ),
    )
    assert tuple(decoded) == expected_key_order
    assert descriptor == json.dumps(
        decoded,
        ensure_ascii=True,
        allow_nan=False,
        sort_keys=False,
        separators=(",", ":"),
    ).encode("ascii", errors="strict") + b"\n"
    assert descriptor.endswith(b"\n")
    assert b"\r" not in descriptor
    assert b"synthetic-private-value" not in descriptor
    assert str(_resources[0].owned_job.handle).encode("ascii") not in descriptor
    assert _manifest.channel_token.encode("ascii") not in descriptor
    assert _manifest.channel_addresses[0].pipe_name.encode("ascii") not in descriptor
    assert authority.plan.descriptor_sha256 == sha256(descriptor).hexdigest()
    assert namespace[
        "_c6_broker_native_core_v1_render_guarded_target_descriptor"
    ](authority) == descriptor
    assert side_effect_calls == []


def test_broker_native_guarded_target_constructor_plan_is_single_use_dormant_and_process_free(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    monkeypatch.setattr(os, "urandom", lambda size: bytes(range(size)))
    namespace = _broker_native_guarded_target_constructor_plan_namespace(module)
    authority, _manifest, _vector, _environment, _resources = (
        _broker_native_guarded_target_constructor_plan_authority(namespace)
    )
    render = namespace[
        "_c6_broker_native_core_v1_render_guarded_target_descriptor"
    ]
    authenticate = namespace[
        "_c6_broker_native_core_v1_authenticate_guarded_target_descriptor_authority"
    ]

    assert tuple(inspect.signature(render).parameters) == ("authority",)
    assert tuple(inspect.signature(authenticate).parameters) == ("authority",)
    assert authority.phase == "descriptor-plan-bound"
    assert authenticate(authority) is authority
    descriptor = render(authority)
    assert type(descriptor) is bytes
    assert descriptor == authority.plan.descriptor_bytes
    assert authority.phase == "descriptor-rendered"
    assert authenticate(authority) is authority
    with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
        render(authority)
    with pytest.raises((AttributeError, TypeError)):
        authority.plan.activation_state = "active"
    assert "synthetic-private-value" not in repr(authority)
    assert "synthetic-private-value" not in repr(authority.plan)
    assert not any(
        token in authority.plan.descriptor_bytes
        for token in (
            b"CreateProcessW",
            b"ResumeThread",
            b"native_prepare",
            b"activation-enabled",
        )
    )
    assert side_effect_calls == []


def test_broker_native_guarded_target_constructor_plan_closure_dependencies_fail_closed_before_bind_authenticate_or_render(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    monkeypatch.setattr(os, "urandom", lambda size: bytes(range(size)))
    namespace = _broker_native_guarded_target_constructor_plan_namespace(module)
    (
        precreation_authority,
        _manifest,
        native_vector,
        environment_block,
        _resources,
    ) = _broker_native_guarded_target_constructor_plan_prerequisites(namespace)
    bind = namespace[
        "_c6_broker_native_core_v1_bind_guarded_target_constructor_plan"
    ]
    authority = bind(precreation_authority, native_vector, environment_block)
    authenticate = namespace[
        "_c6_broker_native_core_v1_authenticate_guarded_target_descriptor_authority"
    ]
    render = namespace[
        "_c6_broker_native_core_v1_render_guarded_target_descriptor"
    ]
    hostile_calls: list[str] = []

    class HostileDependency:
        def __getattribute__(self, name: str) -> object:
            if name == "record":
                return object.__getattribute__(self, name)
            object.__getattribute__(self, "record")(
                f"getattribute:{name}"
            )
            raise AssertionError("poisoned namespace dependency dispatched")

        def record(self, event: str) -> None:
            hostile_calls.append(event)

        def __call__(self, *_args: object, **_kwargs: object) -> object:
            self.record("call")
            raise AssertionError("poisoned namespace dependency dispatched")

        def __eq__(self, _other: object) -> bool:
            self.record("eq")
            raise AssertionError("poisoned namespace dependency dispatched")

        def __iter__(self) -> object:
            self.record("iter")
            raise AssertionError("poisoned namespace dependency dispatched")

        def __bool__(self) -> bool:
            self.record("bool")
            raise AssertionError("poisoned namespace dependency dispatched")

    missing = object()

    def exercise(operation: object) -> None:
        for dependency_name in (
            _BROKER_NATIVE_GUARDED_TARGET_CONSTRUCTOR_PLAN_NAMESPACE_DEPENDENCIES
        ):
            original = namespace.get(dependency_name, missing)
            namespace[dependency_name] = HostileDependency()
            try:
                with pytest.raises(
                    RuntimeError,
                    match=r"^GUARDED_BOOTSTRAP_INVALID$",
                ):
                    operation()
            finally:
                if original is missing:
                    namespace.pop(dependency_name)
                else:
                    namespace[dependency_name] = original

    exercise(lambda: bind(precreation_authority, native_vector, environment_block))
    exercise(lambda: authenticate(authority))
    exercise(lambda: render(authority))
    assert authority.phase == "descriptor-plan-bound"
    assert hostile_calls == []
    assert side_effect_calls == []


def test_broker_native_guarded_target_constructor_plan_resource_digest_covers_exact_handles_metadata_tokens_and_addresses(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    token_ordinal = 0

    def distinct_token(size: int) -> bytes:
        nonlocal token_ordinal
        result = bytes((token_ordinal + index) % 256 for index in range(size))
        token_ordinal += 1
        return result

    monkeypatch.setattr(os, "urandom", distinct_token)
    namespace = _broker_native_guarded_target_constructor_plan_namespace(module)
    authority_a, manifest_a, _vector_a, _environment_a, resources_a = (
        _broker_native_guarded_target_constructor_plan_authority(
            namespace,
            handle_offset=0,
        )
    )
    authority_b, manifest_b, _vector_b, _environment_b, resources_b = (
        _broker_native_guarded_target_constructor_plan_authority(
            namespace,
            handle_offset=500,
        )
    )
    plan_a = authority_a.plan
    plan_b = authority_b.plan

    assert plan_a.explicit_job_list_ids == plan_b.explicit_job_list_ids
    assert plan_a.broker_owned_inherited_handle_roles == (
        plan_b.broker_owned_inherited_handle_roles
    )
    assert tuple(resource.owned_job.handle for resource in resources_a) != tuple(
        resource.owned_job.handle for resource in resources_b
    )
    assert manifest_a.channel_token != manifest_b.channel_token
    assert plan_a.precreation_exact_resource_projection_sha256 == (
        _broker_native_guarded_target_constructor_plan_exact_resource_projection_sha256(
            manifest_a
        )
    )
    assert plan_b.precreation_exact_resource_projection_sha256 == (
        _broker_native_guarded_target_constructor_plan_exact_resource_projection_sha256(
            manifest_b
        )
    )
    assert (
        plan_a.precreation_exact_resource_projection_sha256
        != plan_b.precreation_exact_resource_projection_sha256
    )

    bind = namespace[
        "_c6_broker_native_core_v1_bind_guarded_target_constructor_plan"
    ]
    for ordinal, mutation in enumerate(("handle", "metadata", "token", "address")):
        (
            precreation_authority,
            manifest,
            native_vector,
            environment_block,
            _resources,
        ) = _broker_native_guarded_target_constructor_plan_prerequisites(
            namespace,
            id_offset=(ordinal + 1) * 1_000,
        )
        original_digest = (
            _broker_native_guarded_target_constructor_plan_exact_resource_projection_sha256(
                manifest
            )
        )
        replacements: dict[str, object] = {}
        if mutation in ("handle", "metadata"):
            original_resource = manifest.explicit_job_list_resources[0]
            original_job = original_resource.owned_job
            replacement_job = original_job
            replacement_kind = original_resource.job_kind
            if mutation == "handle":
                replacement_job = type(original_job)(
                    original_job.logical_job_id,
                    original_job.handle + 1,
                    original_job.completion_associated,
                )
            else:
                replacement_kind = "T"
            replacement_resource = type(original_resource)(
                replacement_job,
                replacement_kind,
                original_resource.parent_logical_job_id,
                original_resource.owner,
            )
            replacements["explicit_job_list_resources"] = (
                replacement_resource,
                *manifest.explicit_job_list_resources[1:],
            )
        elif mutation == "token":
            replacement_token = "f" * 32
            replacements["channel_token"] = replacement_token
            replacements["channel_addresses"] = tuple(
                type(address)(replacement_token, address.fixed_role)
                for address in manifest.channel_addresses
            )
        elif mutation == "address":
            original_address = manifest.channel_addresses[0]
            replacement_address = tuple.__new__(
                type(original_address),
                (
                    original_address.token,
                    original_address.fixed_role,
                    original_address.pipe_name + "-drift",
                    original_address.parent_action,
                    original_address.server_open_mode,
                    original_address.child_access,
                ),
            )
            replacements["channel_addresses"] = (
                replacement_address,
                *manifest.channel_addresses[1:],
            )
        else:
            raise AssertionError(mutation)
        mutated_manifest = _broker_native_guarded_target_precreation_manifest_copy(
            namespace,
            manifest,
            **replacements,
        )
        assert tuple(
            resource.owned_job.logical_job_id
            for resource in mutated_manifest.explicit_job_list_resources
        ) == tuple(
            resource.owned_job.logical_job_id
            for resource in manifest.explicit_job_list_resources
        )
        assert tuple(
            address.fixed_role for address in mutated_manifest.channel_addresses
        ) == tuple(address.fixed_role for address in manifest.channel_addresses)
        assert (
            _broker_native_guarded_target_constructor_plan_exact_resource_projection_sha256(
                mutated_manifest
            )
            != original_digest
        )
        precreation_authority._manifest = mutated_manifest
        with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
            bind(precreation_authority, native_vector, environment_block)
    assert side_effect_calls == []


def test_broker_native_guarded_target_constructor_plan_source_fragment_is_cross_bound_and_forbids_runtime_activation(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    draft = (
        module._launch_extract_broker_native_control_plane_candidate_from_bootstrap_source(
            BOOTSTRAP_PATH.read_bytes()
        )
    )
    prefix = module._launch_broker_native_constructor_runtime_prefix_source_fragment(
        draft_fragment=draft
    )
    precreation = (
        module._launch_broker_native_guarded_target_precreation_source_fragment()
    )
    fragment = (
        module._launch_broker_native_guarded_target_constructor_plan_source_fragment()
    )

    assert fragment.version == (
        "complete-suite-broker-native-guarded-target-constructor-plan-source-fragment-v1"
    )
    assert fragment.implementation_id == "broker-native-core-v1"
    assert fragment.activation_state == "dormant-source-only"
    assert fragment.completeness_state == (
        "descriptor-and-draft-projection-authority-only-global-constructor-set-"
        "unavailable-no-native-preparation-or-process-authority"
    )
    assert fragment.constructor_runtime_prefix_source_version == prefix.version
    assert fragment.constructor_runtime_prefix_source_size == len(
        prefix.source_bytes
    )
    assert fragment.constructor_runtime_prefix_source_sha256 == (
        prefix.source_sha256
    )
    assert fragment.precreation_source_version == precreation.version
    assert fragment.precreation_source_size == len(precreation.source_bytes)
    assert fragment.precreation_source_sha256 == precreation.source_sha256
    assert fragment.class_names == (
        "_C6BrokerNativeCoreV1GuardedTargetConstructorPlan",
        "_C6BrokerNativeCoreV1GuardedTargetDescriptorAuthority",
    )
    assert fragment.function_names == (
        "_c6_broker_native_core_v1_bind_guarded_target_constructor_plan",
        "_c6_broker_native_core_v1_render_guarded_target_descriptor",
        "_c6_broker_native_core_v1_authenticate_guarded_target_descriptor_authority",
    )
    assert type(fragment.source_bytes) is bytes
    assert fragment.source_bytes.endswith(b"\n")
    assert b"\r" not in fragment.source_bytes
    assert fragment.source_sha256 == sha256(fragment.source_bytes).hexdigest()
    assert len(fragment.source_bytes) == (
        module._BROKER_NATIVE_GUARDED_TARGET_CONSTRUCTOR_PLAN_SOURCE_SIZE
    )
    assert fragment.source_sha256 == (
        module._BROKER_NATIVE_GUARDED_TARGET_CONSTRUCTOR_PLAN_SOURCE_SHA256
    )
    assert (
        module._launch_broker_native_guarded_target_constructor_plan_composite_source_bytes(
            prefix_fragment=prefix,
            precreation_fragment=precreation,
        )
        == prefix.source_bytes + precreation.source_bytes + fragment.source_bytes
    )
    forbidden = (
        b"CreateProcessW",
        b"ResumeThread",
        b"subprocess",
        b"os.name",
        b"platform",
        b"codex",
        b"ACTIVATION-ENABLED",
    )
    assert not any(token in fragment.source_bytes for token in forbidden)
    assert b"_GUARDED_TARGET_IMPLEMENTATION_SET_BYTES" not in fragment.source_bytes
    assert b"constructor_implementation_set_sha256" not in fragment.source_bytes
    assert b"draft_constructor_attribute_projection_sha256" in fragment.source_bytes
    assert b"draft_job_topology_projection_sha256" in fragment.source_bytes
    assert b"precreation_exact_resource_projection_sha256" in fragment.source_bytes
    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_extract_broker_native_guarded_target_constructor_plan_source_fragment(
            fragment.source_bytes.replace(
                b'dormant-source-only',
                b'active-source-only',
                1,
            )
        )
    assert not hasattr(fragment, "__dict__")
    with pytest.raises((AttributeError, FrozenInstanceError)):
        fragment.activation_state = "active"
    assert side_effect_calls == []


def test_native_constructor_atomic_completeness_gate_remains_closed_with_descriptor_plan_only(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    native_calls: list[str] = []

    def forbidden_native(*_args: object, **_kwargs: object) -> object:
        native_calls.append("native-binding")
        pytest.fail("descriptor-only plan reached a native binding")

    monkeypatch.setattr(ctypes, "WinDLL", forbidden_native)
    monkeypatch.setattr(os, "urandom", lambda size: bytes(range(size)))
    namespace = _broker_native_guarded_target_constructor_plan_namespace(module)
    descriptor_authority, _manifest, _vector, _environment, _resources = (
        _broker_native_guarded_target_constructor_plan_authority(namespace)
    )
    gate = module._launch_build_native_constructor_atomic_completeness_gate(
        host_fragment=(
            module._launch_host_native_control_plane_candidate_source_fragment()
        ),
        broker_fragment=(
            module._launch_extract_broker_native_control_plane_candidate_from_bootstrap_source(
                BOOTSTRAP_PATH.read_bytes()
            )
        ),
    )

    assert descriptor_authority.plan.completeness_state.endswith(
        "no-native-preparation-or-process-authority"
    )
    assert gate.gate_state == "closed"
    assert gate.activation_permitted is False
    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_require_native_constructor_atomic_completeness(gate)
    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        module._launch_load_native_leaf_construction_authority()
    assert not BOOTSTRAP_PATH.with_name(
        "complete_suite_control_plane.ps1"
    ).exists()
    assert native_calls == []
    assert side_effect_calls == []


