@pytest.mark.parametrize("callable_mutation", ("code", "defaults", "worker-cell"))
def test_broker_native_guarded_target_constructor_plan_public_dispatch_authenticates_wrapper_and_worker_state_before_dispatch(
    operation_name: str,
    callable_mutation: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    monkeypatch.setattr(os, "urandom", lambda size: bytes(range(size)))
    namespace = _broker_native_guarded_target_constructor_plan_namespace(module)
