@pytest.mark.parametrize("rollback_shape", ("snapshot", "reconstructed"))
def test_broker_native_guarded_target_constructor_plan_coherent_lifecycle_projection_rollback_cannot_reopen_render(
    rollback_shape: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    monkeypatch.setattr(os, "urandom", lambda size: bytes(range(size)))
    namespace = _broker_native_guarded_target_constructor_plan_namespace(module)
    authority, _manifest, _vector, _environment, _resources = (
        _broker_native_guarded_target_constructor_plan_authority(namespace)
    )
    authenticate = namespace[
        "_c6_broker_native_core_v1_authenticate_guarded_target_descriptor_authority"
    ]
    render = namespace[
        "_c6_broker_native_core_v1_render_guarded_target_descriptor"
    ]
    public_cells = dict(
        zip(authenticate.__code__.co_freevars, authenticate.__closure__, strict=True)
    )
    worker = public_cells["authenticate_descriptor"].cell_contents
    worker_cells = dict(
        zip(worker.__code__.co_freevars, worker.__closure__, strict=True)
    )
    state_helper = worker_cells["state_is_current"].cell_contents
    state_cells = dict(
        zip(
            state_helper.__code__.co_freevars,
            state_helper.__closure__,
            strict=True,
        )
    )
    lifecycle_helper = state_cells["lifecycle_state_is_current"].cell_contents
    lifecycle_cells = dict(
        zip(
            lifecycle_helper.__code__.co_freevars,
            lifecycle_helper.__closure__,
            strict=True,
        )
    )
    record_name = next(
        name
        for name in ("authority_lifecycle_events", "authority_records")
        if name in lifecycle_cells
    )
    records_cell = lifecycle_cells[record_name]
    records_anchor_cell = lifecycle_cells.get(f"{record_name}_anchor")
    bound_records = records_cell.cell_contents
    render(authority)
    if rollback_shape == "snapshot":
        rollback_records = bound_records
    else:
        rollback_records = tuple(tuple(list(record)) for record in bound_records)
        assert rollback_records == bound_records
        assert rollback_records is not bound_records
        assert all(
            reconstructed is not original
            for reconstructed, original in zip(
                rollback_records,
                bound_records,
                strict=True,
            )
        )
    records_cell.cell_contents = rollback_records
    if records_anchor_cell is not None:
        records_anchor_cell.cell_contents = rollback_records
    object.__setattr__(authority, "_phase", "descriptor-plan-bound")
    with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
        authenticate(authority)
    with pytest.raises(RuntimeError, match=r"^GUARDED_BOOTSTRAP_INVALID$"):
        render(authority)
    assert side_effect_calls == []


