def test_broker_native_guarded_target_descriptor_projection_scanner_uses_bounded_local_ast_traversal_without_import_or_deque_resolution(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    scanner = (
        module._launch_scan_broker_native_guarded_target_descriptor_projection_source
    )
    source = (
        module._BROKER_NATIVE_GUARDED_TARGET_DESCRIPTOR_PROJECTION_SOURCE_BYTES
    )
    import_calls: list[tuple[str, tuple[str, ...]]] = []
    deque_calls: list[object] = []
    original_import = builtins.__import__
    collections_module = sys.modules["collections"]

    def tracked_import(
        name: str,
        globals_: object = None,
        locals_: object = None,
        fromlist: object = (),
        level: int = 0,
    ) -> object:
        frame = sys._getframe(1)
        stack_names: list[str] = []
        while frame is not None and len(stack_names) < 12:
            stack_names.append(frame.f_code.co_name)
            frame = frame.f_back
        import_calls.append((name, tuple(stack_names)))
        return original_import(name, globals_, locals_, fromlist, level)

    def hostile_deque(*args: object, **kwargs: object) -> object:
        deque_calls.append((args, kwargs))
        raise AssertionError("collections.deque resolved")

    with monkeypatch.context() as local_patch:
        local_patch.setattr(collections_module, "deque", hostile_deque)
        local_patch.setattr(builtins, "__import__", tracked_import)
        result = scanner(source)
    assert result == (
        module._BROKER_NATIVE_GUARDED_TARGET_DESCRIPTOR_PROJECTION_CLASS_NAMES,
        module._BROKER_NATIVE_GUARDED_TARGET_DESCRIPTOR_PROJECTION_FUNCTION_NAMES,
    )
    assert import_calls == []
    assert deque_calls == []


def test_broker_native_guarded_target_descriptor_projection_preserves_unexpected_baseexception_identity_and_predecessor_state(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    monkeypatch.setattr(os, "urandom", lambda size: bytes(range(size)))
    fragment = (
        module._launch_broker_native_guarded_target_descriptor_projection_source_fragment()
    )
    source = fragment.source_bytes.decode("ascii", errors="strict")
    tree = ast.parse(source)
    factory = next(
        node
        for node in tree.body
        if isinstance(node, ast.FunctionDef)
        and node.name
        == "_c6_broker_native_core_v1_project_guarded_target_descriptor_exports"
    )
    project_worker_node = next(
        node
        for node in factory.body
        if isinstance(node, ast.FunctionDef)
        and node.name
        == "project_worker"
    )
    target_line = next(
        node.lineno
        for node in ast.walk(project_worker_node)
        if isinstance(node, ast.Assign)
        and any(
            isinstance(target, ast.Name)
            and target.id == "precreation_snapshot"
            for target in node.targets
        )
    )
    namespace = _broker_native_guarded_target_descriptor_projection_namespace(
        module
    )
    precreation, manifest, _resources, attempt, original_clock = (
        _broker_native_guarded_target_descriptor_projection_prerequisites(
            namespace
        )
    )
    project = namespace[
        "_c6_broker_native_core_v1_project_guarded_target_descriptor"
    ]
    project_worker = dict(
        zip(project.__code__.co_freevars, project.__closure__, strict=True)
    )["project_worker"].cell_contents

    class BoundaryProbe(BaseException):
        pass

    failure = BoundaryProbe("projection-boundary")

    def boundary_trace(frame: object, event: str, _argument: object) -> object:
        if (
            event == "line"
            and frame.f_code is project_worker.__code__
            and frame.f_lineno == target_line
        ):
            raise failure
        return boundary_trace

    previous_trace = sys.gettrace()
    sys.settrace(boundary_trace)
    try:
        with pytest.raises(BoundaryProbe) as raised:
            project(precreation)
    finally:
        sys.settrace(previous_trace)
    assert raised.value is failure
    assert precreation.manifest is manifest
    assert precreation.phase == "precreation-frozen"
    assert object.__getattribute__(attempt, "_monotonic_ns") is precreation
    assert object.__getattribute__(attempt._state, "_monotonic_ns") is precreation
    assert object.__getattribute__(precreation, "_monotonic_ns_delegate") is (
        original_clock
    )
    assert side_effect_calls == []


