@pytest.mark.parametrize(
    "boundary",
    (
        "before-auth-wrapper-checker",
        "builder-wrapper-checker",
        "after-auth-wrapper-checker",
        "first-project-local-trust-barrier",
        "final-project-local-trust-barrier",
        "local-trust-callable-matches",
        "canonical-document",
        "canonical-encode-string",
        "canonical-encode-value",
        "encode-value-recursion",
    ),
)
def test_broker_native_guarded_target_descriptor_projection_internal_python_dispatch_boundaries_recheck_on_the_call_line(
    boundary: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    monkeypatch.setattr(os, "urandom", lambda size: bytes(range(size)))
    namespace = _broker_native_guarded_target_descriptor_projection_namespace(
        module
    )
    precreation, _manifest, _resources, attempt, _clock = (
        _broker_native_guarded_target_descriptor_projection_prerequisites(
            namespace
        )
    )
    project = namespace[
        "_c6_broker_native_core_v1_project_guarded_target_descriptor"
    ]

    def closure_values(callable_object: object) -> dict[str, object]:
        return {
            name: cell.cell_contents
            for name, cell in zip(
                callable_object.__code__.co_freevars,
                callable_object.__closure__ or (),
            )
        }

    project_cells = closure_values(project)
    before_auth = project_cells["authenticate_precreation_before_build"]
    build_boundary = project_cells["build_projection_at_boundary"]
    after_auth = project_cells["authenticate_precreation_after_build"]
    local_trust = project_cells["local_trust_matches"]
    build_projection = build_boundary.__defaults__[0][0]
    canonical_document = build_projection.__defaults__[0][0]
    canonical_cells = closure_values(canonical_document)
    eliminated_checker_boundaries = {
        "before-auth-wrapper-checker": before_auth,
        "builder-wrapper-checker": build_boundary,
        "after-auth-wrapper-checker": after_auth,
        "local-trust-callable-matches": local_trust,
    }
    eliminated_encoder_boundaries = {
        "canonical-encode-string": "encode_string",
        "canonical-encode-value": "encode_value",
        "encode-value-recursion": "encode_value",
    }
    hostile_calls: list[str] = []

    def hostile_dependency(*_args: object, **_kwargs: object) -> object:
        hostile_calls.append("dispatch")
        raise AssertionError(f"removed {boundary} dependency dispatched")

    if boundary in eliminated_checker_boundaries:
        assert "callable_matches" not in project_cells
        assert "callable_matches" not in closure_values(
            eliminated_checker_boundaries[boundary]
        )
        namespace["callable_matches"] = hostile_dependency
        result = project(precreation)
        assert result.activation_state == "dormant-source-only"
        assert hostile_calls == []
        assert object.__getattribute__(attempt, "_monotonic_ns") is precreation
        assert object.__getattribute__(attempt._state, "_monotonic_ns") is precreation
        assert side_effect_calls == []
        return
    if boundary in eliminated_encoder_boundaries:
        removed_name = eliminated_encoder_boundaries[boundary]
        assert removed_name not in canonical_cells
        assert removed_name not in canonical_document.__code__.co_names
        namespace[removed_name] = hostile_dependency
        result = project(precreation)
        assert result.activation_state == "dormant-source-only"
        assert hostile_calls == []
        assert object.__getattribute__(attempt, "_monotonic_ns") is precreation
        assert object.__getattribute__(attempt._state, "_monotonic_ns") is precreation
        assert side_effect_calls == []
        return
    occurrence = 0
    if boundary == "first-project-local-trust-barrier":
        caller_code = project_cells["project_worker"].__code__
        callee = local_trust
        dispatch_text = "local_trust_matches() if"
    elif boundary == "final-project-local-trust-barrier":
        caller_code = project_cells["project_worker"].__code__
        callee = local_trust
        dispatch_text = "local_trust_matches() if"
        occurrence = -1
    else:
        assert boundary == "canonical-document"
        caller_code = build_projection.__code__
        callee = canonical_document
        dispatch_text = "resource_bytes = canonical_document("
    source = module._launch_broker_native_guarded_target_descriptor_projection_source_fragment().source_bytes.decode(
        "ascii",
        errors="strict",
    )
    source_lines = source.splitlines()
    caller_lines = tuple(
        line_number
        for _start, _end, line_number in caller_code.co_lines()
        if line_number is not None
    )
    matching_lines = tuple(
        line_number
        for line_number in dict.fromkeys(caller_lines)
        if dispatch_text in source_lines[line_number - 1]
    )
    assert matching_lines
    target_line = matching_lines[occurrence]
    original_code = callee.__code__
    poisoned_code = original_code.replace(
        co_name=f"poisoned_projection_{boundary}_dispatch"
    )
    armed = True

    def boundary_trace(frame: object, event: str, _argument: object) -> object:
        nonlocal armed
        if (
            event == "call"
            and frame.f_code is poisoned_code
            and not hostile_calls
        ):
            hostile_calls.append("dispatch")
        if (
            armed
            and event == "line"
            and frame.f_code is caller_code
            and frame.f_lineno == target_line
        ):
            armed = False
            callee.__code__ = poisoned_code
        return boundary_trace

    caught: BaseException | None = None
    previous_trace = sys.gettrace()
    sys.settrace(boundary_trace)
    try:
        project(precreation)
    except BaseException as exc:
        caught = exc
    finally:
        sys.settrace(previous_trace)
        callee.__code__ = original_code
    assert hostile_calls == []
    assert type(caught) is RuntimeError
    assert caught.args == ("GUARDED_BOOTSTRAP_INVALID",)
    assert object.__getattribute__(attempt, "_monotonic_ns") is precreation
    assert object.__getattribute__(attempt._state, "_monotonic_ns") is precreation
    assert side_effect_calls == []


@pytest.mark.parametrize(
    "closure_name",
    (
        "trusted_memoryview",
        "trusted_compile",
        "trusted_list_pop",
        "trusted_ast_instance_dict_get",
    ),
)
def test_broker_native_guarded_target_descriptor_projection_scanner_closure_cell_rebind_on_later_use_line_rejects_before_dispatch(
    closure_name: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    scanner = (
        module._launch_scan_broker_native_guarded_target_descriptor_projection_source
    )
    scanner_cells = dict(
        zip(scanner.__code__.co_freevars, scanner.__closure__, strict=True)
    )
    assert closure_name not in scanner_cells
    scanner_worker = scanner_cells["scanner_worker"].cell_contents
    assert scanner_worker.__code__.co_freevars == ()
    original_defaults = scanner_worker.__defaults__
    assert original_defaults is not None
    fast_dependencies = original_defaults[0]
    original_dependency = {
        "trusted_memoryview": memoryview,
        "trusted_compile": compile,
        "trusted_list_pop": list.pop,
        "trusted_ast_instance_dict_get": type(
            ast.AST.__dict__["__dict__"]
        ).__get__,
    }[closure_name]
    dependency_indices = tuple(
        index
        for index, dependency in enumerate(fast_dependencies)
        if dependency is original_dependency
    )
    assert len(dependency_indices) == 1
    caller_lines = tuple(
        line_number
        for _start, _end, line_number in scanner_worker.__code__.co_lines()
        if line_number is not None
    )
    target_line = min(
        line_number
        for line_number in caller_lines
        if line_number > scanner_worker.__code__.co_firstlineno
    )
    hostile_calls: list[str] = []
    armed = True

    def hostile_callable(*_args: object, **_kwargs: object) -> object:
        hostile_calls.append("dispatch")
        raise AssertionError(f"hostile scanner closure dispatched: {closure_name}")

    def boundary_trace(frame: object, event: str, _argument: object) -> object:
        nonlocal armed
        if (
            armed
            and event == "line"
            and frame.f_code is scanner_worker.__code__
            and frame.f_lineno == target_line
        ):
            armed = False
            mutant_fast = list(fast_dependencies)
            mutant_fast[dependency_indices[0]] = hostile_callable
            scanner_worker.__defaults__ = (tuple(mutant_fast),)
        return boundary_trace

    caught: BaseException | None = None
    result: object = None
    monkeypatch.setattr(module, closure_name, hostile_callable, raising=False)
    previous_trace = sys.gettrace()
    sys.settrace(boundary_trace)
    try:
        result = scanner(
            module._BROKER_NATIVE_GUARDED_TARGET_DESCRIPTOR_PROJECTION_SOURCE_BYTES
        )
    except BaseException as exc:
        caught = exc
    finally:
        sys.settrace(previous_trace)
