@pytest.mark.parametrize(
    ("boundary", "closure_name"),
    (
        (
            "canonical-document-list-append",
            "trusted_list_append",
        ),
        (
            "local-trust-dict-get",
            "trusted_dict_get",
        ),
        (
            "before-auth-wrapper-object-getattribute",
            "trusted_object_getattribute",
        ),
        (
            "projector-type",
            "trusted_type",
        ),
        (
            "builder-canonical-guard-object-getattribute",
            "trusted_object_getattribute",
        ),
        (
            "builder-precreation-slot-get",
            "trusted_precreation_slot_get",
        ),
        (
            "projector-precreation-slot-get",
            "trusted_precreation_slot_get",
        ),
    ),
)
def test_broker_native_guarded_target_descriptor_projection_retained_callable_closure_cell_rebind_on_later_use_line_rejects_before_dispatch(
    boundary: str,
    closure_name: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    monkeypatch.setattr(os, "urandom", lambda size: bytes(range(size)))
    namespace = _broker_native_guarded_target_descriptor_projection_namespace(
        module
    )
    precreation, _manifest, _resources, attempt, _clock = (
        _broker_native_guarded_target_descriptor_projection_prerequisites(
            namespace
        )
    )
    project = namespace[
        "_c6_broker_native_core_v1_project_guarded_target_descriptor"
    ]

    def closure_values(callable_object: object) -> dict[str, object]:
        return {
            name: cell.cell_contents
            for name, cell in zip(
                callable_object.__code__.co_freevars,
                callable_object.__closure__,
                strict=True,
            )
        }

    project_cells = closure_values(project)
    before_auth = project_cells["authenticate_precreation_before_build"]
    build_boundary = project_cells["build_projection_at_boundary"]
    build_projection = build_boundary.__defaults__[0][0]
    canonical_document = build_projection.__defaults__[0][0]
    local_trust = project_cells["local_trust_matches"]
    project_worker = project_cells["project_worker"]
    if boundary == "canonical-document-list-append":
        retained_callable = canonical_document
        invocation_args = (("test",), (1,))
    elif boundary == "local-trust-dict-get":
        retained_callable = local_trust
        invocation_args = ()
    elif boundary == "before-auth-wrapper-object-getattribute":
        retained_callable = before_auth
        invocation_args = (precreation,)
    elif boundary == "projector-type":
        retained_callable = project_worker
        invocation_args = (precreation,)
    elif boundary == "builder-canonical-guard-object-getattribute":
        retained_callable = build_projection
        invocation_args = (precreation,)
    elif boundary == "builder-precreation-slot-get":
        retained_callable = build_projection
        invocation_args = (precreation,)
    else:
        assert boundary == "projector-precreation-slot-get"
        retained_callable = project_worker
        invocation_args = (precreation,)
    assert retained_callable.__code__.co_freevars == ()
    original_defaults = retained_callable.__defaults__
    assert original_defaults is not None
    fast_dependencies = original_defaults[0]
    original_dependency = {
        "trusted_list_append": list.append,
        "trusted_dict_get": dict.get,
        "trusted_object_getattribute": object.__getattribute__,
        "trusted_type": type,
        "trusted_precreation_slot_get": type(
            type(precreation).__dict__["_manifest"]
        ).__get__,
    }[closure_name]
    dependency_indices = tuple(
        index
        for index, dependency in enumerate(fast_dependencies)
        if dependency is original_dependency
    )
    assert len(dependency_indices) == 1
    caller = retained_callable
    caller_lines = tuple(
        line_number
        for _start, _end, line_number in caller.__code__.co_lines()
        if line_number is not None
    )
    target_line = min(
        line_number
        for line_number in caller_lines
        if line_number > caller.__code__.co_firstlineno
    )
    hostile_calls: list[str] = []
    armed = True

    def hostile_callable(*_args: object, **_kwargs: object) -> object:
        hostile_calls.append("dispatch")
        raise AssertionError(f"hostile retained closure dispatched: {boundary}")

    def boundary_trace(frame: object, event: str, _argument: object) -> object:
        nonlocal armed
        if (
            armed
            and event == "line"
            and frame.f_code is caller.__code__
            and frame.f_lineno == target_line
        ):
            armed = False
            mutant_fast = list(fast_dependencies)
            mutant_fast[dependency_indices[0]] = hostile_callable
            retained_callable.__defaults__ = (
                tuple(mutant_fast),
                *original_defaults[1:],
            )
        if event == "return" and frame.f_code is caller.__code__:
            retained_callable.__defaults__ = original_defaults
        return boundary_trace

    caught: BaseException | None = None
    result: object = None
    namespace[closure_name] = hostile_callable
    previous_trace = sys.gettrace()
    sys.settrace(boundary_trace)
    try:
        result = retained_callable(*invocation_args)
    except BaseException as exc:
        caught = exc
    finally:
        sys.settrace(previous_trace)
        retained_callable.__defaults__ = original_defaults
    assert hostile_calls == []
    assert caught is None
    if boundary in {
        "projector-type",
        "builder-canonical-guard-object-getattribute",
        "builder-precreation-slot-get",
        "projector-precreation-slot-get",
    }:
        assert result.activation_state == "dormant-source-only"
    elif boundary == "canonical-document-list-append":
        assert result == b'{"test":1}\n'
    elif boundary == "local-trust-dict-get":
        assert result is True
    else:
        assert boundary == "before-auth-wrapper-object-getattribute"
        assert result is precreation
    assert object.__getattribute__(attempt, "_monotonic_ns") is precreation
    assert object.__getattribute__(attempt._state, "_monotonic_ns") is precreation
    assert side_effect_calls == []


