def test_broker_native_guarded_target_descriptor_projection_public_wrapper_state_cell_rebind_rejects_before_subscription(
    surface: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    monkeypatch.setattr(os, "urandom", lambda size: bytes(range(size)))
    if surface == "raw-scanner-worker-state":
        callable_object = (
            module._launch_scan_broker_native_guarded_target_descriptor_projection_source
        )
        invocation_args = (
            module._BROKER_NATIVE_GUARDED_TARGET_DESCRIPTOR_PROJECTION_SOURCE_BYTES,
        )
        state_name = "scanner_worker_state"
        attempt = None
        precreation = None
    else:
        namespace = _broker_native_guarded_target_descriptor_projection_namespace(
            module
        )
        precreation, _manifest, _resources, attempt, _clock = (
            _broker_native_guarded_target_descriptor_projection_prerequisites(
                namespace
            )
        )
        callable_object = namespace[
            "_c6_broker_native_core_v1_project_guarded_target_descriptor"
        ]
        invocation_args = (precreation,)
        state_name = {
            "project-worker-state": "project_worker_state",
            "project-helper-states": "trusted_helper_states",
            "project-local-trust-state": "trusted_local_trust_state",
        }[surface]
    closure_cells = dict(
        zip(
            callable_object.__code__.co_freevars,
            callable_object.__closure__,
            strict=True,
        )
    )
    target_cell = closure_cells[state_name]
    original_state = target_cell.cell_contents
    hostile_calls: list[str] = []

    class HostileState:
        def __getitem__(self, _index: object) -> object:
            hostile_calls.append("dispatch")
            raise AssertionError(f"hostile state subscribed: {surface}")

    target_lines = tuple(
        line_number
        for _start, _end, line_number in callable_object.__code__.co_lines()
        if line_number is not None
        and line_number > callable_object.__code__.co_firstlineno
    )
    target_line = min(target_lines)
    armed = True

    def boundary_trace(frame: object, event: str, _argument: object) -> object:
        nonlocal armed
        if (
            armed
            and event == "line"
            and frame.f_code is callable_object.__code__
            and frame.f_lineno == target_line
        ):
            armed = False
            target_cell.cell_contents = HostileState()
        return boundary_trace

    caught: BaseException | None = None
    previous_trace = sys.gettrace()
    sys.settrace(boundary_trace)
    try:
        callable_object(*invocation_args)
    except BaseException as exc:
        caught = exc
    finally:
        sys.settrace(previous_trace)
        target_cell.cell_contents = original_state
    assert hostile_calls == []
    assert type(caught) is RuntimeError
    assert caught.args == (
        "LAUNCH_PREFLIGHT_BUNDLE_INVALID"
        if surface == "raw-scanner-worker-state"
        else "GUARDED_BOOTSTRAP_INVALID",
    )
    if attempt is not None:
        assert object.__getattribute__(attempt, "_monotonic_ns") is precreation
        assert object.__getattribute__(attempt._state, "_monotonic_ns") is precreation
    assert side_effect_calls == []


