@pytest.mark.parametrize(
    "class_mutation",
    (
        "generated-init-code",
        "generated-init-method",
        "post-init-code",
        "post-init-method",
        "property-code",
        "namespace",
        "global-bases-mro",
    ),
)
def test_broker_native_guarded_target_constructor_plan_final_review_repair_authenticates_fragment_class_before_construction_without_dispatch(
    class_mutation: str,
) -> None:
    module = _preflight()
    source = module._BROKER_NATIVE_GUARDED_TARGET_CONSTRUCTOR_PLAN_SOURCE_BYTES
    extractor = (
        module._launch_extract_broker_native_guarded_target_constructor_plan_source_fragment
    )
    fragment_type = module._BrokerNativeGuardedTargetConstructorPlanSourceFragment
    hostile_calls: list[str] = []

    def hostile_method(*_args: object, **_kwargs: object) -> None:
        hostile_calls.append("method")
        raise AssertionError("hostile fragment callable dispatched")

    if class_mutation == "generated-init-code":
        target = fragment_type.__dict__["__init__"]
        original = target.__code__
        target.__code__ = original.replace(co_name="poisoned_fragment_init")
        restore = lambda: setattr(target, "__code__", original)
    elif class_mutation == "generated-init-method":
        original = fragment_type.__dict__["__init__"]
        fragment_type.__init__ = hostile_method
        restore = lambda: setattr(fragment_type, "__init__", original)
    elif class_mutation == "post-init-code":
        target = fragment_type.__dict__["__post_init__"]
        original = target.__code__
        target.__code__ = original.replace(co_name="poisoned_fragment_post_init")
        restore = lambda: setattr(target, "__code__", original)
    elif class_mutation == "post-init-method":
        original = fragment_type.__dict__["__post_init__"]
        fragment_type.__post_init__ = hostile_method
        restore = lambda: setattr(fragment_type, "__post_init__", original)
    elif class_mutation == "property-code":
        getter = fragment_type.__dict__["source_sha256"].fget
        assert getter is not None
        original = getter.__code__
        getter.__code__ = original.replace(co_name="poisoned_fragment_property")
        restore = lambda: setattr(getter, "__code__", original)
    elif class_mutation == "namespace":
        fragment_type.attacker_marker = object()
        restore = lambda: delattr(fragment_type, "attacker_marker")
    else:
        original = module._BrokerNativeGuardedTargetConstructorPlanSourceFragment
        forged = type(
            f"Forged{original.__name__}",
            original.__bases__,
            {},
        )
        module._BrokerNativeGuardedTargetConstructorPlanSourceFragment = forged
        restore = lambda: setattr(
            module,
            "_BrokerNativeGuardedTargetConstructorPlanSourceFragment",
            original,
        )
        assert forged.__bases__ == original.__bases__
        assert forged.__mro__ != original.__mro__
    try:
        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ):
            extractor(source)
    finally:
        restore()
    assert hostile_calls == []


@pytest.mark.parametrize(
    "composite_mutation",
    (
        "code",
        "defaults",
        "kwdefaults",
        "globals",
        "builtins",
        "factory-global",
        "prefix-post-init",
        "precreation-post-init",
    ),
)
def test_broker_native_guarded_target_constructor_plan_final_review_repair_closes_composite_and_predecessor_dependencies_without_dispatch(
    composite_mutation: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    prefix, precreation = _constructor_plan_final_review_predecessor_fragments(module)
    composite = (
        module._launch_broker_native_guarded_target_constructor_plan_composite_source_bytes
    )
    target = composite
    hostile_calls: list[str] = []

    def hostile_dependency(*_args: object, **_kwargs: object) -> object:
        hostile_calls.append("dependency")
        raise AssertionError("hostile composite dependency dispatched")

    if composite_mutation == "code":
        original = composite.__code__
        composite.__code__ = original.replace(co_name="poisoned_constructor_composite")
        restore = lambda: setattr(composite, "__code__", original)
    elif composite_mutation == "defaults":
        original = composite.__defaults__
        composite.__defaults__ = (object(),)
        restore = lambda: setattr(composite, "__defaults__", original)
    elif composite_mutation == "kwdefaults":
        original = composite.__kwdefaults__
        composite.__kwdefaults__ = {"poison": object()}
        restore = lambda: setattr(composite, "__kwdefaults__", original)
    elif composite_mutation in {"globals", "builtins"}:
        replacement_globals = dict(composite.__globals__)
        if composite_mutation == "builtins":
            replacement_globals["__builtins__"] = dict(composite.__builtins__)
        target = types.FunctionType(
            composite.__code__,
            replacement_globals,
            composite.__name__,
            composite.__defaults__,
            composite.__closure__,
        )
        target.__kwdefaults__ = composite.__kwdefaults__
        restore = lambda: None
    elif composite_mutation == "factory-global":
        monkeypatch.setattr(
            module,
            "_launch_broker_native_guarded_target_constructor_plan_source_fragment",
            hostile_dependency,
        )
        restore = lambda: None
    else:
        predecessor_type = type(
            prefix if composite_mutation == "prefix-post-init" else precreation
        )
        original = predecessor_type.__dict__["__post_init__"]
        predecessor_type.__post_init__ = hostile_dependency
        restore = lambda: setattr(predecessor_type, "__post_init__", original)
    try:
        with pytest.raises(
            RuntimeError,
            match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
        ):
            target(prefix_fragment=prefix, precreation_fragment=precreation)
    finally:
        restore()
    assert hostile_calls == []


def test_broker_native_guarded_target_constructor_plan_final_review_repair_checks_lifecycle_operation_type_before_equality() -> None:
    module = _preflight()
    namespace = _broker_native_guarded_target_constructor_plan_namespace(module)
    authority, _manifest, _vector, _environment, _resources = (
        _broker_native_guarded_target_constructor_plan_authority(namespace)
    )
    authenticate = namespace[
        "_c6_broker_native_core_v1_authenticate_guarded_target_descriptor_authority"
    ]
    records_cell = _constructor_plan_final_review_lifecycle_records_cell(
        authenticate,
        "authenticate_descriptor",
    )
    original_records = records_cell.cell_contents
    hostile_calls: list[str] = []

    class HostileOperation:
        def __eq__(self, _other: object) -> bool:
            hostile_calls.append("eq")
            raise AssertionError("hostile lifecycle operation equality dispatched")

    hostile_event = list(original_records[0])
    assert len(hostile_event) == 17
    hostile_event[6] = HostileOperation()
    records_cell.cell_contents = (tuple(hostile_event), *original_records[1:])
    try:
        with pytest.raises(
            RuntimeError,
            match=r"^GUARDED_BOOTSTRAP_INVALID$",
        ):
            authenticate(authority)
    finally:
        records_cell.cell_contents = original_records
    assert hostile_calls == []


@pytest.mark.parametrize(
    "vector_case",
    ("empty", "embedded-nul", "30001-units"),
)
def test_broker_native_guarded_target_constructor_plan_final_review_repair_rejects_noncanonical_exact_native_vectors_before_lifecycle_mutation(
    vector_case: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    monkeypatch.setattr(os, "urandom", lambda size: bytes(range(size)))
    namespace = _broker_native_guarded_target_constructor_plan_namespace(module)
    precreation, _manifest, _vector, environment, _resources = (
        _broker_native_guarded_target_constructor_plan_prerequisites(namespace)
    )
    bind = namespace[
        "_c6_broker_native_core_v1_bind_guarded_target_constructor_plan"
    ]
    records_cell = _constructor_plan_final_review_lifecycle_records_cell(
        bind,
        "bind_constructor_plan",
    )
    original_records = records_cell.cell_contents
    if vector_case == "empty":
        command_line = ""
    elif vector_case == "embedded-nul":
        command_line = "pytest\x00-q"
    else:
        command_line = "x" * 30_000
    vector_bytes = (command_line + "\x00").encode(
        "utf-16-le",
        errors="strict",
    )
    vector_type = namespace["_C6BrokerNativeCoreDraftNativeVector"]
    forged_vector = tuple.__new__(
        vector_type,
        (
            "complete-suite-windows-native-vector-v1",
            len(vector_bytes) // 2,
            sha256(vector_bytes).hexdigest(),
            command_line,
        ),
    )
    assert type(forged_vector) is vector_type
    if vector_case == "30001-units":
        assert forged_vector.utf16_units == 30_001

    with pytest.raises(
        RuntimeError,
        match=r"^GUARDED_BOOTSTRAP_INVALID$",
    ):
        bind(precreation, forged_vector, environment)
    assert records_cell.cell_contents is original_records
    assert side_effect_calls == []


