def _constructor_plan_second_final_review_cells(
    function: object,
) -> dict[str, object]:
    return dict(
        zip(
            function.__code__.co_freevars,
            function.__closure__ or (),
            strict=True,
        )
    )


def _constructor_plan_second_final_review_context(
    module: object,
) -> dict[str, object]:
    source = module._BROKER_NATIVE_GUARDED_TARGET_CONSTRUCTOR_PLAN_SOURCE_BYTES
    scanner = module._launch_scan_broker_native_guarded_target_constructor_plan_source
    closed_scanner = (
        module._launch_closed_scan_broker_native_guarded_target_constructor_plan_source
    )
    extractor = (
        module._launch_extract_broker_native_guarded_target_constructor_plan_source_fragment
    )
    extractor_worker = _constructor_plan_second_final_review_cells(extractor)[
        "extractor_worker"
    ].cell_contents
    construct_fragment = _constructor_plan_second_final_review_cells(
        extractor_worker
    )["construct_fragment"].cell_contents
    validate_fragment = _constructor_plan_second_final_review_cells(
        construct_fragment
    )["validate_fragment"].cell_contents
    fragment_type = module._BrokerNativeGuardedTargetConstructorPlanSourceFragment
    fragment_post_init = type.__getattribute__(fragment_type, "__dict__")[
        "__post_init__"
    ]
    factory = (
        module._launch_broker_native_guarded_target_constructor_plan_source_fragment
    )
    composite = (
        module._launch_broker_native_guarded_target_constructor_plan_composite_source_bytes
    )
    return {
        "source": source,
        "scanner": scanner,
        "scanner_worker": _constructor_plan_second_final_review_cells(scanner)[
            "scanner_worker"
        ].cell_contents,
        "closed_scanner": closed_scanner,
        "extractor": extractor,
        "extractor_worker": extractor_worker,
        "construct_fragment": construct_fragment,
        "validate_fragment": validate_fragment,
        "fragment_type": fragment_type,
        "fragment_post_init": fragment_post_init,
        "factory": factory,
        "composite": composite,
    }


def _constructor_plan_second_final_review_capture(
    invocation: object,
) -> BaseException | None:
    try:
        invocation()
    except BaseException as exc:
        return exc
    return None


@pytest.mark.parametrize(
    "surface",
    (
        "scanner-callable-state-code",
        "scanner-tuple-getitem-cell",
        "scanner-reject-cell",
        "extractor-class-state-code",
        "extractor-class-state-cell",
        "extractor-validate-code",
        "extractor-construct-code",
        "extractor-construct-setattr-cell",
        "factory-dict-get-cell",
        "factory-reject-cell",
        "composite-dependency-state-code",
        "composite-dependency-state-cell",
        "composite-memoryview-tobytes-cell",
        "composite-reject-cell",
        "fragment-post-init-class-state-cell",
        "dataclass-generated-callable-closure-cell",
    ),
)
def test_broker_native_guarded_target_constructor_plan_second_final_review_repair_recursively_seals_helper_and_primitive_state_without_dispatch(
    surface: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    context = _constructor_plan_second_final_review_context(module)
    source = context["source"]
    prefix, precreation = _constructor_plan_final_review_predecessor_fragments(
        module
    )
    fragment = context["factory"]()
    hostile_calls: list[str] = []

    def hostile_callable(*_args: object, **_kwargs: object) -> object:
        hostile_calls.append("dispatch")
        raise AssertionError(f"hostile second-review dependency dispatched: {surface}")

    scanner_cells = _constructor_plan_second_final_review_cells(
        context["scanner"]
    )
    extractor_cells = _constructor_plan_second_final_review_cells(
        context["extractor"]
    )
    construct_cells = _constructor_plan_second_final_review_cells(
        context["construct_fragment"]
    )
    factory_cells = _constructor_plan_second_final_review_cells(
        context["factory"]
    )
    composite_cells = _constructor_plan_second_final_review_cells(
        context["composite"]
    )
    dependency_state = composite_cells["dependency_state_is_current"].cell_contents
    dependency_cells = _constructor_plan_second_final_review_cells(
        dependency_state
    )

    code_target: object | None = None
    cell_target: object | None = None
    replacement: object = hostile_callable
    if surface == "scanner-callable-state-code":
        code_target = scanner_cells["callable_state_is_current"].cell_contents
        invocation = lambda: context["scanner"](source)
    elif surface == "scanner-tuple-getitem-cell":
        if "trusted_tuple_getitem" not in scanner_cells:
            assert context["scanner"](source) == (
                module._BROKER_NATIVE_GUARDED_TARGET_CONSTRUCTOR_PLAN_CLASS_NAMES,
                module._BROKER_NATIVE_GUARDED_TARGET_CONSTRUCTOR_PLAN_FUNCTION_NAMES,
            )
            assert hostile_calls == []
            assert side_effect_calls == []
            return
        cell_target = scanner_cells["trusted_tuple_getitem"]
        invocation = lambda: context["scanner"](source)
    elif surface == "scanner-reject-cell":
        cell_target = scanner_cells["reject"]
        invocation = lambda: context["scanner"](source)
    elif surface == "extractor-class-state-code":
        code_target = extractor_cells["class_state_is_current"].cell_contents
        invocation = lambda: context["extractor"](source)
    elif surface == "extractor-class-state-cell":
        cell_target = extractor_cells["class_state_is_current"]
        invocation = lambda: context["extractor"](source)
    elif surface == "extractor-validate-code":
        code_target = context["validate_fragment"]
        invocation = lambda: context["extractor"](source)
    elif surface == "extractor-construct-code":
        code_target = context["construct_fragment"]
        invocation = lambda: context["extractor"](source)
    elif surface == "extractor-construct-setattr-cell":
        cell_target = construct_cells["trusted_object_setattr"]
        invocation = lambda: context["extractor"](source)
    elif surface == "factory-dict-get-cell":
        cell_target = factory_cells["trusted_dict_get"]
        invocation = context["factory"]
    elif surface == "factory-reject-cell":
        cell_target = factory_cells["reject"]
        invocation = context["factory"]
    elif surface == "composite-dependency-state-code":
        code_target = dependency_state
        invocation = lambda: context["composite"](
            prefix_fragment=prefix,
            precreation_fragment=precreation,
        )
    elif surface == "composite-dependency-state-cell":
        cell_target = composite_cells["dependency_state_is_current"]
        invocation = lambda: context["composite"](
            prefix_fragment=prefix,
            precreation_fragment=precreation,
        )
    elif surface == "composite-memoryview-tobytes-cell":
        cell_target = composite_cells["trusted_memoryview_tobytes"]
        invocation = lambda: context["composite"](
            prefix_fragment=prefix,
            precreation_fragment=precreation,
        )
    elif surface == "composite-reject-cell":
        cell_target = composite_cells["reject"]
        invocation = lambda: context["composite"](
            prefix_fragment=prefix,
            precreation_fragment=precreation,
        )
    elif surface == "fragment-post-init-class-state-cell":
        post_init_cells = _constructor_plan_second_final_review_cells(
            context["fragment_post_init"]
        )
        cell_target = post_init_cells["class_state_is_current"]
        invocation = lambda: context["fragment_post_init"](fragment)
    else:
        assert surface == "dataclass-generated-callable-closure-cell"
        generated = type.__getattribute__(
            context["fragment_type"],
            "__dict__",
        )["__setattr__"]
        assert generated.__closure__ is not None
        cell_target = generated.__closure__[0]
        replacement = object()
        invocation = lambda: context["extractor"](source)

    if code_target is not None:
        original_code = code_target.__code__
        poisoned_code = original_code.replace(
            co_name=f"poisoned_second_review_{surface.replace('-', '_')}"
        )

        def dispatch_trace(
            frame: object,
            event: str,
            _argument: object,
        ) -> object:
            if event == "call" and frame.f_code is poisoned_code:
                hostile_calls.append("dispatch")
            return dispatch_trace

        code_target.__code__ = poisoned_code
        previous_trace = sys.gettrace()
        sys.settrace(dispatch_trace)
        try:
            caught = _constructor_plan_second_final_review_capture(invocation)
        finally:
            sys.settrace(previous_trace)
            code_target.__code__ = original_code
    else:
        assert cell_target is not None
        original_value = cell_target.cell_contents
        cell_target.cell_contents = replacement
        try:
            caught = _constructor_plan_second_final_review_capture(invocation)
        finally:
            cell_target.cell_contents = original_value
    assert type(caught) is RuntimeError
    assert caught.args == ("LAUNCH_PREFLIGHT_BUNDLE_INVALID",)
    assert hostile_calls == []
    assert side_effect_calls == []


