@pytest.mark.parametrize(
    (
        "node_type_name",
        "field_name",
        "assignment_name",
        "selector_freevar",
    ),
    (
        ("Module", "body", "class_names", None),
        (
            "ClassDef",
            "name",
            "class_names",
            "trusted_class_def_type_fast",
        ),
        (
            "FunctionDef",
            "name",
            "all_function_names",
            "trusted_function_def_type_fast",
        ),
    ),
)
def test_broker_native_guarded_target_constructor_plan_residual_review_gap_scanner_ast_field_descriptor_changes_at_exact_use_boundaries(
    node_type_name: str,
    field_name: str,
    assignment_name: str,
    selector_freevar: str | None,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    context = _constructor_plan_second_final_review_context(module)
    scanner = context["scanner"]
    scanner_worker = context["scanner_worker"]
    expected = (
        module._BROKER_NATIVE_GUARDED_TARGET_CONSTRUCTOR_PLAN_CLASS_NAMES,
        module._BROKER_NATIVE_GUARDED_TARGET_CONSTRUCTOR_PLAN_FUNCTION_NAMES,
    )
    baseline = scanner(context["source"])
    assert baseline == expected
    assert side_effect_calls == []

    source_tree = ast.parse(Path(module.__file__).read_text(encoding="utf-8"))
    worker_nodes = tuple(
        node
        for node in ast.walk(source_tree)
        if isinstance(node, ast.FunctionDef)
        and node.name == scanner_worker.__name__
        and node.lineno == scanner_worker.__code__.co_firstlineno
    )
    assert len(worker_nodes) == 1
    worker_node = worker_nodes[0]
    effective_assignment_name = (
        "tree_body" if field_name == "body" else assignment_name
    )
    assignments = tuple(
        node
        for node in ast.walk(worker_node)
        if isinstance(node, ast.Assign)
        and len(node.targets) == 1
        and isinstance(node.targets[0], ast.Name)
        and node.targets[0].id == effective_assignment_name
    )
    assert len(assignments) == 1
    assignment = assignments[0]
    attributes = tuple(
        node
        for node in ast.walk(assignment.value)
        if isinstance(node, ast.Attribute)
        and node.attr == field_name
        and isinstance(node.value, ast.Name)
        and node.value.id == ("tree" if field_name == "body" else "node")
    )
    dictionary_calls = tuple(
        node
        for node in ast.walk(assignment.value)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == "trusted_dict_get_fast"
        and any(
            isinstance(argument, ast.Constant)
            and argument.value == field_name
            for argument in node.args
        )
    )
    assert len(attributes) + len(dictionary_calls) == 1
    target_line = (
        attributes[0].lineno
        if attributes
        else dictionary_calls[0].lineno
    )
    trace_code = scanner_worker.__code__
    if selector_freevar is not None:
        code_type = type(scanner_worker.__code__)
        pending = [scanner_worker.__code__]
        matches: list[object] = []
        while pending:
            current = pending.pop()
            pending.extend(
                value
                for value in current.co_consts
                if type(value) is code_type
            )
            current_lines = {
                line_number
                for _start, _end, line_number in current.co_lines()
                if line_number is not None
            }
            if (
                current is not scanner_worker.__code__
                and current.co_name == "<genexpr>"
                and selector_freevar in current.co_freevars
                and (
                    field_name in current.co_names
                    or field_name in current.co_consts
                )
                and target_line in current_lines
            ):
                matches.append(current)
        assert len(matches) == 1
        trace_code = matches[0]
    trace_lines = {
        line_number
        for _start, _end, line_number in trace_code.co_lines()
        if line_number is not None
    }
    assert target_line in trace_lines

    node_type = getattr(ast, node_type_name)
    node_namespace = type.__getattribute__(node_type, "__dict__")
    absent_member = object()
    original_member = node_namespace.get(field_name, absent_member)
    hostile_calls: list[str] = []
    armed = True
    mutation_fired = False

    def hostile_field(_instance: object) -> object:
        hostile_calls.append(f"{node_type_name}.{field_name}")
        raise AssertionError(
            f"hostile AST field descriptor dispatched: "
            f"{node_type_name}.{field_name}"
        )

    hostile_member = property(hostile_field)

    def boundary_trace(
        frame: object,
        event: str,
        _argument: object,
    ) -> object:
        nonlocal armed, mutation_fired
        if (
            armed
            and event == "line"
            and frame.f_code is trace_code
            and frame.f_lineno == target_line
        ):
            armed = False
            type.__setattr__(node_type, field_name, hostile_member)
            mutation_fired = True
        return boundary_trace

    result: object = None
    caught: BaseException | None = None
    previous_trace = sys.gettrace()
    sys.settrace(boundary_trace)
    try:
        result = scanner(context["source"])
    except BaseException as exc:
        caught = exc
    finally:
        sys.settrace(previous_trace)
        if original_member is absent_member:
            type.__delattr__(node_type, field_name)
        else:
            type.__setattr__(node_type, field_name, original_member)
    assert mutation_fired
    assert side_effect_calls == []
    assert hostile_calls == []
    assert caught is None
    assert result == expected


@pytest.mark.parametrize(
    ("boundary", "caller_name", "callee_name"),
    (
        ("scanner-worker", "scanner", "scanner_worker"),
        ("scanner-closed", "closed_scanner", "scanner_fast_public"),
        (
            "extractor-validator-scanner",
            "validate_fragment",
            "trusted_scanner",
        ),
        (
            "extractor-post-init-validator",
            "fragment_post_init",
            "validate_fragment",
        ),
        (
            "extractor-constructor-validator",
            "construct_fragment",
            "validate_fragment",
        ),
        ("extractor-scanner", "extractor_worker", "canonical_scanner"),
        (
            "extractor-constructor",
            "extractor_worker",
            "construct_fragment",
        ),
        ("extractor-worker", "extractor", "extractor_worker"),
        ("factory-extractor", "factory", "trusted_extractor"),
        ("composite-factory", "composite", "trusted_factory"),
    ),
)
def test_broker_native_guarded_target_constructor_plan_residual_review_gap_rejects_same_line_guard_state_replacement_without_protocol_dispatch(
    boundary: str,
    caller_name: str,
    callee_name: str,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    context = _constructor_plan_second_final_review_context(module)
    caller = context[caller_name]
    prefix: object = None
    precreation: object = None
    identity_fragment: object = None
    if boundary == "scanner-worker":
        invocation = lambda: context["scanner"](context["source"])
    elif boundary == "scanner-closed":
        invocation = lambda: context["closed_scanner"](context["source"])
    elif boundary in (
        "extractor-validator-scanner",
        "extractor-post-init-validator",
    ):
        identity_fragment = context["factory"]()
        invocation = (
            (lambda: context["validate_fragment"](identity_fragment))
            if boundary == "extractor-validator-scanner"
            else (lambda: context["fragment_post_init"](identity_fragment))
        )
    elif boundary in (
        "extractor-constructor-validator",
        "extractor-scanner",
        "extractor-constructor",
        "extractor-worker",
    ):
        invocation = lambda: context["extractor"](context["source"])
    elif boundary == "factory-extractor":
        invocation = context["factory"]
    else:
        assert boundary == "composite-factory"
        prefix, precreation = _constructor_plan_final_review_predecessor_fragments(
            module
        )
        invocation = lambda: context["composite"](
            prefix_fragment=prefix,
            precreation_fragment=precreation,
        )

    baseline = invocation()
    if identity_fragment is not None:
        assert baseline is identity_fragment
    _constructor_plan_residual_review_assert_normal_result(
        module,
        context,
        boundary,
        baseline,
        prefix,
        precreation,
    )
    assert side_effect_calls == []

    state_name = "callable_state_guard_state"
    cells = _constructor_plan_second_final_review_cells(caller)
    call_lines = _constructor_plan_residual_review_call_lines(
        module,
        caller,
        callee_name,
    )

    def is_guard_state_record(value: object) -> bool:
        return (
            type(value) is tuple
            and len(value) >= 7
            and type(value[0]) is types.FunctionType
            and value[0].__name__ == "callable_state_is_current"
            and value[0].__code__ is value[1]
            and value[0].__defaults__ is value[2]
            and value[0].__kwdefaults__ is value[3]
            and value[0].__globals__ is value[4]
            and value[0].__builtins__ is value[5]
            and value[0].__closure__ is value[6]
        )

    if state_name not in cells or not call_lines:
        assert state_name not in cells
        assert state_name not in caller.__code__.co_freevars
        assert state_name not in caller.__code__.co_cellvars
        assert state_name not in caller.__code__.co_names
        dependency_values = _constructor_plan_residual_review_dependency_values(
            caller
        )
        assert not any(
            is_guard_state_record(value) for value in dependency_values
        )
        normal_result = invocation()
        if identity_fragment is not None:
            assert normal_result is identity_fragment
        _constructor_plan_residual_review_assert_normal_result(
            module,
            context,
            boundary,
            normal_result,
            prefix,
            precreation,
        )
        assert side_effect_calls == []
        return

    assert len(call_lines) == 1
    target_line = call_lines[0]
    caller_lines = {
        line_number
        for _start, _end, line_number in caller.__code__.co_lines()
        if line_number is not None
    }
    assert target_line in caller_lines
    state_cell = cells[state_name]
    original_state = state_cell.cell_contents
    assert is_guard_state_record(original_state)
    hostile_calls: list[str] = []

    class HostileStateRecord:
        def fail(self, protocol: str) -> object:
            hostile_calls.append(protocol)
            raise AssertionError(
                f"hostile guard state protocol dispatched: {boundary}:{protocol}"
            )

        def __getitem__(self, _index: object) -> object:
            return self.fail("getitem")

        def __iter__(self) -> object:
            return self.fail("iter")

        def __len__(self) -> int:
            return self.fail("len")

        def __bool__(self) -> bool:
            return self.fail("bool")

        def __eq__(self, _other: object) -> bool:
            return self.fail("eq")

        def __ne__(self, _other: object) -> bool:
            return self.fail("ne")

    hostile_state = HostileStateRecord()
    armed = True
    mutation_fired = False

    def boundary_trace(
        frame: object,
        event: str,
        _argument: object,
    ) -> object:
        nonlocal armed, mutation_fired
        if (
            armed
            and event == "line"
            and frame.f_code is caller.__code__
            and frame.f_lineno == target_line
        ):
            armed = False
            state_cell.cell_contents = hostile_state
            mutation_fired = True
        return boundary_trace

    previous_trace = sys.gettrace()
    sys.settrace(boundary_trace)
    try:
        caught = _constructor_plan_second_final_review_capture(invocation)
    finally:
        sys.settrace(previous_trace)
        state_cell.cell_contents = original_state
    assert mutation_fired
    assert side_effect_calls == []
    assert hostile_calls == []
    assert type(caught) is RuntimeError
    assert caught.args == ("LAUNCH_PREFLIGHT_BUNDLE_INVALID",)



def test_broker_native_guarded_target_constructor_plan_review_repair_a_authenticates_executing_frame_builtins_when_clone_shares_trusted_globals(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    module = _preflight()
    side_effect_calls = _guard_native_leaf_side_effects(monkeypatch)
    prefix, precreation = _constructor_plan_final_review_predecessor_fragments(
        module
    )
    composite = (
        module._launch_broker_native_guarded_target_constructor_plan_composite_source_bytes
    )
    shared_globals = composite.__globals__
    original_builtins_entry = shared_globals["__builtins__"]
    alternate_builtins = dict(composite.__builtins__)
    hostile_calls: list[str] = []

    def hostile_probe(*_args: object, **_kwargs: object) -> object:
        hostile_calls.append("dispatch")
        raise AssertionError("synthetic alternate-builtins probe dispatched")

    alternate_builtins["__task9_review_repair_a_hostile_probe__"] = hostile_probe
    clone: object
    try:
        shared_globals["__builtins__"] = alternate_builtins
        clone = types.FunctionType(
            composite.__code__,
            shared_globals,
            composite.__name__,
            composite.__defaults__,
            composite.__closure__,
        )
    finally:
        shared_globals["__builtins__"] = original_builtins_entry
    clone.__kwdefaults__ = composite.__kwdefaults__
    assert clone.__globals__ is shared_globals
    assert clone.__globals__ is composite.__globals__
    assert clone.__builtins__ is alternate_builtins
    assert clone.__builtins__ is not composite.__builtins__
    assert shared_globals["__builtins__"] is original_builtins_entry

    with pytest.raises(
        RuntimeError,
        match=r"^LAUNCH_PREFLIGHT_BUNDLE_INVALID$",
    ):
        clone(
            prefix_fragment=prefix,
            precreation_fragment=precreation,
        )
    assert hostile_calls == []
    assert side_effect_calls == []
